# install_elliotos.sh — ElliotOS v17.0 — gerado $(date +%Y-%m-%d)
# ElliotOS v17.0 — instalador manual (Termux padrão + Linux explícito)
set -e

# ============================================================================
# _run_uninstall — definida no topo para estar disponível em qualquer caminho
# de execução, inclusive quando _SKIP_PREFLIGHT=1 (flags -u / -ua / --doctor)
# ============================================================================
_run_uninstall() {
    if [ -z "${HOME:-}" ] || [ ! -d "$HOME" ]; then
        printf "\033[1;31m[✗] Variável HOME não definida ou inválida — abortando desinstalação.\033[0m\n"
        exit 1
    fi
    _TPFX="${PREFIX:-/data/data/com.termux/files/usr}"
    if [ -z "${OS_TYPE:-}" ]; then
        if [ -d "/data/data/com.termux" ]; then OS_TYPE="termux"
        elif grep -qi "debian\|ubuntu" /etc/os-release 2>/dev/null; then OS_TYPE="debian"
        elif grep -qi "arch" /etc/os-release 2>/dev/null; then OS_TYPE="arch"
        elif grep -qi "fedora\|rhel\|centos" /etc/os-release 2>/dev/null; then OS_TYPE="fedora"
        else OS_TYPE="unknown"; fi
    fi
    printf "\n\033[1;33m╔══════════════════════════════════════════════════════════════╗\033[0m\n"
    if [ "${INSTALL_UNINSTALL_ALL:-0}" = "1" ]; then
        printf "\033[1;33m║          ElliotOS — Desinstalador COMPLETO                   ║\033[0m\n"
    else
        printf "\033[1;33m║          ElliotOS — Desinstalador                            ║\033[0m\n"
    fi
    printf "\033[1;33m╚══════════════════════════════════════════════════════════════╝\033[0m\n\n"

    printf "  \033[1;36m[*] Removendo binários...\033[0m\n"
    rm -f "$_TPFX/bin/lua-net" "$_TPFX/bin/lua" "$_TPFX/bin/lua5.4" \
          "$_TPFX/bin/ms" "$_TPFX/bin/luar" "$_TPFX/bin/lpm" "$_TPFX/bin/xpm" \
          "$_TPFX/bin/cxx" "$_TPFX/bin/ee" "$_TPFX/bin/xtun" \
          "$_TPFX/bin/elliot-gui" "$_TPFX/bin/rungui" \
          "$_TPFX/lib/liblua-net.so" "$_TPFX/lib/lua-net.so"
    printf "  \033[1;32m  ✓ Binários removidos\033[0m\n"

    printf "  \033[1;36m[*] Removendo diretório de build...\033[0m\n"
    rm -rf "$HOME/.lua-net-build"
    printf "  \033[1;32m  ✓ Build dir removido\033[0m\n"

    printf "  \033[1;36m[*] Removendo módulos e scripts...\033[0m\n"
    rm -rf "$_TPFX/share/lua-scripts" "$_TPFX/share/c-scripts" "$_TPFX/share/lua-modules" \
           "$_TPFX/share/lua/5.4/ell.lua"
    printf "  \033[1;32m  ✓ Módulos removidos\033[0m\n"

    printf "  \033[1;36m[*] Removendo cache e logs...\033[0m\n"
    rm -rf "$HOME/.lua-cache" "$HOME/.elliotai" "$HOME/.cache/elliot" \
           "$HOME/.elliot"
    rm -f "$HOME/.elliot_libnet.log" "$HOME/.elliot_make.log" "$HOME/.elliot_vanilla.log"
    printf "  \033[1;32m  ✓ Cache e logs removidos\033[0m\n"

    printf "  \033[1;36m[*] Removendo autenticação...\033[0m\n"
    rm -f "$HOME/.elliotos_auth"
    printf "  \033[1;32m  ✓ Senha removida\033[0m\n"

    printf "  \033[1;36m[*] Limpando .bashrc...\033[0m\n"
    sed -i '/# ── ElliotOS: verificação de senha/,/# ─\{10,\}/d' \
        "$HOME/.bashrc" 2>/dev/null || true
    sed -i '/# ── ElliotOS: prompt customizado/,/# ─\{10,\}/d' \
        "$HOME/.bashrc" 2>/dev/null || true
    sed -i '/lua-net\|lpm_lua_path\|LUA_PATH.*lua-modules\|LUA_PATH.*luarocks\|LUA_CPATH.*luarocks\|GEMINI_API_KEY\|AI_KEY\|NPM_BIN_PATH\|elliotos_auth_check\|_elliotos_auth_check/d' \
        "$HOME/.bashrc" 2>/dev/null || true
    printf "  \033[1;32m  ✓ .bashrc limpo\033[0m\n"

    printf "  \033[1;36m[*] Limpando .inputrc...\033[0m\n"
    sed -i '/# ── ElliotOS: readline/,/# ─\{10,\}/d' \
        "$HOME/.inputrc" 2>/dev/null || true
    printf "  \033[1;32m  ✓ .inputrc limpo\033[0m\n"

    if [ "${INSTALL_UNINSTALL_ALL:-0}" = "1" ]; then
        printf "  \033[1;36m[*] Removendo dados do usuário...\033[0m\n"
        rm -rf "$HOME/.lua-modules" "$HOME/.elliotai"
        printf "  \033[1;32m  ✓ Dados do usuário removidos\033[0m\n"

        printf "  \033[1;36m[*] Removendo dependências do sistema...\033[0m\n"
        case "$OS_TYPE" in
            termux)
                pkg remove -y clang binutils make cmake build-essential \
                    readline curl libcurl openssl openssl-tool autoconf \
                    wget git figlet tree libsqlite sqlite \
                    nodejs 2>/dev/null || true
                ;;
            debian)
                sudo apt-get remove -y --purge \
                    clang build-essential make cmake wget git figlet \
                    libreadline-dev libcurl4-openssl-dev libssl-dev \
                    libsqlite3-dev sqlite3 nodejs npm 2>/dev/null || true
                sudo apt-get autoremove -y 2>/dev/null || true
                ;;
            arch)
                sudo pacman -Rns --noconfirm \
                    clang base-devel cmake wget git figlet \
                    readline curl openssl sqlite nodejs npm 2>/dev/null || true
                ;;
            fedora)
                sudo dnf remove -y \
                    clang gcc make cmake wget git figlet \
                    readline-devel libcurl-devel openssl-devel \
                    sqlite-devel sqlite nodejs npm 2>/dev/null || true
                ;;
        esac
        printf "  \033[1;32m  ✓ Dependências removidas\033[0m\n"
    fi

    printf "\n  \033[1;32m[✔] ElliotOS desinstalado com sucesso!\033[0m\n"
    if [ "${INSTALL_UNINSTALL_ALL:-0}" = "1" ]; then
        printf "  \033[0;90m  Dependências do sistema e dados do usuário também removidos.\033[0m\n\n"
    else
        printf "  \033[0;90m  Dependências do sistema mantidas (clang, curl, etc.)\033[0m\n\n"
    fi
}

# ============================================================================
# PRÉ-PARSE RÁPIDO — identifica comandos que não precisam do preflight
# --help / -h         → exibe ajuda e sai (sem compilação, sem rede)
# --doctor            → diagnóstico pós-instalação (binários já existem)
# -u / --uninstall    → apenas remove arquivos (sem compilação, sem rede)
# -ua / --uninstall-all → idem
# ============================================================================
_SKIP_PREFLIGHT=0
for _early_arg in "$@"; do
    case "$_early_arg" in
        -h|--help|-u|--uninstall|-ua|--uninstall-all|--doctor|--gui)
            _SKIP_PREFLIGHT=1
            break
            ;;
    esac
done

if [ "$_SKIP_PREFLIGHT" = "1" ]; then
    # Define funções auxiliares de output que o restante do script espera
    _pf_ok()   { :; }
    _pf_warn() { :; }
    _pf_err()  { :; }
    _pf_info() { :; }
    # Exporta valores padrão que install_elliotos() e _run_uninstall() consultam
    _PF_ARCH_FLAGS="-O2"
    _PF_CC="${CC:-clang}"
    if [ -d "/data/data/com.termux" ]; then
        _ENV_TERMUX=1
    else
        _ENV_TERMUX=0
    fi
    export _PF_ARCH_FLAGS _PF_CC _ENV_TERMUX
else

# ============================================================================
# PREFLIGHT — verifica compatibilidade antes de instalar qualquer coisa
# Roda apenas para instalação/atualização real (não para --help, --doctor, -u)
# ============================================================================
_pf_ok()   { printf "  \033[1;32m✓\033[0m %s\n" "$1"; }
_pf_warn() { printf "  \033[1;33m⚠\033[0m %s\n" "$1"; }
_pf_err()  { printf "  \033[1;31m✗\033[0m %s\n" "$1"; }
_pf_info() { printf "  \033[0;90m→\033[0m %s\n" "$1"; }

printf "\n\033[1;35m── ElliotOS v17.0 — Verificação de compatibilidade ─────────────\033[0m\n\n"

_PREFLIGHT_FAIL=0

# ── 1. Shell: precisa de bash >= 4 ──────────────────────────────────────
_BASH_VER="${BASH_VERSINFO[0]:-0}"
if [ "$_BASH_VER" -ge 4 ]; then
    _pf_ok "Bash $_BASH_VER (>= 4 requerido)"
else
    _pf_err "Bash $_BASH_VER encontrado — precisa de bash >= 4"
    _pf_info "Instale: pkg install bash"
    _PREFLIGHT_FAIL=1
fi

# ── 2. Ambiente: Termux ou Linux ────────────────────────────────────────
if [ -d "/data/data/com.termux" ]; then
    _pf_ok "Termux detectado"
    _ENV_TERMUX=1
    _PF_PREFIX="${PREFIX:-/data/data/com.termux/files/usr}"
else
    _pf_ok "Linux detectado (não-Termux)"
    _ENV_TERMUX=0
    _PF_PREFIX="${PREFIX:-/usr/local}"
fi

# ── 3. Arquitetura ──────────────────────────────────────────────────────
_ARCH=$(uname -m 2>/dev/null || echo "unknown")
case "$_ARCH" in
    aarch64|arm64)
        _pf_ok "Arquitetura: $_ARCH (ARM64 — suporte total)"
        _PF_ARCH_FLAGS="-O2 -march=armv8-a"
        ;;
    armv8*|armv7*)
        _pf_ok "Arquitetura: $_ARCH (ARM32 — suporte total)"
        _PF_ARCH_FLAGS="-O2 -march=armv7-a -mfpu=neon"
        ;;
    armv6*)
        _pf_ok "Arquitetura: $_ARCH (ARMv6 — suporte total)"
        _PF_ARCH_FLAGS="-O2 -march=armv6 -mfpu=vfp"
        ;;
    x86_64|amd64)
        _pf_ok "Arquitetura: $_ARCH (x86_64 — suporte total)"
        _PF_ARCH_FLAGS="-O2"
        ;;
    i686|i386)
        _pf_ok "Arquitetura: $_ARCH (x86 32-bit — suporte total)"
        _PF_ARCH_FLAGS="-O2 -m32"
        ;;
    riscv64)
        _pf_ok "Arquitetura: $_ARCH (RISC-V 64 — suporte total)"
        _PF_ARCH_FLAGS="-O2"
        ;;
    *)
        _pf_warn "Arquitetura: $_ARCH (não reconhecida — usando flags genéricos)"
        _PF_ARCH_FLAGS="-O2"
        ;;
esac

# ── 4. Android version (só Termux) ──────────────────────────────────────
if [ "$_ENV_TERMUX" = "1" ]; then
    _ANDROID_VER=$(getprop ro.build.version.release 2>/dev/null || echo "")
    _ANDROID_SDK=$(getprop ro.build.version.sdk 2>/dev/null || echo "0")
    if [ -n "$_ANDROID_VER" ]; then
        if [ "$_ANDROID_SDK" -ge 28 ]; then
            _pf_ok "Android $_ANDROID_VER (SDK $_ANDROID_SDK >= 28)"
        elif [ "$_ANDROID_SDK" -ge 21 ]; then
            _pf_warn "Android $_ANDROID_VER (SDK $_ANDROID_SDK) — suportado mas recomenda >= 9"
        else
            _pf_err "Android $_ANDROID_VER (SDK $_ANDROID_SDK < 21) — não suportado"
            _PREFLIGHT_FAIL=1
        fi
    fi

    # Termux versão mínima
    _TV=$(termux-info 2>/dev/null | grep -i "termux version" | grep -oE '[0-9]+\.[0-9]+' | head -1 || echo "")
    if [ -n "$_TV" ]; then
        _TV_MAJOR=$(echo "$_TV" | cut -d. -f1)
        if [ "$_TV_MAJOR" -ge 118 ]; then
            _pf_ok "Termux v$_TV (>= 0.118)"
        else
            _pf_warn "Termux v$_TV antigo — recomenda F-Droid >= 0.118"
            _pf_info "Baixe em: https://f-droid.org/packages/com.termux"
        fi
    fi
fi

# ── 5. Espaço em disco ──────────────────────────────────────────────────
_FREE_KB=$(df "$HOME" 2>/dev/null | awk 'NR==2{print $4}' || echo "0")
_FREE_MB=$(( _FREE_KB / 1024 ))
if [ "$_FREE_MB" -ge 200 ]; then
    _pf_ok "Espaço livre: ${_FREE_MB}MB (>= 200MB requerido)"
elif [ "$_FREE_MB" -ge 100 ]; then
    _pf_warn "Espaço livre: ${_FREE_MB}MB — pouco, pode falhar durante compilação"
else
    _pf_err "Espaço livre: ${_FREE_MB}MB — insuficiente (mínimo 100MB)"
    _PREFLIGHT_FAIL=1
fi

# ── 6. Compilador ───────────────────────────────────────────────────────
if command -v clang >/dev/null 2>&1; then
    _CLANG_VER=$(clang --version 2>/dev/null | head -1 | grep -oE '[0-9]+\.[0-9]+' | head -1)
    _pf_ok "clang $_CLANG_VER encontrado"
    _PF_CC="clang"
elif command -v gcc >/dev/null 2>&1; then
    _GCC_VER=$(gcc --version 2>/dev/null | head -1 | grep -oE '[0-9]+\.[0-9]+' | head -1)
    _pf_warn "clang ausente — usando gcc $_GCC_VER (fallback)"
    _PF_CC="gcc"
else
    _pf_err "Nenhum compilador encontrado (clang ou gcc)"
    _pf_info "Instale: pkg install clang"
    _PREFLIGHT_FAIL=1
fi

# ── 7. Dependências críticas ────────────────────────────────────────────
# libcurl e libssl via header
if [ ! -f "${_PF_PREFIX}/include/curl/curl.h" ] && \
   ! pkg list-installed 2>/dev/null | grep -q "libcurl"; then
    _pf_warn "libcurl-dev pode estar ausente — será instalado automaticamente"
else
    _pf_ok "libcurl disponível"
fi

if [ ! -f "${_PF_PREFIX}/include/openssl/ssl.h" ] && \
   ! pkg list-installed 2>/dev/null | grep -q "openssl"; then
    _pf_warn "openssl-dev pode estar ausente — será instalado automaticamente"
else
    _pf_ok "openssl disponível"
fi

# ── 8. pthread ──────────────────────────────────────────────────────────
if [ -f "${_PF_PREFIX}/include/pthread.h" ] || \
   [ -f "/usr/include/pthread.h" ] || \
   [ -f "/usr/include/aarch64-linux-gnu/pthread.h" ]; then
    _pf_ok "pthread.h encontrado"
else
    # no Termux está em bionic, testa com clang
    if echo '#include <pthread.h>' | ${_PF_CC:-clang} -x c - -c -o /dev/null 2>/dev/null; then
        _pf_ok "pthread disponível (bionic)"
    else
        _pf_warn "pthread.h não encontrado — pode ser necessário: pkg install libc++"
    fi
fi

# ── 9. Memória RAM ──────────────────────────────────────────────────────
_MEM_KB=$(grep MemAvailable /proc/meminfo 2>/dev/null | awk '{print $2}' || echo "0")
_MEM_MB=$(( _MEM_KB / 1024 ))
if [ "$_MEM_MB" -ge 512 ]; then
    _pf_ok "RAM disponível: ${_MEM_MB}MB"
elif [ "$_MEM_MB" -ge 256 ]; then
    _pf_warn "RAM disponível: ${_MEM_MB}MB — compilação pode ser lenta"
else
    _pf_warn "RAM disponível: ${_MEM_MB}MB — muito pouco, pode falhar na compilação"
    _pf_info "Feche outros apps antes de instalar"
fi

# ── 10. Rede ────────────────────────────────────────────────────────────
if curl -s --max-time 3 https://www.lua.org >/dev/null 2>&1; then
    _pf_ok "Rede OK (lua.org acessível)"
else
    _pf_warn "Sem acesso à internet — download do Lua 5.4 pode falhar"
    _pf_info "Garanta conexão antes de instalar"
fi

# ── Resultado do preflight ───────────────────────────────────────────────
printf "\n"
if [ "$_PREFLIGHT_FAIL" = "1" ]; then
    printf "\033[1;31m╔══════════════════════════════════════════════════════╗\033[0m\n"
    printf "\033[1;31m║  PREFLIGHT FALHOU — corrija os erros acima           ║\033[0m\n"
    printf "\033[1;31m╚══════════════════════════════════════════════════════╝\033[0m\n\n"
    exit 1
else
    printf "\033[1;32m✓ Sistema compatível — iniciando instalação...\033[0m\n\n"
fi

# exporta flags detectados para uso no restante do instalador
export _PF_ARCH_FLAGS _PF_CC _ENV_TERMUX

fi  # fim do bloco: [ "$_SKIP_PREFLIGHT" = "0" ] → preflight completo

# ============================================================================
# ELLIOTOS v17.0 — SCRIPT ÚNICO COMPLETO
# IA nativa em C com libcurl (sem, sem dependência externa)
# Personalidade CYN portada do elliotai.py para C
# Sistema de retry, fallback, cache em disco, system prompt completo
# ============================================================================

# ── Ambiente: Termux por padrão, Linux via flag explícita ────────────────
OS_TYPE="termux"
BIN_DIR="${PREFIX:-/data/data/com.termux/files/usr}/bin"
INSTALL_EDITOR=0
INSTALL_GUI=0
INSTALL_SQ=0

# ── Parse de argumentos ──────────────────────────────────────────────────
# -e / --editor    : instala ElliotOS Editor (ee) — editor C nativo
# --termux         : força ambiente Termux (padrão)
# --debian         : ambiente Debian/Ubuntu (apt)
# --ubuntu         : alias para --debian
# --arch           : ambiente Arch Linux (pacman)
# --fedora         : ambiente Fedora/RHEL (dnf)
# --update         : recompila binário e atualiza scripts sem reinstalar tudo
# --doctor         : verifica instalação atual e reporta problemas
INSTALL_UNINSTALL=0
INSTALL_UNINSTALL_ALL=0
INSTALL_UPDATE=0


for _arg in "$@"; do
    case "$_arg" in
        -e|--editor)  INSTALL_EDITOR=1       ;;
        --gui)        INSTALL_GUI=1           ;;
        -sq)          INSTALL_SQ=1            ;;
        -u|--uninstall) INSTALL_UNINSTALL=1  ;;
        -ua)          INSTALL_UNINSTALL=1; INSTALL_UNINSTALL_ALL=1 ;;
        --update)     INSTALL_UPDATE=1       ;;
        --doctor)     ;;  # tratado no case final
        --termux)
            OS_TYPE="termux"
            BIN_DIR="${PREFIX:-/data/data/com.termux/files/usr}/bin"
            ;;
        --debian|--ubuntu)
            OS_TYPE="debian"
            BIN_DIR="/usr/local/bin"
            ;;
        --arch)
            OS_TYPE="arch"
            BIN_DIR="/usr/local/bin"
            ;;
        --fedora)
            OS_TYPE="fedora"
            BIN_DIR="/usr/local/bin"
            ;;
        -h|--help)
            printf "\033[1;35m┌────────────────────────────────────────────────────────────────┐\033[0m\n"
            printf "\033[1;35m│\033[0m\033[1;31m   _________ __   .__  .__        __   ________    _________  \033[0m \033[1;35m│\033[0m\n"
            printf "\033[1;35m│\033[0m\033[1;31m  /   _____/|  |  |  | |__| _____/  |_ \_____  \  /   _____/  \033[0m \033[1;35m│\033[0m\n"
            printf "\033[1;35m│\033[0m\033[1;31m  \_____  \ |  |  |  | |  |/  _ \   __\ /   |   \ \_____  \   \033[0m \033[1;35m│\033[0m\n"
            printf "\033[1;35m│\033[0m\033[1;31m  /        \|  |_ |  |_|  (  <_> )  |  /    |    \/        \  \033[0m \033[1;35m│\033[0m\n"
            printf "\033[1;35m│\033[0m\033[1;31m /_______  /|____/|____/__|\____/|__|  \_______  /_______  /  \033[0m  \033[1;35m│\033[0m\n"
            printf "\033[1;35m│\033[0m\033[1;31m         \/                                     \/        \/  \033[0m   \033[1;35m│\033[0m\n"
            printf "\033[1;35m└────────────────────────────────────────────────────────────────┘\033[0m\n"
            printf "\n"
            printf "  \033[1;37mElliotOS v17.0\033[0m  \033[0;90m—  O sistema operacional de scripting mais completo do Termux\033[0m\n"
            printf "  \033[0;90m  100%% Lua + C + Bash · Zero dependências externas · Sem Python · Sem Node\033[0m\n"
            printf "\n"
            printf "\033[0;90m  ────────────────────────────────────────────────────────────────\033[0m\n"
            printf "  \033[1;36m⚡ Por que ElliotOS é diferente?\033[0m\n"
            printf "\033[0;90m  ────────────────────────────────────────────────────────────────\033[0m\n"
            printf "\n"
            printf "  \033[1;32m🧠 IA Nativa em C\033[0m\n"
            printf "  \033[0;90m     CYN roda direto no binário — sem Python, sem dependências.\033[0m\n"
            printf "  \033[0;90m     Backend: tgpt (Pollinations grátis por padrão, sem chave).\033[0m\n"
            printf "  \033[0;90m     sky/pollinations/isou (sem key) · groq/openai/gemini/deepseek (com key).\033[0m\n"
            printf "  \033[0;90m     Mantém histórico de conversa, fallback automático entre providers.\033[0m\n"
            printf "\n"
            printf "  \033[1;32m🌐 Módulo net — Rede de alto nível\033[0m\n"
            printf "  \033[0;90m     HTTP/HTTPS, TCP, UDP, DNS, port scan, WebSocket, sockets raw.\033[0m\n"
            printf "  \033[0;90m     Tudo em Lua, powered by libcurl + sockets C nativos.\033[0m\n"
            printf "\n"
            printf "  \033[1;32m🔐 Módulo mod — 23 scanners de pentest\033[0m\n"
            printf "  \033[0;90m     XSS, SQLi, LFI, RCE, SSTI, SSRF, JWT, Open Redirect,\033[0m\n"
            printf "  \033[0;90m     spider automático, recon passivo, WAF detection e mais.\033[0m\n"
            printf "\n"
            printf "  \033[1;32m⚙  Módulo sys — Threads e processos reais\033[0m\n"
            printf "  \033[0;90m     Multi-threading nativo via pthreads, spawn de processos,\033[0m\n"
            printf "  \033[0;90m     task tracker, comunicação entre VMs Lua isoladas.\033[0m\n"
            printf "\n"
            printf "  \033[1;32m🔒 Módulo crypto — Criptografia OpenSSL\033[0m\n"
            printf "  \033[0;90m     MD5, SHA256, SHA512, HMAC, AES-256, Base64 — tudo nativo.\033[0m\n"
            printf "\n"
            printf "  \033[1;32m🗄  Módulo db — SQLite3 embutido\033[0m\n"
            printf "  \033[0;90m     Banco de dados local sem servidor, queries Lua direto no C.\033[0m\n"
            printf "\n"
            printf "  \033[1;32m🖥  Módulo cc — Compilador C inline\033[0m\n"
            printf "  \033[0;90m     Escreva, compile e execute código C direto do REPL Lua.\033[0m\n"
            printf "\n"
            printf "  \033[1;32m🎨 Editor ElliotOS/MoonStyle  \033[0;90m(flag -e)\033[0m\n"
            printf "  \033[0;90m     Editor C nativo: syntax highlight Lua/C/Bash, auto-pair, completions\033[0m\n"
            printf "  \033[0;90m     da API ElliotOS (net.* mod.* ai.* fs.* sys.* crypto.*), zero deps.\033[0m\n"
            printf "\n"
            printf "\033[0;90m  ────────────────────────────────────────────────────────────────\033[0m\n"
            printf "  \033[1;36mUSO:\033[0m  bash luascript [ambiente] [perfil] [opções]\n\n"
            printf "  \033[1;33mAmbiente\033[0m  \033[0;90m(padrão: Termux — sem root em qualquer plataforma)\033[0m\n"
            printf "  \033[1;32m  --termux\033[0m         Android/Termux\n"
            printf "  \033[1;32m  --debian\033[0m         Debian ou Ubuntu (apt)\n"
            printf "  \033[1;32m  --ubuntu\033[0m         alias para --debian\n"
            printf "  \033[1;32m  --arch\033[0m           Arch Linux (pacman)\n"
            printf "  \033[1;32m  --fedora\033[0m         Fedora / RHEL (dnf)\n\n"
            printf "  \033[1;33mOpções\033[0m\n"
            printf "  \033[1;32m  -e / --editor\033[0m    \033[0;90minstala editor MoonStyle (Lua·C/C++ LSP + Luarocks)\033[0m\n"
            printf "  \033[1;32m  -u\033[0m               \033[0;90mdesinstala ElliotOS (mantém clang, curl, openssl...)\033[0m\n"
            printf "  \033[1;32m  -ua\033[0m              \033[0;90mdesinstala ElliotOS + todas as dependências do sistema\033[0m\n"
            printf "  \033[1;32m  --update\033[0m         \033[0;90mrecompila binário e atualiza scripts (sem reinstalar deps)\033[0m\n"
            printf "  \033[1;32m  --doctor\033[0m         \033[0;90mverifica saúde da instalação atual\033[0m\n\n"
            printf "  \033[1;32m  --gui\033[0m            \033[0;90minstala ElliotOS + XFCE4 via Termux:X11 (interface gr\u00e1fica)\033[0m\n"

            printf "  \033[1;32m  -sq\033[0m               \033[0;90moutput verbose da compilação (sem barra de progresso)\033[0m\n"
            printf "  \033[1;36mExemplos:\033[0m\n"
            printf "  \033[0;90m  bash luascript\033[0m                     \033[0;90m# Termux\033[0m\n"
            printf "  \033[0;90m  bash luascript -e\033[0m                  \033[0;90m# Termux + editor MoonStyle\033[0m\n"
            printf "  \033[0;90m  bash luascript --debian -e\033[0m         \033[0;90m# Debian + editor\033[0m\n"
            printf "  \033[0;90m  bash luascript -u\033[0m                  \033[0;90m# desinstala ElliotOS (deps mantidas)\033[0m\n"
            printf "  \033[0;90m  bash luascript -ua\033[0m                 \033[0;90m# desinstala tudo, inclusive deps\033[0m\n"
            printf "  \033[0;90m  bash luascript --update\033[0m            \033[0;90m# atualiza sem reinstalar\033[0m\n"
            printf "  \033[0;90m  bash luascript --doctor\033[0m            \033[0;90m# diagnóstico da instalação\033[0m\n\n"
            printf "  \033[0;90m  bash luascript --gui\033[0m               \033[0;90m# instala com interface gr\u00e1fica XFCE4\033[0m\n"
            printf "  \033[0;90melliot                  → REPL Lua interativo\033[0m\n"
            printf "  \033[0;90melliot script.lua       → executa script\033[0m\n"
            printf "  \033[0;90melliot -e 'print(1+1)'  → inline\033[0m\n"
            printf "  \033[0;90mms -h                   → ajuda da CLI central\033[0m\n\n"
            printf "  \033[0;90mCYN está aqui. Sem Python. Sem desculpas.  \033[1;35m💜\033[0m\n\n"
            exit 0
            ;;
    esac
done

# Ajusta PREFIX e BIN para Linux se necessário
if [ "$OS_TYPE" != "termux" ]; then
    PREFIX="${PREFIX:-/usr/local}"
    BIN_DIR="/usr/local/bin"
fi
BIN="${BIN_DIR}/lua-net"
BUILD_DIR="$HOME/.lua-net-build"
CACHE_DIR="$HOME/.lua-cache"
SCRIPTS_DIR="$PREFIX/share/lua-scripts"
C_SCRIPTS_DIR="$PREFIX/share/c-scripts"
MODULES_DIR="$PREFIX/share/lua-modules"
LUA_VERSION="5.4.8"
LUA_TAR="lua-${LUA_VERSION}.tar.gz"
LUA_URL="https://www.lua.org/ftp/${LUA_TAR}"

# ── Desinstalador ─────────────────────────────────────────────────────────
# Toda a lógica vive em _run_uninstall() (definida no final do script).
# Aqui apenas exibimos o banner, pedimos confirmação e delegamos.
# Manter a lógica num único lugar evita divergência entre as duas entradas
# de desinstalação (-u no meio do script vs. -u no case final).
if [ "$INSTALL_UNINSTALL" = "1" ]; then
    # Guard: HOME vazio/inválido tornaria os rm -rf em _run_uninstall destrutivos
    if [ -z "${HOME:-}" ] || [ ! -d "$HOME" ]; then
        printf "\033[1;31m[✗] Variável HOME não definida ou inválida — abortando desinstalação.\033[0m\n"
        exit 1
    fi
    printf "\033[1;31m"
    printf "  ╔══════════════════════════════════════════════════════╗\n"
    if [ "$INSTALL_UNINSTALL_ALL" = "1" ]; then
        printf "  ║     ElliotOS — Desinstalador COMPLETO                ║\n"
        printf "  ║  Remove ElliotOS + todas as dependências.            ║\n"
        printf "  ║  ⚠  clang, curl, openssl, sqlite... serão removidos ║\n"
    else
        printf "  ║        ElliotOS — Desinstalador                      ║\n"
        printf "  ║  Remove binários e arquivos do ElliotOS.             ║\n"
        printf "  ║  Dependências do sistema (clang, curl...) mantidas.  ║\n"
    fi
    printf "  ╚══════════════════════════════════════════════════════╝\n"
    printf "\033[0m\n"
    printf "  \033[1;33m[?] Confirmar desinstalação? [s/N]:\033[0m "
    read -r _confirm
    if [ "$_confirm" != "s" ] && [ "$_confirm" != "S" ]; then
        printf "  \033[1;32m[✓] Cancelado.\033[0m\n"
        exit 0
    fi
    # Bash lê o script inteiro antes de executar, então _run_uninstall()
    # já existe em memória mesmo sendo definida mais adiante no arquivo.
    _run_uninstall
    exit 0
fi

setup_dirs() {
    mkdir -p "$BUILD_DIR" "$CACHE_DIR" "$SCRIPTS_DIR" "$C_SCRIPTS_DIR" "$MODULES_DIR"
    mkdir -p "$HOME/.elliotai"
    mkdir -p "$HOME/.lua-modules"
    # Registra ~/.lua-modules no LUA_PATH para que require() encontre os módulos do lmod
    if ! grep -qF "lua-modules" "$HOME/.bashrc" 2>/dev/null; then
        echo 'export LUA_PATH="$HOME/.lua-modules/?.lua;$HOME/.lua-modules/?/init.lua;${LUA_PATH:-}"' >> "$HOME/.bashrc"
    fi
    touch "$CACHE_DIR/.gitkeep"
    # Remove models.json para forçar reinicialização com modelos padrão atualizados
    rm -f "$HOME/.elliotai/models.json"

    # Garante que o diretório de binários do npm esteja no PATH (Termux)
    if [ "$OS_TYPE" = "termux" ]; then
        NPM_BIN_PATH="$HOME/.node_modules/bin"
        mkdir -p "$HOME/.node_modules"
        npm config set prefix "$HOME/.node_modules" 2>/dev/null || true
        if ! grep -q "export PATH=\"$NPM_BIN_PATH:\$PATH\"" "$HOME/.bashrc"; then
            echo "export PATH=\"$NPM_BIN_PATH:\$PATH\"" >> "$HOME/.bashrc"
            printf "\033[1;32m  ✔ Configurado PATH para npm global no .bashrc\033[0m\n"
        fi
    fi
}

check_dependencies() {
    # Helper: instala tgpt em qualquer distro
    _install_tgpt() {
        if command -v tgpt >/dev/null 2>&1; then
            _ok "tgpt já instalado — pulando"
            return 0
        fi
        _step "🤖" "Instalando tgpt (backend IA)..."
        pkg install -y fakeroot tgpt 2>/dev/null || \
        { _tgpt_tmp=$(mktemp 2>/dev/null || echo "${TMPDIR:-$HOME/.cache/elliot}/tgpt_install_$$.sh") && \
          curl -sSL https://raw.githubusercontent.com/aandrew-me/tgpt/main/install \
              -o "$_tgpt_tmp" 2>/dev/null && \
          [ -s "$_tgpt_tmp" ] && bash "$_tgpt_tmp" 2>/dev/null; \
          rm -f "$_tgpt_tmp"; } || \
        _warn "tgpt não instalado — instale manualmente depois"
    }

    # Helper: checa se uma lista de binários/comandos já está disponível
    # Uso: _all_cmds_exist clang make cmake curl
    _all_cmds_exist() {
        for _cmd in "$@"; do
            command -v "$_cmd" >/dev/null 2>&1 || return 1
        done
        return 0
    }

    case "$OS_TYPE" in
        termux)
            if [ "${INSTALL_UPDATE:-0}" = "1" ]; then
                _ok "Modo --update: pulando instalação de dependências"
            else
            # Remove versões conflitantes de Lua
            pkg remove -y luarocks lua54 lua53 lua52 lua51 2>/dev/null || true
            rm -f "${PREFIX}/bin/lua5.4" "${PREFIX}/bin/lua5.3" "${PREFIX}/bin/lua5.1" \
                  "${PREFIX}/bin/luarocks" "${PREFIX}/bin/luarocks-5.4" 2>/dev/null || true

            # Pacotes base — instala só se algum estiver faltando
            if ! _all_cmds_exist clang make cmake curl wget git figlet nmap file; then
                _step "📦" "Instalando dependências base..."
                pkg install -y wget timg which binutils wget git make cmake build-essential clang \
                    figlet tree readline curl libcurl openssl openssl-tool \
                    autoconf whois ncurses nmap file 2>/dev/null || true
            else
                _ok "Dependências base já instaladas — pulando"
            fi

            # libcurl/libssh2: reinstala sempre para garantir compatibilidade de símbolos
            _step "🔗" "Atualizando libcurl + libssh2 (compatibilidade de símbolos)..."
            pkg reinstall -y libcurl libssh2 2>/dev/null || true
            pkg upgrade -y libssh2 libcurl 2>/dev/null || true

            _install_tgpt

            # SQLite + Node
            if ! _all_cmds_exist node sqlite3; then
                _step "📦" "Instalando SQLite + Node..."
                pkg install -y libsqlite sqlite nodejs 2>/dev/null || true
            else
                _ok "SQLite + Node já instalados — pulando"
            fi
            fi  # end INSTALL_UPDATE check
            ;;

        debian)
            _SUDO=""; command -v sudo >/dev/null 2>&1 && _SUDO="sudo"
            [ "$(id -u)" = "0" ] && _SUDO=""

            if [ "${INSTALL_UPDATE:-0}" != "1" ]; then
            if ! _all_cmds_exist clang make cmake curl wget git figlet nmap file; then
                _step "📦" "Instalando dependências base..."
                $_SUDO apt-get update -qq 2>/dev/null || true
                $_SUDO apt-get install -y \
                    build-essential clang wget git make cmake \
                    libreadline-dev libcurl4-openssl-dev libssl-dev \
                    libncurses-dev figlet whois curl nmap file 2>/dev/null || true
            else
                _ok "Dependências base já instaladas — pulando"
            fi

            _install_tgpt

            _NODE_VER=$(node --version 2>/dev/null | tr -d v | cut -d. -f1)
            _SQLITE_OK=0
            dpkg -l libsqlite3-dev sqlite3 >/dev/null 2>&1 && _SQLITE_OK=1
            if [ "${_SQLITE_OK}" = "0" ] || [ -z "$_NODE_VER" ] || [ "${_NODE_VER:-0}" -lt 18 ] 2>/dev/null; then
                _step "📦" "Instalando SQLite + Node..."
                if [ -z "$_NODE_VER" ] || [ "${_NODE_VER:-0}" -lt 18 ] 2>/dev/null; then
                    curl -fsSL https://deb.nodesource.com/setup_20.x | $_SUDO bash - 2>/dev/null || true
                fi
                $_SUDO apt-get install -y libsqlite3-dev sqlite3 nodejs 2>/dev/null || true
            else
                _ok "SQLite + Node já instalados — pulando"
            fi
            fi  # end INSTALL_UPDATE
            ;;

        arch)
            _SUDO=""; command -v sudo >/dev/null 2>&1 && _SUDO="sudo"
            [ "$(id -u)" = "0" ] && _SUDO=""

            if [ "${INSTALL_UPDATE:-0}" != "1" ]; then
            if ! _all_cmds_exist clang make cmake curl wget git figlet nmap file; then
                _step "📦" "Instalando dependências base..."
                $_SUDO pacman -Sy --noconfirm \
                    base-devel clang wget git cmake \
                    readline curl openssl ncurses figlet whois nmap file 2>/dev/null || true
            else
                _ok "Dependências base já instaladas — pulando"
            fi

            _install_tgpt

            if ! _all_cmds_exist node sqlite3; then
                _step "📦" "Instalando SQLite + Node..."
                $_SUDO pacman -S --noconfirm sqlite nodejs npm 2>/dev/null || true
            else
                _ok "SQLite + Node já instalados — pulando"
            fi
            fi  # end INSTALL_UPDATE
            ;;

        fedora)
            _SUDO=""; command -v sudo >/dev/null 2>&1 && _SUDO="sudo"
            [ "$(id -u)" = "0" ] && _SUDO=""

            if [ "${INSTALL_UPDATE:-0}" != "1" ]; then
            if ! _all_cmds_exist clang make cmake curl wget git figlet nmap file; then
                _step "📦" "Instalando dependências base..."
                # figlet via EPEL no Fedora
                $_SUDO dnf install -y epel-release 2>/dev/null || true
                $_SUDO dnf install -y \
                    gcc clang make cmake wget git \
                    readline-devel libcurl-devel openssl-devel \
                    ncurses-devel figlet whois curl nmap file 2>/dev/null || true
            else
                _ok "Dependências base já instaladas — pulando"
            fi

            _install_tgpt

            if ! _all_cmds_exist node sqlite3; then
                _step "📦" "Instalando SQLite + Node..."
                $_SUDO dnf install -y sqlite-devel sqlite nodejs npm 2>/dev/null || true
            else
                _ok "SQLite + Node já instalados — pulando"
            fi
            fi  # end INSTALL_UPDATE
            ;;

        *)
            printf "\033[1;33m  ⚠ OS não reconhecido.\033[0m\n"
            printf "\033[0;90m  Instale: clang libcurl openssl readline ncurses sqlite make\033[0m\n"
            ;;
    esac
}

