_print_banner() {
    printf "\033[1;35m┌────────────────────────────────────────────────────────────────┐\033[0m\n"
    printf "\033[1;35m│\033[0m\033[1;31m   _________ __   .__  .__        __   ________    _________  \033[0m \033[1;35m│\033[0m\n"
    printf "\033[1;35m│\033[0m\033[1;31m  /   _____/|  |  |  | |__| _____/  |_ \\_____  \\  /   _____/  \033[0m \033[1;35m│\033[0m\n"
    printf "\033[1;35m│\033[0m\033[1;31m  \\_____  \\ |  |  |  | |  |/  _ \\   __\\ /   |   \\ \\_____  \\   \033[0m \033[1;35m│\033[0m\n"
    printf "\033[1;35m│\033[0m\033[1;31m  /        \\|  |_ |  |_|  (  <_> )  |  /    |    \\/        \\  \033[0m \033[1;35m│\033[0m\n"
    printf "\033[1;35m│\033[0m\033[1;31m /_______  /|____/|____/__|\\____/|__|  \\_______  /_______  /  \033[0m  \033[1;35m│\033[0m\n"
    printf "\033[1;35m│\033[0m\033[1;31m         \\/                                     \\/        \\/   \033[0m  \033[1;35m│\033[0m\n"
    printf "\033[1;35m│                                                                │\033[0m\n"
    printf "\033[1;35m│\033[0m\033[1;36m  __  __                ___  _        _                        \033[0m \033[1;35m│\033[0m\n"
    printf "\033[1;35m│\033[0m\033[1;36m |  \\/  | ___  ___ _ _ / __|| |_ _  _| | ___                   \033[0m \033[1;35m│\033[0m\n"
    printf "\033[1;35m│\033[0m\033[1;36m | |\\/| |/ _ \\/ _ \\ \\ /\\__ \\| __| || | |/ -_)                  \033[0m \033[1;35m│\033[0m\n"
    printf "\033[1;35m│\033[0m\033[1;36m |_|  |_|\\___/\\___/_\\_\\|___/ \\__|\\_, |_|\\___|                  \033[0m \033[1;35m│\033[0m\n"
    printf "\033[1;35m│\033[0m\033[1;36m                                  |__/                         \033[0m \033[1;35m│\033[0m\n"
    printf "\033[1;35m└────────────────────────────────────────────────────────────────┘\033[0m\n"
}

_step() {
    # _step ICON "mensagem"
    printf "\033[1;36m  %s\033[0m \033[1;37m%s\033[0m\n" "$1" "$2"
}

_ok() {
    printf "\033[1;32m     ✓ %s\033[0m\n" "$1"
}

_warn() {
    printf "\033[1;33m     ⚠ %s\033[0m\n" "$1"
}

_err() {
    printf "\033[1;31m     ✗ %s\033[0m\n" "$1"
}

_section() {
    printf "\n\033[0;90m  ───────────────────────────────────────────────────\033[0m\n"
    printf "\033[1;35m  %s\033[0m\n" "$1"
    printf "\033[0;90m  ───────────────────────────────────────────────────\033[0m\n\n"
}

install_elliotos() {
    _INSTALL_START=$(date +%s)

    # ── Lock de instalação — evita conflito se rodar dois instaladores ao mesmo tempo
    _LOCK_DIR="${TMPDIR:-$HOME/.cache/elliot}"
    _LOCK_FILE="$_LOCK_DIR/.elliotos_install.lock"
    mkdir -p "$_LOCK_DIR"
    if [ -f "$_LOCK_FILE" ]; then
        _LOCK_PID=$(cat "$_LOCK_FILE" 2>/dev/null)
        # Ignora o lock se o PID for o proprio processo (chamada interna, ex: --gui chama install_elliotos)
        if [ "$_LOCK_PID" != "$$" ] && kill -0 "$_LOCK_PID" 2>/dev/null; then
            printf "\033[1;31m[✗] Outra instalação do ElliotOS já está em andamento (PID $_LOCK_PID).\033[0m\n"
            printf "\033[0;90m    Se isso for um erro, remova: $_LOCK_FILE\033[0m\n"
            exit 1
        fi
    fi
    echo $$ > "$_LOCK_FILE"
    trap 'rm -f "$_LOCK_FILE"' EXIT INT TERM

    clear

    # ── Banner de abertura ────────────────────────────────────────────────
    _print_banner
    printf "\033[1;37m  ElliotOS v17.0\033[0m  \033[0;90m—  Sistema operacional de IA nativa para Termux\033[0m\n"
    printf "\n"
    printf "\033[0;90m  ┌─ O que é o ElliotOS? ──────────────────────────────────────────┐\033[0m\n"
    printf "\033[0;90m  │\033[0m  Um ambiente Lua compilado em C puro, sem Python, sem Node,    \033[0;90m│\033[0m\n"
    printf "\033[0;90m  │\033[0m  sem dependências externas. IA via tgpt (Pollinations grátis    \033[0;90m│\033[0m\n"
    printf "\033[0;90m  │\033[0m  por padrão, sem chave) com a personalidade \033[1;35mCYN\033[0m. Pentest   \033[0;90m│\033[0m\n"
    printf "\033[0;90m  │\033[0m  toolkit com 23 scanners, labs locais e rede real em C.        \033[0;90m│\033[0m\n"
    printf "\033[0;90m  └────────────────────────────────────────────────────────────────┘\033[0m\n"
    printf "\n"
    printf "\033[1;36m  Base:\033[0m    \033[0;90mLua ${LUA_VERSION} + libcurl + readline + pthreads + OpenSSL + SQLite3\033[0m\n"
    printf "\033[1;36m  IA:\033[0m      \033[0;90mtgpt — sky · pollinations · isou (sem key) · groq · openai · gemini · deepseek\033[0m\n"
    printf "\n"

    # ── Dependências ─────────────────────────────────────────────────────
    _section "ETAPA 1 / 4 — Dependências do sistema"
    _step "📦" "Verificando pacotes necessários..."
    check_dependencies
    setup_dirs
    _ok "Todas as dependências instaladas"

    if ! command -v ar &>/dev/null; then
        _warn "ar não encontrado — criando symlink para llvm-ar"
        ln -sf "$PREFIX/bin/llvm-ar"     "$PREFIX/bin/ar"     2>/dev/null || true
        ln -sf "$PREFIX/bin/llvm-ranlib" "$PREFIX/bin/ranlib" 2>/dev/null || true
    fi

    # ── Preparação ───────────────────────────────────────────────────────
    _section "ETAPA 2 / 4 — Preparando ambiente de build"
    _step "🛠 " "Limpando sessão anterior..."
    pkill -9 -x lua-net 2>/dev/null || true  # pkill é mais portável que killall (ausente em algumas distros)
    rm -f "$BIN" "$PREFIX/bin/ms" "$PREFIX/bin/lua" "$PREFIX/bin/luar" "$PREFIX/bin/elliot"
    rm -rf "$BUILD_DIR" && mkdir -p "$BUILD_DIR"
    # Remove artefatos de build anteriores para evitar conflito na reinsatalação
    rm -f "$HOME/.elliot_libnet.log" "$HOME/.elliot_make.log" "$HOME/.elliot_vanilla.log"
    cd "$BUILD_DIR"
    _ok "Diretório de build: $BUILD_DIR"

    # ── Limpa caches de versões antigas do Lua ───────────────────────────
    find "$CACHE_DIR" -name "lua-*.tar.gz" ! -name "lua-${LUA_VERSION}.tar.gz" -delete 2>/dev/null || true


    _download_with_retry() {
        local _url="$1" _out="$2" _tries=3 _wait=2 _i
        # mirrors em ordem — tenta o oficial primeiro, depois o espelho
        local _mirrors="$_url https://mirror.inode.at/lua/ftp/$(basename $_url)"
        for _i in $(seq 1 $_tries); do
            for _m in $_mirrors; do
                printf "    \033[0;90m↳ tentativa %d: %s\033[0m\n" "$_i" "$_m"
                wget --timeout=30 --tries=1 -q --show-progress "$_m" -O "$_out" \
                    && return 0
            done
            _warn "Tentativa $_i falhou — aguardando ${_wait}s..."
            sleep $_wait; _wait=$((_wait * 2))
        done
        _err "Download falhou após $_tries tentativas — verifique sua conexão"
        exit 1
    }

    # ── Download Lua ─────────────────────────────────────────────────────
    _step "⬇ " "Obtendo Lua ${LUA_VERSION}..."
    _need_download=1
    # SHA256SUMS: timeout de 10s — se lua.org demorar, ignora e pula verificação
    _real_sha=$(wget --timeout=10 --tries=1 -qO- \
        "https://www.lua.org/ftp/SHA256SUMS" 2>/dev/null \
        | awk "/$LUA_TAR/"'{print $1}')
    if [ -f "$CACHE_DIR/$LUA_TAR" ]; then
        _cached_sha=$(sha256sum "$CACHE_DIR/$LUA_TAR" 2>/dev/null | cut -d' ' -f1)
        if tar -tzf "$CACHE_DIR/$LUA_TAR" >/dev/null 2>&1; then
            if [ -n "$_real_sha" ] && [ "$_cached_sha" != "$_real_sha" ]; then
                _warn "SHA256 não confere — cache adulterado, baixando novamente..."
                rm -f "$CACHE_DIR/$LUA_TAR"
            else
                cp "$CACHE_DIR/$LUA_TAR" .
                _ok "Cache válido (SHA256 OK) — download ignorado"
                _need_download=0
            fi
        else
            _warn "Cache corrompido — baixando novamente..."
            rm -f "$CACHE_DIR/$LUA_TAR"
        fi
    fi
    if [ "$_need_download" = "1" ]; then
        _download_with_retry "$LUA_URL" "$LUA_TAR"
        # Verifica integridade do arquivo recém baixado
        if [ -n "$_real_sha" ]; then
            _dl_sha=$(sha256sum "$LUA_TAR" 2>/dev/null | cut -d' ' -f1)
            if [ "$_dl_sha" != "$_real_sha" ]; then
                _err "SHA256 não confere após download — arquivo corrompido ou adulterado"
                rm -f "$LUA_TAR"
                exit 1
            fi
            _ok "SHA256 verificado ✓"
        fi
        cp "$LUA_TAR" "$CACHE_DIR/"
        _ok "Lua ${LUA_VERSION} baixado e salvo em cache"
    fi

    _step "📂" "Extraindo fontes..."
    # Extrai com múltiplos threads se pigz/pbzip2 disponível, senão tar normal
    if command -v pigz >/dev/null 2>&1; then
        tar -x --use-compress-program=pigz -f "$LUA_TAR"
    else
        tar -xzf "$LUA_TAR"
    fi
    cd "lua-${LUA_VERSION}/src"
    _ok "Fontes extraídos em $BUILD_DIR/lua-${LUA_VERSION}/src"

    # ── Compila lua vanilla ANTES de qualquer patch ──────────────────────────
    _step "🔧" "Compilando Lua ${LUA_VERSION} raw (luar)..."
    _TPFX_V="${PREFIX:-/data/data/com.termux/files/usr}"
    # usa flags detectados no preflight, com fallback
    _ARCH_FLAGS="${_PF_ARCH_FLAGS:--O2}"
    _CC="${_PF_CC:-clang}"
    _VANILLA_FLAGS="${_ARCH_FLAGS} -fPIC -DLUA_USE_POSIX -DLUA_USE_DLOPEN -DLUA_USE_READLINE -I${_TPFX_V}/include"
    _VANILLA_LIBS="-lm -ldl -lreadline -L${_TPFX_V}/lib"
    # tenta ncurses, fallback tinfo (varia por versão do Termux)
    _NCURSES_LIB=""
    [ -f "${_TPFX_V}/lib/libncurses.so" ] && _NCURSES_LIB="-lncurses"
    [ -z "$_NCURSES_LIB" ] && [ -f "${_TPFX_V}/lib/libtinfo.so" ] && _NCURSES_LIB="-ltinfo"
    _VANILLA_LIBS="$_VANILLA_LIBS $_NCURSES_LIB"
    _SRC_DIR="$(pwd)"
    printf "  \033[0;90m[luar] compilador: %s\033[0m\n" "$_CC"
    printf "  \033[0;90m[luar] src dir: %s\033[0m\n" "$_SRC_DIR"
    printf "  \033[0;90m[luar] bin dir: %s\033[0m\n" "$BIN_DIR"

    # ── Barra de progresso do luar ───────────────────────────────────────────
    _luar_bar_width=40
    _luar_bar_draw() {
        local pct=$1 label=$2
        local filled=$(( pct * _luar_bar_width / 100 ))
        local empty=$(( _luar_bar_width - filled ))
        local bar=""
        for ((i=0;i<filled;i++)); do bar+="█"; done
        for ((i=0;i<empty;i++));  do bar+="░"; done
        printf "\r  \033[1;34m[%s]\033[0m \033[1;36m%3d%%\033[0m  %s" "$bar" "$pct" "$label"
    }

    printf "\n"
    if [ "$INSTALL_SQ" = "1" ]; then
        printf "\n\033[1;36m── Compilando luar (Lua ${LUA_VERSION} raw) ──────────────────────────\033[0m\n"
        (
            cd "$_SRC_DIR"
            ${_CC} ${_VANILLA_FLAGS} -v \
                lua.c \
                lapi.c lcode.c lctype.c ldebug.c ldo.c ldump.c lfunc.c lgc.c llex.c \
                lmem.c lobject.c lopcodes.c lparser.c lstate.c lstring.c ltable.c \
                ltm.c lundump.c lvm.c lzio.c \
                lauxlib.c lbaselib.c lcorolib.c ldblib.c liolib.c lmathlib.c \
                loadlib.c loslib.c lstrlib.c ltablib.c lutf8lib.c linit.c \
                ${_VANILLA_LIBS} -o "$_SRC_DIR/luar_bin"
        ) 2>&1 | tee "$HOME/.elliot_vanilla.log"
        _LUAR_OK=${PIPESTATUS[0]}
    else
        _luar_bar_draw 0 "Aguardando compilador...         "
        (
            cd "$_SRC_DIR"
            ${_CC} ${_VANILLA_FLAGS} \
                lua.c \
                lapi.c lcode.c lctype.c ldebug.c ldo.c ldump.c lfunc.c lgc.c llex.c \
                lmem.c lobject.c lopcodes.c lparser.c lstate.c lstring.c ltable.c \
                ltm.c lundump.c lvm.c lzio.c \
                lauxlib.c lbaselib.c lcorolib.c ldblib.c liolib.c lmathlib.c \
                loadlib.c loslib.c lstrlib.c ltablib.c lutf8lib.c linit.c \
                ${_VANILLA_LIBS} -o "$_SRC_DIR/luar_bin"
        ) > "$HOME/.elliot_vanilla.log" 2>&1
        _LUAR_OK=$?
        _luar_pct=0
        _luar_spinchars='⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏'
        _luar_spin=0
        while kill -0 "$_luar_pid" 2>/dev/null; do
            [ "$_luar_pct" -lt 95 ] && _luar_pct=$(( _luar_pct + 2 ))
            _luar_sc=$(printf '%s' "$_luar_spinchars" | cut -c$(( (_luar_spin % 10) + 1 )))
            _luar_bar_draw "$_luar_pct" "Compilando luar... ${_luar_sc}           "
            _luar_spin=$(( _luar_spin + 1 ))
            sleep 0.25
        done
        _luar_bar_draw 100 "Concluído!                       "
        printf "\n\n"
    fi

