    local $/; my $content = <$fh>; close $fh;
    my $orig = $content;
    for my $pair (@{ $T{$file} }) {
        my ($from, $to) = @$pair;
        $content =~ s/\Q$from\E/$to/g;
    }
    if ($content ne $orig) {
        open(my $out, ">:raw", $file) or next;
        print $out $content; close $out;
    }
