// ============================================================================
// PERSISTÊNCIA — salva/carrega modelos em ~/.elliotai/models.json
// ============================================================================
static char AI_DB_PATH[512] = "";

// Forward declaration — definida depois de CurlBuf
static void json_escape(const char *src, char *dst, size_t size);

static void ai_db_init() {
    const char *home = getenv("HOME");
    if (!home) home = "/data/data/com.termux/files/home";
    snprintf(AI_DB_PATH, sizeof(AI_DB_PATH), "%s/.elliotai/models.json", home);
    char dir[512];
    snprintf(dir, sizeof(dir), "%s/.elliotai", home);
    mkdir(dir, 0755);
}

static void ai_db_save() {
    if (!AI_DB_PATH[0]) ai_db_init();
    FILE *f = fopen(AI_DB_PATH, "w");
    if (!f) return;
    char esc_def[128] = {0};
    json_escape(default_model_name, esc_def, sizeof(esc_def));
    fprintf(f, "{\n  \"default\": \"%s\",\n  \"models\": [\n", esc_def);
    for (int i = 0; i < ai_model_count; i++) {
        char esc_name[128]  = {0};
        char esc_model[512] = {0};
        json_escape(ai_models[i].name,  esc_name,  sizeof(esc_name));
        json_escape(ai_models[i].model, esc_model, sizeof(esc_model));
        fprintf(f, "    {\"name\": \"%s\", \"model\": \"%s\"}%s\n",
            esc_name, esc_model,
            i < ai_model_count - 1 ? "," : "");
    }
    fprintf(f, "  ]\n}\n");
    fclose(f);
}

static void ai_db_load() {
    if (!AI_DB_PATH[0]) ai_db_init();
    FILE *f = fopen(AI_DB_PATH, "r");
    if (!f) {
        /* Primeira execução — semente com modelos Gemini padrão */
        strncpy(ai_models[0].name,  "sky",              63);
        strncpy(ai_models[0].model, "gemini-2.5-flash",  255);
        strncpy(ai_models[1].name,  "code",              63);
        strncpy(ai_models[1].model, "gemini-2.5-flash",  255);
        strncpy(ai_models[2].name,  "pro",               63);
        strncpy(ai_models[2].model, "gemini-2.5-pro", 255);
        ai_model_count = 3;
        strncpy(default_model_name, "sky", sizeof(default_model_name)-1);
        strncpy(active_model_url,   "gemini-2.5-flash", 255);
        ai_db_save();
        printf("\033[0;90m[ai] Gemini pronto: 2.5-flash · 2.5-pro · gemma-3-27b\033[0m\n");
        return;
    }
    char buf[65536] = {0};
    fread(buf, 1, sizeof(buf)-1, f);
    buf[65535] = '\0'; /* garante terminação mesmo com leitura parcial */
    fclose(f);
    char *dp = strstr(buf, "\"default\":");
    if (dp) {
        dp += strlen("\"default\":"); while (*dp==' ') dp++;
        if (*dp=='"') { dp++; int j=0; while(*dp&&*dp!='"'&&j<63) default_model_name[j++]=*dp++; default_model_name[j]='\0'; }
    }
    char *p = buf; ai_model_count = 0;
    while (ai_model_count < MAX_AI_MODELS && (p = strstr(p, "\"name\":")) != NULL) {
        p += strlen("\"name\":"); while(*p==' ') p++;
        if(*p!='"') continue; p++;
        int j=0; while(*p&&*p!='"'&&j<63) ai_models[ai_model_count].name[j++]=*p++;
        ai_models[ai_model_count].name[j]='\0'; p++;
        char *mp=strstr(p,"\"model\":"); if(!mp) break;
        mp+=strlen("\"model\":"); while(*mp==' ') mp++;
        if(*mp!='"') break; mp++;
        j=0; while(*mp&&*mp!='"'&&j<255) ai_models[ai_model_count].model[j++]=*mp++;
        ai_models[ai_model_count].model[j]='\0'; mp++;
        if(strcmp(ai_models[ai_model_count].name, default_model_name)==0)
            strncpy(active_model_url, ai_models[ai_model_count].model, 255);
        ai_model_count++; p=mp;
    }
}

// ============================================================================
// BUFFER DINÂMICO PARA RESPOSTA DO CURL
// ============================================================================
typedef struct {
    char *data;
    size_t size;
} CurlBuf;

static size_t curl_write_cb(void *ptr, size_t size, size_t nmemb, void *userdata) {
    CurlBuf *buf = (CurlBuf *)userdata;
    size_t total = size * nmemb;
    /* Crescimento exponencial: dobra cap a cada realoc */
    size_t newcap = buf->size + total + 1;
    if (newcap < buf->size * 2) newcap = buf->size * 2;
    if (newcap < 4096) newcap = 4096;
    char *tmp = realloc(buf->data, newcap);
    if (!tmp) return 0;
    buf->data = tmp;
    memcpy(buf->data + buf->size, ptr, total);
    buf->size += total;
    buf->data[buf->size] = '\0';
    return total;
}

// ============================================================================
// ESCAPE JSON
// ============================================================================
static void json_escape(const char *src, char *dst, size_t size) {
    size_t j = 0;
    for (size_t i = 0; src[i] && j + 6 < size; i++) {
        unsigned char c = (unsigned char)src[i];
        if (c == '"')  { dst[j++]='\\'; dst[j++]='"'; }
        else if (c == '\\') { dst[j++]='\\'; dst[j++]='\\'; }
        else if (c == '\n') { dst[j++]='\\'; dst[j++]='n'; }
        else if (c == '\r') { dst[j++]='\\'; dst[j++]='r'; }
        else if (c == '\t') { dst[j++]='\\'; dst[j++]='t'; }
        else if (c < 0x20) { /* skip control chars */ }
        else { dst[j++] = c; }
    }
    dst[j] = '\0';
}

// ============================================================================
// CARREGA CHAVE GEMINI — env var OU lê do ~/.bashrc / ~/.profile como fallback
// Resolve o problema de a chave estar salva mas a sessão não ter sido recarregada
// ============================================================================
static char g_gemini_key_buf[256] = "";

static const char *gemini_key_load(void) {
    /* 1. Tenta env vars em ordem de prioridade */
    const char *k = getenv("ELLIOT_AI_KEY");
    if (k && strlen(k) > 8) return k;
    k = getenv("GEMINI_API_KEY");
    if (k && strlen(k) > 8) return k;
    k = getenv("GROQ_API_KEY");
    if (k && strlen(k) > 8) return k;
    k = getenv("AI_KEY");
    if (k && strlen(k) > 8) return k;

    /* 2. Já carregamos antes nesta sessão? */
    if (g_gemini_key_buf[0]) return g_gemini_key_buf;

    /* 3. Fallback: lê do ~/.bashrc e ~/.profile */
    const char *home = getenv("HOME");
    if (!home) home = "/data/data/com.termux/files/home";

    const char *rcfiles[] = { ".bashrc", ".profile", ".zshrc", ".bash_profile", NULL };
    for (int fi = 0; rcfiles[fi]; fi++) {
        char path[512];
        snprintf(path, sizeof(path), "%s/%s", home, rcfiles[fi]);
        FILE *f = fopen(path, "r");
        if (!f) continue;
        char line[512];
        while (fgets(line, sizeof(line), f)) {
            /* Procura: export ELLIOT_AI_KEY=, GEMINI_API_KEY=, GROQ_API_KEY=, AI_KEY= */
            const char *needle = "ELLIOT_AI_KEY=";
            char *p = strstr(line, needle);
            if (!p) { needle = "GEMINI_API_KEY="; p = strstr(line, needle); }
            if (!p) { needle = "GROQ_API_KEY=";   p = strstr(line, needle); }
            if (!p) { needle = "AI_KEY=";          p = strstr(line, needle); }
            if (!p) continue;
            p += strlen(needle);
            /* Remove aspas simples ou duplas */
            if (*p == '\'' || *p == '"') p++;
            int j = 0;
            while (*p && *p != '\'' && *p != '"' && *p != '\n' && *p != '\r' && j < 255)
                g_gemini_key_buf[j++] = *p++;
            g_gemini_key_buf[j] = '\0';
            if (j > 8) {
                fclose(f);
                /* Exporta para o processo atual para próximas chamadas */
                setenv("GEMINI_API_KEY", g_gemini_key_buf, 1);
                return g_gemini_key_buf;
            }
            g_gemini_key_buf[0] = '\0';
        }
        fclose(f);
    }
    return NULL;
}

// Persiste em ~/.elliotai/history.json
// ============================================================================
#define MAX_HIST_TURNS 20
#define MAX_HIST_MSG   16384

typedef struct {
    char role[16];
    char content[MAX_HIST_MSG];
} HistMsg;

static HistMsg ai_history[MAX_HIST_TURNS * 2];
static int     ai_history_count = 0;
static char    ai_hist_path[512] = "";

// ============================================================================
// SANITIZAR RESPOSTA — remove nomes de provedores (como elliotai.py fazia)
// ============================================================================
static void sanitize_response(char *resp) {
    const char *banned[] = {
        "openrouter.ai","openai.com","api.openai","api.openrouter",
        "generativelanguage.googleapis.com","googleapis.com",
        "google.com/ai","ai.google.dev",
        NULL
    };
    size_t rlen = strlen(resp);
    if (rlen > 32768) return;
    char lower[32768];
    for (size_t k = 0; k <= rlen; k++) lower[k] = tolower((unsigned char)resp[k]);
    for (int i = 0; banned[i]; i++) {
        size_t blen = strlen(banned[i]);
        size_t rlen2 = strlen(lower);
        char *found = lower; char *p;
        while ((p = strstr(found, banned[i])) != NULL) {
            size_t off = p - lower;
            const char *repl = "[redacted]"; size_t rpl = strlen(repl);
            size_t tail = rlen2 - off - blen;
            memmove(resp+off+rpl,  resp+off+blen,  tail+1);
            memmove(lower+off+rpl, lower+off+blen, tail+1);
            memcpy(resp+off,  repl, rpl);
            memcpy(lower+off, repl, rpl);
            rlen2 = rlen2 - blen + rpl;
            found = lower + off + rpl;
        }
    }
}

// ============================================================================
// EXTRAI TEXTO DA RESPOSTA GEMINI
// Formato: {"candidates":[{"content":{"parts":[{"text":"..."}]}}]}
// ============================================================================
static int extract_content(const char *json, char *out, size_t out_size) {
    /* Tenta extrair "text": "..." da resposta Gemini */
    const char *p = strstr(json, "\"text\":");
    if (p) {
        p += strlen("\"text\":"); while (*p==' ') p++;
        if (*p == '"') {
            p++; size_t i=0;
            while (*p && i+1 < out_size) {
                if (*p=='\\' && *(p+1)) {
                    p++;
                    if      (*p=='n')  { out[i++]='\n'; }
                    else if (*p=='r')  { out[i++]='\r'; }
                    else if (*p=='t')  { out[i++]='\t'; }
                    else if (*p=='"')  { out[i++]='"';  }
                    else if (*p=='\\') { out[i++]='\\'; }
                    else if (*p=='/')  { out[i++]='/';  }
                    else if (*p=='u' && *(p+1) && *(p+2) && *(p+3) && *(p+4)) {
                        /* Decodifica \uXXXX — converte os mais comuns para ASCII */
                        char hex[5]={p[1],p[2],p[3],p[4],0};
                        unsigned int codepoint = (unsigned int)strtol(hex, NULL, 16);
                        p += 4; /* avança os 4 dígitos hex */
                        /* Converte codepoints ASCII (0x00–0x7E) diretamente */
                        if (codepoint < 0x80 && codepoint > 0) {
                            out[i++] = (char)codepoint;
                        }
                        /* Codepoints UTF-8 de 2 bytes (0x80–0x7FF) */
                        else if (codepoint < 0x800) {
                            if (i+2 < out_size) {
                                out[i++] = (char)(0xC0 | (codepoint >> 6));
                                out[i++] = (char)(0x80 | (codepoint & 0x3F));
                            }
                        }
                        /* Codepoints maiores: mantém como \uXXXX */
                        else {
                            if (i+6 < out_size) {
                                out[i++]='\\'; out[i++]='u';
                                out[i++]=hex[0]; out[i++]=hex[1];
                                out[i++]=hex[2]; out[i++]=hex[3];
                            }
                        }
                    } else { out[i++]=*p; }
                    p++;
                } else if (*p=='"') { break; }
                else { out[i++]=*p++; }
            }
            out[i]='\0';
            if (i>0) return 1;
        }
    }
    /* Fallback: extrai mensagem de erro da Gemini {"error":{"message":"..."}} */
    const char *ep = strstr(json, "\"message\":");
    if (ep) {
        ep += strlen("\"message\":"); while(*ep==' ') ep++;
        if (*ep=='"') {
            ep++; size_t ei=0; char errmsg[512]={0};
            while (*ep&&*ep!='"'&&ei<510) {
                if(*ep=='\\'&&*(ep+1)){ep++;errmsg[ei++]=*ep++;}
                else errmsg[ei++]=*ep++;
            }
            errmsg[ei]='\0';
            snprintf(out, out_size, "❌ Erro Gemini: %s", errmsg);
            return strlen(out)>0 ? 1 : 0;
        }
    }
    return 0;
}

// ============================================================================
// GEMINI AI — chamada HTTP nativa via libcurl
// API: https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent
// Chave: env GEMINI_API_KEY  (ou AI_KEY como fallback)
// ============================================================================
// Monta o payload Gemini no formato correto incluindo histórico
static void gemini_build_payload(const char *system_prompt, const char *user_msg,
                                  int max_tokens, char *out, size_t out_size) {
    /* Gemini usa:
     * { "system_instruction": {"parts":[{"text":"..."}]},
     *   "contents": [{"role":"user","parts":[{"text":"..."}]}, ...],
     *   "generationConfig": {"maxOutputTokens": N, "temperature": 0.2}
     * }
     * Histórico: role "user" e "model" (não "assistant") */
    char esc_sys[8192]={0};
    json_escape(system_prompt, esc_sys, sizeof(esc_sys));

    int w = snprintf(out, out_size,
        "{\"contents\":[{\"role\":\"user\",\"parts\":[{\"text\":\"%s\"}]},{\"role\":\"model\",\"parts\":[{\"text\":\"Entendido.\"}]},", esc_sys);

    /* Histórico — converte "assistant" → "model" para Gemini */
    for (int i=0; i<ai_history_count && (size_t)w < out_size-512; i++) {
        char esc_c[MAX_HIST_MSG*2]={0};
        json_escape(ai_history[i].content, esc_c, sizeof(esc_c));
        const char *role = strcmp(ai_history[i].role,"assistant")==0 ? "model" : "user";
        w += snprintf(out+w, out_size-w,
            "{\"role\":\"%s\",\"parts\":[{\"text\":\"%s\"}]},", role, esc_c);
    }

    /* Mensagem atual do usuário */
    char esc_usr[8192]={0};
    json_escape(user_msg, esc_usr, sizeof(esc_usr));
    snprintf(out+w, out_size-w,
        "{\"role\":\"user\",\"parts\":[{\"text\":\"%s\"}]}],"
        "\"generationConfig\":{\"maxOutputTokens\":%d,\"temperature\":0.2}}",
        esc_usr, max_tokens);
}

// ── tgpt provider config ──────────────────────────────────────────────────
// Provider padrão: pollinations (sem API key)
// Pode ser sobrescrito via env AI_TGPT_PROVIDER ou ai.add()
static char g_tgpt_provider[64] = "sky";
static char g_tgpt_model[128]   = "";   // vazio = padrão do provider
static int  g_ai_raw_mode       = 0;    // 1 = ms -A: sem streaming, sem header, sem timer

// Escapa aspas simples para uso seguro em shell
static void shell_escape_sq(const char *in, char *out, size_t sz) {
    size_t j = 0;
    for (size_t i = 0; in[i] && j+4 < sz; i++) {
        if (in[i] == '\'') {
            // ' → '\''
            if (j+4 >= sz) break;
            out[j++] = '\''; out[j++] = '\\'; out[j++] = '\''; out[j++] = '\'';
        } else {
            out[j++] = in[i];
        }
    }
    out[j] = '\0';
}



/* ── json_get: extrai campo de JSON simples ──────────────────────────────── */
static char *json_get_field(const char *json, const char *field, char *val, size_t val_sz) {
    char needle[128];
    snprintf(needle, sizeof(needle), "\"%s\"", field);
    const char *p = strstr(json, needle);
    if (!p) return NULL;
    p += strlen(needle);
    while (*p==' '||*p==':') p++;
    if (*p=='"') {
        p++;
        size_t i=0;
        while (*p&&*p!='"'&&i+2<val_sz) { if(*p=='\\'&&*(p+1)){p++;} val[i++]=*p++; }
        val[i]='\0';
    } else {
        size_t i=0;
        while (*p&&*p!=','&&*p!='}'&&*p!=']'&&i+1<val_sz) val[i++]=*p++;
        val[i]='\0';
    }
    return val;
}

/* ── do_curl: executa curl via popen, escreve resposta em out_buf ─────────── */
static int do_curl_req(const char *url, const char *headers[], int hdr_count,
                       const char *body, char *out_buf, size_t out_sz) {
    char curl_bin[256] = "curl";
    {
        FILE *wp = popen("command -v curl 2>/dev/null", "r");
        if (wp) {
            if (fgets(curl_bin,sizeof(curl_bin),wp)) {
                size_t l=strlen(curl_bin);
                while(l>0&&(curl_bin[l-1]=='\n'||curl_bin[l-1]=='\r')) curl_bin[--l]='\0';
            }
            pclose(wp);
        }
        if (!curl_bin[0]) strncpy(curl_bin,"curl",sizeof(curl_bin)-1);
    }

    /* Escreve body em arquivo temp */
    char tmpf[256]={0};
    if (body && body[0]) {
        snprintf(tmpf,sizeof(tmpf),"/data/data/com.termux/files/usr/tmp/elliot_req_%d.json",(int)getpid());
        FILE *tf=fopen(tmpf,"w");
        if (tf){ fputs(body,tf); fclose(tf); }
    }

    /* Monta comando curl */
    size_t cmd_sz = 65536;
    char *cmd = malloc(cmd_sz);
    if (!cmd) { if(tmpf[0]) remove(tmpf); return 0; }
    size_t p=0;
    p += snprintf(cmd+p,cmd_sz-p,"'%s' -sS --max-time 60 ",curl_bin);
    for (int i=0;i<hdr_count;i++)
        p += snprintf(cmd+p,cmd_sz-p,"-H '%s' ",headers[i]);
    if (tmpf[0])
        p += snprintf(cmd+p,cmd_sz-p,"-X POST --data-binary @'%s' ",tmpf);
    p += snprintf(cmd+p,cmd_sz-p,"'%s' 2>/dev/null",url);

    FILE *fp = popen(cmd, "r");
    free(cmd);
    if (!fp) { if(tmpf[0]) remove(tmpf); return 0; }

    size_t total=0; int c;
    while ((c=fgetc(fp))!=EOF && total<out_sz-1)
        out_buf[total++]=(char)c;
    out_buf[total]='\0';
    pclose(fp);
    if (tmpf[0]) remove(tmpf);
    return (int)total;
}

/* ── Extrai texto de resposta JSON e imprime se não estiver em raw mode ───── */
static int extract_and_print(const char *raw, const char *field,
                              char *out_buf, size_t out_sz, const char *err_prefix) {
    const char *p = strstr(raw, field);
    if (!p) {
        char msg[512]={0};
        const char *ep = strstr(raw,"\"error\"");
        if (ep) json_get_field(ep,"message",msg,sizeof(msg));
        snprintf(out_buf,out_sz,"❌ %s: %s", err_prefix, msg[0]?msg:raw);
        return 0;
    }
    p += strlen(field);
    while (*p==' '||*p==':') p++;
    if (*p=='"') p++;
    size_t i=0;
    while (*p && i+2<out_sz) {
        if (*p=='\\'&&*(p+1)=='n')  { out_buf[i++]='\n'; p+=2; continue; }
        if (*p=='\\'&&*(p+1)=='t')  { out_buf[i++]='\t'; p+=2; continue; }
        if (*p=='\\'&&*(p+1)=='"')  { out_buf[i++]='"';  p+=2; continue; }
        if (*p=='\\'&&*(p+1)=='\\') { out_buf[i++]='\\'; p+=2; continue; }
        if (*p=='"') break;
        out_buf[i++]=*p++;
    }
    out_buf[i]='\0';
    if (!g_ai_raw_mode && i>0) { printf("%s\033[0m\n",out_buf); fflush(stdout); }
    return i>0 ? 1 : 0;
}

/* ── GEMINI ─────────────────────────────────────────────────────────────── */
static int ai_gemini_ask(const char *api_key, const char *model,
                         const char *system_prompt, const char *user_prompt,
                         char *out_buf, size_t out_sz, int max_tokens) {
    const char *mdl = (model&&model[0]) ? model : "gemini-2.5-flash";
    size_t slen = system_prompt?strlen(system_prompt):0;
    size_t ulen = strlen(user_prompt);
    size_t jsz  = (slen+ulen)*4+4096;

    char *jesc_sys = malloc(jsz);
    char *jesc_usr = malloc(jsz);
    char *body     = malloc(jsz+131072);
    if (!jesc_sys||!jesc_usr||!body) {
        free(jesc_sys);free(jesc_usr);free(body);
        snprintf(out_buf,out_sz,"❌ sem memória"); return 0;
    }
    /* Usa json_escape existente: void json_escape(src,dst,size) */
    json_escape(system_prompt?system_prompt:"", jesc_sys, jsz);
    json_escape(user_prompt, jesc_usr, jsz);

    /* Histórico como turns */
    char *hist_json = calloc(1,131072);
    size_t hj=0;
    if (hist_json) {
        int hs = ai_history_count>8 ? ai_history_count-8 : 0;
        for (int i=hs;i<ai_history_count;i++) {
            size_t hl = strlen(ai_history[i].content)*4+64;
            char *eh  = malloc(hl);
            if (!eh) break;
            json_escape(ai_history[i].content,eh,hl);
            const char *role = strcmp(ai_history[i].role,"assistant")==0?"model":"user";
            hj += snprintf(hist_json+hj,131072-hj,
                "{\"role\":\"%s\",\"parts\":[{\"text\":\"%s\"}]},",role,eh);
            free(eh);
        }
    }

    snprintf(body,jsz+131072,
        "{"
          "\"contents\":[{\"role\":\"user\",\"parts\":[{\"text\":\"%s\"}]},{\"role\":\"model\",\"parts\":[{\"text\":\"Entendido.\"}]},%s{\"role\":\"user\",\"parts\":[{\"text\":\"%s\"}]}],"
          "\"generationConfig\":{\"maxOutputTokens\":%d,\"temperature\":0.7}"
        "}",
        jesc_sys, hist_json?hist_json:"", jesc_usr,
        max_tokens>0?max_tokens:2048);
    free(jesc_sys);free(jesc_usr);free(hist_json);

    char url[512];
    snprintf(url,sizeof(url),
        "https://generativelanguage.googleapis.com/v1/models/%s:generateContent?key=%s",
        mdl,api_key);

    const char *hdrs[]={"Content-Type: application/json","Accept: application/json"};
    char *raw = malloc(1024*1024);
    if (!raw) { free(body); snprintf(out_buf,out_sz,"❌ sem memória"); return 0; }
    raw[0]='\0';

    do_curl_req(url,hdrs,2,body,raw,1024*1024);
    free(body);

    int r = extract_and_print(raw,"\"text\"",out_buf,out_sz,"Gemini");
    free(raw);
    return r;
}

/* ── OPENAI-COMPAT (Groq, OpenAI, DeepSeek) ─────────────────────────────── */
static int ai_openai_compat_ask(const char *api_key, const char *base_url,
                                const char *model, const char *system_prompt,
                                const char *user_prompt, char *out_buf, size_t out_sz,
                                int max_tokens) {
    size_t slen = system_prompt?strlen(system_prompt):0;
    size_t ulen = strlen(user_prompt);
    size_t jsz  = (slen+ulen)*4+4096;

    char *jesc_sys = malloc(jsz);
    char *jesc_usr = malloc(jsz);
    char *body     = malloc(jsz+131072);
    if (!jesc_sys||!jesc_usr||!body) {
        free(jesc_sys);free(jesc_usr);free(body);
        snprintf(out_buf,out_sz,"❌ sem memória"); return 0;
    }
    json_escape(system_prompt?system_prompt:"",jesc_sys,jsz);
    json_escape(user_prompt,jesc_usr,jsz);

    /* Messages array com histórico */
    char *msgs = calloc(1,131072);
    size_t mp=0;
    if (msgs) {
        if (jesc_sys[0])
            mp += snprintf(msgs+mp,131072-mp,
                "{\"role\":\"system\",\"content\":\"%s\"},",jesc_sys);
        int hs=ai_history_count>8?ai_history_count-8:0;
        for (int i=hs;i<ai_history_count;i++) {
            size_t hl=strlen(ai_history[i].content)*4+64;
            char *eh=malloc(hl);
            if (!eh) break;
            json_escape(ai_history[i].content,eh,hl);
            mp += snprintf(msgs+mp,131072-mp,
                "{\"role\":\"%s\",\"content\":\"%s\"},",ai_history[i].role,eh);
            free(eh);
        }
        mp += snprintf(msgs+mp,131072-mp,
            "{\"role\":\"user\",\"content\":\"%s\"}",jesc_usr);
    }

    snprintf(body,jsz+131072,
        "{\"model\":\"%s\",\"messages\":[%s],"
        "\"max_tokens\":%d,\"temperature\":0.7,\"stream\":false}",
        model, msgs?msgs:"", max_tokens>0?max_tokens:2048);
    free(jesc_sys);free(jesc_usr);free(msgs);

    char auth_hdr[512];
    snprintf(auth_hdr,sizeof(auth_hdr),"Authorization: Bearer %s",api_key);
    const char *hdrs[]={"Content-Type: application/json",auth_hdr};

    char url[512];
    snprintf(url,sizeof(url),"%s/chat/completions",base_url);

    char *raw=malloc(1024*1024);
    if (!raw) { free(body); snprintf(out_buf,out_sz,"❌ sem memória"); return 0; }
    raw[0]='\0';

    do_curl_req(url,hdrs,2,body,raw,1024*1024);
    free(body);

    int r = extract_and_print(raw,"\"content\"",out_buf,out_sz,"API");
    free(raw);
    return r;
}

/* ── TGPT (providers gratuitos) ──────────────────────────────────────────── */
static int ai_tgpt_ask(const char *provider, const char *model,
                       const char *system_prompt, const char *user_prompt,
                       char *out_buf, size_t out_sz) {
    char tgpt_bin[512]={0};
    {
        FILE *wp=popen("command -v tgpt 2>/dev/null","r");
        if (wp) {
            if (fgets(tgpt_bin,sizeof(tgpt_bin),wp)) {
                size_t tl=strlen(tgpt_bin);
                while(tl>0&&(tgpt_bin[tl-1]=='\n'||tgpt_bin[tl-1]=='\r')) tgpt_bin[--tl]='\0';
            }
            pclose(wp);
        }
        if (!tgpt_bin[0]) {
            const char *try[]={
                "/data/data/com.termux/files/usr/bin/tgpt",
                "/data/data/com.termux/files/home/go/bin/tgpt",
                "/usr/local/bin/tgpt","/usr/bin/tgpt",NULL
            };
            for (int ti=0;try[ti];ti++)
                if (access(try[ti],X_OK)==0){ strncpy(tgpt_bin,try[ti],sizeof(tgpt_bin)-1); break; }
        }
    }
    if (!tgpt_bin[0]) {
        snprintf(out_buf,out_sz,"❌ tgpt não encontrado.\nInstale: pkg install tgpt");
        return 0;
    }

    /* Monta prompt */
    size_t plen=(system_prompt?strlen(system_prompt):0)+strlen(user_prompt)+8192;
    if (plen<32768) plen=32768;
    char *full=malloc(plen);
    if (!full){ snprintf(out_buf,out_sz,"❌ sem memória"); return 0; }
    size_t fp=0;
#define TA(s) do{size_t _n=strlen(s);if(fp+_n+1<plen){memcpy(full+fp,(s),_n);fp+=_n;full[fp]='\0';}}while(0)
    if(system_prompt&&system_prompt[0]){TA("[SYSTEM] ");TA(system_prompt);TA("\n\n");}
    int hs=ai_history_count>6?ai_history_count-6:0;
    for(int i=hs;i<ai_history_count;i++){
        const char *r=strcmp(ai_history[i].role,"assistant")==0?"CYN":"User";
        TA(r);TA(": ");TA(ai_history[i].content);TA("\n");
    }
    TA("User: ");TA(user_prompt);TA("\nCYN:");
#undef TA

    size_t esc_sz=fp*5+64;
    char *esc=malloc(esc_sz);
    if(!esc){free(full);snprintf(out_buf,out_sz,"❌ sem memória");return 0;}
    shell_escape_sq(full,esc,esc_sz);
    free(full);

    size_t cmd_sz=esc_sz+512;
    char *cmd=malloc(cmd_sz);
    if(!cmd){free(esc);snprintf(out_buf,out_sz,"❌ sem memória");return 0;}

    if (model&&model[0])
        snprintf(cmd,cmd_sz,"'%s' --provider '%s' --model '%s' --quiet '%s' 2>/dev/null",
            tgpt_bin,provider,model,esc);
    else
        snprintf(cmd,cmd_sz,"'%s' --provider '%s' --quiet '%s' 2>/dev/null",
            tgpt_bin,provider,esc);
    free(esc);

    FILE *fp2=popen(cmd,"r");
    free(cmd);
    if(!fp2){snprintf(out_buf,out_sz,"❌ Falha ao executar tgpt");return 0;}

    size_t total=0; int c;
    while((c=fgetc(fp2))!=EOF&&total<out_sz-1){
        out_buf[total++]=(char)c;
        if(!g_ai_raw_mode){fputc(c,stdout);fflush(stdout);}
    }
    out_buf[total]='\0';
    pclose(fp2);

    if(!g_ai_raw_mode&&total>0){printf("\033[0m\n");fflush(stdout);}
    while(total>0&&(out_buf[total-1]=='\n'||out_buf[total-1]=='\r')) out_buf[--total]='\0';

    if(total==0){
        snprintf(out_buf,out_sz,
            "❌ %s não retornou resposta.\n"
            "Tente: ai.provider('sky') ou ai.provider('pollinations')",provider);
        return 0;
    }
    return 1;
}

/* ── DISPATCHER PRINCIPAL ───────────────────────────────────────────────── */
static int ai_http_ask(const char *model, const char *system_prompt,
                       const char *user_prompt, char *out_buf, size_t out_sz,
                       int max_tokens) {
    const char *env_prov = getenv("AI_TGPT_PROVIDER");
    const char *provider = (env_prov && env_prov[0]) ? env_prov : g_tgpt_provider;
    const char *use_model = (model && model[0]) ? model : (g_tgpt_model[0] ? g_tgpt_model : NULL);

    /* Carrega key */
    const char *api_key = getenv("ELLIOT_AI_KEY");
    if (!api_key||!api_key[0]) api_key = getenv("GEMINI_API_KEY");
    if (!api_key||!api_key[0]) api_key = getenv("GROQ_API_KEY");
    if (!api_key||!api_key[0]) api_key = getenv("OPENAI_API_KEY");
    if (!api_key||!api_key[0]) api_key = getenv("DEEPSEEK_API_KEY");
    if (!api_key||!api_key[0]) api_key = getenv("AI_KEY");

    /* Seleciona system prompt — usa strcmp para evitar comparacao de ponteiro */
    static const char *_kw[] = {
        "net.","sys.","fs.","ai.","crypto.","db.","mod.","pent.","web.","exploit.",
        "ms -","ms --","lpm ","lmod.","scan","xss","sqli","lfi","rce","ssrf","ssti","prototype","pollution",
        "payload","shell","reverse","bind","inject","flood","fuzzing",
        "function","require","local ","net.tcp","sys.sh","net.listen",
        "nexus","recon","portscan","webcheck","hashcrack","learn.lua",
        "script","hash","wordlist","headers","fingerprint","banner",
        NULL
    };
    const char *sys;
    if (!system_prompt || !system_prompt[0]) {
        sys = CYN_SYSTEM_PROMPT_CORE;
    } else if (strcmp(system_prompt, CYN_SYSTEM_PROMPT) == 0 ||
               strcmp(system_prompt, CYN_SYSTEM_PROMPT_CORE) == 0) {
        /* Um dos prompts padrão — decide pelo conteúdo do user_prompt */
        sys = CYN_SYSTEM_PROMPT_CORE;
        for (int i=0; _kw[i]; i++)
            if (strstr(user_prompt, _kw[i])) { sys = CYN_SYSTEM_PROMPT; break; }
    } else {
        sys = system_prompt; /* prompt customizado (code, agent, etc.) */
    }

    /* ── GEMINI ── */
    if (strcmp(provider,"gemini")==0) {
        if (!api_key||strlen(api_key)<8) {
            snprintf(out_buf,out_sz,"❌ Gemini requer API key.\nConfigure: ai.key('AIza...')"); return 0;
        }
        const char *mdl = use_model ? use_model : "gemini-2.5-flash";
        return ai_gemini_ask(api_key, mdl, sys, user_prompt, out_buf, out_sz, max_tokens);
    }

    /* ── GROQ ── */
    if (strcmp(provider,"groq")==0) {
        if (!api_key||strlen(api_key)<8) {
            snprintf(out_buf,out_sz,"❌ Groq requer API key.\nConfigure: ai.key('gsk_...')"); return 0;
        }
        const char *mdl = use_model ? use_model : "llama-3.3-70b-versatile";
        return ai_openai_compat_ask(api_key,
            "https://api.groq.com/openai/v1",
            mdl, sys, user_prompt, out_buf, out_sz, max_tokens);
    }

    /* ── OPENAI ── */
    if (strcmp(provider,"openai")==0) {
        if (!api_key||strlen(api_key)<8) {
            snprintf(out_buf,out_sz,"❌ OpenAI requer API key.\nConfigure: ai.key('sk-...')"); return 0;
        }
        const char *mdl = use_model ? use_model : "gpt-4o-mini";
        return ai_openai_compat_ask(api_key,
            "https://api.openai.com/v1",
            mdl, sys, user_prompt, out_buf, out_sz, max_tokens);
    }

    /* ── DEEPSEEK ── */
    if (strcmp(provider,"deepseek")==0) {
        if (!api_key||strlen(api_key)<8) {
            snprintf(out_buf,out_sz,"❌ DeepSeek requer API key.\nConfigure: ai.key('sk-...')"); return 0;
        }
        const char *mdl = use_model ? use_model : "deepseek-chat";
        return ai_openai_compat_ask(api_key,
            "https://api.deepseek.com/v1",
            mdl, sys, user_prompt, out_buf, out_sz, max_tokens);
    }

    /* ── ANTHROPIC (Claude) ── */
    if (strcmp(provider,"anthropic")==0) {
        if (!api_key||strlen(api_key)<8) {
            snprintf(out_buf,out_sz,"❌ Anthropic requer API key.\nConfigure: ai.key('sk-ant-...')"); return 0;
        }
        /* Anthropic usa OpenAI-compat via header especial */
        char auth_hdr[256], ver_hdr[64];
        snprintf(auth_hdr,sizeof(auth_hdr),"x-api-key: %s",api_key);
        snprintf(ver_hdr,sizeof(ver_hdr),"anthropic-version: 2023-06-01");
        const char *mdl = use_model ? use_model : "claude-haiku-4-5-20251001";
        /* Reutiliza openai_compat com URL Anthropic */
        return ai_openai_compat_ask(api_key,
            "https://api.anthropic.com/v1",
            mdl, sys, user_prompt, out_buf, out_sz, max_tokens);
    }

    /* ── TGPT (sky, pollinations, isou, ollama, koboldai) ── */
    return ai_tgpt_ask(provider, use_model, sys, user_prompt, out_buf, out_sz);
}
/* ── histórico declarado acima de gemini_build_payload ── */

static void hist_db_init() {
    const char *home = getenv("HOME");
    if (!home) home = "/data/data/com.termux/files/home";
    /* Garante que o diretório existe antes de qualquer leitura/escrita */
    char dir[512];
    snprintf(dir, sizeof(dir), "%s/.elliotai", home);
    mkdir(dir, 0700);
    snprintf(ai_hist_path, sizeof(ai_hist_path), "%s/.elliotai/history.json", home);
}

// Adiciona mensagem ao histórico em memória
static void hist_add(const char *role, const char *content) {
    // Se lotou, descarta o par mais antigo (índices 0 e 1)
    if (ai_history_count >= MAX_HIST_TURNS * 2) {
        int shift = 2;
        memmove(ai_history, ai_history + shift,
                (ai_history_count - shift) * sizeof(HistMsg));
        ai_history_count -= shift;
    }
    strncpy(ai_history[ai_history_count].role,    role,    15);
    strncpy(ai_history[ai_history_count].content, content, MAX_HIST_MSG - 1);
    ai_history[ai_history_count].role[15]             = '\0';
    ai_history[ai_history_count].content[MAX_HIST_MSG-1] = '\0';
    ai_history_count++;
}

// Salva histórico em disco
static void hist_save() {
    if (!ai_hist_path[0]) hist_db_init();
    FILE *f = fopen(ai_hist_path, "w");
    if (!f) return;
    fprintf(f, "[\n");
    for (int i = 0; i < ai_history_count; i++) {
        // Escapa o conteúdo para JSON ao salvar
        char esc[MAX_HIST_MSG * 2];
        json_escape(ai_history[i].content, esc, sizeof(esc));
        fprintf(f, "  {\"role\":\"%s\",\"content\":\"%s\"}%s\n",
            ai_history[i].role, esc,
            i < ai_history_count - 1 ? "," : "");
    }
    fprintf(f, "]\n");
    fclose(f);
}

// Carrega histórico do disco
static void hist_load() {
    if (!ai_hist_path[0]) hist_db_init();
    FILE *f = fopen(ai_hist_path, "r");
    if (!f) return;
    char buf[131072] = {0};
    fread(buf, 1, sizeof(buf)-1, f);
    fclose(f);
    ai_history_count = 0;
    char *p = buf;
    while (ai_history_count < MAX_HIST_TURNS * 2) {
        char *rp = strstr(p, "\"role\":"); if (!rp) break;
        rp += 7; while (*rp==' ') rp++;
        if (*rp != '"') { break; } rp++;
        int j = 0;
        while (*rp && *rp != '"' && j < 15) ai_history[ai_history_count].role[j++] = *rp++;
        ai_history[ai_history_count].role[j] = '\0'; if (*rp=='"') rp++;
        char *cp = strstr(rp, "\"content\":"); if (!cp) break;
        cp += 10; while (*cp==' ') cp++;
        if (*cp != '"') { break; } cp++;
        j = 0;
        while (*cp && j < MAX_HIST_MSG - 1) {
            if (*cp == '\\' && *(cp+1)) {
                cp++;
                if (*cp=='n')       ai_history[ai_history_count].content[j++]='\n';
                else if (*cp=='t')  ai_history[ai_history_count].content[j++]='\t';
                else if (*cp=='"')  ai_history[ai_history_count].content[j++]='"';
                else if (*cp=='\\') ai_history[ai_history_count].content[j++]='\\';
                else                ai_history[ai_history_count].content[j++]=*cp;
                cp++;
            } else if (*cp == '"') { cp++; break; }
            else { ai_history[ai_history_count].content[j++] = *cp++; }
        }
        ai_history[ai_history_count].content[j] = '\0';
        ai_history_count++;
        p = cp;
    }
}

