    printf("\033[1;36m║  Modelos Gemini Disponíveis                ║\033[0m\n");
    printf("\033[1;36m╚════════════════════════════════════════════╝\033[0m\n\n");
    int found = 0;
    for (int i = 0; GEMINI_MODELS[i][0]; i++) {
        if (query && strlen(query) > 0) {
            char name_lo[64]={0}, q_lo[64]={0};
            for(int k=0;GEMINI_MODELS[i][0][k]&&k<63;k++) name_lo[k]=tolower((unsigned char)GEMINI_MODELS[i][0][k]);
            for(int k=0;GEMINI_MODELS[i][1][k]&&k<63;k++) { char c=tolower((unsigned char)GEMINI_MODELS[i][1][k]); if(k<63) name_lo[63]=0; (void)c; }
            for(int k=0;query[k]&&k<63;k++) q_lo[k]=tolower((unsigned char)query[k]);
            if (!strstr(name_lo,q_lo) && !strstr(GEMINI_MODELS[i][1],query)) continue;
        }
        printf("  \033[1;32m%-16s\033[0m %s\n", GEMINI_MODELS[i][0], GEMINI_MODELS[i][1]);
        found++;
    }
    if (!found) printf("\033[1;31m  Nenhum modelo encontrado para '%s'\033[0m\n", query?query:"");
    printf("\n\033[0;90m  Use: ai.add('gemini-2.0-flash','meu-flash')\033[0m\n");
    printf("\033[0;90m  Ou defina direto: ai.main('flash')\033[0m\n\n");
    return found;
}

// ============================================================================
// AI.ADD — adicionar modelo
// ============================================================================
static int l_ai_add(lua_State *L) {
    const char *model_url = luaL_checkstring(L, 1);
    const char *name      = luaL_checkstring(L, 2);
    if (ai_model_count >= MAX_AI_MODELS) {
        printf("\033[1;31m❌ Máximo de %d modelos!\033[0m\n", MAX_AI_MODELS);
        lua_pushboolean(L, 0); return 1;
    }
    for (int i = 0; i < ai_model_count; i++) {
        if (strcmp(ai_models[i].name, name) == 0) {
            printf("\033[1;31m❌ Modelo '%s' já existe!\033[0m\n", name);
            lua_pushboolean(L, 0); return 1;
        }
    }
    strncpy(ai_models[ai_model_count].name,  name,      63);
    strncpy(ai_models[ai_model_count].model, model_url, 255);
    ai_model_count++;
    ai_db_save();
    printf("\033[1;32m✅ Modelo adicionado: %s\033[0m\n", name);
    lua_pushboolean(L, 1); return 1;
}

// ============================================================================
// AI.REMOVE — remove modelo salvo pelo apelido
// ============================================================================
static int l_ai_remove(lua_State *L) {
    const char *name = luaL_checkstring(L, 1);
    int found = -1;
    for (int i = 0; i < ai_model_count; i++) {
        if (strcmp(ai_models[i].name, name) == 0) { found = i; break; }
    }
    if (found < 0) {
        printf("\033[1;31m❌ Modelo '%s' não encontrado!\033[0m\n", name);
        lua_pushboolean(L, 0); return 1;
    }
    // Desloca os modelos após o removido
    for (int i = found; i < ai_model_count - 1; i++) {
        ai_models[i] = ai_models[i + 1];
    }
    ai_model_count--;
    // Se era o padrão, limpa o padrão
    if (strcmp(default_model_name, name) == 0) {
        default_model_name[0] = '\0';
        active_model_url[0]   = '\0';
        printf("\033[1;33m⚠  Era o modelo padrão — use ai.main() para definir outro.\033[0m\n");
    }
    ai_db_save();
    printf("\033[1;32m✅ Modelo removido: %s\033[0m\n", name);
    lua_pushboolean(L, 1); return 1;
}
static int l_ai_main(lua_State *L) {
    const char *model_name = luaL_checkstring(L, 1);
    if(strlen(model_name) == 0) {
        printf("\033[1;31m❌ Nome inválido!\033[0m\n");
        lua_pushboolean(L, 0); return 1;
    }
    /* 1. Busca por apelido cadastrado via ai.add() */
    for (int i = 0; i < ai_model_count; i++) {
        if (strcmp(ai_models[i].name, model_name) == 0) {
            strncpy(default_model_name, model_name, sizeof(default_model_name)-1);
            default_model_name[sizeof(default_model_name)-1] = '\0';
            strncpy(active_model_url, ai_models[i].model, 255);
            ai_db_save();
            printf("\033[1;32m✅ Modelo: %s\033[0m\n\033[0;90m   %s\033[0m\n\n", model_name, ai_models[i].model);
            lua_pushboolean(L, 1); return 1;
        }
    }
    /* 2. Aceita nome direto do modelo (ex: "gemini-2.5-flash") sem ai.add() */
    if (strstr(model_name,"gemini")||strstr(model_name,"gpt")||strstr(model_name,"llama")||
        strstr(model_name,"deepseek")||strstr(model_name,"mistral")||strstr(model_name,"gemma")||
        strstr(model_name,"claude")||strstr(model_name,"flash")||strstr(model_name,"pro")) {
        strncpy(default_model_name, model_name, sizeof(default_model_name)-1);
        default_model_name[sizeof(default_model_name)-1] = '\0';
        strncpy(active_model_url, model_name, 255);
        ai_config_save();
        printf("\033[1;32m✅ Modelo: %s\033[0m\n", model_name);
        lua_pushboolean(L, 1); return 1;
    }
    printf("\033[1;31m❌ Modelo '%s' não reconhecido!\033[0m\n", model_name);
    printf("\033[0;90m  Exemplos: ai.main('gemini-2.5-flash')  ai.main('gemini-2.0-flash-lite')\033[0m\n");
    printf("\033[0;90m  Lista:    ai.model('gemini')  ou  ai.list('local')\033[0m\n\n");
    lua_pushboolean(L, 0); return 1;
}

// ============================================================================
// AI.LIST — lista modelos Gemini
//   ai.list()           → consulta API Gemini ao vivo (padrão)
//   ai.list('local')    → modelos salvos localmente + lista builtin
//   ai.list('flash')    → filtra pelo nome na lista builtin
// ============================================================================
static int l_ai_list(lua_State *L) {
    const char *query = luaL_optstring(L, 1, NULL);

    /* chamada interna do ms.check — retorna silenciosamente */
    if (query && strcmp(query, "_quiet_check_") == 0) return 0;

    /* ai.list('local') — lista local salva */
    if (query && strcasecmp(query, "local") == 0) {
        printf("\n\033[1;36m╔════════════════════════════════════════════╗\033[0m\n");
        printf("\033[1;36m║  Modelos salvos localmente                 ║\033[0m\n");
        printf("\033[1;36m╚════════════════════════════════════════════╝\033[0m\n\n");
        if (ai_model_count == 0) {
            printf("\033[1;33m⚠️  Nenhum modelo salvo!\033[0m\n\n");
        } else {
            for (int i=0; i<ai_model_count; i++) {
                printf("  \033[1;32m%d. %s", i+1, ai_models[i].name);
                if (strcmp(ai_models[i].name, default_model_name)==0)
                    printf(" \033[1;33m(PADRÃO)\033[0m");
                else printf("\033[0m");
                printf("\n     \033[0;90m%s\033[0m\n\n", ai_models[i].model);
            }
        }
        printf("\033[1;33m── Builtin conhecidos ─────────────────────\033[0m\n");
        for (int i=0; GEMINI_MODELS[i][0]; i++)
            printf("  \033[1;32m%-16s\033[0m %s\n", GEMINI_MODELS[i][0], GEMINI_MODELS[i][1]);
        printf("\n\033[0;90m  ai.list() para ver modelos reais da API\033[0m\n\n");
        return 0;
    }

    /* ai.list() ou ai.list('online') — lista providers tgpt disponíveis */
    if (!query || strlen(query) == 0 || strcasecmp(query, "online") == 0) {
        printf("\n\033[1;35m╔══════════════════════════════════════════════════════════════╗\033[0m\n");
        printf("\033[1;35m║  CYN — Providers disponíveis via tgpt                        ║\033[0m\n");
        printf("\033[1;35m╚══════════════════════════════════════════════════════════════╝\033[0m\n\n");
        printf("  \033[0;90m── Gratuitos (sem key) ─────────────────────────────────────\033[0m\n");
        printf("  \033[1;32msky\033[0m            grátis, sem chave \033[0;90m(gpt-4.1-mini — melhor sem key)\033[0m\n");
        printf("  \033[1;32mpollinations\033[0m   grátis, sem chave \033[0;90m(openai-large, mistral, flux...)\033[0m\n");
        printf("  \033[1;32misou\033[0m           grátis, sem chave \033[0;90m(com busca web integrada)\033[0m\n");
        printf("  \033[1;32mollama\033[0m          local,  sem chave \033[0;90m(llama3, mistral, codellama...)\033[0m\n");
        printf("  \033[1;32mkoboldai\033[0m        local,  sem chave \033[0;90m(modelos de ficção/RP)\033[0m\n");
        printf("  \033[0;90m── Com API key ─────────────────────────────────────────────\033[0m\n");
        printf("  \033[1;32mgroq\033[0m           requer key \033[0;90m(llama-3.3-70b, mixtral — muito rápido)\033[0m\n");
        printf("  \033[1;32mgemini\033[0m         requer key \033[0;90m(gemini-2.5-flash, gemini-2.5-pro)\033[0m\n");
        printf("  \033[1;32mopenai\033[0m         requer key \033[0;90m(gpt-4o, gpt-4o-mini)\033[0m\n");
        printf("  \033[1;32mdeepseek\033[0m       requer key \033[0;90m(deepseek-chat, deepseek-reasoner)\033[0m\n\n");
        printf("  \033[0;90mUso:\033[0m\n");
        printf("  ai.provider('sky')                             \033[0;90m-- sem chave (recomendado)\033[0m\n");
        printf("  ai.provider('isou')                            \033[0;90m-- sem chave, tem busca web\033[0m\n");
        printf("  ai.provider('groq','llama-3.3-70b-versatile')  \033[0;90m-- requer ai.key()\033[0m\n");
        printf("  ai.provider('ollama','llama3')                 \033[0;90m-- local\033[0m\n\n");
        return 0;
    }

    /* ai.list('query') — filtra lista builtin por nome */
    if (query && strlen(query) > 0) {
        ai_list_gemini_models(query, 0);
        return 0;
    }

    return 0;
}

// ============================================================================
// AI.KEY — define ou mostra a chave Gemini sem precisar reinstalar
// ai.key()            → mostra chave atual (censurada)
// ai.key('AIza...')   → salva nova chave no ~/.bashrc e ativa imediatamente
// ============================================================================
// ── persistência de provider/model ─────────────────────────────────────────
// Salva em ~/.elliot_ai.cfg  (formato simples: provider=xxx\nmodel=yyy)
static void ai_config_save(void) {
    const char *home = getenv("HOME");
    if (!home) return;
    char path[512];
    snprintf(path, sizeof(path), "%s/.elliot_ai.cfg", home);
    FILE *f = fopen(path, "w");
    if (!f) return;
    fprintf(f, "provider=%s\n", g_tgpt_provider);
    fprintf(f, "model=%s\n",    g_tgpt_model);
    fclose(f);
}

static void ai_config_load(void) {
    const char *home = getenv("HOME");
    if (!home) return;
    char path[512];
    snprintf(path, sizeof(path), "%s/.elliot_ai.cfg", home);
    FILE *f = fopen(path, "r");
    if (!f) return;
    char line[256];
    while (fgets(line, sizeof(line), f)) {
        /* remove newline */
        int len = (int)strlen(line);
        while (len > 0 && (line[len-1]=='\n'||line[len-1]=='\r')) line[--len]='\0';
        if (strncmp(line, "provider=", 9)==0 && line[9]) {
            strncpy(g_tgpt_provider, line+9, sizeof(g_tgpt_provider)-1);
            g_tgpt_provider[sizeof(g_tgpt_provider)-1]='\0';
        } else if (strncmp(line, "model=", 6)==0) {
            strncpy(g_tgpt_model, line+6, sizeof(g_tgpt_model)-1);
            g_tgpt_model[sizeof(g_tgpt_model)-1]='\0';
        }
    }
    fclose(f);
}

// ai.provider([nome]) — mostra ou muda o provider tgpt
static int l_ai_provider(lua_State *L) {
    const char *p = luaL_optstring(L, 1, NULL);
    const char *m = luaL_optstring(L, 2, NULL); /* model opcional */
    if (!p) {
        /* mostra atual */
        const char *env_prov = getenv("AI_TGPT_PROVIDER");
        const char *cur = (env_prov && env_prov[0]) ? env_prov : g_tgpt_provider;
        printf("\033[1;36mProvider atual:\033[0m %s", cur);
        if (g_tgpt_model[0]) printf("  \033[0;90m(model: %s)\033[0m", g_tgpt_model);
        printf("\n");
        printf("\033[0;90mProviders disponíveis: sky · pollinations · isou · ollama · koboldai (sem key)\033[0m\n");
        printf("\033[0;90m                       groq · gemini · openai · deepseek (com key)\033[0m\n");
        lua_pushstring(L, cur);
        return 1;
    }
    strncpy(g_tgpt_provider, p, sizeof(g_tgpt_provider)-1);
    g_tgpt_provider[sizeof(g_tgpt_provider)-1] = '\0';
    if (m && m[0]) {
        strncpy(g_tgpt_model, m, sizeof(g_tgpt_model)-1);
        g_tgpt_model[sizeof(g_tgpt_model)-1] = '\0';
        printf("\033[1;32m✓ Provider: %s  Model: %s\033[0m\n", g_tgpt_provider, g_tgpt_model);
    } else {
        g_tgpt_model[0] = '\0';
        printf("\033[1;32m✓ Provider: %s\033[0m\n", g_tgpt_provider);
    }
    ai_config_save();   /* persiste no disco */
    lua_pushboolean(L, 1);
    return 1;
}

static int l_ai_key(lua_State *L) {
    const char *new_key = luaL_optstring(L, 1, NULL);

    if (!new_key || strlen(new_key) == 0) {
        /* Mostra chave atual censurada */
        const char *k = gemini_key_load();
        if (!k || strlen(k) < 4) {
            printf("\033[1;31m❌ Nenhuma chave configurada.\033[0m\n");
            printf("\033[0;90m💡 Com tgpt, chave só é necessária para: groq, gemini, deepseek, openai\033[0m\n");
            printf("\033[1;32m   Providers gratuitos: ai.provider('sky') · ai.provider('pollinations') · ai.provider('isou')\033[0m\n");
            printf("\033[1;33m   ai.key('sua-chave')  — define chave para providers que exigem\033[0m\n");
        } else {
            /* Mostra só os últimos 6 chars com prefixo correto */
            int klen = (int)strlen(k);
            const char *kpfx = "****";
            if (strncmp(k,"gsk_",4)==0) kpfx="gsk_";
            else if (strncmp(k,"AIza",4)==0) kpfx="AIza";
            else if (strncmp(k,"sk-",3)==0) kpfx="sk-";
            printf("\033[1;32m✅ Chave ativa: %s...%s\033[0m\n", kpfx, k + (klen > 6 ? klen-6 : 0));
        }
        return 0;
    }

    /* Valida formato básico */
    if (strlen(new_key) < 20) {
        printf("\033[1;31m❌ Chave inválida (muito curta). Obtenha em: https://aistudio.google.com/apikey\033[0m\n");
        return 0;
    }

    /* Salva no ~/.bashrc */
    const char *home = getenv("HOME");
    if (!home) home = "/data/data/com.termux/files/home";

    const char *rcfiles[] = { ".bashrc", ".profile", NULL };
    for (int i = 0; rcfiles[i]; i++) {
        char path[512];
        snprintf(path, sizeof(path), "%s/%s", home, rcfiles[i]);

        /* Lê o arquivo, remove linha antiga da chave */
        FILE *f = fopen(path, "r");
        char content[65536] = {0};
        if (f) { fread(content, 1, sizeof(content)-1, f); fclose(f); }

        /* Filtra linhas com qualquer variavel de chave conhecida */
        char filtered[65536] = {0};
        char *p = content; int fw = 0;
        while (*p) {
            char *nl = strchr(p, '\n');
            size_t llen = nl ? (size_t)(nl - p + 1) : strlen(p);
            if (!strstr(p, "GEMINI_API_KEY") && !strstr(p, "ELLIOT_AI_KEY") &&
                !strstr(p, "AI_KEY=") && !strstr(p, "GROQ_API_KEY") &&
                !strstr(p, "OPENAI_API_KEY") && !strstr(p, "DEEPSEEK_API_KEY")) {
                if (fw + (int)llen < 65530) { memcpy(filtered+fw, p, llen); fw += llen; }
            }
            p = nl ? nl+1 : p+strlen(p);
        }
        /* Salva como ELLIOT_AI_KEY (generica) e GEMINI_API_KEY (legado) */
        int wrote = snprintf(filtered+fw, sizeof(filtered)-fw,
            "\nexport ELLIOT_AI_KEY='%s'\nexport GEMINI_API_KEY='%s'\n", new_key, new_key);
        if (wrote > 0) fw += wrote;

        f = fopen(path, "w");
        if (f) { fwrite(filtered, 1, fw, f); fclose(f); }
    }

    /* Ativa na sessão atual para todos os providers */
    setenv("ELLIOT_AI_KEY",   new_key, 1);
    setenv("GEMINI_API_KEY",  new_key, 1);
    setenv("GROQ_API_KEY",    new_key, 1);
    setenv("OPENAI_API_KEY",  new_key, 1);
    setenv("DEEPSEEK_API_KEY",new_key, 1);
    g_gemini_key_buf[0] = '\0'; /* limpa cache para forçar reload */

    /* Mostra prefixo correto conforme o tipo da chave */
    const char *key_prefix = "****";
    if (strncmp(new_key, "gsk_", 4) == 0)       key_prefix = "gsk_";
    else if (strncmp(new_key, "AIza", 4) == 0)   key_prefix = "AIza";
    else if (strncmp(new_key, "sk-", 3) == 0)    key_prefix = "sk-";
    else if (strncmp(new_key, "Bearer ", 7) == 0) key_prefix = "Bearer";

    int klen = (int)strlen(new_key);
    printf("\033[1;32m✅ Chave salva e ativada: %s...%s\033[0m\n",
           key_prefix, new_key + (klen > 6 ? klen-6 : 0));
    printf("\033[0;90m   Salva em ~/.bashrc e ~/.profile  (ELLIOT_AI_KEY)\033[0m\n");
    lua_pushboolean(L, 1); return 1;
}

// ============================================================================
// AI.ASK — NÚCLEO CENTRAL — usa libcurl nativa, CYN system prompt, retry
// Portado integralmente do ModelClient + ElliotAI.ask() do elliotai.py
// Sem. Sem subprocess. Sem curl externo.
// ============================================================================
static int l_ai_ask(lua_State *L) {
    const char *prompt     = luaL_checkstring(L, 1);
    const char *model_arg  = luaL_optstring(L, 2, NULL);
    int         max_tokens = (int)luaL_optinteger(L, 3, 2047); // padrão 512, máx 8192

    // Resolve modelo
    const char *model_to_use = active_model_url;
    const char *display_name = strlen(default_model_name) ? default_model_name : "padrão";

    if (model_arg != NULL) {
        // Nome ou URL direta passada como argumento
        const char *found_url = NULL;
        for (int i = 0; i < ai_model_count; i++) {
            if (strcmp(ai_models[i].name, model_arg) == 0) {
                found_url    = ai_models[i].model;
                display_name = ai_models[i].name;
                break;
            }
        }
        model_to_use = found_url ? found_url : model_arg;
        if (!found_url) display_name = model_arg;
    }

    if (!g_ai_raw_mode) {
        printf("\n\033[1;35m[CYN]\033[0m \033[0;90m%s\033[0m\n", display_name);
    }
    /* Não imprime "processando..." — o streaming vai aparecer direto */
    if (!g_ai_raw_mode) {
        printf("\033[1;33m");  /* amarelo negrito — cor da resposta da CYN */
        fflush(stdout);
    }

    struct timeval _t0, _t1;
    gettimeofday(&_t0, NULL);

    char response[32768] = {0};
    /* ai_http_ask imprime via fputc durante streaming (silencioso em raw_mode) */
    /* Usa prompt compacto para conversas simples, completo para pedidos técnicos */
    static const char *_kw[] = {
        "net.","sys.","fs.","ai.","crypto.","db.","mod.","pent.","web.","exploit.",
        "ms -","ms --","lpm ","lmod.","scan","xss","sqli","lfi","rce","ssrf","ssti","prototype","pollution",
        "payload","shell","reverse","bind","exploit","inject","flood","fuzzing",
        "function","require","local ","net.tcp","sys.sh","net.listen","net.http",
        "nexus","recon","portscan","webcheck","hashcrack","learn.lua",
        "script","hash","wordlist","headers","fingerprint","banner",
        NULL
    };
    const char *_sys = CYN_SYSTEM_PROMPT_CORE;
    for (int _i = 0; _kw[_i]; _i++) {
        if (strstr(prompt, _kw[_i])) { _sys = CYN_SYSTEM_PROMPT; break; }
    }
    int ok = ai_http_ask(model_to_use, _sys, prompt, response, sizeof(response), max_tokens);

    gettimeofday(&_t1, NULL);
    double _elapsed = (_t1.tv_sec - _t0.tv_sec) + (_t1.tv_usec - _t0.tv_usec) / 1e6;

    if (ok && strlen(response) > 0) {
        hist_add("user",      prompt);
        hist_add("assistant", response);
        hist_save();
        if (g_ai_raw_mode) {
            /* raw: devolve string pura para o print() do Lua, sem decoração */
            g_ai_raw_mode = 0;
            lua_pushstring(L, response);
            return 1;
        }
        /* modo normal: resposta já impressa pelo streaming, só mostra timer */
        printf("\033[0;90m  ⏱  %.2fs\033[0m\n\n", _elapsed);
        return 0;
    } else {
        /* Detecta erros comuns e dá dica útil */
        if (strstr(response, "RESOURCE_EXHAUSTED") || strstr(response, "quota") || strstr(response, "credits")) {
            printf("\033[1;31m[CYN] Quota esgotada. Típico.\033[0m\n");
            printf("\033[0;90m  Modelo menor pode resolver:\033[0m\n");
            printf("\033[1;32m   ai.add('gemini-2.0-flash-8b','flash8')\033[0m\n");
            printf("\033[1;32m   ai.main('flash8')\033[0m\n");
        } else if (strstr(response, "401") || strstr(response, "invalid") || strstr(response, "not found")) {
            printf("\033[1;31m[CYN] Chave inválida ou modelo inexistente.\033[0m\n");
            printf("\033[0;90m  Corrige isso: export GEMINI_API_KEY='sua-chave'\033[0m\n");
            printf("\033[0;90m  %s\033[0m\n", response);
        } else {
            printf("\033[1;31m[CYN] Erro na requisição.\033[0m\n");
            printf("\033[0;90m  %s\033[0m\n", response);
        }
        return 0;
    }
}

// ============================================================================
// AI.CODE — geração de código técnico sem restrições (usa CYN_CODE_PROMPT)
// Usa o modelo 'code' se existir, senão fallback para lista permissiva
// ============================================================================

/* Modelos Gemini para geração de código — usados como fallback se 'code' não estiver salvo */
static const char *g_code_models[] = {
    "gemini-2.5-pro",    /* melhor para código — raciocínio avançado */
    "gemini-2.5-flash",  /* fallback rápido */
    "gemini-2.0-flash",
    "gemma-3-27b-it",
    NULL
};

// AI.SEARCH — busca web via DuckDuckGo + resumo pela CYN
static int l_ai_search(lua_State *L) {
    const char *query = luaL_checkstring(L, 1);

    printf("\033[1;33m[search] buscando: %s\033[0m\n", query);
    fflush(stdout);

    /* 1. Busca DuckDuckGo HTML (sem API key) */
    char cmd[4096];
    snprintf(cmd, sizeof(cmd),
        "curl -sL --max-time 10 -A 'Mozilla/5.0' "
        "-H 'Accept-Language: pt-BR,pt;q=0.9' "
        "'https://html.duckduckgo.com/html/?q=%s' 2>/dev/null",
        query);

    /* URL-encode básico: espaço → + */
    for (int i = 0; cmd[i]; i++) if (cmd[i] == ' ' && i > 80) { /* já no query */ }

    /* Re-monta com query encoded */
    char qenc[1024] = {0};
    for (int i = 0, j = 0; query[i] && j < 1020; i++) {
        if (query[i] == ' ') { qenc[j++] = '+'; }
        else { qenc[j++] = query[i]; }
    }
    snprintf(cmd, sizeof(cmd),
        "curl -sL --max-time 10 -A 'Mozilla/5.0' "
        "'https://html.duckduckgo.com/html/?q=%s' 2>/dev/null "
        "| sed 's/<[^>]*>//g' 2>/dev/null "
        "| grep -v '^[[:space:]]*$' 2>/dev/null "
        "| head -30 2>/dev/null",
        qenc);

    FILE *fp = popen(cmd, "r");
    if (!fp) {
        lua_pushstring(L, "❌ Falha ao acessar a web.");
        return 1;
    }

    char raw[4096] = {0};  /* limitado para não explodir o prompt do tgpt */
    size_t total = 0;
    char buf[512];
    while (fgets(buf, sizeof(buf), fp) && total < sizeof(raw)-1) {
        size_t n = strlen(buf);
        if (total + n < sizeof(raw)-1) {
            memcpy(raw + total, buf, n);
            total += n;
        }
    }
    pclose(fp);

    if (total < 10) {
        printf("\033[1;31m[search] sem resultados ou sem conexão\033[0m\n");
        lua_pushstring(L, "❌ Sem resultados ou sem conexão com a internet.");
        return 1;
    }

    /* 2. Manda o conteúdo bruto pra CYN resumir */
    char search_prompt[20000];
    snprintf(search_prompt, sizeof(search_prompt),
        "O usuário pediu uma pesquisa na web sobre: \"%s\"\n\n"
        "Abaixo estão os resultados brutos extraídos do DuckDuckGo.\n"
        "Analise e responda em português de forma clara e objetiva, "
        "destacando as informações mais relevantes:\n\n"
        "--- RESULTADOS ---\n%s\n--- FIM ---",
        query, raw);

    char response[8192] = {0};
    struct timeval _t0, _t1;
    gettimeofday(&_t0, NULL);

    printf("\033[1;33m");
    fflush(stdout);

    /* Seleciona prompt compacto ou completo conforme conteúdo */
    static const char *_kw2[] = {
        "net.","sys.","fs.","ai.","crypto.","db.","mod.","pent.","web.","exploit.",
        "ms -","ms --","lpm ","lmod.","scan","xss","sqli","lfi","rce","ssrf","ssti","prototype","pollution",
        "payload","shell","reverse","bind","exploit","inject","flood","fuzzing",
        "function","require","local ","net.tcp","sys.sh","net.listen","net.http",
        NULL
    };
    const char *_sysp = CYN_SYSTEM_PROMPT_CORE;
    for (int _i = 0; _kw2[_i]; _i++) {
        if (strstr(query, _kw2[_i])) { _sysp = CYN_SYSTEM_PROMPT; break; }
    }
    int ok = ai_http_ask(active_model_url, _sysp,
                         search_prompt, response, sizeof(response), 2047);

    printf("\033[0m\n");
    gettimeofday(&_t1, NULL);
    double _cel = (_t1.tv_sec - _t0.tv_sec) + (_t1.tv_usec - _t0.tv_usec)/1e6;
    printf("\033[0;90m  ⏱  %.2fs\033[0m\n\n", _cel);

    if (!ok) {
        lua_pushstring(L, response[0] ? response : "❌ Erro na resposta da IA.");
        return 1;
    }

    hist_add("user",      search_prompt);
    hist_add("assistant", response);
    lua_pushstring(L, response);
    return 1;
}


static int l_ai_code(lua_State *L) {
    const char *prompt = luaL_checkstring(L, 1);
    const char *out_file = (lua_gettop(L) >= 2 && lua_isstring(L, 2))
                           ? lua_tostring(L, 2) : NULL;

    /* Sempre usa o modelo ativo do usuário (ai.main) */
    const char *model_url  = active_model_url[0] ? active_model_url : "gemini-2.5-flash";
    const char *model_name = model_url;

    /* Detecta pedido de pesquisa dentro do prompt do --code */
    char enriched_prompt[40000] = {0};
    strncpy(enriched_prompt, prompt, sizeof(enriched_prompt)-1);

    {
        /* Copia lower do prompt para detectar intenção */
        char plow[8192] = {0};
        for (int _i = 0; prompt[_i] && _i < 8191; _i++)
            plow[_i] = (char)tolower((unsigned char)prompt[_i]);

        int has_search = (
            strstr(plow, "pesquisa na web")    ||
            strstr(plow, "pesquise na web")    ||
            strstr(plow, "busca na web")        ||
            strstr(plow, "busque na web")       ||
            strstr(plow, "pesquisa na internet")||
            strstr(plow, "busca na internet")   ||
            strstr(plow, "buscar na internet")  ||
            strstr(plow, "buscar na web")       ||
            strstr(plow, "pesquisar na web")    ||
            strstr(plow, "search the web")      ||
            strstr(plow, "procure na web")      ||
            strstr(plow, "procura na web")
        );

        if (has_search) {
            printf("\033[1;33m[code] pesquisa na web detectada — buscando contexto...\033[0m\n");
            fflush(stdout);

            /* URL-encode do prompt: espaço → + */
            char qenc[1024] = {0};
            for (int _i = 0, _j = 0; prompt[_i] && _j < 1020; _i++) {
                if (prompt[_i] == ' ') qenc[_j++] = '+';
                else qenc[_j++] = prompt[_i];
            }

            char scmd[4096];
            snprintf(scmd, sizeof(scmd),
                "curl -sL --max-time 10 -A 'Mozilla/5.0' "
                "'https://html.duckduckgo.com/html/?q=%s' 2>/dev/null "
                "| sed 's/<[^>]*>//g' 2>/dev/null "
                "| grep -v '^[[:space:]]*$' 2>/dev/null "
                "| head -25 2>/dev/null",
                qenc);

            FILE *sfp = popen(scmd, "r");
            char web_raw[3500] = {0};  /* limitado para caber no prompt */
            if (sfp) {
                size_t wtotal = 0;
                char wbuf[512];
                while (fgets(wbuf, sizeof(wbuf), sfp) && wtotal < sizeof(web_raw)-1) {
                    size_t wn = strlen(wbuf);
                    if (wtotal + wn < sizeof(web_raw)-1) {
                        memcpy(web_raw + wtotal, wbuf, wn);
                        wtotal += wn;
                    }
                }
                pclose(sfp);
            }

            if (strlen(web_raw) > 10) {
                /* Trunca contexto web para não estourar limite do tgpt */
                if (strlen(web_raw) > 2800) web_raw[2800] = '\0';
                printf("\033[0;90m[code] contexto web obtido — gerando código...\033[0m\n");
                snprintf(enriched_prompt, sizeof(enriched_prompt),
                    "%s\n\n"
                    "--- CONTEXTO WEB ---\n%s\n--- FIM ---\n\n"
                    "Use o contexto acima para enriquecer o código gerado.",
                    prompt, web_raw);
            } else {
                printf("\033[1;31m[code] sem resultado web, gerando com conhecimento próprio...\033[0m\n");
            }
        }
    }

    printf("\033[0;90m[code] modelo: %s\033[0m\n", model_name);
    printf("\033[0;90m[code] gerando...\033[0m\n");

    struct timeval _ct0, _ct1;
    gettimeofday(&_ct0, NULL);

    char response[32768] = {0};
    int ok = ai_http_ask(model_url, CYN_CODE_PROMPT, enriched_prompt, response, sizeof(response), 2047);

    gettimeofday(&_ct1, NULL);
    double _celapsed = (_ct1.tv_sec - _ct0.tv_sec) + (_ct1.tv_usec - _ct0.tv_usec) / 1e6;

    if (ok && strlen(response) > 0) {
        hist_add("user",      prompt);
        hist_add("assistant", response);
        hist_save();

        /* Tenta extrair só o bloco de código se houver ```...``` */
        char *fence_start = strstr(response, "```");
        char *code_out = response; /* default: resposta inteira */
        if (fence_start) {
            /* pula a linha do ``` (pode ter linguagem: ```bash, ```lua) */
            char *code_begin = strchr(fence_start + 3, '\n');
            if (code_begin) {
                code_begin++; /* pula o \n */
                char *fence_end = strstr(code_begin, "```");
                if (fence_end) {
                    /* termina a string no fechamento do bloco */
                    *fence_end = '\0';
                    code_out = code_begin;
                }
            }
        }

        printf("\033[1;32m%s\033[0m\n", code_out);

        /* Salva em arquivo se -o foi passado */
        if (out_file && strlen(out_file) > 0) {
            FILE *fout = fopen(out_file, "w");
            if (fout) {
                fputs(code_out, fout);
                fclose(fout);
                printf("\033[1;33m[code] salvo em: %s\033[0m\n", out_file);
            } else {
                printf("\033[1;31m[code] erro ao salvar em: %s\033[0m\n", out_file);
            }
        }

        printf("\033[0;90m  \xe2\x8f\xb1  %.2fs\033[0m\n\n", _celapsed);
        lua_pushstring(L, code_out);
    } else {
        printf("\033[1;31m%s\033[0m\n", response);
        printf("\033[0;90m  \xe2\x8f\xb1  %.2fs\033[0m\n\n", _celapsed);
        lua_pushstring(L, response);
    }
    return 1;
}

/* Lista modelos permissivos sugeridos para ai.code() */
static int l_ai_models_code(lua_State *L) {
    (void)L;
    printf("\n\033[1;35m╔══════════════════════════════════════════════════════════════╗\033[0m\n");
    printf("\033[1;35m║  Modelos free recomendados para ai.code()                    ║\033[0m\n");
    printf("\033[1;35m╚══════════════════════════════════════════════════════════════╝\033[0m\n\n");
    for (int i = 0; i < ai_model_count; i++) {
        if (strcmp(ai_models[i].name, "code") == 0) {
            printf("\033[1;32m  [ativo]\033[0m  code → \033[1;37m%s\033[0m\n\n", ai_models[i].model);
            break;
        }
    }
    printf("\033[1;33m  Modelos permissivos sugeridos:\033[0m\n");
    for (int i = 0; g_code_models[i]; i++)
        printf("  \033[0;90m%d.\033[0m \033[1;36m%s\033[0m\n", i+1, g_code_models[i]);
    printf("\n\033[0;90m  Para trocar: ai.remove('code') → ai.add('novo_modelo','code')\033[0m\n\n");
    lua_pushinteger(L, 0);
    return 1;
}


// AI.MODEL — lista modelos disponíveis de um provider e quota restante
static int l_ai_model(lua_State *L) {
    const char *arg = luaL_optstring(L, 1, NULL);
    const char *api_key = getenv("ELLIOT_AI_KEY");
    if (!api_key||!api_key[0]) api_key = getenv("GEMINI_API_KEY");

    /* Sem argumento — mostra modelo ativo */
    if (!arg || !arg[0]) {
        const char *mdl = active_model_url[0] ? active_model_url : "gemini-2.5-flash";
        printf("\033[1;35m[CYN]\033[0m Modelo ativo: \033[1;36m%s\033[0m\n", mdl);
        printf("\033[0;90m  Use ai.model('gemini') para listar modelos disponíveis\033[0m\n");
        return 0;
    }

    /* Gemini — lista via API */
    if (strcmp(arg,"gemini")==0) {
        printf("\033[1;35m[CYN]\033[0m \033[1;33mBuscando modelos Gemini...\033[0m\n");
        if (!api_key||!api_key[0]) {
            printf("\033[1;31m❌ Configure a key primeiro: ai.key('AIza...')\033[0m\n");
            return 0;
        }

        /* Lista modelos */
        char list_url[512];
        snprintf(list_url,sizeof(list_url),
            "https://generativelanguage.googleapis.com/v1/models?key=%s&pageSize=50", api_key);

        char *raw = calloc(1,512*1024);
        if (!raw) return 0;

        const char *hdrs[]={"Accept: application/json"};
        do_curl_req(list_url, hdrs, 1, NULL, raw, 512*1024);

        const char *active = active_model_url[0] ? active_model_url : "gemini-2.5-flash";

        printf("\n\033[1;35m╔══════════════════════════════════════════╗\033[0m\n");
        printf("\033[1;35m║       Modelos Gemini Disponíveis         ║\033[0m\n");
        printf("\033[1;35m╚══════════════════════════════════════════╝\033[0m\n\n");

        /* Parseia nomes dos modelos */
        int count = 0;
        const char *p = raw;
        while ((p = strstr(p, "\"name\":")) != NULL) {
            p += 7;
            while (*p==' '||*p=='"') p++;
            /* pula "models/" prefix */
            if (strncmp(p,"models/",7)==0) p+=7;
            char name[128]={0};
            int ni=0;
            while (*p && *p!='"' && ni<127) name[ni++]=*p++;

            /* Filtra só os generateContent */
            if (!strstr(name,"gemini") && !strstr(name,"gemma")) continue;
            if (strstr(name,"embedding")||strstr(name,"aqa")) continue;

            int is_active = (strcmp(name, active)==0);
            if (is_active)
                printf("  \033[1;32m▶ %-40s ◀ (ativo)\033[0m\n", name);
            else
                printf("  \033[0;37m  %-40s\033[0m\n", name);
            count++;
        }
        free(raw);

        if (count==0) {
            printf("  \033[1;31m❌ Nenhum modelo encontrado. Verifique a key.\033[0m\n");
        } else {
            printf("\n\033[0;90m  Total: %d modelos\033[0m\n", count);
            printf("\033[0;90m  Para trocar: ai.main('nome-do-modelo')\033[0m\n");
        }

        /* Testa quota fazendo request mínimo e captura erro */
        printf("\n\033[1;33m  Testando quota do modelo ativo...\033[0m\n");
        char test_url[512];
        snprintf(test_url,sizeof(test_url),
            "https://generativelanguage.googleapis.com/v1/models/%s:generateContent?key=%s",
            active, api_key);
        char *qraw = calloc(1,32*1024);
        if (qraw) {
            const char *qhdrs[]={"Content-Type: application/json","Accept: application/json"};
            do_curl_req(test_url,qhdrs,2,
                "{\"contents\":[{\"role\":\"user\",\"parts\":[{\"text\":\"1\"}]}],\"generationConfig\":{\"maxOutputTokens\":1}}",
                qraw,32*1024);
            if (strstr(qraw,"RESOURCE_EXHAUSTED")||strstr(qraw,"quota")) {
                printf("  \033[1;31m❌ Quota ESGOTADA para %s\033[0m\n", active);
                printf("  \033[0;90m  Tente: ai.main('gemini-2.0-flash-lite')\033[0m\n");
            } else if (strstr(qraw,"candidates")||strstr(qraw,"text")) {
                printf("  \033[1;32m✅ Quota OK — modelo funcionando\033[0m\n");
            } else if (strstr(qraw,"error")) {
                printf("  \033[1;31m❌ Erro: %s\033[0m\n", qraw);
            }
            free(qraw);
        }
        printf("\n");
        return 0;
    }

    /* Outros providers — mostra lista estática */
    printf("\033[1;35m[CYN]\033[0m Modelos conhecidos para \033[1;36m%s\033[0m:\n", arg);
    if (strcmp(arg,"groq")==0) {
        printf("  llama-3.3-70b-versatile\n  llama-3.1-8b-instant\n  mixtral-8x7b-32768\n  gemma2-9b-it\n");
    } else if (strcmp(arg,"openai")==0) {
        printf("  gpt-4o\n  gpt-4o-mini\n  gpt-4-turbo\n  gpt-3.5-turbo\n");
    } else if (strcmp(arg,"deepseek")==0) {
        printf("  deepseek-chat\n  deepseek-reasoner\n");
    } else {
        printf("  \033[0;90mProvider '%s' não reconhecido. Use: gemini, groq, openai, deepseek\033[0m\n", arg);
    }
    printf("\033[0;90m  Para trocar: ai.main('nome-do-modelo')\033[0m\n");
    return 0;
}

// AI.FORGET — limpa apenas o histórico de mensagens, preserva estado atual
static int l_ai_forget(lua_State *L) {
    (void)L;
    ai_history_count = 0;
    if (ai_hist_path[0]) remove(ai_hist_path);
    printf("\033[1;35m[CYN] Histórico apagado. Começando do zero.\033[0m\n");
    return 0;
}

// ai.clear() — alias semântico de ai.forget() (limpa conversa, mantém modelos/persona)
static int l_ai_clear(lua_State *L) {
    return l_ai_forget(L);
}

// ai.raw_mode(bool) — ativa/desativa modo raw (usado internamente por ms -A)
static int l_ai_set_raw(lua_State *L) {
    g_ai_raw_mode = lua_toboolean(L, 1);
    return 0;
}

// ai.history() — exibe o histórico de conversa atual
static int l_ai_history(lua_State *L) {
    (void)L;
    if (ai_history_count == 0) {
        printf("\033[0;90m  (histórico vazio — use ai.ask() para iniciar uma conversa)\033[0m\n");
        return 0;
    }
    printf("\n\033[1;35m╔══════════════════════════════════════════╗\033[0m\n");
    printf("\033[1;35m║  Histórico de conversa  (%2d mensagens)  ║\033[0m\n", ai_history_count);
    printf("\033[1;35m╚══════════════════════════════════════════╝\033[0m\n\n");
    for (int i = 0; i < ai_history_count; i++) {
        int is_user = strcmp(ai_history[i].role, "user") == 0;
        if (is_user)
            printf("\033[1;36m┌─ Você ──────────────────────────────\033[0m\n\033[0;97m%s\033[0m\n\n",
                   ai_history[i].content);
        else
            printf("\033[1;35m┌─ CYN ───────────────────────────────\033[0m\n\033[0;37m%s\033[0m\n\n",
                   ai_history[i].content);
    }
    return 0;
}

