// TASKS
#define MAX_TASKS 256
typedef struct { long id; char name[128]; char cmd[512]; char type[16]; int active; time_t created; } TaskInfo;
static TaskInfo G_Tasks[MAX_TASKS];
static int G_TaskCount = 0;
static pthread_mutex_t task_mutex = PTHREAD_MUTEX_INITIALIZER;

/* ── ivar: forward declarations (definição completa mais abaixo) ── */
static int g_ivar_enabled = 0; /* desativado por padrão — lido do disco no init */
static int g_ivar_count   = 0;

/* ── ivar: persistência em ~/.elliot_ivar.cfg ───────────────────────────── */
static void ivar_config_save(void) {
    const char *home = getenv("HOME");
    if (!home) return;
    char path[512];
    snprintf(path, sizeof(path), "%s/.elliot_ivar.cfg", home);
    FILE *f = fopen(path, "w");
    if (!f) return;
    fprintf(f, "enabled=%d\n", g_ivar_enabled);
    fclose(f);
}

static void ivar_config_load(void) {
    const char *home = getenv("HOME");
    if (!home) return;
    char path[512];
    snprintf(path, sizeof(path), "%s/.elliot_ivar.cfg", home);
    FILE *f = fopen(path, "r");
    if (!f) return; /* sem cfg → mantém default 0 */
    char line[64];
    while (fgets(line, sizeof(line), f)) {
        int len = (int)strlen(line);
        while (len > 0 && (line[len-1]=='\n'||line[len-1]=='\r')) line[--len]='\0';
        if (strncmp(line, "enabled=", 8)==0)
            g_ivar_enabled = (line[8]=='1') ? 1 : 0;
    }
    fclose(f);
}

// TUI
typedef struct { char title[128]; int w, h, x, y, selected, count, running; char labels[32][128]; int refs[32]; int max_len; } TUIState;
static TUIState G_Stack[12];
static int G_Depth = -1;
#define CUR_TUI G_Stack[G_Depth]

// SIGWINCH — redesenha TUI quando o terminal é redimensionado
static volatile sig_atomic_t g_tui_needs_redraw = 0;
static void sigwinch_handler(int sig) { (void)sig; g_tui_needs_redraw = 1; }

static void draw_tui() {
    if (G_Depth < 0) return;
    printf("\033[H\033[J");
    int win_w = (CUR_TUI.max_len > CUR_TUI.w) ? CUR_TUI.max_len : CUR_TUI.w;
    int t_len = (int)strlen(CUR_TUI.title);
    if(t_len > win_w) win_w = t_len;
    win_w += 4;
    const char* colors[] = {"\033[1;36m","\033[1;32m","\033[1;33m","\033[1;35m","\033[1;31m"};
    const char* c = colors[G_Depth % 5];
    printf("\033[%d;%dH%s┌─ %s ",CUR_TUI.y,CUR_TUI.x,c,CUR_TUI.title);
    for(int i=0;i<(win_w-t_len);i++) printf("─");
    printf("┐\033[0m\n");
    for(int i=0;i<CUR_TUI.h;i++){
        printf("\033[%d;%dH%s│\033[0m ",CUR_TUI.y+1+i,CUR_TUI.x,c);
        if(i<CUR_TUI.count){
            if(i==CUR_TUI.selected) printf("\033[7m %-*s \033[0m",win_w,CUR_TUI.labels[i]);
            else printf(" %-*s ",win_w,CUR_TUI.labels[i]);
        } else printf("%-*s ",win_w+1,"");
        printf("%s│\033[0m\n",c);
    }
    printf("\033[%d;%dH%s└─",CUR_TUI.y+CUR_TUI.h+1,CUR_TUI.x,c);
    for(int i=0;i<win_w+2;i++) printf("─");
    printf("┘\033[0m\n");
    fflush(stdout);
}

static int l_tui_main(lua_State *L) {
    if(G_Depth<11) G_Depth++;
    const char *size=luaL_checkstring(L,1);
    sscanf(size,"%dx%d",&CUR_TUI.w,&CUR_TUI.h);
    strncpy(CUR_TUI.title,luaL_checkstring(L,2),127);
    CUR_TUI.selected=0; CUR_TUI.count=0; CUR_TUI.running=1; CUR_TUI.max_len=0;
    CUR_TUI.x=2; CUR_TUI.y=2;
    for(int i=0;i<32;i++) CUR_TUI.refs[i]=LUA_NOREF;
    // Registra handler de resize — redesenha automaticamente se terminal mudar
    signal(SIGWINCH, sigwinch_handler);
    draw_tui();
    return 0;
}

static int l_tui_read(lua_State *L) {
    const char *prompt = luaL_checkstring(L, 1);
    char input[512];
    // Salva estado atual, força modo canônico para leitura de linha
    struct termios oldt, newt;
    tcgetattr(STDIN_FILENO, &oldt);
    newt = oldt;
    newt.c_lflag |= (ICANON | ECHO);
    newt.c_lflag &= ~(ECHONL);
    tcsetattr(STDIN_FILENO, TCSANOW, &newt);
    printf("\n\033[1;32m%s\033[0m ", prompt); fflush(stdout);
    if (fgets(input, sizeof(input), stdin)) {
        input[strcspn(input, "\n")] = 0;
        lua_pushstring(L, input);
    } else {
        lua_pushnil(L);
    }
    tcsetattr(STDIN_FILENO, TCSANOW, &oldt); // restaura exato estado anterior
    return 1;
}

static int l_tui_func(lua_State *L) {
    luaL_checktype(L, 1, LUA_TTABLE);
    CUR_TUI.count   = 0;
    CUR_TUI.max_len = 0;

    // Libera refs anteriores
    for (int i = 0; i < 32; i++) {
        if (CUR_TUI.refs[i] != LUA_NOREF && CUR_TUI.refs[i] != LUA_REFNIL) {
            luaL_unref(L, LUA_REGISTRYINDEX, CUR_TUI.refs[i]);
            CUR_TUI.refs[i] = LUA_NOREF;
        }
    }

    int n = (int)lua_rawlen(L, 1);
    for (int i = 1; i <= n && CUR_TUI.count < 32; i++) {
        lua_rawgeti(L, 1, i);  // pega item[i]
        if (!lua_istable(L, -1)) { lua_pop(L, 1); continue; }

        // Aceita dois formatos:
        // Formato A (seu): {["label"] = function}  — chave string, valor função
        // Formato B (antigo): {"label", ref}        — índice 1=label, 2=ref

        char label_buf[128] = {0};
        const char *label = NULL;
        int fn_ref = LUA_NOREF;

        // Tenta Formato A: itera as chaves da subtabela
        lua_pushnil(L);
        while (lua_next(L, -2)) {
            if (lua_type(L, -2) == LUA_TSTRING && lua_type(L, -1) == LUA_TFUNCTION) {
                // Copia antes do pop — ponteiro Lua invalida após remoção da stack
                const char *raw = lua_tostring(L, -2);
                if (raw) { strncpy(label_buf, raw, 127); label_buf[127] = '\0'; label = label_buf; }
                lua_pushvalue(L, -1);
                fn_ref = luaL_ref(L, LUA_REGISTRYINDEX);
                lua_pop(L, 1); // pop value
                lua_pop(L, 1); // pop key
                break;
            }
            lua_pop(L, 1);
        }

        // Tenta Formato B se A não funcionou
        if (label == NULL) {
            lua_rawgeti(L, -1, 1);
            if (lua_type(L, -1) == LUA_TSTRING) {
                const char *raw = lua_tostring(L, -1);
                if (raw) { strncpy(label_buf, raw, 127); label_buf[127] = '\0'; label = label_buf; }
            }
            lua_pop(L, 1);
            lua_rawgeti(L, -1, 2);
            if (lua_type(L, -1) == LUA_TFUNCTION) {
                lua_pushvalue(L, -1);
                fn_ref = luaL_ref(L, LUA_REGISTRYINDEX);
            }
            lua_pop(L, 1);
        }

        if (label) {
            strncpy(CUR_TUI.labels[CUR_TUI.count], label, 127);
            CUR_TUI.labels[CUR_TUI.count][127] = '\0';
            int ll = (int)strlen(label);
            if (ll > CUR_TUI.max_len) CUR_TUI.max_len = ll;
            CUR_TUI.refs[CUR_TUI.count] = fn_ref;
            CUR_TUI.count++;
        }

        lua_pop(L, 1); // pop subtabela
    }

    if (CUR_TUI.count == 0) {
        printf("\033[1;31m[tui] Nenhuma opção encontrada na tabela!\033[0m\n");
        return 0;
    }

    draw_tui();

    struct termios oldt, newt;
    tcgetattr(STDIN_FILENO, &oldt);
    newt = oldt;
    newt.c_lflag &= ~(ICANON | ECHO);
    newt.c_cc[VMIN]  = 1;
    newt.c_cc[VTIME] = 0;
    tcsetattr(STDIN_FILENO, TCSANOW, &newt);

    int selected_ref = LUA_NOREF;
    CUR_TUI.running  = 1;

    while (CUR_TUI.running) {
        // Verifica se o terminal foi redimensionado (SIGWINCH)
        if (g_tui_needs_redraw) { g_tui_needs_redraw = 0; draw_tui(); }
        int ch = getchar();
        if (ch == 27) {
            // Breve timeout para os bytes da sequência de escape
            struct termios esc_t = newt;
            esc_t.c_cc[VMIN]=0; esc_t.c_cc[VTIME]=1;
            tcsetattr(STDIN_FILENO, TCSANOW, &esc_t);
            int c2 = getchar(); int c3 = (c2 != -1) ? getchar() : -1;
            tcsetattr(STDIN_FILENO, TCSANOW, &newt);
            if (c2 == '[' && c3 == 'A') {
                if (CUR_TUI.selected > 0) CUR_TUI.selected--;
            } else if (c2 == '[' && c3 == 'B') {
                if (CUR_TUI.selected < CUR_TUI.count - 1) CUR_TUI.selected++;
            }
        } else if (ch == 10 || ch == 13) {
            selected_ref    = CUR_TUI.refs[CUR_TUI.selected];
            CUR_TUI.running = 0;
        } else if (ch == 'q' || ch == 3) {
            CUR_TUI.running = 0;
        }
        if (CUR_TUI.running) draw_tui();
    }

    tcsetattr(STDIN_FILENO, TCSANOW, &oldt);

    // Chama a função associada ao item selecionado
    if (selected_ref != LUA_NOREF && selected_ref != LUA_REFNIL) {
        lua_rawgeti(L, LUA_REGISTRYINDEX, selected_ref);
        if (lua_isfunction(L, -1)) {
            if (lua_pcall(L, 0, 0, 0) != LUA_OK) {
                printf("\033[1;31m[tui] Erro: %s\033[0m\n", lua_tostring(L, -1));
                lua_pop(L, 1);
            }
        } else {
            lua_pop(L, 1);
        }
    }

    return 0;
}

static int l_tui_close(lua_State *L) {
    (void)L;
    if(G_Depth>=0) G_Depth--;
    printf("\033[H\033[J"); fflush(stdout);
    return 0;
}

static int l_tui_help(lua_State *L) {
    (void)L;
    printf("\n\033[1;36m╔═══════════════════════════════════════╗\033[0m\n");
    printf("\033[1;36m║  TUI - Terminal UI                    ║\033[0m\n");
    printf("\033[1;36m╚═══════════════════════════════════════╝\033[0m\n\n");
    printf("  tui.main('80x20','Título') - Criar janela\n");
    printf("  tui.func({                 - Menu interativo (↑↓ Enter q=sair)\n");
    printf("    {['Opção 1']=function() ... end},\n");
    printf("    {['Opção 2']=function() ... end},\n");
    printf("  })\n");
    printf("  tui.read('Prompt')         - Ler input do usuário\n");
    printf("  tui.close()                - Fechar janela\n\n");
    return 0;
}

// UI
static int l_ui_color(lua_State *L) {
    const char *color = luaL_checkstring(L, 1);
    const char *mod   = luaL_optstring(L, 2, "");
    // prefixo bold: "1;" quando bold, "" quando não
    const char *b  = (strcmp(mod, "bold") == 0) ? "1;" : "";

    if (strcmp(color, "reset") == 0 || strcmp(color, "off") == 0) {
        printf("\033[0m"); fflush(stdout); return 0;
    }

    // Modificadores sozinhos — emite sequência única e retorna
    if (strcmp(color,"bold")      == 0) { printf("\033[1m");  fflush(stdout); return 0; }
    if (strcmp(color,"dim")       == 0) { printf("\033[2m");  fflush(stdout); return 0; }
    if (strcmp(color,"italic")    == 0) { printf("\033[3m");  fflush(stdout); return 0; }
    if (strcmp(color,"underline") == 0) { printf("\033[4m");  fflush(stdout); return 0; }
    if (strcmp(color,"blink")     == 0) { printf("\033[5m");  fflush(stdout); return 0; }
    if (strcmp(color,"reverse")   == 0) { printf("\033[7m");  fflush(stdout); return 0; }
    if (strcmp(color,"strike")    == 0) { printf("\033[9m");  fflush(stdout); return 0; }

    // Cores fg normais — sequência única com bold opcional: \033[1;31m ou \033[31m
    if      (strcmp(color,"black")          == 0) printf("\033[%s30m", b);
    else if (strcmp(color,"red")            == 0) printf("\033[%s31m", b);
    else if (strcmp(color,"green")          == 0) printf("\033[%s32m", b);
    else if (strcmp(color,"yellow")         == 0) printf("\033[%s33m", b);
    else if (strcmp(color,"blue")           == 0) printf("\033[%s34m", b);
    else if (strcmp(color,"magenta")        == 0) printf("\033[%s35m", b);
    else if (strcmp(color,"cyan")           == 0) printf("\033[%s36m", b);
    else if (strcmp(color,"white")          == 0) printf("\033[%s37m", b);

    // Bright
    else if (strcmp(color,"bright_black")   == 0) printf("\033[%s90m", b);
    else if (strcmp(color,"bright_red")     == 0) printf("\033[%s91m", b);
    else if (strcmp(color,"bright_green")   == 0) printf("\033[%s92m", b);
    else if (strcmp(color,"bright_yellow")  == 0) printf("\033[%s93m", b);
    else if (strcmp(color,"bright_blue")    == 0) printf("\033[%s94m", b);
    else if (strcmp(color,"bright_magenta") == 0) printf("\033[%s95m", b);
    else if (strcmp(color,"bright_cyan")    == 0) printf("\033[%s96m", b);
    else if (strcmp(color,"bright_white")   == 0) printf("\033[%s97m", b);

    // Extras 256
    else if (strcmp(color,"orange")         == 0) printf("\033[%s38;5;208m", b);
    else if (strcmp(color,"pink")           == 0) printf("\033[%s38;5;213m", b);
    else if (strcmp(color,"purple")         == 0) printf("\033[%s38;5;135m", b);
    else if (strcmp(color,"lime")           == 0) printf("\033[%s38;5;154m", b);
    else if (strcmp(color,"teal")           == 0) printf("\033[%s38;5;37m",  b);
    else if (strcmp(color,"gold")           == 0) printf("\033[%s38;5;220m", b);
    else if (strcmp(color,"sky")            == 0) printf("\033[%s38;5;117m", b);
    else if (strcmp(color,"gray")           == 0) printf("\033[%s38;5;245m", b);
    else if (strcmp(color,"dark_gray")      == 0) printf("\033[%s38;5;236m", b);
    else if (strcmp(color,"brown")          == 0) printf("\033[%s38;5;130m", b);
    else if (strcmp(color,"salmon")         == 0) printf("\033[%s38;5;210m", b);
    else if (strcmp(color,"mint")           == 0) printf("\033[%s38;5;121m", b);
    else if (strcmp(color,"lavender")       == 0) printf("\033[%s38;5;183m", b);
    else if (strcmp(color,"coral")          == 0) printf("\033[%s38;5;203m", b);

    // Background
    else if (strcmp(color,"bg_black")       == 0) printf("\033[%s40m",  b);
    else if (strcmp(color,"bg_red")         == 0) printf("\033[%s41m",  b);
    else if (strcmp(color,"bg_green")       == 0) printf("\033[%s42m",  b);
    else if (strcmp(color,"bg_yellow")      == 0) printf("\033[%s43m",  b);
    else if (strcmp(color,"bg_blue")        == 0) printf("\033[%s44m",  b);
    else if (strcmp(color,"bg_magenta")     == 0) printf("\033[%s45m",  b);
    else if (strcmp(color,"bg_cyan")        == 0) printf("\033[%s46m",  b);
    else if (strcmp(color,"bg_white")       == 0) printf("\033[%s47m",  b);
    else if (strcmp(color,"bg_orange")      == 0) printf("\033[%s48;5;208m", b);
    else if (strcmp(color,"bg_pink")        == 0) printf("\033[%s48;5;213m", b);
    else if (strcmp(color,"bg_purple")      == 0) printf("\033[%s48;5;135m", b);

    // 256 direto: "256:202" ou "bg256:21"
    else if (strncmp(color, "256:", 4) == 0) {
        int n = atoi(color + 4);
        if (n >= 0 && n <= 255) printf("\033[%s38;5;%dm", b, n);
    }
    else if (strncmp(color, "bg256:", 6) == 0) {
        int n = atoi(color + 6);
        if (n >= 0 && n <= 255) printf("\033[%s48;5;%dm", b, n);
    }
    else {
        printf("\033[0m"); // desconhecida → reset seguro
    }

    fflush(stdout);
    return 0;
}

static int l_ui_box(lua_State *L) {
    const char *title   = luaL_checkstring(L, 1);
    const char *content = luaL_optstring(L, 2, "");

    // Calcula largura mínima necessária
    // inner = w - 4 (2 bordas + 2 espaços padding)
    int w = 44; // mínimo: inner=40
    int tl = (int)strlen(title);
    if (tl + 4 > w) w = tl + 4;

    // Para conteúdo, considera cada linha separada por \n
    // e expande w se necessário
    {
        const char *p = content;
        int llen = 0;
        while (*p) {
            if (*p == '\n') {
                if (llen + 4 > w) w = llen + 4;
                llen = 0;
            } else { llen++; }
            p++;
        }
        if (llen + 4 > w) w = llen + 4;
    }

    int inner = w - 4; // espaço útil entre "║ " e " ║"

    // Linha topo
    printf("\033[1;36m╔═");
    for (int i = 0; i < w - 4; i++) printf("═");
    printf("═╗\033[0m\n");

    // Título
    printf("\033[1;36m║\033[1;33m %-*s \033[1;36m║\033[0m\n", inner, title);

    // Separador + conteúdo só se houver conteúdo
    if (content && content[0] != '\0') {
        printf("\033[1;36m╠═");
        for (int i = 0; i < w - 4; i++) printf("═");
        printf("═╣\033[0m\n");

        // Imprime linha por linha
        char line[1024];
        const char *p = content;
        while (*p) {
            int j = 0;
            int lim = inner < 1020 ? inner : 1020; /* protege o buffer de 1024 */
            while (*p && *p != '\n' && j < lim) line[j++] = *p++;
            /* descarta resto da linha se muito longa */
            while (*p && *p != '\n') p++;
            line[j] = '\0';
            if (*p == '\n') p++;
            printf("\033[1;36m║\033[0m %-*s \033[1;36m║\033[0m\n", inner, line);
        }
    }

    // Linha fundo
    printf("\033[1;36m╚═");
    for (int i = 0; i < w - 4; i++) printf("═");
    printf("═╝\033[0m\n");

    return 0;
}

static int l_ui_clear(lua_State *L) { (void)L; printf("\033[H\033[2J\033[3J"); fflush(stdout); return 0; }
static int l_ui_sleep(lua_State *L) { double s=luaL_checknumber(L,1); usleep((useconds_t)(s*1000000.0)); return 0; }
static int l_ui_fig(lua_State *L) {
    const char *text = luaL_checkstring(L, 1);
    const char *font = luaL_optstring(L, 2, "slant");

    // Sanitiza texto e fonte — remove chars que quebram o shell
    char safe_text[256] = {0};
    char safe_font[64]  = {0};
    int j = 0;
    for (int i = 0; text[i] && j < 255; i++) {
        char c = text[i];
        if (c=='\'' || c=='"' || c==';' || c=='&' || c=='|' || c=='`' || c=='$' || c=='\\' || c=='\r' || c=='\n' || (unsigned char)c < 0x20) continue;
        safe_text[j++] = c;
    }
    j = 0;
    for (int i = 0; font[i] && j < 63; i++) {
        char c = font[i];
        if (c=='\'' || c=='"' || c==';' || c=='&' || c=='|' || c=='`' || c=='$' || c=='\\' || c=='/' || c=='\r' || c=='\n' || (unsigned char)c < 0x20) continue;
        safe_font[j++] = c;
    }

    char cmd[512];
    snprintf(cmd, sizeof(cmd),
        "figlet -f '%s' '%s' 2>/dev/null || figlet '%s'",
        safe_font, safe_text, safe_text);
    system(cmd);
    return 0;
}

/* ui.input([prompt]) — lê linha do usuário, retorna string */
static int l_ui_input(lua_State *L) {
    const char *prompt = luaL_optstring(L, 1, "");
    if (prompt && prompt[0]) { fputs(prompt, stdout); fflush(stdout); }
    char buf[4096];
    if (!fgets(buf, sizeof(buf), stdin)) { lua_pushnil(L); return 1; }
    size_t len = strlen(buf);
    if (len > 0 && buf[len-1] == '\n') buf[--len] = '\0';
    lua_pushlstring(L, buf, len);
    return 1;
}

