// FS
static int l_fs_exists(lua_State *L) { lua_pushboolean(L,access(luaL_checkstring(L,1),F_OK)==0); return 1; }
static int l_fs_mkdir(lua_State *L) { lua_pushboolean(L,mkdir(luaL_checkstring(L,1),0755)==0); return 1; }
static int l_fs_rm(lua_State *L) { lua_pushboolean(L,remove(luaL_checkstring(L,1))==0); return 1; }
static int l_fs_move(lua_State *L) { lua_pushboolean(L,rename(luaL_checkstring(L,1),luaL_checkstring(L,2))==0); return 1; }
static int l_fs_copy(lua_State *L) {
    FILE *s=fopen(luaL_checkstring(L,1),"rb"); if(!s){lua_pushboolean(L,0);return 1;}
    FILE *d=fopen(luaL_checkstring(L,2),"wb"); if(!d){fclose(s);lua_pushboolean(L,0);return 1;}
    char buf[4096]; size_t n;
    while((n=fread(buf,1,sizeof(buf),s))>0) fwrite(buf,1,n,d);
    fclose(s); fclose(d); lua_pushboolean(L,1); return 1;
}
static int l_fs_read(lua_State *L) {
    FILE *f=fopen(luaL_checkstring(L,1),"rb"); if(!f){lua_pushnil(L);return 1;}
    luaL_Buffer b; luaL_buffinit(L,&b);
    char buf[4096]; size_t n;
    while((n=fread(buf,1,sizeof(buf),f))>0) luaL_addlstring(&b,buf,n);
    fclose(f); luaL_pushresult(&b); return 1;
}
static int l_fs_write(lua_State *L) {
    FILE *f=fopen(luaL_checkstring(L,1),"wb"); if(!f){lua_pushboolean(L,0);return 1;}
    size_t len; const char *data=luaL_checklstring(L,2,&len);
    fwrite(data,1,len,f); fclose(f); lua_pushboolean(L,1); return 1;
}
static int l_fs_append(lua_State *L) {
    FILE *f=fopen(luaL_checkstring(L,1),"ab"); if(!f){lua_pushboolean(L,0);return 1;}
    size_t len; const char *data=luaL_checklstring(L,2,&len);
    fwrite(data,1,len,f); fclose(f); lua_pushboolean(L,1); return 1;
}
static int l_fs_list(lua_State *L) {
    const char *path = luaL_optstring(L, 1, ".");
    DIR *d = opendir(path);
    if (!d) { lua_pushnil(L); lua_pushstring(L, strerror(errno)); return 2; }
    lua_newtable(L);
    int idx = 1;
    struct dirent *ent;
    while ((ent = readdir(d)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) continue;
        lua_pushstring(L, ent->d_name);
        lua_rawseti(L, -2, idx++);
    }
    closedir(d);
    return 1;
}
static int l_fs_stat(lua_State *L) {
    const char *path = luaL_checkstring(L, 1);
    struct stat st;
    if (stat(path, &st) != 0) {
        lua_pushnil(L);
        lua_pushstring(L, strerror(errno));
        return 2;
    }
    lua_newtable(L);
    lua_pushinteger(L, (lua_Integer)st.st_size);  lua_setfield(L, -2, "size");
    lua_pushinteger(L, (lua_Integer)st.st_mtime); lua_setfield(L, -2, "mtime");
    lua_pushinteger(L, (lua_Integer)st.st_ctime); lua_setfield(L, -2, "ctime");
    lua_pushinteger(L, (lua_Integer)st.st_mode);  lua_setfield(L, -2, "mode");
    lua_pushboolean(L, S_ISDIR(st.st_mode));      lua_setfield(L, -2, "isdir");
    lua_pushboolean(L, S_ISREG(st.st_mode));      lua_setfield(L, -2, "isfile");
    lua_pushboolean(L, S_ISLNK(st.st_mode));      lua_setfield(L, -2, "islink");
    return 1;
}

static int l_fs_isdir(lua_State *L) {
    const char *path = luaL_checkstring(L, 1);
    struct stat st;
    lua_pushboolean(L, stat(path, &st) == 0 && S_ISDIR(st.st_mode));
    return 1;
}

static int l_fs_isfile(lua_State *L) {
    const char *path = luaL_checkstring(L, 1);
    struct stat st;
    lua_pushboolean(L, stat(path, &st) == 0 && S_ISREG(st.st_mode));
    return 1;
}

static int l_fs_chmod(lua_State *L) {
    const char *path = luaL_checkstring(L, 1);
    int mode = (int)luaL_checkinteger(L, 2);
    if (chmod(path, (mode_t)mode) != 0) {
        lua_pushboolean(L, 0);
        lua_pushstring(L, strerror(errno));
        return 2;
    }
    lua_pushboolean(L, 1);
    return 1;
}

static int l_fs_glob(lua_State *L) {
    const char *dir_path  = luaL_optstring(L, 1, ".");
    const char *pattern   = luaL_optstring(L, 2, "*");
    size_t pat_len = strlen(pattern);
    DIR *d = opendir(dir_path);
    if (!d) { lua_pushnil(L); lua_pushstring(L, strerror(errno)); return 2; }
    lua_newtable(L);
    int idx = 1;
    struct dirent *ent;
    while ((ent = readdir(d)) != NULL) {
        if (strcmp(ent->d_name,".") == 0 || strcmp(ent->d_name,"..") == 0) continue;
        // Suporte a padrão simples: prefixo* sufixo*
        const char *star = strchr(pattern, '*');
        int match = 0;
        if (!star) {
            match = strcmp(ent->d_name, pattern) == 0;
        } else if (star == pattern) {
            // *sufixo
            const char *suf = star + 1;
            size_t suf_len = strlen(suf);
            size_t name_len = strlen(ent->d_name);
            match = (suf_len == 0) || (name_len >= suf_len &&
                strcmp(ent->d_name + name_len - suf_len, suf) == 0);
        } else {
            // prefixo*sufixo
            size_t pre_len = (size_t)(star - pattern);
            const char *suf = star + 1;
            size_t suf_len = strlen(suf);
            size_t name_len = strlen(ent->d_name);
            match = (name_len >= pre_len + suf_len) &&
                (strncmp(ent->d_name, pattern, pre_len) == 0) &&
                (suf_len == 0 || strcmp(ent->d_name + name_len - suf_len, suf) == 0);
        }
        (void)pat_len;
        if (match) {
            lua_pushstring(L, ent->d_name);
            lua_rawseti(L, -2, idx++);
        }
    }
    closedir(d);
    return 1;
}

