static int l_sh_capture(lua_State *L) {
    FILE *f=popen(luaL_checkstring(L,1),"r"); if(!f){lua_pushnil(L);lua_pushstring(L,"popen failed");return 2;}
    luaL_Buffer b; luaL_buffinit(L,&b);
