    while((n=fread(buf,1,sizeof(buf),f))>0) luaL_addlstring(&b,buf,n);
    int raw_rc=pclose(f); luaL_pushresult(&b);
    lua_pushinteger(L, WIFEXITED(raw_rc) ? WEXITSTATUS(raw_rc) : raw_rc);
    return 2;
}
