// NET
// ── Sanitiza URL para uso no shell (escapa aspas simples) ─────────────────


// ============================================================================
// net.get(url [, arquivo]) — baixa conteúdo bruto (código, texto, binário)
//   - sem arquivo: retorna string (comportamento original)
//   - com arquivo: salva no arquivo, retorna bytes salvos ou nil,err
//
// Detecta automaticamente se a URL aponta para código-fonte:
//   raw.githubusercontent.com, pastebin.com/raw, etc.
//   Se for uma URL de página HTML normal, extrai apenas o conteúdo do <body>
//   de code blocks (<pre>, <code>) se existirem.
// ============================================================================
// ── Detecta se URL aponta direto para código-fonte (raw) ──────────────────
// URLs raw não precisam de extração — o conteúdo JÁ é o código puro
static int url_is_raw(const char *url) {
    // Pastebin raw, GitHub raw, GitLab raw, hastebin, dpaste, sprunge, ix.io, etc.
    const char *raw_patterns[] = {
        "raw.githubusercontent.com",
        "pastebin.com/raw",
        "gitlab.com/raw",
        "hastebin.com/raw",
        "dpaste.com/raw",
        "dpaste.org/raw",
        "ix.io/",
        "sprunge.us/",
        "0x0.st/",
        "transfer.sh/",
        "/raw/",       // qualquer /raw/ no caminho
        NULL
    };
    for (int i = 0; raw_patterns[i]; i++) {
        if (strstr(url, raw_patterns[i])) return 1;
    }
    // Extensões de código-fonte diretamente na URL (sem query)
    const char *ext_start = strrchr(url, '/');
    if (!ext_start) ext_start = url;
    const char *dot = strrchr(ext_start, '.');
    if (dot) {
        const char *code_exts[] = {
            ".c",".h",".cpp",".cc",".cxx",
            ".py",".lua",".js",".ts",".sh",".bash",
            ".go",".rs",".java",".kt",".swift",
            ".rb",".php",".pl",".r",".m",
            ".cs",".vb",".asm",".s",
            ".json",".yaml",".yml",".toml",".ini",".conf",
            ".txt",".md",".csv",
            NULL
        };
        for (int i = 0; code_exts[i]; i++) {
            // Compara ignorando query string
            size_t el = strlen(code_exts[i]);
            if (strncasecmp(dot, code_exts[i], el) == 0 &&
                (dot[el] == '\0' || dot[el] == '?' || dot[el] == '#'))
                return 1;
        }
    }
    return 0;
}

// ── Extrai código de dentro do HTML ───────────────────────────────────────
// Pega conteúdo de <pre> e <code>, decodifica entidades HTML básicas.
// Se não achar nenhum bloco, retorna o texto plano sem tags.
static char *html_extract_code(const char *html, size_t html_len, size_t *out_len) {
    size_t cap = html_len + 1;
    char *out  = malloc(cap);
    if (!out) return NULL;
    size_t pos = 0;
    int found_block = 0;

    // Procura por <pre...> ou <code...>
    const char *p = html;
    const char *end = html + html_len;

    while (p < end) {
        // Verifica se começa um bloco <pre ou <code
        int is_pre  = (p + 4 <= end && strncasecmp(p, "<pre", 4) == 0 &&
                       (p[4]=='>' || p[4]==' ' || p[4]=='\n' || p[4]=='\r' || p[4]=='\t'));
        int is_code = (p + 5 <= end && strncasecmp(p, "<code",5) == 0 &&
                       (p[5]=='>' || p[5]==' ' || p[5]=='\n' || p[5]=='\r' || p[5]=='\t'));

        if (is_pre || is_code) {
            found_block = 1;
            // Pula até fechar a tag de abertura >
            while (p < end && *p != '>') p++;
            if (p < end) p++; // pula o '>'

            // Determina a tag de fechamento
            const char *close_tag = is_pre ? "</pre" : "</code";
            size_t close_len = strlen(close_tag);

            // Copia conteúdo até a tag de fechamento, decodificando entidades
            while (p < end) {
                if (strncasecmp(p, close_tag, close_len) == 0) {
                    p += close_len;
                    while (p < end && *p != '>') p++; // pula </pre>
                    if (p < end) p++;
                    break;
                }
                // Pula tags HTML internas (<span class="...">, etc.)
                if (*p == '<') {
                    while (p < end && *p != '>') p++;
                    if (p < end) p++;
                    continue;
                }
                // Decodifica entidades HTML básicas
                if (*p == '&') {
                    if (strncmp(p, "&lt;",  4)==0) { if(pos<cap-1) out[pos++]='<'; p+=4; continue; }
                    if (strncmp(p, "&gt;",  4)==0) { if(pos<cap-1) out[pos++]='>'; p+=4; continue; }
                    if (strncmp(p, "&amp;", 5)==0) { if(pos<cap-1) out[pos++]='&'; p+=5; continue; }
                    if (strncmp(p, "&quot;",6)==0) { if(pos<cap-1) out[pos++]='"'; p+=6; continue; }
                    if (strncmp(p, "&#39;", 5)==0) { if(pos<cap-1) out[pos++]='\'';p+=5; continue; }
                    if (strncmp(p, "&nbsp;",6)==0) { if(pos<cap-1) out[pos++]=' '; p+=6; continue; }
                    if (strncmp(p, "&#10;", 5)==0) { if(pos<cap-1) out[pos++]='\n';p+=5; continue; }
                }
                if (pos < cap-1) out[pos++] = *p;
                p++;
            }
            // Separa blocos com newline
            if (pos < cap-1 && pos > 0 && out[pos-1] != '\n')
                out[pos++] = '\n';

        } else {
            p++;
        }
    }

    // Se não achou nenhum <pre>/<code>, faz strip simples de todas as tags HTML
    if (!found_block) {
        pos = 0;
        p = html;
        int in_tag    = 0;
        int in_script = 0;
        int in_style  = 0;
        while (p < end) {
            // Detecta e pula <script> e <style> completos
            if (!in_tag && strncasecmp(p,"<script",7)==0) { in_script=1; p++; continue; }
            if (in_script && strncasecmp(p,"</script",8)==0) { in_script=0; p+=8; continue; }
            if (in_script) { p++; continue; }
            if (!in_tag && strncasecmp(p,"<style",6)==0) { in_style=1; p++; continue; }
            if (in_style && strncasecmp(p,"</style",7)==0) { in_style=0; p+=7; continue; }
            if (in_style) { p++; continue; }

            if (*p == '<') { in_tag=1; p++; continue; }
            if (*p == '>') { in_tag=0; p++; continue; }
            if (in_tag)   { p++; continue; }

            // Decodifica entidades
            if (*p == '&') {
                if (strncmp(p,"&lt;", 4)==0)  { if(pos<cap-1) out[pos++]='<'; p+=4; continue; }
                if (strncmp(p,"&gt;", 4)==0)  { if(pos<cap-1) out[pos++]='>'; p+=4; continue; }
                if (strncmp(p,"&amp;",5)==0)  { if(pos<cap-1) out[pos++]='&'; p+=5; continue; }
                if (strncmp(p,"&quot;",6)==0) { if(pos<cap-1) out[pos++]='"'; p+=6; continue; }
                if (strncmp(p,"&#39;",5)==0)  { if(pos<cap-1) out[pos++]='\'';p+=5; continue; }
                if (strncmp(p,"&nbsp;",6)==0) { if(pos<cap-1) out[pos++]=' '; p+=6; continue; }
            }
            if (pos < cap-1) out[pos++] = *p;
            p++;
        }
        // Remove linhas vazias excessivas (mais de 2 seguidas)
        char *cleaned = malloc(pos+1);
        if (cleaned) {
            size_t ci=0; int blanks=0;
            for (size_t i=0; i<pos; i++) {
                if (out[i]=='\n') {
                    blanks++;
                    if (blanks <= 2) cleaned[ci++]='\n';
                } else {
                    blanks=0;
                    cleaned[ci++]=out[i];
                }
            }
            free(out);
            out = cleaned;
            pos = ci;
        }
    }

    out[pos] = '\0';
    *out_len = pos;
    return out;
}

// ── Salva conteúdo em arquivo e reporta ───────────────────────────────────
static int save_to_file(const char *file, const char *data, size_t len,
                        const char *label, lua_State *L) {
    FILE *f = fopen(file, "wb");
    if (!f) {
        char e[256]; snprintf(e,sizeof(e),"fopen('%s'): %s",file,strerror(errno));
        lua_pushnil(L); lua_pushstring(L,e); return 2;
    }
    fwrite(data, 1, len, f);
    fclose(f);
    printf("\033[1;32m[%s] Salvo: %s (%zu bytes)\033[0m\n", label, file, len);
    lua_pushinteger(L, (lua_Integer)len);
    return 1;
}

// ── Baixa URL e retorna conteúdo bruto em memória ─────────────────────────
// fetch_raw — libcurl nativa, sem dependência de curl externo
// ua_override: string "Header: valor" ou NULL para UA padrão
static char *fetch_raw(const char *url, const char *ua_override,
                       size_t *out_len) {
    CURL *ch = curl_easy_init();
    if(!ch){ *out_len=0; return NULL; }

    CurlBuf cb = {NULL,0};
    cb.data = malloc(1); cb.data[0]='\0';

    struct curl_slist *hdrs = NULL;
    if(ua_override && strncasecmp(ua_override,"user-agent:",11)!=0) {
        /* Se não começa com "User-Agent:", usa como User-Agent direto */
        char ua_hdr[512]; snprintf(ua_hdr,sizeof(ua_hdr),"User-Agent: %s",ua_override);
        hdrs = curl_slist_append(hdrs, ua_hdr);
    } else if(ua_override) {
        hdrs = curl_slist_append(hdrs, ua_override);
    }

    curl_easy_setopt(ch, CURLOPT_URL,            url);
    curl_easy_setopt(ch, CURLOPT_FOLLOWLOCATION, 1L);
    curl_easy_setopt(ch, CURLOPT_MAXREDIRS,      8L);
    curl_easy_setopt(ch, CURLOPT_WRITEFUNCTION,  curl_write_cb);
    curl_easy_setopt(ch, CURLOPT_WRITEDATA,      &cb);
    curl_easy_setopt(ch, CURLOPT_TIMEOUT,        15L);       /* era 30 — reduzido */
    curl_easy_setopt(ch, CURLOPT_CONNECTTIMEOUT, 8L);        /* era 20 — reduzido */
    curl_easy_setopt(ch, CURLOPT_SSL_VERIFYPEER, 0L);
    curl_easy_setopt(ch, CURLOPT_SSL_VERIFYHOST, 0L);
    curl_easy_setopt(ch, CURLOPT_ACCEPT_ENCODING,"");        /* aceita gzip/br */
    curl_easy_setopt(ch, CURLOPT_USERAGENT,
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/124");
    if(hdrs) curl_easy_setopt(ch, CURLOPT_HTTPHEADER, hdrs);

    CURLcode rc = curl_easy_perform(ch);
    if(hdrs) curl_slist_free_all(hdrs);
    curl_easy_cleanup(ch);

    if(rc != CURLE_OK || !cb.data){ free(cb.data); *out_len=0; return NULL; }
    *out_len = cb.size;
    return cb.data;
}

// ============================================================================
// net.get(url [, arquivo])
//   — Baixa o CÓDIGO/CONTEÚDO da URL, não o HTML da página
//   — Se a URL já é raw (pastebin/raw, .c, .py, etc.): salva direto
//   — Se a URL é uma página HTML: extrai blocos <pre>/<code> do HTML
//   — sem arquivo: retorna string
//   — com arquivo: salva e retorna bytes escritos
// ============================================================================
/* ── Helper: aplica opções curl comuns de uma tabela Lua opcional ─────────────
 * Aceita tabela em qualquer posição >= arg_idx com campos:
 *   timeout  (int, segundos total,  padrão 15)
 *   connect  (int, segundos connect, padrão 5)
 *   headers  (tabela k=v)
 *   follow   (bool, seguir redirect, padrão true)
 *   quiet    (bool, suprime printf, padrão false)
 *   ua       (string, User-Agent customizado)
 *   file     (string, salva resposta em arquivo)
 * Retorna: quiet flag, file path (ou NULL)
 * ─────────────────────────────────────────────────────────────────────────── */
typedef struct {
    long   timeout;
    long   connect_timeout;
    int    follow;
    int    quiet;
    char   ua[256];
    char   file[512];
    struct curl_slist *hdrs;
} CurlOpts;

static CurlOpts curl_parse_opts(lua_State *L, int tbl_idx) {
    CurlOpts o;
    o.timeout         = 15L;
    o.connect_timeout = 5L;
    o.follow          = 1;
    o.quiet           = 0;
    o.file[0]         = '\0';
    o.hdrs            = NULL;
    strncpy(o.ua,
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/124",
        sizeof(o.ua)-1);

    if (tbl_idx < 1 || tbl_idx > lua_gettop(L) || !lua_istable(L, tbl_idx))
        return o;

    lua_getfield(L, tbl_idx, "timeout");
    if (lua_isnumber(L,-1)) o.timeout = (long)lua_tointeger(L,-1);
    lua_pop(L,1);

    lua_getfield(L, tbl_idx, "connect");
    if (lua_isnumber(L,-1)) o.connect_timeout = (long)lua_tointeger(L,-1);
    lua_pop(L,1);

    lua_getfield(L, tbl_idx, "follow");
    if (lua_isboolean(L,-1)) o.follow = lua_toboolean(L,-1);
    lua_pop(L,1);

    lua_getfield(L, tbl_idx, "quiet");
    if (lua_isboolean(L,-1)) o.quiet = lua_toboolean(L,-1);
    lua_pop(L,1);

    lua_getfield(L, tbl_idx, "ua");
    if (lua_isstring(L,-1)) strncpy(o.ua, lua_tostring(L,-1), sizeof(o.ua)-1);
    lua_pop(L,1);

    lua_getfield(L, tbl_idx, "file");
    if (lua_isstring(L,-1)) strncpy(o.file, lua_tostring(L,-1), sizeof(o.file)-1);
    lua_pop(L,1);

    lua_getfield(L, tbl_idx, "headers");
    if (lua_istable(L,-1)) {
        lua_pushnil(L);
        while (lua_next(L, -2)) {
            if (lua_isstring(L,-1)) {
                char hline[512]={0};
                if (lua_isstring(L,-2))
                    snprintf(hline,sizeof(hline),"%s: %s",lua_tostring(L,-2),lua_tostring(L,-1));
                else
                    snprintf(hline,sizeof(hline),"%s",lua_tostring(L,-1));
                o.hdrs = curl_slist_append(o.hdrs, hline);
            }
            lua_pop(L,1);
        }
    }
    lua_pop(L,1);
    return o;
}

static void curl_apply_opts(CURL *ch, const CurlOpts *o) {
    curl_easy_setopt(ch, CURLOPT_TIMEOUT,        o->timeout);
    curl_easy_setopt(ch, CURLOPT_CONNECTTIMEOUT, o->connect_timeout);
    curl_easy_setopt(ch, CURLOPT_FOLLOWLOCATION, (long)o->follow);
    curl_easy_setopt(ch, CURLOPT_MAXREDIRS,      5L);
    curl_easy_setopt(ch, CURLOPT_SSL_VERIFYPEER, 0L);
    curl_easy_setopt(ch, CURLOPT_SSL_VERIFYHOST, 0L);
    curl_easy_setopt(ch, CURLOPT_ACCEPT_ENCODING,"");
    curl_easy_setopt(ch, CURLOPT_USERAGENT,      o->ua);
    if (o->hdrs) curl_easy_setopt(ch, CURLOPT_HTTPHEADER, o->hdrs);
}

/* ── net.get(url [, opts_ou_arquivo])
 *   opts: tabela {timeout=5, headers={}, quiet=true, follow=true, ua="...", file="..."}
 *   compat: segundo arg string = arquivo de saída (comportamento antigo)
 * Retorna: body(string), http_code(int)  ou  nil, errmsg
 * ─────────────────────────────────────────────────────────────────────────── */
static int l_net_get(lua_State *L) {
    const char *url = luaL_checkstring(L, 1);

    /* Compatibilidade: arg2 string = arquivo (comportamento original) */
    const char *compat_file = NULL;
    CurlOpts opts;
    if (lua_gettop(L) >= 2 && lua_isstring(L,2)) {
        compat_file = lua_tostring(L,2);
        opts = curl_parse_opts(L, 0); /* defaults */
    } else {
        opts = curl_parse_opts(L, 2);
    }
    const char *outfile = compat_file ? compat_file
                        : (opts.file[0] ? opts.file : NULL);

    CURL *ch = curl_easy_init();
    if (!ch) { lua_pushnil(L); lua_pushstring(L,"curl init falhou"); return 2; }

    CurlBuf cb={NULL,0}; cb.data=malloc(1); cb.data[0]='\0';
    curl_easy_setopt(ch, CURLOPT_URL,           url);
    curl_easy_setopt(ch, CURLOPT_WRITEFUNCTION, curl_write_cb);
    curl_easy_setopt(ch, CURLOPT_WRITEDATA,     &cb);
    curl_apply_opts(ch, &opts);

    CURLcode rc = curl_easy_perform(ch);
    long code=0; curl_easy_getinfo(ch, CURLINFO_RESPONSE_CODE, &code);
    char *eff=NULL; curl_easy_getinfo(ch, CURLINFO_EFFECTIVE_URL, &eff);
    if (opts.hdrs) curl_slist_free_all(opts.hdrs);
    curl_easy_cleanup(ch);

    if (!opts.quiet) {
        printf("\033[1;36m[net.get]\033[0m %s → HTTP %ld (%zu bytes)\n", url, code, cb.size);
        if (eff && strcmp(eff,url)!=0)
            printf("\033[0;90m          → %s\033[0m\n", eff);
    }
    if (rc != CURLE_OK || !cb.data) {
        if (!opts.quiet)
            printf("\033[1;31m[net.get] erro: %s\033[0m\n", curl_easy_strerror(rc));
        free(cb.data);
        lua_pushnil(L); lua_pushstring(L, curl_easy_strerror(rc)); return 2;
    }
    if (outfile) { int r=save_to_file(outfile,cb.data,cb.size,"net.get",L); free(cb.data); return r; }
    lua_pushlstring(L, cb.data, cb.size);
    lua_pushinteger(L, code);
    free(cb.data); return 2;
}

/* ── net.geth(url [, opts])
 *   Como net.get mas retorna headers HTTP também + não printa por padrão.
 *   opts: mesma tabela de net.get + campo "headers" para enviar headers customizados
 * Retorna: body(string), http_code(int)  ou  nil, errmsg
 * ─────────────────────────────────────────────────────────────────────────── */
static int l_net_geth(lua_State *L) {
    const char *url  = luaL_checkstring(L, 1);
    const char *compat_file = NULL;
    CurlOpts opts;
    if (lua_gettop(L)>=2 && lua_isstring(L,2)) {
        compat_file = lua_tostring(L,2);
        opts = curl_parse_opts(L, 3);
    } else {
        opts = curl_parse_opts(L, 2);
    }
    const char *outfile = compat_file ? compat_file
                        : (opts.file[0] ? opts.file : NULL);

    CURL *ch = curl_easy_init();
    if (!ch) { lua_pushnil(L); lua_pushstring(L,"curl init falhou"); return 2; }

    CurlBuf cb={NULL,0}; cb.data=malloc(1); cb.data[0]='\0';
    curl_easy_setopt(ch, CURLOPT_URL,           url);
    curl_easy_setopt(ch, CURLOPT_WRITEFUNCTION, curl_write_cb);
    curl_easy_setopt(ch, CURLOPT_WRITEDATA,     &cb);
    curl_apply_opts(ch, &opts);

    CURLcode rc = curl_easy_perform(ch);
    long code=0; curl_easy_getinfo(ch, CURLINFO_RESPONSE_CODE, &code);
    if (opts.hdrs) curl_slist_free_all(opts.hdrs);
    curl_easy_cleanup(ch);

    if (!opts.quiet)
        printf("\033[1;33m[net.geth]\033[0m %s → HTTP %ld (%zu bytes)\n", url, code, cb.size);

    if (rc != CURLE_OK || !cb.data) {
        if (!opts.quiet)
            printf("\033[1;31m[net.geth] erro: %s\033[0m\n", curl_easy_strerror(rc));
        free(cb.data);
        lua_pushnil(L); lua_pushstring(L, curl_easy_strerror(rc)); return 2;
    }
    if (outfile) { int r=save_to_file(outfile,cb.data,cb.size,"net.geth",L); free(cb.data); return r; }
    lua_pushlstring(L, cb.data, cb.size);
    lua_pushinteger(L, code);
    free(cb.data); return 2;
}


/* ── net.post(url, body [, content_type [, opts]])
 *   opts: tabela {timeout, headers, quiet, ua, file}
 * Retorna: body(string), http_code(int)  ou  nil, errmsg
 * ─────────────────────────────────────────────────────────────────────────── */
static int l_net_post(lua_State *L) {
    const char *url  = luaL_checkstring(L, 1);
    size_t dlen;
    const char *data = luaL_checklstring(L, 2, &dlen);
    const char *ct   = luaL_optstring(L, 3, "application/x-www-form-urlencoded");
    CurlOpts opts    = curl_parse_opts(L, 4);

    CURL *ch = curl_easy_init();
    if (!ch) { lua_pushnil(L); lua_pushstring(L,"curl init falhou"); return 2; }

    CurlBuf cb={NULL,0}; cb.data=malloc(1); cb.data[0]='\0';

    char ct_hdr[256]; snprintf(ct_hdr, sizeof(ct_hdr), "Content-Type: %s", ct);
    opts.hdrs = curl_slist_append(opts.hdrs, ct_hdr);

    curl_easy_setopt(ch, CURLOPT_URL,            url);
    curl_easy_setopt(ch, CURLOPT_POST,           1L);
    curl_easy_setopt(ch, CURLOPT_POSTFIELDS,     data);
    curl_easy_setopt(ch, CURLOPT_POSTFIELDSIZE,  (long)dlen);
    curl_easy_setopt(ch, CURLOPT_WRITEFUNCTION,  curl_write_cb);
    curl_easy_setopt(ch, CURLOPT_WRITEDATA,      &cb);
    curl_apply_opts(ch, &opts);

    CURLcode rc = curl_easy_perform(ch);
    long code=0; curl_easy_getinfo(ch, CURLINFO_RESPONSE_CODE, &code);
    if (opts.hdrs) curl_slist_free_all(opts.hdrs);
    curl_easy_cleanup(ch);

    if (!opts.quiet)
        printf("\033[1;36m[net.post]\033[0m %s → HTTP %ld (%zu bytes)\n", url, code, cb.size);
    if (rc != CURLE_OK || !cb.data) {
        if (!opts.quiet)
            printf("\033[1;31m[net.post] erro: %s\033[0m\n", curl_easy_strerror(rc));
        free(cb.data);
        lua_pushnil(L); lua_pushstring(L, curl_easy_strerror(rc)); return 2;
    }
    lua_pushlstring(L, cb.data, cb.size);
    lua_pushinteger(L, code);
    free(cb.data); return 2;
}

/* ── net.fetch(url, opts) — interface moderna unificada ─────────────────────
 *   opts: {
 *     method  = "GET"|"POST"|"PUT"|"DELETE"|"HEAD"  (padrão "GET")
 *     body    = string  (payload para POST/PUT)
 *     timeout = int     (segundos, padrão 10)
 *     connect = int     (connect timeout, padrão 5)
 *     headers = tabela  (k=v)
 *     quiet   = bool    (sem printf, padrão false)
 *     follow  = bool    (seguir redirect, padrão true)
 *     ua      = string  (User-Agent)
 *     file    = string  (salva resposta)
 *   }
 * Retorna: body(string), http_code(int), headers_recebidos(string)
 * ─────────────────────────────────────────────────────────────────────────── */
static int l_net_fetch(lua_State *L) {
    const char *url = luaL_checkstring(L, 1);
    CurlOpts opts   = curl_parse_opts(L, 2);

    /* method */
    const char *method = "GET";
    const char *body   = NULL;
    size_t body_len    = 0;
    if (lua_gettop(L)>=2 && lua_istable(L,2)) {
        lua_getfield(L,2,"method");
        if (lua_isstring(L,-1)) method = lua_tostring(L,-1);
        lua_pop(L,1);
        lua_getfield(L,2,"body");
        if (lua_isstring(L,-1)) body = lua_tolstring(L,-1,&body_len);
        lua_pop(L,1);
    }

    /* default timeout mais curto para fetch interativo */
    if (opts.timeout == 15L) opts.timeout = 10L;

    CURL *ch = curl_easy_init();
    if (!ch) { lua_pushnil(L); lua_pushstring(L,"curl init falhou"); return 2; }

    CurlBuf cb={NULL,0}; cb.data=malloc(1); cb.data[0]='\0';
    CurlBuf hb={NULL,0}; hb.data=malloc(1); hb.data[0]='\0';

    curl_easy_setopt(ch, CURLOPT_URL,             url);
    curl_easy_setopt(ch, CURLOPT_WRITEFUNCTION,   curl_write_cb);
    curl_easy_setopt(ch, CURLOPT_WRITEDATA,       &cb);
    curl_easy_setopt(ch, CURLOPT_HEADERFUNCTION,  curl_write_cb);
    curl_easy_setopt(ch, CURLOPT_HEADERDATA,      &hb);
    curl_apply_opts(ch, &opts);

    if (strcasecmp(method,"POST")==0 || strcasecmp(method,"PUT")==0) {
        curl_easy_setopt(ch, CURLOPT_CUSTOMREQUEST, method);
        if (body) {
            curl_easy_setopt(ch, CURLOPT_POSTFIELDS,    body);
            curl_easy_setopt(ch, CURLOPT_POSTFIELDSIZE, (long)body_len);
        }
    } else if (strcasecmp(method,"HEAD")==0) {
        curl_easy_setopt(ch, CURLOPT_NOBODY, 1L);
    } else if (strcasecmp(method,"GET")!=0) {
        curl_easy_setopt(ch, CURLOPT_CUSTOMREQUEST, method);
    }

    CURLcode rc = curl_easy_perform(ch);
    long code=0; curl_easy_getinfo(ch, CURLINFO_RESPONSE_CODE, &code);
    if (opts.hdrs) curl_slist_free_all(opts.hdrs);
    curl_easy_cleanup(ch);

    if (!opts.quiet)
        printf("\033[1;36m[net.fetch]\033[0m %s %s → HTTP %ld (%zu bytes)\n",
               method, url, code, cb.size);
    if (rc != CURLE_OK || !cb.data) {
        if (!opts.quiet)
            printf("\033[1;31m[net.fetch] erro: %s\033[0m\n", curl_easy_strerror(rc));
        free(cb.data); free(hb.data);
        lua_pushnil(L); lua_pushstring(L, curl_easy_strerror(rc)); return 2;
    }
    if (opts.file[0]) { save_to_file(opts.file,cb.data,cb.size,"net.fetch",L); }

    lua_pushlstring(L, cb.data, cb.size);
    lua_pushinteger(L, code);
    lua_pushlstring(L, hb.data, hb.size);
    free(cb.data); free(hb.data);
    return 3;
}

static int l_net_import(lua_State *L) {
    const char *url = luaL_checkstring(L, 1);
    size_t len = 0;
    char *code_buf = fetch_raw(url, NULL, &len);
    if(!code_buf || len == 0){ free(code_buf); lua_pushboolean(L, 0); return 1; }
    int ok = (luaL_dostring(L, code_buf) == LUA_OK);
    lua_settop(L, 0);
    free(code_buf);
    lua_pushboolean(L, ok);
    return 1;
}
// ============================================================================
// SISTEMA DE SOCKETS ORIENTADO A OBJETO — estilo LuaSocket
// ============================================================================
//
// net.connect(host, port [, opts])    → sock  (TCP IPv4, forma mais simples)
// net.tcp(host, port [, opts])        → sock  (alias de connect)
// net.udp(host, port [, opts])        → sock  (UDP)
// net.tcp6(host, port [, opts])       → sock  (TCP IPv6)
// net.listen(port [, host])           → sock  (servidor TCP)
// net.socketex(family,type,host,port) → sock  (forma completa)
// net.socketex({...})                 → sock  (forma tabela)
//
// Todos retornam um objeto sock com métodos:
//   sock:send(data)           → bytes_enviados ou nil, err
//   sock:recv([max])          → data ou nil, err
//   sock:recvall([max])       → data completo até fechar conexão
//   sock:recvline()           → uma linha (até \n)
//   sock:lines()              → iterator — for line in sock:lines() do
//   sock:settimeout(segundos) → configura timeout
//   sock:peer()               → "host:port" do outro lado
//   sock:close()              → fecha
//   sock:closed()             → true/false
//   sock:fd()                 → file descriptor numérico
//
// Aliases para compatibilidade com código antigo:
//   net.send(fd, data)
//   net.recv(fd [, max])
//   net.close(fd)
// ============================================================================

// ── Registry key para metatable dos sockets ──────────────────────────────
#define SOCK_META "ElliotOS.Socket"

typedef struct {
    int  fd;
    int  closed;
    char host[256];
    int  port;
    char family[8];   // "ipv4","ipv6","unix"
    char stype[8];    // "stream","dgram"
} SockObj;

// ── Função interna de conexão — núcleo compartilhado ─────────────────────
static int sock_do_connect(lua_State *L,
    const char *host, int port,
    const char *family_str, const char *type_str,
    int timeout, int opt_nodelay, int opt_keepalive,
    int opt_reuseaddr,
    const char *bind_ip, int bind_port,
    const char *payload, size_t payload_len)
{
    int af    = AF_INET;
    int stype = SOCK_STREAM;

    if      (strcasecmp(family_str,"ipv6") == 0) af = AF_INET6;
    else if (strcasecmp(family_str,"unix") == 0) af = AF_UNIX;

    if (strcasecmp(type_str,"dgram") == 0 || strcasecmp(type_str,"udp") == 0)
        stype = SOCK_DGRAM;

    if (af != AF_UNIX && port <= 0) {
        lua_pushnil(L); lua_pushstring(L,"porta obrigatória para ip/domínio"); return 2;
    }

    int fd = socket(af, stype, 0);
    if (fd < 0) {
        char e[128]; snprintf(e,sizeof(e),"socket(): %s",strerror(errno));
        lua_pushnil(L); lua_pushstring(L,e); return 2;
    }

    // Opções de desempenho — aplicadas ANTES do connect para efeito imediato
    if (opt_reuseaddr) { int v=1; setsockopt(fd,SOL_SOCKET,SO_REUSEADDR,&v,sizeof(v)); }
    if (opt_keepalive) { int v=1; setsockopt(fd,SOL_SOCKET,SO_KEEPALIVE,&v,sizeof(v)); }
    /* TCP_NODELAY ativado por padrão em stream sockets — elimina delay de Nagle.
     * Isso é o principal responsável pela lentidão percebida no send() */
    if (stype==SOCK_STREAM && af!=AF_UNIX) {
        int v=1; setsockopt(fd,IPPROTO_TCP,TCP_NODELAY,&v,sizeof(v));
    }
    /* Aumenta buffers do kernel para 256KB (default é ~8-87KB dependendo do kernel)
     * Reduz stalls em transferências de dados grandes */
    { int rb=262144, sb=262144;
      setsockopt(fd,SOL_SOCKET,SO_RCVBUF,&rb,sizeof(rb));
      setsockopt(fd,SOL_SOCKET,SO_SNDBUF,&sb,sizeof(sb)); }
    // Timeout de I/O
    struct timeval tv_io; tv_io.tv_sec=timeout; tv_io.tv_usec=0;
    setsockopt(fd,SOL_SOCKET,SO_RCVTIMEO,&tv_io,sizeof(tv_io));
    setsockopt(fd,SOL_SOCKET,SO_SNDTIMEO,&tv_io,sizeof(tv_io));

    // Bind local opcional
    if (bind_ip && af==AF_INET) {
        struct sockaddr_in bsa; memset(&bsa,0,sizeof(bsa));
        bsa.sin_family=AF_INET; bsa.sin_port=htons(bind_port);
        inet_pton(AF_INET,bind_ip,&bsa.sin_addr);
        if (bind(fd,(struct sockaddr*)&bsa,sizeof(bsa))<0) {
            char e[128]; snprintf(e,sizeof(e),"bind(): %s",strerror(errno));
            close(fd); lua_pushnil(L); lua_pushstring(L,e); return 2;
        }
    }

    // Conecta
    int connect_ok = 0;

    if (af == AF_UNIX) {
        struct sockaddr_un su; memset(&su,0,sizeof(su));
        su.sun_family=AF_UNIX; strncpy(su.sun_path,host,sizeof(su.sun_path)-1);
        if (stype==SOCK_DGRAM || connect(fd,(struct sockaddr*)&su,sizeof(su))==0)
            connect_ok=1;
    } else {
        // Resolve + non-blocking connect + select
        struct addrinfo hints;
        memset(&hints,0,sizeof(hints));
        hints.ai_family   = af;
        hints.ai_socktype = stype;
        char ps[8]; snprintf(ps,sizeof(ps),"%d",port);

        struct addrinfo *res = NULL;
        int gai_rc = getaddrinfo(host, ps, &hints, &res);
        if (gai_rc == 0) {
            /* Deadline absoluto: agora + timeout segundos */
            struct timespec t0;
            clock_gettime(CLOCK_MONOTONIC, &t0);

            if (stype == SOCK_DGRAM) {
                /* UDP: connect() apenas configura endereço padrão — não bloqueia */
                for (struct addrinfo *r = res; r && !connect_ok; r = r->ai_next) {
                    if (connect(fd, r->ai_addr, r->ai_addrlen) == 0) {
                        connect_ok = 1;
                        if (payload && payload_len > 0)
                            send(fd, payload, payload_len, MSG_NOSIGNAL);
                    }
                }
                freeaddrinfo(res);
            } else {
                /* TCP: non-blocking connect + select com deadline total */
                int flg = fcntl(fd, F_GETFL, 0);
                if (flg < 0) flg = 0;
                fcntl(fd, F_SETFL, flg | O_NONBLOCK);

                for (struct addrinfo *r = res; r && !connect_ok; r = r->ai_next) {
                    /* Calcula tempo restante do deadline */
                    struct timespec now;
                    clock_gettime(CLOCK_MONOTONIC, &now);
                    long elapsed = (long)(now.tv_sec - t0.tv_sec);
                    long remain  = (long)timeout - elapsed;
                    if (remain <= 0) break; /* deadline expirado */

                    int cr = connect(fd, r->ai_addr, r->ai_addrlen);
                    int conn_errno = errno;
                    if (cr == 0 || conn_errno == EINPROGRESS || conn_errno == EINTR) {
                        fd_set ws; FD_ZERO(&ws); FD_SET(fd, &ws);
                        struct timeval tv_c;
                        tv_c.tv_sec  = remain;
                        tv_c.tv_usec = 0;
                        if (select(fd+1, NULL, &ws, NULL, &tv_c) > 0) {
                            int err = 0; socklen_t el = sizeof(err);
                            getsockopt(fd, SOL_SOCKET, SO_ERROR, &err, &el);
                            if (err == 0) { connect_ok = 1; fcntl(fd, F_SETFL, flg); }
                        }
                    }
                    if (!connect_ok) {
                        struct sockaddr sa_un; memset(&sa_un,0,sizeof(sa_un));
                        sa_un.sa_family = AF_UNSPEC;
                        connect(fd, &sa_un, sizeof(sa_un));
                    }
                }
                freeaddrinfo(res);
                if (connect_ok) fcntl(fd, F_SETFL, flg);
            }
        }
    }

    if (!connect_ok) {
        close(fd);
        lua_pushnil(L); lua_pushstring(L,"conexão falhou / timeout ou host inválido"); return 2;
    }

    // ── Cria userdata + metatable ─────────────────────────────────────────
    SockObj *s = (SockObj*)lua_newuserdata(L, sizeof(SockObj));
    s->fd     = fd;
    s->closed = 0;
    s->port   = port;
    strncpy(s->host,   host,        255);
    strncpy(s->family, family_str,  7);
    strncpy(s->stype,  type_str,    7);

    luaL_getmetatable(L, SOCK_META);
    lua_setmetatable(L, -2);
    return 1; // retorna o objeto sock
}

// ── Métodos do objeto sock ────────────────────────────────────────────────

static int sock_send(lua_State *L) {
    SockObj *s = (SockObj*)luaL_checkudata(L, 1, SOCK_META);
    if (s->closed) { lua_pushnil(L); lua_pushstring(L,"socket fechado"); return 2; }
    size_t len; const char *data = luaL_checklstring(L, 2, &len);
    /* MSG_NOSIGNAL evita SIGPIPE. Para envios grandes, envia em blocos de 64KB
     * para aproveitar o buffer do kernel sem copiar tudo de uma vez. */
    size_t total = 0;
    while (total < len) {
        size_t chunk = len - total;
        if (chunk > 65536) chunk = 65536;
        ssize_t n = send(s->fd, data + total, chunk, MSG_NOSIGNAL);
        if (n <= 0) {
            if (total > 0) { lua_pushinteger(L,(lua_Integer)total); return 1; }
            lua_pushnil(L); lua_pushstring(L, strerror(errno)); return 2;
        }
        total += (size_t)n;
    }
    lua_pushinteger(L, (lua_Integer)total);
    return 1;
}

static int sock_recv(lua_State *L) {
    SockObj *s   = (SockObj*)luaL_checkudata(L, 1, SOCK_META);
    if (s->closed) { lua_pushnil(L); lua_pushstring(L,"socket fechado"); return 2; }
    int max = (int)luaL_optinteger(L, 2, 4096);
    if (max < 1 || max > 131072) max = 4096;
    /* Stack buffer para leituras pequenas — evita malloc/free no caminho quente */
    char stack_buf[4096];
    char *buf = (max <= 4096) ? stack_buf : (char*)malloc(max + 1);
    if (!buf) { lua_pushnil(L); lua_pushstring(L,"sem memória"); return 2; }
    ssize_t n = recv(s->fd, buf, max, 0);
    if (n <= 0) {
        if (buf != stack_buf) free(buf);
        if (n == 0) { s->closed=1; lua_pushnil(L); lua_pushstring(L,"conexão fechada"); return 2; }
        lua_pushnil(L); lua_pushstring(L, strerror(errno)); return 2;
    }
    lua_pushlstring(L, buf, (size_t)n);
    if (buf != stack_buf) free(buf);
    return 1;
}

static int sock_recvall(lua_State *L) {
    SockObj *s = (SockObj*)luaL_checkudata(L, 1, SOCK_META);
    if (s->closed) { lua_pushnil(L); lua_pushstring(L,"socket fechado"); return 2; }
    int max = (int)luaL_optinteger(L, 2, 65536);
    if (max < 1 || max > 4194304) max = 65536;
    luaL_Buffer b; luaL_buffinit(L, &b);
    /* Chunk de 16KB — mais eficiente que 4KB no caminho quente de recvall */
    char buf[16384];
    ssize_t n; int total = 0;
    while (total < max) {
        int want = (int)sizeof(buf);
        if (want > max - total) want = max - total;
        n = recv(s->fd, buf, (size_t)want, 0);
        if (n <= 0) break;
        luaL_addlstring(&b, buf, (size_t)n);
        total += (int)n;
    }
    luaL_pushresult(&b);
    return 1;
}

static int sock_recvline(lua_State *L) {
    SockObj *s = (SockObj*)luaL_checkudata(L, 1, SOCK_META);
    if (s->closed) { lua_pushnil(L); lua_pushstring(L,"socket fechado"); return 2; }
    luaL_Buffer b; luaL_buffinit(L, &b);
    /* Lê byte a byte com MSG_PEEK para achar \n, depois lê o bloco inteiro.
     * Isso elimina o overhead de syscall por caractere da versão anterior. */
    char peek[256]; ssize_t n;
    while (1) {
        n = recv(s->fd, peek, sizeof(peek), MSG_PEEK);
        if (n <= 0) break;
        /* Procura \n no peek buffer */
        char *nl = (char*)memchr(peek, '\n', (size_t)n);
        size_t to_read = nl ? (size_t)(nl - peek + 1) : (size_t)n;
        char consume[256];
        ssize_t got = recv(s->fd, consume, to_read, 0);
        if (got <= 0) break;
        luaL_addlstring(&b, consume, (size_t)got);
        if (nl) break; /* linha completa */
    }
    if (n <= 0 && luaL_bufflen(&b) == 0) {
        lua_pushnil(L); lua_pushstring(L, n==0?"conexão fechada":strerror(errno)); return 2;
    }
    luaL_pushresult(&b);
    return 1;
}

// Iterator para sock:lines() — o sock fica no upvalue 1
// IMPORTANTE: Lua passa (state, control) como args 1 e 2 do iterator.
// Não podemos usar sock_recvline(L) direto pois ela busca em L,1.
// Lemos o upvalue e operamos diretamente.
static int sock_lines_iter(lua_State *L) {
    SockObj *s = (SockObj*)lua_touserdata(L, lua_upvalueindex(1));
    if (!s || s->closed) return 0;
    luaL_Buffer b; luaL_buffinit(L, &b);
    char peek[256]; ssize_t n;
    while (1) {
        n = recv(s->fd, peek, sizeof(peek), MSG_PEEK);
        if (n <= 0) break;
        char *nl = (char*)memchr(peek, '\n', (size_t)n);
        size_t to_read = nl ? (size_t)(nl - peek + 1) : (size_t)n;
        char consume[256];
        ssize_t got = recv(s->fd, consume, to_read, 0);
        if (got <= 0) break;
        luaL_addlstring(&b, consume, (size_t)got);
        if (nl) break;
    }
    if (n <= 0 && luaL_bufflen(&b) == 0) return 0;
    luaL_pushresult(&b);
    return 1;
}
static int sock_lines(lua_State *L) {
    luaL_checkudata(L, 1, SOCK_META);
    lua_pushvalue(L, 1); // sock como upvalue 1
    lua_pushcclosure(L, sock_lines_iter, 1);
    return 1;
}

static int sock_settimeout(lua_State *L) {
    SockObj *s = (SockObj*)luaL_checkudata(L, 1, SOCK_META);
    double sec  = luaL_checknumber(L, 2);
    struct timeval tv;
    tv.tv_sec  = (time_t)sec;
    tv.tv_usec = (suseconds_t)((sec - (double)tv.tv_sec) * 1e6);
    setsockopt(s->fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
    setsockopt(s->fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));
    lua_pushboolean(L, 1); return 1;
}

static int sock_peer(lua_State *L) {
    SockObj *s = (SockObj*)luaL_checkudata(L, 1, SOCK_META);
    char buf[300]; snprintf(buf, sizeof(buf), "%s:%d", s->host, s->port);
    lua_pushstring(L, buf); return 1;
}

static int sock_fd_method(lua_State *L) {
    SockObj *s = (SockObj*)luaL_checkudata(L, 1, SOCK_META);
    lua_pushinteger(L, s->fd); return 1;
}

static int sock_closed_method(lua_State *L) {
    SockObj *s = (SockObj*)luaL_checkudata(L, 1, SOCK_META);
    lua_pushboolean(L, s->closed); return 1;
}

static int sock_close(lua_State *L) {
    SockObj *s = (SockObj*)luaL_checkudata(L, 1, SOCK_META);
    if (!s->closed) { close(s->fd); s->closed=1; }
    lua_pushboolean(L, 1); return 1;
}

// __gc — fecha automaticamente ao coletar lixo
static int sock_gc(lua_State *L) {
    SockObj *s = (SockObj*)lua_touserdata(L, 1);
    if (s && !s->closed) { close(s->fd); s->closed=1; }
    return 0;
}

// __tostring
static int sock_tostring(lua_State *L) {
    SockObj *s = (SockObj*)luaL_checkudata(L, 1, SOCK_META);
    char buf[400];
    snprintf(buf, sizeof(buf), "Socket<%s/%s %s:%d fd=%d%s>",
        s->family, s->stype, s->host, s->port, s->fd,
        s->closed?" CLOSED":"");
    lua_pushstring(L, buf); return 1;
}

// sock:accept() — aceita conexão entrante (para sockets listen)
static int sock_accept(lua_State *L) {
    SockObj *s = (SockObj*)luaL_checkudata(L, 1, SOCK_META);
    if (s->closed) { lua_pushnil(L); lua_pushstring(L,"socket fechado"); return 2; }

    struct sockaddr_in cli; socklen_t clen=sizeof(cli);
    int cfd = accept(s->fd,(struct sockaddr*)&cli,&clen);
    if (cfd < 0) {
        lua_pushnil(L); lua_pushstring(L,strerror(errno)); return 2;
    }

    SockObj *c = (SockObj*)lua_newuserdata(L, sizeof(SockObj));
    c->fd=cfd; c->closed=0;
    c->port = ntohs(cli.sin_port);
    inet_ntop(AF_INET, &cli.sin_addr, c->host, sizeof(c->host));
    strncpy(c->family,"ipv4",7);
    strncpy(c->stype,"stream",7);
    luaL_getmetatable(L, SOCK_META);
    lua_setmetatable(L, -2);
    return 1;
}

// ── sock:bind(ip, port) — fixa endereço local ────────────────────────────
static int sock_bind(lua_State *L) {
    SockObj *s   = (SockObj*)luaL_checkudata(L, 1, SOCK_META);
    const char *ip = luaL_checkstring(L, 2);
    int port       = (int)luaL_checkinteger(L, 3);
    if (s->closed) { lua_pushnil(L); lua_pushstring(L,"socket fechado"); return 2; }

    struct sockaddr_in sa; memset(&sa,0,sizeof(sa));
    sa.sin_family = AF_INET;
    sa.sin_port   = htons((uint16_t)port);
    if (inet_pton(AF_INET, ip, &sa.sin_addr) <= 0) {
        lua_pushnil(L); lua_pushstring(L,"IP inválido"); return 2;
    }
    int v=1; setsockopt(s->fd, SOL_SOCKET, SO_REUSEADDR, &v, sizeof(v));
    if (bind(s->fd, (struct sockaddr*)&sa, sizeof(sa)) < 0) {
        lua_pushnil(L); lua_pushstring(L, strerror(errno)); return 2;
    }
    lua_pushboolean(L, 1); return 1;
}

// ── sock:sendto(data, host, port) — UDP sem connect prévio ───────────────
static int sock_sendto(lua_State *L) {
    SockObj *s     = (SockObj*)luaL_checkudata(L, 1, SOCK_META);
    size_t len; const char *data = luaL_checklstring(L, 2, &len);
    const char *host = luaL_checkstring(L, 3);
    int port         = (int)luaL_checkinteger(L, 4);
    if (s->closed) { lua_pushnil(L); lua_pushstring(L,"socket fechado"); return 2; }

    struct sockaddr_in dst; memset(&dst,0,sizeof(dst));
    dst.sin_family = AF_INET;
    dst.sin_port   = htons((uint16_t)port);

    /* resolve hostname */
    struct hostent *he = gethostbyname(host);
    if (!he) { lua_pushnil(L); lua_pushstring(L,"falha ao resolver host"); return 2; }
    memcpy(&dst.sin_addr, he->h_addr_list[0], sizeof(dst.sin_addr));

    ssize_t n = sendto(s->fd, data, len, MSG_NOSIGNAL,
                       (struct sockaddr*)&dst, sizeof(dst));
    if (n < 0) { lua_pushnil(L); lua_pushstring(L, strerror(errno)); return 2; }
    lua_pushinteger(L, (lua_Integer)n); return 1;
}

// ── sock:recvfrom([max]) — UDP recebe + endereço de origem ───────────────
static int sock_recvfrom(lua_State *L) {
    SockObj *s = (SockObj*)luaL_checkudata(L, 1, SOCK_META);
    int max    = (int)luaL_optinteger(L, 2, 4096);
    if (s->closed) { lua_pushnil(L); lua_pushstring(L,"socket fechado"); return 2; }
    if (max < 1 || max > 131072) max = 4096;

    char *buf = malloc(max+1);
    if (!buf) { lua_pushnil(L); lua_pushstring(L,"sem memória"); return 2; }

    struct sockaddr_in src; socklen_t slen = sizeof(src);
    ssize_t n = recvfrom(s->fd, buf, max, 0,
                         (struct sockaddr*)&src, &slen);
    if (n < 0) {
        free(buf);
        lua_pushnil(L); lua_pushstring(L, strerror(errno)); return 2;
    }
    lua_pushlstring(L, buf, (size_t)n);      /* dado */
    free(buf);
    char ipstr[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &src.sin_addr, ipstr, sizeof(ipstr));
    lua_pushstring(L, ipstr);                /* ip origem */
    lua_pushinteger(L, ntohs(src.sin_port)); /* porta origem */
    return 3; /* data, ip, port */
}

// ── sock:sendall(data) — envia tudo ou retorna erro ───────────────────────
// Diferente de send que pode enviar parcial, sendall garante entrega total.
static int sock_sendall(lua_State *L) {
    SockObj *s = (SockObj*)luaL_checkudata(L, 1, SOCK_META);
    size_t len; const char *data = luaL_checklstring(L, 2, &len);
    if (s->closed) { lua_pushnil(L); lua_pushstring(L,"socket fechado"); return 2; }

    size_t sent = 0;
    while (sent < len) {
        ssize_t n = send(s->fd, data+sent, len-sent, MSG_NOSIGNAL);
        if (n <= 0) {
            lua_pushnil(L);
            lua_pushfstring(L, "enviou %d/%d bytes: %s",
                (int)sent, (int)len, strerror(errno));
            return 2;
        }
        sent += (size_t)n;
    }
    lua_pushinteger(L, (lua_Integer)sent); return 1;
}

// ── sock:peek([max]) — lê sem consumir do buffer (MSG_PEEK) ───────────────
static int sock_peek(lua_State *L) {
    SockObj *s = (SockObj*)luaL_checkudata(L, 1, SOCK_META);
    int max    = (int)luaL_optinteger(L, 2, 4096);
    if (s->closed) { lua_pushnil(L); lua_pushstring(L,"socket fechado"); return 2; }
    if (max < 1 || max > 65536) max = 4096;

    char *buf = malloc(max+1);
    if (!buf) { lua_pushnil(L); lua_pushstring(L,"sem memória"); return 2; }
    ssize_t n = recv(s->fd, buf, max, MSG_PEEK);
    if (n < 0) { free(buf); lua_pushnil(L); lua_pushstring(L,strerror(errno)); return 2; }
    lua_pushlstring(L, buf, (size_t)n);
    free(buf); return 1;
}

// ── sock:shutdown(how) — fecha metade da conexão ─────────────────────────
// how: "r" = só leitura, "w" = só escrita, "rw" = ambos (igual close mas mantém fd)
static int sock_shutdown(lua_State *L) {
    SockObj *s       = (SockObj*)luaL_checkudata(L, 1, SOCK_META);
    const char *how  = luaL_optstring(L, 2, "rw");
    if (s->closed) { lua_pushnil(L); lua_pushstring(L,"socket fechado"); return 2; }

    int h = SHUT_RDWR;
    if (strcmp(how,"r")==0)       h = SHUT_RD;
    else if (strcmp(how,"w")==0)  h = SHUT_WR;

    if (shutdown(s->fd, h) < 0) {
        lua_pushnil(L); lua_pushstring(L, strerror(errno)); return 2;
    }
    lua_pushboolean(L, 1); return 1;
}

// ── sock:setsockopt(level, opt, val) — opções avançadas ──────────────────
// level: "socket" | "tcp" | "ip"
// opt  : "reuseaddr","keepalive","nodelay","broadcast","rcvbuf","sndbuf",
//        "rcvtimeo","sndtimeo","linger"
// val  : número (segundos para timeout, bytes para buf, 0/1 para flags)
static int sock_setsockopt_m(lua_State *L) {
    SockObj *s        = (SockObj*)luaL_checkudata(L, 1, SOCK_META);
    const char *level = luaL_checkstring(L, 2);
    const char *opt   = luaL_checkstring(L, 3);
    if (s->closed) { lua_pushnil(L); lua_pushstring(L,"socket fechado"); return 2; }

    int lvl = SOL_SOCKET;
    if      (strcasecmp(level,"tcp")==0) lvl = IPPROTO_TCP;
    else if (strcasecmp(level,"ip")==0)  lvl = IPPROTO_IP;

    /* timeout: val em segundos (float) */
    if (strcasecmp(opt,"rcvtimeo")==0 || strcasecmp(opt,"sndtimeo")==0) {
        double sec = luaL_checknumber(L, 4);
        struct timeval tv;
        tv.tv_sec  = (time_t)sec;
        tv.tv_usec = (suseconds_t)((sec-(double)tv.tv_sec)*1e6);
        int o = (strcasecmp(opt,"rcvtimeo")==0) ? SO_RCVTIMEO : SO_SNDTIMEO;
        setsockopt(s->fd, SOL_SOCKET, o, &tv, sizeof(tv));
        lua_pushboolean(L,1); return 1;
    }
    /* linger: val = segundos (0 = desativa) */
    if (strcasecmp(opt,"linger")==0) {
        int sec = (int)luaL_checkinteger(L, 4);
        struct linger lg; lg.l_onoff=(sec>0)?1:0; lg.l_linger=sec;
        setsockopt(s->fd, SOL_SOCKET, SO_LINGER, &lg, sizeof(lg));
        lua_pushboolean(L,1); return 1;
    }
    /* opções inteiras */
    int val = (int)luaL_checkinteger(L, 4);
    int optname = -1;
    if      (strcasecmp(opt,"reuseaddr")==0)  optname=SO_REUSEADDR;
    else if (strcasecmp(opt,"keepalive")==0)  optname=SO_KEEPALIVE;
    else if (strcasecmp(opt,"broadcast")==0)  optname=SO_BROADCAST;
    else if (strcasecmp(opt,"rcvbuf")==0)     optname=SO_RCVBUF;
    else if (strcasecmp(opt,"sndbuf")==0)     optname=SO_SNDBUF;
    else if (strcasecmp(opt,"nodelay")==0)  { lvl=IPPROTO_TCP; optname=TCP_NODELAY; }
    else {
        lua_pushnil(L);
        lua_pushfstring(L,"opção desconhecida: %s", opt);
        return 2;
    }
    setsockopt(s->fd, lvl, optname, &val, sizeof(val));
    lua_pushboolean(L,1); return 1;
}

// ── sock:getsockopt(level, opt) — lê opção atual ─────────────────────────
static int sock_getsockopt_m(lua_State *L) {
    SockObj *s        = (SockObj*)luaL_checkudata(L, 1, SOCK_META);
    const char *level = luaL_checkstring(L, 2);
    const char *opt   = luaL_checkstring(L, 3);
    if (s->closed) { lua_pushnil(L); lua_pushstring(L,"socket fechado"); return 2; }

    int lvl = SOL_SOCKET;
    if      (strcasecmp(level,"tcp")==0) lvl = IPPROTO_TCP;
    else if (strcasecmp(level,"ip")==0)  lvl = IPPROTO_IP;

    int optname = -1;
    if      (strcasecmp(opt,"reuseaddr")==0) optname=SO_REUSEADDR;
    else if (strcasecmp(opt,"keepalive")==0) optname=SO_KEEPALIVE;
    else if (strcasecmp(opt,"broadcast")==0) optname=SO_BROADCAST;
    else if (strcasecmp(opt,"rcvbuf")==0)    optname=SO_RCVBUF;
    else if (strcasecmp(opt,"sndbuf")==0)    optname=SO_SNDBUF;
    else if (strcasecmp(opt,"error")==0)     optname=SO_ERROR;
    else if (strcasecmp(opt,"nodelay")==0) { lvl=IPPROTO_TCP; optname=TCP_NODELAY; }
    else { lua_pushnil(L); lua_pushfstring(L,"opção desconhecida: %s",opt); return 2; }

    int val=0; socklen_t vlen=sizeof(val);
    getsockopt(s->fd, lvl, optname, &val, &vlen);
    lua_pushinteger(L, val); return 1;
}

// ── sock:wait([timeout]) — aguarda dado disponível (select) ──────────────
// Retorna true se há dado pra ler, false se timeout, nil+err se erro.
static int sock_wait(lua_State *L) {
    SockObj *s = (SockObj*)luaL_checkudata(L, 1, SOCK_META);
    double sec = luaL_optnumber(L, 2, 5.0);
    if (s->closed) { lua_pushnil(L); lua_pushstring(L,"socket fechado"); return 2; }

    fd_set rfds; FD_ZERO(&rfds); FD_SET(s->fd, &rfds);
    struct timeval tv;
    tv.tv_sec  = (time_t)sec;
    tv.tv_usec = (suseconds_t)((sec-(double)tv.tv_sec)*1e6);
    int r = select(s->fd+1, &rfds, NULL, NULL, &tv);
    if (r < 0)  { lua_pushnil(L); lua_pushstring(L,strerror(errno)); return 2; }
    lua_pushboolean(L, r > 0); return 1;
}

// ── sock:local() — endereço local real (após bind/connect) ────────────────
static int sock_local(lua_State *L) {
    SockObj *s = (SockObj*)luaL_checkudata(L, 1, SOCK_META);
    struct sockaddr_in sa; socklen_t sl = sizeof(sa);
    if (getsockname(s->fd,(struct sockaddr*)&sa,&sl) < 0) {
        lua_pushnil(L); lua_pushstring(L,strerror(errno)); return 2;
    }
    char ip[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &sa.sin_addr, ip, sizeof(ip));
    lua_pushstring(L, ip);
    lua_pushinteger(L, ntohs(sa.sin_port));
    return 2; /* ip, port */
}

// ── sock:info() — tabela com todos os detalhes do socket ─────────────────
static int sock_info(lua_State *L) {
    SockObj *s = (SockObj*)luaL_checkudata(L, 1, SOCK_META);
    lua_newtable(L);
    lua_pushstring(L, s->host);   lua_setfield(L,-2,"host");
    lua_pushinteger(L, s->port);  lua_setfield(L,-2,"port");
    lua_pushstring(L, s->family); lua_setfield(L,-2,"family");
    lua_pushstring(L, s->stype);  lua_setfield(L,-2,"type");
    lua_pushinteger(L, s->fd);    lua_setfield(L,-2,"fd");
    lua_pushboolean(L, s->closed);lua_setfield(L,-2,"closed");
    /* endereço local */
    struct sockaddr_in sa; socklen_t sl=sizeof(sa);
    if (getsockname(s->fd,(struct sockaddr*)&sa,&sl)==0) {
        char ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET,&sa.sin_addr,ip,sizeof(ip));
        lua_pushstring(L,ip);                    lua_setfield(L,-2,"local_ip");
        lua_pushinteger(L,ntohs(sa.sin_port));   lua_setfield(L,-2,"local_port");
    }
    /* erro pendente */
    int err=0; socklen_t el=sizeof(err);
    getsockopt(s->fd,SOL_SOCKET,SO_ERROR,&err,&el);
    lua_pushinteger(L,err); lua_setfield(L,-2,"error");
    /* rcvbuf / sndbuf */
    int rb=0,sb=0; socklen_t rl=sizeof(rb),sbl=sizeof(sb);
    getsockopt(s->fd,SOL_SOCKET,SO_RCVBUF,&rb,&rl);
    getsockopt(s->fd,SOL_SOCKET,SO_SNDBUF,&sb,&sbl);
    lua_pushinteger(L,rb); lua_setfield(L,-2,"rcvbuf");
    lua_pushinteger(L,sb); lua_setfield(L,-2,"sndbuf");
    return 1;
}


// Registra a metatable do objeto sock
static void sock_register_meta(lua_State *L) {
    luaL_newmetatable(L, SOCK_META);
    // __index aponta para a própria metatable (métodos)
    lua_pushvalue(L, -1);
    lua_setfield(L, -2, "__index");

    lua_pushcfunction(L, sock_send);          lua_setfield(L, -2, "send");
    lua_pushcfunction(L, sock_sendall);       lua_setfield(L, -2, "sendall");
    lua_pushcfunction(L, sock_sendto);        lua_setfield(L, -2, "sendto");
    lua_pushcfunction(L, sock_recv);          lua_setfield(L, -2, "recv");
    lua_pushcfunction(L, sock_recvall);       lua_setfield(L, -2, "recvall");
    lua_pushcfunction(L, sock_recvline);      lua_setfield(L, -2, "recvline");
    lua_pushcfunction(L, sock_recvfrom);      lua_setfield(L, -2, "recvfrom");
    lua_pushcfunction(L, sock_peek);          lua_setfield(L, -2, "peek");
    lua_pushcfunction(L, sock_lines);         lua_setfield(L, -2, "lines");
    lua_pushcfunction(L, sock_wait);          lua_setfield(L, -2, "wait");
    lua_pushcfunction(L, sock_bind);          lua_setfield(L, -2, "bind");
    lua_pushcfunction(L, sock_shutdown);      lua_setfield(L, -2, "shutdown");
    lua_pushcfunction(L, sock_settimeout);    lua_setfield(L, -2, "settimeout");
    lua_pushcfunction(L, sock_setsockopt_m);  lua_setfield(L, -2, "setsockopt");
    lua_pushcfunction(L, sock_getsockopt_m);  lua_setfield(L, -2, "getsockopt");
    lua_pushcfunction(L, sock_local);         lua_setfield(L, -2, "local");
    lua_pushcfunction(L, sock_info);          lua_setfield(L, -2, "info");
    lua_pushcfunction(L, sock_peer);          lua_setfield(L, -2, "peer");
    lua_pushcfunction(L, sock_fd_method);     lua_setfield(L, -2, "fd");
    lua_pushcfunction(L, sock_closed_method); lua_setfield(L, -2, "closed");
    lua_pushcfunction(L, sock_close);         lua_setfield(L, -2, "close");
    lua_pushcfunction(L, sock_accept);        lua_setfield(L, -2, "accept");
    lua_pushcfunction(L, sock_gc);            lua_setfield(L, -2, "__gc");
    lua_pushcfunction(L, sock_tostring);      lua_setfield(L, -2, "__tostring");
    lua_pop(L, 1); // pop metatable
}

// ── net.connect(host, port [, timeout]) — TCP IPv4 simples ───────────────
static int l_net_connect(lua_State *L) {
    const char *host = luaL_checkstring(L, 1);
    int port         = (int)luaL_checkinteger(L, 2);
    int timeout      = (int)luaL_optinteger(L, 3, 5);
    return sock_do_connect(L, host, port, "ipv4", "stream", timeout, 0, 0, 1, NULL, 0, NULL, 0);
}

// ── net.tcp(host, port [, timeout]) — alias de connect ───────────────────
static int l_net_tcp(lua_State *L) { return l_net_connect(L); }

// ── net.udp(host, port [, timeout]) ──────────────────────────────────────
static int l_net_udp(lua_State *L) {
    const char *host = luaL_checkstring(L, 1);
    int port         = (int)luaL_checkinteger(L, 2);
    int timeout      = (int)luaL_optinteger(L, 3, 5);
    return sock_do_connect(L, host, port, "ipv4", "dgram", timeout, 0, 0, 1, NULL, 0, NULL, 0);
}

// ── net.tcp6(host, port [, timeout]) ─────────────────────────────────────
static int l_net_tcp6(lua_State *L) {
    const char *host = luaL_checkstring(L, 1);
    int port         = (int)luaL_checkinteger(L, 2);
    int timeout      = (int)luaL_optinteger(L, 3, 5);
    return sock_do_connect(L, host, port, "ipv6", "stream", timeout, 0, 0, 1, NULL, 0, NULL, 0);
}

// ── net.listen(port [, host [, backlog]]) — servidor TCP ─────────────────
static int l_net_listen(lua_State *L) {
    int port          = (int)luaL_checkinteger(L, 1);
    const char *host  = luaL_optstring(L, 2, "0.0.0.0");
    int backlog       = (int)luaL_optinteger(L, 3, 5);

    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) { lua_pushnil(L); lua_pushstring(L,strerror(errno)); return 2; }
    int v=1; setsockopt(fd,SOL_SOCKET,SO_REUSEADDR,&v,sizeof(v));

    struct sockaddr_in sa; memset(&sa,0,sizeof(sa));
    sa.sin_family=AF_INET; sa.sin_port=htons(port);
    inet_pton(AF_INET, host, &sa.sin_addr);

    if (bind(fd,(struct sockaddr*)&sa,sizeof(sa))<0) {
        char e[128]; snprintf(e,sizeof(e),"bind(): %s",strerror(errno));
        close(fd); lua_pushnil(L); lua_pushstring(L,e); return 2;
    }
    if (listen(fd, backlog)<0) {
        char e[128]; snprintf(e,sizeof(e),"listen(): %s",strerror(errno));
        close(fd); lua_pushnil(L); lua_pushstring(L,e); return 2;
    }

    SockObj *s = (SockObj*)lua_newuserdata(L, sizeof(SockObj));
    s->fd=fd; s->closed=0; s->port=port;
    strncpy(s->host, host, 255);
    strncpy(s->family, "ipv4", 7);
    strncpy(s->stype, "listen", 7);
    luaL_getmetatable(L, SOCK_META);
    lua_setmetatable(L, -2);

    printf("\033[1;32m[net] Ouvindo em %s:%d\033[0m\n", host, port);
    return 1;
}

/* ── progress_bar — barra de progresso em tempo real ─────────────────────────
   Imprime na mesma linha com \r. Chama fflush(stdout) no fim.
   clear=1 → apaga a linha inteira (para imprimir resultado e depois repintar).
   ─────────────────────────────────────────────────────────────────────────── */
static void progress_bar(int done, int total, const char *label) {
    if (total <= 0) return;
    const int W = 26; /* largura da barra em células */
    int filled = (int)((long)done * W / total);
    if (filled > W) filled = W;
    /* apaga linha anterior */
    printf("\r\033[2K  \033[1;34m[");
    for (int i = 0; i < W; i++) {
        if (i < filled)
            printf("\xe2\x96\x88");   /* █ bloco cheio  */
        else
            printf("\xe2\x96\x91");   /* ░ bloco vazio  */
    }
    printf("]\033[0m  %s \033[1;33m%d\033[0m/\033[0;37m%d\033[0m  ",
           label, done, total);
    fflush(stdout);
}

/* ── progress_clear — apaga a linha da barra antes de imprimir resultado ──── */
static void progress_clear(void) {
    printf("\r\033[2K");
    fflush(stdout);
}

/* ── net_syn_probe — SYN sem root ────────────────────────────────────────────
   Usa connect() não-bloqueante: o kernel envia SYN, nós lemos SO_ERROR
   e fechamos com SO_LINGER={1,0} (RST imediato) antes do ACK final.
   Retorno: "open" | "closed" | "filtered"
   Latência em ms gravada em *out_ms se não NULL.
   ─────────────────────────────────────────────────────────────────────────── */
static const char *net_syn_probe(const char *host, int port,
                                 const char *family, int timeout_s,
                                 double *out_ms) {
    int af = (family && strcasecmp(family,"ipv6")==0) ? AF_INET6 : AF_INET;
    struct addrinfo hints_sp, *res_sp = NULL;
    memset(&hints_sp, 0, sizeof(hints_sp));
    hints_sp.ai_family   = af;
    hints_sp.ai_socktype = SOCK_STREAM;
    char ps_sp[8]; snprintf(ps_sp, sizeof(ps_sp), "%d", port);
    if (getaddrinfo(host, ps_sp, &hints_sp, &res_sp) != 0 || !res_sp)
        return NULL; /* não resolveu */

    int fd_sp = socket(af, SOCK_STREAM, 0);
    if (fd_sp < 0) { freeaddrinfo(res_sp); return NULL; }

    int flg_sp = fcntl(fd_sp, F_GETFL, 0); if (flg_sp < 0) flg_sp = 0;
    fcntl(fd_sp, F_SETFL, flg_sp | O_NONBLOCK);

    struct timeval t_sp0, t_sp1;
    gettimeofday(&t_sp0, NULL);

    /* connect() envia o SYN — retorna EINPROGRESS (normal) */
    connect(fd_sp, res_sp->ai_addr, res_sp->ai_addrlen);
    freeaddrinfo(res_sp);

    /* aguarda SYN-ACK ou RST via select() */
    fd_set wfds_sp;
    FD_ZERO(&wfds_sp); FD_SET(fd_sp, &wfds_sp);
    struct timeval tv_sp = {(timeout_s > 0 ? timeout_s : 5), 0};
    const char *sp_status = "filtered";
    int sel_sp = select(fd_sp + 1, NULL, &wfds_sp, NULL, &tv_sp);
    if (sel_sp > 0) {
        int err_sp = 0; socklen_t el_sp = sizeof(err_sp);
        getsockopt(fd_sp, SOL_SOCKET, SO_ERROR, &err_sp, &el_sp);
        sp_status = (err_sp == 0)            ? "open"
                  : (err_sp == ECONNREFUSED) ? "closed"
                  :                            "filtered";
    }

    /* SO_LINGER {1,0} → RST imediato ao close(), sem ACK final */
    struct linger sl_sp = {1, 0};
    setsockopt(fd_sp, SOL_SOCKET, SO_LINGER, &sl_sp, sizeof(sl_sp));
    close(fd_sp);

    gettimeofday(&t_sp1, NULL);
    if (out_ms)
        *out_ms = (t_sp1.tv_sec  - t_sp0.tv_sec)  * 1000.0
                + (t_sp1.tv_usec - t_sp0.tv_usec)  / 1000.0;
    return sp_status;
}

// ── net.socketex — forma completa (tabela ou posicional) ─────────────────
static int l_net_socketex(lua_State *L) {
    // Formato posicional: net.socketex(family, type, host, port [,timeout [,payload]])
    if (lua_type(L, 1) == LUA_TSTRING) {
        const char *family  = luaL_checkstring(L, 1);
        const char *stype   = luaL_checkstring(L, 2);
        const char *host    = luaL_checkstring(L, 3);
        int port            = (int)luaL_checkinteger(L, 4);
        int timeout         = (int)luaL_optinteger(L, 5, 5);
        const char *payload = luaL_optstring(L, 6, NULL);
        (void)payload; // payload via send após conectar
        size_t pl_len=0;
        const char *pl = payload ? payload : NULL;
        if(pl) pl_len=strlen(pl);
        /* SYN probe — retorna tabela {status,host,port,ms,open} */
        if (strcasecmp(stype,"syn")==0) {
            double sx_ms = 0.0;
            const char *sx_st = net_syn_probe(host, port, family,
                                              (timeout > 0 ? timeout : 5), &sx_ms);
            if (!sx_st) {
                lua_pushnil(L);
                lua_pushfstring(L, "não resolveu: %s", host);
                return 2;
            }
            lua_newtable(L);
            lua_pushstring(L, sx_st);                              lua_setfield(L,-2,"status");
            lua_pushstring(L, host);                               lua_setfield(L,-2,"host");
            lua_pushinteger(L, port);                              lua_setfield(L,-2,"port");
            lua_pushnumber(L, sx_ms);                              lua_setfield(L,-2,"ms");
            lua_pushboolean(L, strcmp(sx_st,"open")==0);           lua_setfield(L,-2,"open");
            return 1;
        }
        return sock_do_connect(L, host, port, family, stype, timeout, 0, 0, 1, NULL, 0, pl, pl_len);
    }

    // Formato tabela: net.socketex({host=..., port=..., ...})
    luaL_checktype(L, 1, LUA_TTABLE);

    lua_getfield(L,1,"host");
    if (!lua_isstring(L,-1)) { lua_pop(L,1); lua_pushnil(L); lua_pushstring(L,"opts.host obrigatório"); return 2; }
    const char *host = lua_tostring(L,-1); lua_pop(L,1);

    lua_getfield(L,1,"port");    int port    = lua_isnumber(L,-1)  ? (int)lua_tointeger(L,-1) : 0;   lua_pop(L,1);
    lua_getfield(L,1,"family");  const char *fam = lua_isstring(L,-1) ? lua_tostring(L,-1) : "ipv4"; lua_pop(L,1);
    lua_getfield(L,1,"type");    const char *typ = lua_isstring(L,-1) ? lua_tostring(L,-1) : "stream";lua_pop(L,1);
    lua_getfield(L,1,"timeout"); int timeout = lua_isnumber(L,-1)  ? (int)lua_tointeger(L,-1) : 5;   lua_pop(L,1);
    lua_getfield(L,1,"nodelay"); int nodelay = lua_isboolean(L,-1) ? lua_toboolean(L,-1) : 0;         lua_pop(L,1);
    lua_getfield(L,1,"keepalive");int keepalive=lua_isboolean(L,-1)?lua_toboolean(L,-1):0;            lua_pop(L,1);
    lua_getfield(L,1,"bind");    const char *bip = lua_isstring(L,-1) ? lua_tostring(L,-1) : NULL;    lua_pop(L,1);
    lua_getfield(L,1,"bindport");int bport   = lua_isnumber(L,-1)  ? (int)lua_tointeger(L,-1) : 0;   lua_pop(L,1);

    /* SYN probe via formato tabela */
    if (strcasecmp(typ,"syn")==0) {
        double xt_ms = 0.0;
        const char *xt_st = net_syn_probe(host, port, fam,
                                          (timeout > 0 ? timeout : 5), &xt_ms);
        if (!xt_st) {
            lua_pushnil(L);
            lua_pushfstring(L, "não resolveu: %s", host);
            return 2;
        }
        lua_newtable(L);
        lua_pushstring(L, xt_st);                              lua_setfield(L,-2,"status");
        lua_pushstring(L, host);                               lua_setfield(L,-2,"host");
        lua_pushinteger(L, port);                              lua_setfield(L,-2,"port");
        lua_pushnumber(L, xt_ms);                              lua_setfield(L,-2,"ms");
        lua_pushboolean(L, strcmp(xt_st,"open")==0);           lua_setfield(L,-2,"open");
        return 1;
    }
    return sock_do_connect(L, host, port, fam, typ, timeout, nodelay, keepalive, 1, bip, bport, NULL, 0);
}

// ── Aliases de compatibilidade (código antigo com fd numérico) ────────────
static int l_net_send(lua_State *L) {
    // Aceita sock:send() via metatable OU net.send(fd, data) antigo
    if (lua_type(L,1) == LUA_TNUMBER) {
        int fd = (int)luaL_checkinteger(L,1);
        size_t len; const char *data = luaL_checklstring(L,2,&len);
        ssize_t n = send(fd,data,len,MSG_NOSIGNAL);
        if (n<0){lua_pushnil(L);lua_pushstring(L,strerror(errno));return 2;}
        lua_pushinteger(L,(lua_Integer)n); return 1;
    }
    return sock_send(L);
}
static int l_net_recv(lua_State *L) {
    if (lua_type(L,1) == LUA_TNUMBER) {
        int fd = (int)luaL_checkinteger(L,1);
        int max = (int)luaL_optinteger(L,2,4096);
        if (max>65536) max=65536;
        char *buf=malloc(max+1); if(!buf){lua_pushnil(L);return 1;}
        ssize_t n=recv(fd,buf,max,0);
        if(n<=0){free(buf);lua_pushnil(L);lua_pushstring(L,n==0?"conexão fechada":strerror(errno));return 2;}
        lua_pushlstring(L,buf,(size_t)n); free(buf); return 1;
    }
    return sock_recv(L);
}
static int l_net_close(lua_State *L) {
    if (lua_type(L,1) == LUA_TNUMBER) {
        lua_pushboolean(L, close((int)luaL_checkinteger(L,1))==0); return 1;
    }
    return sock_close(L);
}

// ── net.socket — fire-and-forget: conecta, envia, recebe, fecha ──────────
/* ── net.socket — fire-and-forget ────────────────────────────────────────────
   Conecta, envia payload opcional, lê resposta, fecha. Tudo numa chamada.

   net.socket(family, type, host, port [, timeout [, payload]])
     family  : "ipv4" | "ipv6" | "unix"
     type    : "stream" | "tcp" | "dgram" | "udp"
     host    : IP ou hostname
     port    : número da porta
     timeout : segundos (padrão 5)
     payload : string a enviar logo após conectar (opcional)

   Retorna: resposta (string) ou nil, errmsg

   Exemplos:
     net.socket("ipv4","stream","1.1.1.1",80,3,"GET / HTTP/1.0\r\nHost: 1.1.1.1\r\n\r\n")
     net.socket("ipv4","dgram","8.8.8.8",53,3)          -- só conecta/testa
     net.socket("ipv4","stream","192.168.1.1",22)        -- banner grab SSH
   ─────────────────────────────────────────────────────────────────────────── */
static int l_net_socket(lua_State *L) {
    const char *family  = luaL_checkstring(L, 1);
    const char *stype   = luaL_checkstring(L, 2);
    const char *host    = luaL_checkstring(L, 3);
    int port            = (int)luaL_checkinteger(L, 4);
    int timeout         = (int)luaL_optinteger(L, 5, 5);
    size_t pl_len = 0;
    const char *payload = NULL;
    if (lua_gettop(L) >= 6 && lua_type(L, 6) == LUA_TSTRING)
        payload = lua_tolstring(L, 6, &pl_len);

    int af    = AF_INET;
    int st    = SOCK_STREAM;
    if (strcasecmp(family,"ipv6")==0) af = AF_INET6;
    if (strcasecmp(stype,"dgram")==0||strcasecmp(stype,"udp")==0) st = SOCK_DGRAM;

    /* SYN probe — connect() não-bloqueante sem root; fecha com RST antes do ACK */
    if (strcasecmp(stype,"syn")==0) {
        double syn_ms = 0.0;
        const char *syn_st = net_syn_probe(host, port, family,
                                           (timeout > 0 ? timeout : 5), &syn_ms);
        if (!syn_st) {
            lua_pushnil(L);
            lua_pushfstring(L, "não resolveu: %s", host);
            return 2;
        }
        const char *syn_color =
            (strcmp(syn_st,"open")   == 0) ? "\033[1;32m" :
            (strcmp(syn_st,"closed") == 0) ? "\033[1;31m" : "\033[1;33m";
        char syn_out[192] = {0};
        snprintf(syn_out, sizeof(syn_out),
            "[SYN] %s:%d \xe2\x86\x92 %s%s\033[0m (+%.0fms)",
            host, port, syn_color, syn_st, syn_ms);
        lua_pushstring(L, syn_out);
        return 1;
    }

    /* resolve */
    struct addrinfo hints, *res = NULL;
    memset(&hints,0,sizeof(hints));
    hints.ai_family   = af;
    hints.ai_socktype = st;
    char ps[8]; snprintf(ps,sizeof(ps),"%d",port);
    if (getaddrinfo(host, ps, &hints, &res) != 0 || !res) {
        lua_pushnil(L);
        lua_pushfstring(L,"não resolveu: %s", host);
        return 2;
    }

    int fd = socket(af, st, 0);
    if (fd < 0) {
        freeaddrinfo(res);
        lua_pushnil(L); lua_pushstring(L, strerror(errno)); return 2;
    }

    /* TCP_NODELAY: sem delay de Nagle — crítico para latência do fire-and-forget */
    if (st == SOCK_STREAM) { int v=1; setsockopt(fd,IPPROTO_TCP,TCP_NODELAY,&v,sizeof(v)); }
    /* Buffers 256KB */
    { int rb=262144,sb=262144;
      setsockopt(fd,SOL_SOCKET,SO_RCVBUF,&rb,sizeof(rb));
      setsockopt(fd,SOL_SOCKET,SO_SNDBUF,&sb,sizeof(sb)); }
    /* timeout de I/O */
    struct timeval tv = {timeout, 0};
    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
    setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));

    /* conecta */
    int ok = 0;
    if (st == SOCK_DGRAM) {
        /* UDP: connect() apenas associa destino — não abre conexão real
         * Em algumas redes/kernels pode falhar com ENETUNREACH ou EPERM
         * Nesse caso ainda tenta send() diretamente com sendto() */
        int conn_ret = connect(fd, res->ai_addr, res->ai_addrlen);
        if (conn_ret == 0) {
            ok = 1;
            /* Sem payload: envia 1 byte nulo para o pacote realmente sair */
            if (!payload || pl_len == 0) {
                char nul = 0;
                send(fd, &nul, 1, MSG_NOSIGNAL);
            }
        } else {
            /* connect() falhou — tenta sendto() diretamente (bypassa connect) */
            char nul = 0;
            ssize_t sr = sendto(fd, payload&&pl_len>0 ? payload : &nul,
                                payload&&pl_len>0 ? pl_len : 1,
                                MSG_NOSIGNAL, res->ai_addr, res->ai_addrlen);
            ok = (sr > 0);
            if (!ok) {
                /* último recurso: marca ok=1 mesmo assim — UDP é connectionless */
                ok = 1;
            }
        }
    } else {
        /* TCP: non-blocking connect + select */
        int flg = fcntl(fd, F_GETFL, 0); if (flg<0) flg=0;
        fcntl(fd, F_SETFL, flg | O_NONBLOCK);
        connect(fd, res->ai_addr, res->ai_addrlen);
        fd_set wfds; FD_ZERO(&wfds); FD_SET(fd, &wfds);
        struct timeval tv2 = {timeout, 0};
        if (select(fd+1, NULL, &wfds, NULL, &tv2) > 0) {
            int err=0; socklen_t el=sizeof(err);
            getsockopt(fd,SOL_SOCKET,SO_ERROR,&err,&el);
            ok = (err == 0);
        }
        fcntl(fd, F_SETFL, flg); /* restaura modo bloqueante */
    }
    freeaddrinfo(res);

    if (!ok) {
        close(fd);
        lua_pushnil(L); lua_pushstring(L,"conexão recusada ou timeout"); return 2;
    }

    /* envia payload se houver */
    if (payload && pl_len > 0) {
        size_t sent = 0;
        while (sent < pl_len) {
            ssize_t n = send(fd, payload + sent, pl_len - sent, MSG_NOSIGNAL);
            if (n <= 0) break;
            sent += (size_t)n;
        }
    }

    /* lê resposta em buffer de 128KB alocado uma vez */
    char *buf = malloc(131072);
    if (!buf) { close(fd); lua_pushnil(L); lua_pushstring(L,"malloc"); return 2; }
    ssize_t total = 0;

    struct timeval t_start, t_end;
    gettimeofday(&t_start, NULL);

    if (st == SOCK_DGRAM) {
        /* UDP: recv único com timeout de 1s */
        struct timeval tv_udp = {1, 0};
        setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv_udp, sizeof(tv_udp));
        ssize_t n = recv(fd, buf, 131071, 0);
        if (n > 0) { total = n; buf[total] = '\0'; }
    } else {
        /* TCP: usa select() para detectar se há dados disponíveis
         * antes de bloquear no recv — evita ficar preso em servidores
         * que esperam payload (HTTP, TLS) antes de responder */
        fd_set rfds;
        struct timeval tv_sel = {timeout, 0};
        FD_ZERO(&rfds); FD_SET(fd, &rfds);
        int sel = select(fd+1, &rfds, NULL, NULL, &tv_sel);
        if (sel > 0) {
            /* há dados — lê tudo disponível */
            while (total < 131071) {
                /* verifica se ainda há dados sem bloquear */
                fd_set rfds2; FD_ZERO(&rfds2); FD_SET(fd,&rfds2);
                struct timeval tv2 = {0, 200000}; /* 200ms entre chunks */
                if(select(fd+1,&rfds2,NULL,NULL,&tv2)<=0) break;
                ssize_t n = recv(fd, buf+total, 131071-total, 0);
                if (n <= 0) break;
                total += n;
            }
        }
        /* sel == 0: timeout expirou sem dados (servidor esperando payload) */
        /* sel < 0: erro de socket */
    }
    close(fd);
    gettimeofday(&t_end, NULL);

    /* calcula tempo decorrido */
    double elapsed = (t_end.tv_sec  - t_start.tv_sec) +
                     (t_end.tv_usec - t_start.tv_usec) / 1e6;
    char timer_str[32]={0};
    if(elapsed < 1.0) snprintf(timer_str,sizeof(timer_str),"%.0fms",(elapsed*1000));
    else              snprintf(timer_str,sizeof(timer_str),"%.2fs",elapsed);

    if (total > 0) {
        /* retorna resposta + timer no final */
        char *out = malloc(total + 64);
        if(out) {
            memcpy(out, buf, total);
            snprintf(out+total, 63, "\n[%s %s +%s]",
                     st==SOCK_DGRAM?"UDP":"TCP", "resposta recebida", timer_str);
            lua_pushstring(L, out);
            free(out);
        } else {
            lua_pushlstring(L, buf, (size_t)total);
        }
        free(buf);
        return 1;
    }
    free(buf);

    /* sem resposta — mensagem com timer */
    char msg[154]={0};
    if (st == SOCK_DGRAM)
        snprintf(msg,sizeof(msg),"[UDP] pacote enviado — sem resposta (+%s)",timer_str);
    else
        snprintf(msg,sizeof(msg),
            "[TCP] conectado — servidor não enviou dados (+%s)\n"
            "      TLS/HTTPS? Use payload: ms --socket ipv4 stream host 443 5 'GET / HTTP/1.0\\r\\n\\r\\n'",
            timer_str);
    lua_pushstring(L, msg);
    return 1;
}

static int l_net_scan(lua_State *L) {
    const char *host = luaL_checkstring(L, 1);
    int from = (int)luaL_optinteger(L, 2, 1);
    int to   = (int)luaL_optinteger(L, 3, 1024);
    if (from < 1)     from = 1;
    if (to   > 65535) to   = 65535;
    if (from > to)    { int t=from; from=to; to=t; }

    /* Resolve hostname uma vez */
    struct addrinfo hints, *res0=NULL;
    memset(&hints,0,sizeof(hints));
    hints.ai_family=AF_INET; hints.ai_socktype=SOCK_STREAM;
    char ps[8]; snprintf(ps,sizeof(ps),"80");
    if(getaddrinfo(host,ps,&hints,&res0)!=0 || !res0){
        printf("\033[1;31m[!] net.scan: não resolveu '%s'\033[0m\n",host);
        lua_newtable(L); return 1;
    }
    struct sockaddr_in resolved_sa;
    memset(&resolved_sa,0,sizeof(resolved_sa));
    resolved_sa.sin_family=AF_INET;
    memcpy(&resolved_sa.sin_addr,&((struct sockaddr_in*)res0->ai_addr)->sin_addr,
           sizeof(resolved_sa.sin_addr));
    char ip_str[INET_ADDRSTRLEN]={0};
    inet_ntop(AF_INET,&resolved_sa.sin_addr,ip_str,sizeof(ip_str));
    freeaddrinfo(res0);

    int total_ports=to-from+1;
    if(total_ports<=0){lua_newtable(L);return 1;}

    int *open_ports=(int*)calloc((size_t)total_ports,sizeof(int));
    if(!open_ports){lua_newtable(L);return 1;}

    printf("\n\033[1;33m[*] net.scan (SYN) — %s (%s) portas %d-%d\033[0m\n\n",
           host,ip_str,from,to);

    struct timeval scan_t0, scan_t1;
    gettimeofday(&scan_t0, NULL);

    /* Batch de 512 — mais paralelo sem estourar ulimit -n
     * Android/Termux default: 32768 fds disponíveis, 512 por batch é seguro.
     * poll() em vez de select() para não ter limite de FD_SETSIZE. */
    #define SCAN_BATCH 512
    int batch_fds[SCAN_BATCH];
    int batch_ports[SCAN_BATCH];
    struct pollfd pfds[SCAN_BATCH];
    int open_count=0;
    int scan_total = to - from + 1;   /* total de portas a escanear */
    int scan_done  = 0;               /* portas já processadas      */

    int port=from;
    while(port<=to){
        int n_batch=0;
        while(n_batch<SCAN_BATCH && port<=to){
            /* SOCK_NONBLOCK no socket() elimina o par fcntl(F_GETFL/F_SETFL)
             * por socket — economiza 2 syscalls × 512 fds por batch */
            int fd=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK,0);
            if(fd<0){port++;continue;}
            struct sockaddr_in sa=resolved_sa;
            sa.sin_port=htons((uint16_t)port);
            connect(fd,(struct sockaddr*)&sa,sizeof(sa)); /* EINPROGRESS ok */
            batch_fds[n_batch]=fd;
            batch_ports[n_batch]=port;
            pfds[n_batch].fd=fd;
            pfds[n_batch].events=POLLOUT|POLLERR;
            pfds[n_batch].revents=0;
            n_batch++; port++;
        }

        /* poll() 200ms: suficiente para LAN (<10ms) e maioria de alvos WAN */
        poll(pfds,n_batch,200);

        for(int i=0;i<n_batch;i++){
            int is_open=0;
            if(pfds[i].revents & POLLOUT){
                int err=0; socklen_t el=sizeof(err);
                getsockopt(batch_fds[i],SOL_SOCKET,SO_ERROR,&err,&el);
                if(err==0) is_open=1;
            }
            if(is_open){
                /* Banner grab — 100ms timeout (inline; não bloqueia próximo batch) */
                char banner[257]={0};
                struct timeval tbv; tbv.tv_sec=0; tbv.tv_usec=100000;
                setsockopt(batch_fds[i],SOL_SOCKET,SO_RCVTIMEO,&tbv,sizeof(tbv));
                int flg2=fcntl(batch_fds[i],F_GETFL,0);
                fcntl(batch_fds[i],F_SETFL,flg2&~O_NONBLOCK);
                ssize_t bn=recv(batch_fds[i],banner,256,MSG_PEEK);
                if(bn<=0) bn=recv(batch_fds[i],banner,256,0);
                char clean[257]={0}; int ci=0;
                for(int bi=0;bi<(int)bn&&bi<256;bi++){
                    unsigned char bc=(unsigned char)banner[bi];
                    if(bc>=0x20&&bc<0x7f) clean[ci++]=banner[bi];
                    else if(bc=='\n'||bc=='\r'){if(ci>0&&clean[ci-1]!=' ')clean[ci++]=' ';}
                }
                while(ci>0&&clean[ci-1]==' ')ci--;
                clean[ci]='\0';

                open_ports[open_count++]=batch_ports[i];
                if(clean[0]) {
                    progress_clear();
                    printf("\033[1;32m  [+] %-5d ABERTA\033[0m  \033[0;36m%s\033[0m\n",
                           batch_ports[i],clean);
                } else {
                    progress_clear();
                    printf("\033[1;32m  [+] %-5d ABERTA\033[0m\n",batch_ports[i]);
                }
            }
            /* SO_LINGER{1,0}: RST imediato evita TIME_WAIT — libera porta
             * local instantaneamente para o próximo batch */
            { struct linger _sl={1,0};
              setsockopt(batch_fds[i],SOL_SOCKET,SO_LINGER,&_sl,sizeof(_sl)); }
            close(batch_fds[i]);
            pfds[i].fd=-1; /* reset para próximo batch */
        }
        /* atualiza barra de progresso após cada batch */
        scan_done += n_batch;
        progress_bar(scan_done, scan_total, "portas:");
    }
    progress_clear(); /* limpa barra antes do resumo */
    #undef SCAN_BATCH

    gettimeofday(&scan_t1, NULL);
    double scan_elapsed = (scan_t1.tv_sec  - scan_t0.tv_sec) +
                          (scan_t1.tv_usec - scan_t0.tv_usec) / 1e6;
    char scan_timer[32]={0};
    if(scan_elapsed < 60.0)
        snprintf(scan_timer,sizeof(scan_timer),"%.1fs",scan_elapsed);
    else
        snprintf(scan_timer,sizeof(scan_timer),"%dm%ds",
                 (int)(scan_elapsed/60),(int)scan_elapsed%60);

    if(open_count==0)
        printf("\033[1;33m  [-] Nenhuma porta aberta em %s:%d-%d\033[0m  \033[0;90m(%s)\033[0m\n",
               host,from,to,scan_timer);
    else
        printf("\n\033[1;33m[*] %d porta(s) aberta(s)\033[0m  \033[0;90m(%s)\033[0m\n",
               open_count,scan_timer);

    lua_newtable(L);
    for(int i=0;i<open_count;i++){
        lua_pushinteger(L,open_ports[i]);
        lua_rawseti(L,-2,i+1);
    }
    free(open_ports);
    return 1;
}

static int l_net_ping(lua_State *L) {
    const char *host_raw = luaL_checkstring(L, 1);
    // Sanitiza host — só permite chars válidos de hostname/IP
    char host[256] = {0};
    int j = 0;
    for(int i = 0; host_raw[i] && j < 255; i++) {
        char c = host_raw[i];
        // Permite: letras, dígitos, '.', '-', '_', ':', '[', ']' (IPv6)
        if((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||
            c=='.'||c=='-'||c=='_'||c==':'||c=='['||c==']')
            host[j++] = c;
    }
    if(j == 0) { lua_pushboolean(L, 0); return 1; }
    char cmd[300];
    snprintf(cmd, sizeof(cmd), "ping -c 1 -W 1 '%s' > /dev/null 2>&1", host);
    lua_pushboolean(L, system(cmd) == 0); return 1;
}
static int l_net_dns(lua_State *L) {
    const char *host = luaL_checkstring(L, 1);
    const char *type_str = luaL_optstring(L, 2, "A"); // A, AAAA, ANY

    int af = AF_INET;
    if (strcasecmp(type_str, "AAAA") == 0 || strcasecmp(type_str, "ipv6") == 0)
        af = AF_INET6;
    else if (strcasecmp(type_str, "ANY") == 0)
        af = AF_UNSPEC;

    struct addrinfo hints, *res = NULL;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family   = af;
    hints.ai_socktype = SOCK_STREAM;

    int rc = getaddrinfo(host, NULL, &hints, &res);
    if (rc != 0) {
        lua_pushnil(L);
        lua_pushstring(L, gai_strerror(rc));
        return 2;
    }

    lua_newtable(L);
    int idx = 1;
    for (struct addrinfo *r = res; r; r = r->ai_next) {
        char ip[INET6_ADDRSTRLEN] = {0};
        if (r->ai_family == AF_INET) {
            struct sockaddr_in *sa = (struct sockaddr_in *)r->ai_addr;
            inet_ntop(AF_INET, &sa->sin_addr, ip, sizeof(ip));
        } else if (r->ai_family == AF_INET6) {
            struct sockaddr_in6 *sa = (struct sockaddr_in6 *)r->ai_addr;
            inet_ntop(AF_INET6, &sa->sin6_addr, ip, sizeof(ip));
        }
        if (ip[0]) {
            lua_pushstring(L, ip);
            lua_rawseti(L, -2, idx++);
        }
    }
    freeaddrinfo(res);
    return 1;
}

static int l_net_help(lua_State *L) {
    (void)L;
    printf("\n\033[1;36m=== net — Sockets + HTTP ===\033[0m\n\n");

    printf("\033[1;33mALIASES LEGADOS (fd numérico — código antigo):\033[0m\n");
    printf("  net.send(fd, data)          envia em fd numérico\n");
    printf("  net.recv(fd [,max])         recebe de fd numérico (padrão 4096 bytes)\n");
    printf("  net.close(fd)               fecha fd numérico → true/false\n");
    printf("  Prefira os métodos do objeto: s:send() s:recv() s:close()\n\n");
    printf("\033[1;33mCONEXAO SIMPLES:\033[0m\n");
    printf("  net.connect(host,port[,t])          TCP IPv4 → SockObj\n");
    printf("  net.tcp(host,port[,t])               alias de connect\n");
    printf("  net.udp(host,port[,t])               UDP IPv4 → SockObj\n");
    printf("  net.tcp6(host,port[,t])              TCP IPv6 → SockObj\n");
    printf("  net.listen(port[,host[,backlog]])    Servidor TCP → SockObj\n\n");

    printf("\033[1;33mnet.socket — fire-and-forget:\033[0m\n");
    printf("  net.socket(family,type,host,port[,timeout[,payload]])\n");
    printf("  Conecta, envia, recebe e fecha tudo numa chamada. Retorna resposta.\n");
    printf("  family : \"ipv4\" | \"ipv6\"\n");
    printf("  type   : \"stream\" | \"tcp\" | \"dgram\" | \"udp\" | \"syn\"\n");
    printf("  Ex: net.socket(\"ipv4\",\"stream\",\"1.1.1.1\",80,3,\"GET / HTTP/1.0\\r\\n\\r\\n\")\n");
    printf("  Ex: net.socket(\"ipv4\",\"dgram\",\"8.8.8.8\",53)  -- UDP\n");
    printf("  Ex: net.socket(\"ipv4\",\"syn\",\"1.1.1.1\",80)   -- SYN probe (sem root)\n");
    printf("      Retorna: \"[SYN] host:port → open|closed|filtered (+Xms)\"\n\n");

    printf("\033[1;33mnet.socketex — objeto completo / SYN probe:\033[0m\n");
    printf("  net.socketex(family,type,host,port[,timeout])\n");
    printf("  net.socketex({host=,port=,family=,type=,...})\n");
    printf("  type=\"syn\" → SYN probe sem root; retorna tabela em vez de objeto:\n");
    printf("    { status=\"open\"||\"closed\"||\"filtered\", open=bool,\n");
    printf("      host=str, port=num, ms=num }\n\n");

    printf("\033[1;33mMETODOS DO OBJETO sock (socketex / connect / tcp / udp):\033[0m\n");
    printf("  -- envio\n");
    printf("  s:send(data)                envia (pode ser parcial)\n");
    printf("  s:sendall(data)             garante envio total ou erro\n");
    printf("  s:sendto(data,host,port)    UDP sem connect previo\n\n");
    printf("  -- recepcao\n");
    printf("  s:recv([max])               lê ate max bytes (padrão 4096)\n");
    printf("  s:recvall([max])            lê tudo ate fechar (padrão 64k)\n");
    printf("  s:recvline()                lê uma linha (ate \\n)\n");
    printf("  s:recvfrom([max])           UDP: retorna data, ip, port\n");
    printf("  s:peek([max])               espia sem consumir buffer\n");
    printf("  for ln in s:lines() do      iterator de linhas\n\n");
    printf("  -- controle\n");
    printf("  s:wait([timeout])           aguarda dado disponivel (select)\n");
    printf("  s:settimeout(sec)           altera timeout de I/O (float ok)\n");
    printf("  s:bind(ip,port)             fixa endereco local\n");
    printf("  s:shutdown(\"r\"|\"w\"|\"rw\")    fecha metade da conexao\n");
    printf("  s:accept()                  aceita cliente (sockets listen)\n");
    printf("  s:close()                   fecha o socket\n\n");
    printf("  -- opcoes\n");
    printf("  s:setsockopt(level,opt,val) ex: (\"tcp\",\"nodelay\",1)\n");
    printf("  s:getsockopt(level,opt)     ex: (\"socket\",\"rcvbuf\")\n");
    printf("    levels: socket | tcp | ip\n");
    printf("    opts  : reuseaddr keepalive nodelay broadcast\n");
    printf("            rcvbuf sndbuf rcvtimeo sndtimeo linger error\n\n");
    printf("  -- info\n");
    printf("  s:info()                    tabela completa: host,port,family,type,\n");
    printf("                              fd,local_ip,local_port,rcvbuf,sndbuf\n");
    printf("  s:local()                   ip local, porta local\n");
    printf("  s:peer()                    \"host:porta\" remoto\n");
    printf("  s:fd()                      file descriptor numerico\n");
    printf("  s:closed()                  true/false\n\n");

    printf("\033[1;33mHTTP / UTIL:\033[0m\n");
    printf("  net.get(url [,arquivo])              GET → body (string)\n");
    printf("                                       Exibe URL, HTTP code, tamanho\n");
    printf("  net.geth(url [,arq [,headers]])      GET → body, http_code\n");
    printf("                                       headers: tabela {Nome=Valor}\n");
    printf("  net.post(url, data [,ct [,hdrs]])    POST → body, http_code\n");
    printf("                                       ct: content-type (padrão: form-urlencoded)\n");
    printf("                                       hdrs: tabela de headers extras\n");
    printf("  net.dns(host [,tipo])                DNS → tabela de IPs\n");
    printf("                                       tipo: 'A' (padrão), 'AAAA', 'ANY'\n");
    printf("  net.ping(host)                       → true/false\n");
    printf("  net.scan(host [,de [,ate]])           SYN scan sem root + banner grab\n");
    printf("                                       → tabela de portas abertas\n");
    printf("                                       padrão: portas 1-1024\n");
    printf("  net.os(host)                         OS/device fingerprint sem root\n");
    printf("                                       Aceita IP local ou domínio\n");
    printf("                                       → {host, ip, ttl, os_hint, type,\n");
    printf("                                          ports, server, confidence}\n");
    printf("                                       Ex: net.os('192.168.101.1')\n");
    printf("                                       Ex: net.os('google.com')\n");
    printf("  net.ip([cidr [,timeout]])            host discovery na rede local\n");
    printf("                                       Ex: net.ip()  → detecta rede local automaticamente\n");
    printf("                                       Ex: net.ip('192.168.1.0/24', 2)\n");
    printf("                                       → tabela de IPs ativos\n");
    printf("  net.fetch(url [,opts])               GET com controle fino de timeout/headers\n");
    printf("                                       → body, code, headers_raw\n");
    printf("  net.import(url)                      baixa URL e executa como Lua\n");
    printf("                                       → true (ok) ou false (erro de fetch/syntax)\n");
    printf("                                       Ex: net.import('http://host/mod.lua')\n\n");

    printf("\033[1;33mEXEMPLOS:\033[0m\n");
    printf("  -- GET simples\n");
    printf("  local body = net.get('http://site.com/')\n");
    printf("  local html,code = net.geth('http://site.com/')\n");
    printf("  print('HTTP', code, #html, 'bytes')\n\n");
    printf("  -- POST com headers customizados\n");
    printf("  local r,c = net.post('http://site.com/api', '{\"id\":1}',\n");
    printf("                        'application/json',\n");
    printf("                        {Authorization='Bearer TOKEN'})\n\n");
    printf("  -- DNS lookup\n");
    printf("  local ips = net.dns('exemplo.com')\n");
    printf("  for _,ip in ipairs(ips) do print(ip) end\n\n");
    printf("  -- Port scan\n");
    printf("  local portas = net.scan('192.168.1.1', 1, 65535)\n");
    printf("  for _,p in ipairs(portas) do print('aberta:', p) end\n\n");
    printf("  -- SYN probe (sem root, sem payload)\n");
    printf("  print(net.socket(\"ipv4\",\"syn\",\"1.1.1.1\",80))\n");
    printf("  -- [SYN] 1.1.1.1:80 → open (+12ms)\n\n");
    printf("  -- SYN probe via socketex → tabela\n");
    printf("  local r = net.socketex(\"ipv4\",\"syn\",\"192.168.1.1\",22)\n");
    printf("  print(r.status, r.open, r.ms)  -- \"open\" true 4.2\n\n");
    printf("  -- banner grab SSH\n");
    printf("  print(net.socket(\"ipv4\",\"stream\",\"192.168.1.1\",22))\n\n");
    printf("  -- HTTP manual via socket\n");
    printf("  local s = net.socketex(\"ipv4\",\"stream\",\"example.com\",80)\n");
    printf("  s:sendall(\"GET / HTTP/1.0\\r\\nHost: example.com\\r\\n\\r\\n\")\n");
    printf("  print(s:recvall())  s:close()\n\n");
    printf("  -- UDP sendto/recvfrom\n");
    printf("  local s = net.socketex(\"ipv4\",\"dgram\",\"0.0.0.0\",0)\n");
    printf("  s:bind(\"0.0.0.0\",9000)\n");
    printf("  s:sendto(\"oi\",\"192.168.1.1\",9001)\n");
    printf("  local data,ip,port = s:recvfrom()  s:close()\n\n");
    printf("  -- import: executa Lua remoto\n");
    printf("  net.import('http://192.168.1.1:8000/lib.lua')\n");
    printf("  -- retorna true se o código foi baixado e executado sem erro\n\n");
    printf("  -- servidor TCP\n");
    printf("  local srv = net.listen(8080)\n");
    printf("  local cli = srv:accept()\n");
    printf("  for line in cli:lines() do print(line) end\n");
    printf("  cli:close()  srv:close()\n\n");
    return 0;
}

// SYS
// sys.thread usa fork() igual ao spawn — assim sys.kill(pid) funciona nos dois
// Cada filho cria seu próprio lua_State isolado e executa o código

static int l_sys_spawn(lua_State *L) {
    const char *cmd = luaL_checkstring(L, 1);

    pid_t pid = fork();
    if (pid < 0) {
        printf("\033[1;31m[sys.spawn] fork() falhou\033[0m\n");
        lua_pushinteger(L, -1); return 1;
    }
    if (pid == 0) {
        setsid();
        execl("/bin/sh", "sh", "-c", cmd, NULL);
        _exit(127);
    }

    pthread_mutex_lock(&task_mutex);
    if (G_TaskCount < MAX_TASKS) {
        G_Tasks[G_TaskCount].id     = (long)pid;
        G_Tasks[G_TaskCount].active = 1;
        strncpy(G_Tasks[G_TaskCount].type, "spawn", 15);
        strncpy(G_Tasks[G_TaskCount].name, cmd,     127);
        G_TaskCount++;
    }
    pthread_mutex_unlock(&task_mutex);

    printf("\033[1;32m[+] PID %d: %s\033[0m\n", pid, cmd);
    lua_pushinteger(L, (lua_Integer)pid);
    return 1;
}

static int l_sys_sh(lua_State *L) {
    const char *cmd = luaL_checkstring(L, 1);
    pid_t pid = fork();
    if (pid < 0) { lua_pushinteger(L,-1); return 1; }
    if (pid == 0) { setsid(); execl("/bin/sh","sh","-c",cmd,NULL); _exit(127); }
    char name[64]={0}; int ni=0;
    for(int i=0;cmd[i]&&ni<50;i++){char c=cmd[i];if(c=='\n'||c=='\r'){if(ni>0)break;continue;}name[ni++]=c;}
    pthread_mutex_lock(&task_mutex);
    if(G_TaskCount<MAX_TASKS){
        G_Tasks[G_TaskCount].id=(long)pid; G_Tasks[G_TaskCount].active=1;
        strncpy(G_Tasks[G_TaskCount].type,"sh",15);
        strncpy(G_Tasks[G_TaskCount].name,name,127); G_TaskCount++;
    }
    pthread_mutex_unlock(&task_mutex);
    printf("\033[1;32m[+] sh PID %d: %s\033[0m\n",pid,name);
    lua_pushinteger(L,(lua_Integer)pid); return 1;
}

/* ── Thread Lua isolada ───────────────────────────────────────────────────── */
#define LUA_THREAD_RESULT_MAX 4096
#define MAX_LUA_THREADS 64

typedef struct {
    int   tid;
    int   done;
    int   ok;
    char  result[LUA_THREAD_RESULT_MAX];
    int   rfd;   /* read end do pipe */
} LuaThreadSlot;

typedef struct {
    char  code[65536];   /* 64KB — suporta closures e templates grandes */
    int   wfd;
    int   tid;
} LuaThreadArg;

static LuaThreadSlot  g_lth[MAX_LUA_THREADS];
static int            g_lth_count = 0;
static pthread_mutex_t g_lth_mu   = PTHREAD_MUTEX_INITIALIZER;
static int            g_lth_id    = 0;

/* Inicializa rfd=-1 em todos os slots (C zera globais, rfd=0 seria fd stdout) */
__attribute__((constructor)) static void g_lth_init(void) {
    for(int i=0;i<MAX_LUA_THREADS;i++) g_lth[i].rfd = -1;
}

static void *lua_thread_worker(void *arg) {
    LuaThreadArg *ta = (LuaThreadArg *)arg;
    char resbuf[LUA_THREAD_RESULT_MAX] = {0};
    int ok = 0;
    int wfd = ta->wfd; /* salva antes de qualquer free acidental */
    int tid = ta->tid;
    lua_State *T = luaL_newstate();
    if (T) {
        /* Abre apenas as libs padrão do Lua — NÃO usa luaL_openlibs()
         * porque ela também chama "elliot_core" (luaopen_net) que está
         * registrado no linit.c e toca globais não-thread-safe como
         * ai_db_init, readline, etc. */
        luaL_requiref(T, "_G",        luaopen_base,      1); lua_pop(T, 1);
        luaL_requiref(T, LUA_LOADLIBNAME,  luaopen_package,   1); lua_pop(T, 1);
        luaL_requiref(T, LUA_COLIBNAME,    luaopen_coroutine, 1); lua_pop(T, 1);
        luaL_requiref(T, LUA_TABLIBNAME,   luaopen_table,     1); lua_pop(T, 1);
        luaL_requiref(T, LUA_IOLIBNAME,    luaopen_io,        1); lua_pop(T, 1);
        luaL_requiref(T, LUA_OSLIBNAME,    luaopen_os,        1); lua_pop(T, 1);
        luaL_requiref(T, LUA_STRLIBNAME,   luaopen_string,    1); lua_pop(T, 1);
        luaL_requiref(T, LUA_MATHLIBNAME,  luaopen_math,      1); lua_pop(T, 1);
        luaL_requiref(T, LUA_UTF8LIBNAME,  luaopen_utf8,      1); lua_pop(T, 1);
        luaL_requiref(T, LUA_DBLIBNAME,    luaopen_debug,     1); lua_pop(T, 1);
        /* Agora registra os módulos do ElliotOS thread-safe */
        luaopen_net_thread(T);

        /* Suprime output da thread redirecionando io.stdout/stderr do Lua
         * para /dev/null — seguro porque opera só no lua_State desta thread,
         * sem tocar os fds do processo (dup2 causaria race condition). */
        luaL_dostring(T,
            "local nul=io.open('/dev/null','w')"
            "if nul then io.output(nul) end");

        int rc = luaL_dostring(T, ta->code);
        if (rc == LUA_OK) {
            ok = 1;
            if (lua_gettop(T) > 0) {
                int t = lua_type(T,-1);
                if      (t==LUA_TSTRING)  strncpy(resbuf,lua_tostring(T,-1),LUA_THREAD_RESULT_MAX-1);
                else if (t==LUA_TNUMBER)  snprintf(resbuf,LUA_THREAD_RESULT_MAX,"%g",(double)lua_tonumber(T,-1));
                else if (t==LUA_TBOOLEAN) snprintf(resbuf,LUA_THREAD_RESULT_MAX,"%s",lua_toboolean(T,-1)?"true":"false");
                else                      strncpy(resbuf,"nil",LUA_THREAD_RESULT_MAX-1);
            } else { strncpy(resbuf,"nil",LUA_THREAD_RESULT_MAX-1); }
        } else {
            const char *e=lua_tostring(T,-1);
            snprintf(resbuf,LUA_THREAD_RESULT_MAX,"ERROR:%s",e?e:"?");
        }
        lua_close(T);
    } else { strncpy(resbuf,"ERROR:luaL_newstate",LUA_THREAD_RESULT_MAX-1); }

    /* marcar slot como done ANTES de fechar o pipe,
       assim sys.join() nunca lê de um fd já fechado duas vezes */
    pthread_mutex_lock(&g_lth_mu);
    for(int i=0;i<g_lth_count;i++){
        if(g_lth[i].tid==tid){
            g_lth[i].done=1; g_lth[i].ok=ok;
            strncpy(g_lth[i].result,resbuf,LUA_THREAD_RESULT_MAX-1);
            break;
        }
    }
    pthread_mutex_unlock(&g_lth_mu);

    /* escrever resultado no pipe — sempre fecha wfd para desbloquear sys.join() */
    char msg[LUA_THREAD_RESULT_MAX+16];
    int mlen = snprintf(msg,sizeof(msg),"%d|%s\n",ok,resbuf);
    if(wfd>=0){ write(wfd,msg,mlen); close(wfd); }

    free(ta); return NULL;
}

static int l_sys_thread(lua_State *L) {
    int type = lua_type(L,1);
    char code[65536]={0};
    if(type==LUA_TSTRING){
        strncpy(code,lua_tostring(L,1),sizeof(code)-1);
    } else if(type==LUA_TFUNCTION){
        lua_getglobal(L,"string"); lua_getfield(L,-1,"dump"); lua_remove(L,-2);
        lua_pushvalue(L,1);
        if(lua_pcall(L,1,1,0)!=LUA_OK){lua_pop(L,1);return luaL_error(L,"sys.thread: dump falhou");}
        size_t dlen; const char *dump=lua_tolstring(L,-1,&dlen);
        /* Reconstrói como: load(string.char(b1,b2,...))()
         * string.char() aceita inteiros decimais — funciona com bytecode binário */
        int j=snprintf(code,sizeof(code),"load(string.char(");
        for(size_t i=0;i<dlen&&j<(int)sizeof(code)-16;i++){
            if(i>0) code[j++]=',';
            j+=snprintf(code+j,sizeof(code)-j,"%d",(unsigned char)dump[i]);
        }
        snprintf(code+j,sizeof(code)-j,"))()");
        lua_pop(L,1);
    } else { return luaL_error(L,"sys.thread: espera string ou funcao Lua"); }

    LuaThreadArg *ta=(LuaThreadArg*)malloc(sizeof(LuaThreadArg));
    if(!ta){ lua_pushinteger(L,-1); return 1; }

    int pfd[2]={-1,-1};
    if(pipe(pfd)!=0){
        free(ta); lua_pushinteger(L,-1); return 1;
    }
    strncpy(ta->code,code,sizeof(ta->code)-1);
    ta->wfd=pfd[1];

    pthread_mutex_lock(&g_lth_mu);
    ta->tid = ++g_lth_id;
    int slot=-1;
    /* Primeiro tenta reutilizar slot de thread já terminada */
    for(int i=0;i<g_lth_count;i++){
        if(g_lth[i].done && g_lth[i].rfd<0){
            slot=i; break;
        }
    }
    /* Se não achou slot livre, expande o array (se tiver espaço) */
    if(slot<0 && g_lth_count<MAX_LUA_THREADS){
        slot=g_lth_count++;
    }
    if(slot>=0){
        g_lth[slot].tid=ta->tid; g_lth[slot].done=0;
        g_lth[slot].ok=0; g_lth[slot].result[0]='\0';
        g_lth[slot].rfd=pfd[0];
    }
    pthread_mutex_unlock(&g_lth_mu);

    if(slot<0){free(ta);close(pfd[0]);close(pfd[1]);lua_pushinteger(L,-1);return 1;}

    pthread_t pth;
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    /* Stack de 2MB por thread Lua — evita stack overflow no Termux (padrão 8KB em alguns kernels) */
    pthread_attr_setstacksize(&attr, 2 * 1024 * 1024);
    pthread_create(&pth, &attr, lua_thread_worker, ta);
    pthread_attr_destroy(&attr);
    pthread_detach(pth);

    /* registrar em G_Tasks como "lua" */
    char name[64]={0}; int ni=0;
    for(int i=0;code[i]&&ni<50;i++){char c=code[i];if(c=='\n'||c=='\r'){if(ni>0)break;continue;}name[ni++]=c;}
    pthread_mutex_lock(&task_mutex);
    if(G_TaskCount<MAX_TASKS){
        G_Tasks[G_TaskCount].id=(long)ta->tid; G_Tasks[G_TaskCount].active=1;
        strncpy(G_Tasks[G_TaskCount].type,"lua",15);
        strncpy(G_Tasks[G_TaskCount].name,name,127); G_TaskCount++;
    }
    pthread_mutex_unlock(&task_mutex);

    lua_pushinteger(L,(lua_Integer)ta->tid); return 1;
}

static int l_sys_join(lua_State *L) {
    int tid     = (int)luaL_checkinteger(L,1);
    int timeout = (int)luaL_optinteger(L,2,0);
    int rfd=-1;
    pthread_mutex_lock(&g_lth_mu);
    for(int i=0;i<g_lth_count;i++){if(g_lth[i].tid==tid){rfd=g_lth[i].rfd;break;}}
    pthread_mutex_unlock(&g_lth_mu);
    if(rfd<0){lua_pushnil(L);lua_pushstring(L,"thread nao encontrada");return 2;}

    char buf[LUA_THREAD_RESULT_MAX+16]={0}; int got=0;
    if(timeout>0){
        /* poll() — sem limite de FD_SETSIZE, ao contrário de select() */
        struct pollfd pfd; pfd.fd=rfd; pfd.events=POLLIN; pfd.revents=0;
        int pr = poll(&pfd, 1, timeout);
        if(pr>0 && (pfd.revents & POLLIN))
            got=(int)read(rfd,buf,sizeof(buf)-1);
        else {
            close(rfd);
            /* Limpa da tabela antes de retornar */
            pthread_mutex_lock(&g_lth_mu);
            for(int i=0;i<g_lth_count;i++){
                if(g_lth[i].tid==tid){g_lth[i].rfd=-1;break;}
            }
            pthread_mutex_unlock(&g_lth_mu);
            lua_pushnil(L);
            lua_pushstring(L, pr==0?"tempo esgotado":"erro de poll");
            return 2;
        }
    } else {
        got=(int)read(rfd,buf,sizeof(buf)-1);
    }
    close(rfd);

    pthread_mutex_lock(&g_lth_mu);
    for(int i=0;i<g_lth_count;i++){
        if(g_lth[i].tid==tid){g_lth[i].rfd=-1;break;}
    }
    pthread_mutex_unlock(&g_lth_mu);

    if(got<=0){lua_pushnil(L);lua_pushstring(L,"sem resultado");return 2;}
    buf[got]='\0';
    char *pipe_ch=strchr(buf,'|');
    if(!pipe_ch){lua_pushstring(L,buf);return 1;}
    *pipe_ch='\0'; int ok_flag=atoi(buf); char *res=pipe_ch+1;
    int rlen=(int)strlen(res);
    while(rlen>0&&(res[rlen-1]=='\n'||res[rlen-1]=='\r'))res[--rlen]='\0';
    if(!ok_flag){lua_pushnil(L);lua_pushstring(L,res);return 2;}
    char *endp=NULL; double num=strtod(res,&endp);
    if(endp&&*endp=='\0'&&strlen(res)>0) lua_pushnumber(L,num);
    else lua_pushstring(L,res);
    return 1;
}


static int l_sys_list(lua_State *L) {
    (void)L;
    pthread_mutex_lock(&task_mutex);
    int found = 0;
    printf("\n\033[1;33m╔══════════════════════════════════════════╗\033[0m\n");
    printf("\033[1;33m║  Tasks Ativas                            ║\033[0m\n");
    printf("\033[1;33m╚══════════════════════════════════════════╝\033[0m\n");
    for (int i = 0; i < G_TaskCount; i++) {
        if (!G_Tasks[i].active) continue;
        // Para spawns, verifica se o processo ainda existe
        if (strcmp(G_Tasks[i].type, "spawn") == 0) {
            int status;
            pid_t r = waitpid((pid_t)G_Tasks[i].id, &status, WNOHANG);
            if (r != 0) { G_Tasks[i].active = 0; continue; } // já morreu
        }
        printf("  \033[1;32m[%ld]\033[0m \033[1;36m%-8s\033[0m %s\n",
            G_Tasks[i].id, G_Tasks[i].type, G_Tasks[i].name);
        found++;
    }
    if (!found) printf("  \033[1;33m(nenhuma task ativa)\033[0m\n");
    printf("\n");
    pthread_mutex_unlock(&task_mutex);
    return 0;
}
static int l_sys_kill(lua_State *L) {
    long id = (long)luaL_checkinteger(L, 1);
    int killed = 0;
    pthread_mutex_lock(&task_mutex);
    for (int i = 0; i < G_TaskCount; i++) {
        if (G_Tasks[i].id == id && G_Tasks[i].active) {
            if (strcmp(G_Tasks[i].type, "spawn") == 0) {
                // mata o processo real
                kill((pid_t)id, SIGTERM);
                usleep(100000);
                kill((pid_t)id, SIGKILL); // força se necessário
            }
            G_Tasks[i].active = 0;
            killed = 1;
            break;
        }
    }
    pthread_mutex_unlock(&task_mutex);
    if (killed) printf("\033[1;32m✅ Task %ld encerrada\033[0m\n", id);
    else        printf("\033[1;31m❌ Task %ld não encontrada\033[0m\n", id);
    lua_pushboolean(L, killed); return 1;
}
/* ══════════════════════════════════════════════════════════════════════════
 * _elliot_print_logo — logo ASCII art do ElliotOS (roxo + amarelo + azul)
 * Chamada por lg() e pelo cabeçalho de sys.info()
 * ════════════════════════════════════════════════════════════════════════ */
static void _elliot_print_logo(void) {
    /* Paleta ANSI */
    const char *P  = "\033[1;35m";   /* roxo  (purple)  */
    const char *Y  = "\033[1;33m";   /* amarelo         */
    const char *B  = "\033[1;34m";   /* azul            */
    const char *C  = "\033[1;36m";   /* ciano (acento)  */
    const char *W  = "\033[1;37m";   /* branco brilhante*/
    const char *R  = "\033[0m";      /* reset           */

    printf("\n");
    /* linha 1 */
    printf("  %s ███████╗%s██╗     %s██╗     %s██╗%s ██████╗ %s████████╗%s\n",P,B,B,Y,P,C,W);
    /* linha 2 */
    printf("  %s ██╔════╝%s██║     %s██║     %s██║%s██╔═══██╗%s╚══██╔══╝%s\n",P,B,B,Y,P,C,W);
    /* linha 3 */
    printf("  %s █████╗  %s██║     %s██║     %s██║%s██║   ██║%s   ██║   %s\n",P,B,B,Y,P,C,W);
    /* linha 4 */
    printf("  %s ██╔══╝  %s██║     %s██║     %s██║%s██║   ██║%s   ██║   %s\n",P,B,B,Y,P,C,W);
    /* linha 5 */
    printf("  %s ███████╗%s███████╗%s███████╗%s██║%s╚██████╔╝%s   ██║   %s\n",P,B,B,Y,P,C,W);
    /* linha 6 */
    printf("  %s ╚══════╝%s╚══════╝%s╚══════╝%s╚═╝%s ╚═════╝ %s   ╚═╝   %s\n",P,B,B,Y,P,C,W);
    printf("\n");
    /* sublinha decorativa */
    printf("  %s╌╌╌╌╌╌╌╌%s╌╌╌╌╌╌╌╌%s╌╌╌╌╌╌╌╌%s╌╌╌╌╌╌╌╌%s╌╌╌╌╌╌╌╌%s╌╌╌╌╌╌╌%s\n",P,B,B,Y,P,C,W);
    /* tagline */
    printf("  %s  ◆  %sOS v17.0%s  •  %sLua 5.4 + C + Bash%s  •  %sTermux / Linux%s  ◆\n",
           Y, W, Y, B, Y, P, R);
    /* sublinha decorativa baixo */
    printf("  %s╌╌╌╌╌╌╌╌%s╌╌╌╌╌╌╌╌%s╌╌╌╌╌╌╌╌%s╌╌╌╌╌╌╌╌%s╌╌╌╌╌╌╌╌%s╌╌╌╌╌╌╌%s\n\n",P,B,B,Y,P,C,R);
    fflush(stdout); /* garante exibição imediata no REPL — stdout pode estar em buffer */
}

/* lg() — exibe apenas o logo do ElliotOS */
static int l_lg(lua_State *L) {
    (void)L;
    _elliot_print_logo();
    return 0;
}

