static int l_ic(lua_State *L) {
    (void)L;
    const char *td = getenv("TMPDIR");
    if (!td || !*td) td = "/tmp";
    char tmp_b64[512], tmp_png[512], cmd[1100];
    snprintf(tmp_b64, sizeof(tmp_b64), "%s/.elliotos_ic_%d.b64", td, (int)getpid());
    snprintf(tmp_png, sizeof(tmp_png), "%s/.elliotos_ic_%d.png", td, (int)getpid());

    /* 1. Escreve o base64 direto em arquivo — sem pipe, máxima velocidade */
    FILE *f = fopen(tmp_b64, "w");
    if (f) {
        fwrite(_IC_LOGO_B64, 1, sizeof(_IC_LOGO_B64)-1, f);
        fclose(f);
    }

    /* 2. Decodifica com base64 -d (lê de arquivo, não de pipe) */
    snprintf(cmd, sizeof(cmd), "base64 -d '%s' > '%s' 2>/dev/null", tmp_b64, tmp_png);
    system(cmd);
    remove(tmp_b64);

    /* 3. Exibe e limpa */
    snprintf(cmd, sizeof(cmd),
        "command -v timg >/dev/null 2>&1 && timg --center -g 60x20 '%s' 2>/dev/null",
        tmp_png);
    system(cmd);
    remove(tmp_png);
    return 0;
}



static int l_sys_info(lua_State *L) {
    (void)L;

    /* ── Logo + Banner do sistema ───────────────────────────────────────── */
    _elliot_print_logo();

    printf("  \033[1;36mSobre o sistema:\033[0m\n");
    printf("  \033[0;37mElliotOS e um sistema operacional de scripting para Termux/Android.\033[0m\n");
    printf("  \033[0;37mSem root. Sem Python. Lua 5.4 + C + Bash — modulos nativos de IA e pentest.\033[0m\n");
    printf("  \033[0;37mFeito com \033[1;31mC\033[0m \033[0;37m+\033[0m \033[1;32mBash\033[0m \033[0;37m+\033[0m \033[1;33mLua\033[0m \033[0;37m— zero dependencias Python.\033[0m\n\n");

    printf("  \033[1;36mOrigem e objetivo:\033[0m\n");
    printf("  \033[0;37mFeito por \033[1;35mMike Elliot\033[0;37m com raiva e proposito.\033[0m\n");
    printf("  \033[0;37mPentest sempre foi territorio de computador — \033[1;31mParrotOS\033[0;37m, \033[1;31mKali Linux\033[0;37m, \033[1;31mBlackArch\033[0;37m.\033[0m\n");
    printf("  \033[0;37mFerramentas poderosas, mas presas em maquinas que a maioria nao tem.\033[0m\n");
    printf("  \033[0;37mMike Elliot decidiu mudar isso: construiu o ElliotOS para rodar\033[0m\n");
    printf("  \033[0;37mespecificamente no \033[1;32mTermux\033[0;37m, sem root, direto no Android —\033[0m\n");
    printf("  \033[0;37mmas com suporte completo a qualquer Linux: Debian, Ubuntu, Arch, Fedora.\033[0m\n");
    printf("  \033[0;37mTudo em um unico script. \033[1;31mC\033[0;37m + \033[1;32mBash\033[0;37m + \033[1;33mLua\033[0;37m.\033[0m\n");
    printf("  \033[0;37mSem Python3. Sem Node. Sem ocupar metade do armazenamento do dispositivo.\033[0m\n");
    printf("  \033[0;37mSe voce tem um Android, voce tem um lab de pentest.\033[0m\n\n");

    /* ── Kernel / SO ────────────────────────────────────────────────────── */
    printf("  \033[1;33m── Sistema Operacional ──────────────────────────────────────────\033[0m\n");
    {
        FILE *f = popen("uname -r 2>/dev/null","r");
        char kernel[256]={0};
        if(f){ fgets(kernel,sizeof(kernel),f); pclose(f); }
        kernel[strcspn(kernel,"\n")] = 0;
        printf("  \033[0;90mKernel:\033[0m        \033[1;32m%s\033[0m\n", kernel[0]?kernel:"desconhecido");
    }
    {
        FILE *f = popen("uname -m 2>/dev/null","r");
        char arch[64]={0};
        if(f){ fgets(arch,sizeof(arch),f); pclose(f); }
        arch[strcspn(arch,"\n")] = 0;
        printf("  \033[0;90mArquitetura:\033[0m   \033[1;32m%s\033[0m\n", arch[0]?arch:"desconhecido");
    }
    {
        /* Android version via getprop */
        FILE *f = popen("getprop ro.build.version.release 2>/dev/null","r");
        char ver[64]={0};
        if(f){ fgets(ver,sizeof(ver),f); pclose(f); }
        ver[strcspn(ver,"\n")] = 0;
        if(ver[0])
            printf("  \033[0;90mAndroid:\033[0m       \033[1;32m%s\033[0m\n", ver);
    }
    {
        FILE *f = popen("getprop ro.product.model 2>/dev/null","r");
        char model[128]={0};
        if(f){ fgets(model,sizeof(model),f); pclose(f); }
        model[strcspn(model,"\n")] = 0;
        if(model[0])
            printf("  \033[0;90mDispositivo:\033[0m   \033[1;32m%s\033[0m\n", model);
    }

    /* ── CPU ────────────────────────────────────────────────────────────── */
    printf("\n  \033[1;33m── CPU ──────────────────────────────────────────────────────────\033[0m\n");
    {
        char cpu_name[256] = {0};

        /* Tenta model name (x86/desktop) */
        FILE *f = popen("grep -m1 'model name' /proc/cpuinfo 2>/dev/null | cut -d: -f2","r");
        if(f){ fgets(cpu_name,sizeof(cpu_name),f); pclose(f); }

        /* Tenta Hardware (alguns Android) */
        if(!cpu_name[0]||cpu_name[0]=='\n'){
            FILE *f2 = popen("grep -m1 'Hardware' /proc/cpuinfo 2>/dev/null | cut -d: -f2","r");
            if(f2){ fgets(cpu_name,sizeof(cpu_name),f2); pclose(f2); }
        }

        /* Android ARM: decodifica CPU implementer + CPU part */
        if(!cpu_name[0]||cpu_name[0]=='\n'){
            /* lê todos os implementers e parts únicos */
            FILE *fi = fopen("/proc/cpuinfo","r");
            char line[256]; unsigned int impl=0, part=0;
            unsigned int impl2=0, part2=0; int found2=0;
            unsigned int cur_impl=0;
            if(fi){
                while(fgets(line,sizeof(line),fi)){
                    if(strncmp(line,"CPU implementer",15)==0){
                        sscanf(line,"CPU implementer : %x",&cur_impl);
                        if(!impl) impl=cur_impl;
                        else if(cur_impl!=impl&&!impl2) impl2=cur_impl;
                    }
                    if(strncmp(line,"CPU part",8)==0){
                        unsigned int p2=0; sscanf(line,"CPU part : %x",&p2);
                        if(!part) part=p2;
                        else if(p2!=part&&!part2){ part2=p2; found2=1; }
                    }
                }
                fclose(fi);
            }

            /* Tabela ARM implementer+part → nome */
            const char *name1="", *name2="";
            /* ARM (0x41) */
            if(impl==0x41){
                if(part==0xd05) name1="Cortex-A55";
                else if(part==0xd04) name1="Cortex-A35";
                else if(part==0xd08) name1="Cortex-A72";
                else if(part==0xd09) name1="Cortex-A73";
                else if(part==0xd0a) name1="Cortex-A75";
                else if(part==0xd0b) name1="Cortex-A76";
                else if(part==0xd0d) name1="Cortex-A77";
                else if(part==0xd41) name1="Cortex-A78";
                else if(part==0xd44) name1="Cortex-X1";
                else if(part==0xd46) name1="Cortex-A510";
                else if(part==0xd47) name1="Cortex-A710";
                else if(part==0xd48) name1="Cortex-X2";
                else if(part==0xd4d) name1="Cortex-A715";
                else if(part==0xd4e) name1="Cortex-X3";
                else if(part==0xd80) name1="Cortex-A520";
                else if(part==0xd81) name1="Cortex-A720";
                else if(part==0xd87) name1="Cortex-X4";
                else { static char tmp1[32]; snprintf(tmp1,sizeof(tmp1),"ARM part=0x%03x",part); name1=tmp1; }
            }
            /* Qualcomm Kryo/Falkor (0x51) */
            else if(impl==0x51){
                if(part==0x800) name1="Kryo 2xx Gold";
                else if(part==0x801) name1="Kryo 2xx Silver";
                else if(part==0x802) name1="Kryo 3xx Gold";
                else if(part==0x803) name1="Kryo 3xx Silver";
                else if(part==0x804) name1="Kryo 4xx Gold";
                else if(part==0x805) name1="Kryo 4xx Silver";
                else { static char tmp1q[32]; snprintf(tmp1q,sizeof(tmp1q),"Qualcomm part=0x%03x",part); name1=tmp1q; }
            }
            /* Samsung (0x53) */
            else if(impl==0x53){
                if(part==0x001) name1="Exynos M1";
                else if(part==0x002) name1="Exynos M2/M3";
                else if(part==0x003) name1="Exynos M4";
                else if(part==0x004) name1="Exynos M5";
                else { static char tmp1s[32]; snprintf(tmp1s,sizeof(tmp1s),"Samsung part=0x%03x",part); name1=tmp1s; }
            }
            /* Apple (0x61) */
            else if(impl==0x61){
                if(part==0x022) name1="Apple Firestorm";
                else if(part==0x023) name1="Apple Icestorm";
                else name1="Apple Silicon";
            }

            /* segundo cluster (big.LITTLE) */
            if(found2&&impl2==0x41){
                if(part2==0xd05) name2="Cortex-A55";
                else if(part2==0xd0a) name2="Cortex-A75";
                else if(part2==0xd0b) name2="Cortex-A76";
                else if(part2==0xd0d) name2="Cortex-A77";
                else if(part2==0xd41) name2="Cortex-A78";
                else if(part2==0xd44) name2="Cortex-X1";
                else if(part2==0xd46) name2="Cortex-A510";
                else if(part2==0xd47) name2="Cortex-A710";
                else if(part2==0xd48) name2="Cortex-X2";
                else if(part2==0xd4d) name2="Cortex-A715";
                else if(part2==0xd4e) name2="Cortex-X3";
                else if(part2==0xd80) name2="Cortex-A520";
                else if(part2==0xd81) name2="Cortex-A720";
                else if(part2==0xd87) name2="Cortex-X4";
            } else if(found2&&impl2==0x51){
                name2="Kryo";
            }

            if(name1[0]&&name2[0])
                snprintf(cpu_name,sizeof(cpu_name)," %s + %s (big.LITTLE)",name1,name2);
            else if(name1[0])
                snprintf(cpu_name,sizeof(cpu_name)," %s",name1);
        }

        /* trim */
        char *p = cpu_name; while(*p==' '||*p=='\t') p++;
        p[strcspn(p,"\n")] = 0;
        printf("  \033[0;90mProcessador:\033[0m   \033[1;37m%s\033[0m\n", p[0]?p:"desconhecido");
    }
    {
        FILE *f = popen("nproc 2>/dev/null","r");
        char cores[16]={0};
        if(f){ fgets(cores,sizeof(cores),f); pclose(f); }
        cores[strcspn(cores,"\n")] = 0;
        printf("  \033[0;90mNúcleos:\033[0m       \033[1;37m%s\033[0m\n", cores[0]?cores:"?");
    }

    /* ── RAM ────────────────────────────────────────────────────────────── */
    printf("\n  \033[1;33m── Memória RAM ──────────────────────────────────────────────────\033[0m\n");
    {
        /* Lê /proc/meminfo diretamente */
        long total_kb=0, free_kb=0, avail_kb=0, buffers_kb=0, cached_kb=0;
        FILE *f = fopen("/proc/meminfo","r");
        if(f){
            char line[128];
            while(fgets(line,sizeof(line),f)){
                if(strncmp(line,"MemTotal:",9)==0)     sscanf(line+9,"%ld",&total_kb);
                else if(strncmp(line,"MemFree:",8)==0)  sscanf(line+8,"%ld",&free_kb);
                else if(strncmp(line,"MemAvailable:",13)==0) sscanf(line+13,"%ld",&avail_kb);
                else if(strncmp(line,"Buffers:",8)==0)  sscanf(line+8,"%ld",&buffers_kb);
                else if(strncmp(line,"Cached:",7)==0)   sscanf(line+7,"%ld",&cached_kb);
            }
            fclose(f);
        }
        long used_kb = total_kb - avail_kb;
        double total_mb = total_kb/1024.0;
        double used_mb  = used_kb /1024.0;
        double free_mb  = avail_kb/1024.0;

        /* barra de uso */
        int pct = total_kb>0 ? (int)(used_kb*100/total_kb) : 0;
        int W=32; int filled=(pct*W)/100;
        char bar[256]={0}; int bi=0;
        const char *col = pct>85?"\033[1;31m":pct>60?"\033[1;33m":"\033[1;32m";
        /* █ = \xe2\x96\x88 (3 bytes), ░ = \xe2\x96\x91 (3 bytes) */
        for(int i=0;i<filled;i++){ memcpy(bar+bi,"\xe2\x96\x88",3); bi+=3; }
        for(int i=filled;i<W;i++){ memcpy(bar+bi,"\xe2\x96\x91",3); bi+=3; }
        bar[bi]=0;

        printf("  \033[0;90mTotal:\033[0m         \033[1;37m%.0f MB  (%.1f GB)\033[0m\n", total_mb, total_mb/1024.0);
        printf("  \033[0;90mUsada:\033[0m         %s%.0f MB\033[0m \033[0;90m(%d%%)\033[0m\n", col, used_mb, pct);
        printf("  \033[0;90mDisponível:\033[0m    \033[1;32m%.0f MB\033[0m\n", free_mb);
        printf("  \033[0;90mUso:\033[0m           %s[%s]\033[0m %d%%\n\n", col, bar, pct);
    }

    /* ── Armazenamento / Tamanho do MoonStyle ───────────────────────────── */
    printf("  \033[1;33m── Tamanho do ElliotOS/MoonStyle no disco ───────────────────────\033[0m\n");
    {
        const char *home = getenv("HOME");
        if(!home) home = "/data/data/com.termux/files/home";
        const char *prefix = getenv("PREFIX");
        if(!prefix) prefix = "/data/data/com.termux/files/usr";

        /* binário principal */
        char bin_path[512];
        snprintf(bin_path,511,"%s/bin/lua-net",prefix);
        struct stat st;
        long bin_bytes=0;
        if(stat(bin_path,&st)==0) bin_bytes=st.st_size;

        /* cache */
        char cache_cmd[512];
        snprintf(cache_cmd,511,"du -sb '%s/.lua-cache' 2>/dev/null | cut -f1",home);
        FILE *f=popen(cache_cmd,"r"); long cache_bytes=0;
