            {
                const char *etools[] = { "luar", "ms", "cxx", "lpm", "xpm", NULL };
                const char *elabels[]= { "luar (Lua Raw)", "ms (CLI central)", "cxx (compilador C/C++)", "lpm (pkg manager)", "xpm (pentest manager)", NULL };
                for(int ti=0; etools[ti]; ti++){
