                 home ? home : "/data/data/com.termux/files/home");
        int n_lmod = 0;
        snprintf(cmd, sizeof(cmd), "ls \"%s\"/*.lua 2>/dev/null | wc -l", lmod_dir);
        FILE *fl = popen(cmd, "r");
        if(fl){ fscanf(fl, "%d", &n_lmod); pclose(fl); }
        if(n_lmod > 0)
            printf("  \033[0;90mlmod:\033[0m          \033[1;32m%d módulos do usuário\033[0m \033[0;90m(%s)\033[0m\n",
                   n_lmod, lmod_dir);

        /* dependências externas: clang, tgpt, git, curl, nmap */
        printf("\n  \033[1;33m── Dependências ─────────────────────────────────────────────────\033[0m\n");
        const char *deps[] = {
            "clang","tgpt","git","curl","nmap","figlet",
            "sqlite3","openssl","wget","pkg","bash","file", NULL
        };
        int dep_ok=0, dep_miss=0;
        for(int d=0; deps[d]; d++){
            char dc[128];
            snprintf(dc, sizeof(dc), "command -v %s >/dev/null 2>&1 && echo 1 || echo 0", deps[d]);
            FILE *fd = popen(dc, "r");
            int found=0;
            if(fd){ fscanf(fd,"%d",&found); pclose(fd); }
            if(found){
