            if((d+1)%3==0) printf("\n");
        }
        printf("\n");
        printf("  \033[0;90mDeps presentes:\033[0m \033[1;32m%d\033[0m  \033[0;90mausentes:\033[0m \033[0;90m%d\033[0m\n", dep_ok, dep_miss);

        /* resumo geral */
        printf("\n  \033[1;33m── Resumo do Sistema ────────────────────────────────────────────\033[0m\n");
        printf("  \033[0;90mScripts instalados:\033[0m \033[1;37m%d\033[0m\n", n_scripts);
        if(n_cmds>0) printf("  \033[0;90mComandos ms --:\033[0m     \033[1;37m%d\033[0m\n", n_cmds);
        if(n_lmod>0) printf("  \033[0;90mModulos lmod:\033[0m       \033[1;37m%d\033[0m\n", n_lmod);
        printf("  \033[0;90mDependencias OK:\033[0m    \033[1;37m%d/%d\033[0m\n", dep_ok, dep_ok+dep_miss);
        /* ivar — variáveis indexadas (experimental) */
        {
            printf("  \033[0;90mIvar (exp):\033[0m         %s\033[0m\n",
                   g_ivar_enabled ? "\033[1;32mtrue" : "\033[0;90mfalse");
        }
    }

    printf("\n");
    return 0;
}
static int l_sys_env(lua_State *L) {
    // sys.env("VAR") → valor ou nil
    // sys.env("VAR", "valor") → seta variável (processo atual)
    // sys.env() → tabela com todas
    if (lua_gettop(L) == 0) {
        // retorna tabela com env completo
        extern char **environ;
        lua_newtable(L);
        for (char **e = environ; *e; e++) {
            char *eq = strchr(*e, '=');
            if (!eq) continue;
            lua_pushlstring(L, *e, (size_t)(eq - *e));
            lua_pushstring(L, eq + 1);
            lua_settable(L, -3);
        }
        return 1;
    }
    const char *name = luaL_checkstring(L, 1);
    if (lua_gettop(L) >= 2) {
        // setar
        const char *val = luaL_checkstring(L, 2);
        lua_pushboolean(L, setenv(name, val, 1) == 0);
        return 1;
    }
    // ler
    const char *v = getenv(name);
    if (v) lua_pushstring(L, v);
    else   lua_pushnil(L);
    return 1;
}

static int l_sys_pid(lua_State *L) {
    lua_pushinteger(L, (lua_Integer)getpid());
    return 1;
}

static int l_sys_exit(lua_State *L) {
    int code = (int)luaL_optinteger(L, 1, 0);
    exit(code);
    return 0; // unreachable
}

/* ══════════════════════════════════════════════════════════════════════════════
 * sys.time()    → float  — wall clock em segundos (CLOCK_REALTIME)
 * sys.time_ms() → int    — wall clock em milissegundos
 * sys.sleep(ms) → void   — dorme N milissegundos (nanosleep, sem spawnar processo)
 * sys.mutex()   → objeto mutex com :lock() :unlock() :try() :destroy()
 * ══════════════════════════════════════════════════════════════════════════════ */

/* ── sys.time() ─────────────────────────────────────────────────────────────── */
static int l_sys_time(lua_State *L) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    lua_pushnumber(L, (lua_Number)ts.tv_sec + (lua_Number)ts.tv_nsec / 1e9);
    return 1;
}

/* ── sys.time_ms() ──────────────────────────────────────────────────────────── */
static int l_sys_time_ms(lua_State *L) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    lua_pushinteger(L, (lua_Integer)ts.tv_sec * 1000 + (lua_Integer)(ts.tv_nsec / 1000000));
    return 1;
}

/* ── sys.sleep(ms) ──────────────────────────────────────────────────────────── */
static int l_sys_sleep(lua_State *L) {
    lua_Number ms = luaL_checknumber(L, 1);
    if (ms <= 0) return 0;
    struct timespec ts;
    ts.tv_sec  = (time_t)(ms / 1000.0);
    ts.tv_nsec = (long)(((long long)ms % 1000) * 1000000L);
    nanosleep(&ts, NULL);
    return 0;
}

/* ══ sys.mutex() — objeto mutex baseado em pthread_mutex_t ═══════════════════ */
#define SYS_MUTEX_META "ElliotOS.Mutex"

typedef struct {
    pthread_mutex_t m;
    int             destroyed;
} LuaMutex;

static int l_mutex_lock(lua_State *L) {
    LuaMutex *mx = (LuaMutex*)luaL_checkudata(L, 1, SYS_MUTEX_META);
    if (mx->destroyed) return luaL_error(L, "mutex já destruído");
    int rc = pthread_mutex_lock(&mx->m);
    lua_pushboolean(L, rc == 0);
    return 1;
}

static int l_mutex_unlock(lua_State *L) {
    LuaMutex *mx = (LuaMutex*)luaL_checkudata(L, 1, SYS_MUTEX_META);
    if (mx->destroyed) return luaL_error(L, "mutex já destruído");
    int rc = pthread_mutex_unlock(&mx->m);
    lua_pushboolean(L, rc == 0);
    return 1;
}

static int l_mutex_try(lua_State *L) {
    LuaMutex *mx = (LuaMutex*)luaL_checkudata(L, 1, SYS_MUTEX_META);
    if (mx->destroyed) { lua_pushboolean(L, 0); return 1; }
    /* trylock: retorna true se adquiriu, false se já está bloqueado */
    int rc = pthread_mutex_trylock(&mx->m);
    lua_pushboolean(L, rc == 0);
    return 1;
}

static int l_mutex_destroy(lua_State *L) {
    LuaMutex *mx = (LuaMutex*)luaL_checkudata(L, 1, SYS_MUTEX_META);
    if (!mx->destroyed) {
        pthread_mutex_destroy(&mx->m);
        mx->destroyed = 1;
    }
    return 0;
}

/* __gc: destrói automaticamente quando coletado */
static int l_mutex_gc(lua_State *L) {
    return l_mutex_destroy(L);
}

/* __tostring */
static int l_mutex_tostring(lua_State *L) {
    LuaMutex *mx = (LuaMutex*)luaL_checkudata(L, 1, SYS_MUTEX_META);
    lua_pushfstring(L, "mutex(%s)", mx->destroyed ? "destroyed" : "active");
    return 1;
}

static void mutex_register_meta(lua_State *L) {
    if (luaL_newmetatable(L, SYS_MUTEX_META)) {
        lua_pushvalue(L, -1);
        lua_setfield(L, -2, "__index");
        lua_pushcfunction(L, l_mutex_lock);     lua_setfield(L, -2, "lock");
        lua_pushcfunction(L, l_mutex_unlock);   lua_setfield(L, -2, "unlock");
        lua_pushcfunction(L, l_mutex_try);      lua_setfield(L, -2, "try");
        lua_pushcfunction(L, l_mutex_destroy);  lua_setfield(L, -2, "destroy");
        lua_pushcfunction(L, l_mutex_gc);       lua_setfield(L, -2, "__gc");
        lua_pushcfunction(L, l_mutex_tostring); lua_setfield(L, -2, "__tostring");
    }
    lua_pop(L, 1);
}

static int l_sys_mutex(lua_State *L) {
    mutex_register_meta(L);
    LuaMutex *mx = (LuaMutex*)lua_newuserdata(L, sizeof(LuaMutex));
    mx->destroyed = 0;
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    /* PTHREAD_MUTEX_RECURSIVE: mesma thread pode fazer lock múltiplas vezes */
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&mx->m, &attr);
    pthread_mutexattr_destroy(&attr);
    luaL_getmetatable(L, SYS_MUTEX_META);
    lua_setmetatable(L, -2);
    return 1;
}

/* ══════════════════════════════════════════════════════════════════════════════
 * sys.channel() — Canal de comunicação entre threads via pipe POSIX
 *
 * Cria um par de fds (read/write). O objeto retornado tem:
 *   ch:send(str)           — envia string (bloqueia se buffer cheio)
 *   ch:recv([timeout_ms])  — recebe string (bloqueia até dados ou timeout)
 *   ch:close()             — fecha ambos os fds
 *   ch:fd_r()              — retorna fd de leitura (para passar a threads)
 *   ch:fd_w()              — retorna fd de escrita
 *
 * Uso típico:
 *   local ch = sys.channel()
 *   local tid = sys.thread(string.format([[
 *       local fd = %d
 *       -- escreve no canal
 *       local f = io.open("/proc/self/fd/"..fd, "w")
 *       f:write("resultado\n"); f:close()
 *   ]], ch:fd_w()))
 *   local msg = ch:recv(5000)  -- recebe com timeout 5s
 *   ch:close()
 *
 * Alternativa simples (send/recv via métodos):
 *   ch:send("hello")   -- na thread produtora
 *   ch:recv(1000)      -- na thread consumidora (timeout 1s)
 * ══════════════════════════════════════════════════════════════════════════════ */

#define SYS_CHAN_META "ElliotOS.Channel"

typedef struct {
    int rfd;
    int wfd;
    int closed;
} LuaChannel;

static int l_chan_send(lua_State *L) {
    LuaChannel *ch = (LuaChannel*)luaL_checkudata(L, 1, SYS_CHAN_META);
    if (ch->closed || ch->wfd < 0) {
        lua_pushnil(L); lua_pushstring(L,"canal fechado"); return 2;
    }
    size_t len; const char *msg = luaL_checklstring(L, 2, &len);

    /* Protocolo: 4 bytes de tamanho (big-endian) + dados */
    uint32_t nlen = (uint32_t)len;
    unsigned char hdr[4];
    hdr[0]=(nlen>>24)&0xFF; hdr[1]=(nlen>>16)&0xFF;
    hdr[2]=(nlen>>8)&0xFF;  hdr[3]=nlen&0xFF;

    ssize_t w = write(ch->wfd, hdr, 4);
    if (w < 4) { lua_pushnil(L); lua_pushstring(L,"write header falhou"); return 2; }
    size_t sent=0;
    while (sent < len) {
        ssize_t n = write(ch->wfd, msg+sent, len-sent);
        if (n <= 0) { lua_pushnil(L); lua_pushstring(L,"write dados falhou"); return 2; }
        sent += (size_t)n;
    }
    lua_pushboolean(L, 1); return 1;
}

static int l_chan_recv(lua_State *L) {
    LuaChannel *ch = (LuaChannel*)luaL_checkudata(L, 1, SYS_CHAN_META);
    if (ch->closed || ch->rfd < 0) {
        lua_pushnil(L); lua_pushstring(L,"canal fechado"); return 2;
    }
    int timeout_ms = (int)luaL_optinteger(L, 2, -1); /* -1 = sem timeout */

    /* Espera dados com poll() */
    if (timeout_ms >= 0) {
        struct pollfd pfd; pfd.fd=ch->rfd; pfd.events=POLLIN; pfd.revents=0;
        int pr = poll(&pfd, 1, timeout_ms);
        if (pr == 0) { lua_pushnil(L); lua_pushstring(L,"tempo esgotado"); return 2; }
        if (pr <  0) { lua_pushnil(L); lua_pushstring(L,"erro de poll"); return 2; }
    }

    /* Lê header de 4 bytes com tamanho */
    unsigned char hdr[4]={0};
    ssize_t got=0;
    while (got < 4) {
        ssize_t n = read(ch->rfd, hdr+got, 4-got);
        if (n <= 0) { lua_pushnil(L); lua_pushstring(L,"pipe fechado"); return 2; }
        got += n;
    }
    uint32_t msglen = ((uint32_t)hdr[0]<<24)|((uint32_t)hdr[1]<<16)|
                      ((uint32_t)hdr[2]<<8)|(uint32_t)hdr[3];
    if (msglen == 0)  { lua_pushstring(L,""); return 1; }
    if (msglen > 4*1024*1024) { /* 4MB max por mensagem */
        lua_pushnil(L); lua_pushstring(L,"mensagem muito grande"); return 2;
    }

    char *buf = (char*)malloc(msglen+1);
    if (!buf) { lua_pushnil(L); lua_pushstring(L,"malloc falhou"); return 2; }
    size_t total=0;
    while (total < msglen) {
        ssize_t n = read(ch->rfd, buf+total, msglen-total);
        if (n <= 0) { free(buf); lua_pushnil(L); lua_pushstring(L,"leitura truncada"); return 2; }
        total += (size_t)n;
    }
    buf[msglen]='\0';
    lua_pushlstring(L, buf, msglen);
    free(buf); return 1;
}

static int l_chan_close(lua_State *L) {
    LuaChannel *ch = (LuaChannel*)luaL_checkudata(L, 1, SYS_CHAN_META);
    if (!ch->closed) {
        if (ch->rfd >= 0) { close(ch->rfd); ch->rfd=-1; }
        if (ch->wfd >= 0) { close(ch->wfd); ch->wfd=-1; }
        ch->closed=1;
    }
    return 0;
}

static int l_chan_fd_r(lua_State *L) {
    LuaChannel *ch = (LuaChannel*)luaL_checkudata(L, 1, SYS_CHAN_META);
    lua_pushinteger(L, ch->rfd); return 1;
}
static int l_chan_fd_w(lua_State *L) {
    LuaChannel *ch = (LuaChannel*)luaL_checkudata(L, 1, SYS_CHAN_META);
    lua_pushinteger(L, ch->wfd); return 1;
}
static int l_chan_gc(lua_State *L)       { return l_chan_close(L); }
static int l_chan_tostring(lua_State *L) {
    LuaChannel *ch = (LuaChannel*)luaL_checkudata(L, 1, SYS_CHAN_META);
    lua_pushfstring(L, "channel(r=%d,w=%d)", ch->rfd, ch->wfd); return 1;
}

static void channel_register_meta(lua_State *L) {
    if (luaL_newmetatable(L, SYS_CHAN_META)) {
        lua_pushvalue(L,-1); lua_setfield(L,-2,"__index");
        lua_pushcfunction(L,l_chan_send);     lua_setfield(L,-2,"send");
        lua_pushcfunction(L,l_chan_recv);     lua_setfield(L,-2,"recv");
        lua_pushcfunction(L,l_chan_close);    lua_setfield(L,-2,"close");
        lua_pushcfunction(L,l_chan_fd_r);     lua_setfield(L,-2,"fd_r");
        lua_pushcfunction(L,l_chan_fd_w);     lua_setfield(L,-2,"fd_w");
        lua_pushcfunction(L,l_chan_gc);       lua_setfield(L,-2,"__gc");
        lua_pushcfunction(L,l_chan_tostring); lua_setfield(L,-2,"__tostring");
    }
    lua_pop(L,1);
}

static int l_sys_channel(lua_State *L) {
    channel_register_meta(L);
    int pfd[2];
    if (pipe(pfd) != 0) {
        lua_pushnil(L); lua_pushstring(L,strerror(errno)); return 2;
    }
    LuaChannel *ch = (LuaChannel*)lua_newuserdata(L, sizeof(LuaChannel));
    ch->rfd=pfd[0]; ch->wfd=pfd[1]; ch->closed=0;
    luaL_getmetatable(L, SYS_CHAN_META);
    lua_setmetatable(L,-2);
    return 1;
}


/* ── sys.net() — interface ativa + bytes TX/RX via /proc/net/dev ── */
static int l_sys_net(lua_State *L) {
    FILE *f = fopen("/proc/net/dev", "r");

    /* ── Fallback: /proc/net/dev bloqueado (Android HyperOS/MIUI) ── */
    if (!f) {
        lua_newtable(L);
        int count = 0;

        /* Tenta /sys/class/net/[iface]/statistics/ - sem root, sem netlink */
        DIR *nd = opendir("/sys/class/net");
        if (nd) {
            struct dirent *de;
            while ((de = readdir(nd)) != NULL) {
                if (de->d_name[0] == '.') continue;
                char path[256];
                unsigned long long rx_bytes=0, tx_bytes=0, rx_pkts=0, tx_pkts=0;
                int got = 0;
                #define _SYS_READ(field, var) do { \
                    FILE *_sf; \
                    snprintf(path,sizeof(path),"/sys/class/net/%s/statistics/%s",de->d_name,field); \
                    _sf=fopen(path,"r"); \
                    if(_sf){fscanf(_sf,"%llu",&(var));fclose(_sf);got++;} \
                } while(0)
                _SYS_READ("rx_bytes",   rx_bytes);
                _SYS_READ("tx_bytes",   tx_bytes);
                _SYS_READ("rx_packets", rx_pkts);
                _SYS_READ("tx_packets", tx_pkts);
                #undef _SYS_READ
                if (got == 0) continue;

                lua_newtable(L);
                lua_pushstring(L,de->d_name); lua_setfield(L,-2,"iface");
                int islo=(strcmp(de->d_name,"lo")==0);
                lua_pushboolean(L,islo); lua_setfield(L,-2,"loopback");
                lua_newtable(L);
                lua_pushinteger(L,(lua_Integer)rx_bytes); lua_setfield(L,-2,"bytes");
                lua_pushinteger(L,(lua_Integer)rx_pkts);  lua_setfield(L,-2,"packets");
                lua_setfield(L,-2,"rx");
                lua_newtable(L);
                lua_pushinteger(L,(lua_Integer)tx_bytes); lua_setfield(L,-2,"bytes");
                lua_pushinteger(L,(lua_Integer)tx_pkts);  lua_setfield(L,-2,"packets");
                lua_setfield(L,-2,"tx");
                unsigned long long tot=rx_bytes+tx_bytes;
                char human[32];
                if(tot>=1024ULL*1024*1024) snprintf(human,sizeof(human),"%.2f GB",tot/(1024.0*1024*1024));
                else if(tot>=1024ULL*1024) snprintf(human,sizeof(human),"%.2f MB",tot/(1024.0*1024));
                else if(tot>=1024ULL)      snprintf(human,sizeof(human),"%.2f KB",tot/1024.0);
                else                       snprintf(human,sizeof(human),"%llu B",tot);
                lua_pushstring(L,human); lua_setfield(L,-2,"total_human");
                lua_rawseti(L,-2,++count);
            }
            closedir(nd);
        }

        if (count == 0) {
            lua_pop(L,1);
            lua_pushnil(L);
            lua_pushstring(L,
                "sys.net: /proc/net/dev e /sys/class/net bloqueados.\n"
                "  Este dispositivo (HyperOS/MIUI) restringe acesso a stats de rede sem root.\n"
                "  Alternativa: sh.capture('ifconfig') se net-tools estiver instalado.");
            return 2;
        }

        /* printa resumo */
        printf("\033[1;36m── Interfaces de rede (/sys/class/net) ─────────────\033[0m\n");
        for (int i=1; i<=count; i++) {
            lua_rawgeti(L,-1,i);
            lua_getfield(L,-1,"iface");
            lua_getfield(L,-2,"loopback");
            lua_getfield(L,-3,"rx"); lua_getfield(L,-1,"bytes"); lua_remove(L,-2);
            lua_getfield(L,-4,"tx"); lua_getfield(L,-1,"bytes"); lua_remove(L,-2);
            lua_getfield(L,-5,"total_human");
            const char *ifc=lua_tostring(L,-5);
            int islo=lua_toboolean(L,-4);
            long long rxb=(long long)lua_tointeger(L,-3);
            long long txb=(long long)lua_tointeger(L,-2);
            const char *tot2=lua_tostring(L,-1);
            const char *col=islo?"\033[0;90m":"\033[1;33m";
            printf("  %s%-12s\033[0m  RX:\033[1;32m%8.2f MB\033[0m  TX:\033[1;33m%8.2f MB\033[0m  Total:\033[1;37m%s\033[0m\n",
                   col,ifc?ifc:"?",rxb/(1024.0*1024),txb/(1024.0*1024),tot2?tot2:"?");
            lua_pop(L,6);
        }
        printf("\033[0;90m  Fonte: /sys/class/net/*/statistics\033[0m\n\n");
        return 1;
    }

    /* ── Caminho normal: /proc/net/dev disponível ── */
    char line[512];
    fgets(line, sizeof(line), f); /* Inter-|... */
    fgets(line, sizeof(line), f); /* face |bytes... */

    lua_newtable(L); /* tabela de resultado */
    int count = 0;

    while (fgets(line, sizeof(line), f)) {
        char iface[64] = {0};
        unsigned long long rx_bytes=0, rx_pkts=0, rx_err=0, rx_drop=0;
        unsigned long long tx_bytes=0, tx_pkts=0, tx_err=0, tx_drop=0;
        /* /proc/net/dev: iface: rx_bytes pkts err drop fifo frame compressed multicast
                                 tx_bytes pkts err drop fifo colls carrier compressed */
        int n = sscanf(line,
            " %63[^:]: %llu %llu %llu %llu %*u %*u %*u %*u"
                      " %llu %llu %llu %llu",
            iface,
            &rx_bytes, &rx_pkts, &rx_err, &rx_drop,
            &tx_bytes, &tx_pkts, &tx_err, &tx_drop);

        if (n < 9) continue;

        /* ignora loopback e interfaces com 0 bytes em ambas direções */
        int is_lo = (strcmp(iface, "lo") == 0);
        if (is_lo && rx_bytes == 0 && tx_bytes == 0) continue;

        /* monta sub-tabela por interface */
        lua_newtable(L);

        lua_pushstring(L, iface);   lua_setfield(L, -2, "iface");
        lua_pushboolean(L, is_lo);  lua_setfield(L, -2, "loopback");

        /* rx */
        lua_newtable(L);
        lua_pushinteger(L, (lua_Integer)rx_bytes); lua_setfield(L, -2, "bytes");
        lua_pushinteger(L, (lua_Integer)rx_pkts);  lua_setfield(L, -2, "packets");
        lua_pushinteger(L, (lua_Integer)rx_err);   lua_setfield(L, -2, "errors");
        lua_pushinteger(L, (lua_Integer)rx_drop);  lua_setfield(L, -2, "dropped");
        lua_setfield(L, -2, "rx");

        /* tx */
        lua_newtable(L);
        lua_pushinteger(L, (lua_Integer)tx_bytes); lua_setfield(L, -2, "bytes");
        lua_pushinteger(L, (lua_Integer)tx_pkts);  lua_setfield(L, -2, "packets");
        lua_pushinteger(L, (lua_Integer)tx_err);   lua_setfield(L, -2, "errors");
        lua_pushinteger(L, (lua_Integer)tx_drop);  lua_setfield(L, -2, "dropped");
        lua_setfield(L, -2, "tx");

        /* bytes totais formatados (KB/MB/GB) */
        unsigned long long total = rx_bytes + tx_bytes;
        char human[32];
        if      (total >= 1024ULL*1024*1024) snprintf(human,sizeof(human),"%.2f GB", total/(1024.0*1024*1024));
        else if (total >= 1024ULL*1024)      snprintf(human,sizeof(human),"%.2f MB", total/(1024.0*1024));
        else if (total >= 1024ULL)           snprintf(human,sizeof(human),"%.2f KB", total/1024.0);
        else                                 snprintf(human,sizeof(human),"%llu B",  total);
        lua_pushstring(L, human); lua_setfield(L, -2, "total_human");

        lua_rawseti(L, -2, ++count);
    }
    fclose(f);

    if (count == 0) {
        lua_pop(L, 1);
        lua_pushnil(L);
        lua_pushstring(L, "nenhuma interface encontrada em /proc/net/dev");
        return 2;
    }

    /* printa resumo sempre que chamado sem args ou com arg 'print' */
    int do_print = (lua_gettop(L) == 0) ||
                   (lua_gettop(L) >= 1 && lua_isstring(L,1) &&
                    strcmp(lua_tostring(L,1),"print")==0);
    /* na prática a tabela é o único item no stack ao retornar — sempre printa */
    do_print = 1;
    if (do_print) {
        printf("\033[1;36m── Interfaces de rede ──────────────────────────────\033[0m\n");
        for (int i = 1; i <= count; i++) {
            lua_rawgeti(L, -1, i);
            lua_getfield(L, -1, "iface");
            lua_getfield(L, -2, "loopback");
            lua_getfield(L, -3, "rx"); lua_getfield(L, -1, "bytes"); lua_remove(L, -2);
            lua_getfield(L, -4, "tx"); lua_getfield(L, -1, "bytes"); lua_remove(L, -2);
            lua_getfield(L, -5, "total_human");

            const char *ifc  = lua_tostring(L, -5);
            int         islo = lua_toboolean(L, -4);
            long long   rxb  = (long long)lua_tointeger(L, -3);
            long long   txb  = (long long)lua_tointeger(L, -2);
            const char *tot  = lua_tostring(L, -1);

            const char *col = islo ? "\033[0;90m" : "\033[1;33m";
            const char *tag = islo ? " (lo)" : "";
            printf("  %s%-10s\033[0m%s  RX: \033[1;32m%8.2f MB\033[0m  "
                   "TX: \033[1;33m%8.2f MB\033[0m  Total: \033[1;37m%s\033[0m\n",
                   col, ifc ? ifc : "?", tag,
                   rxb / (1024.0*1024),
                   txb / (1024.0*1024),
                   tot ? tot : "?");

            lua_pop(L, 6); /* ifc, islo, rxb, txb, tot, sub-tabela */
        }
        printf("\033[0;90m  Fonte: /proc/net/dev\033[0m\n\n");
    }

    return 1;
}

/* ── sys.storage() — espaço em disco via statvfs ── */
static int l_sys_storage(lua_State *L) {
    /* path padrão = HOME do Termux; aceita arg opcional */
    const char *path = "/data/data/com.termux/files";
    if (lua_gettop(L) >= 1 && lua_isstring(L, 1))
        path = lua_tostring(L, 1);

    struct statvfs st;
    if (statvfs(path, &st) != 0) {
        /* tenta fallback para /sdcard */
        if (statvfs("/sdcard", &st) != 0) {
            lua_pushnil(L);
            lua_pushfstring(L,
                "statvfs() falhou em '%s': %s — Android pode bloquear acesso a este path",
                path, strerror(errno));
            return 2;
        }
        path = "/sdcard";
    }

    unsigned long long block   = (unsigned long long)st.f_frsize;
    unsigned long long total   = block * (unsigned long long)st.f_blocks;
    unsigned long long free_b  = block * (unsigned long long)st.f_bfree;
    unsigned long long avail   = block * (unsigned long long)st.f_bavail;
    unsigned long long used    = total - free_b;

    /* helper: formata bytes em string legível */
    #define _FMT_BYTES(n, buf) do { \
        unsigned long long _v = (n); \
        if      (_v >= 1024ULL*1024*1024) snprintf(buf,sizeof(buf),"%.2f GB",_v/(1024.0*1024*1024)); \
        else if (_v >= 1024ULL*1024)      snprintf(buf,sizeof(buf),"%.2f MB",_v/(1024.0*1024)); \
        else if (_v >= 1024ULL)           snprintf(buf,sizeof(buf),"%.2f KB",_v/1024.0); \
        else                              snprintf(buf,sizeof(buf),"%llu B",_v); \
    } while(0)

    char s_total[32], s_used[32], s_free[32], s_avail[32];
    _FMT_BYTES(total, s_total);
    _FMT_BYTES(used,  s_used);
    _FMT_BYTES(free_b,s_free);
    _FMT_BYTES(avail, s_avail);
    #undef _FMT_BYTES

    double pct_used = total > 0 ? (used * 100.0 / total) : 0.0;

    /* tabela de retorno */
    lua_newtable(L);
    lua_pushstring(L, path);          lua_setfield(L, -2, "path");
    lua_pushinteger(L,(lua_Integer)total); lua_setfield(L,-2,"total_bytes");
    lua_pushinteger(L,(lua_Integer)used);  lua_setfield(L,-2,"used_bytes");
    lua_pushinteger(L,(lua_Integer)free_b);lua_setfield(L,-2,"free_bytes");
    lua_pushinteger(L,(lua_Integer)avail); lua_setfield(L,-2,"avail_bytes");
    lua_pushstring(L, s_total);       lua_setfield(L, -2, "total");
    lua_pushstring(L, s_used);        lua_setfield(L, -2, "used");
    lua_pushstring(L, s_free);        lua_setfield(L, -2, "free");
    lua_pushstring(L, s_avail);       lua_setfield(L, -2, "avail");
    lua_pushnumber(L, pct_used);      lua_setfield(L, -2, "pct_used");

    /* barra visual de uso */
    int bar_w = 30;
    int bar_fill = (int)(pct_used * bar_w / 100.0);
    char bar[64] = {0};
    for (int i = 0; i < bar_w; i++)
        bar[i] = (i < bar_fill) ? '#' : '-';
    lua_pushstring(L, bar); lua_setfield(L, -2, "bar");

    /* printa resumo */
    const char *color = pct_used > 90 ? "\033[1;31m"
                      : pct_used > 70 ? "\033[1;33m"
                      :                 "\033[1;32m";
    printf("\033[1;36m── Armazenamento (%s) ───────────────────────────\033[0m\n", path);
    printf("  Total     : \033[1;37m%s\033[0m\n", s_total);
    printf("  Usado     : %s%s\033[0m  (%.1f%%)\n", color, s_used, pct_used);
    printf("  Disponível: \033[1;32m%s\033[0m\n", s_avail);
    printf("  %s[%s]\033[0m  %.1f%%\n", color, bar, pct_used);
    if (pct_used > 90)
        printf("  \033[1;31m⚠ Espaço crítico! Limpe arquivos desnecessários.\033[0m\n");
    printf("\033[0;90m  Fonte: statvfs('%s')\033[0m\n\n", path);

    return 1;
}

static int l_sys_help(lua_State *L) {
    (void)L;
    printf("\n\033[1;36m╔══════════════════════════════════════════════════════════════╗\033[0m\n");
    printf("\033[1;36m║  sys — Processos, Threads Shell e Threads Lua                ║\033[0m\n");
    printf("\033[1;36m╚══════════════════════════════════════════════════════════════╝\033[0m\n\n");

    printf("  \033[1;36m── PROCESSOS / SHELL ──────────────────────────────────────────\033[0m\n\n");

    printf("  \033[1;33msys.spawn\033[0m(cmd)\n");
    printf("    Executa comando em processo filho separado (fork+exec).\n");
    printf("    cmd     : string de comando shell  ex: 'sleep 10'\n");
