    return 0;
}


static int l_c_run(lua_State *L) {
    const char *code = luaL_checkstring(L, 1);

    /* ── 1. diretório base executável ─────────────────────────────── */
    const char *home = getenv("HOME");
    if (!home || !home[0]) home = "/data/data/com.termux/files/home";

    /* ── 2. arquivo fonte temporário ──────────────────────────────── */
    char src[512];
    snprintf(src, sizeof(src), "%s/.elliot_cc_%d.c", home, (int)getpid());
    FILE *sf = fopen(src, "w");
    if (!sf) { lua_pushstring(L, "fopen falhou"); return 1; }
    fwrite(code, 1, strlen(code), sf);
    fclose(sf);

    /* ── 3. path do binário ────────────────────────────────────────── */
    char bin[512];
    snprintf(bin, sizeof(bin), "%s/.elliot_cc_%d", home, (int)getpid());

    /* ── 4. compilar via sh -c capturando stderr ──────────────────── */
    char cmd[1200];
    /* tenta clang, senão gcc */
    snprintf(cmd, sizeof(cmd),
        "if command -v clang >/dev/null 2>&1; then"
        "  clang \"%s\" -o \"%s\" -lm 2>&1;"
        "elif command -v gcc >/dev/null 2>&1; then"
        "  gcc \"%s\" -o \"%s\" -lm 2>&1;"
        "else echo NO_COMPILER; fi",
        src, bin, src, bin);

    /* temporariamente SIG_DFL para popen/pclose funcionar */
    struct sigaction sa_old, sa_tmp = {0};
    sa_tmp.sa_handler = SIG_DFL;
    sigaction(SIGCHLD, &sa_tmp, &sa_old);

    char errbuf[2048] = {0};
    FILE *cf = popen(cmd, "r");
    if (cf) {
        fread(errbuf, 1, sizeof(errbuf)-1, cf);
        pclose(cf);
    }

    sigaction(SIGCHLD, &sa_old, NULL); /* restaura handler original */

    /* ── 5. verificar se binário foi gerado ───────────────────────── */
    if (strstr(errbuf, "NO_COMPILER")) {
        remove(src);
        lua_pushstring(L, "clang/gcc não encontrado");
        return 1;
    }
    struct stat _st;
    if (stat(bin, &_st) != 0) {
        remove(src);
        if (errbuf[0])
            lua_pushstring(L, errbuf);
        else
            lua_pushstring(L, "compilador não gerou binário");
        return 1;
    }
    chmod(bin, 0755);
    remove(src);

    /* ── 6. executar via fork+execv com waitpid SIG_DFL ──────────── */
    sigaction(SIGCHLD, &sa_tmp, &sa_old); /* SIG_DFL durante waitpid */

    pid_t pid = fork();
    if (pid < 0) {
        sigaction(SIGCHLD, &sa_old, NULL);
        remove(bin);
        lua_pushstring(L, "fork falhou");
        return 1;
    }
    if (pid == 0) {
        /* filho */
        char *av[] = {bin, NULL};
        execv(bin, av);
        _exit(127);
    }
    /* pai: espera filho com SIG_DFL ativo */
    int wst = 0;
    while (waitpid(pid, &wst, 0) < 0 && errno == EINTR) {}
    sigaction(SIGCHLD, &sa_old, NULL); /* restaura */

    remove(bin);
    int exitcode = WIFEXITED(wst) ? WEXITSTATUS(wst) : -1;
    lua_pushinteger(L, exitcode);
    return 1;
}
