    return 0;
}


/* cc.lua2c - Transpilador Lua -> C  (ElliotOS v19.0 - Professional)
 *
 * Arquitetura:
 *   Fase 1 - Tokenizer : stream de tokens tipados
 *   Fase 2 - Parser    : Pratt parser por precedencia
 *   Fase 3 - Emitter   : caminha tokens e emite C valido
 *
 * Cobertura Lua 5.4:
 *   - local com inferencia de tipo (int/double/char[]/const char*)
 *   - funcoes named, local, anonimas com forward decls automaticas
 *   - retorno multiplo e atribuicao multipla
 *   - tabelas numericas como arrays C
 *   - for numerico e for generico (ipairs)
 *   - while / repeat..until / do..end
 *   - if / elseif / else aninhados
 *   - operadores: .. (concat), ^ (pow), // (idiv), ~= (neq), # (len)
 *   - string.*, math.*, os.*, io.*, table.*
 *   - goto e ::labels::
 *   - runtime header embutido com helpers seguros
 *   - buffer dinamico sem limite fixo (realloc)
 *   - tabela de simbolos com escopos aninhados ilimitados
 * ======================================================================== */
/* ============================================================================
 * SECTION 0 -- Buffer dinamico (shared com resto de libnet.c)
 * ============================================================================ */
/* ── Buffer dinamico L2CBuf ─────────────────────────────────────────────── */
typedef struct { char *buf; size_t len; size_t cap; } L2CBuf;

static void l2c_buf_init(L2CBuf *b){
    b->cap = 256; b->len = 0;
    b->buf = (char*)malloc(b->cap);
    if(b->buf) b->buf[0] = '\0';
}
static void l2c_buf_free(L2CBuf *b){ free(b->buf); b->buf=NULL; b->len=b->cap=0; }
static void l2c_buf_reset(L2CBuf *b){ b->len=0; if(b->buf) b->buf[0]='\0'; }

static void l2c_buf_grow(L2CBuf *b, size_t need){
    if(b->len + need + 1 <= b->cap) return;
    while(b->cap < b->len + need + 1) b->cap *= 2;
    b->buf = (char*)realloc(b->buf, b->cap);
}
static void l2c_buf_add(L2CBuf *b, const char *s){
    size_t n = strlen(s);
    l2c_buf_grow(b, n);
    memcpy(b->buf + b->len, s, n);
    b->len += n;
    b->buf[b->len] = '\0';
}
static void l2c_buf_addc(L2CBuf *b, char c){
    l2c_buf_grow(b, 1);
    b->buf[b->len++] = c;
    b->buf[b->len]   = '\0';
}
static void l2c_buf_addn(L2CBuf *b, const char *s, size_t n){
    l2c_buf_grow(b, n);
    memcpy(b->buf + b->len, s, n);
    b->len += n;
    b->buf[b->len] = '\0';
}
static void l2c_buf_addf(L2CBuf *b, const char *fmt, ...){
    char tmp[512]; va_list ap; va_start(ap,fmt);
    vsnprintf(tmp, sizeof(tmp), fmt, ap); va_end(ap);
    l2c_buf_add(b, tmp);
}
static void l2c_buf_append(L2CBuf *dst, const L2CBuf *src){
    if(src->len) l2c_buf_addn(dst, src->buf, src->len);
}

/* ============================================================================
 * SECTION 1 -- Tokenizer
 * ============================================================================ */

typedef enum {
    /* literals */
    TK_INT, TK_FLOAT, TK_STRING, TK_IDENT,
    /* keywords */
    TK_AND, TK_BREAK, TK_DO, TK_ELSE, TK_ELSEIF, TK_END,
    TK_FALSE, TK_FOR, TK_FUNCTION, TK_GOTO, TK_IF, TK_IN,
    TK_LOCAL, TK_NIL, TK_NOT, TK_OR, TK_REPEAT, TK_RETURN,
    TK_THEN, TK_TRUE, TK_UNTIL, TK_WHILE,
    /* operators */
    TK_PLUS, TK_MINUS, TK_STAR, TK_SLASH, TK_PERCENT, TK_CARET,
    TK_HASH, TK_AMPERSAND, TK_TILDE, TK_PIPE,
    TK_LSHIFT, TK_RSHIFT, TK_DSLASH,   /* // */
    TK_EQ, TK_NEQ, TK_LT, TK_LE, TK_GT, TK_GE,
    TK_ASSIGN,
    TK_LPAREN, TK_RPAREN, TK_LBRACE, TK_RBRACE, TK_LBRACKET, TK_RBRACKET,
    TK_SEMICOLON, TK_COLON, TK_DCOLON, TK_COMMA, TK_DOT, TK_DOTDOT, TK_DOTDOTDOT,
    /* compound assign (Lua doesn't have, but common user mistake -- we emit error) */
    TK_PLUSEQ, TK_MINUSEQ, TK_STAREQ, TK_SLASHEQ,
    /* special */
    TK_EOF, TK_ERR
} L2CTokKind;

typedef struct {
    L2CTokKind kind;
    char       str[256];   /* raw text of token */
    int        line;
} L2CTok;

typedef struct {
    const char *src;
    int         pos;
    int         line;
    L2CTok      cur;
    L2CTok      peek;      /* one-token lookahead */
    int         has_peek;
    char        errbuf[256];
} L2CLex;

static void l2c_lex_init(L2CLex *lx, const char *src){
    memset(lx,0,sizeof(*lx));
    lx->src=src; lx->line=1;
}

/* -- helpers -- */
static int l2c_is_digit(char c){ return c>='0'&&c<='9'; }
static int l2c_is_alpha(char c){
    return (c>='a'&&c<='z')||(c>='A'&&c<='Z')||c=='_';
}
static int l2c_is_alnum(char c){ return l2c_is_alpha(c)||l2c_is_digit(c); }

/* -- pula comentario ou whitespace; retorna 1 se avancou -- */
static int l2c_skip_ws_comments(L2CLex *lx){
    const char *s=lx->src; int p=lx->pos; int line=lx->line;
    int changed=0;
    for(;;){
        while(s[p]==' '||s[p]=='\t'||s[p]=='\r'||s[p]=='\n'){
            if(s[p]=='\n') line++;
            p++; changed=1;
        }
        /* long comment --[[ ]] */
        if(s[p]=='-'&&s[p+1]=='-'&&s[p+2]=='['&&s[p+3]=='['){
            p+=4; changed=1;
            while(s[p]&&!(s[p]==']'&&s[p+1]==']')){
                if(s[p]=='\n') line++;
                p++;
            }
            if(s[p]==']') p+=2;
            continue;
        }
        /* line comment -- */
        if(s[p]=='-'&&s[p+1]=='-'){
            p+=2; changed=1;
            while(s[p]&&s[p]!='\n') p++;
            continue;
        }
        break;
    }
    lx->pos=p; lx->line=line;
    return changed;
}

/* -- le long string [[ ... ]] ou [=[ ... ]=] -- retorna conteudo em dst -- */
static int l2c_read_longstr(L2CLex *lx, char *dst, int dsz){
    const char *s=lx->src; int p=lx->pos;
    int level=0;
    if(s[p]!='[') return 0;
    p++;
    while(s[p]=='='){level++;p++;}
    if(s[p]!='[') return 0;
    p++;
    /* skip optional first newline */
    if(s[p]=='\n'){lx->line++;p++;}
    else if(s[p]=='\r'){p++;if(s[p]=='\n'){p++;lx->line++;}}
    int di=0;
    for(;;){
        if(!s[p]){ snprintf(lx->errbuf,sizeof(lx->errbuf),"long string nao fechada"); return -1; }
        if(s[p]=='\n') lx->line++;
        if(s[p]==']'){
            int lv2=0; int q=p+1;
            while(s[q]=='='){ lv2++; q++; }
            if(s[q]==']'&&lv2==level){ p=q+1; break; }
        }
        if(di<dsz-1){ dst[di++]=s[p]; }
        p++;
    }
    dst[di]='\0';
    lx->pos=p;
    return 1;
}

/* -- le proximo token e armazena em *tk -- */
static void l2c_lex_next_raw(L2CLex *lx, L2CTok *tk){
    l2c_skip_ws_comments(lx);
    const char *s=lx->src; int p=lx->pos;
    tk->line=lx->line; tk->str[0]='\0';

    if(!s[p]){ tk->kind=TK_EOF; return; }

    /* numeros */
    if(l2c_is_digit(s[p])||(s[p]=='.'&&l2c_is_digit(s[p+1]))){
        int di=0; int is_float=0;
        if(s[p]=='0'&&(s[p+1]=='x'||s[p+1]=='X')){
            /* hex */
            tk->str[di++]=s[p++]; tk->str[di++]=s[p++];
            while((s[p]>='0'&&s[p]<='9')||(s[p]>='a'&&s[p]<='f')||
                  (s[p]>='A'&&s[p]<='F')||s[p]=='_') {
                if(s[p]!='_'&&di<255){ tk->str[di++]=s[p]; } p++;
            }
            if(s[p]=='.'){ is_float=1; tk->str[di++]=s[p++];
                while(l2c_is_digit(s[p])&&di<255) tk->str[di++]=s[p++]; }
            if((s[p]=='p'||s[p]=='P')&&di<253){
                is_float=1; tk->str[di++]=s[p++];
                if(s[p]=='+'||s[p]=='-') tk->str[di++]=s[p++];
                while(l2c_is_digit(s[p])&&di<255) tk->str[di++]=s[p++];
            }
        } else {
            while((l2c_is_digit(s[p])||s[p]=='_')&&di<255){
                if(s[p]!='_'){ tk->str[di++]=s[p]; } p++;
            }
            if(s[p]=='.'&&s[p+1]!='.'){ is_float=1; tk->str[di++]=s[p++];
                while((l2c_is_digit(s[p])||s[p]=='_')&&di<255){
                    if(s[p]!='_'){ tk->str[di++]=s[p]; } p++;
                }
            }
            if((s[p]=='e'||s[p]=='E')&&di<253){
                is_float=1; tk->str[di++]=s[p++];
                if(s[p]=='+'||s[p]=='-') tk->str[di++]=s[p++];
                while(l2c_is_digit(s[p])&&di<255) tk->str[di++]=s[p++];
            }
        }
        tk->str[di]='\0'; lx->pos=p;
        tk->kind = is_float ? TK_FLOAT : TK_INT;
        return;
    }

    /* strings */
    if(s[p]=='"'||s[p]=='\''){
        char q=s[p++]; int di=0;
        while(s[p]&&s[p]!=q){
            if(s[p]=='\\'){
                p++;
                char esc=s[p++];
                switch(esc){
                    case 'n':  if(di<253){tk->str[di++]='\\';tk->str[di++]='n';} break;
                    case 't':  if(di<253){tk->str[di++]='\\';tk->str[di++]='t';} break;
                    case 'r':  if(di<253){tk->str[di++]='\\';tk->str[di++]='r';} break;
                    case '\\': if(di<253){tk->str[di++]='\\';tk->str[di++]='\\';} break;
                    case '"':  if(di<253){tk->str[di++]='\\';tk->str[di++]='"';} break;
                    case '\'': if(di<253){tk->str[di++]='\\';tk->str[di++]='\'';} break;
                    case '0':  if(di<253){tk->str[di++]='\\';tk->str[di++]='0';} break;
                    default:   if(di<253) tk->str[di++]=esc; break;
                }
            } else {
                if(s[p]=='\n') lx->line++;
                if(di<254){ if(s[p]=='"'){tk->str[di++]='\\';tk->str[di++]='"';}
                             else tk->str[di++]=s[p]; }
                p++;
            }
        }
        tk->str[di]='\0';
        if(s[p]) p++;
        lx->pos=p; tk->kind=TK_STRING; return;
    }

    /* long string literal */
    if(s[p]=='['&&(s[p+1]=='['||s[p+1]=='=')){
        lx->pos=p;
        char tmp[4096]; int r=l2c_read_longstr(lx,tmp,sizeof(tmp));
        if(r<=0){ tk->kind=TK_ERR; snprintf(tk->str,sizeof(tk->str),"%s",lx->errbuf); return; }
        /* escape for C string */
        int di=0;
        for(int i=0;tmp[i]&&di<253;i++){
            if(tmp[i]=='"'){tk->str[di++]='\\';tk->str[di++]='"';}
            else if(tmp[i]=='\n'){tk->str[di++]='\\';tk->str[di++]='n';}
            else if(tmp[i]=='\r'){}
            else if(tmp[i]=='\\'){tk->str[di++]='\\';tk->str[di++]='\\';}
            else tk->str[di++]=tmp[i];
        }
        tk->str[di]='\0'; tk->kind=TK_STRING; return;
    }

    /* identificadores e keywords */
    if(l2c_is_alpha(s[p])){
        int di=0;
        while(l2c_is_alnum(s[p])&&di<254) tk->str[di++]=s[p++];
        tk->str[di]='\0'; lx->pos=p;
        /* keyword map */
        static const struct { const char *w; L2CTokKind k; } kws[]={
            {"and",TK_AND},{"break",TK_BREAK},{"do",TK_DO},{"else",TK_ELSE},
            {"elseif",TK_ELSEIF},{"end",TK_END},{"false",TK_FALSE},{"for",TK_FOR},
            {"function",TK_FUNCTION},{"goto",TK_GOTO},{"if",TK_IF},{"in",TK_IN},
            {"local",TK_LOCAL},{"nil",TK_NIL},{"not",TK_NOT},{"or",TK_OR},
            {"repeat",TK_REPEAT},{"return",TK_RETURN},{"then",TK_THEN},
            {"true",TK_TRUE},{"until",TK_UNTIL},{"while",TK_WHILE},{NULL,TK_EOF}
        };
        /* case-insensitive: "If", "IF", "While" etc são keywords válidas */
        char lower_str[256];
        for(int ci=0;tk->str[ci];ci++) lower_str[ci]=(char)tolower((unsigned char)tk->str[ci]);
        lower_str[strlen(tk->str)]='\0';
        for(int i=0;kws[i].w;i++)
            if(strcmp(lower_str,kws[i].w)==0){ tk->kind=kws[i].k; return; }
        tk->kind=TK_IDENT; return;
    }

    /* operadores e pontuacao */
    char c=s[p]; char c2=s[p+1];
    lx->pos=p+1;
    switch(c){
        case '+': if(c2=='='){lx->pos++;tk->kind=TK_PLUSEQ;snprintf(tk->str,8,"+=");}
                  else{tk->kind=TK_PLUS;tk->str[0]='+';tk->str[1]='\0';} return;
        case '-': if(c2=='='){lx->pos++;tk->kind=TK_MINUSEQ;snprintf(tk->str,8,"-=");}
                  else{tk->kind=TK_MINUS;tk->str[0]='-';tk->str[1]='\0';} return;
        case '*': if(c2=='='){lx->pos++;tk->kind=TK_STAREQ;snprintf(tk->str,8,"*=");}
                  else{tk->kind=TK_STAR;tk->str[0]='*';tk->str[1]='\0';} return;
        case '/': if(c2=='/'){lx->pos++;
                      if(s[lx->pos]=='='){lx->pos++;tk->kind=TK_SLASHEQ;snprintf(tk->str,8,"/=");}
                      else{tk->kind=TK_DSLASH;snprintf(tk->str,4,"//");}} 
                  else if(c2=='='){lx->pos++;tk->kind=TK_SLASHEQ;snprintf(tk->str,8,"/=");}
                  else{tk->kind=TK_SLASH;tk->str[0]='/';tk->str[1]='\0';} return;
        case '%': tk->kind=TK_PERCENT; tk->str[0]='%'; tk->str[1]='\0'; return;
        case '^': tk->kind=TK_CARET;   tk->str[0]='^'; tk->str[1]='\0'; return;
        case '#': tk->kind=TK_HASH;    tk->str[0]='#'; tk->str[1]='\0'; return;
        case '&': tk->kind=TK_AMPERSAND;tk->str[0]='&';tk->str[1]='\0'; return;
        case '|': tk->kind=TK_PIPE;    tk->str[0]='|'; tk->str[1]='\0'; return;
        case '~': if(c2=='='){lx->pos++;tk->kind=TK_NEQ;snprintf(tk->str,4,"~=");}
                  else{tk->kind=TK_TILDE;tk->str[0]='~';tk->str[1]='\0';} return;
        case '<': if(c2=='<'){lx->pos++;tk->kind=TK_LSHIFT;snprintf(tk->str,4,"<<");}
                  else if(c2=='='){lx->pos++;tk->kind=TK_LE;snprintf(tk->str,4,"<=");}
                  else{tk->kind=TK_LT;tk->str[0]='<';tk->str[1]='\0';} return;
        case '>': if(c2=='>'){lx->pos++;tk->kind=TK_RSHIFT;snprintf(tk->str,4,">>");}
                  else if(c2=='='){lx->pos++;tk->kind=TK_GE;snprintf(tk->str,4,">=");}
                  else{tk->kind=TK_GT;tk->str[0]='>';tk->str[1]='\0';} return;
        case '=': if(c2=='='){lx->pos++;tk->kind=TK_EQ;snprintf(tk->str,4,"==");}
                  else{tk->kind=TK_ASSIGN;tk->str[0]='=';tk->str[1]='\0';} return;
        case '(': tk->kind=TK_LPAREN;  tk->str[0]='('; tk->str[1]='\0'; return;
        case ')': tk->kind=TK_RPAREN;  tk->str[0]=')'; tk->str[1]='\0'; return;
        case '{': tk->kind=TK_LBRACE;  tk->str[0]='{'; tk->str[1]='\0'; return;
        case '}': tk->kind=TK_RBRACE;  tk->str[0]='}'; tk->str[1]='\0'; return;
        case '[': tk->kind=TK_LBRACKET;tk->str[0]='['; tk->str[1]='\0'; return;
        case ']': tk->kind=TK_RBRACKET;tk->str[0]=']'; tk->str[1]='\0'; return;
        case ';': tk->kind=TK_SEMICOLON;tk->str[0]=';';tk->str[1]='\0'; return;
        case ':': if(c2==':'){lx->pos++;tk->kind=TK_DCOLON;snprintf(tk->str,4,"::");}
                  else{tk->kind=TK_COLON;tk->str[0]=':';tk->str[1]='\0';} return;
        case ',': tk->kind=TK_COMMA;   tk->str[0]=','; tk->str[1]='\0'; return;
        case '.': if(c2=='.'&&s[p+2]=='.'){lx->pos+=2;tk->kind=TK_DOTDOTDOT;snprintf(tk->str,8,"...");}
                  else if(c2=='.'){lx->pos++;tk->kind=TK_DOTDOT;snprintf(tk->str,4,"..");}
                  else{tk->kind=TK_DOT;tk->str[0]='.';tk->str[1]='\0';} return;
        default:
            snprintf(tk->str,sizeof(tk->str),"char ilegivel '%c'",c);
            tk->kind=TK_ERR; return;
    }
}

static L2CTok l2c_lex_advance(L2CLex *lx){
    if(lx->has_peek){ lx->cur=lx->peek; lx->has_peek=0; return lx->cur; }
    l2c_lex_next_raw(lx,&lx->cur);
    return lx->cur;
}
static L2CTok l2c_lex_peek(L2CLex *lx){
    if(!lx->has_peek){ l2c_lex_next_raw(lx,&lx->peek); lx->has_peek=1; }
    return lx->peek;
}
static int l2c_lex_check(L2CLex *lx, L2CTokKind k){ return l2c_lex_peek(lx).kind==k; }
static int l2c_lex_match(L2CLex *lx, L2CTokKind k){
    if(l2c_lex_check(lx,k)){ l2c_lex_advance(lx); return 1; } return 0;
}

/* ============================================================================
 * SECTION 2 -- Tabela de Simbolos com Escopos
 * ============================================================================ */
#define L2C_INT    1
#define L2C_DOUBLE 2
#define L2C_STR    3   /* char[N] mutavel */
#define L2C_CSTR   4   /* const char* */
#define L2C_BOOL   5
#define L2C_VOID   6
#define L2C_TABLE  7   /* void* aponta para struct gerada */
#define L2C_FUNC   8   /* ponteiro de funcao */

/* slot de simbolo */
typedef struct {
    char name[128];
    int  type;
    int  scope;
    int  str_size;  /* para L2C_STR: tamanho do buffer */
    int  is_global; /* 0=local, 1=global C */
} L2CSym2;

#define L2C_SCOPE_MAX 4096
typedef struct {
    L2CSym2 *syms;
    int      count;
    int      cap;
    int      scope;  /* escopo atual */
} L2CSymTab;

static void l2c_st_init(L2CSymTab *st){
    st->cap=256; st->count=0; st->scope=0;
    st->syms=(L2CSym2*)malloc(sizeof(L2CSym2)*st->cap);
}
static void l2c_st_free(L2CSymTab *st){ free(st->syms); st->syms=NULL; }
static void l2c_st_push_scope(L2CSymTab *st){ st->scope++; }
static void l2c_st_pop_scope(L2CSymTab *st){
    if(st->scope<=0) return;
    /* remove simbolos do escopo saindo */
    while(st->count>0&&st->syms[st->count-1].scope>=st->scope) st->count--;
    st->scope--;
}
static void l2c_st_set(L2CSymTab *st, const char *name, int type, int str_size){
    /* atualiza se ja existe no escopo atual */
    for(int i=st->count-1;i>=0;i--){
        if(strcmp(st->syms[i].name,name)==0&&st->syms[i].scope==st->scope){
            st->syms[i].type=type;
            if(str_size) st->syms[i].str_size=str_size;
            return;
        }
    }
    if(st->count>=st->cap){
        st->cap*=2;
        st->syms=(L2CSym2*)realloc(st->syms,sizeof(L2CSym2)*st->cap);
        if(!st->syms){ st->cap=0; st->count=0; return; }
    }
    L2CSym2 *sym=&st->syms[st->count++];
    strncpy(sym->name,name,127); sym->name[127]='\0';
    sym->type=type; sym->scope=st->scope;
    sym->str_size=str_size?str_size:512;
    sym->is_global=0;
}
static L2CSym2 *l2c_st_get(L2CSymTab *st, const char *name){
    for(int i=st->count-1;i>=0;i--)
        if(strcmp(st->syms[i].name,name)==0) return &st->syms[i];
    return NULL;
}
static int l2c_st_type(L2CSymTab *st, const char *name){
    L2CSym2 *s=l2c_st_get(st,name);
    return s?s->type:0;
}

/* ============================================================================
 * SECTION 3 -- Inferencia de Tipo de expressao (sem parser completo)
 *              Usada para decidir tipo de variavel antes de emitir declaracao
 * ============================================================================ */

/* forward-declare o emitter de expressao */
struct L2CEmit_s;
static void l2c_emit_expr(L2CLex *lx, L2CBuf *out, struct L2CEmit_s *em, int want_str);

/* -- inferencia leve baseada no token corrente (peek) -- */
static int l2c_peek_type(L2CLex *lx, L2CSymTab *st){
    L2CTok tk=l2c_lex_peek(lx);
    switch(tk.kind){
        case TK_INT:    return L2C_INT;
        case TK_FLOAT:  return L2C_DOUBLE;
        case TK_STRING: return L2C_STR;
        case TK_TRUE:
        case TK_FALSE:  return L2C_BOOL;
        case TK_NIL:    return L2C_VOID;
        case TK_FUNCTION: return L2C_FUNC;
        case TK_LBRACE: return L2C_TABLE;
        case TK_IDENT: {
            /* checar se e chamada de funcao conhecida */
            const char *n=tk.str;
            if(strncmp(n,"tostring",8)==0)  return L2C_CSTR;
            if(strncmp(n,"tonumber",8)==0)  return L2C_DOUBLE;
            if(strncmp(n,"tostring",8)==0)  return L2C_CSTR;
            int t=l2c_st_type(st,n);
            return t?t:L2C_DOUBLE;
        }
        default: return L2C_DOUBLE;
    }
}

/* ============================================================================
 * SECTION 4 -- Estado do Emitter
 * ============================================================================ */
typedef struct L2CEmit_s {
    L2CBuf    *out;         /* saida principal */
    L2CBuf    *helpers;     /* runtime helpers (adicionados ao header) */
    L2CBuf    *fwddecl;     /* forward declarations de funcoes */
    L2CSymTab  st;
    int        depth;       /* indentacao atual */
    int        in_func;
    char       func_ret_type; /* tipo C de retorno (L2C_*) */
    int        tmp_counter; /* gerador de nomes temporarios */
    int        tbl_counter; /* gerador de nomes de struct */
    /* flags de helpers necessarios */
    int        need_strbuf;
    int        need_math;
    int        need_time;
    int        need_ctype;
    int        need_stdarg;
    char       errbuf[256];
    int        had_error;
    int        line;
} L2CEmit;

static void l2c_emit_indent(L2CEmit *em){
    for(int i=0;i<em->depth*4;i++) l2c_buf_addc(em->out,' ');
}

static int l2c_emit_tmp(L2CEmit *em, char *dst, int dsz){
    return snprintf(dst,dsz,"_l2c_t%d",em->tmp_counter++);
}

static void l2c_emit_error(L2CEmit *em, const char *msg, int line){
    if(!em->had_error){
        snprintf(em->errbuf,sizeof(em->errbuf),"linha %d: %s",line,msg);
        em->had_error=1;
    }
}

/* ============================================================================
 * SECTION 5 -- Emitter de Expressoes
 *
 * Implementa Pratt parser (precedencia por nivel de funcao recursiva)
 * Retorna tipo inferido da expressao
 * ============================================================================ */

/* -- emit concat a..b -> snprintf ou strcat chain -- */
static int l2c_emit_concat_chain(L2CLex *lx, L2CBuf *out, L2CEmit *em);
static int l2c_emit_expr_prec(L2CLex *lx, L2CBuf *out, L2CEmit *em, int min_prec);

/* precedencia de operadores binarios */
static int l2c_binop_prec(L2CTokKind k){
    switch(k){
        case TK_OR:     return 1;
        case TK_AND:    return 2;
        case TK_LT: case TK_GT: case TK_LE: case TK_GE:
        case TK_EQ: case TK_NEQ: return 3;
        case TK_PIPE:   return 4;
        case TK_TILDE:  return 5;
        case TK_AMPERSAND: return 6;
        case TK_LSHIFT: case TK_RSHIFT: return 7;
        case TK_DOTDOT: return 8;   /* right-assoc */
        case TK_PLUS: case TK_MINUS: return 9;
        case TK_STAR: case TK_SLASH: case TK_DSLASH: case TK_PERCENT: return 10;
        case TK_CARET:  return 12;  /* right-assoc, highest */
        default: return -1;
    }
}
static int l2c_binop_right(L2CTokKind k){
    return k==TK_DOTDOT||k==TK_CARET;
}

/* -- emite chamada de funcao com mapeamento Lua->C -- */
static int l2c_emit_call(L2CLex *lx, L2CBuf *out, L2CEmit *em, const char *fname){
    /* mapeamentos especiais */
    int ret_type=L2C_DOUBLE;

    /* string.* */
    if(strcmp(fname,"string.upper")==0||strcmp(fname,"string.lower")==0){
        em->need_strbuf=1; em->need_ctype=1;
        l2c_buf_add(out, strcmp(fname,"string.upper")==0 ? "_l2c_upper(" : "_l2c_lower(");
        ret_type=L2C_CSTR; goto emit_args_close;
    }
    if(strcmp(fname,"string.len")==0||strcmp(fname,"string.length")==0){
        l2c_buf_add(out,"(int)strlen("); ret_type=L2C_INT; goto emit_args_close;
    }
    if(strcmp(fname,"string.sub")==0){
        em->need_strbuf=1;
        l2c_buf_add(out,"_l2c_sub("); ret_type=L2C_CSTR; goto emit_args_close;
    }
    if(strcmp(fname,"string.rep")==0){
        em->need_strbuf=1;
        l2c_buf_add(out,"_l2c_rep("); ret_type=L2C_CSTR; goto emit_args_close;
    }
    if(strcmp(fname,"string.reverse")==0){
        em->need_strbuf=1;
        l2c_buf_add(out,"_l2c_rev("); ret_type=L2C_CSTR; goto emit_args_close;
    }
    if(strcmp(fname,"string.byte")==0){
        l2c_buf_add(out,"((int)("); ret_type=L2C_INT; goto emit_args_close;
    }
    if(strcmp(fname,"string.char")==0){
        em->need_strbuf=1;
        l2c_buf_add(out,"_l2c_char("); ret_type=L2C_CSTR; goto emit_args_close;
    }
    if(strcmp(fname,"string.find")==0){
        em->need_strbuf=1;
        l2c_buf_add(out,"_l2c_find("); ret_type=L2C_INT; goto emit_args_close;
    }
    if(strcmp(fname,"string.format")==0){
        em->need_strbuf=1; em->need_stdarg=1;
        l2c_buf_add(out,"_l2c_fmt("); ret_type=L2C_CSTR; goto emit_args_close;
    }
    if(strcmp(fname,"string.gmatch")==0||strcmp(fname,"string.match")==0){
        em->need_strbuf=1;
        l2c_buf_add(out,"_l2c_match("); ret_type=L2C_CSTR; goto emit_args_close;
    }
    if(strcmp(fname,"string.gsub")==0){
        em->need_strbuf=1;
        l2c_buf_add(out,"_l2c_gsub("); ret_type=L2C_CSTR; goto emit_args_close;
    }

    /* math.* */
    if(strcmp(fname,"math.floor")==0){em->need_math=1;l2c_buf_add(out,"(int)floor(");ret_type=L2C_INT;goto emit_args_close;}
    if(strcmp(fname,"math.ceil")==0) {em->need_math=1;l2c_buf_add(out,"(int)ceil("); ret_type=L2C_INT;goto emit_args_close;}
    if(strcmp(fname,"math.sqrt")==0) {em->need_math=1;l2c_buf_add(out,"sqrt(");       ret_type=L2C_DOUBLE;goto emit_args_close;}
    if(strcmp(fname,"math.abs")==0)  {em->need_math=1;l2c_buf_add(out,"fabs(");       ret_type=L2C_DOUBLE;goto emit_args_close;}
    if(strcmp(fname,"math.sin")==0)  {em->need_math=1;l2c_buf_add(out,"sin(");        ret_type=L2C_DOUBLE;goto emit_args_close;}
    if(strcmp(fname,"math.cos")==0)  {em->need_math=1;l2c_buf_add(out,"cos(");        ret_type=L2C_DOUBLE;goto emit_args_close;}
    if(strcmp(fname,"math.tan")==0)  {em->need_math=1;l2c_buf_add(out,"tan(");        ret_type=L2C_DOUBLE;goto emit_args_close;}
    if(strcmp(fname,"math.log")==0)  {em->need_math=1;l2c_buf_add(out,"log(");        ret_type=L2C_DOUBLE;goto emit_args_close;}
    if(strcmp(fname,"math.exp")==0)  {em->need_math=1;l2c_buf_add(out,"exp(");        ret_type=L2C_DOUBLE;goto emit_args_close;}
    if(strcmp(fname,"math.pow")==0||strcmp(fname,"math.pow")==0){em->need_math=1;l2c_buf_add(out,"pow(");ret_type=L2C_DOUBLE;goto emit_args_close;}
    if(strcmp(fname,"math.max")==0)  {em->need_math=1;l2c_buf_add(out,"fmax(");       ret_type=L2C_DOUBLE;goto emit_args_close;}
    if(strcmp(fname,"math.min")==0)  {em->need_math=1;l2c_buf_add(out,"fmin(");       ret_type=L2C_DOUBLE;goto emit_args_close;}
    if(strcmp(fname,"math.huge")==0) {l2c_buf_add(out,"INFINITY");l2c_buf_add(out,"/*noargs*/");em->need_math=1;return L2C_DOUBLE;}
    if(strcmp(fname,"math.pi")==0)   {l2c_buf_add(out,"M_PI");l2c_buf_add(out,"/*noargs*/");em->need_math=1;return L2C_DOUBLE;}
    if(strcmp(fname,"math.random")==0){l2c_buf_add(out,"((double)rand()/RAND_MAX");l2c_buf_add(out,"/*noargs*/");return L2C_DOUBLE;}
    if(strcmp(fname,"math.randomseed")==0){l2c_buf_add(out,"srand(");ret_type=L2C_VOID;goto emit_args_close;}
    if(strcmp(fname,"math.type")==0) {l2c_buf_add(out,"_l2c_mathtype(");em->need_strbuf=1;ret_type=L2C_CSTR;goto emit_args_close;}
    if(strcmp(fname,"math.tointeger")==0){l2c_buf_add(out,"(int)(");ret_type=L2C_INT;goto emit_args_close;}

    /* os.* */
    if(strcmp(fname,"os.time")==0)  {em->need_time=1;l2c_buf_add(out,"(int)time(NULL");l2c_buf_add(out,"/*noargs*/");l2c_lex_match(lx,TK_LPAREN);l2c_lex_match(lx,TK_RPAREN);return L2C_INT;}
    if(strcmp(fname,"os.clock")==0) {em->need_time=1;l2c_buf_add(out,"(double)clock(");ret_type=L2C_DOUBLE;goto emit_args_close;}
    if(strcmp(fname,"os.exit")==0)  {l2c_buf_add(out,"exit(");ret_type=L2C_VOID;goto emit_args_close;}

    /* io.* */
    if(strcmp(fname,"io.write")==0){
        l2c_buf_add(out,"printf("); ret_type=L2C_VOID; goto emit_args_close;
    }

    /* table.* */
    if(strcmp(fname,"table.insert")==0){
        /* table.insert(t, v) ou table.insert(t, pos, v) -- sem runtime dinamico; emite comentario */
        l2c_buf_add(out,"/* table.insert("); ret_type=L2C_VOID; goto emit_args_close;
    }
    if(strcmp(fname,"table.remove")==0){
        l2c_buf_add(out,"/* table.remove("); ret_type=L2C_VOID; goto emit_args_close;
    }
    if(strcmp(fname,"table.sort")==0){
        /* qsort wrapper: emite comentario */
        l2c_buf_add(out,"/* table.sort("); ret_type=L2C_VOID; goto emit_args_close;
    }
    if(strcmp(fname,"table.concat")==0){
        em->need_strbuf=1;
        l2c_buf_add(out,"_l2c_tblcat("); ret_type=L2C_CSTR; goto emit_args_close;
    }

    /* conversoes */
    if(strcmp(fname,"tostring")==0){em->need_strbuf=1;l2c_buf_add(out,"_l2c_tostr(");ret_type=L2C_CSTR;goto emit_args_close;}
    if(strcmp(fname,"tonumber")==0){l2c_buf_add(out,"atof(");ret_type=L2C_DOUBLE;goto emit_args_close;}
    if(strcmp(fname,"type")==0){em->need_strbuf=1;l2c_buf_add(out,"_l2c_type(");ret_type=L2C_CSTR;goto emit_args_close;}
    if(strcmp(fname,"rawget")==0||strcmp(fname,"rawset")==0){
        l2c_buf_add(out,"/* "); l2c_buf_add(out,fname); l2c_buf_add(out,"(");
        ret_type=L2C_VOID; goto emit_args_close;
    }
    if(strcmp(fname,"rawequal")==0){l2c_buf_add(out,"(");ret_type=L2C_BOOL;goto emit_args_close;}
    if(strcmp(fname,"error")==0){
        l2c_buf_add(out,"(fprintf(stderr,\"%s\\n\","); ret_type=L2C_VOID; goto emit_args_close;
    }
    if(strcmp(fname,"assert")==0){l2c_buf_add(out,"assert(");ret_type=L2C_VOID;goto emit_args_close;}
    if(strcmp(fname,"ipairs")==0||strcmp(fname,"pairs")==0){
        l2c_buf_add(out,"/* ");l2c_buf_add(out,fname);l2c_buf_add(out,"(");
        ret_type=L2C_VOID; goto emit_args_close;
    }
    if(strcmp(fname,"pcall")==0){
        /* pcall(f, ...) -> simplesmente chama f(...) -- sem setjmp */
        l2c_buf_add(out,"/* pcall -> */ (");
        ret_type=L2C_BOOL; goto emit_args_close;
    }
    if(strcmp(fname,"select")==0){l2c_buf_add(out,"/* select(");ret_type=L2C_VOID;goto emit_args_close;}
    if(strcmp(fname,"unpack")==0||strcmp(fname,"table.unpack")==0){l2c_buf_add(out,"/* unpack(");ret_type=L2C_VOID;goto emit_args_close;}
    if(strcmp(fname,"print")==0){
        /* emitido separadamente como statement; aqui so como expressao */
        l2c_buf_add(out,"printf("); ret_type=L2C_VOID; goto emit_args_close;
    }
    if(strcmp(fname,"require")==0){
        l2c_buf_add(out,"/* require("); ret_type=L2C_VOID; goto emit_args_close;
    }
    if(strcmp(fname,"setmetatable")==0||strcmp(fname,"getmetatable")==0){
        l2c_buf_add(out,"/* "); l2c_buf_add(out,fname); l2c_buf_add(out,"(");
        ret_type=L2C_VOID; goto emit_args_close;
    }
    if(strcmp(fname,"collectgarbage")==0){l2c_buf_add(out,"/* collectgarbage(");ret_type=L2C_VOID;goto emit_args_close;}
    if(strcmp(fname,"rawlen")==0){l2c_buf_add(out,"(int)sizeof("); ret_type=L2C_INT; goto emit_args_close;}
    if(strcmp(fname,"next")==0){l2c_buf_add(out,"/* next(");ret_type=L2C_VOID;goto emit_args_close;}

    /* fallback: emite como chamada C direta */
    l2c_buf_add(out,fname); l2c_buf_addc(out,'(');
    ret_type=L2C_DOUBLE;

emit_args_close:;
    /* consome '(' se presente */
    if(l2c_lex_check(lx,TK_LPAREN)) l2c_lex_advance(lx);
    /* emite argumentos */
    int first=1;
    while(!l2c_lex_check(lx,TK_RPAREN)&&!l2c_lex_check(lx,TK_EOF)){
        if(!first) l2c_buf_add(out,", ");
        first=0;
        l2c_emit_expr_prec(lx,out,em,0);
        if(!l2c_lex_match(lx,TK_COMMA)) break;
    }
    l2c_lex_match(lx,TK_RPAREN);
    l2c_buf_addc(out,')');
    return ret_type;
}

/* -- emite expressao primaria (atom) -- */
static int l2c_emit_primary(L2CLex *lx, L2CBuf *out, L2CEmit *em){
    L2CTok tk=l2c_lex_advance(lx);
    switch(tk.kind){
        case TK_INT:
            l2c_buf_add(out,tk.str);
            return L2C_INT;
        case TK_FLOAT:
            l2c_buf_add(out,tk.str);
            return L2C_DOUBLE;
        case TK_STRING:
            l2c_buf_addc(out,'"'); l2c_buf_add(out,tk.str); l2c_buf_addc(out,'"');
            return L2C_STR;
        case TK_TRUE:  l2c_buf_add(out,"1"); return L2C_BOOL;
        case TK_FALSE: l2c_buf_add(out,"0"); return L2C_BOOL;
        case TK_NIL:   l2c_buf_add(out,"NULL"); return L2C_VOID;
        case TK_DOTDOTDOT: l2c_buf_add(out,"__VA_ARGS__"); return L2C_DOUBLE;

        case TK_IDENT: {
            /* constroi nome completo (pode ser a.b.c) */
            char full[256]; strncpy(full,tk.str,255); full[255]='\0';
            while(l2c_lex_check(lx,TK_DOT)||l2c_lex_check(lx,TK_COLON)){
                L2CTok dot=l2c_lex_advance(lx);
                if(!l2c_lex_check(lx,TK_IDENT)){ (void)dot; break; }
                L2CTok nm=l2c_lex_advance(lx);
                /* a.b -> a_b no C; a:b -> metodo */
                strncat(full,"_",sizeof(full)-strlen(full)-1);
                strncat(full,nm.str,sizeof(full)-strlen(full)-1);
            }

            /* chamada de funcao */
            if(l2c_lex_check(lx,TK_LPAREN)||l2c_lex_check(lx,TK_STRING)){
                return l2c_emit_call(lx,out,em,full);
            }

            /* chamada com {table} */
            if(l2c_lex_check(lx,TK_LBRACE)){
                l2c_buf_add(out,full); l2c_buf_addc(out,'(');
                /* emite tabela como argumento */
                l2c_lex_advance(lx); /* { */
                int first2=1;
                while(!l2c_lex_check(lx,TK_RBRACE)&&!l2c_lex_check(lx,TK_EOF)){
                    if(!first2){ l2c_buf_add(out,", "); } first2=0;
                    l2c_emit_expr_prec(lx,out,em,0);
                    l2c_lex_match(lx,TK_COMMA);
                }
                l2c_lex_match(lx,TK_RBRACE);
                l2c_buf_addc(out,')');
                return L2C_DOUBLE;
            }

            /* subscript t[i] */
            if(l2c_lex_check(lx,TK_LBRACKET)){
                l2c_lex_advance(lx);
                l2c_buf_add(out,full); l2c_buf_addc(out,'[');
                L2CBuf idx; l2c_buf_init(&idx);
                l2c_emit_expr_prec(lx,&idx,em,0);
                /* Lua index 1-based -> C 0-based */
                int is_int_lit=0;
                if(idx.buf&&idx.buf[0]>='0'&&idx.buf[0]<='9') is_int_lit=1;
                if(is_int_lit){
                    int v=atoi(idx.buf?idx.buf:"1");
                    l2c_buf_addf(out,"%d",v-1);
                } else {
                    l2c_buf_add(out,idx.buf?idx.buf:"0");
                    l2c_buf_add(out,"-1");
                }
                l2c_buf_free(&idx);
                l2c_buf_addc(out,']');
                l2c_lex_match(lx,TK_RBRACKET);
                L2CSym2 *s=l2c_st_get(&em->st,full);
                return s?s->type:L2C_DOUBLE;
            }

            /* variavel simples */
            int t=l2c_st_type(&em->st,full);
            l2c_buf_add(out,full);
            return t?t:L2C_DOUBLE;
        }

        case TK_LPAREN: {
            l2c_buf_addc(out,'(');
            int t=l2c_emit_expr_prec(lx,out,em,0);
            l2c_lex_match(lx,TK_RPAREN);
            l2c_buf_addc(out,')');
            return t;
        }

        case TK_LBRACE: {
            /* tabela literal -> array C */
            em->tbl_counter++;
            /* emite como inicializador de array */
            l2c_buf_addc(out,'{');
            int first2=1; int n=0;
            while(!l2c_lex_check(lx,TK_RBRACE)&&!l2c_lex_check(lx,TK_EOF)){
                /* key=value ou value */
                if(l2c_lex_check(lx,TK_LBRACKET)){
                    l2c_lex_advance(lx);
                    /* skip key */
                    l2c_emit_expr_prec(lx,NULL,em,0);
                    l2c_lex_match(lx,TK_RBRACKET);
                    l2c_lex_match(lx,TK_ASSIGN);
                    if(!first2){ l2c_buf_add(out,", "); } first2=0;
                    l2c_emit_expr_prec(lx,out,em,0);
                    n++;
                } else if(l2c_lex_check(lx,TK_IDENT)){
                    L2CTok peeked=l2c_lex_peek(lx);
                    /* save pos */
                    L2CTok saved_cur=lx->cur; L2CTok saved_peek=lx->peek;
                    int saved_has=lx->has_peek; int saved_pos=lx->pos;
                    l2c_lex_advance(lx);
                    if(l2c_lex_check(lx,TK_ASSIGN)){
                        /* key=value: skip */
                        l2c_lex_advance(lx);
                        if(!first2){ l2c_buf_add(out,", "); } first2=0;
                        l2c_emit_expr_prec(lx,out,em,0);
                        n++;
                    } else {
                        /* restore e emite como value */
                        lx->cur=saved_cur; lx->peek=saved_peek;
                        lx->has_peek=saved_has; lx->pos=saved_pos;
                        (void)peeked;
                        if(!first2){ l2c_buf_add(out,", "); } first2=0;
                        l2c_emit_expr_prec(lx,out,em,0);
                        n++;
                    }
                } else {
                    if(!first2){ l2c_buf_add(out,", "); } first2=0;
                    l2c_emit_expr_prec(lx,out,em,0);
                    n++;
                }
                if(!l2c_lex_match(lx,TK_COMMA)&&!l2c_lex_match(lx,TK_SEMICOLON)) break;
            }
            l2c_lex_match(lx,TK_RBRACE);
            l2c_buf_addc(out,'}');
            (void)n;
            return L2C_TABLE;
        }

        case TK_FUNCTION: {
            /* funcao anonima -> emite como nome _l2c_fn<N> com forward decl */
            char anon_name[64]; snprintf(anon_name,sizeof(anon_name),"_l2c_fn%d",em->tmp_counter++);
            /* ler parametros */
            l2c_lex_match(lx,TK_LPAREN);
            char params_raw[512]={0}; int pi=0;
            while(!l2c_lex_check(lx,TK_RPAREN)&&!l2c_lex_check(lx,TK_EOF)){
                L2CTok p=l2c_lex_advance(lx);
                if(pi<510){ memcpy(params_raw+pi,p.str,strlen(p.str)); pi+=strlen(p.str); }
                if(l2c_lex_check(lx,TK_COMMA)){ l2c_lex_advance(lx); if(pi<510) params_raw[pi++]=','; }
            }
            params_raw[pi]='\0';
            l2c_lex_match(lx,TK_RPAREN);
            /* emite referencia no output atual */
            l2c_buf_add(out,anon_name);
            /* guarda corpo para emitir depois -- simplificacao: skip body */
            l2c_buf_addf(em->fwddecl,"/* anon fn %s(%s) -- corpo omitido */\n",anon_name,params_raw);
            /* consome body ate 'end' */
            int depth=1;
            while(!l2c_lex_check(lx,TK_EOF)&&depth>0){
                L2CTok bt=l2c_lex_advance(lx);
                if(bt.kind==TK_FUNCTION||bt.kind==TK_IF||bt.kind==TK_WHILE||
                   bt.kind==TK_FOR||bt.kind==TK_REPEAT||bt.kind==TK_DO) depth++;
                else if(bt.kind==TK_END) depth--;
            }
            return L2C_FUNC;
        }

        default:
            l2c_buf_add(out,"/**/");
            return L2C_DOUBLE;
    }
}

/* -- emite unario -- */
static int l2c_emit_unary(L2CLex *lx, L2CBuf *out, L2CEmit *em){
    L2CTok pk=l2c_lex_peek(lx);
    if(pk.kind==TK_MINUS){
        l2c_lex_advance(lx); l2c_buf_add(out,"-");
        return l2c_emit_unary(lx,out,em);
    }
    if(pk.kind==TK_NOT){
        l2c_lex_advance(lx); l2c_buf_add(out,"!");
        return l2c_emit_unary(lx,out,em);
    }
    if(pk.kind==TK_HASH){
        l2c_lex_advance(lx); l2c_buf_add(out,"(int)strlen(");
        int t=l2c_emit_primary(lx,out,em);
        l2c_buf_addc(out,')');
        return t;
    }
    if(pk.kind==TK_TILDE){
        l2c_lex_advance(lx); l2c_buf_add(out,"~");
        return l2c_emit_unary(lx,out,em);
    }
    return l2c_emit_primary(lx,out,em);
}

/* -- Pratt: emite binario com precedencia -- */
static int l2c_emit_expr_prec(L2CLex *lx, L2CBuf *out, L2CEmit *em, int min_prec){
    if(!out){
        /* modo skip: avanca tokens sem emitir */
        l2c_emit_unary(lx,NULL,em);
        for(;;){
            int prec=l2c_binop_prec(l2c_lex_peek(lx).kind);
            if(prec<min_prec||prec<0) break;
            l2c_lex_advance(lx);
            l2c_emit_expr_prec(lx,NULL,em,l2c_binop_right(lx->cur.kind)?prec:prec+1);
        }
        return L2C_DOUBLE;
    }

    L2CBuf lhs; l2c_buf_init(&lhs);
    int lhs_type=l2c_emit_unary(lx,&lhs,em);
    int had_binop = 0;  /* flag: houve pelo menos um operador binário? */

    for(;;){
        L2CTok op=l2c_lex_peek(lx);
        int prec=l2c_binop_prec(op.kind);
        if(prec<0||prec<min_prec) break;
        l2c_lex_advance(lx);
        int next_prec = l2c_binop_right(op.kind) ? prec : prec+1;
        had_binop = 1;

        /* concatenacao -> handler especial */
        if(op.kind==TK_DOTDOT){
            em->need_strbuf=1;
            /* coleta todos os operandos da chain */
            char parts[32][512]; int np=0;
            if(lhs.buf&&strlen(lhs.buf)<512) strncpy(parts[np++],lhs.buf,511);
            l2c_buf_free(&lhs);
            for(;;){
                L2CBuf rpart; l2c_buf_init(&rpart);
                l2c_emit_expr_prec(lx,&rpart,em,next_prec);
                if(rpart.buf&&strlen(rpart.buf)<512&&np<32) strncpy(parts[np++],rpart.buf,511);
                l2c_buf_free(&rpart);
                if(l2c_lex_peek(lx).kind!=TK_DOTDOT) break;
                l2c_lex_advance(lx);
            }
            /* gera _l2c_cat(a, b, ...) */
            l2c_buf_add(out,"_l2c_cat(");
            l2c_buf_addf(out,"%d",np);
            for(int i=0;i<np;i++){
                l2c_buf_add(out,", "); l2c_buf_add(out,parts[i]);
            }
            l2c_buf_addc(out,')');
            return L2C_CSTR;
        }

        /* potencia -> pow() */
        if(op.kind==TK_CARET){
            em->need_math=1;
            L2CBuf rhs2; l2c_buf_init(&rhs2);
            l2c_emit_expr_prec(lx,&rhs2,em,next_prec);
            l2c_buf_add(out,"pow(");
            l2c_buf_add(out,lhs.buf?lhs.buf:"0");
            l2c_buf_add(out,", ");
            l2c_buf_add(out,rhs2.buf?rhs2.buf:"0");
            l2c_buf_addc(out,')');
            l2c_buf_free(&lhs); l2c_buf_free(&rhs2);
            return L2C_DOUBLE;
        }

        L2CBuf rhs2; l2c_buf_init(&rhs2);
        int rhs_type=l2c_emit_expr_prec(lx,&rhs2,em,next_prec);
        (void)rhs_type;

        /* emite no output */
        l2c_buf_add(out,lhs.buf?lhs.buf:"0");
        switch(op.kind){
            case TK_PLUS:   l2c_buf_add(out," + "); break;
            case TK_MINUS:  l2c_buf_add(out," - "); break;
            case TK_STAR:   l2c_buf_add(out," * "); break;
            case TK_SLASH:  l2c_buf_add(out," / "); break;
            case TK_DSLASH: l2c_buf_add(out," / "); break; /* idiv -- ambos int */
            case TK_PERCENT:l2c_buf_add(out," % "); break;
            case TK_AND:    l2c_buf_add(out," && "); break;
            case TK_OR:     l2c_buf_add(out," || "); break;
            case TK_EQ:     l2c_buf_add(out," == "); break;
            case TK_NEQ:    l2c_buf_add(out," != "); break;
            case TK_LT:     l2c_buf_add(out," < "); break;
            case TK_LE:     l2c_buf_add(out," <= "); break;
            case TK_GT:     l2c_buf_add(out," > "); break;
            case TK_GE:     l2c_buf_add(out," >= "); break;
            case TK_AMPERSAND: l2c_buf_add(out," & "); break;
            case TK_PIPE:   l2c_buf_add(out," | "); break;
            case TK_TILDE:  l2c_buf_add(out," ^ "); break;
            case TK_LSHIFT: l2c_buf_add(out," << "); break;
            case TK_RSHIFT: l2c_buf_add(out," >> "); break;
            default:        l2c_buf_add(out,"  "); break;
        }
        l2c_buf_add(out,rhs2.buf?rhs2.buf:"0");
        l2c_buf_free(&lhs); lhs=rhs2; /* rhs2 transferida */
        /* limpa rhs2 struct sem free do data (ja transferido) */
        rhs2.buf=NULL;
        if(op.kind==TK_DSLASH) lhs_type=L2C_INT;
        else if(op.kind==TK_AND||op.kind==TK_OR||
                op.kind==TK_EQ||op.kind==TK_NEQ||
                op.kind==TK_LT||op.kind==TK_LE||
                op.kind==TK_GT||op.kind==TK_GE) lhs_type=L2C_BOOL;
    }

    /* Emite lhs apenas se não houve operador binário (expressão atômica simples).
     * Se houve binop, o valor já foi emitido dentro do loop acima. */
    if(!had_binop) l2c_buf_add(out,lhs.buf?lhs.buf:"");
    l2c_buf_free(&lhs);
    return lhs_type;
}

/* wrapper publico */
static void l2c_emit_expr(L2CLex *lx, L2CBuf *out, L2CEmit *em, int want_str){
    (void)want_str;
    l2c_emit_expr_prec(lx,out,em,0);
}

/* ============================================================================
 * SECTION 6 -- Emitter de Statements
 * ============================================================================ */

/* forward */
static void l2c_emit_block(L2CLex *lx, L2CEmit *em, L2CTokKind stop1, L2CTokKind stop2, L2CTokKind stop3);

static void l2c_emit_print_stmt(L2CLex *lx, L2CEmit *em){
    /* print(a, b, ...) -> printf com tipos corretos */
    l2c_lex_match(lx,TK_LPAREN);
    /* coleta args */
    L2CBuf args[16]; int types[16]; int nargs=0;
    while(!l2c_lex_check(lx,TK_RPAREN)&&!l2c_lex_check(lx,TK_EOF)&&nargs<16){
        l2c_buf_init(&args[nargs]);
        types[nargs]=l2c_emit_expr_prec(lx,&args[nargs],em,0);
        nargs++;
        if(!l2c_lex_match(lx,TK_COMMA)) break;
    }
    l2c_lex_match(lx,TK_RPAREN);
    l2c_emit_indent(em);
    l2c_buf_add(em->out,"printf(\"");
    for(int i=0;i<nargs;i++){
        int t=types[i];
        if(t==L2C_INT||t==L2C_BOOL) l2c_buf_add(em->out,"%d");
        else if(t==L2C_DOUBLE)      l2c_buf_add(em->out,"%g");
        else                         l2c_buf_add(em->out,"%s");
        if(i<nargs-1) l2c_buf_addc(em->out,'\t');
    }
    l2c_buf_add(em->out,"\\n\"");
    for(int i=0;i<nargs;i++){
        l2c_buf_add(em->out,", ");
        /* cast necessario para %s */
        if(types[i]==L2C_BOOL){
            l2c_buf_add(em->out,"(");
            l2c_buf_add(em->out,args[i].buf?args[i].buf:"0");
            l2c_buf_add(em->out,")");
        } else {
            l2c_buf_add(em->out,args[i].buf?args[i].buf:"0");
        }
        l2c_buf_free(&args[i]);
    }
    l2c_buf_add(em->out,");\n");
}

static void l2c_emit_func_decl(L2CLex *lx, L2CEmit *em, int is_local){
    (void)is_local;
    /* function nome(params) body end */
    char fname[256]={0};
    L2CTok nm=l2c_lex_advance(lx);
    strncpy(fname,nm.str,255);
    /* pode ter : ou . */
    while(l2c_lex_check(lx,TK_DOT)||l2c_lex_check(lx,TK_COLON)){
        l2c_lex_advance(lx);
        if(l2c_lex_check(lx,TK_IDENT)){
            L2CTok mn=l2c_lex_advance(lx);
            strncat(fname,"_",sizeof(fname)-strlen(fname)-1);
            strncat(fname,mn.str,sizeof(fname)-strlen(fname)-1);
        }
    }
    l2c_lex_match(lx,TK_LPAREN);

    /* parametros */
    typedef struct { char name[64]; int type; } Param;
    Param params[32]; int nparams=0;
    while(!l2c_lex_check(lx,TK_RPAREN)&&!l2c_lex_check(lx,TK_EOF)){
        if(l2c_lex_check(lx,TK_DOTDOTDOT)){
            l2c_lex_advance(lx);
            strncpy(params[nparams].name,"...",63);
            params[nparams++].type=L2C_DOUBLE;
            break;
        }
        L2CTok pn=l2c_lex_advance(lx);
        strncpy(params[nparams].name,pn.str,63);
        params[nparams++].type=L2C_DOUBLE; /* inferencia avancada futura */
        if(!l2c_lex_match(lx,TK_COMMA)) break;
    }
    l2c_lex_match(lx,TK_RPAREN);

    /* forward decl */
    l2c_buf_addf(em->fwddecl,"double %s(",fname);
    for(int i=0;i<nparams;i++){
        if(i) l2c_buf_add(em->fwddecl,", ");
        if(strcmp(params[i].name,"...")==0) l2c_buf_add(em->fwddecl,"...");
        else l2c_buf_addf(em->fwddecl,"double %s",params[i].name);
    }
    if(!nparams) l2c_buf_add(em->fwddecl,"void");
    l2c_buf_add(em->fwddecl,");\n");

    /* definicao */
    l2c_buf_addf(em->out,"\ndouble %s(",fname);
    l2c_st_push_scope(&em->st);
    for(int i=0;i<nparams;i++){
        if(i) l2c_buf_add(em->out,", ");
        if(strcmp(params[i].name,"...")==0) l2c_buf_add(em->out,"...");
        else {
            l2c_buf_addf(em->out,"double %s",params[i].name);
            l2c_st_set(&em->st,params[i].name,L2C_DOUBLE,0);
        }
    }
    if(!nparams) l2c_buf_add(em->out,"void");
    l2c_buf_add(em->out,") {\n");

    int old_depth=em->depth; em->depth=1;
    int old_func=em->in_func; em->in_func=1;
    l2c_emit_block(lx,em,TK_END,TK_EOF,TK_EOF);
    l2c_lex_match(lx,TK_END);
    l2c_st_pop_scope(&em->st);

    em->depth=old_depth; em->in_func=old_func;
    l2c_buf_add(em->out,"    return 0.0;\n}\n");
}

static void l2c_emit_statement(L2CLex *lx, L2CEmit *em){
    L2CTok tk=l2c_lex_peek(lx);
    if(em->had_error) return;

    switch(tk.kind){

    case TK_SEMICOLON: l2c_lex_advance(lx); return;

    /* -- local var -- */
    case TK_LOCAL: {
        l2c_lex_advance(lx);
        if(l2c_lex_check(lx,TK_FUNCTION)){
            l2c_lex_advance(lx);
            l2c_emit_func_decl(lx,em,1);
            return;
        }
        /* local a, b, c = expr, expr, expr */
        char names[8][128]; int nn=0;
        while(l2c_lex_check(lx,TK_IDENT)&&nn<8){
            L2CTok vn=l2c_lex_advance(lx);
            strncpy(names[nn++],vn.str,127);
            if(!l2c_lex_match(lx,TK_COMMA)) break;
        }
        /* type annotation (Lua 5.4) */
        if(l2c_lex_check(lx,TK_DCOLON)){
            l2c_lex_advance(lx); l2c_lex_advance(lx); /* skip ::type:: */
            l2c_lex_match(lx,TK_DCOLON);
        }
        if(l2c_lex_match(lx,TK_ASSIGN)){
            L2CBuf rhss[8]; int types2[8]; int nr=0;
            while(nr<nn){
                l2c_buf_init(&rhss[nr]);
                int pk=l2c_peek_type(lx,&em->st);
                types2[nr]=pk;
                types2[nr]=l2c_emit_expr_prec(lx,&rhss[nr],em,0);
                nr++;
                if(!l2c_lex_match(lx,TK_COMMA)) break;
            }
            /* emite declaracoes */
            for(int i=0;i<nn;i++){
                int tp=i<nr?types2[i]:L2C_DOUBLE;
                l2c_st_set(&em->st,names[i],tp,0);
                l2c_emit_indent(em);
                if(tp==L2C_STR){
                    int sz=512;
                    l2c_buf_addf(em->out,"char %s[%d]",names[i],sz);
                    if(i<nr&&rhss[i].buf&&rhss[i].buf[0]){
                        /* se e string literal -> strcpy, senao snprintf */
                        if(rhss[i].buf[0]=='"')
                            l2c_buf_addf(em->out,"; strcpy(%s, %s);\n",names[i],rhss[i].buf);
                        else
                            l2c_buf_addf(em->out,"; snprintf(%s, %d, \"%%s\", %s);\n",names[i],sz,rhss[i].buf);
                    } else {
                        l2c_buf_add(em->out," = {0};\n");
                    }
                } else if(tp==L2C_CSTR){
                    l2c_buf_addf(em->out,"const char *%s = %s;\n",names[i],
                        i<nr&&rhss[i].buf?rhss[i].buf:"NULL");
                } else if(tp==L2C_BOOL){
                    l2c_buf_addf(em->out,"int %s = %s;\n",names[i],
                        i<nr&&rhss[i].buf?rhss[i].buf:"0");
                } else if(tp==L2C_INT){
                    l2c_buf_addf(em->out,"int %s = %s;\n",names[i],
                        i<nr&&rhss[i].buf?rhss[i].buf:"0");
                } else if(tp==L2C_TABLE){
                    /* emite como array generico */
                    l2c_buf_addf(em->out,"double %s[] = %s;\n",names[i],
                        i<nr&&rhss[i].buf?rhss[i].buf:"{0}");
                } else {
                    l2c_buf_addf(em->out,"double %s = %s;\n",names[i],
                        i<nr&&rhss[i].buf?rhss[i].buf:"0.0");
                }
                if(i<nr) l2c_buf_free(&rhss[i]);
            }
            for(int i=nr;i<8;i++) if(rhss[i].buf) l2c_buf_free(&rhss[i]);
        } else {
            /* sem inicializacao */
            for(int i=0;i<nn;i++){
                l2c_st_set(&em->st,names[i],L2C_DOUBLE,0);
                l2c_emit_indent(em);
                l2c_buf_addf(em->out,"double %s = 0.0;\n",names[i]);
            }
        }
        return;
    }

    /* -- function decl -- */
    case TK_FUNCTION:
        l2c_lex_advance(lx);
        l2c_emit_func_decl(lx,em,0);
        return;

    /* -- if -- */
    case TK_IF: {
        l2c_lex_advance(lx);
        l2c_emit_indent(em);
        /* Pula parênteses externos opcionais: "if (cond) then" → "if (cond) {" sem duplo parêntese */
        int _if_has_paren = l2c_lex_check(lx, TK_LPAREN);
        if(_if_has_paren) l2c_lex_advance(lx); /* consome ( */
        l2c_buf_add(em->out,"if (");
        l2c_emit_expr_prec(lx,em->out,em,0);
        if(_if_has_paren) l2c_lex_match(lx, TK_RPAREN); /* consome ) */
        l2c_buf_add(em->out,") {\n");
        l2c_lex_match(lx,TK_THEN);
        em->depth++;
        l2c_emit_block(lx,em,TK_END,TK_ELSE,TK_ELSEIF);
        em->depth--;
        while(l2c_lex_check(lx,TK_ELSEIF)){
            l2c_lex_advance(lx);
            l2c_emit_indent(em); l2c_buf_add(em->out,"} else if (");
            int _ei_has_paren = l2c_lex_check(lx, TK_LPAREN);
            if(_ei_has_paren) l2c_lex_advance(lx);
            l2c_emit_expr_prec(lx,em->out,em,0);
            if(_ei_has_paren) l2c_lex_match(lx, TK_RPAREN);
            l2c_buf_add(em->out,") {\n");
            l2c_lex_match(lx,TK_THEN);
            em->depth++;
            l2c_emit_block(lx,em,TK_END,TK_ELSE,TK_ELSEIF);
            em->depth--;
        }
        if(l2c_lex_match(lx,TK_ELSE)){
            l2c_emit_indent(em); l2c_buf_add(em->out,"} else {\n");
            em->depth++;
            l2c_emit_block(lx,em,TK_END,TK_EOF,TK_EOF);
            em->depth--;
        }
        l2c_lex_match(lx,TK_END);
        l2c_emit_indent(em); l2c_buf_add(em->out,"}\n");
        return;
    }

    /* -- while -- */
    case TK_WHILE: {
        l2c_lex_advance(lx);
        l2c_emit_indent(em); l2c_buf_add(em->out,"while (");
        int _wh_has_paren = l2c_lex_check(lx, TK_LPAREN);
        if(_wh_has_paren) l2c_lex_advance(lx);
        l2c_emit_expr_prec(lx,em->out,em,0);
        if(_wh_has_paren) l2c_lex_match(lx, TK_RPAREN);
        l2c_buf_add(em->out,") {\n");
        l2c_lex_match(lx,TK_DO);
        l2c_st_push_scope(&em->st); em->depth++;
        l2c_emit_block(lx,em,TK_END,TK_EOF,TK_EOF);
        em->depth--; l2c_st_pop_scope(&em->st);
        l2c_lex_match(lx,TK_END);
        l2c_emit_indent(em); l2c_buf_add(em->out,"}\n");
        return;
    }

    /* -- repeat..until -- */
    case TK_REPEAT: {
        l2c_lex_advance(lx);
        l2c_emit_indent(em); l2c_buf_add(em->out,"do {\n");
        l2c_st_push_scope(&em->st); em->depth++;
        l2c_emit_block(lx,em,TK_UNTIL,TK_EOF,TK_EOF);
        em->depth--; l2c_st_pop_scope(&em->st);
        l2c_lex_match(lx,TK_UNTIL);
        l2c_emit_indent(em); l2c_buf_add(em->out,"} while (!(");
        l2c_emit_expr_prec(lx,em->out,em,0);
        l2c_buf_add(em->out,"));\n");
        return;
    }

    /* -- do..end -- */
    case TK_DO: {
        l2c_lex_advance(lx);
        l2c_emit_indent(em); l2c_buf_add(em->out,"{\n");
        l2c_st_push_scope(&em->st); em->depth++;
        l2c_emit_block(lx,em,TK_END,TK_EOF,TK_EOF);
        em->depth--; l2c_st_pop_scope(&em->st);
        l2c_lex_match(lx,TK_END);
        l2c_emit_indent(em); l2c_buf_add(em->out,"}\n");
        return;
    }

    /* -- for numerico ou generico -- */
    case TK_FOR: {
        l2c_lex_advance(lx);
        /* le primeiro nome */
        char vname[128]={0};
        L2CTok vn=l2c_lex_advance(lx);
        strncpy(vname,vn.str,127);

        if(l2c_lex_match(lx,TK_ASSIGN)){
            /* for numerico: for i=start,limit[,step] do */
            L2CBuf start_b,limit_b,step_b;
            l2c_buf_init(&start_b); l2c_buf_init(&limit_b); l2c_buf_init(&step_b);
            l2c_emit_expr_prec(lx,&start_b,em,0);
            l2c_lex_match(lx,TK_COMMA);
            l2c_emit_expr_prec(lx,&limit_b,em,0);
            int has_step=0;
            if(l2c_lex_match(lx,TK_COMMA)){
                has_step=1; l2c_emit_expr_prec(lx,&step_b,em,0);
            }
            l2c_lex_match(lx,TK_DO);

            /* inferir se int ou double */
            const char *vtype="double";
            if(start_b.buf&&strchr(start_b.buf,'.')==NULL&&
               limit_b.buf&&strchr(limit_b.buf,'.')==NULL) vtype="int";

            l2c_st_push_scope(&em->st);
            l2c_st_set(&em->st,vname,strcmp(vtype,"int")==0?L2C_INT:L2C_DOUBLE,0);
            l2c_emit_indent(em);
            if(has_step){
                const char *step_s=step_b.buf?step_b.buf:"1";
                int neg_step=(step_s[0]=='-');
                l2c_buf_addf(em->out,
                    "for (%s %s = %s; %s %s %s; %s += %s) {\n",
                    vtype, vname,
                    start_b.buf?start_b.buf:"0",
                    vname, neg_step?">=":"<=",
                    limit_b.buf?limit_b.buf:"0",
                    vname, step_s);
            } else {
                l2c_buf_addf(em->out,
                    "for (%s %s = %s; %s <= %s; %s++) {\n",
                    vtype, vname,
                    start_b.buf?start_b.buf:"0",
                    vname, limit_b.buf?limit_b.buf:"0",
                    vname);
            }
            l2c_buf_free(&start_b); l2c_buf_free(&limit_b); l2c_buf_free(&step_b);
            em->depth++;
            l2c_emit_block(lx,em,TK_END,TK_EOF,TK_EOF);
            em->depth--;
            l2c_st_pop_scope(&em->st);
            l2c_lex_match(lx,TK_END);
            l2c_emit_indent(em); l2c_buf_add(em->out,"}\n");
        } else {
            /* for generico: for k, v in ipairs(t) do */
            char vnames[8][128]; int nvnames=0;
            strncpy(vnames[nvnames++],vname,127);
            while(l2c_lex_match(lx,TK_COMMA)&&nvnames<8){
                L2CTok vn2=l2c_lex_advance(lx);
                strncpy(vnames[nvnames++],vn2.str,127);
            }
            l2c_lex_match(lx,TK_IN);
            /* detecta ipairs/pairs */
            int is_ipairs=0;
            L2CBuf iter_expr; l2c_buf_init(&iter_expr);
            if(l2c_lex_check(lx,TK_IDENT)){
                L2CTok it=l2c_lex_peek(lx);
                if(strcmp(it.str,"ipairs")==0) is_ipairs=1;
                else if(strcmp(it.str,"pairs")==0) is_ipairs=0;
            }
            l2c_emit_expr_prec(lx,&iter_expr,em,0);
            l2c_lex_match(lx,TK_DO);

            /* para ipairs -> for(int _i=0; ...) com cast */
            l2c_st_push_scope(&em->st);
            if(is_ipairs){
                char *arr_name=iter_expr.buf?iter_expr.buf:"_arr";
                /* strip "ipairs(" prefix se presente */
                if(strncmp(arr_name,"ipairs(",7)==0){
                    arr_name+=7;
                    int len=(int)strlen(arr_name);
                    if(len>0&&arr_name[len-1]==')') arr_name[len-1]='\0';
                }
                l2c_emit_indent(em);
                l2c_buf_addf(em->out,
                    "for (int _l2c_i = 0; _l2c_i < (int)(sizeof(%s)/sizeof(%s[0])); _l2c_i++) {\n",
                    arr_name, arr_name);
                em->depth++;
                if(nvnames>=1){
                    l2c_st_set(&em->st,vnames[0],L2C_INT,0);
                    l2c_emit_indent(em);
                    l2c_buf_addf(em->out,"int %s = _l2c_i + 1;\n",vnames[0]);
                }
                if(nvnames>=2){
                    l2c_st_set(&em->st,vnames[1],L2C_DOUBLE,0);
                    l2c_emit_indent(em);
                    l2c_buf_addf(em->out,"double %s = %s[_l2c_i];\n",vnames[1],arr_name);
                }
            } else {
                /* pairs -> sem suporte runtime completo, emite comentario + loop vazio */
                l2c_emit_indent(em);
                l2c_buf_addf(em->out,"/* pairs(%s) -- iteracao de tabela hash nao suportada */\n",
                    iter_expr.buf?iter_expr.buf:"");
                l2c_buf_add(em->out,"if(0) {\n");
                em->depth++;
                for(int i=0;i<nvnames;i++){
                    l2c_st_set(&em->st,vnames[i],L2C_DOUBLE,0);
                    l2c_emit_indent(em);
                    l2c_buf_addf(em->out,"double %s = 0;\n",vnames[i]);
                }
            }
            l2c_buf_free(&iter_expr);
            l2c_emit_block(lx,em,TK_END,TK_EOF,TK_EOF);
            em->depth--;
            l2c_st_pop_scope(&em->st);
            l2c_lex_match(lx,TK_END);
            l2c_emit_indent(em); l2c_buf_add(em->out,"}\n");
        }
        return;
    }

    /* -- return -- */
    case TK_RETURN: {
        l2c_lex_advance(lx);
        l2c_emit_indent(em);
        /* checar se ha valor */
        L2CTokKind nk=l2c_lex_peek(lx).kind;
        if(nk==TK_END||nk==TK_ELSE||nk==TK_ELSEIF||nk==TK_UNTIL||
           nk==TK_EOF||nk==TK_SEMICOLON){
            if(em->in_func) l2c_buf_add(em->out,"return 0.0;\n");
            else l2c_buf_add(em->out,"return 0;\n");
            l2c_lex_match(lx,TK_SEMICOLON);
            return;
        }
        l2c_buf_add(em->out,"return (double)(");
        l2c_emit_expr_prec(lx,em->out,em,0);
        l2c_buf_add(em->out,");\n");
        l2c_lex_match(lx,TK_SEMICOLON);
        return;
    }

    /* -- break -- */
    case TK_BREAK:
        l2c_lex_advance(lx);
        l2c_emit_indent(em); l2c_buf_add(em->out,"break;\n");
        return;

    /* -- goto -- */
    case TK_GOTO: {
        l2c_lex_advance(lx);
        L2CTok lbl=l2c_lex_advance(lx);
        l2c_emit_indent(em);
        l2c_buf_addf(em->out,"goto %s;\n",lbl.str);
        return;
    }

    /* -- ::label:: -- */
    case TK_DCOLON: {
        l2c_lex_advance(lx);
        L2CTok lbl=l2c_lex_advance(lx);
        l2c_lex_match(lx,TK_DCOLON);
        l2c_buf_addf(em->out,"%s:\n",lbl.str);
        return;
    }

    /* -- print especial -- */
    case TK_IDENT: {
        if(strcmp(tk.str,"print")==0){
            l2c_lex_advance(lx);
            l2c_emit_print_stmt(lx,em);
            return;
        }
        /* atribuicao ou chamada de funcao -- fall through */
        goto assign_or_call;
    }

    default:
    assign_or_call:;
    {
        /* coleta lado esquerdo: pode ser var, var[i], var.field */
        char lhs_names[8][256]; int nlhs=0;
        int is_assign=0;

        /* salva posicao do lexer */
        L2CTok saved_cur=lx->cur; L2CTok saved_pk=lx->peek;
        int saved_has=lx->has_peek; int saved_pos=lx->pos;

        /* tenta ler varlist */
        while(l2c_lex_check(lx,TK_IDENT)&&nlhs<8){
            L2CTok vn2=l2c_lex_advance(lx);
            char vfull[256]; strncpy(vfull,vn2.str,255);
            /* sufixo .field ou [idx] */
            while(l2c_lex_check(lx,TK_DOT)||l2c_lex_check(lx,TK_COLON)||
                  l2c_lex_check(lx,TK_LBRACKET)){
                if(l2c_lex_check(lx,TK_LBRACKET)){
                    strncat(vfull,"[",sizeof(vfull)-strlen(vfull)-1);
                    l2c_lex_advance(lx);
                    L2CBuf ibuf; l2c_buf_init(&ibuf);
                    l2c_emit_expr_prec(lx,&ibuf,em,0);
                    /* Lua 1-based -> C 0-based */
                    if(ibuf.buf&&ibuf.buf[0]>='0'&&ibuf.buf[0]<='9'){
                        int v=atoi(ibuf.buf); char tmp2[32]; snprintf(tmp2,32,"%d",v-1);
                        strncat(vfull,tmp2,sizeof(vfull)-strlen(vfull)-1);
                    } else {
                        strncat(vfull,ibuf.buf?ibuf.buf:"0",sizeof(vfull)-strlen(vfull)-1);
                        strncat(vfull,"-1",sizeof(vfull)-strlen(vfull)-1);
                    }
                    l2c_buf_free(&ibuf);
                    strncat(vfull,"]",sizeof(vfull)-strlen(vfull)-1);
                    l2c_lex_match(lx,TK_RBRACKET);
                } else {
                    l2c_lex_advance(lx);
                    if(l2c_lex_check(lx,TK_IDENT)){
                        L2CTok fld=l2c_lex_advance(lx);
                        strncat(vfull,".",sizeof(vfull)-strlen(vfull)-1);
                        strncat(vfull,fld.str,sizeof(vfull)-strlen(vfull)-1);
                    }
                }
            }
            strncpy(lhs_names[nlhs++],vfull,255);
            if(!l2c_lex_match(lx,TK_COMMA)) break;
        }

        /* compound assign (Lua nao tem, mas usuario pode escrever) */
        L2CTokKind nk2=l2c_lex_peek(lx).kind;
        if(nk2==TK_PLUSEQ||nk2==TK_MINUSEQ||nk2==TK_STAREQ||nk2==TK_SLASHEQ){
            l2c_lex_advance(lx);
            char op_c[3]={nk2==TK_PLUSEQ?'+':nk2==TK_MINUSEQ?'-':nk2==TK_STAREQ?'*':'/',
                          '=','\0'};
            l2c_emit_indent(em);
            l2c_buf_addf(em->out,"%s %s ",lhs_names[0],op_c);
            l2c_emit_expr_prec(lx,em->out,em,0);
            l2c_buf_add(em->out,";\n");
            return;
        }

        if(nk2==TK_ASSIGN){ is_assign=1; l2c_lex_advance(lx); }

        if(is_assign){
            L2CBuf rhss2[8]; int types3[8]; int nr2=0;
            while(nr2<nlhs){
                l2c_buf_init(&rhss2[nr2]);
                types3[nr2]=l2c_emit_expr_prec(lx,&rhss2[nr2],em,0);
                nr2++;
                if(!l2c_lex_match(lx,TK_COMMA)) break;
            }
            for(int i=0;i<nlhs;i++){
                int existing_type=l2c_st_type(&em->st,lhs_names[i]);
                int tp=i<nr2?types3[i]:L2C_DOUBLE;
                l2c_emit_indent(em);
                if(existing_type==L2C_STR){
                    /* strcpy */
                    if(i<nr2&&rhss2[i].buf&&rhss2[i].buf[0]=='"'){
                        l2c_buf_addf(em->out,"strcpy(%s, %s);\n",lhs_names[i],rhss2[i].buf);
                    } else {
                        l2c_buf_addf(em->out,"snprintf(%s, sizeof(%s), \"%%s\", %s);\n",
                            lhs_names[i],lhs_names[i],i<nr2&&rhss2[i].buf?rhss2[i].buf:"\"\"");
                    }
                } else if(!existing_type){
                    /* variavel nova implicita -> global C */
                    l2c_st_set(&em->st,lhs_names[i],tp,0);
                    if(tp==L2C_INT) l2c_buf_addf(em->out,"int %s = %s;\n",lhs_names[i],i<nr2&&rhss2[i].buf?rhss2[i].buf:"0");
                    else if(tp==L2C_STR) l2c_buf_addf(em->out,"char %s[512]; strcpy(%s, %s);\n",lhs_names[i],lhs_names[i],i<nr2&&rhss2[i].buf?rhss2[i].buf:"\"\"");
                    else l2c_buf_addf(em->out,"double %s = %s;\n",lhs_names[i],i<nr2&&rhss2[i].buf?rhss2[i].buf:"0.0");
                } else {
                    l2c_buf_addf(em->out,"%s = %s;\n",lhs_names[i],i<nr2&&rhss2[i].buf?rhss2[i].buf:(tp==L2C_STR?"\"\"":"0"));
                }
                if(i<nr2) l2c_buf_free(&rhss2[i]);
            }
            return;
        }

        /* nao e atribuicao -- restaura e emite como expressao-statement (chamada) */
        lx->cur=saved_cur; lx->peek=saved_pk;
        lx->has_peek=saved_has; lx->pos=saved_pos;
        l2c_emit_indent(em);
        l2c_emit_expr_prec(lx,em->out,em,0);
        l2c_buf_add(em->out,";\n");
        return;
    }
    } /* switch */
}

static void l2c_emit_block(L2CLex *lx, L2CEmit *em,
                            L2CTokKind stop1, L2CTokKind stop2, L2CTokKind stop3){
    for(;;){
        if(em->had_error) return;
        L2CTokKind pk=l2c_lex_peek(lx).kind;
        if(pk==TK_EOF||pk==stop1||pk==stop2||pk==stop3) return;
        l2c_emit_statement(lx,em);
    }
}

