                curl_easy_setopt(_blc,CURLOPT_CONNECTTIMEOUT,5L); \
                curl_easy_setopt(_blc,CURLOPT_SSL_VERIFYPEER,0L); \
                curl_easy_setopt(_blc,CURLOPT_SSL_VERIFYHOST,0L); \
                curl_easy_setopt(_blc,CURLOPT_FOLLOWLOCATION,1L); \
                curl_easy_perform(_blc); curl_easy_cleanup(_blc); \
                if (_blwb.len > _bl) _bl = _blwb.len; \
                free(_blwb.buf); \
            } \
          } \
        } \
        \
        /* Lança threads em lotes dinâmicos: mín 32 máx 128 */ \
        { int _BATCH = 32; \
          { FILE *_np=popen("nproc 2>/dev/null","r"); int _nc=4; \
            if(_np){fscanf(_np,"%d",&_nc);pclose(_np);} \
            _BATCH=_nc*8; if(_BATCH<32)_BATCH=32; if(_BATCH>128)_BATCH=128; } \
          pthread_t *_pool=(pthread_t*)malloc(sizeof(pthread_t)*(size_t)_BATCH); \
          if(!_pool) _BATCH=0; \
          int _done=0; \
          while (_pool && _done < _final_count) { \
            int _n=_final_count-_done; if(_n>_BATCH)_n=_BATCH; \
            for(int _pi=0;_pi<_n;_pi++){ \
                test_arg_t *_ta=calloc(1,sizeof(test_arg_t)); \
                if(!_ta)continue; \
                strncpy(_ta->payload,_final_payloads[_done+_pi],511); \
                strncpy(_ta->target,_etarget,1023); \
                _ta->timeout=timeout_val; \
                _ta->baseline_len=_bl; \
                _ta->waf_type=(int)_waf; \
                pthread_create(&_pool[_pi],NULL,worker_fn,_ta); \
            } \
            for(int _pi=0;_pi<_n;_pi++) pthread_join(_pool[_pi],NULL); \
            _done+=_n; \
            if(_done<_final_count) printf("\033[0;90m  [%d/%d]\033[0m\n",_done,_final_count); \
          } \
          if(_pool) free(_pool); \
        } \
        if (_sorted_alloc) free(_final_payloads); \
        \
        int _ep_hits      = (int)atomic_load(&g_vuln_count)  - _grand_total; \
        int _payload_hits = (int)atomic_load(&g_payload_hits) - _grand_payloads_hits; \
        _grand_total         = (int)atomic_load(&g_vuln_count); \
