            printf("\033[1;31m%-35s\033[0m\033[1m  │\033[0m\n", waf_name(_waf)); \
        else \
            printf("\033[1;32m%-35s\033[0m\033[1m  │\033[0m\n", "Nenhum"); \
        printf("\033[1m│  Payloads testados : %-24d│\033[0m\n", _final_count); \
