            printf("\033[1;31m│  ❌ VULNERÁVEL                              │\033[0m\n"); \
            printf("\033[1;31m│     Payloads confirmados : %-17d│\033[0m\n", _payload_hits); \
            printf("\033[1;31m│     Endpoints únicos     : %-17d│\033[0m\n", _ep_hits); \
        } else \
            printf("\033[1;32m│  ✅ Sem vulnerabilidade detectada           │\033[0m\n"); \
        printf("\033[1m└─────────────────────────────────────────────┘\033[0m\n"); \
    } \
    \
    /* Summary final se múltiplos endpoints */ \
    if (_tc > 1) { \
        printf("\n\033[1;33m══ RESUMO GERAL (%d endpoints testados) ══\033[0m\n", _tc); \
        printf("\033[1m  Total payloads testados   : %d\033[0m\n", _grand_payloads); \
        if (_grand_total > 0) { \
            printf("\033[1;31m  Payloads confirmados      : %d\033[0m\n", _grand_payloads_hits); \
            printf("\033[1;31m  Endpoints únicos vulnéráveis: %d\033[0m\n\n", _grand_total); \
        } else \
            printf("\033[1;32m  Resultado: 0 vulnerabilidades encontradas\033[0m\n\n"); \
    } \
    \
    if (_from_file) free_payloads(_use_payloads, _use_count); \
    else if (_use_payloads) free(_use_payloads); \
    if (_auto_mode) free_scan_targets(_ts, _tc); \
    lua_pushinteger(L, _grand_total); \
} while(0)


/* ─── auto-spider: coleta endpoints com parâmetros ───────────────────────────
 * Faz GET na URL base, extrai <a href> e <form action> que contenham '?'
 * Resolve relativos, filtra mesmo domínio.
 * Retorna array de strings (caller faz free de cada elemento + do array).
 * *out_count = número de itens; retorna NULL se nenhum encontrado.
 */
/* ── helpers internos para collect_scan_targets ── */
/* Garante que a URL tem scheme http:// — modifica out, retorna out */
static const char *normalize_url(const char *raw, char *out, size_t outsz) {
    if (strncmp(raw,"http://",7)==0 || strncmp(raw,"https://",8)==0) {
        snprintf(out, outsz, "%s", raw);
    } else {
        snprintf(out, outsz, "http://%s", raw);
    }
    return out;
}

/* Pool global de handles CURL reutilizáveis para o spider — evita init/cleanup por fetch */
/* cst_fetch usa handle próprio por chamada — sem estado global */

static void cst_fetch(const char *url, WorkBuf *wb) {
    wb->buf = malloc(262144); wb->cap = 262144; wb->len = 0;
    if (!wb->buf) return;

    /* Cada thread usa seu próprio handle — sem mutex, sem reset entre threads */
    CURL *ch = curl_easy_init();
    if (!ch) { free(wb->buf); wb->buf=NULL; return; }

    curl_easy_setopt(ch, CURLOPT_URL,            url);
    curl_easy_setopt(ch, CURLOPT_WRITEFUNCTION,  worker_write_cb);
    curl_easy_setopt(ch, CURLOPT_WRITEDATA,       wb);
    curl_easy_setopt(ch, CURLOPT_TIMEOUT,         10L);
    curl_easy_setopt(ch, CURLOPT_CONNECTTIMEOUT,   5L);
    curl_easy_setopt(ch, CURLOPT_SSL_VERIFYPEER,   0L);
    curl_easy_setopt(ch, CURLOPT_SSL_VERIFYHOST,   0L);
    curl_easy_setopt(ch, CURLOPT_FOLLOWLOCATION,   1L);
    curl_easy_setopt(ch, CURLOPT_MAXREDIRS,        5L);
    curl_easy_setopt(ch, CURLOPT_MAXFILESIZE,      524288L);
    curl_easy_setopt(ch, CURLOPT_USERAGENT,
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/124");
    curl_easy_perform(ch);
    curl_easy_cleanup(ch);

    if (wb->len < wb->cap) wb->buf[wb->len] = 0;
    else wb->buf[wb->cap-1] = 0;
}

/* Resolve URL relativa contra base_url.
 * Suporta: absoluta, /path, ../rel, ./rel, rel
 * Normaliza sequencias ../ no path resultante. */
static void cst_url_normalize(char *path) {
    /* remove /foo/../ recursivamente */
    char *p;
    while ((p = strstr(path, "/../")) != NULL) {
        char *prev = p - 1;
        while (prev > path && *prev != '/') prev--;
        if (prev <= path) { memmove(p, p+3, strlen(p+3)+1); }
        else              { memmove(prev, p+3, strlen(p+3)+1); }
    }
    /* remove /./ */
    while ((p = strstr(path, "/./")) != NULL)
        memmove(p, p+2, strlen(p+2)+1);
    /* remove barras duplas // (exceto após http: ou https:) */
    p = path;
    while (*p) {
        if (p[0]=='/' && p[1]=='/') {
            /* verifica se é o :// do protocolo */
            if (p > path && *(p-1)==':') { p+=2; continue; }
            memmove(p, p+1, strlen(p+1)+1);
            continue;
        }
        p++;
    }
}

static void cst_resolve(const char *raw, const char *base_url,
                        const char *origin, char *out, size_t outsz) {
    if (strncmp(raw,"http://",7)==0 || strncmp(raw,"https://",8)==0) {
        snprintf(out, outsz, "%s", raw);
        return;
    }
    if (raw[0]=='/') {
        snprintf(out, outsz, "%s%s", origin, raw);
        /* normaliza // que pode acontecer se origin termina com / e raw começa com / */
        char *path_s = out + strlen(origin) - 1;
        if (path_s > out && *path_s=='/' && *(path_s+1)=='/')
            memmove(path_s, path_s+1, strlen(path_s+1)+1);
        return;
    }
    /* query-only (ex: ?page=2): anexa ao path atual sem o diretorio pai */
    if (raw[0]=='?') {
        /* remove query existente do base_url */
        char base_nq[1024] = {0};
        const char *bqm = strchr(base_url, '?');
        if (bqm) { size_t bl = (size_t)(bqm-base_url); if (bl<sizeof(base_nq)) memcpy(base_nq,base_url,bl); }
        else snprintf(base_nq, sizeof(base_nq), "%s", base_url);
        snprintf(out, outsz, "%s%s", base_nq, raw);
        return;
    }
    /* relativo: monta base_dir */
    char base_dir[512] = {0};
    const char *ls = strrchr(base_url, '/');
    if (ls && ls > base_url+8) {
        size_t dl = (size_t)(ls - base_url) + 1;
        if (dl < sizeof(base_dir)) memcpy(base_dir, base_url, dl);
    } else {
        snprintf(base_dir, sizeof(base_dir), "%s/", base_url);
    }
    snprintf(out, outsz, "%s%s", base_dir, raw);
    /* normaliza ../ e ./ no path (apenas na parte apos o origin) */
    char *path_start = out + strlen(origin);
    if (path_start > out && path_start < out + strlen(out))
        cst_url_normalize(path_start);
}

/* adiciona target normalizado ao array, sem duplicatas */
static void cst_add(char **targets, int *n, int max,
                    const char *full, const char *origin) {
    if (*n >= max) return;
    /* precisa ter ? e = e ser do mesmo domínio */
    if (!strstr(full, origin)) return;
    char *qm = strchr(full, '?');
    if (!qm || !strchr(qm, '=')) return;

    /* ── Validação extra: rejeita lixo de JS ──────────────────────────────
     * A URL deve começar com http:// ou https://
     * O path (antes do ?) não pode ter: espaços, {, }, (, ), ;, \n, JS ops */
    if (strncmp(full,"http://",7)!=0 && strncmp(full,"https://",8)!=0) return;
    /* verifica caracteres inválidos no path (antes do ?) */
    for (const char *c = full; c < qm; c++) {
        unsigned char ch = (unsigned char)*c;
        /* rejeita: espaço, controle, {, }, (, ), ;, <, >, |, \, ^, `, ~ */
        if (ch < 0x21 || ch > 0x7e) return;
        if (*c=='{' || *c=='}' || *c=='(' || *c==')' || *c==';' ||
            *c=='<' || *c=='>' || *c=='|' || *c=='^' || *c=='`' ||
            *c=='\\' || *c=='+' || *c=='\'' || *c=='"') return;
    }
    /* path não pode ser absurdamente longo (JS inline) */
    if ((size_t)(qm - full) > 256) return;

    /* Para URLs com múltiplos parâmetros (ex: /search?q=hello&page=1&sort=asc)
     * gera um target para CADA parâmetro: /search?q=  /search?q=hello&page=  etc.
     * Assim todos os campos são testados, não apenas o último. */
    char base[512] = {0};
    size_t blen = (size_t)(qm - full);
    if (blen >= sizeof(base)) return;
    memcpy(base, full, blen); /* ex: "http://site.com/search" */

    /* copia a query string */
    const char *qs = qm + 1; /* pula o '?' */
    char query[512] = {0};
    /* remove fragment # se houver */
    const char *frag = strchr(qs, '#');
    size_t qslen = frag ? (size_t)(frag - qs) : strlen(qs);
    if (qslen >= sizeof(query)) qslen = sizeof(query) - 1;
    memcpy(query, qs, qslen);

    /* itera cada par key=value */
    char acc[512] = {0}; /* acumula "key=value&" anteriores para URLs multi-param */
    char *tok = query;
    while (tok && *tok) {
        char *amp = strchr(tok, '&');
        size_t plen = amp ? (size_t)(amp - tok) : strlen(tok);
        char pair[256] = {0};
        if (plen >= sizeof(pair)) { if (amp) tok = amp+1; else break; continue; }
        memcpy(pair, tok, plen);

        char *eq = strchr(pair, '=');
        if (eq) {
            /* trunca o valor: mantém key= */
            *(eq+1) = '\0';
            /* monta target: base?acc+key= */
            char norm[1024] = {0};
            if (acc[0])
                snprintf(norm, sizeof(norm), "%s?%s%s", base, acc, pair);
            else
                snprintf(norm, sizeof(norm), "%s?%s", base, pair);
            /* adiciona se não duplicado */
            int dup = 0;
            for (int i = 0; i < *n; i++) if (strcmp(targets[i], norm) == 0) { dup = 1; break; }
            if (!dup && *n < max) targets[(*n)++] = strdup(norm);

            /* acumula este par completo (com valor original) para o próximo target */
            char pair_full[256] = {0};
            memcpy(pair_full, tok, plen);
            size_t al = strlen(acc);
            if (al + plen + 2 < sizeof(acc)) {
                memcpy(acc + al, pair_full, plen);
                acc[al + plen] = '&';
                acc[al + plen + 1] = '\0';
            }
        }
        tok = amp ? amp + 1 : NULL;
    }
}

/* extrai href/action com ?param= de um html e adiciona ao targets */
/* Extrai o valor de um atributo HTML — suporta com e sem aspas.
 * Ex: href="/path?q=1"  href='/path'  href=/path?q=1
 * Retorna o comprimento copiado em out (max outsz-1). */
static size_t html_attr_val(const char *src, char *out, size_t outsz) {
    if (!src || !out || outsz < 2) return 0;
    out[0] = '\0';
    /* skip whitespace antes do valor (ex: href=\n   "/path") */
    while (*src == ' ' || *src == '\t' || *src == '\n' || *src == '\r') src++;
    char q = *src;
    const char *start;
    const char *end;
    if (q == '"' || q == '\'') {
        start = src + 1;
        end   = strchr(start, q);
        if (!end) return 0;
    } else {
        start = src;
        /* sem aspas: termina em espaco, >, ou \0 */
        end = start;
        while (*end && *end != ' ' && *end != '>' && *end != '\t' && *end != '\n' && *end != '\r') end++;
    }
    size_t len = (size_t)(end - start);
    if (len == 0 || len >= outsz) return 0;
    /* copia com decode de &amp; -> & e &lt; -> < */
    size_t wi = 0;
    for (size_t ri = 0; ri < len && wi + 1 < outsz; ri++) {
        if (start[ri] == '&' && ri + 4 < len && strncmp(start+ri, "&amp;", 5) == 0) {
            out[wi++] = '&'; ri += 4;
        } else if (start[ri] == '&' && ri + 3 < len && strncmp(start+ri, "&lt;", 4) == 0) {
            out[wi++] = '<'; ri += 3;
        } else if (start[ri] == '&' && ri + 3 < len && strncmp(start+ri, "&gt;", 4) == 0) {
            out[wi++] = '>'; ri += 3;
        } else {
            out[wi++] = start[ri];
        }
    }
    out[wi] = '\0';
    return wi;
}
static void cst_extract_params(char *html, const char *page_url,
                               const char *origin,
                               char **targets, int *n, int max) {
    /* procura href, action e atributos data-* comuns com ou sem aspas */
    const char *attrs[] = {"href=","action=","data-href=","data-url=","data-src=",NULL};
    for (int ai=0; attrs[ai] && *n<max; ai++) {
        char *pos = html;
        size_t alen = strlen(attrs[ai]);
        while (*n < max) {
            pos = strcasestr(pos, attrs[ai]);
            if (!pos) break;
            pos += alen;
            char raw[513]={0};
            size_t rlen = html_attr_val(pos, raw, sizeof(raw));
            if (rlen == 0) { pos++; continue; }
            /* avança pos além do valor */
            if (*pos == '"' || *pos == '\'') pos += rlen + 2;
            else pos += rlen;
            if (raw[0] == '#' || strncmp(raw,"mailto",6)==0 || strncmp(raw,"javascript",10)==0) continue;
            char full[1024]={0};
            cst_resolve(raw, page_url, origin, full, sizeof(full));
            cst_add(targets, n, max, full, origin);
        }
    }
}

/* extrai forms + inputs de um html e adiciona endpoints ao targets */
static void cst_extract_forms(char *html, const char *page_url,
                              const char *origin,
                              char **targets, int *n, int max) {
    char *fp = html;
    while (*n < max && (fp = strcasestr(fp, "<form")) != NULL) {
        /* acha o fim da tag <form ...> */
        char *form_tag_end = strchr(fp+5, '>');
        if (!form_tag_end) break;

        /* extrai action= da tag form — com ou sem aspas */
        char faction[512] = {0};
        char *fa = strcasestr(fp+5, "action=");
        if (fa && fa < form_tag_end) {
            fa += 7;
            html_attr_val(fa, faction, sizeof(faction));
        }
        char fbase[1024]={0};
        if (faction[0]) cst_resolve(faction, page_url, origin, fbase, sizeof(fbase));
        else snprintf(fbase, sizeof(fbase), "%s", page_url);
        /* remove query do action */
        char *fqm = strchr(fbase,'?'); if (fqm) *fqm='\0';

        /* acha o </form> correspondente */
        char *form_end = strcasestr(fp+5, "</form");
        if (!form_end) form_end = fp + strlen(fp);

        /* extrai inputs dentro do form */
        const char *itags[] = {"<input ","<select ","<textarea ",NULL};
        for (int ii=0; itags[ii] && *n<max; ii++) {
            char *ip = fp;
            while (*n<max && ip < form_end) {
                ip = strcasestr(ip, itags[ii]);
                if (!ip||ip>form_end) break;
                ip++;
                char *itag_end = strchr(ip, '>');
                if (!itag_end||itag_end>form_end) break;

                /* verifica type= — ignora hidden/submit/button */
                char *it = strcasestr(ip, "type=");
                if (it&&it<itag_end) {
                    char tv[32]={0}; char *tvs=it+5;
                    if (*tvs=='"'||*tvs=='\'') tvs++;
                    memcpy(tv,tvs,sizeof(tv)-1);
                    char *tvend=tv; while(*tvend&&*tvend!='"'&&*tvend!='\''&&*tvend!=' '&&*tvend!='>') tvend++;
                    *tvend='\0';
                    if (strcasestr(tv,"hidden")||strcasestr(tv,"submit")||strcasestr(tv,"button"))
                        {ip=itag_end;continue;}
                }

                /* extrai name= — com ou sem aspas */
                char *nm = strcasestr(ip, "name=");
                if (!nm||nm>itag_end){ip=itag_end;continue;}
                nm+=5;
                char iname[65]={0};
                if (html_attr_val(nm, iname, sizeof(iname)) == 0) {ip=itag_end;continue;}
                char cand[1024]={0};
                snprintf(cand,sizeof(cand),"%s?%s=",fbase,iname);
                cst_add(targets, n, max, cand, origin);
                ip=itag_end;
            }
        }
        fp = form_tag_end+1;
    }
}

/* -- Extrai URLs de strings JS e JSON ----------------------------------------
 * Captura padroes como:
 *   fetch('/api/search?q=')
 *   axios.get('/users?id=')
 *   url: '/api/data?type='
 *   "next": "/list?page=2"
 *   <meta http-equiv=refresh content="0;url=/page?id=1">
 *   <iframe src="/embed?id=1">
 * Estrategia: procura sequencias '/path?...=' ou "/path?...=" em qualquer contexto */
static void cst_extract_js(const char *html, const char *page_url,
                            const char *origin,
                            char **targets, int *n, int max) {
    if (!html) return;
    const char *pos = html;

    /* 1. Strings JS/JSON: qualquer "...?...=" ou '...?...=' */
    while (*n < max && *pos) {
        const char *dq = strchr(pos, '"');
        const char *sq = strchr(pos, '\'');
        const char *p;
        char qchar;
        if (!dq && !sq) break;
        if (!dq)       { p = sq; qchar = '\''; }
        else if (!sq)  { p = dq; qchar = '"';  }
        else if (dq < sq) { p = dq; qchar = '"';  }
        else           { p = sq; qchar = '\''; }
        pos = p + 1;
        const char *end = strchr(pos, qchar);
        if (!end || end == pos || (size_t)(end-pos) > 512) continue;
        const char *qm = memchr(pos, '?', (size_t)(end-pos));
        if (!qm) continue;
        const char *eq = memchr(qm, '=', (size_t)(end-qm));
        if (!eq) continue;
        char rawu[513] = {0};
        size_t rlen = (size_t)(end - pos);
        if (rlen == 0 || rlen >= sizeof(rawu)) continue;
        memcpy(rawu, pos, rlen);
        if (strncmp(rawu,"mailto",6)==0 || strncmp(rawu,"javascript",10)==0) continue;
        char full[1024] = {0};
        cst_resolve(rawu, page_url, origin, full, sizeof(full));
        cst_add(targets, n, max, full, origin);
    }

    /* 2. <meta http-equiv=refresh content="0;url=/page?id="> */
    pos = html;
    while (*n < max) {
        const char *mp = strcasestr(pos, "<meta");
        if (!mp) break;
        const char *mend = strchr(mp, '>');
        if (!mend) break;
        pos = mend + 1;
        if (!strcasestr(mp, "refresh")) continue;
        const char *cp = strcasestr(mp, "content=");
        if (!cp || cp > mend) continue;
        cp += 8;
        char cv[512] = {0};
        html_attr_val(cp, cv, sizeof(cv));
        char *up = strcasestr(cv, "url=");
        if (!up) continue;
        up += 4;
        char rawu[512] = {0};
        size_t ul = strlen(up);
        if (ul == 0 || ul >= sizeof(rawu)) continue;
        memcpy(rawu, up, ul);
        char full[1024] = {0};
        cst_resolve(rawu, page_url, origin, full, sizeof(full));
        cst_add(targets, n, max, full, origin);
    }

    /* 3. <iframe src="/embed?id="> */
    pos = html;
    while (*n < max) {
        const char *ip = strcasestr(pos, "<iframe");
        if (!ip) break;
        const char *iend = strchr(ip, '>');
        if (!iend) break;
        pos = iend + 1;
        const char *sp = strcasestr(ip, "src=");
        if (!sp || sp > iend) continue;
        sp += 4;
        char rawu[512] = {0};
        html_attr_val(sp, rawu, sizeof(rawu));
        if (!strchr(rawu, '?')) continue;
        char full[1024] = {0};
        cst_resolve(rawu, page_url, origin, full, sizeof(full));
        cst_add(targets, n, max, full, origin);
    }
}


/* ── Thread de fetch para o nível 2 do spider automático ── */
typedef struct { const char *url; WorkBuf wb; } CstL2Arg;
static void *cst_l2_thread(void *arg_v) {
    CstL2Arg *a = (CstL2Arg*)arg_v;
    cst_fetch(a->url, &a->wb);
    return NULL;
}

static char **collect_scan_targets(const char *base_url, int *out_count) {
    *out_count = 0;

    /* normaliza URL: adiciona http:// se não tiver scheme */
    char _norm_base[1024]={0};
    base_url = normalize_url(base_url, _norm_base, sizeof(_norm_base));

    /* extrai origin */
    char origin[256]={0};
    const char *p=base_url;
    if (strncmp(p,"http://",7)==0) p+=7;
    else if (strncmp(p,"https://",8)==0) p+=8;
    const char *sl=strchr(p,'/');
    size_t hlen=sl?(size_t)(sl-p):strlen(p);
    if (hlen>=sizeof(origin)) hlen=sizeof(origin)-1;
    if (strncmp(base_url,"https",5)==0)
        snprintf(origin,sizeof(origin),"https://%.*s",(int)hlen,p);
    else
        snprintf(origin,sizeof(origin),"http://%.*s",(int)hlen,p);

    #define MAX_TARGETS 128
    char **targets = calloc(MAX_TARGETS, sizeof(char*));
    if (!targets) return NULL;
    int n=0;

    /* ── Nível 1: busca página base ── */
    WorkBuf wb1={0}; cst_fetch(base_url, &wb1);
    if (!wb1.buf) { free(targets); return NULL; }

    cst_extract_params(wb1.buf, base_url, origin, targets, &n, MAX_TARGETS);
    cst_extract_forms (wb1.buf, base_url, origin, targets, &n, MAX_TARGETS);
    cst_extract_js    (wb1.buf, base_url, origin, targets, &n, MAX_TARGETS);

    /* ── Nível 2: coleta hrefs E form actions sem ? e visita cada um ── */
    #define MAX_L2 32
    char *l2[MAX_L2]; int l2n=0;
    {
        /* hrefs sem parâmetros */
        char *pos=wb1.buf;
        while (l2n<MAX_L2) {
            pos=strcasestr(pos,"href="); if(!pos) break;
            pos+=5;
            char raw[513]={0};
            size_t rlen = html_attr_val(pos, raw, sizeof(raw));
            if (rlen == 0) { pos++; continue; }
            if (*pos=='"'||*pos=='\'') pos += rlen + 2;
            else pos += rlen;
            if(raw[0]=='#'||strncmp(raw,"mailto",6)==0||strncmp(raw,"javascript",10)==0) continue;
            char full[1024]={0};
            cst_resolve(raw, base_url, origin, full, sizeof(full));
            if(!strstr(full,origin)) continue;
            if(strchr(full,'?')) continue;
            size_t fl=strlen(full);
            if(fl>0&&full[fl-1]=='/') full[fl-1]='\0';
            if(strcmp(full,base_url)==0) continue;
            int dup=0; for(int di=0;di<l2n;di++) if(strcmp(l2[di],full)==0){dup=1;break;}
            if(!dup) l2[l2n++]=strdup(full);
        }
        /* form actions sem parâmetros — garante que /exec /login /search sejam visitados */
        char *fpos=wb1.buf;
        while(l2n<MAX_L2 && (fpos=strcasestr(fpos,"<form"))!=NULL) {
            char *ftend=strchr(fpos+5,'>'); if(!ftend){fpos++;continue;}
            char *fa=strcasestr(fpos+5,"action=");
            if(fa && fa<ftend) {
                fa+=7; char faction[512]={0};
                html_attr_val(fa, faction, sizeof(faction));
                if(faction[0] && strncmp(faction,"#",1)!=0 &&
                   strncmp(faction,"javascript",10)!=0) {
                    char afull[1024]={0};
                    cst_resolve(faction, base_url, origin, afull, sizeof(afull));
                    if(strstr(afull,origin) && !strchr(afull,'?')) {
                        size_t afl=strlen(afull);
                        if(afl>0&&afull[afl-1]=='/') afull[afl-1]='\0';
                        int dup=0;
                        for(int di=0;di<l2n;di++) if(strcmp(l2[di],afull)==0){dup=1;break;}
                        if(strcmp(afull,base_url)!=0&&!dup) l2[l2n++]=strdup(afull);
                    }
                }
            }
            fpos=ftend+1;
        }
    }
    free(wb1.buf);

    /* Fetch nível 2 em lotes paralelos de 8 threads — evita travar 32×10s sequenciais */
    #define L2_BATCH 8
    {
        int li = 0;
        while (li < l2n && n < MAX_TARGETS) {
            int batch = l2n - li; if (batch > L2_BATCH) batch = L2_BATCH;
            CstL2Arg _args[L2_BATCH]; memset(_args, 0, sizeof(_args));
            pthread_t _ths[L2_BATCH];
            for (int bi = 0; bi < batch; bi++) _args[bi].url = l2[li+bi];
            for (int bi = 0; bi < batch; bi++)
                pthread_create(&_ths[bi], NULL, cst_l2_thread, &_args[bi]);
            for (int bi = 0; bi < batch; bi++)
                pthread_join(_ths[bi], NULL);
            for (int bi = 0; bi < batch && n < MAX_TARGETS; bi++) {
                if (_args[bi].wb.buf && _args[bi].wb.len > 0) {
                    cst_extract_params(_args[bi].wb.buf, _args[bi].url, origin, targets, &n, MAX_TARGETS);
                    cst_extract_forms (_args[bi].wb.buf, _args[bi].url, origin, targets, &n, MAX_TARGETS);
                    cst_extract_js    (_args[bi].wb.buf, _args[bi].url, origin, targets, &n, MAX_TARGETS);
                }
                free(_args[bi].wb.buf);
                free(l2[li+bi]);
            }
            li += batch;
        }
        /* libera URLs restantes não processadas */
        for (int li2 = li; li2 < l2n; li2++) free(l2[li2]);
    }
    #undef L2_BATCH
    #undef MAX_L2
    #undef MAX_TARGETS

    if (n==0) { free(targets); return NULL; }
    *out_count=n;
    return targets;
}

static void free_scan_targets(char **t, int n) {
    if (!t) return;
    for (int i=0;i<n;i++) free(t[i]);
    free(t);
}

