#define PARAMS_WORDLIST_COUNT 72

/* Log global de vulnerabilidades — acumulado entre chamadas */
static FILE *g_vuln_log = NULL;
static void elliot_log_open(void) {
    if(g_vuln_log) return;
    const char *home=getenv("HOME");
    if(!home) home="/data/data/com.termux/files/home";
    char logdir[512]; snprintf(logdir,sizeof(logdir),"%s/.elliot_logs",home);
    mkdir(logdir,0755);
    char logpath[512]; snprintf(logpath,sizeof(logpath),"%s/vulns.txt",logdir);
    g_vuln_log=fopen(logpath,"a");
}
static void elliot_log(const char *type, const char *url, const char *detail) {
    elliot_log_open();
    if(!g_vuln_log) return;
    time_t t=time(NULL); struct tm *tm=localtime(&t);
    char ts[32]={0}; strftime(ts,sizeof(ts),"%Y-%m-%d %H:%M:%S",tm);
    fprintf(g_vuln_log,"[%s] [%s] %s | %s\n",ts,type,url,detail?detail:"");
    fflush(g_vuln_log);
}

/* Faz request com retry inteligente (2 tentativas com delay) */
static int params_fetch(CURL *ch, const char *url, CurlBuf *cb, long *code, int timeout) {
    for(int attempt=0;attempt<2;attempt++) {
        cb->size=0; if(cb->data) cb->data[0]='\0';
        curl_easy_reset(ch);
        curl_easy_setopt(ch,CURLOPT_URL,url);
        curl_easy_setopt(ch,CURLOPT_WRITEFUNCTION,curl_write_cb);
        curl_easy_setopt(ch,CURLOPT_WRITEDATA,cb);
        curl_easy_setopt(ch,CURLOPT_TIMEOUT,(long)timeout);
        curl_easy_setopt(ch,CURLOPT_CONNECTTIMEOUT,5L);
        curl_easy_setopt(ch,CURLOPT_SSL_VERIFYPEER,0L);
        curl_easy_setopt(ch,CURLOPT_FOLLOWLOCATION,1L);
        curl_easy_setopt(ch,CURLOPT_USERAGENT,rand_ua());
        CURLcode rc=curl_easy_perform(ch);
        curl_easy_getinfo(ch,CURLINFO_RESPONSE_CODE,code);
        if(rc==CURLE_OK && *code>0 && *code!=429) return 1;
        /* Retry: 429=rate limit espera mais, outros erros espera menos */
        int wait = (*code==429) ? 3 : 1;
        sleep(wait);
    }
    return 0;
}

static int l_mod_params(lua_State *L) {
    const char *raw_url = luaL_checkstring(L, 1);
    const char *wl_file = luaL_optstring(L, 2, NULL);
    /* Opção: chain=true roda nosql automaticamente nos params encontrados */
    int do_chain = 0;
    if(lua_gettop(L)>=3 && lua_isboolean(L,3)) do_chain=lua_toboolean(L,3);

    /* Extrai base URL */
    char base[512]={0};
    const char *qm=strchr(raw_url,'?');
    size_t blen_base=qm?(size_t)(qm-raw_url):strlen(raw_url);
    if(blen_base<sizeof(base)){memcpy(base,raw_url,blen_base);base[blen_base]='\0';}
    else snprintf(base,sizeof(base),"%s",raw_url);
    size_t bl=strlen(base); while(bl>8&&base[bl-1]=='/') base[--bl]='\0';

    /* Carrega wordlist */
    char **custom_wl=NULL; int custom_n=0;
    if(wl_file) custom_wl=load_payloads_file(wl_file,&custom_n);
    const char **wl=(const char**)g_params_wordlist;
    int wl_n=PARAMS_WORDLIST_COUNT;
    if(custom_wl&&custom_n>0){wl=(const char**)custom_wl;wl_n=custom_n;}

    /* Filtra ruído da wordlist */
    int skip_count=0;
    for(int i=0;i<wl_n&&wl[i];i++) {
        for(int n=0;g_params_noise[n];n++)
            if(strcasecmp(wl[i],g_params_noise[n])==0){skip_count++;break;}
    }

    printf("\n\033[1;35m╔══════════════════════════════════════════════════════════════╗\033[0m\n");
    printf("\033[1;35m║  mod.params — Parameter Discovery v2                         ║\033[0m\n");
    printf("\033[1;35m╚══════════════════════════════════════════════════════════════╝\033[0m\n\n");
    printf("\033[1;33m[*]\033[0m Target  : %s\n", base);
    printf("\033[1;33m[*]\033[0m Params  : %d (-%d ruído)\n", wl_n, skip_count);
    if(do_chain) printf("\033[1;33m[*]\033[0m Chain   : NoSQL automático nos params encontrados\n");
    printf("\033[0;90m[*] Log   : ~/.elliot_logs/vulns.txt\033[0m\n\n");

    CURL *ch=curl_easy_init();
    if(!ch){lua_pushinteger(L,0);return 1;}

    /* Baseline com retry */
    CurlBuf cb_base={NULL,0}; cb_base.data=malloc(65536); if(cb_base.data) cb_base.data[0]='\0';
    long base_code=0;
    params_fetch(ch,base,&cb_base,&base_code,8);
    size_t base_sz=cb_base.size;
    free(cb_base.data);

    const char *probe="elliot7x9z";
    int found=0; int critical=0;

    /* Arrays para guardar params encontrados (para chain) */
    char found_params[64][64]={0}; int found_n=0;

    for(int i=0;i<wl_n&&wl[i];i++) {
        /* Filtra ruído */
        int is_noise=0;
        for(int n=0;g_params_noise[n];n++)
            if(strcasecmp(wl[i],g_params_noise[n])==0){is_noise=1;break;}
        if(is_noise) continue;

        char url[1024]; snprintf(url,sizeof(url),"%s?%s=%s",base,wl[i],probe);
        CurlBuf cb={NULL,0}; cb.data=malloc(32768); if(cb.data) cb.data[0]='\0';
        long code=0;
        if(!params_fetch(ch,url,&cb,&code,8)){free(cb.data);continue;}

        if(code==404||code==410){free(cb.data);continue;}

        /* ── Score ── */
        int score=0;
        int reflected   = (cb.data&&strstr(cb.data,probe))?1:0;
        long diff=(long)cb.size-(long)base_sz; if(diff<0)diff=-diff;
        int size_diff   = (diff>100)?1:0;
        int code_change = (code!=base_code&&base_code>0&&code!=400)?1:0;
        int interesting = (code==200||code==201||code==500)?1:0;

        if(reflected)   score+=3;
        if(code_change) score+=2;
        if(size_diff&&interesting) score+=1;

        if(score==0){free(cb.data);continue;}

        /* ── Classifica por score ── */
        const char *level_color, *level_label;
        if(score>=5)      {level_color="\033[1;31m";level_label="HIGH  ";}
        else if(score>=3) {level_color="\033[1;33m";level_label="MEDIUM";}
        else              {level_color="\033[0;33m"; level_label="LOW   ";}

        /* Razões detectadas */
        char reasons[64]={0}; int ri=0;
        if(reflected)   ri+=snprintf(reasons+ri,sizeof(reasons)-ri,"reflected ");
        if(code_change) ri+=snprintf(reasons+ri,sizeof(reasons)-ri,"code:%ld→%ld ",base_code,code);
        if(size_diff)   ri+=snprintf(reasons+ri,sizeof(reasons)-ri,"size+%ld ",diff);

        printf("%s  [%s] %-20s score:%-2d HTTP %ld  %s\033[0m\n",
               level_color,level_label,wl[i],score,code,reasons);
        printf("\033[0;90m            %s?%s=\033[0m\n",base,wl[i]);

        /* Log */
        char log_detail[256]={0};
        snprintf(log_detail,sizeof(log_detail),"param=%s score=%d reasons=%s",wl[i],score,reasons);
        elliot_log("PARAM",base,log_detail);

        /* Guarda para chain */
        if(found_n<64) strncpy(found_params[found_n++],wl[i],63);
        found++;
        free(cb.data);
    }

    /* ── Chain: testa NoSQL nos params encontrados ── */
    if(do_chain && found_n>0) {
        printf("\n\033[1;35m[chain]\033[0m Testando NoSQL nos %d param(s) encontrado(s)...\n\n", found_n);
        for(int pi=0;pi<found_n;pi++) {
            /* Testa $ne=1 como probe rápido */
            char url_nosql[1024];
            snprintf(url_nosql,sizeof(url_nosql),"%s?%s[$ne]=1",base,found_params[pi]);
            CurlBuf cb_ns={NULL,0}; cb_ns.data=malloc(32768); if(cb_ns.data) cb_ns.data[0]='\0';
            long code_ns=0;
            if(params_fetch(ch,url_nosql,&cb_ns,&code_ns,8)) {
                /* Compara com baseline do param normal */
                char url_normal[1024];
                snprintf(url_normal,sizeof(url_normal),"%s?%s=1",base,found_params[pi]);
                CurlBuf cb_n2={NULL,0}; cb_n2.data=malloc(32768); if(cb_n2.data) cb_n2.data[0]='\0';
                long code_n2=0;
                params_fetch(ch,url_normal,&cb_n2,&code_n2,8);

                /* Detecta se NoSQL mudou a resposta significativamente */
                long ns_diff=(long)cb_ns.size-(long)cb_n2.size; if(ns_diff<0)ns_diff=-ns_diff;
                int nosql_hit = (ns_diff>200||(code_ns!=code_n2&&code_ns==200&&code_n2!=200));

                if(nosql_hit) {
                    critical++;
                    printf("\033[1;31m  ☠ [CRITICAL] NoSQL injection confirmado!\033[0m\n");
                    printf("\033[1;31m    param=%s  diff=%ld bytes  HTTP %ld→%ld\033[0m\n",
                           found_params[pi],ns_diff,code_n2,code_ns);
                    printf("\033[0;90m    payload: %s?%s[$ne]=1\033[0m\n",base,found_params[pi]);
                    char crit_detail[256]={0};
                    snprintf(crit_detail,sizeof(crit_detail),
                        "CRITICAL NoSQL: param=%s diff=%ld",found_params[pi],ns_diff);
                    elliot_log("CRITICAL",base,crit_detail);
                }
                free(cb_n2.data);
            }
            free(cb_ns.data);
        }
    }

    curl_easy_cleanup(ch);
    if(custom_wl){for(int i=0;i<custom_n;i++)free(custom_wl[i]);free(custom_wl);}

    /* Sumário final */
    printf("\n\033[1;35m── Sumário ────────────────────────────────────────────────────\033[0m\n");
    if(found==0) {
        printf("\033[1;32m  ✓ Nenhum parâmetro oculto detectado\033[0m\n");
    } else {
        printf("  Parâmetros : %d encontrado(s)\n", found);
        if(critical>0)
            printf("\033[1;31m  ☠ CRÍTICO  : %d NoSQL injection confirmado(s)!\033[0m\n",critical);
        printf("\033[0;90m  Log salvo  : ~/.elliot_logs/vulns.txt\033[0m\n");
    }
    printf("\n");

    /* Retorna: count (int), critical (int), params (table) */
    /* Também imprime sumário final antes de retornar */
    if(found>0){
        printf("\n\033[1;32m[+] Parâmetros encontrados:\033[0m\n");
        for(int i=0;i<found_n;i++) printf("    - %s\n",found_params[i]);
        printf("  Total: %d\n",found);
        if(critical>0) printf("\033[1;31m  ☠ CRÍTICO: %d NoSQL injection confirmado(s)!\033[0m\n",critical);
    }
    /* Retorna 3 valores: count, critical, table_of_params */
    lua_pushinteger(L,found);
    lua_pushinteger(L,critical);
    lua_newtable(L);
    for(int i=0;i<found_n;i++){lua_pushstring(L,found_params[i]);lua_rawseti(L,-2,i+1);}
    return 3;
}


