    printf("    Detecta: /etc/passwd (root:x:0:0:), win.ini, /proc/version+gcc,\n");
    printf("             php://filter (resposta base64 pura >85%%).\n");
    printf("    url          : URL com '?param=' ou URL base para spider automático\n");
    printf("    payload_file : (opt) .txt com payloads\n");
    printf("    n_endpoints  : (opt) quantos endpoints testar. 0=todos. Padrão=1\n");
    printf("    Retorna      : número de inclusões confirmadas\n\n");

    printf("  \033[1;33mmod.ssrf\033[0m(url [, payload_file [, n_endpoints]])\n");
