    printf("    url     : URL completa\n");
    printf("    Retorna : número de segredos encontrados\n\n");

    printf("  \033[1;33mmod.git\033[0m(url)\n");
    printf("    Detecta repositório .git exposto publicamente.\n");
    printf("    Testa HEAD, config, logs, refs. Extrai remote URL se exposto.\n");
    printf("    url     : URL base  ex: 'http://site.com'\n");
    printf("    Retorna : número de arquivos .git acessíveis\n\n");

    printf("  \033[1;33mmod.open_redirect\033[0m(url)\n");
    printf("    Testa open redirect em parâmetros comuns (redirect, url, next, goto...).\n");
