    printf("    max_pages : (opt) limite de páginas — padrão 30\n");
    printf("    Retorna   : tabela Lua com URLs encontradas\n\n");

    printf("  \033[1;33mmod.recon\033[0m(host)\n");
    printf("    Reconhecimento passivo: DNS, WHOIS, robots.txt, tecnologias.\n");
    printf("    host    : domínio ou IP  ex: 'exemplo.com'\n");
    printf("    Retorna : 0\n\n");

    printf("  \033[1;33mmod.info\033[0m(url)\n");
