    printf("    url     : URL completa  ex: 'http://site.com/'\n");
    printf("    Retorna : 0\n\n");

    printf("  \033[1;33mmod.headers\033[0m(url)\n");
    printf("    Análise de segurança de headers HTTP:\n");
