    printf("    url     : URL ou ws:// ou wss://  ex: 'http://site.com'\n");
    printf("    Retorna : número de endpoints WS encontrados\n\n");

    /* ── IA ── */
    printf("  \033[1;36m── IA PAYLOAD GENERATOR ───────────────────────────────────────\033[0m\n\n");

    printf("  \033[1;33mmod.payload\033[0m(tipo, n [, contexto])\n");
    printf("    Gera payloads customizados via IA e salva em arquivo .txt.\n");
