    printf("  \033[1;33mmod.chain\033[0m(url [, opts])\n");
    printf("    Pipeline automático completo: spider → classifica endpoints → aplica\n");
    printf("    o scanner certo em cada categoria automaticamente.\n");
    printf("    Fases: params→XSS/SQLi/RCE/LFI  inputs→XSS/SQLi  api→params/nosql\n");
    printf("           auth→SQLi/CSRF  idor→IDOR  sensitive→secrets/backup  headers\n");
    printf("    url  : URL base  ex: 'http://site.com/'\n");
    printf("    opts : tabela opcional de configurações:\n");
    printf("           { pages=30, xss=true, sqli=true, lfi=true, rce=true,\n");
    printf("             csrf=true, headers=true, params=true, api=true,\n");
    printf("             auth=true, backup=true, secrets=true, idor=true,\n");
    printf("             nosql=true, crlf=true }\n");
    printf("    Retorna : total de vulnerabilidades encontradas\n\n");
    printf("  \033[0;90m  Exemplos:\033[0m\n");
    printf("    mod.chain('http://site.com/')                    -- tudo ativo\n");
    printf("    mod.chain('http://site.com/', {pages=50})        -- mais páginas\n");
    printf("    mod.chain('http://site.com/', {lfi=false, rce=false}) -- sem LFI/RCE\n\n");

    printf("  \033[1;33mmod.help\033[0m()\n");
    printf("    Esta ajuda.\n\n");

    /* ── EXEMPLOS ── */
    printf("  \033[1;36m── EXEMPLOS ───────────────────────────────────────────────────\033[0m\n\n");
    printf("  \033[0;90m-- pipeline completo automático (mod.chain)\033[0m\n");
    printf("  mod.chain('http://site.com/')                        -- tudo de uma vez\n");
    printf("  mod.chain('http://site.com/', {pages=50, lfi=false}) -- sem LFI\n\n");
    printf("  \033[0;90m-- scan básico\033[0m\n");
    printf("  mod.recon('exemplo.com')\n");
    printf("  mod.scan('exemplo.com', 1, 65535)\n\n");
    printf("  \033[0;90m-- spider automático (testa só o primeiro endpoint)\033[0m\n");
    printf("  mod.xss('http://site.com/')\n");
    printf("  mod.sqli('http://site.com/')\n\n");
    printf("  \033[0;90m-- spider automático testando mais endpoints\033[0m\n");
    printf("  mod.lfi('http://site.com/', nil, 3)   -- primeiros 3 endpoints\n");
    printf("  mod.rce('http://site.com/', nil, 0)   -- todos os endpoints\n\n");
    printf("  \033[0;90m-- parâmetro direto (sem spider)\033[0m\n");
    printf("  mod.sqli('http://site.com/item?id=')\n");
    printf("  mod.lfi('http://site.com/page?f=')\n");
    printf("  mod.ssrf('http://site.com/fetch?url=')\n\n");
    printf("  \033[0;90m-- auth\033[0m\n");
    printf("  mod.auth('http://site.com/login')                      -- auto\n");
    printf("  mod.auth('http://site.com/login', 'admin')             -- usuario fixo\n");
    printf("  mod.auth('http://site.com/login', nil, '/sdcard/w.txt') -- wordlist\n\n");
    printf("  \033[0;90m-- payloads IA + uso\033[0m\n");
    printf("  local f = mod.payload('ssti', 100, 'Jinja2 Flask')\n");
    printf("  mod.ssti('http://site.com/render?tpl=', f)\n\n");
    printf("  \033[0;90m-- spider manual\033[0m\n");
    printf("  local urls = mod.spider('http://site.com/', 50)\n");
    printf("  for i,u in ipairs(urls) do print(i, u) end\n\n");
    printf("  \033[1;31m⚠  Use apenas em targets autorizados (DVWA, HackTheBox, labs, pent.*)\033[0m\n\n");
    return 0;
}

