/* ── Helpers HTTP ────────────────────────────────────────────────────────── */
static void pent_send(int fd, int code, const char *ctype,
                      const char *body, size_t blen,
                      const char *extra_hdrs) {
    char hdr[512];
    const char *status =
        code==200?"OK":code==301?"Moved Permanently":
        code==401?"Unauthorized":code==403?"Forbidden":
        code==404?"Not Found":"Internal Server Error";
    int hlen = snprintf(hdr, sizeof(hdr),
        "HTTP/1.1 %d %s\r\n"
        "Content-Type: %s\r\n"
        "Content-Length: %zu\r\n"
        "X-Powered-By: PHP/5.6.0\r\n"
        "Server: Apache/2.2.14\r\n"
        "%s"
        "Connection: close\r\n\r\n",
        code, status, ctype, blen,
        extra_hdrs ? extra_hdrs : "");
    send(fd, hdr, hlen, MSG_NOSIGNAL);
    if (body && blen > 0) send(fd, body, blen, MSG_NOSIGNAL);
}

static void pent_urldec(const char *src, char *dst, size_t dsz) {
    size_t di = 0;
    for (size_t i = 0; src[i] && di < dsz-1; i++) {
        if (src[i]=='%' && src[i+1] && src[i+2]) {
            char hex[3] = {src[i+1], src[i+2], 0};
            dst[di++] = (char)strtol(hex, NULL, 16);
            i += 2;
        } else if (src[i]=='+') {
            dst[di++] = ' ';
        } else {
            dst[di++] = src[i];
        }
    }
    dst[di] = '\0';
}

/* Extrai valor de query string: ?key=value */
static void pent_qparam(const char *qs, const char *key,
                        char *out, size_t outsz) {
    out[0] = '\0';
    if (!qs) return;
    size_t klen = strlen(key);
    const char *p = qs;
    while (*p) {
        if (strncmp(p, key, klen)==0 && p[klen]=='=') {
            p += klen + 1;
            size_t i = 0;
            while (*p && *p!='&' && i < outsz-1) out[i++] = *p++;
            out[i] = '\0';
            pent_urldec(out, out, outsz);
            return;
        }
        while (*p && *p!='&') p++;
        if (*p=='&') p++;
    }
}

/* HTML escape simples */
static void pent_escape(const char *src, char *dst, size_t dsz) {
    size_t di = 0;
    for (size_t i = 0; src[i] && di < dsz-4; i++) {
        if      (src[i]=='<') { memcpy(dst+di,"&lt;",4);  di+=4; }
        else if (src[i]=='>') { memcpy(dst+di,"&gt;",4);  di+=4; }
        else if (src[i]=='&') { memcpy(dst+di,"&amp;",5); di+=5; }
        else dst[di++] = src[i];
    }
    dst[di] = '\0';
}

