/* Helpers extras                                                               */
/* ─────────────────────────────────────────────────────────────────────────── */

/* Extrai body de requisição POST (após \r\n\r\n) */
static const char *pent_get_body(const char *req) {
    const char *p = strstr(req, "\r\n\r\n");
    return p ? p + 4 : NULL;
}

/* Extrai valor de um campo no body POST (key=value&...) — reusa pent_qparam */
static void pent_body_param(const char *body, const char *key,
                            char *out, size_t outsz) {
    if (!body) { out[0]='\0'; return; }
    pent_qparam(body, key, out, outsz);
}

/* Verifica se header X contém valor Y (case-insensitive simples) */
static int pent_has_header(const char *req, const char *hdr, const char *val) {
    char *p = strcasestr((char*)req, hdr);
    if (!p) return 0;
    p += strlen(hdr);
    while (*p == ' ' || *p == ':') p++;
    return strncasecmp(p, val, strlen(val)) == 0;
}

/* Extrai valor de um header da request */
static void pent_get_header(const char *req, const char *hdr,
                            char *out, size_t outsz) {
    out[0] = '\0';
    char *p = strcasestr((char*)req, hdr);
    if (!p) return;
    p += strlen(hdr);
    while (*p == ' ' || *p == ':') p++;
    size_t i = 0;
    while (*p && *p != '\r' && *p != '\n' && i < outsz-1) out[i++] = *p++;
    out[i] = '\0';
}

/* Base64 decode simples (para JWT) */
static int pent_b64decode(const char *in, char *out, size_t outsz) {
    static const char t[] =
        "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    size_t i=0, oi=0;
    unsigned int acc=0; int bits=0;
    for (; in[i] && in[i]!='=' && oi<outsz-1; i++) {
        char *p = strchr(t, in[i]);
        if (!p) { /* URL-safe: troca - e _ */
            if (in[i]=='-') p = strchr(t, '+');
            else if (in[i]=='_') p = strchr(t, '/');
            if (!p) continue;
        }
        acc = (acc << 6) | (unsigned int)(p - t);
        bits += 6;
        if (bits >= 8) { bits -= 8; out[oi++] = (char)((acc >> bits) & 0xFF); }
    }
    out[oi] = '\0';
    return (int)oi;
}

/* Verifica JWT vulnerável: aceita alg=none e secret="secret" */
/* Retorna 1=válido(none), 2=válido(HS256 weak), 0=inválido */
static int pent_jwt_check(const char *token, char *payload_out, size_t psz) {
    if (!token || !*token) return 0;
    /* split em '.' */
    char tmp[1024]; strncpy(tmp, token, 1023);
    char *h = tmp;
    char *p = strchr(h, '.');   if (!p) return 0; *p++='\0';
    char *s = strchr(p, '.');   if (!s) return 0; *s++='\0';

    char hdr[256]={0}, pay[512]={0};
    pent_b64decode(h, hdr, sizeof(hdr));
    pent_b64decode(p, pay, sizeof(pay));
    if (payload_out) { strncpy(payload_out, pay, psz-1); payload_out[psz-1]='\0'; }

    /* none attack */
    if (strstr(hdr,"\"none\"") || strstr(hdr,"\"NONE\"") ||
        strcasestr(hdr,"alg\":\"none")) return 1;

    /* weak secret: aceita qualquer token com sig == "secret" */
    if (strcmp(s,"secret")==0 || strcmp(s,"dGVzdA")==0) return 2;

    return 0;
}

/* ─────────────────────────────────────────────────────────────────────────── */
/* HANDLER PRINCIPAL                                                            */
/* ─────────────────────────────────────────────────────────────────────────── */
static void pent_handle_conn(int cfd, const char *level) {
    char req[16384] = {0};
    ssize_t n = recv(cfd, req, sizeof(req)-1, 0);
    if (n <= 0) { close(cfd); return; }

    char method[8]={0}, path[512]={0};
    sscanf(req, "%7s %511s", method, path);
    char *qs = strchr(path, '?');
    if (qs) { *qs = '\0'; qs++; }

    int is_med  = (strcmp(level,"med")==0);
    int is_hard = (strcmp(level,"hard")==0);
    int is_post = (strcmp(method,"POST")==0);
    const char *body_raw = is_post ? pent_get_body(req) : NULL;

    char body[65536];

    /* ================================================================
     * / — HOME
     * ================================================================ */
    if (strcmp(path,"/")==0) {
        snprintf(body, sizeof(body),
            "<h2>PentLab [%s] — ElliotOS</h2>"
            "<p class=warn>%s</p>"
            "<div class=box>"
            "<b>Vulnerabilidades disponíveis:</b><br><br>"
            "🔴 <b>Injeções:</b> SQLi · XSS Reflected · XSS Stored · DOM XSS · "
            "SSTI · RCE · XXE · Path Traversal · LFI<br>"
            "🟠 <b>Auth/Session:</b> Auth Bypass · IDOR · JWT None Attack · "
            "JWT Weak Secret · Broken Access Control · Insecure Reset<br>"
            "🟡 <b>Config:</b> CORS · CSRF · Missing Headers · Info Disclosure · "
            "Backup Exposto · Debug Endpoint<br>"
            "🔵 <b>Outros:</b> File Upload Bypass · SSRF · Mass Assignment · "
            "Insecure Deserialization · Sem Rate Limiting<br>"
            "</div>"
            "<p><small>Use <code>ms --scan-all http://127.0.0.1:808%s/</code> para varrer tudo.</small></p>",
            level,
            is_hard ? "Nível DIFÍCIL — filtros ativos, bypasses necessários." :
            is_med  ? "Nível MÉDIO — algumas proteções, mas bypassáveis." :
                      "Nível FÁCIL — sem proteção nenhuma. Vai fundo!",
            is_hard ? "3" : is_med ? "2" : "1"
        );
        /* VULNERABILIDADE: sem security headers */
        pent_send_html(cfd, 200, body, NULL);

    /* ================================================================
     * /xss — XSS Refletido
     * ================================================================ */
    } else if (strcmp(path,"/xss")==0) {
        char msg[512]={0};
        pent_qparam(qs, "msg", msg, sizeof(msg));
        if (msg[0]) {
            if (is_hard) {
                char filtered[512]={0}; const char *pp=msg; int fi=0;
                while (*pp && fi<510) {
                    if (strncasecmp(pp,"<script",7)==0){pp+=7;continue;}
                    if (strncasecmp(pp,"</script>",9)==0){pp+=9;continue;}
                    if (strncasecmp(pp,"onerror",7)==0||
                        strncasecmp(pp,"onload",6)==0||
                        strncasecmp(pp,"onclick",7)==0)
                        { while(*pp&&*pp!=' '&&*pp!='>'&&*pp!='"') pp++; continue; }
                    filtered[fi++]=*pp++;
                }
                /* ainda vulnerável via SVG/data URI */
                snprintf(body,sizeof(body),
                    "<h3>XSS Refletido <span class=vuln-tag>HARD — filtra script+on*</span></h3>"
                    "<p>%s</p>"
                    "<form><input name=msg placeholder='payload'><button>Enviar</button></form>"
                    "<p class=warn>Dica: tente &lt;svg onmouseover=alert(1)&gt; ou "
                    "&lt;img src=x onerror=alert(1)&gt; com encoding</p>", filtered);
            } else if (is_med) {
                char filtered[1024]={0}; int fi=0;
                for (int ci=0; msg[ci]&&fi<1020; ci++) {
                    if (msg[ci]=='<') { filtered[fi++]='<'; }
                    else filtered[fi++]=msg[ci];
                }
                snprintf(body,sizeof(body),
                    "<h3>XSS Refletido <span class=vuln-tag>MED — filtra &lt; só</span></h3>"
                    "<p>%s</p>"
                    "<form><input name=msg><button>Enviar</button></form>"
                    "<p class=warn>Dica: tente \" onerror=alert(1) x=\"</p>", filtered);
            } else {
                /* easy: sem escape */
                snprintf(body,sizeof(body),
                    "<h3>XSS Refletido <span class=vuln-tag>EASY — sem escape</span></h3>"
                    "<p>%s</p>"
                    "<form><input name=msg><button>Enviar</button></form>", msg);
            }
        } else {
            snprintf(body,sizeof(body),
                "<h3>XSS Refletido</h3>"
                "<form>Mensagem: <input name=msg placeholder='&lt;script&gt;alert(1)&lt;/script&gt;'>"
                "<button>Enviar</button></form>");
        }
        pent_send_html(cfd,200,body,NULL);

    /* ================================================================
     * /comment — XSS STORED
     * ================================================================ */
    } else if (strcmp(path,"/comment")==0) {
        if (is_post && body_raw) {
            char comment[512]={0};
            pent_body_param(body_raw,"text",comment,sizeof(comment));
            if (comment[0]) {
                pthread_mutex_lock(&g_comment_mu);
                if (g_comment_count < MAX_COMMENTS) {
                    /* easy: armazena sem escape nenhum */
                    strncpy(g_comments[g_comment_count], comment, 511);
                    g_comment_count++;
                }
                pthread_mutex_unlock(&g_comment_mu);
            }
        }
        /* monta lista de comentários — sem escape = XSS Stored */
        char list[32768]={0};
        pthread_mutex_lock(&g_comment_mu);
        for (int i=0; i<g_comment_count; i++) {
            char row[600];
            if (is_hard) {
                /* hard: escapa < > mas não atributos */
                char esc[512]; pent_escape(g_comments[i],esc,sizeof(esc));
                snprintf(row,sizeof(row),"<div class=box>%s</div>", esc);
            } else {
                /* easy/med: sem escape = stored XSS */
                snprintf(row,sizeof(row),"<div class=box>%s</div>", g_comments[i]);
            }
            strncat(list,row,sizeof(list)-strlen(list)-1);
        }
        pthread_mutex_unlock(&g_comment_mu);
        snprintf(body,sizeof(body),
            "<h3>XSS Stored <span class=vuln-tag>comentários sem sanitização</span></h3>"
            "<form method=POST action=/comment>"
            "Comentário: <input name=text size=40>"
            "<button>Postar</button></form><hr>%s",
            list[0]?list:"<p class=warn>Nenhum comentário ainda.</p>");
        pent_send_html(cfd,200,body,NULL);

    /* ================================================================
     * /dom — DOM XSS (JavaScript puro)
     * ================================================================ */
    } else if (strcmp(path,"/dom")==0) {
        /* vulnerabilidade está no JS do cliente — não há sanitização server-side */
        snprintf(body,sizeof(body),
            "<h3>DOM XSS <span class=vuln-tag>innerHTML sem sanitização</span></h3>"
            "<input id=q placeholder='seu nome' size=30>"
            "<button onclick=\"document.getElementById('out').innerHTML="
            "'Olá, '+document.getElementById('q').value\">Dizer Olá</button>"
            "<div id=out class=box></div>"
            "<p class=warn>Dica: insira <code>&lt;img src=x onerror=alert(1)&gt;</code> no campo</p>"
            "<hr><h4>Via URL hash:</h4>"
            "<p>Tente: <code>/dom#&lt;img src=x onerror=alert(document.cookie)&gt;</code></p>"
            "<script>"
            "if(location.hash){"
            "  document.getElementById('out').innerHTML=decodeURIComponent(location.hash.slice(1));"
            "}"
            "</script>");
        pent_send_html(cfd,200,body,NULL);

    /* ================================================================
     * /search — SQLi
     * ================================================================ */
    } else if (strcmp(path,"/search")==0) {
        char name[256]={0}; pent_qparam(qs,"name",name,sizeof(name));
        if (name[0] && g_pent_db) {
            int blocked=0;
            if (is_med||is_hard) {
                if (strchr(name,'\'') || strchr(name,'"')) blocked=1;
            }
            if (is_hard) {
                char upper[256]={0};
                for(int ci=0;name[ci]&&ci<255;ci++)
                    upper[ci]=toupper((unsigned char)name[ci]);
                if (strstr(upper,"OR ") || strstr(upper," OR") ||
                    strstr(upper,"UNION") || strstr(upper,"--") ||
                    strstr(upper,"DROP") || strstr(upper,"SELECT"))
                    blocked=1;
            }
            if (blocked) {
                snprintf(body,sizeof(body),
                    "<p class=err>WAF: entrada bloqueada.</p>"
                    "<p class=warn>Dica: tente 1/**/OR/**/1=1 ou usar hex encoding</p>");
                pent_send_html(cfd,403,body,NULL); return;
            }
            char sql[512];
            snprintf(sql,sizeof(sql),
                "SELECT id,name,role FROM users WHERE name='%s'", name);
            char result[8192]={0};
            pthread_mutex_lock(&g_pent_db_mu);
            sqlite3_stmt *stmt=NULL;
            int rc=sqlite3_prepare_v2(g_pent_db,sql,-1,&stmt,NULL);
            if (rc==SQLITE_OK) {
                while (sqlite3_step(stmt)==SQLITE_ROW) {
                    char row[256];
                    snprintf(row,sizeof(row),
                        "<div class=box>ID: <b>%d</b> | Nome: <b>%s</b> | Role: <b>%s</b></div>",
                        sqlite3_column_int(stmt,0),
                        (const char*)sqlite3_column_text(stmt,1),
                        (const char*)sqlite3_column_text(stmt,2));
                    strncat(result,row,sizeof(result)-strlen(result)-1);
                }
                sqlite3_finalize(stmt);
            } else {
                snprintf(result,sizeof(result),
                    "<p class=err>DB Error: %s</p>", sqlite3_errmsg(g_pent_db));
            }
            pthread_mutex_unlock(&g_pent_db_mu);
            char esc[512]; pent_escape(name,esc,sizeof(esc));
            snprintf(body,sizeof(body),
                "<h3>SQLi — Busca por: %s</h3>"
                "<p class=warn>Query: SELECT id,name,role FROM users WHERE name='%s'</p>"
                "%s"
                "<form>Nome: <input name=name><button>Buscar</button></form>",
                esc, esc, result[0]?result:"<p>Nenhum resultado</p>");
        } else {
            snprintf(body,sizeof(body),
                "<h3>SQL Injection <span class=vuln-tag>query não parametrizada</span></h3>"
                "<form>Nome: <input name=name placeholder=\"' OR '1'='1\">"
                "<button>Buscar</button></form>"
                "<p class=warn>Tabelas: users(id,name,pass,role), notes(id,user_id,content)</p>");
        }
        pent_send_html(cfd,200,body,NULL);

    /* ================================================================
     * /login — SQLi Auth Bypass
     * ================================================================ */
    } else if (strcmp(path,"/login")==0) {
        char user[128]={0}, pw[128]={0};
        if (is_post && body_raw) {
            pent_body_param(body_raw,"user",user,sizeof(user));
            pent_body_param(body_raw,"pass",pw,sizeof(pw));
        } else {
            pent_qparam(qs,"user",user,sizeof(user));
            pent_qparam(qs,"pass",pw,sizeof(pw));
        }
        if (user[0] && g_pent_db) {
            char sql[512];
            snprintf(sql,sizeof(sql),
                "SELECT * FROM users WHERE name='%s' AND pass='%s'", user, pw);
            pthread_mutex_lock(&g_pent_db_mu);
            sqlite3_stmt *stmt=NULL; int found=0; char role[64]={0};
            if (sqlite3_prepare_v2(g_pent_db,sql,-1,&stmt,NULL)==SQLITE_OK) {
                if (sqlite3_step(stmt)==SQLITE_ROW) {
                    found=1;
                    strncpy(role,(const char*)sqlite3_column_text(stmt,3),63);
                }
                sqlite3_finalize(stmt);
            }
            pthread_mutex_unlock(&g_pent_db_mu);
            if (found)
                snprintf(body,sizeof(body),
                    "<div class=flag>✅ LOGIN OK! Role: %s<br>Flag: FLAG{sqli_auth_bypass}</div>",role);
            else
                snprintf(body,sizeof(body),
                    "<p class=err>Login falhou.</p>"
                    "<form method=POST action=/login>"
                    "User:<input name=user> Pass:<input name=pass type=password>"
                    "<button>Login</button></form>"
                    "<p class=warn>Dica: user=admin'--&amp;pass=qualquer</p>");
        } else {
            snprintf(body,sizeof(body),
                "<h3>Login <span class=vuln-tag>SQLi auth bypass</span></h3>"
                "<form method=POST action=/login>"
                "User: <input name=user placeholder=\"admin' --\"><br>"
                "Pass: <input name=pass type=password><br><br>"
                "<button>Login</button></form>");
        }
        pent_send_html(cfd,200,body,NULL);

    /* ================================================================
     * /exec — RCE
     * ================================================================ */
    } else if (strcmp(path,"/exec")==0) {
        char cmd[256]={0};
        pent_qparam(qs,"cmd",cmd,sizeof(cmd));
        if (cmd[0]) {
            int blocked=0;
            if (is_med) { if (strchr(cmd,';')||strchr(cmd,'&')) blocked=1; }
