            }
            char hdrs[640];
            snprintf(hdrs,sizeof(hdrs),"Location: %s\r\n",url);
            snprintf(body,sizeof(body),"<p>Redirecionando para: %s</p>",url);
            pent_send(cfd,301,"text/html",body,strlen(body),hdrs);
        } else {
            snprintf(body,sizeof(body),
                "<h3>Open Redirect <span class=vuln-tag>sem validação de destino</span></h3>"
                "<form>URL: <input name=url value='https://evil.com' size=40>"
                "<button>Redirecionar</button></form>"
                "<p class=warn>Tente: <code>//evil.com</code> · "
                "<code>/\\evil.com</code> · <code>javascript:alert(1)</code></p>");
            pent_send_html(cfd,200,body,NULL);
        }

    /* ================================================================
     * /cors — CORS misconfiguration
     * ================================================================ */
    } else if (strcmp(path,"/cors")==0) {
        char origin[256]={0};
        pent_get_header(req,"Origin",origin,sizeof(origin));
        /* VULNERABILIDADE: reflete qualquer Origin */
        char cors_hdrs[512];
        snprintf(cors_hdrs,sizeof(cors_hdrs),
            "Access-Control-Allow-Origin: %s\r\n"
            "Access-Control-Allow-Credentials: true\r\n",
            origin[0]?origin:"*");
        char json[256];
        snprintf(json,sizeof(json),
            "{\"secret\":\"s3cr3t_data\",\"flag\":\"FLAG{cors_misconfiguration}\","
            "\"origin_reflected\":\"%s\"}",
            origin[0]?origin:"none");
        pent_send(cfd,200,"application/json",json,strlen(json),cors_hdrs);

    /* ================================================================
     * /csrf — CSRF sem token
     * ================================================================ */
    } else if (strcmp(path,"/csrf")==0) {
        if (is_post && body_raw) {
            char email[128]={0};
            pent_body_param(body_raw,"email",email,sizeof(email));
            /* sem verificação de token CSRF, sem verificação de Referer */
            char esc[256]; pent_escape(email,esc,sizeof(esc));
            snprintf(body,sizeof(body),
                "<div class=flag>✅ Email alterado para: %s</div>"
                "<p class=warn>Não houve verificação de token CSRF!</p>"
                "<p>Flag: FLAG{csrf_no_token}</p>",esc);
        } else {
            snprintf(body,sizeof(body),
                "<h3>CSRF <span class=vuln-tag>sem token de proteção</span></h3>"
                "<form method=POST action=/csrf>"
                "Novo email: <input name=email value='hacker@evil.com'><br><br>"
                "<button>Alterar Email</button></form>"
                "<hr>"
                "<p class=warn>Crie um HTML externo que faz POST automático aqui.<br>"
                "Não há token CSRF nem verificação de Referer.</p>"
                "<details><summary>Payload CSRF</summary>"
                "<pre>&lt;form action='http://127.0.0.1:8081/csrf' method=POST&gt;\n"
                "  &lt;input name=email value='hacker@evil.com'&gt;\n"
                "  &lt;input type=submit&gt;\n"
                "&lt;/form&gt;\n"
                "&lt;script&gt;document.forms[0].submit()&lt;/script&gt;</pre>"
                "</details>");
        }
        pent_send_html(cfd,200,body,NULL);

    /* ================================================================
     * /jwt — JWT none attack + weak secret
     * ================================================================ */
    } else if (strcmp(path,"/jwt")==0) {
        char token[512]={0}; pent_qparam(qs,"token",token,sizeof(token));
        if (token[0]) {
            char payload[512]={0};
            int r=pent_jwt_check(token,payload,sizeof(payload));
            if (r==1)
                snprintf(body,sizeof(body),
                    "<div class=flag>✅ None Attack funcionou!<br>"
                    "Payload: %s<br>Flag: FLAG{jwt_none_attack}</div>",payload);
            else if (r==2)
                snprintf(body,sizeof(body),
                    "<div class=flag>✅ Weak Secret — assinatura aceita!<br>"
                    "Payload: %s<br>Flag: FLAG{jwt_weak_secret}</div>",payload);
            else
                snprintf(body,sizeof(body),
                    "<p class=err>Token inválido.</p>"
                    "<p class=warn>Dica: tente alg=none ou assine com 'secret'</p>");
        } else {
            snprintf(body,sizeof(body),
                "<h3>JWT <span class=vuln-tag>none attack + weak secret</span></h3>"
                "<form>Token: <input name=token size=60 "
                "value='eyJhbGciOiJub25lIiwidHlwIjoiSldUIn0"
                ".eyJ1c2VyIjoiYWRtaW4ifQ.'>"
                "<button>Verificar</button></form>"
                "<hr>"
                "<p class=warn><b>None attack:</b> mude alg para none e remova a assinatura<br>"
                "<b>Weak secret:</b> assine com secret='secret' e coloque sig='secret'</p>"
                "<details><summary>Tokens prontos para testar</summary>"
                "<pre>"
                "# None attack (alg=none):\n"
                "eyJhbGciOiJub25lIiwidHlwIjoiSldUIn0.eyJ1c2VyIjoiYWRtaW4ifQ.\n\n"
                "# Weak secret (sig=secret):\n"
                "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9"
                ".eyJ1c2VyIjoiYWRtaW4ifQ.secret"
                "</pre></details>");
        }
        pent_send_html(cfd,200,body,NULL);

    /* ================================================================
     * /xxe — XXE simulado
     * ================================================================ */
    } else if (strcmp(path,"/xxe")==0) {
        if (is_post && body_raw) {
            /* detecta entity expansion e file read simulado */
            char flag[256]={0};
            if (strstr(body_raw,"SYSTEM") || strstr(body_raw,"ENTITY")) {
                if (strstr(body_raw,"/etc/passwd")||strstr(body_raw,"/proc")) {
                    strncpy(flag,"<div class=flag>FLAG{xxe_file_read}</div>",255);
                } else {
                    strncpy(flag,"<div class=flag>FLAG{xxe_entity_detected}</div>",255);
                }
            }
            char esc[8192]; pent_escape(body_raw,esc,sizeof(esc));
            snprintf(body,sizeof(body),
                "<h3>XXE — XML recebido:</h3><pre>%s</pre>%s",esc,flag);
        } else {
            snprintf(body,sizeof(body),
                "<h3>XXE <span class=vuln-tag>XML parser sem proteção</span></h3>"
                "<form method=POST action=/xxe enctype='text/plain'>"
                "<textarea name=xml rows=8 cols=60>"
                "&lt;?xml version=\"1.0\"?&gt;\n"
                "&lt;!DOCTYPE foo [\n"
                "  &lt;!ENTITY xxe SYSTEM \"file:///etc/passwd\"&gt;\n"
                "]&gt;\n"
                "&lt;data&gt;&amp;xxe;&lt;/data&gt;"
                "</textarea><br><br>"
                "<button>Enviar XML</button></form>"
                "<p class=warn>O parser aceita ENTITY SYSTEM — tente ler arquivos locais</p>");
        }
        pent_send_html(cfd,200,body,NULL);

    /* ================================================================
     * /admin — Broken Access Control
     * ================================================================ */
    } else if (strcmp(path,"/admin")==0) {
        char role[64]={0}; pent_qparam(qs,"role",role,sizeof(role));
        char cookie[256]={0}; pent_get_header(req,"Cookie",cookie,sizeof(cookie));

        /* easy: só checa query param ?role=admin */
        /* med: checa cookie também */
        /* hard: checa header X-Admin-Key */
        int access=0;
        if (!is_med && !is_hard) {
            if (strcmp(role,"admin")==0) access=1;
        } else if (is_med) {
            if (strcmp(role,"admin")==0 && strstr(cookie,"session=admin")) access=1;
        } else {
            char xkey[64]={0}; pent_get_header(req,"X-Admin-Key",xkey,sizeof(xkey));
            if (strcmp(xkey,"elliotos-admin-2024")==0) access=1;
        }

        if (access) {
            snprintf(body,sizeof(body),
                "<div class=flag>✅ Acesso admin concedido!<br>"
                "Flag: FLAG{broken_access_control}</div>"
                "<div class=box>"
                "<b>Painel Admin:</b><br>"
                "Usuários: admin, alice, bob<br>"
                "Senhas: admin123, password, 123456<br>"
                "Segredo: %s"
                "</div>","s3cr3t_admin_password");
        } else {
            snprintf(body,sizeof(body),
                "<h3>Admin <span class=vuln-tag>Broken Access Control</span></h3>"
                "<p class=err>Acesso negado.</p>"
                "<p class=warn>[easy] Adicione <code>?role=admin</code> na URL<br>"
                "[med] Também precisa de cookie <code>session=admin</code><br>"
                "[hard] Precisa do header <code>X-Admin-Key: elliotos-admin-2024</code></p>"
                "<form>Role: <input name=role value=user>"
                "<button>Tentar</button></form>");
        }
        pent_send_html(cfd,200,body,NULL);

    /* ================================================================
     * /register — Mass Assignment
     * ================================================================ */
    } else if (strcmp(path,"/register")==0) {
        if (is_post && body_raw) {
            char user[64]={0}, pw[64]={0}, role[64]={0};
            pent_body_param(body_raw,"user",user,sizeof(user));
            pent_body_param(body_raw,"pass",pw,sizeof(pw));
            /* VULNERABILIDADE: aceita role do usuário sem validar */
            pent_body_param(body_raw,"role",role,sizeof(role));
            if (!role[0]) strncpy(role,"user",63);
            char esc_u[128]; pent_escape(user,esc_u,sizeof(esc_u));
            char esc_r[128]; pent_escape(role,esc_r,sizeof(esc_r));
            char flag[256]={0};
            if (strcmp(role,"admin")==0)
                strncpy(flag,"<div class=flag>FLAG{mass_assignment_privesc}</div>",255);
            snprintf(body,sizeof(body),
                "<div class=ok>✅ Registrado: %s com role: <b>%s</b></div>%s"
                "<p class=warn>O campo 'role' foi aceito direto do formulário!</p>",
                esc_u,esc_r,flag);
        } else {
            snprintf(body,sizeof(body),
                "<h3>Register <span class=vuln-tag>Mass Assignment</span></h3>"
                "<form method=POST action=/register>"
                "User: <input name=user><br>"
                "Pass: <input name=pass type=password><br>"
                "<!-- campo oculto que o servidor aceita: -->"
                "<input type=hidden name=role value=user><br><br>"
                "<button>Registrar</button></form>"
                "<p class=warn>Dica: inspecione o HTML — há um campo hidden 'role'.<br>"
                "Mude para <code>admin</code> antes de enviar!</p>");
        }
        pent_send_html(cfd,200,body,NULL);

    /* ================================================================
     * /reset — Insecure Password Reset
     * ================================================================ */
    } else if (strcmp(path,"/reset")==0) {
        char uid_s[32]={0}; pent_qparam(qs,"user",uid_s,sizeof(uid_s));
        char token_in[64]={0}; pent_qparam(qs,"token",token_in,sizeof(token_in));

        if (uid_s[0] && !token_in[0]) {
            /* gera token previsível: md5(userid+timestamp arredondado) */
            int uid=atoi(uid_s); if (uid<1||uid>3) uid=1;
            /* token super previsível: userid*1337 em hex */
            unsigned int tok_val = (unsigned int)(uid * 1337);
            snprintf(g_reset_tokens[uid-1],63,"%08x",tok_val);
            snprintf(body,sizeof(body),
                "<div class=ok>Token de reset enviado para o email do usuário %d</div>"
                "<p class=warn>Token 'enviado': <code>%s</code> (propositalmente exposto!)</p>"
                "<form>Token: <input name=token> User: <input name=user value=%d>"
                "<button>Resetar</button></form>",
                uid, g_reset_tokens[uid-1], uid);
        } else if (uid_s[0] && token_in[0]) {
            int uid=atoi(uid_s); if (uid<1||uid>3) uid=1;
            unsigned int expected = (unsigned int)(uid * 1337);
            char expected_s[32]; snprintf(expected_s,sizeof(expected_s),"%08x",expected);
            if (strcmp(token_in,expected_s)==0) {
                snprintf(body,sizeof(body),
                    "<div class=flag>✅ Reset autorizado! Usuário %d<br>"
                    "Flag: FLAG{insecure_reset_token}</div>"
                    "<form method=POST action=/login>"
                    "Nova senha: <input name=pass value=hacked123>"
                    "<input type=hidden name=user value=admin>"
                    "<button>Alterar</button></form>",uid);
            } else {
                snprintf(body,sizeof(body),
                    "<p class=err>Token inválido.</p>"
                    "<p class=warn>Dica: token = uid * 1337 em hex</p>");
            }
        } else {
            snprintf(body,sizeof(body),
                "<h3>Password Reset <span class=vuln-tag>token previsível</span></h3>"
                "<form>User ID: <input name=user type=number value=1>"
                "<button>Solicitar Reset</button></form>"
                "<p class=warn>O token é gerado com lógica previsível (uid*1337 em hex).<br>"
                "Após solicitar, adivinhe o token sem precisar do email!</p>");
        }
        pent_send_html(cfd,200,body,NULL);

    /* ================================================================
     * /debug — Info Disclosure
     * ================================================================ */
    } else if (strcmp(path,"/debug")==0) {
        /* VULNERABILIDADE: expõe variáveis de ambiente e configuração */
        char *home=getenv("HOME"); char *path_env=getenv("PATH");
        char *user_env=getenv("USER"); char *shell=getenv("SHELL");
        snprintf(body,sizeof(body),
            "<h3>Debug <span class=vuln-tag>info disclosure</span></h3>"
            "<div class=box>"
            "<b>Variáveis de ambiente:</b><br>"
            "HOME=%s<br>USER=%s<br>SHELL=%s<br>"
            "PATH=%s<br>"
            "</div>"
            "<div class=box>"
            "<b>Configuração do servidor:</b><br>"
            "PHP/5.6.0 (falso mas realista)<br>"
            "Apache/2.2.14<br>"
            "SQLite: %s<br>"
            "Flag: FLAG{debug_info_exposure}<br>"
            "</div>"
            "<div class=box>"
            "<b>Usuários no banco:</b><br>"
            "admin:admin123 · alice:password · bob:123456"
            "</div>",
            home?home:"?", user_env?user_env:"?",
            shell?shell:"?", path_env?path_env:"?",
            sqlite3_libversion());
        pent_send_html(cfd,200,body,NULL);

    /* ================================================================
     * /backup — Backup file exposto
     * ================================================================ */
    } else if (strcmp(path,"/backup")==0 ||
               strcmp(path,"/backup.sql")==0 ||
               strcmp(path,"/db.bak")==0 ||
               strcmp(path,"/config.php.bak")==0) {
        const char *backup_content =
            "-- PentLab Database Backup\n"
            "-- NUNCA exponha isso em produção!\n\n"
            "CREATE TABLE users(id INTEGER PRIMARY KEY, name TEXT, pass TEXT, role TEXT);\n"
            "INSERT INTO users VALUES(1,'admin','admin123','admin');\n"
            "INSERT INTO users VALUES(2,'alice','password','user');\n"
            "INSERT INTO users VALUES(3,'bob','123456','user');\n\n"
            "-- config.php\n"
            "-- DB_PASS=s3cr3t_db_password\n"
            "-- API_KEY=AIzaSyFAKE_KEY_FLAG{backup_exposed}\n"
            "-- SECRET=jwt_s3cr3t_key\n";
        /* sem autenticação, sem proteção */
        snprintf(body,sizeof(body),
            "<h3>Backup Exposto <span class=vuln-tag>arquivo sensível público</span></h3>"
            "<pre>%s</pre>"
            "<p class=warn>Arquivos como .bak .old .sql costumam ficar acessíveis!</p>",
            backup_content);
        pent_send_html(cfd,200,body,NULL);

    /* ================================================================
     * /headers — Missing security headers
     * ================================================================ */
    } else if (strcmp(path,"/headers")==0) {
        snprintf(body,sizeof(body),
            "<h3>Security Headers <span class=vuln-tag>ausentes propositalmente</span></h3>"
            "<p>Esta página não tem:</p>"
            "<div class=box>"
            "❌ Content-Security-Policy<br>"
            "❌ X-Frame-Options<br>"
            "❌ X-XSS-Protection<br>"
            "❌ Strict-Transport-Security<br>"
            "❌ X-Content-Type-Options<br>"
            "❌ Referrer-Policy<br>"
            "</div>"
            "<p class=warn>Teste com: <code>ms --headers http://127.0.0.1:8081/</code></p>"
            "<p>Flag: FLAG{missing_security_headers}</p>");
        /* propositalmente sem headers de segurança */
        pent_send_html(cfd,200,body,NULL);

    /* ================================================================
     * /ssrf — Server-Side Request Forgery
     * ================================================================ */
    } else if (strcmp(path,"/ssrf")==0) {
        char url[512]={0}; pent_qparam(qs,"url",url,sizeof(url));
        if (url[0]) {
            int blocked=0;
            if (is_hard) {
                /* hard: bloqueia 169.254 (AWS metadata) e endereços locais óbvios */
                if (strstr(url,"169.254")||strstr(url,"metadata")) blocked=1;
            }
            if (blocked) {
                snprintf(body,sizeof(body),
                    "<p class=err>URL bloqueada.</p>"
                    "<p class=warn>Dica: tente 0.0.0.0 · 0177.0.0.1 · http://[::1]</p>");
                pent_send_html(cfd,403,body,NULL); return;
            }
            /* faz fetch da URL passada pelo usuário */
            CURL *ch=curl_easy_init();
            CurlBuf cb={0,0};
            if (ch) {
                curl_easy_setopt(ch,CURLOPT_URL,url);
                curl_easy_setopt(ch,CURLOPT_WRITEFUNCTION,curl_write_cb);
                curl_easy_setopt(ch,CURLOPT_WRITEDATA,&cb);
                curl_easy_setopt(ch,CURLOPT_TIMEOUT,5L);
                curl_easy_setopt(ch,CURLOPT_CONNECTTIMEOUT,3L);
                curl_easy_setopt(ch,CURLOPT_SSL_VERIFYPEER,0L);
                curl_easy_setopt(ch,CURLOPT_FOLLOWLOCATION,1L);
                curl_easy_setopt(ch,CURLOPT_MAXREDIRS,3L);
                curl_easy_perform(ch);
                curl_easy_cleanup(ch);
            }
            char esc[32768]={0};
            if (cb.data) {
                pent_escape(cb.data,esc,sizeof(esc)-1);
                free(cb.data);
            }
            snprintf(body,sizeof(body),
                "<h3>SSRF — Resposta de: %s</h3>"
                "<pre>%.8000s</pre>"
                "<p class=warn>Flag: FLAG{ssrf_internal_fetch}</p>",
                url,esc[0]?esc:"(sem resposta)");
        } else {
            snprintf(body,sizeof(body),
                "<h3>SSRF <span class=vuln-tag>o servidor faz requests por você</span></h3>"
                "<form>URL: <input name=url value='http://127.0.0.1:8082/' size=50>"
                "<button>Fetch</button></form>"
                "<p class=warn>Tente acessar portas internas, outros labs, "
                "ou serviços como http://127.0.0.1:22 · http://127.0.0.1:3306</p>"
                "<p>Em clouds: <code>http://169.254.169.254/latest/meta-data/</code></p>");
        }
        pent_send_html(cfd,200,body,NULL);

    /* ================================================================
     * /serialize — Insecure Deserialization simulada
     * ================================================================ */
    } else if (strcmp(path,"/serialize")==0) {
        char data[512]={0}; pent_qparam(qs,"data",data,sizeof(data));
        if (data[0]) {
            /* simula deserialização de "objeto" base64 */
            char decoded[512]={0};
            pent_b64decode(data,decoded,sizeof(decoded));
            char esc[1024]; pent_escape(decoded,esc,sizeof(esc));
            char flag[256]={0};
            if (strstr(decoded,"admin:true")||strstr(decoded,"role:admin"))
                strncpy(flag,"<div class=flag>FLAG{insecure_deserialization}</div>",255);
            snprintf(body,sizeof(body),
                "<h3>Deserialização — Objeto recebido:</h3>"
                "<pre>%s</pre>%s"
                "<form>Data (base64): <input name=data size=50><button>Enviar</button></form>",
                esc,flag);
        } else {
            /* mostra objeto serializado de exemplo */
            const char *example_obj = "{\"user\":\"alice\",\"role\":\"user\",\"id\":2}";
            /* encode base64 manual simples */
            static const char b64t[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
            char b64[256]={0}; size_t elen=strlen(example_obj); int bi=0;
            for (size_t ei=0; ei<elen; ei+=3) {
                unsigned int v=(unsigned char)example_obj[ei]<<16;
                if (ei+1<elen) v|=(unsigned char)example_obj[ei+1]<<8;
                if (ei+2<elen) v|=(unsigned char)example_obj[ei+2];
                b64[bi++]=b64t[(v>>18)&63];
                b64[bi++]=b64t[(v>>12)&63];
                b64[bi++]=ei+1<elen?b64t[(v>>6)&63]:'=';
                b64[bi++]=ei+2<elen?b64t[v&63]:'=';
            }
            snprintf(body,sizeof(body),
                "<h3>Deserialization <span class=vuln-tag>objeto não validado</span></h3>"
                "<p>Objeto original: <code>%s</code></p>"
                "<p>Encoded: <code>%s</code></p>"
                "<form>Data (base64): <input name=data value='%s' size=60>"
                "<button>Enviar</button></form>"
                "<p class=warn>Mude role para admin, recodifique em base64 e envie!</p>",
                example_obj,b64,b64);
        }
        pent_send_html(cfd,200,body,NULL);

    /* ================================================================
     * /rate — Sem rate limiting (brute-force)
     * ================================================================ */
    } else if (strcmp(path,"/rate")==0) {
        char pin[32]={0}; pent_qparam(qs,"pin",pin,sizeof(pin));
        /* PIN correto: 4242 */
        if (pin[0]) {
            if (strcmp(pin,"4242")==0) {
                snprintf(body,sizeof(body),
                    "<div class=flag>✅ PIN correto! Flag: FLAG{no_rate_limit_brute}</div>"
                    "<p>Demorou quanto tempo? Sem limite de tentativas!</p>");
            } else {
                snprintf(body,sizeof(body),
                    "<p class=err>PIN incorreto: %s. Tente de novo!</p>"
                    "<p class=warn>Sem bloqueio · Sem delay · Sem captcha</p>"
                    "<form>PIN: <input name=pin maxlength=4 size=6>"
                    "<button>Tentar</button></form>",pin);
            }
        } else {
            snprintf(body,sizeof(body),
                "<h3>Rate Limiting <span class=vuln-tag>zero proteção contra brute-force</span></h3>"
                "<form>PIN (4 dígitos): <input name=pin maxlength=4 size=6>"
                "<button>Tentar</button></form>"
                "<p class=warn>Sem limite de tentativas! Tente via: <br>"
                "<code>for i in $(seq 0000 9999); do curl -s "
                "\"http://127.0.0.1:8081/rate?pin=$i\" | grep FLAG && echo $i; done</code>"
                "</p>");
        }
        pent_send_html(cfd,200,body,NULL);

    /* ================================================================
     * 404
     * ================================================================ */
    } else {
        snprintf(body,sizeof(body),
            "<h3>404 — Not Found</h3>"
            "<p>Endpoint <code>%s</code> não existe.</p>"
            "<p>Endpoints disponíveis: / /search /login /xss /comment /dom /exec "
            "/file /path /note /tpl /upload /api/users /api/me /redirect /cors "
            "/csrf /jwt /xxe /admin /register /reset /debug /backup /ssrf "
            "/serialize /rate</p>",
            path);
        pent_send_html(cfd,404,body,NULL);
    }

    close(cfd);
}


/* ── Thread do servidor ─────────────────────────────────────────────────── */
static void *pent_server_thread(void *arg) {
    PentServer *srv = (PentServer*)arg;
    while (srv->running) {
        struct sockaddr_in ca; socklen_t cl = sizeof(ca);
        int cfd = accept(srv->fd, (struct sockaddr*)&ca, &cl);
        if (cfd < 0) { if (srv->running) usleep(10000); continue; }
        pent_handle_conn(cfd, srv->level);
    }
    return NULL;
}

/* ── Inicia o lab em C via fork() — processo independente ─────────────── */
static int pent_start_c(int port, const char *level) {
    const char *h = getenv("HOME");
    if (!h) h="/data/data/com.termux/files/home";

    /* Mata processo anterior se existir */
    char pid_file[512];
    snprintf(pid_file, sizeof(pid_file), "%s/.pent_%d.pid", h, port);
    FILE *pf = fopen(pid_file, "r");
    if (pf) {
        int old_pid = 0; fscanf(pf, "%d", &old_pid); fclose(pf);
        if (old_pid > 0) { kill(old_pid, SIGTERM); usleep(200000); }
        remove(pid_file);
    }

    /* Cria arquivo secreto para LFI */
    char sec[512]; snprintf(sec, sizeof(sec), "%s/.pent_secret.txt", h);
    FILE *sf = fopen(sec, "w");
    if (sf) { fprintf(sf, "FLAG{lfi_found_you}\npassword=s3cr3t_%s\n", level); fclose(sf); }

    /* Cria socket ANTES do fork para validar a porta */
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) { printf("\033[1;31m[!] socket() falhou\033[0m\n"); return 0; }
    int one = 1; setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one));
    struct sockaddr_in sa; memset(&sa, 0, sizeof(sa));
    sa.sin_family = AF_INET; sa.sin_port = htons((uint16_t)port);
    sa.sin_addr.s_addr = htonl(INADDR_ANY);
    if (bind(fd, (struct sockaddr*)&sa, sizeof(sa)) < 0) {
        close(fd);
        printf("\033[1;31m[!] bind() falhou na porta %d — porta já em uso?\033[0m\n", port);
        return 0;
    }
    listen(fd, 8);

    /* fork() — filho vira o servidor, pai retorna */
    pid_t pid = fork();
    if (pid < 0) {
        close(fd);
        printf("\033[1;31m[!] fork() falhou\033[0m\n");
        return 0;
    }

    if (pid == 0) {
        /* ── FILHO: servidor HTTP totalmente independente ── */
        /* Torna-se líder de sessão — desvincula do processo pai */
        setsid();

        /* Ignora sinais que matariam o servidor */
        signal(SIGHUP,  SIG_IGN);
        signal(SIGPIPE, SIG_IGN);
        signal(SIGTERM, SIG_DFL); /* só morre via pent.stop() */

        /* Fecha stdin/stdout/stderr para não herdar TTY do pai */
        int devnull = open("/dev/null", O_RDWR);
        if (devnull >= 0) {
            dup2(devnull, STDIN_FILENO);
            dup2(devnull, STDOUT_FILENO);
            dup2(devnull, STDERR_FILENO);
            if (devnull > 2) close(devnull);
        }
        sqlite3 *db = NULL;
        sqlite3_open(":memory:", &db);
        if (db) {
            sqlite3_exec(db,
                "CREATE TABLE users(id INTEGER PRIMARY KEY, name TEXT, pass TEXT, role TEXT);"
                "INSERT INTO users VALUES(1,'admin','admin123','admin');"
                "INSERT INTO users VALUES(2,'alice','password','user');"
                "INSERT INTO users VALUES(3,'bob','123456','user');"
                "CREATE TABLE notes(id INTEGER, user_id INTEGER, content TEXT);"
                "INSERT INTO notes VALUES(1,1,'Flag: FLAG{easy_sqli_win}');"
                "INSERT INTO notes VALUES(2,2,'Note secreta da alice');"
                "INSERT INTO notes VALUES(3,3,'bob private note');",
                NULL, NULL, NULL);
        }
        g_pent_db = db;

        /* Fecha fds desnecessários */
        int maxfd = 1024;
        for (int i = 3; i < maxfd; i++) { if (i != fd) close(i); }

        /* Loop de accept */
        char lvl[16]; strncpy(lvl, level, 15);
        while (1) {
            struct sockaddr_in ca; socklen_t cl = sizeof(ca);
            int cfd = accept(fd, (struct sockaddr*)&ca, &cl);
            if (cfd < 0) { usleep(10000); continue; }
            pent_handle_conn(cfd, lvl);
        }
        exit(0); /* nunca chega aqui */
    }

    /* ── PAI: salva PID e retorna ── */
    close(fd); /* pai não usa o fd */
    FILE *pidf = fopen(pid_file, "w");
    if (pidf) { fprintf(pidf, "%d\n", (int)pid); fclose(pidf); }

    /* Guarda PID no estado global */
    g_pent_srv.port    = port;
    g_pent_srv.running = 1;
    g_pent_srv.fd      = -1;
    g_pent_srv.tid     = 0;
    strncpy(g_pent_srv.level, level, 15);

    usleep(200000); /* aguarda filho fazer bind/listen */
    return (int)pid;
}

