static int l_pent_stop(lua_State *L) {
    (void)L;
    const char *h = getenv("HOME");
    if (!h) h="/data/data/com.termux/files/home";
    int stopped = 0;
    int ports[] = {8081, 8082, 8083};
    for (int i = 0; i < 3; i++) {
        char pid_file[512];
        snprintf(pid_file, sizeof(pid_file), "%s/.pent_%d.pid", h, ports[i]);
        FILE *pf = fopen(pid_file, "r");
        if (!pf) continue;
        int pid = 0; fscanf(pf, "%d", &pid); fclose(pf);
        if (pid > 0 && kill(pid, 0) == 0) {
            kill(pid, SIGTERM);
            remove(pid_file);
            printf("\033[1;32m[✓] Lab porta %d (PID %d) encerrado\033[0m\n", ports[i], pid);
            stopped++;
        } else {
            remove(pid_file);
        }
    }
    g_pent_srv.running = 0;
    if (!stopped) printf("\033[0;90m[*] Nenhum lab rodando\033[0m\n");
    lua_pushinteger(L, stopped);
    return 1;
}

