    const char *labels[] = {"FÁCIL", "MÉDIO", "DIFÍCIL"};

    for (int i = 0; i < 3; i++) {
        /* verifica se a porta está respondendo */
        int sock = socket(AF_INET, SOCK_STREAM, 0);
        struct sockaddr_in addr; memset(&addr,0,sizeof(addr));
        addr.sin_family=AF_INET; addr.sin_port=htons((uint16_t)ports[i]);
        inet_pton(AF_INET,"127.0.0.1",&addr.sin_addr);
        struct timeval tv={0,200000};
        setsockopt(sock,SOL_SOCKET,SO_RCVTIMEO,&tv,sizeof(tv));
        setsockopt(sock,SOL_SOCKET,SO_SNDTIMEO,&tv,sizeof(tv));
        int up = (connect(sock,(struct sockaddr*)&addr,sizeof(addr))==0);
        close(sock);
        const char *col = up ? "\033[1;32m" : "\033[0;90m";
        const char *st  = up ? "● RODANDO " : "○ parado  ";
        printf("  %s%s\033[0m  %-8s  porta %-5d  [%s]\n",
               col, st, names[i], ports[i], labels[i]);
        if (up)
            printf("           \033[0;36m→ http://127.0.0.1:%d/\033[0m\n", ports[i]);
    }
    printf("\n");
    lua_pushboolean(L, g_pent_srv.running);
    return 1;
}


