// ============================================================================
// ms — MoonStyle  (utilitários + diagnóstico profissional)
// ============================================================================

/* ─── severity ───────────────────────────────────────────────────────────── */
// ============================================================================
// MS.CHECK — Self-test com servidor TCP/UDP local embutido
// Testa TODOS os módulos + net com pacotes reais no loopback
// ============================================================================

// ── Servidor de teste local ──────────────────────────────────────────────────
// Aceita TCP e UDP na mesma porta. Thread separada, desligado após os testes.

#define MS_TEST_PORT_BASE 57320

typedef struct {
    int tcp_fd, udp_fd, port;
    volatile int stop;
    volatile int tcp_conns, udp_pkts, tcp_echo_ok, udp_echo_ok;
} MsTestServer;

static MsTestServer g_test_srv = {-1,-1,0,0,0,0,0,0};

static void *mst_tcp_thread(void *arg) {
    MsTestServer *srv = (MsTestServer*)arg;
    struct timeval tv = {1,0};
    setsockopt(srv->tcp_fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
    while (!srv->stop) {
        int c = accept(srv->tcp_fd, NULL, NULL);
        if (c < 0) continue;
        srv->tcp_conns++;
        char buf[512] = {0};
        setsockopt(c, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
        ssize_t n = recv(c, buf, sizeof(buf)-1, 0);
        if (n > 0) {
            char resp[528];
            int rlen = snprintf(resp, sizeof(resp), "ECHO:%.*s", (int)n, buf);
            send(c, resp, rlen, MSG_NOSIGNAL);
            srv->tcp_echo_ok++;
        }
        close(c);
    }
    return NULL;
}

static void *mst_udp_thread(void *arg) {
    MsTestServer *srv = (MsTestServer*)arg;
    struct timeval tv = {1,0};
    setsockopt(srv->udp_fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
    while (!srv->stop) {
        char buf[512] = {0};
        struct sockaddr_in cli; socklen_t cl = sizeof(cli);
        ssize_t n = recvfrom(srv->udp_fd, buf, sizeof(buf)-1, 0,
                             (struct sockaddr*)&cli, &cl);
        if (n < 0) continue;
        srv->udp_pkts++;
        char resp[528];
        int rlen = snprintf(resp, sizeof(resp), "ECHO:%.*s", (int)n, buf);
        sendto(srv->udp_fd, resp, rlen, 0, (struct sockaddr*)&cli, cl);
        srv->udp_echo_ok++;
    }
    return NULL;
}

static int mst_server_start(MsTestServer *srv) {
    srv->stop = 0; srv->tcp_conns = 0; srv->udp_pkts = 0;
    srv->tcp_echo_ok = 0; srv->udp_echo_ok = 0;
    for (int port = MS_TEST_PORT_BASE; port < MS_TEST_PORT_BASE + 100; port++) {
        int tf = socket(AF_INET, SOCK_STREAM, 0);
        int uf = socket(AF_INET, SOCK_DGRAM,  0);
        if (tf < 0 || uf < 0) { if(tf>=0) close(tf); if(uf>=0) close(uf); continue; }
        int one = 1;
        setsockopt(tf, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one));
        setsockopt(uf, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one));
        struct sockaddr_in sa; memset(&sa, 0, sizeof(sa));
        sa.sin_family = AF_INET;
        sa.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
        sa.sin_port = htons((uint16_t)port);
        if (bind(tf,(struct sockaddr*)&sa,sizeof(sa)) < 0 ||
            bind(uf,(struct sockaddr*)&sa,sizeof(sa)) < 0 ||
            listen(tf,16) < 0) {
            close(tf); close(uf); continue;
        }
        srv->tcp_fd = tf; srv->udp_fd = uf; srv->port = port;
        pthread_t t1, t2;
        pthread_create(&t1, NULL, mst_tcp_thread, srv);
        pthread_create(&t2, NULL, mst_udp_thread, srv);
        pthread_detach(t1); pthread_detach(t2);
        return port;
    }
    return -1;
}

static void mst_server_stop(MsTestServer *srv) {
    srv->stop = 1;
    usleep(150000);
    if (srv->tcp_fd >= 0) { close(srv->tcp_fd); srv->tcp_fd = -1; }
    if (srv->udp_fd >= 0) { close(srv->udp_fd); srv->udp_fd = -1; }
}

static long mst_now_ms(void) {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}

// ── Visual ────────────────────────────────────────────────────────────────────
#define MST_OK   "\033[1;32m"
#define MST_FAIL "\033[1;31m"
#define MST_WARN "\033[1;33m"
#define MST_DIM  "\033[0;90m"
static int g_mst_verbose = 0;
#define MST_CYN  "\033[1;36m"
#define MST_RST  "\033[0m"
#define MST_W    56

/* Separador de categoria — agrupa visualmente os testes */
#define MST_CAT(label) \
    printf("\n  \033[1;36m▸ %-58s\033[0m\n", label)

/* ── Severity levels ─────────────────────────────────────────────────────── */
/* FATAL : falha que impede uso do módulo (contabiliza em failed)            */
/* WARN  : degradação parcial, funcionalidade reduzida (contabiliza em warned)*/
/* INFO  : informativo — não conta como falha                                */
typedef enum { MST_SEV_FATAL = 0, MST_SEV_WARN = 1, MST_SEV_INFO = 2 } MstSev;

/* Suprime stdout quando não-verbose — evita output verboso dos módulos */
static int mst_suppress(void) {
    if (g_mst_verbose) return -1;
    fflush(stdout);
    int s = dup(STDOUT_FILENO);
    int dn = open("/dev/null", O_WRONLY);
    if (dn >= 0) { dup2(dn, STDOUT_FILENO); close(dn); }
    return s;
}
static void mst_restore(int saved) {
    if (saved < 0) return;
    fflush(stdout);
    dup2(saved, STDOUT_FILENO);
    close(saved);
}

/* mst_result — severity-aware ──────────────────────────────────────────────
 * ok==1 : sempre ✓ OK (severity ignorada)
 * ok==0 + FATAL : ✗ FATAL  — incrementa failed
 * ok==0 + WARN  : ⚠ AVISO  — incrementa warned (não failed)
 * ok==0 + INFO  : ℹ INFO   — não incrementa nenhum contador de erro
 */
static void mst_result_sev(int *total, int *failed, int *warned,
                           const char *name, int ok, long ms_took,
                           const char *detail, MstSev sev) {
    (*total)++;
    int nl = (int)strlen(name);
    int dots = MST_W - nl - 10;
    if (dots < 2) dots = 2;
    printf("  %s%s%s ", MST_CYN, name, MST_RST);
    for (int i = 0; i < dots; i++) putchar('.');
    if (ok) {
        printf(" %s✓ OK%s  %s%ldms%s\n", MST_OK, MST_RST, MST_DIM, ms_took, MST_RST);
    } else {
        switch (sev) {
            case MST_SEV_FATAL:
                (*failed)++;
                printf(" %s✗ FATAL%s%s%ldms%s\n", MST_FAIL, MST_RST, MST_DIM, ms_took, MST_RST);
                break;
            case MST_SEV_WARN:
                if (warned) (*warned)++;
                printf(" %s⚠ AVISO%s%s%ldms%s\n", MST_WARN, MST_RST, MST_DIM, ms_took, MST_RST);
                break;
            case MST_SEV_INFO:
                printf(" %sℹ INFO%s  %s%ldms%s\n", MST_CYN, MST_RST, MST_DIM, ms_took, MST_RST);
                break;
        }
    }
    if (detail && detail[0]) {
        if (!ok || g_mst_verbose)
            printf("     %s└─ %s%s\n", MST_DIM, detail, MST_RST);
    }
}

/* Wrapper de compatibilidade — mantém todas as chamadas existentes sem alterar */
static void mst_result(int *total, int *failed, const char *name,
                       int ok, long ms_took, const char *detail) {
    mst_result_sev(total, failed, NULL, name, ok, ms_took, detail, MST_SEV_FATAL);
}

// Helper: TCP raw connect + echo ao servidor local
static int mst_tcp_echo(int port, const char *msg, char *resp, int rsz) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) return 0;
    struct sockaddr_in sa; memset(&sa, 0, sizeof(sa));
    sa.sin_family = AF_INET; sa.sin_port = htons((uint16_t)port);
    sa.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    struct timeval tv = {2,0};
    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
    setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));
    int ok = 0;
    if (connect(fd, (struct sockaddr*)&sa, sizeof(sa)) == 0) {
        send(fd, msg, strlen(msg), MSG_NOSIGNAL);
        ssize_t n = recv(fd, resp, rsz-1, 0);
        if (n > 0) { resp[n] = 0; ok = 1; }
    }
    close(fd);
    return ok;
}

