    int base  = lua_gettop(L);
    int total = 0, failed = 0, warned = 0;
    long t0, t1;
    char det[256];

    /* Cabeçalho com hora */
    {
        time_t _tnow = time(NULL);
        struct tm *_tm = localtime(&_tnow);
        char _tstr[32]; strftime(_tstr, sizeof(_tstr), "%Y-%m-%d %H:%M:%S", _tm);
        const char *_perfil = "completo";  const char *_pcor = "\033[1;32m";
        printf("\n\033[1;35m╔══════════════════════════════════════════════════════════════╗\033[0m\n");
        printf("\033[1;35m║  ms.check() — ElliotOS Self-Test                             ║\033[0m\n");
        printf("\033[1;35m╠══════════════════════════════════════════════════════════════╣\033[0m\n");
        printf("\033[1;35m║\033[0m  Perfil : %s%-8s\033[0m                                          \033[1;35m║\033[0m\n", _pcor, _perfil);
        printf("\033[1;35m║\033[0m  Hora   : \033[0;90m%s\033[0m                                \033[1;35m║\033[0m\n", _tstr);
        printf("\033[1;35m╚══════════════════════════════════════════════════════════════╝\033[0m\n\n");
    }

    // Sobe servidor local
    printf("  %s[+] Iniciando servidor TCP+UDP local...%s\n", MST_DIM, MST_RST);
    t0 = mst_now_ms();
    int sp = mst_server_start(&g_test_srv);
    t1 = mst_now_ms();
    if (sp < 0)
        printf("  %s[!] Servidor não iniciou — testes de loopback desativados%s\n\n", MST_WARN, MST_RST);
    else {
        printf("  %s[+] Servidor TCP+UDP pronto na porta %d%s %s(%ldms)%s\n\n",
