    // ═══════════════════════════════════════════════════════════════════════
    MST_CAT("CORE — utilitários base");
    printf("  %s── ms.b64 ──────────────────────────────────────────────────%s\n", MST_DIM, MST_RST);
    {
        t0 = mst_now_ms();
        // C interno
        char *e = b64_encode((const unsigned char*)"ElliotOS:MoonStyle", 18, 0);
        int enc_ok = e && strcmp(e, "RWxsaW90T1M6TW9vblN0eWxl") == 0;
        size_t ol = 0;
        unsigned char *d = b64_decode_full("RWxsaW90T1M6TW9vblN0eWxl", &ol);
        int dec_ok = d && ol == 18 && memcmp(d, "ElliotOS:MoonStyle", 18) == 0;
        if (e) free(e);
        if (d) free(d);
        char *eu = b64_encode((const unsigned char*)"\xfb\xff\xfe", 3, 1);
        int url_ok = eu && strcmp(eu, "-__-") == 0;
        if (eu) free(eu);
        // Lua API: ms.b64.enc → ms.b64.dec roundtrip
        int lua_ok = 0;
        lua_getglobal(L, "ms");
        lua_getfield(L, -1, "b64");
        lua_getfield(L, -1, "enc"); lua_pushstring(L, "TESTE_B64");
        if (lua_pcall(L, 1, 1, 0) == LUA_OK && lua_isstring(L, -1)) {
            const char *enc_lua = lua_tostring(L, -1);
            lua_getfield(L, -2, "dec"); lua_pushstring(L, enc_lua);
            if (lua_pcall(L, 1, 1, 0) == LUA_OK && lua_isstring(L, -1)) {
