                int probe = socket(AF_INET, SOCK_STREAM, 0);
                if (probe < 0) break;
                int one2=1; setsockopt(probe,SOL_SOCKET,SO_REUSEADDR,&one2,sizeof(one2));
                struct sockaddr_in psa; memset(&psa,0,sizeof(psa));
                psa.sin_family=AF_INET; psa.sin_port=htons((uint16_t)candidate);
                psa.sin_addr.s_addr=htonl(INADDR_LOOPBACK);
                if (bind(probe,(struct sockaddr*)&psa,sizeof(psa))==0) {
                    close(probe); lp=candidate; break;
                }
                close(probe);
            }
            if (lp > 0) {
                lua_getglobal(L,"net");
                if(!lua_isnil(L,-1)){
                    lua_getfield(L,-1,"listen");
