            lua_pushstring(L,"http://127.0.0.1:1/");
            lua_pushinteger(L,1);
            int _s=mst_suppress();
            int rc=lua_pcall(L,2,1,0);
            mst_restore(_s);
            if(rc==LUA_OK){ call_ok=1; lua_pop(L,1); }
            else { call_ok=1; lua_pop(L,1); }
        }
        lua_settop(L,base); t1=mst_now_ms();
        mst_result(&total,&failed,"mod.spider() sem crash",fn_ok&&call_ok,t1-t0,
                   fn_ok&&call_ok?"retornou sem crash":"função não existe ou crashou");
    }
    /* Testa net.get com localhost — retorno deve ser nil ou string, nunca crash */
    {
        t0=mst_now_ms();
        lua_getglobal(L,"net"); lua_getfield(L,-1,"get");
        int fn_ok=lua_isfunction(L,-1);
        int call_ok=0;
        if(fn_ok){
            lua_pushstring(L,"http://127.0.0.1:1/test");
            int _s=mst_suppress();
            int rc=lua_pcall(L,1,1,0);
            mst_restore(_s);
            call_ok=(rc==LUA_OK)||(rc==LUA_ERRRUN);
            int top=lua_gettop(L); if(top>base) lua_settop(L,base);
        }
        lua_settop(L,base); t1=mst_now_ms();
        mst_result(&total,&failed,"net.get() sem crash (conn recusada)",fn_ok&&call_ok,t1-t0,
                   fn_ok&&call_ok?"sem crash":"função ausente ou crash fatal");
    }
    /* Testa net.scan com range mínimo — deve retornar tabela */
    {
        t0=mst_now_ms();
        lua_getglobal(L,"net"); lua_getfield(L,-1,"scan");
        int fn_ok=lua_isfunction(L,-1);
        int call_ok=0;
        if(fn_ok){
            lua_pushstring(L,"127.0.0.1");
            lua_pushinteger(L,65534);
            lua_pushinteger(L,65535);
            int _s=mst_suppress();
            int rc=lua_pcall(L,3,1,0);
            mst_restore(_s);
            call_ok=(rc==LUA_OK && lua_istable(L,-1));
            if(rc==LUA_OK||lua_isstring(L,-1)) lua_pop(L,1);
        }
        lua_settop(L,base); t1=mst_now_ms();
        mst_result(&total,&failed,"net.scan() retorna tabela",fn_ok&&call_ok,t1-t0,
                   fn_ok&&call_ok?"tabela retornada OK":"função ausente ou não retornou tabela");
    }

    // net.ping(host) — loopback deve responder true
    {
        t0=mst_now_ms();
        lua_getglobal(L,"net"); lua_getfield(L,-1,"ping");
        int fn_ok=lua_isfunction(L,-1), ok=0;
        if(fn_ok){
            lua_pushstring(L,"127.0.0.1");
            int _s=mst_suppress();
            int rc=lua_pcall(L,1,1,0);
            mst_restore(_s);
            if(rc==LUA_OK) ok=lua_toboolean(L,-1);
            if(rc==LUA_OK||lua_isstring(L,-1)) lua_pop(L,1);
        }
        lua_settop(L,base); t1=mst_now_ms();
        mst_result(&total,&failed,"net.ping('127.0.0.1') → true",fn_ok&&ok,t1-t0,
                   fn_ok ? (ok?"loopback respondeu true":"ping retornou false") : "função ausente");
    }

    // net.fetch(url) — retorna body+code+headers para loopback (sem crash)
    {
        t0=mst_now_ms();
        lua_getglobal(L,"net"); lua_getfield(L,-1,"fetch");
        int fn_ok=lua_isfunction(L,-1), call_ok=0;
        if(fn_ok){
            lua_pushstring(L,"http://127.0.0.1:1/ms_fetch_probe");
            lua_newtable(L);
            lua_pushinteger(L,2); lua_setfield(L,-2,"timeout");
            lua_pushboolean(L,1); lua_setfield(L,-2,"quiet");
            int _s=mst_suppress();
            int rc=lua_pcall(L,2,3,0);
            mst_restore(_s);
            /* aceita OK ou erro de conexão — o importante é não crashar */
            call_ok=(rc==LUA_OK || rc==LUA_ERRRUN);
            lua_settop(L,base+0);
        }
        lua_settop(L,base); t1=mst_now_ms();
        mst_result(&total,&failed,"net.fetch() sem crash (conn recusada)",fn_ok&&call_ok,t1-t0,
                   fn_ok ? (call_ok?"retornou sem crash":"crashou") : "função ausente");
    }

    // net.os(host) — loopback: deve resolver, retornar tabela com campos básicos
    {
        t0=mst_now_ms();
        lua_getglobal(L,"net"); lua_getfield(L,-1,"os");
        int fn_ok=lua_isfunction(L,-1), ok=0;
        char det2[128]="função ausente";
        if(fn_ok){
            lua_pushstring(L,"127.0.0.1");
            int _s=mst_suppress();
            int rc=lua_pcall(L,1,1,0);
            mst_restore(_s);
            if(rc==LUA_OK && lua_istable(L,-1)){
                /* verifica campos obrigatórios: ip, os_hint, type, confidence */
                const char *req[]={"ip","os_hint","type","confidence",NULL};
                int all=1; const char *miss=NULL;
                for(int i=0;req[i];i++){
                    lua_getfield(L,-1,req[i]);
                    if(lua_isnil(L,-1)){all=0;if(!miss)miss=req[i];}
                    lua_pop(L,1);
                }
                if(all){
                    lua_getfield(L,-1,"os_hint");
                    const char *hint=lua_tostring(L,-1);
                    snprintf(det2,sizeof(det2),"tabela OK — os_hint='%s'",hint?hint:"?");
                    lua_pop(L,1);
                    ok=1;
                } else {
                    snprintf(det2,sizeof(det2),"campo '%s' ausente na tabela",miss?miss:"?");
                }
            } else if(rc==LUA_OK && lua_isnil(L,-1)){
                /* nil é aceitável se host não responde — mas ainda é OK */
                snprintf(det2,sizeof(det2),"retornou nil (sem resposta — aceitável)");
                ok=1;
            } else {
                snprintf(det2,sizeof(det2),"rc=%d tipo=%s",rc,lua_typename(L,lua_type(L,-1)));
            }
            lua_settop(L,base+0);
        }
        lua_settop(L,base); t1=mst_now_ms();
        mst_result(&total,&failed,"net.os('127.0.0.1') — tabela fingerprint",fn_ok&&ok,t1-t0,det2);
    }


    // ═══════════════════════════════════════════════════════════════════════
    MST_CAT("EXTRAS — lmod · ell · ed");
    printf("\n  %s── lmod ────────────────────────────────────────────────────%s\n", MST_DIM, MST_RST);
    // lmod registrado com 6 funções
    {
        t0 = mst_now_ms();
        lua_getglobal(L, "lmod"); int ex = !lua_isnil(L,-1), fns_ok = 1;
        const char *mf = NULL;
        if (ex) {
            const char *f[] = {"new","mod","list","remove","path","help",NULL};
            for (int i = 0; f[i]; i++) {
                lua_getfield(L,-1,f[i]);
                if (!lua_isfunction(L,-1)) { fns_ok=0; if(!mf) mf=f[i]; }
                lua_pop(L,1);
            }
        }
        lua_settop(L,base); t1 = mst_now_ms();
        snprintf(det,sizeof(det), ex&&fns_ok ? "6 funções registradas OK" : "'%s' ausente", mf?mf:"módulo");
        mst_result(&total,&failed,"lmod (6 fns registradas)",ex&&fns_ok,t1-t0,det);
    }
    // lmod.path() sem crash
    {
        t0 = mst_now_ms();
        lua_getglobal(L,"lmod"); int ex=!lua_isnil(L,-1), ok=0;
        if(ex){
            lua_getfield(L,-1,"path");
            int rc=lua_pcall(L,0,0,0);
            ok=(rc==LUA_OK);
            if(!ok&&lua_isstring(L,-1)) lua_pop(L,1);
        }
        lua_settop(L,base); t1=mst_now_ms();
        mst_result(&total,&failed,"lmod.path() sem crash",ex&&ok,t1-t0,ex&&ok?"OK":"falhou");
    }
    // lmod.list() sem crash
    {
        t0 = mst_now_ms();
        lua_getglobal(L,"lmod"); int ex=!lua_isnil(L,-1), ok=0;
        if(ex){
            lua_getfield(L,-1,"list");
            int rc=lua_pcall(L,0,0,0);
            ok=(rc==LUA_OK);
            if(!ok&&lua_isstring(L,-1)) lua_pop(L,1);
        }
        lua_settop(L,base); t1=mst_now_ms();
        mst_result(&total,&failed,"lmod.list() sem crash",ex&&ok,t1-t0,ex&&ok?"OK":"falhou");
    }
    // lmod.mod() + lmod.remove() roundtrip — nome sem ponto para evitar falso negativo
    {
        t0 = mst_now_ms();
        char tf_lmod[512], lmod_dir_path[512], lmod_dest[512];
        snprintf(tf_lmod,     sizeof(tf_lmod),     "%s/ms_lmod_probe.lua",           home);
        snprintf(lmod_dir_path,sizeof(lmod_dir_path),"%s/.lua-modules",              home);
        snprintf(lmod_dest,   sizeof(lmod_dest),   "%s/ms_lmod_probe.lua",           lmod_dir_path);
        FILE *f2 = fopen(tf_lmod, "w");
        if (f2) { fputs("return 42\n", f2); fclose(f2); }
        lua_getglobal(L,"lmod"); int ex=!lua_isnil(L,-1);
        int mod_ok=0, rm_ok=0;
        if (ex && f2) {
            lua_getfield(L,-1,"mod"); lua_pushstring(L,tf_lmod);
            int rc=lua_pcall(L,1,0,0);
            if(rc!=LUA_OK&&lua_isstring(L,-1)) lua_pop(L,1);
            mod_ok=(access(lmod_dest,F_OK)==0);
            lua_getfield(L,-1,"remove"); lua_pushstring(L,"ms_lmod_probe");
            rc=lua_pcall(L,1,0,0);
            if(rc!=LUA_OK&&lua_isstring(L,-1)) lua_pop(L,1);
            rm_ok=(access(lmod_dest,F_OK)!=0);
        }
        remove(tf_lmod); remove(lmod_dest);
        lua_settop(L,base); t1=mst_now_ms();
        snprintf(det,sizeof(det),"mod=%s remove=%s",mod_ok?"✓":"✗",rm_ok?"✓":"✗");
        mst_result(&total,&failed,"lmod.mod()+remove() roundtrip",ex&&mod_ok&&rm_ok,t1-t0,det);
    }

    // ═══════════════════════════════════════════════════════════════════════
    printf("\n  %s── ell ─────────────────────────────────────────────────────%s\n", MST_DIM, MST_RST);
    // ell carregável + 4 funções
    {
        t0 = mst_now_ms();
        lua_getglobal(L,"require"); lua_pushstring(L,"ell");
        int rc=lua_pcall(L,1,1,0);
        int loaded=(rc==LUA_OK && lua_istable(L,-1));
        int fns_ok=0; const char *mf2=NULL;
        if(loaded){
            const char *ef[]={"encode","decode","info","help",NULL};
            fns_ok=1;
            for(int i=0;ef[i];i++){
                lua_getfield(L,-1,ef[i]);
                if(!lua_isfunction(L,-1)){fns_ok=0;if(!mf2)mf2=ef[i];}
                lua_pop(L,1);
            }
        } else if(lua_isstring(L,-1)) lua_pop(L,1);
        lua_settop(L,base); t1=mst_now_ms();
        snprintf(det,sizeof(det), loaded&&fns_ok ? "4 funções: encode/decode/info/help OK"
                                                  : loaded ? "'%s' ausente"
                                                           : "require('ell') falhou — checar LUA_PATH",
                 mf2?mf2:"?");
        mst_result(&total,&failed,"ell (require + 4 fns)",loaded&&fns_ok,t1-t0,det);
    }
    // ell.encode + ell.decode roundtrip — nomes sem ponto
    {
        t0 = mst_now_ms();
        char src[512], enc_out[512], dec_out[512], dec_alt[512];
        snprintf(src,    sizeof(src),    "%s/ms_ell_probe.lua",      home);
        snprintf(enc_out,sizeof(enc_out),"%s/ms_ell_probe.ell",      home);
        snprintf(dec_out,sizeof(dec_out),"%s/ms_ell_probe_dec.lua",  home);
        snprintf(dec_alt,sizeof(dec_alt),"%s/ms_ell_probe_decoded.lua",home);
        FILE *f3=fopen(src,"w");
        if(f3){ fputs("local x = 1 + 1\nreturn x\n",f3); fclose(f3); }
        int enc_ok=0, dec_ok=0;
        lua_getglobal(L,"require"); lua_pushstring(L,"ell");
        int rc=lua_pcall(L,1,1,0);
        if(rc==LUA_OK && lua_istable(L,-1)){
            lua_getfield(L,-1,"encode"); lua_pushstring(L,src);
            int rc2=lua_pcall(L,1,0,0);
            if(rc2!=LUA_OK&&lua_isstring(L,-1)) lua_pop(L,1);
            enc_ok=(access(enc_out,F_OK)==0);
            if(enc_ok){
                lua_getfield(L,-1,"decode"); lua_pushstring(L,enc_out);
                rc2=lua_pcall(L,1,0,0);
                if(rc2!=LUA_OK&&lua_isstring(L,-1)) lua_pop(L,1);
                dec_ok=(access(dec_out,F_OK)==0)||(access(dec_alt,F_OK)==0);
            }
        } else if(lua_isstring(L,-1)) lua_pop(L,1);
        remove(src); remove(enc_out); remove(dec_out); remove(dec_alt);
        lua_settop(L,base); t1=mst_now_ms();
        snprintf(det,sizeof(det),"encode=%s decode=%s",enc_ok?"✓":"✗",dec_ok?"✓":"✗");
        mst_result(&total,&failed,"ell.encode()+decode() roundtrip",enc_ok&&dec_ok,t1-t0,det);
    }

    // ═══════════════════════════════════════════════════════════════════════
    if (sp > 0) {
        usleep(100000);
        printf("\n  %s── servidor local ───────────────────────────────────────────%s\n", MST_DIM, MST_RST);
        printf("  %s   TCP conexões aceitas  : %d%s\n", MST_DIM, g_test_srv.tcp_conns,    MST_RST);
        printf("  %s   TCP ecos enviados     : %d%s\n", MST_DIM, g_test_srv.tcp_echo_ok,  MST_RST);
        printf("  %s   UDP pacotes recebidos : %d%s\n", MST_DIM, g_test_srv.udp_pkts,     MST_RST);
        printf("  %s   UDP ecos enviados     : %d%s\n", MST_DIM, g_test_srv.udp_echo_ok,  MST_RST);
        mst_server_stop(&g_test_srv);
    }

    // ═══════════════════════════════════════════════════════════════════════

    /* ── Resumo final ─────────────────────────────────────────────── */
    {
        int passed = total - failed - warned;
        int bar_w  = 40;
        int passed_full = passed + warned;  /* avisos = funcionou, conta como OK */
        int bar_ok = (total > 0) ? (passed * bar_w / total) : bar_w;
        int bar_wn = (total > 0) ? (warned * bar_w / total) : 0;
        /* Garantir que barra chegue a 100% — arredondamento de int */
        int bar_fill = bar_ok + bar_wn;
        if (bar_fill < bar_w && failed == 0) bar_wn += (bar_w - bar_fill);
        int bar_er = (failed > 0) ? (bar_w - bar_ok - bar_wn) : 0;
        if (bar_er < 0) bar_er = 0;

        printf("\n\033[1;35m╔══════════════════════════════════════════════════════════════╗\033[0m\n");
        printf("\033[1;35m║  RESULTADO FINAL                                              ║\033[0m\n");
        printf("\033[1;35m╚══════════════════════════════════════════════════════════════╝\033[0m\n\n");

        /* Barra visual: verde=ok, amarelo=aviso, vermelho=fatal */
        printf("  \033[0;90m[\033[0m");
        for(int i = 0; i < bar_ok; i++) printf("\033[1;32m█\033[0m");
        for(int i = 0; i < bar_wn; i++) printf("\033[1;33m▒\033[0m");
        for(int i = 0; i < bar_er; i++) printf("\033[1;31m░\033[0m");
        printf("\033[0;90m]\033[0m");

        double pct = total > 0 ? ((passed + warned) * 100.0 / total) : 100.0;
        printf("  \033[1;37m%.0f%%\033[0m", pct);
        if (warned > 0 && failed == 0)
            printf("  \033[0;90m(\033[1;32m█\033[0;90m=ok  \033[1;33m▒\033[0;90m=método alternativo)\033[0m");
        printf("\n\n");

        printf("  Total   : \033[1;37m%d\033[0m checks\n", total);
        printf("  OK      : \033[1;32m%d\033[0m\n", passed);
        if (warned > 0)
            printf("  Avisos  : \033[1;33m%d\033[0m  \033[0;90m(⚠ funcional com limitações)\033[0m\n", warned);
        printf("  Fatais  : %s%d\033[0m\n\n",
               failed > 0 ? "\033[1;31m" : "\033[1;32m", failed);

        if (failed == 0 && warned == 0) {
            printf("  \033[1;32m✓ Todos os módulos funcionando perfeitamente.\033[0m\n\n");
        } else if (failed == 0 && warned > 0) {
            printf("  \033[1;33m⚠ Sistema funcional com %d aviso(s):\033[0m\n\n", warned);
            printf("  \033[0;90m  • Avisos são normais no Termux sem root\033[0m\n");
            printf("  \033[0;90m    (sys.net e sys.storage precisam de /proc — bloqueado pelo Android)\033[0m\n");
            printf("  \033[0;90m  • Todas as funções principais funcionam normalmente\033[0m\n");
            printf("  \033[0;90m  • 97%% é o máximo esperado neste ambiente\033[0m\n\n");
        } else {
            printf("  \033[1;31m✗ %d erro(s) fatal(is) detectado(s):\033[0m\n\n", failed);
            printf("  \033[1;33m  Dicas de fix:\033[0m\n");
            printf("  \033[0;90m  • Recompile com: bash luascript --termux\033[0m\n");
            printf("  \033[0;90m  • Verbose completo: ms.check('v')\033[0m\n");
            printf("  \033[0;90m  • Stress test real: ms.force()\033[0m\n");
            printf("  \033[0;90m  • Cada linha com ✗ FATAL acima mostra a causa exata\033[0m\n\n");
        }
    }

    lua_pushinteger(L, failed);
    return 1;
}


// ─────────────────────────────────────────────────────────────────────────────
// ms.force() — Teste de stress real: cada módulo usado de verdade
// Sobe servidor HTTP vulnerável local, testa mod/net/cc/sys sob carga
// Disponível apenas nos perfis meio e god (não no nano)
// ─────────────────────────────────────────────────────────────────────────────
#ifndef ELLIOT_NANO

// Servidor HTTP multi-endpoint para ms.force
typedef struct {
    int fd;
    int port;
    volatile int running;
    pthread_t tid;
} ForceServer;

static ForceServer g_force_srv = {-1, 0, 0, 0};

static void force_srv_handle(int cfd) {
    char req[2048] = {0};
    ssize_t n = recv(cfd, req, sizeof(req)-1, 0);
    if (n <= 0) { close(cfd); return; }
    req[n] = '\0';

    char *path_start = strchr(req, ' ');
    if (!path_start) { close(cfd); return; }
    path_start++;
    char *path_end = strchr(path_start, ' ');
    if (!path_end) { close(cfd); return; }
    *path_end = '\0';

    const char *param = "none";
    char pval[512] = {0};
    char pval_dec[512] = {0};
    char *qm = strchr(path_start, '?');
    if (qm) {
        char *xeq = strstr(qm, "x=");
        if (!xeq) xeq = strstr(qm, "cmd=");
        if (!xeq) xeq = strchr(qm, '=');
        if (xeq) {
            xeq = strchr(xeq, '=') + 1;
            int i = 0;
            while (*xeq && *xeq != '&' && *xeq != ' ' && i < 510)
                pval[i++] = *xeq++;
            pval[i] = '\0';
            /* URL-decode pval → pval_dec */
            int di = 0;
            for (int si = 0; pval[si] && di < 510; si++) {
                if (pval[si] == '%' && pval[si+1] && pval[si+2]) {
                    char hex[3] = {pval[si+1], pval[si+2], 0};
                    pval_dec[di++] = (char)strtol(hex, NULL, 16);
                    si += 2;
                } else if (pval[si] == '+') {
                    pval_dec[di++] = ' ';
                } else {
                    pval_dec[di++] = pval[si];
                }
            }
            pval_dec[di] = '\0';
            param = pval_dec;
        }
    }

    char body[4096];
    const char *route = path_start;

    if (strncmp(route, "/xss", 4) == 0) {
        /* XSS: reflete payload dentro de <script> — contexto executável confirmado.
         * O worker novo exige que o payload apareça literalmente (não URL-encoded).
         * O ForceServer recebe já decodificado, então reflete direto no script. */
        snprintf(body, sizeof(body),
            "<html><body>"
            "<script>var q='%s'; document.write(q);</script>"
            "<p>Resultado: %s</p>"
            "</body></html>", param, param);
    } else if (strncmp(route, "/sqli", 5) == 0) {
        /* Simula app vulnerável a SQLi com dois comportamentos detectáveis:
         * 1. Erro MySQL quando recebe aspas/operadores inválidos
         * 2. Resposta diferente para TRUE vs FALSE (boolean-based) */
        int has_quote  = strstr(param,"'") || strstr(param,"\"") || strstr(param,"--");
        int is_true_c  = strstr(param,"1=1") || strstr(param,"' OR '1'='1") ||
                         strstr(param,"OR 1=1") || strstr(param,"AND 1=1");
        int is_false_c = strstr(param,"1=2") || strstr(param,"AND 1=0") ||
                         strstr(param,"OR 1=2") || strstr(param,"' AND '1'='2");
        int is_union   = strstr(param,"UNION") || strstr(param,"union");

        if(has_quote && !is_true_c && !is_false_c && !is_union){
            /* Erro de sintaxe — sinal [E] */
            snprintf(body, sizeof(body),
                "<html>You have an error in your SQL syntax; "
                "check the manual that corresponds to your MySQL server version "
                "for the right syntax to use near '%s' at line 1</html>", param);
        } else if(is_true_c){
            /* TRUE: retorna dados reais — body maior */
            snprintf(body, sizeof(body),
                "<html><table>"
                "<tr><td>1</td><td>admin</td><td>admin@example.com</td></tr>"
                "<tr><td>2</td><td>user</td><td>user@example.com</td></tr>"
                "<tr><td>3</td><td>guest</td><td>guest@example.com</td></tr>"
                "</table><p>3 resultado(s) encontrado(s)</p></html>");
        } else if(is_false_c){
            /* FALSE: sem resultados — body menor */
            snprintf(body, sizeof(body),
                "<html><p>0 resultado(s) encontrado(s)</p></html>");
        } else {
            snprintf(body, sizeof(body), "<html>Result: %s</html>", param);
        }
    } else if (strncmp(route, "/lfi", 4) == 0) {
        if (strstr(param,"../") || strstr(param,"/etc/passwd") || strstr(param,"..\\")) {
            /* /etc/passwd com múltiplas entradas — worker exige 2+ para confirmar */
            snprintf(body, sizeof(body),
                "<html><pre>"
                "root:x:0:0:root:/root:/bin/bash\n"
                "daemon:x:1:1:daemon:/usr/sbin:/usr/sbin/nologin\n"
                "bin:x:2:2:bin:/bin:/usr/sbin/nologin\n"
                "www-data:x:33:33:www-data:/var/www:/usr/sbin/nologin\n"
                "nobody:x:65534:65534:nobody:/nonexistent:/usr/sbin/nologin\n"
                "</pre></html>");
        } else {
            snprintf(body, sizeof(body), "<html>File: %s</html>", param);
        }
    } else if (strncmp(route, "/rce", 4) == 0) {
        if (strstr(param,";") || strstr(param,"|") || strstr(param,"`") ||
            strstr(param,"$(") || strstr(param,"&&")) {
            /* RCE: output de `id` — uid= E gid= na mesma resposta = critério forte */
            snprintf(body, sizeof(body),
                "<html><pre>uid=33(www-data) gid=33(www-data) groups=33(www-data)</pre>"
                "</html>");
        } else {
            snprintf(body, sizeof(body), "<html>Exec: %s</html>", param);
        }
    } else if (strncmp(route, "/ssrf", 5) == 0) {
        if (strstr(param,"127.0.0.1") || strstr(param,"localhost") ||
            strstr(param,"169.254") || strstr(param,"metadata")) {
            /* SSRF: simula resposta de AWS IMDSv1 — worker aceita ami-id + ami-launch-index */
            snprintf(body, sizeof(body),
                "<html>"
                "ami-id: ami-0abcdef1234567890\n"
                "ami-launch-index: 0\n"
                "instance-id: i-1234567890abcdef0\n"
                "instance-type: t2.micro\n"
                "</html>");
        } else {
            snprintf(body, sizeof(body), "<html>Fetching: %s</html>", param);
        }
    } else if (strncmp(route, "/ssti", 5) == 0) {
        int is_ssti = strstr(param,"{{")  || strstr(param,"${")  ||
                      strstr(param,"<%")  || strstr(param,"#{")  ||
                      strstr(param,"*{")  || strstr(param,"#set") ||
                      strstr(param,"7*7") || strstr(param,"7+7") ||
                      strstr(param,"7*'");
        if (is_ssti) {
            snprintf(body, sizeof(body),
                "<html><body>Result: 49</body></html>");
        } else {
            snprintf(body, sizeof(body), "<html>Template: %s</html>", param);
        }
    } else if (strncmp(route, "/redir", 6) == 0) {
        /* Redirect HTTP real — mod.redir detecta pelo Location header */
        if (strstr(param,"http") || strstr(param,"//") || strstr(param,"evil")) {
            /* Envia 302 com Location para domínio externo */
            char r302[512];
            snprintf(r302,sizeof(r302),
                "HTTP/1.1 302 Found\r\nLocation: https://evil.com/redir\r\n"
                "Content-Length: 0\r\n\r\n");
            send(cfd,r302,strlen(r302),0); close(cfd); return;
        } else {
            snprintf(body, sizeof(body), "<html>Go: %s</html>", param);
        }
    } else if (strncmp(route, "/cors", 5) == 0) {
        const char *r2 =
            "HTTP/1.1 200 OK\r\nAccess-Control-Allow-Origin: *\r\n"
            "Access-Control-Allow-Credentials: true\r\n"
            "Content-Type: text/html\r\nContent-Length: 13\r\n\r\ncors_open:yes";
        send(cfd, r2, strlen(r2), 0); close(cfd); return;
    } else if (strncmp(route, "/headers", 8) == 0) {
        const char *r2 =
            "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: 7\r\n\r\nno_hdrs";
        send(cfd, r2, strlen(r2), 0); close(cfd); return;
    } else if (strncmp(route, "/fuzz", 5) == 0) {
        if (strstr(param,"<") || strstr(param,">") || strstr(param,"%") || strlen(param)>100)
            snprintf(body, sizeof(body), "<html>500 Internal Server Error: %s</html>", param);
        else
            snprintf(body, sizeof(body), "<html>OK: %s</html>", param);
    } else if (strncmp(route, "/auth", 5) == 0) {
        if (strstr(req,"Authorization: Basic YWRtaW46YWRtaW4=")) {
            snprintf(body, sizeof(body), "<html>Welcome admin!</html>");
        } else {
            const char *r2 =
                "HTTP/1.1 401 Unauthorized\r\nWWW-Authenticate: Basic realm=\"test\"\r\n"
                "Content-Length: 0\r\n\r\n";
            send(cfd, r2, strlen(r2), 0); close(cfd); return;
        }
    } else if (strncmp(route, "/csrf", 5) == 0) {
        snprintf(body, sizeof(body),
            "<html><form method=POST action=/transfer>"
            "<input name=amount value=1000><input type=submit></form></html>");
    } else if (strncmp(route, "/xxe", 4) == 0) {
        snprintf(body, sizeof(body),
            "<html>XML: &ext; = root:x:0:0:/root:/bin/bash</html>");
    } else if (strncmp(route, "/jwt", 4) == 0) {
        snprintf(body, sizeof(body),
            "<html>token: eyJhbGciOiJub25lIn0.eyJ1c2VyIjoiYWRtaW4ifQ.</html>");
    } else if (strncmp(route, "/spider", 7) == 0) {
        /* Links para endpoints vulneráveis — usados pelo spider e mod.chain */
        snprintf(body, sizeof(body),
            "<html><body>"
            "<h1>ForceServer Spider Page</h1>"
            "<a href='/xss?x='>XSS test</a> "
            "<a href='/sqli?x='>SQLi test</a> "
            "<a href='/lfi?x='>LFI test</a> "
            "<a href='/rce?cmd='>RCE test</a> "
            "<form action='/csrf' method=POST>"
            "  <input name=amount value=1000>"
            "  <input type=submit value=Transfer>"
            "</form>"
            "</body></html>");
    } else if (strncmp(route, "/recon", 6) == 0) {
        const char *r2 =
            "HTTP/1.1 200 OK\r\nServer: Apache/2.4.41 (Ubuntu)\r\n"
            "X-Powered-By: PHP/7.4.3\r\nContent-Type: text/html\r\n"
            "Content-Length: 5\r\n\r\nHello";
        send(cfd, r2, strlen(r2), 0); close(cfd); return;
    } else if (strncmp(route, "/params", 7) == 0 ||
               strncmp(route, "/fuzz",   5) == 0) {
        /* Endpoint genérico que aceita qualquer parâmetro — usado por mod.params */
        snprintf(body, sizeof(body),
            "<html><body>result: %s</body></html>", param);
    } else if (strncmp(route, "/nosql", 6) == 0) {
        /* Simula erro MongoDB quando usa operadores $ne/$gt */
        if (strstr(param,"$ne") || strstr(param,"$gt") || strstr(param,"$where"))
            snprintf(body, sizeof(body),
                "<html>MongoError: invalid operator near '%s'</html>", param);
        else
            snprintf(body, sizeof(body), "<html>user: %s</html>", param);
    } else if (strncmp(route, "/crlf", 5) == 0) {
        /* Reflete o parâmetro nos headers — CRLF injection */
        if (strstr(param,"%0d") || strstr(param,"%0a") || strstr(param,"\r") || strstr(param,"\n")) {
            char r_crlf[512];
            snprintf(r_crlf,sizeof(r_crlf),
                "HTTP/1.1 200 OK\r\nX-Injected: crlf\r\n"
                "Content-Type: text/html\r\nContent-Length: 8\r\n\r\ninjected");
            send(cfd,r_crlf,strlen(r_crlf),0); close(cfd); return;
        }
        snprintf(body, sizeof(body), "<html>param: %s</html>", param);
    } else {
        snprintf(body, sizeof(body), "<html>ForceServer OK param=%s</html>", param);
    }

    char resp[8192];
    snprintf(resp, sizeof(resp),
        "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: %d\r\n\r\n%s",
        (int)strlen(body), body);
    send(cfd, resp, strlen(resp), 0);
    close(cfd);
}

/* Thread que processa uma conexão individual — permite concorrência real */
static void *force_conn_thread(void *arg) {
    int cfd = (int)(intptr_t)arg;
    struct timeval rtv = {2, 0};
    setsockopt(cfd, SOL_SOCKET, SO_RCVTIMEO, &rtv, sizeof(rtv));
    setsockopt(cfd, SOL_SOCKET, SO_SNDTIMEO, &rtv, sizeof(rtv));
    force_srv_handle(cfd);
    return NULL;
}

static void *force_srv_thread(void *arg) {
    ForceServer *s = (ForceServer*)arg;
    while (s->running) {
        int fd = s->fd;
        if (fd < 0) break;
        struct timeval tv = {0, 200000};
        fd_set fds; FD_ZERO(&fds); FD_SET(fd, &fds);
        int r = select(fd+1, &fds, NULL, NULL, &tv);
        if (r <= 0) continue;
        if (!s->running || s->fd < 0) break;
        struct sockaddr_in ca; socklen_t cl = sizeof(ca);
        int cfd = accept(s->fd, (struct sockaddr*)&ca, &cl);
        if (cfd >= 0) {
            /* Thread por conexão — sem bloqueio do loop de accept */
            pthread_t ct;
            if (pthread_create(&ct, NULL, force_conn_thread, (void*)(intptr_t)cfd) == 0)
                pthread_detach(ct);
            else {
                /* Fallback: processa inline se pthread falhar */
                force_conn_thread((void*)(intptr_t)cfd);
            }
        }
    }
    return NULL;
}

static int force_srv_start(ForceServer *s) {
    s->fd = socket(AF_INET, SOCK_STREAM, 0);
    if (s->fd < 0) return 0;
    int yes = 1;
    setsockopt(s->fd, SOL_SOCKET, SO_REUSEADDR, &yes, sizeof(yes));
    struct sockaddr_in sa; memset(&sa, 0, sizeof(sa));
    sa.sin_family = AF_INET;
    sa.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    sa.sin_port = 0;
    if (bind(s->fd, (struct sockaddr*)&sa, sizeof(sa)) < 0) {
        close(s->fd); s->fd = -1; return 0;
    }
    socklen_t sl = sizeof(sa);
    getsockname(s->fd, (struct sockaddr*)&sa, &sl);
    s->port = ntohs(sa.sin_port);
    /* Backlog 256 — suporta rajadas de requests paralelas dos scanners */
    if (listen(s->fd, 256) < 0) { close(s->fd); s->fd = -1; return 0; }
    s->running = 1;
    pthread_t tid;
    pthread_create(&tid, NULL, force_srv_thread, s);
    pthread_detach(tid);
    usleep(80000);
    return 1;
}

static void force_srv_stop(ForceServer *s) {
    if (s->fd < 0) return;
    s->running = 0;
    int fd = s->fd; s->fd = -1;
    shutdown(fd, SHUT_RDWR);
    close(fd);
    /* thread é detached — não bloqueia */
}

typedef struct {
    int total;
    int failed;
    long long t_total;
    /* Log de falhas — até 64 entradas para sumário final */
    char fail_names[64][80];
    char fail_dets[64][128];
    int  fail_n;
} ForceResult;

static void frc_result(ForceResult *fr, const char *name, int ok,
                       long long ms_elapsed, const char *det) {
    fr->total++;
    fr->t_total += ms_elapsed;
    if (!ok) {
        fr->failed++;
        printf("  \033[1;31m✗\033[0m %-52s \033[1;31m%s\033[0m\n", name, det?det:"erro");
        /* Guarda no log para sumário final */
        if(fr->fail_n < 64){
            strncpy(fr->fail_names[fr->fail_n], name, 79);
            strncpy(fr->fail_dets[fr->fail_n],  det?det:"erro", 127);
            fr->fail_n++;
        }
    } else {
        if (g_mst_verbose)
            printf("  \033[1;32m✓\033[0m %-52s \033[0;90m%lldms\033[0m\n  \033[0;90m     └─ %s\033[0m\n",
                   name, ms_elapsed, det?det:"OK");
        else
            printf("  \033[1;32m✓\033[0m %-52s \033[0;90m%lldms — %s\033[0m\n",
                   name, ms_elapsed, det?det:"OK");
    }
}

/* ret >= 1  = vuln detectada
 * ret == 0  = rodou OK mas não detectou nada (falha silenciosa)
 * ret == -1 = função não existe
 * ret == -2 = erro Lua (crash/exceção no módulo) */
static int frc_call_mod(lua_State *L, int base, const char *fn, const char *url) {
    lua_getglobal(L, "mod");
    if (lua_isnil(L,-1)) { lua_settop(L,base); return -1; }
    lua_getfield(L, -1, fn);
    if (!lua_isfunction(L,-1)) { lua_settop(L,base); return -1; }
    lua_pushstring(L, url);

    /* Suprime stdout dos módulos quando não-verbose — output é muito verboso */
    int saved_stdout = -1;
    if (!g_mst_verbose) {
        fflush(stdout);
        saved_stdout = dup(STDOUT_FILENO);
        int devnull = open("/dev/null", O_WRONLY);
        if (devnull >= 0) { dup2(devnull, STDOUT_FILENO); close(devnull); }
    }

    int rc = lua_pcall(L, 1, 1, 0);

    /* Restaura stdout */
    if (saved_stdout >= 0) {
        fflush(stdout);
        dup2(saved_stdout, STDOUT_FILENO);
        close(saved_stdout);
    }

    int ret = 0;
    if (rc == LUA_OK) {
        if (lua_isnumber(L,-1)) ret = (int)lua_tonumber(L,-1);
    } else {
        ret = -2;
    }
    lua_settop(L, base);
    return ret;
}


/* Servidor eco TCP para testes de net.socket no ms.force */
typedef struct { int fd; } FrcEcoArg;
static FrcEcoArg g_frc_eco_arg = {-1};
static void *frc_eco_thread(void *a) {
    int sfd = ((FrcEcoArg*)a)->fd;
    for (int i = 0; i < 6; i++) {
        struct timeval tv = {2, 0};
        fd_set fs; FD_ZERO(&fs); FD_SET(sfd, &fs);
        if (select(sfd+1, &fs, NULL, NULL, &tv) <= 0) break;
        struct sockaddr_in ca; socklen_t cl = sizeof(ca);
        int cfd = accept(sfd, (struct sockaddr*)&ca, &cl);
        if (cfd < 0) break;
        struct timeval ctv = {1, 0};
        setsockopt(cfd, SOL_SOCKET, SO_RCVTIMEO, &ctv, sizeof(ctv));
        char buf[512] = {0}; ssize_t n = recv(cfd, buf, 511, 0);
        if (n > 0) {
            char out[520]; int ol = snprintf(out, sizeof(out), "ECHO:%.*s", (int)n, buf);
            send(cfd, out, ol, 0);
        }
        close(cfd);
    }
    return NULL;
}

static int l_ms_force(lua_State *L) {
    signal(SIGPIPE, SIG_IGN);
    /* Handler temporário para mostrar onde o processo morre */
    signal(SIGSEGV, SIG_DFL); /* deixa gerar core — pelo menos aparece Segfault */
    signal(SIGABRT, SIG_DFL);
    g_mst_verbose = 0;
    if (lua_gettop(L) >= 1) {
        if (lua_type(L,1)==LUA_TSTRING) {
            const char *a = lua_tostring(L,1);
            if (a && (a[0]=='v'||a[0]=='V')) g_mst_verbose=1;
        } else if (lua_type(L,1)==LUA_TNUMBER && lua_tointeger(L,1)>0) {
            g_mst_verbose=1;
        }
    }
    printf("\n\033[1;35m");
    printf("╔══════════════════════════════════════════════════════════════╗\n");
    printf("║  ms.force() — Stress test real: todos os modulos de verdade ║\n");
    printf("╚══════════════════════════════════════════════════════════════╝\n");
    printf("\033[0m");
    printf("  Servidor HTTP vulneravel local + uso real de cada modulo.\n");
    printf("  Detecta conflitos, crashes e comportamento sob carga real.\n\n");

    ForceResult fr = {0,0,0};
    long long t0, t1;
    char det[512];
    int base = lua_gettop(L);

    printf("  \033[0;33m[*] Subindo ForceServer (HTTP vulneravel — porta dinamica)...\033[0m\n");
    if (!force_srv_start(&g_force_srv)) {
        printf("  \033[1;31m✗ ForceServer falhou — abortando ms.force()\033[0m\n");
        lua_pushinteger(L, -1); return 1;
    }
    int port = g_force_srv.port;
    printf("  \033[1;32m✓ ForceServer porta %d — 16 endpoints vulneraveis\033[0m\n\n", port);

    // ── net.socket + socketex — servidor eco dedicado ────────────────────
    // Sobe um servidor TCP de eco simples em porta livre só pra esses testes.
    // Independente do ForceServer (single-threaded) — sem interferência.
    printf("  \033[0;90m── net.socket + net.socketex (métodos completos) ────────────\033[0m\n");
    {
        /* sobe servidor eco TCP em thread separada */
        int eco_fd = socket(AF_INET, SOCK_STREAM, 0);
        int eco_port = 0;
        pthread_t eco_tid = 0;
        int eco_ok = 0;


        if (eco_fd >= 0) {
            int v=1; setsockopt(eco_fd,SOL_SOCKET,SO_REUSEADDR,&v,sizeof(v));
            struct sockaddr_in esa; memset(&esa,0,sizeof(esa));
            esa.sin_family=AF_INET; esa.sin_addr.s_addr=htonl(INADDR_LOOPBACK);
            esa.sin_port=0;
            if (bind(eco_fd,(struct sockaddr*)&esa,sizeof(esa))==0 &&
                listen(eco_fd,4)==0) {
                socklen_t esl=sizeof(esa);
                getsockname(eco_fd,(struct sockaddr*)&esa,&esl);
                eco_port=ntohs(esa.sin_port);
                /* thread eco: frc_eco_thread definida acima */
                g_frc_eco_arg.fd = eco_fd;
                pthread_create(&eco_tid, NULL, frc_eco_thread, &g_frc_eco_arg);
                usleep(20000); /* 20ms para thread iniciar */
                eco_ok=1;
            }
        }

        if (!eco_ok) {
            printf("  \033[1;33m[!] servidor eco não iniciou — pulando testes de socket\033[0m\n");
            frc_result(&fr,"net.socket fire-and-forget TCP",0,0,"eco nao iniciou");
            frc_result(&fr,"socketex->sendall->recv",0,0,"eco nao iniciou");
            frc_result(&fr,"sock:wait+peek+recvline",0,0,"eco nao iniciou");
        } else {
            /* TEST 1: fire-and-forget */
            {
                t0=mst_now_ms();
                lua_getglobal(L,"net"); lua_getfield(L,-1,"socket");
                lua_pushstring(L,"ipv4"); lua_pushstring(L,"stream");
                lua_pushstring(L,"127.0.0.1"); lua_pushinteger(L,eco_port); lua_pushinteger(L,2);
                lua_pushstring(L,"HELLO_FF");
                int ok=0; char resp[64]={0};
                if(lua_pcall(L,6,2,0)==LUA_OK){
                    const char *r=lua_isstring(L,-2)?lua_tostring(L,-2):NULL;
                    if(!r&&lua_isstring(L,-1)) r=lua_tostring(L,-1);
                    if(r){strncpy(resp,r,63); ok=strstr(r,"ECHO:")!=NULL;}
                }
                lua_settop(L,base); t1=mst_now_ms();
                snprintf(det,sizeof(det),"resp=[%.40s]",resp[0]?resp:"vazio");
                frc_result(&fr,"net.socket fire-and-forget TCP",ok,t1-t0,ok?"OK":det);
            }
            /* TEST 2: socketex sendall + recv */
            {
                t0=mst_now_ms();
                lua_getglobal(L,"net"); lua_getfield(L,-1,"socketex");
                lua_pushstring(L,"ipv4"); lua_pushstring(L,"stream");
                lua_pushstring(L,"127.0.0.1"); lua_pushinteger(L,eco_port); lua_pushinteger(L,2);
                int ok=0; char echoed[64]={0};
                if(lua_pcall(L,5,2,0)==LUA_OK&&lua_type(L,-2)==LUA_TUSERDATA){
                    lua_pop(L,1);
                    lua_getfield(L,-1,"sendall"); lua_pushvalue(L,-2); lua_pushstring(L,"SENDALL_ECO");
                    int sa=(lua_pcall(L,2,1,0)==LUA_OK&&lua_isnumber(L,-1)&&lua_tointeger(L,-1)>0); lua_pop(L,1);
                    lua_getfield(L,-1,"recv"); lua_pushvalue(L,-2); lua_pushinteger(L,64);
                    if(lua_pcall(L,2,1,0)==LUA_OK&&lua_isstring(L,-1)){
                        const char*r=lua_tostring(L,-1); if(r)strncpy(echoed,r,63);
                        ok=sa&&strstr(echoed,"ECHO:")!=NULL; lua_pop(L,1);
                    } else lua_pop(L,1);
                    lua_getfield(L,-1,"close"); lua_pushvalue(L,-2); lua_pcall(L,1,0,0);
                } else lua_settop(L,base+1);
                lua_settop(L,base); t1=mst_now_ms();
                snprintf(det,sizeof(det),"sendall+recv=[%.30s]",echoed[0]?echoed:"vazio");
                frc_result(&fr,"socketex->sendall->recv",ok,t1-t0,ok?"OK":det);
            }
            /* TEST 3: wait + peek + recvline */
            {
                t0=mst_now_ms();
                lua_getglobal(L,"net"); lua_getfield(L,-1,"socketex");
                lua_pushstring(L,"ipv4"); lua_pushstring(L,"stream");
                lua_pushstring(L,"127.0.0.1"); lua_pushinteger(L,eco_port); lua_pushinteger(L,2);
                int ok=0; int wok=0,pok=0,rlok=0; size_t peek_len=0;
                if(lua_pcall(L,5,2,0)==LUA_OK&&lua_type(L,-2)==LUA_TUSERDATA){
                    lua_pop(L,1);
                    lua_getfield(L,-1,"send"); lua_pushvalue(L,-2); lua_pushstring(L,"PEEKME\n");
                    lua_pcall(L,2,1,0); lua_pop(L,1);
                    lua_getfield(L,-1,"wait"); lua_pushvalue(L,-2); lua_pushnumber(L,2.0);
                    if(lua_pcall(L,2,1,0)==LUA_OK){wok=lua_toboolean(L,-1);lua_pop(L,1);}else lua_pop(L,1);
                    lua_getfield(L,-1,"peek"); lua_pushvalue(L,-2); lua_pushinteger(L,32);
                    if(lua_pcall(L,2,1,0)==LUA_OK&&lua_isstring(L,-1)){
                        lua_tolstring(L,-1,&peek_len); pok=(peek_len>0); lua_pop(L,1);
                    } else lua_pop(L,1);
                    lua_getfield(L,-1,"recvline"); lua_pushvalue(L,-2);
                    if(lua_pcall(L,1,1,0)==LUA_OK&&lua_isstring(L,-1)){
                        rlok=strstr(lua_tostring(L,-1),"ECHO:")!=NULL; lua_pop(L,1);
                    } else lua_pop(L,1);
                    ok=wok&&pok&&rlok;
                    lua_getfield(L,-1,"close"); lua_pushvalue(L,-2); lua_pcall(L,1,0,0);
                } else lua_settop(L,base+1);
                lua_settop(L,base); t1=mst_now_ms();
                snprintf(det,sizeof(det),"wait=%d peek=%d(%dB) recvline=%d",wok,pok,(int)peek_len,rlok);
                frc_result(&fr,"sock:wait+peek+recvline",ok,t1-t0,ok?"OK":det);
            }
            /* encerra servidor eco */
            close(eco_fd);
            pthread_join(eco_tid, NULL);
        }

        /* TEST UDP — independente do servidor eco TCP */
        /* TEST UDP loopback: net.socket dgram para 127.0.0.1 */
        {
            t0=mst_now_ms();
            lua_getglobal(L,"net"); lua_getfield(L,-1,"socket");
