        else if(r==0)  snprintf(det,sizeof(det),"FALHA SILENCIOSA: nao detectou vuln no ForceServer"); \
        else           snprintf(det,sizeof(det),"%d hit(s) detectado(s)",r); \
        frc_result(&fr,label,ok,t1-t0,det); \
    } while(0)

