            CURLcode rc=curl_easy_perform(ch);
            curl_easy_cleanup(ch);
            if(rc==CURLE_OK && wb.buf && wb.len>0){
                /* Busca "49" isolado — mesmo critério do test_worker_ssti */
                char *body=wb.buf; char *p=body;
                while((p=strstr(p,"49"))!=NULL){
                    char before=(p>body)?*(p-1):' ';
                    char after=*(p+2);
                    int b_ok=!(before>='0'&&before<='9');
                    int a_ok=!(after>='0'&&after<='9');
                    if(b_ok && a_ok){ hit=1; break; }
                    p+=2;
                }
                snprintf(det,sizeof(det),"body='%.50s' 49_found=%d",wb.buf,hit);
            } else {
                snprintf(det,sizeof(det),"curl falhou rc=%d",(int)rc);
            }
        } else {
            snprintf(det,sizeof(det),"curl/malloc falhou");
        }
        free(wb.buf);
