        #define SCRIPT_TEST2(label, spath_var, argcode_var, accept_exit) \
        { \
            t0=mst_now_ms(); \
            int exists=0; { FILE *_f=fopen(spath_var,"r"); if(_f){exists=1;fclose(_f);} } \
            int ok=0; \
