                char code[2048]; \
                code[0]='\0'; \
                strncat(code, "os.exit=function(c) error('__exit__'..(tostring(c or 0)),0) end\n", sizeof(code)-strlen(code)-1); \
                strncat(code, argcode_var, sizeof(code)-strlen(code)-1); \
                strncat(code, "\n", sizeof(code)-strlen(code)-1); \
                strncat(code, "local fn,lerr=loadfile('", sizeof(code)-strlen(code)-1); \
                strncat(code, spath_var, sizeof(code)-strlen(code)-1); \
                strncat(code, "')\n", sizeof(code)-strlen(code)-1); \
                strncat(code, "if not fn then return 0,'loadfile: '..(lerr or '?') end\n", sizeof(code)-strlen(code)-1); \
                strncat(code, "local ok2,err2=pcall(fn)\n", sizeof(code)-strlen(code)-1); \
                strncat(code, "if ok2 then return 1,'ok' end\n", sizeof(code)-strlen(code)-1); \
                strncat(code, "if type(err2)=='string' then\n", sizeof(code)-strlen(code)-1); \
                strncat(code, "  if err2:find('__exit__') then return 1,'exit chamado' end\n", sizeof(code)-strlen(code)-1); \
                strncat(code, "  if err2:find('attempt to call a nil') then return 0,'nil-call: '..err2:sub(1,60) end\n", sizeof(code)-strlen(code)-1); \
                strncat(code, "  if err2:find('attempt to index a nil') then return 0,'nil-index: '..err2:sub(1,60) end\n", sizeof(code)-strlen(code)-1); \
                strncat(code, "  return 1,'err-ok: '..err2:sub(1,60)\n", sizeof(code)-strlen(code)-1); \
                strncat(code, "end\n", sizeof(code)-strlen(code)-1); \
                strncat(code, "return 0,'tipo: '..type(err2)\n", sizeof(code)-strlen(code)-1); \
                int _rc=luaL_loadstring(L, code); \
                if(_rc==LUA_OK){ \
                    int _s=mst_suppress(); \
                    _rc=lua_pcall(L,0,2,0); \
                    mst_restore(_s); \
                    if(_rc==LUA_OK){ \
