/* ══════════════════════════════════════════════════════════════════════════
   ms.alias — aliases persistentes que viram globals Lua

   ms.alias("NET", "net.geth()")   → NET("google.com") chama net.geth("google.com")
   ms.alias("SCAN", "net.scan(..., 1, 9999)") → SCAN("host") usa ... direto
   ms.alias("nome")                → executa alias (sem args)
   ms.alias()                      → lista todos
   ms.alias("nome", nil)           → remove alias e global

   Regra de injeção de args:
     - código termina com "()"  → injeta args:  foo() → foo(...)
     - código já contém "..."   → passa ... direto
     - caso contrário           → wrappa em function(...) codigo end
   ══════════════════════════════════════════════════════════════════════════ */

#define ALIAS_FILE "/.elliotai/aliases.lua"

static const char *alias_path(char *buf, size_t sz) {
    const char *home = getenv("HOME");
    if (!home) home = "/data/data/com.termux/files/home";
    snprintf(buf, sz, "%s%s", home, ALIAS_FILE);
    return buf;
}

/* Lê aliases do disco → empilha tabela {nome=codigo} no topo */
static void alias_load_table(lua_State *L) {
    char path[512];
    alias_path(path, sizeof(path));
    lua_newtable(L);                        /* t = {}              [top] */
    FILE *f = fopen(path, "r");
    if (!f) return;
    /* lê linha a linha: alias["key"] = "val" */
    char line[4096];
    while (fgets(line, sizeof(line), f)) {
        /* procura alias["KEY"] = "VAL" */
        char *ks = strstr(line, "alias[\"");
        if (!ks) continue;
        ks += 7;
        char *ke = strstr(ks, "\"]");
        if (!ke) continue;
        *ke = '\0';
        char *vs = strstr(ke+2, " = \"");
        if (!vs) continue;
        vs += 4;
        size_t vlen = strlen(vs);
        if (vlen > 0 && vs[vlen-1] == '\n') vs[--vlen] = '\0';
        if (vlen > 0 && vs[vlen-1] == '"')  vs[--vlen] = '\0';
        /* unescape \\ e \" */
        char val[4096]; size_t vi = 0;
        for (size_t i = 0; i < vlen && vi < sizeof(val)-1; i++) {
            if (vs[i] == '\\' && i+1 < vlen) { i++; val[vi++] = vs[i]; }
            else val[vi++] = vs[i];
        }
        val[vi] = '\0';
        lua_pushstring(L, val);
        lua_setfield(L, -2, ks);            /* t[key] = val */
    }
    fclose(f);
}

/* Salva tabela (índice tbl_idx) em disco */
static void alias_save_table(lua_State *L, int tbl_idx) {
    char path[512], dir[512];
    alias_path(path, sizeof(path));
    const char *home = getenv("HOME");
    if (!home) home = "/data/data/com.termux/files/home";
    snprintf(dir, sizeof(dir), "%s/.elliotai", home);
    struct stat st;
    if (stat(dir, &st) != 0) mkdir(dir, 0755);
    FILE *f = fopen(path, "w");
    if (!f) return;
    fprintf(f, "-- ElliotOS aliases (gerado automaticamente)\n");
    lua_pushnil(L);
    while (lua_next(L, tbl_idx)) {
        if (lua_type(L,-2)==LUA_TSTRING && lua_type(L,-1)==LUA_TSTRING) {
            const char *k = lua_tostring(L,-2);
            const char *v = lua_tostring(L,-1);
            fprintf(f, "alias[\"");
            for (const char *p=k; *p; p++) { if(*p=='"'||*p=='\\') fputc('\\',f); fputc(*p,f); }
            fprintf(f, "\"] = \"");
            for (const char *p=v; *p; p++) { if(*p=='"'||*p=='\\') fputc('\\',f); fputc(*p,f); }
            fprintf(f, "\"\n");
        }
        lua_pop(L,1);
    }
    fclose(f);
}

/* Gera wrapper Lua para o código do alias com suporte a args.
   Resultado: string com "function(...) <codigo_adaptado> end"
   Regras:
     1) código contém "..."      → function(...) codigo end
     2) código termina em "()"   → injeta ...: foo() → foo(...)
     3) caso contrário           → function(...) codigo end  (sem injeção) */
static void alias_make_wrapper(const char *code, char *out, size_t outsz) {
    int has_vararg = (strstr(code, "...") != NULL);
    /* termina com "()" vazio ignorando espaço */
    const char *e = code + strlen(code) - 1;
    while (e > code && (*e == ' ' || *e == '\t' || *e == '\n')) e--;
    int ends_empty_call = (e > code && *e == ')' && *(e-1) == '(');

    if (ends_empty_call && !has_vararg) {
        /* net.geth() → pega referência da função e wrappa */
        size_t base_len = (size_t)(e - 1 - code);
        char base[4096];
        if (base_len >= sizeof(base)) base_len = sizeof(base)-1;
        memcpy(base, code, base_len);
        base[base_len] = '\0';
        /* usa select('#',...) para passar N args corretamente */
        snprintf(out, outsz,
            "do local _fn=%s "
            "return function(...) return _fn(...) end "
            "end",
            base);
    } else {
        /* tem ... ou não tem () — wrappa como expressão */
        snprintf(out, outsz,
            "do return function(...) return %s end end",
            code);
    }
}

/* Registra alias como global Lua (função callable) */
static void alias_register_global(lua_State *L, const char *name, const char *code) {
    char wrapper[8192];
    alias_make_wrapper(code, wrapper, sizeof(wrapper));
    if (luaL_loadstring(L, wrapper) != LUA_OK) {
        lua_pop(L, 1); /* descarta erro — sintaxe ruim */
        return;
    }
    if (lua_pcall(L, 0, 1, 0) != LUA_OK) {
        lua_pop(L, 1);
        return;
    }
    lua_setglobal(L, name);     /* _G[name] = function(...) ... end */
}

/* Chamado na inicialização: carrega todos aliases salvos como globals */
static void alias_boot(lua_State *L) {
    alias_load_table(L);
    int tbl = lua_gettop(L);
    lua_pushnil(L);
    while (lua_next(L, tbl)) {
        if (lua_type(L,-2)==LUA_TSTRING && lua_type(L,-1)==LUA_TSTRING) {
            alias_register_global(L, lua_tostring(L,-2), lua_tostring(L,-1));
        }
        lua_pop(L,1);
    }
    lua_pop(L,1); /* remove tabela */
}

static int l_ms_alias(lua_State *L) {
    int nargs = lua_gettop(L);

    /* ms.alias() — lista todos */
    if (nargs == 0) {
        alias_load_table(L);
        int tbl = lua_gettop(L);
        int count = 0;
        printf("\n\033[1;35m╔══════════════════════════════════════════════╗\033[0m\n");
        printf("\033[1;35m║  ms.alias — aliases / globals                ║\033[0m\n");
        printf("\033[1;35m╚══════════════════════════════════════════════╝\033[0m\n\n");
        lua_pushnil(L);
        while (lua_next(L, tbl)) {
            if (lua_type(L,-2)==LUA_TSTRING && lua_type(L,-1)==LUA_TSTRING) {
                printf("  \033[1;33m%-20s\033[0m → \033[0;36m%s\033[0m\n",
                    lua_tostring(L,-2), lua_tostring(L,-1));
                count++;
            }
            lua_pop(L,1);
        }
        if (count == 0)
            printf("  \033[0;90m(nenhum alias definido ainda)\033[0m\n");
        printf("\n  \033[0;90mUso: ms.alias(\"NOME\", \"codigo()\")  — criar global\033[0m\n");
        printf("  \033[0;90m     NOME(args)                     — chamar\033[0m\n");
        printf("  \033[0;90m     ms.alias(\"NOME\", nil)          — remover\033[0m\n\n");
        lua_pop(L,1);
        return 0;
    }

    luaL_checkstring(L, 1);
    const char *name = lua_tostring(L, 1);

    /* ms.alias("nome") — executa sem args */
    if (nargs == 1) {
        alias_load_table(L);
        int tbl = lua_gettop(L);
        lua_getfield(L, tbl, name);
        if (lua_isnil(L,-1)) {
            lua_pop(L,2);
            return luaL_error(L, "alias '%s' nao encontrado", name);
        }
        const char *code = lua_tostring(L,-1);
        char wrapper[8192];
        alias_make_wrapper(code, wrapper, sizeof(wrapper));
        int r = luaL_loadstring(L, wrapper);
        if (r != LUA_OK) { const char *e=lua_tostring(L,-1); lua_pop(L,3); return luaL_error(L,"%s",e); }
        lua_pcall(L, 0, 1, 0);
        lua_call(L, 0, LUA_MULTRET);
        return lua_gettop(L) - tbl;
    }

    /* ms.alias("nome", nil/false) — remove */
    if (nargs >= 2 && (lua_isnil(L,2) || (lua_isboolean(L,2) && !lua_toboolean(L,2)))) {
        alias_load_table(L);
        int tbl = lua_gettop(L);
        lua_pushnil(L); lua_setfield(L, tbl, name);
        alias_save_table(L, tbl);
        lua_pop(L,1);
        /* remove global */
        lua_pushnil(L); lua_setglobal(L, name);
        printf("  \033[1;32m✓\033[0m alias/global '\033[1;33m%s\033[0m' removido\n", name);
        return 0;
    }

    /* ms.alias("nome", "codigo") — cria/atualiza */
    if (nargs >= 2 && lua_isstring(L,2)) {
        const char *code = lua_tostring(L,2);
        /* valida sintaxe do wrapper antes de salvar */
        char wrapper[8192];
        alias_make_wrapper(code, wrapper, sizeof(wrapper));
        int r = luaL_loadstring(L, wrapper);
        if (r != LUA_OK) {
            const char *err = lua_tostring(L,-1); lua_pop(L,1);
            return luaL_error(L, "sintaxe invalida: %s", err);
        }
        lua_pop(L,1);
        /* salva no disco */
        alias_load_table(L);
        int tbl = lua_gettop(L);
        lua_pushstring(L, code); lua_setfield(L, tbl, name);
        alias_save_table(L, tbl);
        lua_pop(L,1);
        /* registra global imediatamente */
        alias_register_global(L, name, code);
        printf("  \033[1;32m✓\033[0m alias '\033[1;33m%s\033[0m' salvo e registrado como global\n", name);
        return 0;
    }

    return luaL_error(L, "uso: ms.alias(NOME[, codigo])");
}

static int l_ms_help(lua_State *L) {
    /* ms.help('modulo') — help específico por módulo */
    if (lua_gettop(L) >= 1 && lua_type(L, 1) == LUA_TSTRING) {
        const char *mod = lua_tostring(L, 1);
        /* Dispatch para help de cada módulo global */
        lua_getglobal(L, mod);
        if (!lua_isnil(L, -1)) {
            lua_getfield(L, -1, "help");
            if (lua_isfunction(L, -1)) {
                if (lua_pcall(L, 0, 0, 0) != LUA_OK) {
                    fprintf(stderr, "  \033[1;31m✗\033[0m %s.help() erro: %s\n",
                            mod, lua_tostring(L, -1));
                    lua_pop(L, 1);
                }
                return 0;
