/* ============================================================================
   db.* — SQLite3 global implícito
   db.open(path)       — abre/cria banco
   db.close()          — fecha
   db.exec(sql)        — executa sem retorno (CREATE, INSERT, UPDATE, DELETE)
   db.query(sql)       — SELECT → tabela Lua [{col=val,...}, ...]
   db.tables()         — lista tabelas
   db.help()
   ============================================================================ */

static sqlite3 *g_db = NULL;

static int l_db_open(lua_State *L) {
    const char *path = luaL_checkstring(L,1);
    if(g_db){ sqlite3_close(g_db); g_db=NULL; }
    int rc = sqlite3_open(path, &g_db);
    if(rc != SQLITE_OK){
        printf("\033[1;31m[!] db.open: %s\033[0m\n", sqlite3_errmsg(g_db));
        sqlite3_close(g_db); g_db=NULL;
        lua_pushboolean(L,0); return 1;
    }
    printf("\033[1;32m[✓] db: %s\033[0m\n", path);
    lua_pushboolean(L,1); return 1;
}

static int l_db_close(lua_State *L) {
    (void)L;
    if(g_db){ sqlite3_close(g_db); g_db=NULL; printf("\033[0;90m[db] fechado\033[0m\n"); }
    return 0;
}

static int l_db_exec(lua_State *L) {
    if(!g_db){ lua_pushboolean(L,0); lua_pushstring(L,"db não aberto — use db.open(path)"); return 2; }
    const char *sql = luaL_checkstring(L,1);
    char *err=NULL;
    int rc = sqlite3_exec(g_db, sql, NULL, NULL, &err);
    if(rc != SQLITE_OK){
        printf("\033[1;31m[!] db.exec: %s\033[0m\n", err);
        lua_pushboolean(L,0); lua_pushstring(L,err);
        sqlite3_free(err); return 2;
    }
    lua_pushboolean(L,1); return 1;
}

static int l_db_query(lua_State *L) {
    if(!g_db){ lua_newtable(L); lua_pushstring(L,"db não aberto"); return 2; }
    const char *sql = luaL_checkstring(L,1);
    sqlite3_stmt *stmt=NULL;
    if(sqlite3_prepare_v2(g_db,sql,-1,&stmt,NULL) != SQLITE_OK){
        printf("\033[1;31m[!] db.query: %s\033[0m\n", sqlite3_errmsg(g_db));
        lua_newtable(L); return 1;
    }
    lua_newtable(L); /* array de rows */
    int row=0;
    while(sqlite3_step(stmt)==SQLITE_ROW){
        row++;
        lua_newtable(L); /* row table */
        int cols=sqlite3_column_count(stmt);
        for(int c=0;c<cols;c++){
            const char *name=sqlite3_column_name(stmt,c);
            int type=sqlite3_column_type(stmt,c);
            if(type==SQLITE_INTEGER) lua_pushinteger(L,sqlite3_column_int64(stmt,c));
            else if(type==SQLITE_FLOAT) lua_pushnumber(L,sqlite3_column_double(stmt,c));
            else if(type==SQLITE_NULL) lua_pushnil(L);
            else lua_pushstring(L,(const char*)sqlite3_column_text(stmt,c));
            lua_setfield(L,-2,name);
        }
        lua_rawseti(L,-2,row);
    }
    sqlite3_finalize(stmt);
    return 1;
}

static int l_db_tables(lua_State *L) {
    lua_pushstring(L,"SELECT name FROM sqlite_master WHERE type='table' ORDER BY name");
    return l_db_query(L);
}

