/* ============================================================================
   mod.graphql — GraphQL introspection + field enumeration
   ============================================================================ */

static int l_mod_graphql(lua_State *L) {
    const char *url_raw = luaL_checkstring(L,1);
    char url[1024]={0};
    { const char *u=normalize_url(url_raw,url,sizeof(url)); (void)u; }

    printf("\n\033[1;35m╔═══════════════════════════════════════╗\033[0m\n");
