/* luaopen_net_thread — para threads Lua isoladas: sem readline/AI db/RP db */
/* Parseia string para CIDR: aceita "192.168.1.0/24", "192.168.1", "192.168.1.5" */


/* ── net.ip: SYN discovery + port scan — igual ao net.scan mas para CIDRs ──
 *
 *  net.ip()                          → descobre rede local, probe portas comuns
 *  net.ip("192.168.1.0/24")             → dado CIDR, probe portas comuns
 *  net.ip("192.168.1.0/24", 1, 1024) → dado CIDR, SYN scan portas 1-1024
 *  net.ip(1, 1024)                   → auto CIDR, SYN scan portas 1-1024
 *
 *  Fase 1 (discovery): SYN probe em portas comuns em batch de 512 hosts
 *                      simultaneamente — RST ou SYN-ACK = host vivo.
 *  Fase 2 (scan):      SYN scan do range [from,to] só nos hosts vivos.
 * ─────────────────────────────────────────────────────────────────────────── */
static int parse_cidr(const char *s, uint32_t *base, int *prefix) {
    char buf[64]; strncpy(buf, s, 63); buf[63]='\0';
    char *slash = strchr(buf, '/');
    *prefix = 24;
    if (slash) { *slash='\0'; *prefix = atoi(slash+1); }
    else {
        /* conta octetos — "192.168.1" → /24, "192.168" → /16 */
        int dots=0; for (char *p=buf; *p; p++) if (*p=='.') dots++;
        if (dots==1) *prefix=16;
        else if (dots==2) *prefix=24;
        else *prefix=24; /* IP completo → /24 da subnet */
    }
    /* completa octetos faltantes com zero */
    char full[24]={0}; int dots=0;
    for (char *p=buf;*p;p++) if(*p=='.') dots++;
    if (dots==1) snprintf(full,sizeof(full),"%s.0.0",buf);
    else if (dots==2) snprintf(full,sizeof(full),"%s.0",buf);
    else strncpy(full,buf,23);
    struct in_addr a;
    if (inet_pton(AF_INET, full, &a) != 1) return 0;
    *base = ntohl(a.s_addr);
    return 1;
}

/* ── net.os(host) — OS/device fingerprint sem root ──────────────────────────
 * Funciona com IP local ou domínio.
 * Para IPs locais: TTL via ping + port pattern.
 * Para domínios/IPs externos: DNS resolve + HTTP/HTTPS headers + port pattern.
 * Retorna tabela: {host, ip, ttl, os_hint, type, ports, server, confidence}
 * ─────────────────────────────────────────────────────────────────────────── */

/* portas top usadas no fingerprint */
static const int NET_OS_PORTS[] = {
    21, 22, 23, 25, 53, 80, 110, 135, 139, 143,
    443, 445, 554, 3306, 3389, 5000, 8080, 8443, 8888, 9090
};
#define NET_OS_NPORTS 20
#define NET_OS_TIMEOUT_MS 600

/* conecta não-bloqueante, retorna 1 se aberta */
static int nos_port_open(struct sockaddr_in *sa, int port) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) return 0;
    int fl = fcntl(fd, F_GETFL, 0); if (fl < 0) fl = 0;
    fcntl(fd, F_SETFL, fl | O_NONBLOCK);
    struct sockaddr_in dst = *sa;
    dst.sin_port = htons((uint16_t)port);
    connect(fd, (struct sockaddr*)&dst, sizeof(dst));
    struct pollfd pf; pf.fd = fd; pf.events = POLLOUT|POLLERR; pf.revents = 0;
    poll(&pf, 1, NET_OS_TIMEOUT_MS);
    int open = 0;
    if (pf.revents & POLLOUT) {
        int err = 0; socklen_t el = sizeof(err);
        getsockopt(fd, SOL_SOCKET, SO_ERROR, &err, &el);
        open = (err == 0);
    }
    close(fd);
    return open;
}

/* tenta pegar banner HTTP (HEAD /) — retorna 1 se obteve algo */
static int nos_http_banner(const char *host, int port,
                           char *server_out, int server_sz,
                           char *powered_out, int powered_sz) {
    server_out[0] = powered_out[0] = '\0';
    struct addrinfo hints, *res = NULL;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; hints.ai_socktype = SOCK_STREAM;
    char ps[8]; snprintf(ps, sizeof(ps), "%d", port);
    if (getaddrinfo(host, ps, &hints, &res) != 0 || !res) return 0;

    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) { freeaddrinfo(res); return 0; }
    struct timeval tv; tv.tv_sec = 2; tv.tv_usec = 0;
    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
    setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));

    int connected = (connect(fd, res->ai_addr, res->ai_addrlen) == 0);
    freeaddrinfo(res);
    if (!connected) { close(fd); return 0; }

    /* envia HEAD */
    char req[512];
    snprintf(req, sizeof(req),
        "HEAD / HTTP/1.0\r\nHost: %s\r\nUser-Agent: curl/7.88\r\nConnection: close\r\n\r\n",
        host);
    send(fd, req, strlen(req), 0);

    /* lê resposta */
    char buf[2048] = {0};
    int total = 0, n;
    while (total < (int)sizeof(buf)-1) {
        n = (int)recv(fd, buf+total, sizeof(buf)-1-total, 0);
        if (n <= 0) break;
        total += n;
    }
    close(fd);
    buf[total] = '\0';

    /* extrai Server: */
    char *sv = strcasestr(buf, "\r\nServer:");
    if (!sv) sv = strcasestr(buf, "\nServer:");
    if (sv) {
        sv = strchr(sv, ':'); if (sv) sv++;
        while (*sv == ' ') sv++;
        int i = 0;
        while (*sv && *sv != '\r' && *sv != '\n' && i < server_sz-1)
            server_out[i++] = *sv++;
        server_out[i] = '\0';
    }

    /* extrai X-Powered-By: */
    char *pw = strcasestr(buf, "\r\nX-Powered-By:");
    if (!pw) pw = strcasestr(buf, "\nX-Powered-By:");
    if (pw) {
        pw = strchr(pw, ':'); if (pw) pw++;
        while (*pw == ' ') pw++;
        int i = 0;
        while (*pw && *pw != '\r' && *pw != '\n' && i < powered_sz-1)
            powered_out[i++] = *pw++;
        powered_out[i] = '\0';
    }

    return (server_out[0] || powered_out[0]) ? 1 : (total > 0 ? 1 : 0);
}

/* lê TTL do ping — retorna -1 se falhou */
static int nos_get_ttl(const char *host) {
    char cmd[320];
    /* sanitiza host */
    char safe[256] = {0}; int j = 0;
    for (int i = 0; host[i] && j < 255; i++) {
        char c = host[i];
        if ((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||
             c=='.'||c=='-'||c=='_'||c==':'||c=='['||c==']') safe[j++]=c;
    }
    if (!j) return -1;
    snprintf(cmd, sizeof(cmd),
        "ping -c1 -W1 '%s' 2>/dev/null | grep -oE 'ttl=[0-9]+' | head -1", safe);
    FILE *fp = popen(cmd, "r");
    if (!fp) return -1;
    char line[64] = {0};
    fgets(line, sizeof(line), fp);
    pclose(fp);
    if (!line[0]) return -1;
    char *eq = strchr(line, '=');
    return eq ? atoi(eq+1) : -1;
}

/* infere OS/tipo pelo TTL */
static void nos_ttl_hint(int ttl, char *os_buf, int os_sz, char *type_buf, int type_sz) {
    if (ttl <= 0) {
        snprintf(os_buf,  os_sz,   "desconhecido");
        snprintf(type_buf,type_sz, "unknown");
    } else if (ttl <= 64) {
        snprintf(os_buf,  os_sz,   "Linux / Android / Router");
        snprintf(type_buf,type_sz, "linux");
    } else if (ttl <= 128) {
        snprintf(os_buf,  os_sz,   "Windows");
        snprintf(type_buf,type_sz, "windows");
    } else {
        snprintf(os_buf,  os_sz,   "iOS / macOS / Router Cisco");
        snprintf(type_buf,type_sz, "apple");
    }
}

/* refina type pelo padrão de portas abertas */
static void nos_refine_by_ports(int *open, int nopen,
                                char *os_buf, int os_sz,
                                char *type_buf, int type_sz,
                                char *conf_buf, int conf_sz) {
    int has80=0,has443=0,has22=0,has445=0,has3389=0,has23=0,
        has21=0,has3306=0,has8080=0,has8443=0,has554=0,has53=0;
    for (int i=0;i<nopen;i++) {
        int p=open[i];
        if(p==80)   has80=1;   if(p==443)  has443=1;
        if(p==22)   has22=1;   if(p==445)  has445=1;
        if(p==3389) has3389=1; if(p==23)   has23=1;
        if(p==21)   has21=1;   if(p==3306) has3306=1;
        if(p==8080) has8080=1; if(p==8443) has8443=1;
        if(p==554)  has554=1;  if(p==53)   has53=1;
    }

    if (nopen == 0) {
        snprintf(conf_buf, conf_sz, "baixa");
        return;
    }

    /* Windows: 445 ou 3389 são muito específicos */
    if (has445 || has3389) {
        snprintf(os_buf,   os_sz,   "Windows");
        snprintf(type_buf, type_sz, "windows");
        snprintf(conf_buf, conf_sz, has3389 ? "alta" : "média");
        return;
    }
    /* câmera / DVR: RTSP 554 */
    if (has554) {
        snprintf(os_buf,   os_sz,   "Câmera IP / DVR");
        snprintf(type_buf, type_sz, "camera");
        snprintf(conf_buf, conf_sz, "alta");
        return;
    }
    /* Telnet puro sem web = dispositivo legado IoT */
    if (has23 && !has80 && !has443) {
        snprintf(os_buf,   os_sz,   "IoT / Dispositivo legado (Telnet)");
        snprintf(type_buf, type_sz, "iot");
        snprintf(conf_buf, conf_sz, "média");
        return;
    }
    /* FTP + web = NAS */
    if (has21 && (has80||has443)) {
        snprintf(os_buf,   os_sz,   "NAS / Servidor de arquivos");
        snprintf(type_buf, type_sz, "nas");
        snprintf(conf_buf, conf_sz, "média");
        return;
    }
    /* DNS = resolver/router */
    if (has53) {
        snprintf(os_buf,   os_sz,   "Router / DNS server");
        snprintf(type_buf, type_sz, "router");
        snprintf(conf_buf, conf_sz, "média");
        return;
    }
    /* web sem SSH = router ou servidor simples */
    if ((has80||has443||has8080||has8443) && !has22) {
        snprintf(os_buf,   os_sz,   "Router / Appliance web");
        snprintf(type_buf, type_sz, "router");
        snprintf(conf_buf, conf_sz, "média");
        return;
    }
    /* web + SSH = servidor Linux */
    if ((has80||has443) && has22) {
        snprintf(os_buf,   os_sz,   "Linux (servidor web + SSH)");
        snprintf(type_buf, type_sz, "linux");
        snprintf(conf_buf, conf_sz, "alta");
        return;
    }
    /* só SSH */
    if (has22) {
        snprintf(os_buf,   os_sz,   "Linux / Unix (SSH)");
        snprintf(type_buf, type_sz, "linux");
        snprintf(conf_buf, conf_sz, "média");
        return;
    }
    /* DB exposto */
    if (has3306) {
        snprintf(os_buf,   os_sz,   "Linux (MySQL exposto)");
        snprintf(type_buf, type_sz, "linux");
        snprintf(conf_buf, conf_sz, "média");
        return;
    }
    snprintf(conf_buf, conf_sz, "baixa");
}

/* refina pelo Server: header HTTP */
static void nos_refine_by_server(const char *server, const char *powered,
                                 char *os_buf, int os_sz,
                                 char *type_buf, int type_sz,
                                 char *conf_buf, int conf_sz) {
    if (!server[0] && !powered[0]) return;
    const char *s = server[0] ? server : "";
    const char *p = powered[0] ? powered : "";

    /* CDN / proxy */
    if (strcasestr(s,"cloudflare")||strcasestr(s,"akamai")||
        strcasestr(s,"fastly")||strcasestr(s,"cdn")) {
        snprintf(os_buf,   os_sz,   "CDN (%s)", s);
        snprintf(type_buf, type_sz, "cdn");
        snprintf(conf_buf, conf_sz, "alta");
        return;
    }
    /* IIS = Windows */
    if (strcasestr(s,"iis") || strcasestr(s,"microsoft")) {
        snprintf(os_buf,   os_sz,   "Windows (IIS)");
        snprintf(type_buf, type_sz, "windows");
        snprintf(conf_buf, conf_sz, "alta");
        return;
    }
    /* Apache/nginx/caddy = Linux provavelmente */
    if (strcasestr(s,"apache")||strcasestr(s,"nginx")||
        strcasestr(s,"caddy")||strcasestr(s,"lighttpd")) {
        snprintf(os_buf,   os_sz,   "Linux (%s)", s);
        snprintf(type_buf, type_sz, "linux");
        snprintf(conf_buf, conf_sz, "alta");
        return;
    }
    /* linguagem no Powered-By */
    if (strcasestr(p,"php"))   { snprintf(os_buf,os_sz,"Linux/PHP (%s)",s[0]?s:"?"); snprintf(type_buf,type_sz,"linux"); snprintf(conf_buf,conf_sz,"alta"); return; }
    if (strcasestr(p,"asp"))   { snprintf(os_buf,os_sz,"Windows/ASP.NET"); snprintf(type_buf,type_sz,"windows"); snprintf(conf_buf,conf_sz,"alta"); return; }
    if (strcasestr(p,"express")||strcasestr(p,"node")) { snprintf(os_buf,os_sz,"Linux/Node.js (%s)",s[0]?s:"?"); snprintf(type_buf,type_sz,"linux"); snprintf(conf_buf,conf_sz,"alta"); return; }
}

static int l_net_os(lua_State *L) {
    const char *raw = luaL_checkstring(L, 1);

    /* sanitiza — remove http:// https:// e path */
    char host[256] = {0};
    const char *p = raw;
    if (strncmp(p,"http://",7)==0)  p+=7;
    if (strncmp(p,"https://",8)==0) p+=8;
    int i=0;
    while (*p && *p!='/' && *p!='?' && i<255) host[i++]=*p++;
    host[i]='\0';
    if (!host[0]) { lua_pushnil(L); lua_pushstring(L,"host inválido"); return 2; }

    printf("\n\033[1;36m[net.os]\033[0m \033[1;37m%s\033[0m\n", host);
    printf("\033[0;90m────────────────────────────────────────\033[0m\n");

    /* ── 1. Resolve IP ─────────────────────────────────────────────── */
    char ip_str[INET_ADDRSTRLEN] = {0};
    struct sockaddr_in resolved_sa;
    memset(&resolved_sa, 0, sizeof(resolved_sa));
    resolved_sa.sin_family = AF_INET;

    struct addrinfo hints, *res0 = NULL;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; hints.ai_socktype = SOCK_STREAM;
    if (getaddrinfo(host, "80", &hints, &res0) == 0 && res0) {
        memcpy(&resolved_sa.sin_addr,
               &((struct sockaddr_in*)res0->ai_addr)->sin_addr,
               sizeof(resolved_sa.sin_addr));
        inet_ntop(AF_INET, &resolved_sa.sin_addr, ip_str, sizeof(ip_str));
        freeaddrinfo(res0);
    }
    if (!ip_str[0]) {
        printf("\033[1;31m[!] Não resolveu '%s'\033[0m\n\n", host);
        lua_pushnil(L); lua_pushstring(L,"não resolveu host"); return 2;
    }
    int is_domain = (strcmp(host, ip_str) != 0);
    printf("  \033[0;90mIP:\033[0m        \033[1;37m%s\033[0m\n", ip_str);

    /* ── 2. TTL ────────────────────────────────────────────────────── */
    printf("  \033[0;90mPing...\033[0m\n");
    int ttl = nos_get_ttl(host);
    char os_hint[128]  = "desconhecido";
    char type_str[64]  = "unknown";
    char conf_str[32]  = "baixa";

    if (ttl > 0)
        printf("  \033[0;90mTTL:\033[0m       \033[1;33m%d\033[0m\n", ttl);
    else
        printf("  \033[0;90mTTL:\033[0m       \033[0;90msem resposta\033[0m\n");

    nos_ttl_hint(ttl, os_hint, sizeof(os_hint), type_str, sizeof(type_str));

    /* ── 3. Port scan top ports ────────────────────────────────────── */
    printf("  \033[0;90mPort scan (%d portas)...\033[0m\n", NET_OS_NPORTS);

    int open_ports[NET_OS_NPORTS];
    int nopen = 0;

    /* batch único com poll */
    int fds[NET_OS_NPORTS];
    struct pollfd pfds[NET_OS_NPORTS];
    for (int k = 0; k < NET_OS_NPORTS; k++) {
        fds[k] = socket(AF_INET, SOCK_STREAM, 0);
        pfds[k].fd = fds[k]; pfds[k].events = POLLOUT|POLLERR; pfds[k].revents = 0;
        if (fds[k] < 0) continue;
        int fl = fcntl(fds[k], F_GETFL, 0); if (fl < 0) fl = 0;
        fcntl(fds[k], F_SETFL, fl | O_NONBLOCK);
        struct sockaddr_in dst = resolved_sa;
        dst.sin_port = htons((uint16_t)NET_OS_PORTS[k]);
        connect(fds[k], (struct sockaddr*)&dst, sizeof(dst));
    }
    poll(pfds, NET_OS_NPORTS, NET_OS_TIMEOUT_MS + 200);
    for (int k = 0; k < NET_OS_NPORTS; k++) {
        if (fds[k] < 0) continue;
        if (pfds[k].revents & POLLOUT) {
            int err = 0; socklen_t el = sizeof(err);
            getsockopt(fds[k], SOL_SOCKET, SO_ERROR, &err, &el);
            if (err == 0) open_ports[nopen++] = NET_OS_PORTS[k];
        }
        close(fds[k]);
    }

    if (nopen > 0) {
        printf("  \033[0;90mPortas:\033[0m    \033[1;32m");
        for (int k = 0; k < nopen; k++) printf("%d%s", open_ports[k], k<nopen-1?", ":"");
        printf("\033[0m\n");
    } else {
        printf("  \033[0;90mPortas:\033[0m    \033[0;90mnenhuma das top-%d aberta\033[0m\n", NET_OS_NPORTS);
    }

    /* refina pelo padrão de portas */
    nos_refine_by_ports(open_ports, nopen,
                        os_hint, sizeof(os_hint),
                        type_str, sizeof(type_str),
                        conf_str, sizeof(conf_str));

    /* ── 4. HTTP banner (porta 80 ou 8080 ou 443) ──────────────────── */
    char server_hdr[128]  = {0};
    char powered_hdr[128] = {0};
    int http_ok = 0;

    /* tenta 80, 8080, 443 em ordem */
    int http_ports[] = {80, 8080, 443, 8443};
    for (int k = 0; k < 4 && !http_ok; k++) {
        /* só tenta se a porta estava aberta ou é domínio externo */
        int was_open = 0;
        for (int j = 0; j < nopen; j++) if (open_ports[j]==http_ports[k]) { was_open=1; break; }
        if (!was_open && !is_domain) continue;
        if (was_open || is_domain)
            http_ok = nos_http_banner(host, http_ports[k],
                                      server_hdr, sizeof(server_hdr),
                                      powered_hdr, sizeof(powered_hdr));
    }

    if (server_hdr[0])
        printf("  \033[0;90mServer:\033[0m    \033[1;37m%s\033[0m\n", server_hdr);
    if (powered_hdr[0])
        printf("  \033[0;90mPowered:\033[0m   \033[1;37m%s\033[0m\n", powered_hdr);

    /* refina pelo Server header — pode sobrescrever inferência de portas */
    nos_refine_by_server(server_hdr, powered_hdr,
                         os_hint, sizeof(os_hint),
                         type_str, sizeof(type_str),
                         conf_str, sizeof(conf_str));

    /* ── 5. Output final ───────────────────────────────────────────── */
    const char *conf_color =
        strcmp(conf_str,"alta")==0   ? "\033[1;32m" :
        strcmp(conf_str,"média")==0  ? "\033[1;33m" : "\033[1;31m";

    printf("\033[0;90m────────────────────────────────────────\033[0m\n");
    printf("  \033[1;36mOS/Tipo:\033[0m   \033[1;37m%s\033[0m\n", os_hint);
    printf("  \033[1;36mConf.:\033[0m     %s%s\033[0m\n\n", conf_color, conf_str);

    /* ── retorna tabela Lua ─────────────────────────────────────────── */
    lua_newtable(L);

    lua_pushstring(L, host);       lua_setfield(L, -2, "host");
    lua_pushstring(L, ip_str);     lua_setfield(L, -2, "ip");
    lua_pushinteger(L, ttl);       lua_setfield(L, -2, "ttl");
    lua_pushstring(L, os_hint);    lua_setfield(L, -2, "os_hint");
    lua_pushstring(L, type_str);   lua_setfield(L, -2, "type");
    lua_pushstring(L, conf_str);   lua_setfield(L, -2, "confidence");
    if (server_hdr[0])  { lua_pushstring(L, server_hdr);  lua_setfield(L, -2, "server"); }
    if (powered_hdr[0]) { lua_pushstring(L, powered_hdr); lua_setfield(L, -2, "powered"); }

    /* sub-tabela ports */
    lua_newtable(L);
    for (int k = 0; k < nopen; k++) {
        lua_pushinteger(L, open_ports[k]);
        lua_rawseti(L, -2, k+1);
    }
    lua_setfield(L, -2, "ports");

    return 1;
}

/* ── net_detect_local_cidr ────────────────────────────────────────────────────
   Detecta a rede local via getifaddrs() (C direto, sem shell).
   Pula loopback (127.x) e link-local (169.254.x).
   Retorna 1 e preenche *out com "a.b.c.d/prefix", ou 0 se falhou.
   ─────────────────────────────────────────────────────────────────────────── */
static int net_detect_local_cidr(char *out, size_t outsz) {
    struct ifaddrs *ifa_list = NULL;
    if (getifaddrs(&ifa_list) != 0) return 0;
    int found = 0;
    for (struct ifaddrs *ifa = ifa_list; ifa && !found; ifa = ifa->ifa_next) {
        if (!ifa->ifa_addr   || ifa->ifa_addr->sa_family   != AF_INET) continue;
        if (!ifa->ifa_netmask|| ifa->ifa_netmask->sa_family != AF_INET) continue;
        struct sockaddr_in *sin  = (struct sockaddr_in*)ifa->ifa_addr;
        struct sockaddr_in *smsk = (struct sockaddr_in*)ifa->ifa_netmask;
        uint32_t ip = ntohl(sin->sin_addr.s_addr);
        uint32_t nm = ntohl(smsk->sin_addr.s_addr);
        uint8_t  o1 = (ip >> 24) & 0xFF;
        uint8_t  o2 = (ip >> 16) & 0xFF;
        if (o1 == 127)              continue;
        if (o1 == 169 && o2 == 254) continue;
        int prefix = __builtin_popcount(nm);
        if (prefix < 8 || prefix > 30) continue;
        uint32_t net = ip & nm;
        snprintf(out, outsz, "%u.%u.%u.%u/%d",
            (net>>24)&0xFF, (net>>16)&0xFF, (net>>8)&0xFF, net&0xFF, prefix);
        found = 1;
    }
    freeifaddrs(ifa_list);
    return found;
}


static int l_net_scan_hosts(lua_State *L) {
    char cidr_str[64] = {0};
    int from = 0, to = 0;

    int nargs = lua_gettop(L);
    if (nargs >= 1) {
        if (lua_isnil(L, 1)) {
            /* net.ip(nil, from, to) — auto CIDR, portas explícitas */
            if (nargs >= 2 && lua_isnumber(L, 2)) from = (int)lua_tointeger(L, 2);
            if (nargs >= 3 && lua_isnumber(L, 3)) to   = (int)lua_tointeger(L, 3);
        } else if (lua_isnumber(L, 1)) {
            /* net.ip(from, to) — auto CIDR, portas como args 1 e 2 */
            from = (int)lua_tointeger(L, 1);
            if (nargs >= 2 && lua_isnumber(L, 2)) to = (int)lua_tointeger(L, 2);
        } else if (lua_isstring(L, 1)) {
            /* net.ip("cidr" [, from [, to]]) */
            strncpy(cidr_str, lua_tostring(L, 1), 63);
            if (nargs >= 2 && lua_isnumber(L, 2)) from = (int)lua_tointeger(L, 2);
            if (nargs >= 3 && lua_isnumber(L, 3)) to   = (int)lua_tointeger(L, 3);
        }
    }
    if (from < 1)     from = 0;
    if (to   > 65535) to   = 65535;
    if (from > 0 && to > 0 && from > to) { int t=from; from=to; to=t; }

    /* Auto-detect CIDR — 3 métodos */
    if (cidr_str[0] == '\0') {
        if (!net_detect_local_cidr(cidr_str, sizeof(cidr_str))) {
            FILE *fp = popen(
                "ip route 2>/dev/null | grep -v default"
                " | grep -oE '[0-9]+\\.[0-9]+\\.[0-9]+\\.[0-9]+/[0-9]+'"
                " | grep -v '^169\\.' | head -1", "r");
            if (fp) { fgets(cidr_str, sizeof(cidr_str), fp); pclose(fp); }
            char *nl=strchr(cidr_str,'\n'); if(nl)*nl='\0';
        }
        if (cidr_str[0] == '\0') {
            FILE *fp = popen(
                "ip addr 2>/dev/null | grep 'inet '"
                " | grep -v ' 127\\.' | grep -v ' 169\\.254'"
                " | grep -oE '[0-9]+\\.[0-9]+\\.[0-9]+\\.[0-9]+/[0-9]+'"
                " | head -1", "r");
            if (fp) { fgets(cidr_str, sizeof(cidr_str), fp); pclose(fp); }
            char *nl=strchr(cidr_str,'\n'); if(nl)*nl='\0';
        }
    }
    if (cidr_str[0] == '\0') {
        lua_pushnil(L);
        lua_pushstring(L,"nao detectou rede local -- passe o CIDR: net.ip('192.168.1.0/24')");
        return 2;
    }

    uint32_t base; int prefix;
    if (!parse_cidr(cidr_str, &base, &prefix)) {
        lua_pushnil(L); lua_pushfstring(L,"CIDR invalido: %s",cidr_str); return 2;
    }
    if (prefix < 16 || prefix > 30) {
        lua_pushnil(L); lua_pushstring(L,"prefix deve ser /16 a /30"); return 2;
    }

    uint32_t mask     = 0xFFFFFFFF << (32-prefix);
    uint32_t net_addr = base & mask;
    uint32_t bcast    = net_addr | (~mask);
    int      n_hosts  = (int)(bcast - net_addr - 1);
    if (n_hosts <= 0) n_hosts = 1;
    if (n_hosts > 65534) n_hosts = 65534;

    int do_scan = (from > 0 && to > 0);

    struct timeval h_t0, h_t1;
    gettimeofday(&h_t0, NULL);

    if (do_scan)
        printf("\n\033[1;36m[net.ip] SYN scan -- %s  portas %d-%d  (%d hosts)\033[0m\n\n",
               cidr_str, from, to, n_hosts);
    else
        printf("\n\033[1;36m[net.ip] SYN discovery -- %s  (%d hosts)\033[0m\n\n",
               cidr_str, n_hosts);

    /* ── Fase 1: discovery — batch de 512 hosts por vez em portas comuns ──
     * RST (ECONNREFUSED) e SYN-ACK (err==0) ambos confirmam host vivo.
     * So timeout = host morto ou filtrado.
     * ─────────────────────────────────────────────────────────────────── */
    static const int PROBE_PORTS[] = {80,443,22,8080,445,21,23,8443,3389,53,25,3306};
    #define N_PROBE  12
    #define HB       512

    uint8_t *alive = (uint8_t*)calloc((size_t)n_hosts, 1);
    if (!alive) { lua_newtable(L); return 1; }

    int disc_total = n_hosts * N_PROBE;
    int disc_done  = 0;

    for (int pp = 0; pp < N_PROBE; pp++) {
        int pport = PROBE_PORTS[pp];
        int hi    = 0;
        while (hi < n_hosts) {
            int nb = 0;
            int     fds[HB];
            int     idx[HB];
            struct pollfd pfds[HB];

            while (nb < HB && hi < n_hosts) {
                if (alive[hi]) { hi++; continue; }
                uint32_t hip = net_addr + 1 + (uint32_t)hi;
                int fd = socket(AF_INET, SOCK_STREAM|SOCK_NONBLOCK, 0);
                if (fd < 0) { hi++; continue; }
                struct sockaddr_in sa; memset(&sa,0,sizeof(sa));
                sa.sin_family      = AF_INET;
                sa.sin_addr.s_addr = htonl(hip);
                sa.sin_port        = htons((uint16_t)pport);
                connect(fd,(struct sockaddr*)&sa,sizeof(sa));
                fds[nb] = fd; idx[nb] = hi;
                pfds[nb].fd = fd; pfds[nb].events = POLLOUT|POLLERR; pfds[nb].revents = 0;
                nb++; hi++;
            }

            poll(pfds, nb, 200);

            for (int i = 0; i < nb; i++) {
                if (pfds[i].revents & (POLLOUT|POLLERR)) {
                    int err=0; socklen_t el=sizeof(err);
                    getsockopt(fds[i],SOL_SOCKET,SO_ERROR,&err,&el);
                    if (err == 0 || err == ECONNREFUSED)
                        alive[idx[i]] = 1;
                }
                struct linger sl={1,0};
                setsockopt(fds[i],SOL_SOCKET,SO_LINGER,&sl,sizeof(sl));
                close(fds[i]);
            }
            disc_done += nb;
            progress_bar(disc_done, disc_total, "hosts:");
        }
    }
    progress_clear();

    int alive_count = 0;
    for (int i = 0; i < n_hosts; i++) if (alive[i]) alive_count++;

    if (alive_count == 0) {
        free(alive);
        gettimeofday(&h_t1,NULL);
        double el=(h_t1.tv_sec-h_t0.tv_sec)+(h_t1.tv_usec-h_t0.tv_usec)/1e6;
        char tmr[32]={0};
        if(el<60) snprintf(tmr,sizeof(tmr),"%.1fs",el);
        else snprintf(tmr,sizeof(tmr),"%dm%ds",(int)(el/60),(int)el%60);
        printf("\033[1;33m  [-] Nenhum host ativo em %s\033[0m  \033[0;90m(%s)\033[0m\n",
               cidr_str,tmr);
        lua_newtable(L); return 1;
    }

    printf("\033[1;36m[*]\033[0m \033[1;32m%d host(s) ativos\033[0m%s\n\n",
           alive_count, do_scan ? " -- iniciando port scan..." : ":");

    lua_newtable(L);

    /* ── Fase 2: SYN port scan em cada host vivo ────────────────────────────
     * Mesmo engine do net.scan: SOCK_NONBLOCK + batch 512 + poll 200ms + SO_LINGER.
     * ─────────────────────────────────────────────────────────────────────── */
    #define HS_BATCH 512

    for (int i = 0; i < n_hosts; i++) {
        if (!alive[i]) continue;
        uint32_t hip = net_addr + 1 + (uint32_t)i;
        char ipstr[20];
        snprintf(ipstr,sizeof(ipstr),"%u.%u.%u.%u",
            (hip>>24)&0xFF,(hip>>16)&0xFF,(hip>>8)&0xFF,hip&0xFF);

        if (!do_scan) {
            printf("\033[1;32m  [+] %s\033[0m\n", ipstr);
            lua_newtable(L);
            lua_setfield(L,-2,ipstr);
            continue;
        }

        int open_ports[65536]; int open_count = 0;
        int     hs_fds[HS_BATCH];
        int     hs_prt[HS_BATCH];
        struct pollfd hs_pfds[HS_BATCH];

        struct sockaddr_in base_sa; memset(&base_sa,0,sizeof(base_sa));
        base_sa.sin_family      = AF_INET;
        base_sa.sin_addr.s_addr = htonl(hip);

        int hs_total = to - from + 1;
        int hs_done  = 0;

        int port = from;
        while (port <= to) {
            int nb = 0;
            while (nb < HS_BATCH && port <= to) {
                int fd = socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK,0);
                if (fd < 0) { port++; continue; }
                struct sockaddr_in sa = base_sa;
                sa.sin_port = htons((uint16_t)port);
                connect(fd,(struct sockaddr*)&sa,sizeof(sa));
                hs_fds[nb]  = fd; hs_prt[nb] = port;
                hs_pfds[nb].fd = fd; hs_pfds[nb].events = POLLOUT|POLLERR; hs_pfds[nb].revents = 0;
                nb++; port++;
            }
            poll(hs_pfds, nb, 200);
            for (int j = 0; j < nb; j++) {
                if (hs_pfds[j].revents & POLLOUT) {
                    int err=0; socklen_t el=sizeof(err);
                    getsockopt(hs_fds[j],SOL_SOCKET,SO_ERROR,&err,&el);
                    if (err == 0) open_ports[open_count++] = hs_prt[j];
                }
                struct linger sl={1,0};
                setsockopt(hs_fds[j],SOL_SOCKET,SO_LINGER,&sl,sizeof(sl));
                close(hs_fds[j]); hs_pfds[j].fd=-1;
            }
            hs_done += nb;
            /* label "IP portas:" para identificar qual host está sendo escaneado */
            char hs_label[40]={0};
            snprintf(hs_label, sizeof(hs_label), "\033[0;37m%s\033[0m portas:", ipstr);
            progress_bar(hs_done, hs_total, hs_label);
        }
        progress_clear();

        printf("\033[1;32m  [+] %-16s\033[0m", ipstr);
        if (open_count > 0) {
            printf("  \033[1;33mportas:\033[0m \033[1;32m");
            for (int j=0; j<open_count; j++)
                printf("%d%s", open_ports[j], j<open_count-1?",":"");
            printf("\033[0m");
        } else {
            printf("  \033[0;90m(sem portas abertas em %d-%d)\033[0m", from, to);
        }
        printf("\n");

        lua_newtable(L);
        for (int j=0; j<open_count; j++) {
            lua_pushinteger(L,open_ports[j]);
            lua_rawseti(L,-2,j+1);
        }
        lua_setfield(L,-2,ipstr);
    }

    #undef HS_BATCH
    #undef HB
    #undef N_PROBE

    free(alive);
    gettimeofday(&h_t1,NULL);
    double el=(h_t1.tv_sec-h_t0.tv_sec)+(h_t1.tv_usec-h_t0.tv_usec)/1e6;
    char tmr[32]={0};
    if(el<60) snprintf(tmr,sizeof(tmr),"%.1fs",el);
    else snprintf(tmr,sizeof(tmr),"%dm%ds",(int)(el/60),(int)el%60);
    printf("\n\033[1;36m[net.ip]\033[0m %d host(s) ativos  \033[0;90m(%s)\033[0m\n",
           alive_count,tmr);
    return 1;
}

/* ═══════════════════════════════════════════════════════════════════════════
 * MÓDULO web.* — ElliotOS v17.0
 *   web.get(url [, opts])           → html, code  |  nil, errmsg
 *   web.serve(path, port [, opts])  → nil  (servidor estático em background)
 *   web.stop()                      → nil
 *   web.help()                      → nil
 * ═══════════════════════════════════════════════════════════════════════════*/

typedef struct {
    int          fd;
    int          port;
    volatile int running;
    pthread_t    tid;
    char         root[512];
} WebServer;

static WebServer       g_web_srv = {-1, 0, 0, 0, ""};
static pthread_mutex_t g_web_mu  = PTHREAD_MUTEX_INITIALIZER;

static const char *web_mime(const char *path) {
    const char *dot = strrchr(path, '.');
    if (!dot) return "application/octet-stream";
    if (strcasecmp(dot,".html")==0||strcasecmp(dot,".htm")==0) return "text/html; charset=utf-8";
    if (strcasecmp(dot,".css") ==0) return "text/css; charset=utf-8";
    if (strcasecmp(dot,".js")  ==0) return "application/javascript";
    if (strcasecmp(dot,".json")==0) return "application/json";
    if (strcasecmp(dot,".png") ==0) return "image/png";
    if (strcasecmp(dot,".jpg") ==0||strcasecmp(dot,".jpeg")==0) return "image/jpeg";
    if (strcasecmp(dot,".gif") ==0) return "image/gif";
    if (strcasecmp(dot,".svg") ==0) return "image/svg+xml";
    if (strcasecmp(dot,".ico") ==0) return "image/x-icon";
    if (strcasecmp(dot,".txt") ==0) return "text/plain; charset=utf-8";
    return "application/octet-stream";
}

static char *web_read_file(const char *fpath, size_t *out_len) {
    FILE *f = fopen(fpath, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END); long sz = ftell(f); rewind(f);
    if (sz <= 0) { fclose(f); return NULL; }
    char *buf = malloc((size_t)sz + 1);
    if (!buf)  { fclose(f); return NULL; }
    size_t n = fread(buf, 1, (size_t)sz, f);
    fclose(f); buf[n] = '\0'; *out_len = n;
    return buf;
}

static void web_send_resp(int cfd, int code, const char *ctype,
                          const char *body, size_t blen) {
    const char *status =
        code==200?"OK":code==301?"Moved Permanently":
        code==400?"Bad Request":code==403?"Forbidden":
        code==404?"Not Found":"Internal Server Error";
    char hdr[512];
    int hlen = snprintf(hdr, sizeof(hdr),
        "HTTP/1.1 %d %s\r\n"
        "Content-Type: %s\r\n"
        "Content-Length: %zu\r\n"
        "Server: ElliotOS/17\r\n"
        "Connection: close\r\n\r\n",
        code, status, ctype, blen);
    send(cfd, hdr,  (size_t)hlen, MSG_NOSIGNAL);
    if (body && blen > 0) send(cfd, body, blen, MSG_NOSIGNAL);
}

static void web_handle_conn(int cfd, const char *root) {
    char req[4096] = {0};
    ssize_t n = recv(cfd, req, sizeof(req)-1, 0);
    if (n <= 0) { close(cfd); return; }
    req[n] = '\0';

    char method[8]={0}, rawpath[1024]={0};
    sscanf(req, "%7s %1023s", method, rawpath);

    char *qs = strchr(rawpath, '?');
    if (qs) *qs = '\0';

    /* Bloqueia path traversal */
    if (strstr(rawpath, "..")) {
        const char *b = "<h1>403 Forbidden</h1>";
        web_send_resp(cfd, 403, "text/html", b, strlen(b));
        close(cfd); return;
    }

    char fspath[1024];
    if (strcmp(rawpath,"/")==0)
        snprintf(fspath, sizeof(fspath), "%s/index.html", root);
    else
        snprintf(fspath, sizeof(fspath), "%s%s", root, rawpath);

    size_t flen = 0;
    char *fbuf = web_read_file(fspath, &flen);
    if (!fbuf) {
        /* tenta index.html dentro de dir */
        char alt[1100];
        snprintf(alt, sizeof(alt), "%s/index.html", fspath);
        fbuf = web_read_file(alt, &flen);
        if (!fbuf) {
            const char *b = "<h1>404 Not Found</h1>";
            web_send_resp(cfd, 404, "text/html", b, strlen(b));
            close(cfd); return;
        }
        strncpy(fspath, alt, sizeof(fspath)-1);
    }

    web_send_resp(cfd, 200, web_mime(fspath), fbuf, flen);
    free(fbuf); close(cfd);
}

static void *web_srv_thread(void *arg) {
    (void)arg;
    struct sockaddr_in ca; socklen_t calen = sizeof(ca);
    while (g_web_srv.running) {
        struct pollfd pfd = {g_web_srv.fd, POLLIN, 0};
        if (poll(&pfd, 1, 500) <= 0) continue;
        int cfd = accept(g_web_srv.fd, (struct sockaddr*)&ca, &calen);
        if (cfd < 0) continue;
        pid_t pid = fork();
        if (pid == 0) {
            close(g_web_srv.fd);
            web_handle_conn(cfd, g_web_srv.root);
            _exit(0);
        }
        close(cfd);
        waitpid(-1, NULL, WNOHANG);
    }
    close(g_web_srv.fd); g_web_srv.fd = -1;
    return NULL;
}

/* web.get(url [, opts]) → html, code | nil, errmsg */
static int l_web_get(lua_State *L) {
    const char *url = luaL_checkstring(L, 1);
    CurlOpts opts   = curl_parse_opts(L, 2);

    static const char *WEB_UA =
        "Mozilla/5.0 (Linux; Android 13; Pixel 7) "
        "AppleWebKit/537.36 (KHTML, like Gecko) "
        "Chrome/124.0.0.0 Mobile Safari/537.36";

    CURL *ch = curl_easy_init();
    if (!ch) { lua_pushnil(L); lua_pushstring(L,"curl init falhou"); return 2; }

    CurlBuf cb={NULL,0}; cb.data=malloc(1); cb.data[0]='\0';
    curl_easy_setopt(ch, CURLOPT_URL,            url);
    curl_easy_setopt(ch, CURLOPT_WRITEFUNCTION,  curl_write_cb);
    curl_easy_setopt(ch, CURLOPT_WRITEDATA,      &cb);
    curl_easy_setopt(ch, CURLOPT_FOLLOWLOCATION, 1L);
    curl_easy_setopt(ch, CURLOPT_MAXREDIRS,      10L);
    if (opts.ua[0]) curl_easy_setopt(ch, CURLOPT_USERAGENT, opts.ua);
    else            curl_easy_setopt(ch, CURLOPT_USERAGENT, WEB_UA);
    curl_apply_opts(ch, &opts);

    CURLcode rc=curl_easy_perform(ch);
    long code=0; curl_easy_getinfo(ch, CURLINFO_RESPONSE_CODE, &code);
    char *eff=NULL; curl_easy_getinfo(ch, CURLINFO_EFFECTIVE_URL, &eff);
    char *ctype_raw=NULL; curl_easy_getinfo(ch, CURLINFO_CONTENT_TYPE, &ctype_raw);
    if (opts.hdrs) curl_slist_free_all(opts.hdrs);
    curl_easy_cleanup(ch);

    if (!opts.quiet) {
        printf("\033[1;35m[web.get]\033[0m %s → HTTP %ld (%zu bytes)\n", url, code, cb.size);
        if (eff && strcmp(eff,url)!=0)
            printf("\033[0;90m          ↳ %s\033[0m\n", eff);
        if (ctype_raw)
            printf("\033[0;90m          Content-Type: %s\033[0m\n", ctype_raw);
        if (ctype_raw &&
            strncmp(ctype_raw,"text/",5)!=0 &&
            strncmp(ctype_raw,"application/json",16)!=0 &&
            strncmp(ctype_raw,"application/javascript",22)!=0)
            printf("\033[1;33m[web.get] ⚠ Content-Type '%s' não é HTML/texto\033[0m\n", ctype_raw);
    }
    if (rc != CURLE_OK || !cb.data) {
        if (!opts.quiet) printf("\033[1;31m[web.get] erro: %s\033[0m\n", curl_easy_strerror(rc));
        free(cb.data); lua_pushnil(L); lua_pushstring(L, curl_easy_strerror(rc)); return 2;
    }
    if (opts.file[0]) { int r=save_to_file(opts.file,cb.data,cb.size,"web.get",L); free(cb.data); return r; }
    lua_pushlstring(L, cb.data, cb.size);
    lua_pushinteger(L, code);
    free(cb.data); return 2;
}

/* web.serve(path, port [, opts]) → nil */
static int l_web_serve(lua_State *L) {
    const char *path = luaL_checkstring(L, 1);
    int port         = (int)luaL_checkinteger(L, 2);
    int quiet = 0;
    if (lua_gettop(L)>=3 && lua_istable(L,3)) {
        lua_getfield(L,3,"quiet"); quiet=lua_toboolean(L,-1); lua_pop(L,1);
    }

    pthread_mutex_lock(&g_web_mu);
    if (g_web_srv.running) {
        pthread_mutex_unlock(&g_web_mu);
        lua_pushnil(L);
        lua_pushfstring(L,"servidor já rodando na porta %d — chame web.stop() primeiro", g_web_srv.port);
        return 2;
    }

    struct stat st;
    if (stat(path,&st)!=0 || !S_ISDIR(st.st_mode)) {
        pthread_mutex_unlock(&g_web_mu);
        lua_pushnil(L); lua_pushfstring(L,"diretório não encontrado: %s", path); return 2;
    }

    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd<0) { pthread_mutex_unlock(&g_web_mu); lua_pushnil(L); lua_pushstring(L,strerror(errno)); return 2; }
    int v=1; setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &v, sizeof(v));

    struct sockaddr_in sa; memset(&sa,0,sizeof(sa));
    sa.sin_family=AF_INET; sa.sin_port=htons((uint16_t)port); sa.sin_addr.s_addr=INADDR_ANY;

    if (bind(fd,(struct sockaddr*)&sa,sizeof(sa))<0) {
        char e[128]; snprintf(e,sizeof(e),"bind(): %s",strerror(errno));
        close(fd); pthread_mutex_unlock(&g_web_mu); lua_pushnil(L); lua_pushstring(L,e); return 2;
    }
    if (listen(fd,16)<0) {
        char e[128]; snprintf(e,sizeof(e),"listen(): %s",strerror(errno));
        close(fd); pthread_mutex_unlock(&g_web_mu); lua_pushnil(L); lua_pushstring(L,e); return 2;
    }

    g_web_srv.fd=fd; g_web_srv.port=port; g_web_srv.running=1;
    strncpy(g_web_srv.root, path, sizeof(g_web_srv.root)-1);

    pthread_attr_t attr; pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
    pthread_create(&g_web_srv.tid, &attr, web_srv_thread, NULL);
    pthread_attr_destroy(&attr);
    pthread_mutex_unlock(&g_web_mu);

    if (!quiet) {
        printf("\033[1;32m[web.serve]\033[0m Servidor iniciado\n");
        printf("\033[0;90m  Raiz : %s\033[0m\n", path);
        printf("\033[0;90m  URL  : http://localhost:%d/\033[0m\n", port);
        printf("\033[0;90m  Parar: web.stop()\033[0m\n\n");
    }
    return 0;
}

/* web.stop() */
static int l_web_stop(lua_State *L) {
    (void)L;
    pthread_mutex_lock(&g_web_mu);
    if (!g_web_srv.running) {
        pthread_mutex_unlock(&g_web_mu);
        printf("\033[1;33m[web.stop]\033[0m Nenhum servidor ativo.\n");
        return 0;
    }
    g_web_srv.running=0;
    if (g_web_srv.fd>=0) { shutdown(g_web_srv.fd,SHUT_RDWR); close(g_web_srv.fd); g_web_srv.fd=-1; }
    int p=g_web_srv.port;
    pthread_mutex_unlock(&g_web_mu);
    printf("\033[1;31m[web.stop]\033[0m Servidor parado (porta %d).\n", p);
    return 0;
}

/* ══════════════════════════════════════════════════════════════════════════
 * HELPERS de parsing HTML — sem dependência externa, parser manual em C
 * Estratégia: varredura linear do buffer, sem construir DOM completo.
 * Suficiente para extração de atributos e conteúdo de tags.
 * ══════════════════════════════════════════════════════════════════════════ */

/* Avança ponteiro pulando espaços em branco */
static const char *web_skip_ws(const char *p) {
    while (*p && (*p==' '||*p=='\t'||*p=='\r'||*p=='\n')) p++;
    return p;
}

/* Lê valor de atributo: suporta aspas simples, duplas e sem aspas.
 * Escreve em buf[bsz], retorna ponteiro após o valor. */
static const char *web_attr_val(const char *p, char *buf, size_t bsz) {
    buf[0]='\0';
    p = web_skip_ws(p);
    if (*p != '=') return p;
    p++; p = web_skip_ws(p);
    char q = 0;
    if (*p=='"'||*p=='\'') { q=*p; p++; }
    size_t i=0;
    while (*p && i<bsz-1) {
        if (q && *p==q) { p++; break; }
        if (!q && (*p==' '||*p=='>'||*p=='/'||*p=='\t'||*p=='\n')) break;
        buf[i++]=(char)*p; p++;
    }
    buf[i]='\0';
    return p;
}

/* Procura atributo `name` dentro de uma string de atributos `attrs`.
 * Escreve valor em buf[bsz]. Retorna 1 se encontrou. */
static int web_find_attr(const char *attrs, const char *name,
                          char *buf, size_t bsz) {
    size_t nlen = strlen(name);
    const char *p = attrs;
    while (*p) {
        p = web_skip_ws(p);
        /* tenta casar nome do atributo (case-insensitive) */
        if (strncasecmp(p, name, nlen)==0) {
            char next = p[nlen];
            if (next=='='||next==' '||next=='\t'||next=='>'||next=='/'||next=='\0') {
                p += nlen;
                web_attr_val(p, buf, bsz);
                return 1;
            }
        }
        /* pula até próximo espaço ou > */
        while (*p && *p!='>' && *p!=' ' && *p!='\t' && *p!='\n') {
            if (*p=='"'||*p=='\'') {
                char q=*p; p++;
                while (*p && *p!=q) p++;
                if (*p) p++;
            } else p++;
        }
    }
    buf[0]='\0';
    return 0;
}

/* ══════════════════════════════════════════════════════════════════════════
 * web.links(html) → tabela de strings
 *
 * Extrai todos os href de <a ...> e <link ...> e src de <img ...>.
 * Retorna tabela Lua indexada: { "https://...", "/path", ... }
 * ══════════════════════════════════════════════════════════════════════════ */
/* ══════════════════════════════════════════════════════════════════════════
 * web.links(html [, opts]) — dual mode
 *   Imprime links formatados no terminal E retorna tabela de strings.
 *   opts: { quiet=true, file="saida.txt" }
 *   Se file → salva um link por linha (sem cores).
 * ══════════════════════════════════════════════════════════════════════════ */
static int l_web_links(lua_State *L) {
    size_t hlen;
    const char *html = luaL_checklstring(L, 1, &hlen);

    /* opts */
    int quiet = 0; char outfile[512] = "";
    if (lua_gettop(L) >= 2 && lua_istable(L, 2)) {
        lua_getfield(L,2,"quiet"); quiet = lua_toboolean(L,-1); lua_pop(L,1);
        lua_getfield(L,2,"file");
        if (lua_isstring(L,-1)) strncpy(outfile, lua_tostring(L,-1), sizeof(outfile)-1);
        lua_pop(L,1);
    }

    /* coleta */
    char  **items  = NULL;
    int     count  = 0, cap = 0;

    const char *p = html;
    while ((p = strchr(p, '<')) != NULL) {
        p++; p = web_skip_ws(p);
        int is_a    = strncasecmp(p,"a",1)==0    && (p[1]==' '||p[1]=='\t'||p[1]=='\n'||p[1]=='>');
        int is_link = strncasecmp(p,"link",4)==0 && (p[4]==' '||p[4]=='\t'||p[4]=='\n'||p[4]=='>');
        int is_img  = strncasecmp(p,"img",3)==0  && (p[3]==' '||p[3]=='\t'||p[3]=='\n'||p[3]=='>');
        int is_scr  = strncasecmp(p,"script",6)==0 && (p[6]==' '||p[6]=='\t'||p[6]=='\n'||p[6]=='>');
        if (is_a || is_link || is_img || is_scr) {
            char attrs[2048]; size_t ai=0;
            while (*p && *p!='>' && ai<sizeof(attrs)-1) {
                if (*p=='"'||*p=='\'') { char q=*p; attrs[ai++]=(char)*p; p++;
                    while(*p&&*p!=q&&ai<sizeof(attrs)-1){attrs[ai++]=(char)*p;p++;}
                    if(*p&&ai<sizeof(attrs)-1){attrs[ai++]=(char)*p;p++;}
                } else { attrs[ai++]=(char)*p; p++; }
            }
            attrs[ai]='\0';
            char val[1024]="";
            const char *attr = (is_a||is_link) ? "href" : "src";
            if (web_find_attr(attrs, attr, val, sizeof(val)) && val[0]) {
                if (count >= cap) {
                    cap = cap ? cap*2 : 16;
                    items = realloc(items, (size_t)cap * sizeof(char*));
                }
                items[count++] = strdup(val);
            }
        } else { while (*p && *p!='>') p++; }
    }

    /* imprime */
    if (!quiet) {
        printf("\033[1;35m[web.links]\033[0m %d link(s) encontrado(s)\n", count);
        for (int i=0; i<count; i++)
            printf("  \033[0;36m%3d\033[0m  %s\n", i+1, items[i]);
        if (count > 0) printf("\n");
    }

    /* salva em arquivo cru */
    if (outfile[0]) {
        FILE *f = fopen(outfile, "w");
        if (f) {
            for (int i=0; i<count; i++) fprintf(f, "%s\n", items[i]);
            fclose(f);
            if (!quiet) printf("\033[0;90m  → salvo em %s\033[0m\n", outfile);
        }
    }

    /* retorna tabela */
    lua_newtable(L);
    for (int i=0; i<count; i++) {
        lua_pushstring(L, items[i]);
        lua_rawseti(L, -2, i+1);
        free(items[i]);
    }
    free(items);
    return 1;
}

/* ══════════════════════════════════════════════════════════════════════════
 * web.forms(html [, opts]) — dual mode
 *   Imprime forms formatados E retorna tabela estruturada.
 *   opts: { quiet=true, file="saida.txt" }
 *   Se file → salva em texto cru (action method\n  name type value\n).
 * ══════════════════════════════════════════════════════════════════════════ */
static int l_web_forms(lua_State *L) {
    size_t hlen;
    const char *html = luaL_checklstring(L, 1, &hlen);

    int quiet = 0; char outfile[512] = "";
    if (lua_gettop(L) >= 2 && lua_istable(L, 2)) {
        lua_getfield(L,2,"quiet"); quiet = lua_toboolean(L,-1); lua_pop(L,1);
        lua_getfield(L,2,"file");
        if (lua_isstring(L,-1)) strncpy(outfile, lua_tostring(L,-1), sizeof(outfile)-1);
        lua_pop(L,1);
    }

    /* estrutura temporária */
    typedef struct { char action[512]; char method[32];
                     char (*inp)[3][512]; int inp_count; } WebForm;
    WebForm *forms = NULL; int fcount=0, fcap=0;

    FILE *raw = outfile[0] ? fopen(outfile,"w") : NULL;

    const char *p = html;
    while ((p = strchr(p,'<')) != NULL) {
        p++; p = web_skip_ws(p);
        if (strncasecmp(p,"form",4)==0 &&
            (p[4]==' '||p[4]=='\t'||p[4]=='\n'||p[4]=='>')) {

            char fattrs[2048]; size_t ai=0;
            while (*p&&*p!='>'&&ai<sizeof(fattrs)-1) {
                if(*p=='"'||*p=='\''){char q=*p;fattrs[ai++]=(char)*p;p++;
                    while(*p&&*p!=q&&ai<sizeof(fattrs)-1){fattrs[ai++]=(char)*p;p++;}
                    if(*p&&ai<sizeof(fattrs)-1){fattrs[ai++]=(char)*p;p++;}
                } else {fattrs[ai++]=(char)*p;p++;}
            }
            fattrs[ai]='\0';

            if (fcount >= fcap) { fcap=fcap?fcap*2:8; forms=realloc(forms,(size_t)fcap*sizeof(WebForm)); }
            WebForm *f = &forms[fcount++];
            memset(f,0,sizeof(*f));
            web_find_attr(fattrs,"action",f->action,sizeof(f->action));
            web_find_attr(fattrs,"method",f->method,sizeof(f->method));
            if (!f->method[0]) strcpy(f->method,"get");

            int icap=0;
            f->inp = NULL; f->inp_count=0;

            const char *fp = p;
            while ((fp = strchr(fp,'<')) != NULL) {
                fp++; fp = web_skip_ws(fp);
                if (*fp=='/' && strncasecmp(fp+1,"form",4)==0) break;
                int ii = strncasecmp(fp,"input",5)==0&&(fp[5]==' '||fp[5]=='\t'||fp[5]=='\n'||fp[5]=='>');
                int is = strncasecmp(fp,"select",6)==0&&(fp[6]==' '||fp[6]=='\t'||fp[6]=='\n'||fp[6]=='>');
                int it = strncasecmp(fp,"textarea",8)==0&&(fp[8]==' '||fp[8]=='\t'||fp[8]=='\n'||fp[8]=='>');
                int ib = strncasecmp(fp,"button",6)==0&&(fp[6]==' '||fp[6]=='\t'||fp[6]=='\n'||fp[6]=='>');
                if (ii||is||it||ib) {
                    char ia[1024]; size_t iai=0;
                    while(*fp&&*fp!='>'&&iai<sizeof(ia)-1){
                        if(*fp=='"'||*fp=='\''){char q=*fp;ia[iai++]=(char)*fp;fp++;
                            while(*fp&&*fp!=q&&iai<sizeof(ia)-1){ia[iai++]=(char)*fp;fp++;}
                            if(*fp&&iai<sizeof(ia)-1){ia[iai++]=(char)*fp;fp++;}
                        } else {ia[iai++]=(char)*fp;fp++;}
                    }
                    ia[iai]='\0';
                    if (f->inp_count >= icap) {
                        icap=icap?icap*2:8;
                        f->inp=realloc(f->inp,(size_t)icap*3*512);
                    }
                    char (*row)[512] = (char (*)[512])(f->inp + f->inp_count);
                    web_find_attr(ia,"name", row[0],512);
                    web_find_attr(ia,"type", row[1],512);
                    web_find_attr(ia,"value",row[2],512);
                    if (!row[1][0]) {
                        if(is) strcpy(row[1],"select");
                        else if(it) strcpy(row[1],"textarea");
                        else if(ib) strcpy(row[1],"button");
                        else strcpy(row[1],"text");
                    }
                    f->inp_count++;
                } else { while(*fp&&*fp!='>') fp++; }
            }
            p = fp ? fp : p;
        } else { while(*p&&*p!='>') p++; }
    }

    /* imprime */
    if (!quiet) {
        printf("\033[1;35m[web.forms]\033[0m %d form(s) encontrado(s)\n\n", fcount);
        for (int i=0; i<fcount; i++) {
            WebForm *f = &forms[i];
            printf("  \033[1;33mFORM %d\033[0m  method=\033[0;32m%s\033[0m  action=\033[0;36m%s\033[0m\n",
                   i+1, f->method, f->action[0]?f->action:"(vazio)");
            for (int j=0; j<f->inp_count; j++) {
                char (*row)[512] = (char (*)[512])(f->inp + j);
                printf("    \033[0;90m%-20s\033[0m  type=%-12s  value=%s\n",
                       row[0][0]?row[0]:"(sem nome)", row[1], row[2]);
            }
            printf("\n");
        }
    }

    /* arquivo cru */
    if (raw) {
        for (int i=0; i<fcount; i++) {
            WebForm *f = &forms[i];
            fprintf(raw, "FORM %d  %s  %s\n", i+1, f->method, f->action);
            for (int j=0; j<f->inp_count; j++) {
                char (*row)[512] = (char (*)[512])(f->inp + j);
                fprintf(raw, "  %s\t%s\t%s\n", row[0], row[1], row[2]);
            }
            fprintf(raw, "\n");
        }
        fclose(raw);
        if (!quiet) printf("\033[0;90m  → salvo em %s\033[0m\n", outfile);
    }

    /* retorna tabela */
    lua_newtable(L);
    for (int i=0; i<fcount; i++) {
        WebForm *f = &forms[i];
        lua_newtable(L);
        lua_pushstring(L,f->action); lua_setfield(L,-2,"action");
        lua_pushstring(L,f->method); lua_setfield(L,-2,"method");
        lua_newtable(L);
        for (int j=0; j<f->inp_count; j++) {
            char (*row)[512] = (char (*)[512])(f->inp + j);
            lua_newtable(L);
            lua_pushstring(L,row[0]); lua_setfield(L,-2,"name");
            lua_pushstring(L,row[1]); lua_setfield(L,-2,"type");
            lua_pushstring(L,row[2]); lua_setfield(L,-2,"value");
            lua_rawseti(L,-2,j+1);
        }
        lua_setfield(L,-2,"inputs");
        lua_rawseti(L,-2,i+1);
        free(f->inp);
    }
    free(forms);
    return 1;
}

/* ══════════════════════════════════════════════════════════════════════════
 * web.scripts(html [, opts]) — dual mode
 *   Imprime scripts formatados E retorna tabela.
 *   opts: { quiet=true, file="dir/" ou "arquivo.js" }
 *   Se file for diretório → salva cada script inline como scriptN.js.
 *   Se file for arquivo   → concatena todos os scripts inline no arquivo.
 * ══════════════════════════════════════════════════════════════════════════ */
static int l_web_scripts(lua_State *L) {
    size_t hlen;
    const char *html = luaL_checklstring(L, 1, &hlen);

    int quiet = 0; char outfile[512] = "";
    if (lua_gettop(L) >= 2 && lua_istable(L, 2)) {
        lua_getfield(L,2,"quiet"); quiet = lua_toboolean(L,-1); lua_pop(L,1);
        lua_getfield(L,2,"file");
        if (lua_isstring(L,-1)) strncpy(outfile, lua_tostring(L,-1), sizeof(outfile)-1);
        lua_pop(L,1);
    }

    char  **srcs   = NULL;
    char  **inlines= NULL;
    int     count  = 0, cap = 0;

    const char *p = html;
    while ((p = strchr(p,'<')) != NULL) {
        p++; p = web_skip_ws(p);
        if (strncasecmp(p,"script",6)==0 &&
            (p[6]==' '||p[6]=='\t'||p[6]=='\n'||p[6]=='>')) {
            char sattrs[2048]; size_t ai=0;
            while(*p&&*p!='>'&&ai<sizeof(sattrs)-1){
                if(*p=='"'||*p=='\''){char q=*p;sattrs[ai++]=(char)*p;p++;
                    while(*p&&*p!=q&&ai<sizeof(sattrs)-1){sattrs[ai++]=(char)*p;p++;}
                    if(*p&&ai<sizeof(sattrs)-1){sattrs[ai++]=(char)*p;p++;}
                } else {sattrs[ai++]=(char)*p;p++;}
            }
            sattrs[ai]='\0';
            if (*p=='>') p++;

            char src[1024]="";
            web_find_attr(sattrs,"src",src,sizeof(src));

            char *inline_code = NULL;
            const char *bs = p;
            const char *cl = strcasestr(p,"</script");
            if (cl && cl > bs) {
                size_t blen=(size_t)(cl-bs);
                const char *bc=bs;
                while(bc<cl&&(*bc==' '||*bc=='\t'||*bc=='\r'||*bc=='\n')) bc++;
                if (bc<cl) { inline_code=malloc(blen+1); memcpy(inline_code,bs,blen); inline_code[blen]='\0'; }
                p=cl;
            }
            if (src[0]||inline_code) {
                if (count>=cap){cap=cap?cap*2:8; srcs=realloc(srcs,(size_t)cap*sizeof(char*)); inlines=realloc(inlines,(size_t)cap*sizeof(char*));}
                srcs[count]    = strdup(src);
                inlines[count] = inline_code ? inline_code : strdup("");
                count++;
            }
        } else { while(*p&&*p!='>') p++; }
    }

    /* imprime */
    if (!quiet) {
        int ext_n=0, inl_n=0;
        for(int i=0;i<count;i++) { if(srcs[i][0]) ext_n++; else inl_n++; }
        printf("\033[1;35m[web.scripts]\033[0m %d script(s)  [\033[0;36m%d externo(s)\033[0m  \033[0;33m%d inline\033[0m]\n\n", count, ext_n, inl_n);
        for (int i=0; i<count; i++) {
            if (srcs[i][0]) {
                printf("  \033[1;36m[EXT %d]\033[0m  %s\n", i+1, srcs[i]);
            } else {
                size_t ilen = strlen(inlines[i]);
                /* mostra as primeiras 2 linhas do código */
                char preview[160]=""; int pc=0; int lines=0;
                for (size_t c=0; c<ilen && pc<(int)sizeof(preview)-1 && lines<2; c++) {
                    if (inlines[i][c]=='\n') { lines++; if(lines<2){preview[pc++]='\n';} }
                    else preview[pc++]=inlines[i][c];
                }
                preview[pc]='\0';
                printf("  \033[1;33m[INL %d]\033[0m  %zu bytes\n", i+1, ilen);
                printf("  \033[0;90m%s%s\033[0m\n", preview, ilen>160?"...":"");
            }
        }
        if (count>0) printf("\n");
    }

    /* arquivo */
    if (outfile[0]) {
        struct stat st;
        int is_dir = (stat(outfile,&st)==0 && S_ISDIR(st.st_mode));
        if (is_dir) {
            for (int i=0; i<count; i++) {
                if (!inlines[i][0]) continue;
                char fpath[640]; snprintf(fpath,sizeof(fpath),"%s/script%d.js",outfile,i+1);
                FILE *f=fopen(fpath,"w"); if(!f) continue;
                fputs(inlines[i],f); fclose(f);
                if (!quiet) printf("\033[0;90m  → %s\033[0m\n", fpath);
            }
        } else {
            FILE *f=fopen(outfile,"w");
            if (f) {
                for (int i=0; i<count; i++) {
                    if (!inlines[i][0]) continue;
                    fprintf(f,"/* script %d */\n%s\n\n",i+1,inlines[i]);
                }
                fclose(f);
                if (!quiet) printf("\033[0;90m  → salvo em %s\033[0m\n", outfile);
            }
        }
    }

    /* retorna tabela */
    lua_newtable(L);
    for (int i=0; i<count; i++) {
        lua_newtable(L);
        lua_pushstring(L,srcs[i]);    lua_setfield(L,-2,"src");
        lua_pushstring(L,inlines[i]); lua_setfield(L,-2,"inline");
        lua_rawseti(L,-2,i+1);
        free(srcs[i]); free(inlines[i]);
    }
    free(srcs); free(inlines);
    return 1;
}

/* ══════════════════════════════════════════════════════════════════════════
 * web.save(url, path [, opts]) → bytes_salvos | nil, errmsg
 *
 * Baixa qualquer URL e salva em disco no caminho <path>.
 * Se <path> for um diretório existente, usa o nome do arquivo da URL.
 * Se a URL não tiver extensão, salva como .html.
 * opts: mesmas de web.get {timeout, ua, quiet, headers}
 * ══════════════════════════════════════════════════════════════════════════ */
static int l_web_save(lua_State *L) {
    const char *url  = luaL_checkstring(L, 1);
    const char *path = luaL_checkstring(L, 2);
    CurlOpts opts    = curl_parse_opts(L, 3);

    static const char *WEB_UA =
        "Mozilla/5.0 (Linux; Android 13; Pixel 7) "
        "AppleWebKit/537.36 (KHTML, like Gecko) "
        "Chrome/124.0.0.0 Mobile Safari/537.36";

    /* Resolve caminho final de saída */
    char outpath[1024];
    struct stat st;
    if (stat(path, &st) == 0 && S_ISDIR(st.st_mode)) {
        /* É diretório — extrai nome do arquivo da URL */
        const char *last = strrchr(url, '/');
        const char *fname = (last && *(last+1)) ? last+1 : "index";
        /* Remove query string do nome */
        char clean[512]; strncpy(clean, fname, sizeof(clean)-1); clean[sizeof(clean)-1]='\0';
        char *qs = strchr(clean, '?'); if (qs) *qs='\0';
        char *hash = strchr(clean, '#'); if (hash) *hash='\0';
        /* Sem extensão → adiciona .html */
        if (!strchr(clean, '.')) strncat(clean, ".html", sizeof(clean)-strlen(clean)-1);
        snprintf(outpath, sizeof(outpath), "%s/%s", path, clean);
    } else {
        strncpy(outpath, path, sizeof(outpath)-1);
        outpath[sizeof(outpath)-1] = '\0';
    }

    CURL *ch = curl_easy_init();
    if (!ch) { lua_pushnil(L); lua_pushstring(L,"curl init falhou"); return 2; }

    CurlBuf cb={NULL,0}; cb.data=malloc(1); cb.data[0]='\0';
    curl_easy_setopt(ch, CURLOPT_URL,            url);
    curl_easy_setopt(ch, CURLOPT_WRITEFUNCTION,  curl_write_cb);
    curl_easy_setopt(ch, CURLOPT_WRITEDATA,      &cb);
    curl_easy_setopt(ch, CURLOPT_FOLLOWLOCATION, 1L);
    curl_easy_setopt(ch, CURLOPT_MAXREDIRS,      10L);
    if (opts.ua[0]) curl_easy_setopt(ch, CURLOPT_USERAGENT, opts.ua);
    else            curl_easy_setopt(ch, CURLOPT_USERAGENT, WEB_UA);
    curl_apply_opts(ch, &opts);

    CURLcode rc  = curl_easy_perform(ch);
    long code    = 0; curl_easy_getinfo(ch, CURLINFO_RESPONSE_CODE, &code);
    if (opts.hdrs) curl_slist_free_all(opts.hdrs);
    curl_easy_cleanup(ch);

    if (rc != CURLE_OK || !cb.data) {
        free(cb.data);
        lua_pushnil(L); lua_pushstring(L, curl_easy_strerror(rc)); return 2;
    }

    /* Salva em disco */
    FILE *f = fopen(outpath, "wb");
    if (!f) {
        char e[256]; snprintf(e,sizeof(e),"fopen(%s): %s", outpath, strerror(errno));
        free(cb.data); lua_pushnil(L); lua_pushstring(L,e); return 2;
    }
    size_t written = fwrite(cb.data, 1, cb.size, f);
    fclose(f); free(cb.data);

    if (!opts.quiet) {
        printf("\033[1;35m[web.save]\033[0m %s → HTTP %ld\n", url, code);
        printf("\033[0;90m  Salvo : %s (%zu bytes)\033[0m\n", outpath, written);
    }

    lua_pushinteger(L, (lua_Integer)written);
    return 1;
}

/* web.help() */
static int l_web_help(lua_State *L) {
    (void)L;
    printf(
        "\n\033[1;35m── web.* — Módulo HTML/HTTP ───────────────────────────────\033[0m\n\n"
        "  \033[1;36mweb.get(url [, opts])\033[0m\n"
        "    Baixa HTML/CSS/JS cru de qualquer URL.\n"
        "    UA padrão: Chrome/Android. Segue redirects.\n"
        "    Retorna: html, code  ou  nil, errmsg\n"
        "    opts: {timeout=N, ua='...', quiet=true, headers={}, file='saida.html'}\n\n"
        "  \033[1;36mweb.save(url, path [, opts])\033[0m\n"
        "    Baixa URL e salva diretamente em disco.\n"
        "    Se <path> for diretório, usa o nome do arquivo da URL (auto .html).\n"
        "    Retorna: bytes_salvos  ou  nil, errmsg\n\n"
        "  \033[1;36mweb.links(html)\033[0m\n"
        "    Extrai todos os href de <a> e <link>, e src de <img> e <script>.\n"
        "    Retorna: tabela de strings\n\n"
        "  \033[1;36mweb.forms(html)\033[0m\n"
        "    Extrai todos os <form> com seus inputs, selects, textareas.\n"
        "    Retorna: { {action, method, inputs={name,type,value}}, ... }\n\n"
        "  \033[1;36mweb.scripts(html)\033[0m\n"
        "    Extrai todos os <script>: externos (src) e inline (código).\n"
        "    Retorna: { {src='...', inline='...'}, ... }\n\n"
        "  \033[1;36mweb.serve(path, port [, opts])\033[0m\n"
        "    Servidor HTTP estático em background.\n"
        "    opts: {quiet=true}\n\n"
        "  \033[1;36mweb.stop()\033[0m\n"
        "    Para o servidor iniciado por web.serve().\n\n"
        "  \033[0;90mExemplos:\033[0m\n"
        "    local html = web.get('https://example.com')\n"
        "    for _,l in ipairs(web.links(html)) do print(l) end\n\n"
        "    -- baixar e salvar:\n"
        "    web.save('https://example.com', os.getenv('TMPDIR')..'/site.html')\n"
        "    web.save('https://example.com', os.getenv('TMPDIR')..'/')  -- nome auto\n\n"
        "    -- baixar e servir:\n"
        "    web.save('https://example.com', os.getenv('TMPDIR')..'/meusite/index.html')\n"
        "    web.serve(os.getenv('TMPDIR')..'/meusite', 8080)\n\n"
        "    local forms = web.forms(html)\n"
        "    for _,f in ipairs(forms) do\n"
        "      print(f.method, f.action)\n"
        "      for _,i in ipairs(f.inputs) do print(' ', i.name, i.type) end\n"
        "    end\n\n"
        "    local scripts = web.scripts(html)\n"
        "    for _,s in ipairs(scripts) do\n"
        "      if s.src~='' then print('ext:', s.src)\n"
        "      else print('inline:', #s.inline, 'bytes') end\n"
        "    end\n\n"
        "    web.serve('/data/data/com.termux/files/home/meusite', 8080)\n"
        "    web.stop()\n\n"
    );
    return 0;
}

