    (void)L;
    printf("\n\033[1;35m╔══════════════════════════════════════════════════════════════╗\033[0m\n");
    printf("\033[1;35m║  agent — Agente Autônomo de Código (Gemini + Shell)          ║\033[0m\n");
    printf("\033[1;35m╚══════════════════════════════════════════════════════════════╝\033[0m\n\n");
    printf("  \033[1;33magent.run\033[0m('tarefa')          Executa com confirmação a cada código\n");
    printf("  \033[1;33magent.run\033[0m('tarefa', opts)    Opções:\n");
    printf("    \033[0;90m{ auto=true }         — executa tudo sem pedir confirmação\033[0m\n");
    printf("    \033[0;90m{ max_iter=10 }       — máximo de iterações (padrão: 10)\033[0m\n");
    printf("    \033[0;90m{ lang='bash' }       — força linguagem\033[0m\n");
    printf("    \033[0;90m{ dir='/sdcard' }     — diretório de trabalho\033[0m\n\n");
    printf("  \033[1;33magent.chat\033[0m('msg')            Conversa sem execução\n");
    printf("  \033[1;33magent.reset\033[0m()               Reseta contexto\n\n");
    printf("  \033[1;36mFluxo normal (auto=false):\033[0m\n");
    printf("  1. Gemini gera código → mostra → [s/N]\n");
    printf("  2. Executa → captura output\n");
    printf("  3. Erro → Gemini corrige → volta ao passo 1\n\n");
    printf("  \033[1;36mFluxo automático (auto=true):\033[0m\n");
    printf("  1. Gemini gera código → executa direto sem perguntar\n");
    printf("  2. Erro → Gemini corrige → executa direto\n");
    printf("  3. Repete até DONE ou max_iter\n\n");
    printf("  \033[1;36mExemplos:\033[0m\n");
    printf("  agent.run('crie um port scanner em bash')\n");
    printf("  agent.run('faça um servidor HTTP em', {auto=true})\n");
    printf("  agent.run('compile hello world em C', {auto=true, lang='c'})\n");
    printf("  agent.chat('explica buffer overflow')\n\n");
    return 0;
}

/* ══════════════════════════════════════════════════════════════════
 * lmod — Gerenciador de módulos pessoais do usuário
 * lmod.new("nome.lua")  → cria ~/.lua-modules/nome.lua e abre no ed
 * lmod.mod("arq.lua")   → copia/registra arquivo existente
 * lmod.list()           → lista módulos instalados
 * lmod.remove("nome")   → remove módulo
 * lmod.path()           → mostra o diretório de módulos
 * ══════════════════════════════════════════════════════════════════ */

static const char *lmod_dir(char *buf, int sz) {
    const char *home = getenv("HOME");
    if(!home) home = ".";
    snprintf(buf, sz, "%s/.lua-modules", home);
    return buf;
}

/* Garante que o diretório existe */
static void lmod_ensure_dir(void) {
    char dir[512];
    lmod_dir(dir, sizeof(dir));
    struct stat st;
    if(stat(dir, &st) != 0) mkdir(dir, 0755);
}

/* Remove extensão .lua de um nome se presente */
static void lmod_strip_ext(const char *in, char *out, int sz) {
    strncpy(out, in, sz-1);
    out[sz-1] = '\0';
    int len = strlen(out);
    if(len > 4 && !strcmp(out+len-4, ".lua"))
        out[len-4] = '\0';
}

static int l_lmod_new(lua_State *L) {
    const char *name = luaL_checkstring(L, 1);
    const char *tipo = luaL_optstring(L, 2, "generic"); /* scanner|recon|util|generic */
    char base[256], dir[512], path[768];
    lmod_strip_ext(name, base, sizeof(base));
    lmod_dir(dir, sizeof(dir));
    lmod_ensure_dir();
    snprintf(path, sizeof(path), "%s/%s.lua", dir, base);

    /* Cria o arquivo se não existir */
    struct stat st;
    if(stat(path, &st) != 0) {
        FILE *f = fopen(path, "w");
        if(!f) return luaL_error(L, "lmod: nao foi possivel criar '%s'", path);

        if(strcmp(tipo, "scanner") == 0) {
            fprintf(f,
                "-- Módulo: %s (scanner)\n"
                "-- Template: scanner de vulnerabilidades\n"
                "-- Criado pelo lmod do ElliotOS\n"
                "-- AVISO: usa net.* — instale com perfil -m ou -g (não funciona em --nano)\n\n"
                "local M = {}\n"
                "local net = net  -- modulo net do ElliotOS\n\n"
                "-- Alvo padrão (pode ser passado por argumento)\n"
                "-- Exemplo de uso:\n"
                "--   local s = require('%s')\n"
                "--   s.scan('http://alvo.com')\n\n"
                "function M.scan(url)\n"
                "    if not url then print('Uso: M.scan(url)') return end\n"
                "    print('[*] Iniciando scan em: ' .. url)\n\n"
                "    -- 1. HTTP GET basico\n"
                "    local resp = net.get(url)\n"
                "    if not resp then print('[!] Falha ao conectar') return end\n\n"
                "    -- 2. Analise basica de headers\n"
                "    local headers = net.geth(url)\n"
                "    print('[+] Headers recebidos: ' .. tostring(headers))\n\n"
                "    -- 3. Adicione seus checks aqui:\n"
                "    -- if resp:find('erro') then ... end\n\n"
                "    print('[+] Scan concluído')\n"
                "    return resp\n"
                "end\n\n"
                "function M.help()\n"
                "    print('%s.scan(url)  — roda o scanner no alvo')\n"
                "end\n\n"
                "return M\n", base, base, base);

        } else if(strcmp(tipo, "recon") == 0) {
            fprintf(f,
                "-- Módulo: %s (recon)\n"
                "-- Template: reconhecimento passivo\n"
                "-- Criado pelo lmod do ElliotOS\n\n"
                "local M = {}\n"
                "local net = net\n\n"
                "-- Exemplo de uso:\n"
                "--   local r = require('%s')\n"
                "--   r.run('alvo.com')\n\n"
                "function M.run(host)\n"
                "    if not host then print('Uso: M.run(host)') return end\n"
                "    print('[*] Recon em: ' .. host)\n\n"
                "    -- DNS lookup\n"
                "    local dns = net.dns(host)\n"
                "    print('[DNS] ' .. tostring(dns))\n\n"
                "    -- Port scan basico (portas comuns)\n"
                "    local portas = {21,22,23,25,53,80,443,8080,8443}\n"
                "    print('[*] Port scan...')\n"
                "    for _, p in ipairs(portas) do\n"
                "        local ok = net.scan(host, p, p)\n"
                "        if ok and #ok > 0 then\n"
                "            print('[+] Porta aberta: ' .. p)\n"
                "        end\n"
                "    end\n\n"
                "    -- Headers HTTP\n"
                "    local h = net.geth('http://' .. host)\n"
                "    if h then print('[HTTP] ' .. tostring(h)) end\n\n"
                "    print('[+] Recon concluído')\n"
                "end\n\n"
                "function M.help()\n"
                "    print('%s.run(host)  — roda recon completo no alvo')\n"
                "end\n\n"
                "return M\n", base, base, base);

        } else if(strcmp(tipo, "util") == 0) {
            fprintf(f,
                "-- Módulo: %s (util)\n"
                "-- Template: utilitários gerais\n"
                "-- Criado pelo lmod do ElliotOS\n\n"
                "local M = {}\n\n"
                "-- Exemplo de uso:\n"
                "--   local u = require('%s')\n"
                "--   u.banner('ElliotOS')\n\n"
                "function M.banner(texto)\n"
                "    local linha = string.rep('=', #texto + 4)\n"
                "    print(linha)\n"
                "    print('| ' .. texto .. ' |')\n"
                "    print(linha)\n"
                "end\n\n"
                "function M.tabela(t)\n"
                "    -- Imprime tabela Lua de forma legível\n"
                "    for k, v in pairs(t) do\n"
                "        print(tostring(k) .. ' = ' .. tostring(v))\n"
                "    end\n"
                "end\n\n"
                "function M.trim(s)\n"
                "    return s:match('^%%s*(.-)%%s*$')\n"
                "end\n\n"
                "function M.split(s, sep)\n"
                "    local r = {}\n"
                "    for part in s:gmatch(\"([^\" .. sep .. \"]+)\") do t[#t+1] = part end\n"
                "        r[#r+1] = p\n"
                "    end\n"
                "    return r\n"
                "end\n\n"
                "function M.help()\n"
                "    print('%s.banner(txt)   — imprime banner')\n"
                "    print('%s.tabela(t)     — imprime tabela')\n"
                "    print('%s.trim(s)       — remove espaços')\n"
                "    print('%s.split(s,sep)  — divide string')\n"
                "end\n\n"
                "return M\n", base, base, base, base, base, base);

        } else {
            /* genérico — comportamento original melhorado */
            fprintf(f,
                "-- Módulo: %s\n"
                "-- Criado pelo lmod do ElliotOS\n\n"
                "local M = {}\n\n"
                "-- Escreva suas funções aqui:\n"
                "-- function M.hello()\n"
                "--   print('Olá do módulo %s!')\n"
                "-- end\n\n"
                "function M.help()\n"
                "    print('Módulo %s — sem ajuda definida ainda')\n"
                "end\n\n"
                "return M\n", base, base, base);
        }
        fclose(f);
    }

    lua_pushstring(L, path);
    printf("\033[1;32m  ✓ Módulo '%s' criado [%s]:\033[0m %s\n", base, tipo, path);
    printf("\033[0;90m  Use: local m = require('%s')\033[0m\n", base);

    /* Garante que o diretório está no package.path desta sessão */
    {
        char _lmod_entry[768];
        snprintf(_lmod_entry, sizeof(_lmod_entry), "%s/?.lua", dir);
        lua_getglobal(L, "package");
        if (!lua_isnil(L, -1)) {
            lua_getfield(L, -1, "path");
            const char *_pp = lua_tostring(L, -1);
            if (!_pp || !strstr(_pp, dir)) {
                char _np[4096];
                snprintf(_np, sizeof(_np), "%s;%s/?/init.lua;%s",
                    _lmod_entry, dir, _pp ? _pp : "");
                lua_pop(L, 1);
                lua_pushstring(L, _np);
                lua_setfield(L, -2, "path");
            } else {
                lua_pop(L, 1);
            }
        }
        lua_pop(L, 1);
    }
    return 1;
}

static int l_lmod_mod(lua_State *L) {
    const char *src = luaL_checkstring(L, 1);
    char base[256], dir[512], dst[768];

    /* Extrai só o nome do arquivo (sem path) */
    const char *fname = strrchr(src, '/');
    fname = fname ? fname+1 : src;

    lmod_strip_ext(fname, base, sizeof(base));
    lmod_dir(dir, sizeof(dir));
    lmod_ensure_dir();
    snprintf(dst, sizeof(dst), "%s/%s.lua", dir, base);

    /* Copia o arquivo para ~/.lua-modules/ */
    FILE *in = fopen(src, "r");
    if(!in) return luaL_error(L, "lmod: arquivo '%s' nao encontrado", src);
    FILE *out = fopen(dst, "w");
    if(!out) { fclose(in); return luaL_error(L, "lmod: nao foi possivel escrever em '%s'", dst); }
    char buf[4096]; size_t n;
    while((n = fread(buf, 1, sizeof(buf), in)) > 0) fwrite(buf, 1, n, out);
    fclose(in); fclose(out);

    lua_pushstring(L, dst);
    printf("\033[1;32m  ✓ Módulo registrado:\033[0m %s\n", dst);
    printf("\033[0;90m  Use: require(\"%s\") ou require(\"%s.lua\")\033[0m\n", base, base);

    /* Garante que o diretório está no package.path desta sessão */
    {
        lua_getglobal(L, "package");
        if (!lua_isnil(L, -1)) {
            lua_getfield(L, -1, "path");
            const char *_pp = lua_tostring(L, -1);
            if (!_pp || !strstr(_pp, dir)) {
                char _np[4096];
                snprintf(_np, sizeof(_np), "%s/?.lua;%s/?/init.lua;%s",
                    dir, dir, _pp ? _pp : "");
                lua_pop(L, 1);
                lua_pushstring(L, _np);
                lua_setfield(L, -2, "path");
            } else {
                lua_pop(L, 1);
            }
        }
        lua_pop(L, 1);
    }
    return 1;
}

static int l_lmod_list(lua_State *L) {
    char dir[512];
    lmod_dir(dir, sizeof(dir));
    DIR *d = opendir(dir);
    lua_newtable(L);
    if(!d) return 1;
    struct dirent *ent;
    int idx = 1;
    printf("\033[1;35m  Módulos em %s:\033[0m\n", dir);
    while((ent = readdir(d))) {
        if(ent->d_name[0] == '.') continue;
        char name[256]; lmod_strip_ext(ent->d_name, name, sizeof(name));
        printf("  \033[1;32m  • %s\033[0m\n", name);
        lua_pushstring(L, name);
        lua_rawseti(L, -2, idx++);
    }
    if(idx == 1) printf("  \033[0;90m  (nenhum módulo instalado)\033[0m\n");
    closedir(d);
    return 1;
}

static int l_lmod_remove(lua_State *L) {
    const char *name = luaL_checkstring(L, 1);
    char base[256], dir[512], path[768];
    lmod_strip_ext(name, base, sizeof(base));
    lmod_dir(dir, sizeof(dir));
    snprintf(path, sizeof(path), "%s/%s.lua", dir, base);
    if(remove(path) == 0) {
        printf("\033[1;32m  ✓ Módulo '%s' removido\033[0m\n", base);
        lua_pushboolean(L, 1);
    } else {
        printf("\033[1;31m  ✗ Módulo '%s' não encontrado\033[0m\n", base);
        lua_pushboolean(L, 0);
    }
    return 1;
}

static int l_lmod_path(lua_State *L) {
    char dir[512];
    lmod_dir(dir, sizeof(dir));
    printf("\033[1;35m  Diretório de módulos:\033[0m %s\n", dir);
    lua_pushstring(L, dir);
    return 1;
}

static void elliot_load_prelude(lua_State *L);  /* forward declaration */

static int l_lmod_help(lua_State *L) {
    (void)L;
    printf(
        "\033[1;35m  lmod — Gerenciador de módulos pessoais\033[0m\n\n"

        "  \033[1;32mlmod.new(\"nome\" [, tipo])\033[0m\n"
        "  \033[0;90m    Cria um novo módulo em ~/.lua-modules/ com template pronto\033[0m\n"
        "  \033[0;90m    tipo: \"scanner\" | \"recon\" | \"util\" | \"generic\" (padrão)\033[0m\n\n"

        "  \033[1;36m  Templates disponíveis:\033[0m\n"
        "  \033[0;90m    \"scanner\" — scanner de vulnerabilidades (usa net — requer perfil meio/god)\033[0m\n"
        "  \033[0;90m    \"recon\"   — reconhecimento passivo: DNS, port scan, headers\033[0m\n"
        "  \033[0;90m    \"util\"    — utilitários: banner, tabela, trim, split\033[0m\n"
        "  \033[0;90m    \"generic\" — módulo em branco com help() vazio\033[0m\n\n"

        "  \033[1;32mlmod.mod(\"arquivo.lua\")\033[0m\n"
        "  \033[0;90m    Registra um arquivo .lua existente como módulo global\033[0m\n\n"

        "  \033[1;32mlmod.list()\033[0m\n"
        "  \033[0;90m    Lista todos os módulos instalados\033[0m\n\n"

        "  \033[1;32mlmod.remove(\"nome\")\033[0m\n"
        "  \033[0;90m    Remove um módulo instalado\033[0m\n\n"

        "  \033[1;32mlmod.path()\033[0m\n"
        "  \033[0;90m    Mostra o diretório de módulos (~/.lua-modules)\033[0m\n\n"

        "  \033[1;36mExemplos:\033[0m\n"
        "  \033[0;90m    lmod.new(\"myscanner\", \"scanner\")  -- scanner pronto pra editar\033[0m\n"
        "  \033[0;90m    lmod.new(\"myrecon\",   \"recon\")    -- recon com DNS + port scan\033[0m\n"
        "  \033[0;90m    lmod.new(\"utils\",     \"util\")     -- helpers: trim, split...\033[0m\n"
        "  \033[0;90m    lmod.new(\"meu\")                   -- módulo genérico em branco\033[0m\n"
        "  \033[0;90m    lmod.mod(\"/sdcard/meu.lua\")       -- registra arquivo existente\033[0m\n"
        "  \033[0;90m    local s = require(\"myscanner\")    -- carrega e usa\033[0m\n"
        "  \033[0;90m    s.scan(\"http://alvo.com\")         -- roda o scan\033[0m\n"
    );
    return 0;
}

/* ── elliot_load_prelude — carrega util/json/string/table extensions ── */
static void elliot_load_prelude(lua_State *L) {
    int _prelude_rc = luaL_dostring(L,

/* -- util -------------------------------------------------------------- */
"util = {}\n"

/* util.map(t, fn) -> nova tabela com fn aplicada a cada elemento */
"function util.map(t, fn)\n"
"  local r = {}\n"
"  for i,v in ipairs(t) do r[i] = fn(v, i) end\n"
"  return r\n"
"end\n"

/* util.filter(t, fn) -> elementos onde fn(v) == true */
"function util.filter(t, fn)\n"
"  local r = {}\n"
"  for _,v in ipairs(t) do if fn(v) then r[#r+1] = v end end\n"
"  return r\n"
"end\n"

/* util.reduce(t, fn, acc) -> valor acumulado */
"function util.reduce(t, fn, acc)\n"
"  for _,v in ipairs(t) do acc = fn(acc, v) end\n"
"  return acc\n"
"end\n"

/* util.any(t, fn) / util.all(t, fn) */
"function util.any(t, fn)\n"
"  fn = fn or function(v) return v end\n"
"  for _,v in ipairs(t) do if fn(v) then return true end end\n"
"  return false\n"
"end\n"
"function util.all(t, fn)\n"
"  fn = fn or function(v) return v end\n"
"  for _,v in ipairs(t) do if not fn(v) then return false end end\n"
"  return true\n"
"end\n"

/* util.keys / util.values -- equivalente a dict.keys() */
"function util.keys(t)\n"
"  local r = {}\n"
"  for k in pairs(t) do r[#r+1] = k end\n"
"  return r\n"
"end\n"
"function util.values(t)\n"
"  local r = {}\n"
"  for _,v in pairs(t) do r[#r+1] = v end\n"
"  return r\n"
"end\n"

/* util.range(a, b, step) -- como range() do Python */
"function util.range(a, b, step)\n"
"  if b == nil then b = a; a = 1 end\n"
"  step = step or 1\n"
"  local r = {}\n"
"  local i = a\n"
"  while (step > 0 and i <= b) or (step < 0 and i >= b) do\n"
"    r[#r+1] = i; i = i + step\n"
"  end\n"
"  return r\n"
"end\n"

/* util.enumerate(t) -> {{i,v}, ...} como enumerate() do Python */
"function util.enumerate(t, start)\n"
"  start = start or 1\n"
"  local r = {}\n"
"  for i,v in ipairs(t) do r[#r+1] = {start+i-1, v} end\n"
"  return r\n"
"end\n"

/* util.zip(t1, t2, ...) -- como zip() do Python */
"function util.zip(...)\n"
"  local args = {...}; local r = {}; local n = math.huge\n"
"  for _,t in ipairs(args) do n = math.min(n, #t) end\n"
"  if n == math.huge then return {} end\n"
"  for i = 1, n do\n"
"    local row = {}\n"
"    for _,t in ipairs(args) do row[#row+1] = t[i] end\n"
"    r[#r+1] = row\n"
"  end\n"
"  return r\n"
"end\n"

/* util.flatten(t, depth) -- achata tabelas aninhadas */
"function util.flatten(t, depth)\n"
"  depth = depth or math.huge\n"
"  local r = {}\n"
"  local function flat(tt, d)\n"
"    for _,v in ipairs(tt) do\n"
"      if type(v) == 'table' and d > 0 then flat(v, d-1)\n"
"      else r[#r+1] = v end\n"
"    end\n"
"  end\n"
"  flat(t, depth); return r\n"
"end\n"

/* util.unique(t) -- remove duplicatas, mantém ordem */
"function util.unique(t)\n"
"  local seen = {}; local r = {}\n"
"  for _,v in ipairs(t) do\n"
"    local key = tostring(v)\n"
"    if not seen[key] then seen[key]=true; r[#r+1]=v end\n"
"  end\n"
"  return r\n"
"end\n"

/* util.count(t, fn_or_val) -- conta ocorrencias */
"function util.count(t, fn_or_val)\n"
"  local n = 0\n"
"  if type(fn_or_val) == 'function' then\n"
"    for _,v in ipairs(t) do if fn_or_val(v) then n=n+1 end end\n"
"  else\n"
"    for _,v in ipairs(t) do if v == fn_or_val then n=n+1 end end\n"
"  end\n"
"  return n\n"
"end\n"

/* util.sum / util.min / util.max */
"function util.sum(t, fn)\n"
"  local s = 0\n"
"  for _,v in ipairs(t) do s = s + (fn and fn(v) or v) end\n"
"  return s\n"
"end\n"
"function util.min(t, fn)\n"
"  local m = nil\n"
"  for _,v in ipairs(t) do\n"
"    local x = fn and fn(v) or v\n"
"    if m == nil or x < m then m = x end\n"
"  end\n"
"  return m\n"
"end\n"
"function util.max(t, fn)\n"
"  local m = nil\n"
"  for _,v in ipairs(t) do\n"
"    local x = fn and fn(v) or v\n"
"    if m == nil or x > m then m = x end\n"
"  end\n"
"  return m\n"
"end\n"

/* util.sorted(t, fn) -- retorna copia ordenada */
"function util.sorted(t, fn)\n"
"  local r = {}\n"
"  for _,v in ipairs(t) do r[#r+1] = v end\n"
"  table.sort(r, fn); return r\n"
"end\n"

/* util.groupby(t, fn) -> {key -> [items]} */
"function util.groupby(t, fn)\n"
"  local r = {}\n"
"  for _,v in ipairs(t) do\n"
"    local k = tostring(fn(v))\n"
"    if not r[k] then r[k] = {} end\n"
"    r[k][#r[k]+1] = v\n"
"  end\n"
"  return r\n"
"end\n"

/* util.chunk(t, n) -- divide em blocos de n */
"function util.chunk(t, n)\n"
"  local r = {}; local chunk = {}\n"
"  for _,v in ipairs(t) do\n"
"    chunk[#chunk+1] = v\n"
"    if #chunk == n then r[#r+1] = chunk; chunk = {} end\n"
"  end\n"
"  if #chunk > 0 then r[#r+1] = chunk end\n"
"  return r\n"
"end\n"

/* util.pick / util.omit -- como lodash */
"function util.pick(t, keys)\n"
"  local r = {}\n"
"  for _,k in ipairs(keys) do r[k] = t[k] end\n"
"  return r\n"
"end\n"
"function util.omit(t, keys)\n"
"  local skip = {}; for _,k in ipairs(keys) do skip[k]=true end\n"
"  local r = {}\n"
"  for k,v in pairs(t) do if not skip[k] then r[k]=v end end\n"
"  return r\n"
"end\n"

/* util.merge(t1, t2, ...) -- merge de tabelas (t2 sobrescreve t1) */
"function util.merge(...)\n"
"  local r = {}\n"
"  for _,t in ipairs({...}) do\n"
"    for k,v in pairs(t) do r[k] = v end\n"
"  end\n"
"  return r\n"
"end\n"

/* util.deepcopy(t) -- copia profunda */
"function util.deepcopy(orig)\n"
"  local t = type(orig)\n"
"  if t ~= 'table' then return orig end\n"
"  local copy = {}\n"
"  for k,v in pairs(orig) do copy[util.deepcopy(k)] = util.deepcopy(v) end\n"
"  setmetatable(copy, getmetatable(orig))\n"
"  return copy\n"
"end\n"

/* util.partial(fn, ...) -- aplicação parcial de função */
"function util.partial(fn, ...)\n"
"  local bound = {...}\n"
"  return function(...)\n"
"    local args = {table.unpack(bound)}\n"
"    for _,v in ipairs({...}) do args[#args+1] = v end\n"
"    return fn(table.unpack(args))\n"
"  end\n"
"end\n"

/* util.memoize(fn) -- cache de resultados */
"function util.memoize(fn)\n"
"  local cache = {}\n"
"  return function(...)\n"
"    local key = table.concat({...}, '\\0')\n"
"    if cache[key] == nil then cache[key] = fn(...) end\n"
"    return cache[key]\n"
"  end\n"
"end\n"

/* util.once(fn) -- executa so uma vez */
"function util.once(fn)\n"
"  local done = false; local result\n"
"  return function(...)\n"
"    if not done then done=true; result=fn(...) end\n"
"    return result\n"
"  end\n"
"end\n"

/* util.retry(fn, n, delay_ms) -- tenta n vezes com delay */
"function util.retry(fn, n, delay_ms)\n"
"  n = n or 3; delay_ms = delay_ms or 0\n"
"  for i = 1, n do\n"
"    local ok, err = pcall(fn)\n"
"    if ok then return true end\n"
"    if i < n and delay_ms > 0 then sys.sleep(delay_ms/1000) end\n"
"  end\n"
"  return false\n"
"end\n"

/* util.with_file(path, mode, fn) -- context manager estilo Python 'with open' */
"function util.with_file(path, mode, fn)\n"
"  local f, err = io.open(path, mode)\n"
"  if not f then error('with_file: ' .. (err or path)) end\n"
"  local ok, e = pcall(fn, f)\n"
"  f:close()\n"
"  if not ok then error(e) end\n"
"end\n"

/* util.printf -- printf conveniente */
"function util.printf(fmt, ...)\n"
"  io.write(string.format(fmt, ...))\n"
"end\n"

/* util.pp -- pretty print de qualquer valor */
"do\n"
"  local function _pp(v, indent, seen)\n"
"    indent = indent or 0; seen = seen or {}\n"
"    local pad = string.rep('  ', indent)\n"
"    if type(v) == 'table' then\n"
"      if seen[v] then return pad .. '<circular>' end\n"
"      seen[v] = true\n"
"      local lines = {'{'}\n"
"      for k,val in pairs(v) do\n"
"        local ks = type(k)=='string' and k or ('['..tostring(k)..']')\n"
"        lines[#lines+1] = pad..'  '..ks..' = '.._pp(val,indent+1,seen)\n"
"      end\n"
"      lines[#lines+1] = pad .. '}'\n"
"      return table.concat(lines,'\\n')\n"
"    elseif type(v) == 'string' then\n"
"      return string.format('%q', v)\n"
"    else\n"
"      return tostring(v)\n"
"    end\n"
"  end\n"
"  function util.pp(v)\n"
"    print(_pp(v, 0, {}))\n"
"  end\n"
"end\n"

/* util.help() -- referencia rapida */
"function util.help()\n"
"  local E=string.char(27)\n"
"  local R=E..'[0m'\n"
"  local B=E..'[1m'\n"
"  local G=E..'[1;32m'\n"
"  local M=E..'[1;35m'\n"
"  local C=E..'[1;36m'\n"
"  local D=E..'[2m'\n"
"  local function h(t) print(C..'  -- '..t..R) end\n"
"  local function s(f,d) print('  '..G..f..R..'  '..D..d..R) end\n"
"  print(M)\n"
"  print('  '..B..'util'..R..' -- stdlib funcional para Lua')\n"
"  print('')\n"
"  h('Transformacao')\n"
"  s('util.map(t,fn)',         '-> nova tabela com fn em cada item')\n"
"  s('util.filter(t,fn)',      '-> itens onde fn(v) e verdadeiro')\n"
"  s('util.reduce(t,fn,init)', '-> acumula com fn(acc,v)')\n"
"  s('util.sorted(t,fn)',      '-> copia ordenada; fn=comparador')\n"
"  s('util.unique(t)',         '-> remove duplicatas')\n"
"  s('util.flatten(t,depth)',  '-> achata; depth=nil=total')\n"
"  h('Predicados')\n"
"  s('util.any(t,fn)',         '-> true se algum satisfaz fn')\n"
"  s('util.all(t,fn)',         '-> true se todos satisfazem fn')\n"
"  s('util.count(t,fn)',       '-> quantos satisfazem fn')\n"
"  h('Geracao')\n"
"  s('util.range(n)',          '-> {1..n} / range(a,b) / range(a,b,step)')\n"
"  s('util.enumerate(t)',      '-> {{1,v1},{2,v2},...}')\n"
"  s('util.zip(a,b,...)',      '-> {{a1,b1},{a2,b2},...}')\n"
"  s('util.chunk(t,n)',        '-> divide em sub-tabelas de n')\n"
"  h('Agregacao')\n"
"  s('util.sum(t)',            '-> soma')\n"
"  s('util.min(t)',            '-> menor valor')\n"
"  s('util.max(t)',            '-> maior valor')\n"
"  s('util.groupby(t,fn)',     '-> {key->{itens}} agrupados por fn')\n"
"  h('Tabelas e dicts')\n"
"  s('util.keys(t)',           '-> lista de chaves')\n"
"  s('util.values(t)',         '-> lista de valores')\n"
"  s('util.pick(t,keys)',      '-> sub-tabela com as chaves')\n"
"  s('util.omit(t,keys)',      '-> sub-tabela sem as chaves')\n"
"  s('util.merge(a,b,...)',    '-> une tabelas (b sobrescreve a)')\n"
"  s('util.deepcopy(t)',       '-> copia profunda recursiva')\n"
"  h('Funcoes de alta ordem')\n"
"  s('util.partial(fn,...)',   '-> currying / args parciais')\n"
"  s('util.memoize(fn)',       '-> cacheia resultados')\n"
"  s('util.once(fn)',          '-> executa so na primeira chamada')\n"
"  s('util.retry(fn,n,delay)', '-> tenta n vezes com delay')\n"
"  h('IO e Debug')\n"
"  s('util.with_file(p,m,fn)', '-> abre arquivo, chama fn(f), fecha')\n"
"  s('util.pp(v)',             '-> pretty-print de qualquer valor')\n"
"  s('util.printf(fmt,...)',   '-> print com string.format')\n"
"  print(R)\n"
"end\n"

/* string.help() -- referencia rapida */
"function string.help()\n"
"  local E=string.char(27)\n"
"  local R=E..'[0m'\n"
"  local B=E..'[1m'\n"
"  local G=E..'[1;32m'\n"
"  local M=E..'[1;35m'\n"
"  local C=E..'[1;36m'\n"
"  local D=E..'[2m'\n"
"  local function h(t) print(C..'  -- '..t..R) end\n"
"  local function s(f,d) print('  '..G..f..R..'  '..D..d..R) end\n"
"  print(M)\n"
"  print('  '..B..'string'..R..' -- extensoes de string para Lua')\n"
"  print('')\n"
"  h('Limpeza e busca')\n"
"  s('string.trim(s)',              '-> remove espacos das duas pontas')\n"
"  s('string.ltrim(s)',             '-> remove espacos da esquerda')\n"
"  s('string.rtrim(s)',             '-> remove espacos da direita')\n"
"  s('string.startswith(s,prefix)', '-> true se comeca com prefix')\n"
"  s('string.endswith(s,suffix)',   '-> true se termina com suffix')\n"
"  s('string.contains(s,sub)',      '-> true se sub esta em s')\n"
"  s('string.count_occ(s,sub)',     '-> numero de ocorrencias de sub')\n"
"  s('string.removeprefix(s,p)',    '-> remove prefixo se presente')\n"
"  s('string.removesuffix(s,p)',    '-> remove sufixo se presente')\n"
"  h('Divisao')\n"
"  s('string.split(s,sep)',         '-> tabela de partes')\n"
"  s('string.lines(s)',             '-> tabela de linhas (CRLF ok)')\n"
"  s('string.words(s)',             '-> tabela de palavras')\n"
"  s('string.partition(s,sep)',     '-> antes, sep, depois (1a ocorrencia)')\n"
"  s('string.rpartition(s,sep)',    '-> antes, sep, depois (ultima ocorrencia)')\n"
"  h('Formatacao e padding')\n"
"  s('string.lpad(s,n,ch)',         '-> alinha a direita com ch')\n"
"  s('string.rpad(s,n,ch)',         '-> alinha a esquerda com ch')\n"
"  s('string.center(s,n,ch)',       '-> centraliza com ch')\n"
"  s('string.ljust(s,n,ch)',        '-> alias de rpad')\n"
"  s('string.rjust(s,n,ch)',        '-> alias de lpad')\n"
"  s('string.zfill(s,n)',           '-> preenche com zeros a esquerda')\n"
"  s('string.truncate(s,n,suf)',    '-> corta em n chars + sufixo')\n"
"  s('string.repeat_str(s,n)',      '-> repete s n vezes')\n"
"  s('string.expandtabs(s,n)',      '-> expande tabs em n espacos (padrao 8)')\n"
"  h('Transformacao')\n"
"  s('string.slugify(s)',           '-> Ola Mundo -> ola-mundo')\n"
"  s('string.capitalize(s)',        '-> primeira letra maiuscula')\n"
"  s('string.title(s)',             '-> Cada Palavra Maiuscula')\n"
"  s('string.swapcase(s)',          '-> inverte maiusculas/minusculas')\n"
"  s('string.escape_html(s)',       '-> & < > para entidades HTML')\n"
"  s('string.unescape_html(s)',     '-> entidades HTML para chars')\n"
"  s('string.encode_url(s)',        '-> percent-encoding para URLs')\n"
"  s('string.decode_url(s)',        '-> decodifica percent-encoding')\n"
"  s('string.interpolate(s,vars)',  '-> {host}:{port} com vars=tabela')\n"
"  h('Inspecao e validacao')\n"
"  s('string.isnumeric(s)',         '-> true se todos os chars sao digitos')\n"
"  s('string.isinteger(s)',         '-> true se representa inteiro')\n"
"  s('string.isalpha(s)',           '-> true se so letras')\n"
"  s('string.isalnum(s)',           '-> true se letras e digitos')\n"
"  s('string.isspace(s)',           '-> true se so espacos/tabs/newlines')\n"
"  s('string.islower(s)',           '-> true se todas minusculas')\n"
"  s('string.isupper(s)',           '-> true se todas maiusculas')\n"
"  print(D..'  Dica: use como metodo: s:trim()  s:split(\\\",\\\")  s:interpolate(t)'..R)\n"
"  print(R)\n"
"end\n"


/* -- string extensions ------------------------------------------------- */
"function string.split(s, sep, plain)\n"
"  local t, i = {}, 1\n"
"  sep = sep or '%s+'\n"
"  while i <= #s + 1 do\n"
"    local ps, pe = s:find(sep, i, plain or false)\n"
"    if ps then\n"
"      local part = s:sub(i, ps-1)\n"
"      if part ~= '' then t[#t+1] = part end\n"
"      i = pe + 1\n"
"    else\n"
"      local part = s:sub(i)\n"
"      if part ~= '' then t[#t+1] = part end\n"
"      break\n"
"    end\n"
"  end\n"
"  return setmetatable(t, {__tostring=function(tb) local r={}; for _,v in ipairs(tb) do r[#r+1]='['..tostring(#r+1)..'] '..tostring(v) end; return table.concat(r,'\\n') end})\n"
"end\n"
"function string.trim(s) return s:match('^%s*(.-)%s*$') end\n"
"function string.ltrim(s) return s:match('^%s*(.*)') end\n"
"function string.rtrim(s) return s:match('(.-)%s*$') end\n"
"function string.startswith(s, p) return s:sub(1,#p)==p end\n"
"function string.endswith(s, p) return p=='' or s:sub(-#p)==p end\n"
"function string.contains(s, p) return s:find(p,1,true)~=nil end\n"
"function string.count_occ(s, p)\n"
"  local n,i = 0,1\n"
"  while true do local j=s:find(p,i,true); if not j then break end; n=n+1; i=j+#p end\n"
"  return n\n"
"end\n"
"function string.lpad(s, n, ch) ch=ch or ' '; s=tostring(s); return string.rep(ch,math.max(0,n-#s))..s end\n"
"function string.rpad(s, n, ch) ch=ch or ' '; s=tostring(s); return s..string.rep(ch,math.max(0,n-#s)) end\n"
"function string.center(s, n, ch)\n"
"  ch=ch or ' '; s=tostring(s)\n"
"  local pad=math.max(0,n-#s); local l=math.floor(pad/2); local r=pad-l\n"
"  return string.rep(ch,l)..s..string.rep(ch,r)\n"
"end\n"
"function string.truncate(s, n, suf) suf=suf or '...'; if #s<=n then return s end; return s:sub(1,n-#suf)..suf end\n"
"function string.repeat_str(s, n) return string.rep(s,n) end\n"
"function string.lines(s)\n"
"  local t={}\n"
"  local CR,LF=string.char(13),string.char(10)\n"
"  s=s:gsub(CR..LF,LF):gsub(CR,LF)\n"
"  if s:sub(-1)~=LF then s=s..LF end\n"
"  for l in s:gmatch('([^'..LF..']*)'..LF) do t[#t+1]=l end\n"
"  return setmetatable(t, {__tostring=function(tb) local r={}; for _,v in ipairs(tb) do r[#r+1]='['..tostring(#r+1)..'] '..tostring(v) end; return table.concat(r,'\\n') end})\n"
"end\n"
"function string.words(s) local t={}; for w in s:gmatch('%S+') do t[#t+1]=w end; return setmetatable(t, {__tostring=function(tb) local r={}; for _,v in ipairs(tb) do r[#r+1]='['..tostring(#r+1)..'] '..tostring(v) end; return table.concat(r,'\\n') end}) end\n"
"function string.slugify(s)\n"
"  s=s:lower():gsub('[%s_]+','-'):gsub('[^%w%-]',''):gsub('%-+','-'):gsub('^%-',''):gsub('%-$','')\n"
"  return s\n"
"end\n"
"function string.escape_html(s)\n"
"  local q=string.char(34); local sq=string.char(39)\n"
"  return s:gsub('&','&amp;'):gsub('<','&lt;'):gsub('>','&gt;'):gsub(q,'&quot;'):gsub(sq,'&#39;')\n"
"end\n"
"function string.unescape_html(s)\n"
"  local q=string.char(34); local sq=string.char(39)\n"
"  return s:gsub('&amp;','&'):gsub('&lt;','<'):gsub('&gt;','>'):gsub('&quot;',q):gsub('&#39;',sq)\n"
"end\n"
"function string.interpolate(s, vars)\n"
"  return (s:gsub('{([%w_]+)}', function(k) local v=vars[k]; if v==nil then return '{'..k..'}' end; return tostring(v) end))\n"
"end\n"

/* -- Extensões de table ------------------------------------------------ */
"function table.keys(t)\n"
"  local r = {}; for k in pairs(t) do r[#r+1] = k end; return r\n"
"end\n"
"function table.values(t)\n"
"  local r = {}; for _,v in pairs(t) do r[#r+1] = v end; return r\n"
"end\n"
"function table.contains(t, val)\n"
"  for _,v in ipairs(t) do if v == val then return true end end\n"
"  return false\n"
"end\n"
"function table.copy(t)\n"
"  local r = {}; for k,v in pairs(t) do r[k]=v end; return r\n"
"end\n"
"function table.extend(t1, t2)\n"
"  for _,v in ipairs(t2) do t1[#t1+1] = v end; return t1\n"
"end\n"
"function table.clear(t)\n"
"  for k in pairs(t) do t[k]=nil end\n"
"end\n"
"function table.length(t)\n"
"  local n = 0; for _ in pairs(t) do n=n+1 end; return n\n"
"end\n"

/* -- json -- encode/decode em Lua puro -------------------------------- */
"do\n"
"  local json = {}\n"
"\n"
"  -- encode\n"
"  local function enc(v, indent, lvl)\n"
"    local t = type(v)\n"
"    if t == 'nil' then return 'null'\n"
"    elseif t == 'boolean' then return v and 'true' or 'false'\n"
"    elseif t == 'number' then\n"
"      if v ~= v then return 'null' end  -- NaN\n"
"      if v == math.huge or v == -math.huge then return 'null' end\n"
"      if math.floor(v) == v and math.abs(v) < 1e15 then\n"
"        return string.format('%d', v)\n"
"      end\n"
"      return string.format('%.14g', v)\n"
"    elseif t == 'string' then\n"
"      v = v:gsub('\\\\', '\\\\\\\\')\n"
"           :gsub('\"', '\\\\\"')\n"
"           :gsub('\\n', '\\\\n')\n"
"           :gsub('\\r', '\\\\r')\n"
"           :gsub('\\t', '\\\\t')\n"
"      return '\"' .. v .. '\"'\n"
"    elseif t == 'table' then\n"
"      lvl = lvl or 0\n"
"      -- detecta array\n"
"      local is_arr = true; local n = 0\n"
"      for k in pairs(v) do\n"
"        n = n + 1\n"
"        if type(k) ~= 'number' or k ~= math.floor(k) or k < 1 then\n"
"          is_arr = false; break\n"
"        end\n"
"      end\n"
"      if is_arr and n == #v then\n"
"        local parts = {}\n"
"        for i = 1, #v do parts[i] = enc(v[i], indent, lvl+1) end\n"
"        return '[' .. table.concat(parts, ',') .. ']'\n"
"      else\n"
"        local parts = {}\n"
"        for k,val in pairs(v) do\n"
"          parts[#parts+1] = '\"'..tostring(k)..'\":'..enc(val,indent,lvl+1)\n"
"        end\n"
"        return '{' .. table.concat(parts, ',') .. '}'\n"
"      end\n"
"    end\n"
"    return 'null'\n"
"  end\n"
"\n"
"  function json.encode(v) return enc(v) end\n"
"\n"
"  -- decode\n"
"  local function skip(s, i)\n"
"    while i <= #s and s:sub(i,i):match('%s') do i=i+1 end; return i\n"
"  end\n"
"  local parse_val  -- forward\n"
"  local function parse_str(s, i)\n"
"    i = i + 1  -- skip opening quote\n"
"    local r = {}\n"
"    while i <= #s do\n"
"      local c = s:sub(i,i)\n"
"      if c == '\"' then return table.concat(r), i+1 end\n"
"      if c == '\\\\' then\n"
"        local e = s:sub(i+1,i+1)\n"
"        if     e=='\"' then r[#r+1]='\"'\n"
"        elseif e=='\\\\' then r[#r+1]='\\\\'\n"
"        elseif e=='/' then r[#r+1]='/'\n"
"        elseif e=='n' then r[#r+1]='\\n'\n"
"        elseif e=='r' then r[#r+1]='\\r'\n"
"        elseif e=='t' then r[#r+1]='\\t'\n"
"        elseif e=='b' then r[#r+1]='\\b'\n"
"        elseif e=='f' then r[#r+1]='\\f'\n"
"        else r[#r+1]=e end\n"
"        i = i + 2\n"
"      else\n"
"        r[#r+1] = c; i = i + 1\n"
"      end\n"
"    end\n"
"    error('json.decode: string sem fechar')\n"
"  end\n"
"  local function parse_arr(s, i)\n"
"    i = i + 1; local r = {}; i = skip(s,i)\n"
"    if s:sub(i,i) == ']' then return r, i+1 end\n"
"    while true do\n"
"      local v; v, i = parse_val(s, i)\n"
"      r[#r+1] = v; i = skip(s,i)\n"
"      local c = s:sub(i,i)\n"
"      if c == ']' then return r, i+1\n"
"      elseif c == ',' then i = skip(s, i+1)\n"
"      else error('json.decode: esperava , ou ]') end\n"
"    end\n"
"  end\n"
"  local function parse_obj(s, i)\n"
"    i = i + 1; local r = {}; i = skip(s,i)\n"
"    if s:sub(i,i) == '}' then return r, i+1 end\n"
"    while true do\n"
"      i = skip(s,i)\n"
"      if s:sub(i,i) ~= '\"' then error('json.decode: chave esperada') end\n"
"      local k; k, i = parse_str(s, i)\n"
"      i = skip(s,i)\n"
"      if s:sub(i,i) ~= ':' then error('json.decode: : esperado') end\n"
"      i = skip(s, i+1)\n"
"      local v; v, i = parse_val(s, i)\n"
"      r[k] = v; i = skip(s,i)\n"
"      local c = s:sub(i,i)\n"
"      if c == '}' then return r, i+1\n"
"      elseif c == ',' then i = skip(s, i+1)\n"
"      else error('json.decode: esperava , ou }') end\n"
"    end\n"
"  end\n"
"  parse_val = function(s, i)\n"
"    i = skip(s,i)\n"
"    local c = s:sub(i,i)\n"
"    if c == '\"' then return parse_str(s,i)\n"
"    elseif c == '[' then return parse_arr(s,i)\n"
"    elseif c == '{' then return parse_obj(s,i)\n"
"    elseif c == 't' then return true, i+4\n"
"    elseif c == 'f' then return false, i+5\n"
"    elseif c == 'n' then return nil, i+4\n"
"    else\n"
"      local ns, ne = s:find('^-?%d+%.?%d*[eE]?[+-]?%d*', i)\n"
"      if ns then return tonumber(s:sub(ns,ne)), ne+1 end\n"
"      error('json.decode: token inesperado em pos '..i..': '..c)\n"
"    end\n"
"  end\n"
"  function json.decode(s)\n"
"    if type(s) ~= 'string' then error('json.decode: esperava string') end\n"
"    local v, _ = parse_val(s, skip(s,1))\n"
"    return v\n"
"  end\n"
"\n"
"  -- Atalhos no global: json.encode / json.decode\n"
"  _G.json = json\n"
"end\n"

/* -- Injeção de metodos em string via __index -------------------------- */
/* Permite: (\"hello world\"):split(\" \")  ->  {\"hello\", \"world\"} */
/* Nota: já funciona automaticamente porque Lua roteia metodos de string
   via getmetatable('').__index = string, então string.split etc. já
   ficam disponíveis como s:split() sem nenhuma metatable extra.       */

/* ======================================================================
   ELLIOTOS v17 — STDLIB PATCH: date.* | util.stats | util.iter/chain
   string.upper/lower/isnumeric/isalpha/isspace/zfill/swapcase/title
   Traz ElliotOS ao nível Python 3 sem root, sem C extra, puro Lua.
   ====================================================================== */

/* ── date.* — módulo de data/hora estilo Python datetime ─────────────── */
"do\n"
"  local date = {}\n"
"\n"
"  -- date.now() -> {year,month,day,hour,min,sec,wday,yday,ts}\n"
"  function date.now()\n"
"    local t = os.time()\n"
"    local d = os.date('*t', t)\n"
"    d.ts = t\n"
"    return d\n"
"  end\n"
"\n"
"  -- date.today() -> string 'YYYY-MM-DD'\n"
"  function date.today()\n"
"    return os.date('%Y-%m-%d')\n"
"  end\n"
"\n"
"  -- date.format(ts_or_table, fmt) -> string\n"
"  -- fmt padrao: '%Y-%m-%d %H:%M:%S'  (igual strftime Python)\n"
"  function date.format(t, fmt)\n"
"    fmt = fmt or '%Y-%m-%d %H:%M:%S'\n"
"    if type(t) == 'table' then t = os.time(t) end\n"
"    return os.date(fmt, t)\n"
"  end\n"
"\n"
"  -- date.parse(s) -> timestamp (numero)\n"
"  -- Suporta: 'YYYY-MM-DD', 'YYYY-MM-DD HH:MM:SS', 'DD/MM/YYYY', 'DD/MM/YYYY HH:MM:SS'\n"
"  function date.parse(s)\n"
"    if type(s) ~= 'string' then error('date.parse: esperava string') end\n"
"    local y,mo,d,h,mi,sec\n"
"    -- YYYY-MM-DD HH:MM:SS\n"
"    y,mo,d,h,mi,sec = s:match('^(%d%d%d%d)-(%d%d)-(%d%d) (%d%d):(%d%d):(%d%d)$')\n"
"    if y then return os.time({year=y+0,month=mo+0,day=d+0,hour=h+0,min=mi+0,sec=sec+0}) end\n"
"    -- YYYY-MM-DD\n"
"    y,mo,d = s:match('^(%d%d%d%d)-(%d%d)-(%d%d)$')\n"
"    if y then return os.time({year=y+0,month=mo+0,day=d+0,hour=0,min=0,sec=0}) end\n"
"    -- DD/MM/YYYY HH:MM:SS\n"
"    d,mo,y,h,mi,sec = s:match('^(%d%d)/(%d%d)/(%d%d%d%d) (%d%d):(%d%d):(%d%d)$')\n"
"    if y then return os.time({year=y+0,month=mo+0,day=d+0,hour=h+0,min=mi+0,sec=sec+0}) end\n"
"    -- DD/MM/YYYY\n"
"    d,mo,y = s:match('^(%d%d)/(%d%d)/(%d%d%d%d)$')\n"
"    if y then return os.time({year=y+0,month=mo+0,day=d+0,hour=0,min=0,sec=0}) end\n"
"    error('date.parse: formato nao reconhecido: ' .. s)\n"
"  end\n"
"\n"
"  -- date.diff(a, b) -> tabela {days, hours, minutes, seconds, total_seconds}\n"
"  -- a e b podem ser timestamps (number) ou strings parseáveis\n"
"  function date.diff(a, b)\n"
"    if type(a) == 'string' then a = date.parse(a) end\n"
"    if type(b) == 'string' then b = date.parse(b) end\n"
"    local delta = math.abs(a - b)\n"
"    local days  = math.floor(delta / 86400)\n"
"    local rem   = delta % 86400\n"
"    local hours = math.floor(rem / 3600)\n"
"    rem = rem % 3600\n"
"    local mins  = math.floor(rem / 60)\n"
"    local secs  = rem % 60\n"
"    return {days=days, hours=hours, minutes=mins, seconds=secs, total_seconds=delta}\n"
"  end\n"
"\n"
"  -- date.add(ts, opts) -> novo timestamp\n"
"  -- opts: {days=N, hours=N, minutes=N, seconds=N}\n"
"  function date.add(ts, opts)\n"
"    if type(ts) == 'string' then ts = date.parse(ts) end\n"
"    local delta = (opts.days or 0)*86400 + (opts.hours or 0)*3600\n"
"               + (opts.minutes or 0)*60  + (opts.seconds or 0)\n"
"    return ts + delta\n"
"  end\n"
"\n"
"  -- date.sub(ts, opts) -> novo timestamp (subtrai)\n"
"  function date.sub(ts, opts)\n"
"    if type(ts) == 'string' then ts = date.parse(ts) end\n"
"    local delta = (opts.days or 0)*86400 + (opts.hours or 0)*3600\n"
"               + (opts.minutes or 0)*60  + (opts.seconds or 0)\n"
"    return ts - delta\n"
"  end\n"
"\n"
"  -- date.weekday(ts) -> nome do dia da semana (Portugues)\n"
"  function date.weekday(ts)\n"
"    if type(ts) == 'string' then ts = date.parse(ts) end\n"
"    local dias = {'Domingo','Segunda','Terca','Quarta','Quinta','Sexta','Sabado'}\n"
"    local w = tonumber(os.date('%w', ts)) + 1\n"
"    return dias[w]\n"
"  end\n"
"\n"
"  -- date.is_leap(year) -> boolean\n"
"  function date.is_leap(year)\n"
"    return (year % 4 == 0 and year % 100 ~= 0) or (year % 400 == 0)\n"
"  end\n"
"\n"
"  -- date.timestamp() -> unix timestamp atual (alias de os.time)\n"
"  function date.timestamp() return os.time() end\n"
"\n"
"  -- date.from_timestamp(n) -> tabela {year,month,day,hour,min,sec}\n"
"  function date.from_timestamp(n)\n"
"    local d = os.date('*t', n)\n"
"    d.ts = n\n"
"    return d\n"
"  end\n"
"\n"
"  -- date.help() -> referencia rapida\n"
"  function date.help()\n"
"    local E=string.char(27); local R=E..'[0m'; local G=E..'[1;32m'\n"
"    local C=E..'[1;36m'; local D=E..'[2m'\n"
"    local function s(f,d) print('  '..G..f..R..'  '..D..d..R) end\n"
"    print(C..'  -- date.* -- modulo de data/hora'..R)\n"
"    s('date.now()',              '-> {year,month,day,hour,min,sec,ts}')\n"
"    s('date.today()',            '-> string YYYY-MM-DD')\n"
"    s('date.format(ts,fmt)',     '-> string formatada (fmt tipo strftime)')\n"
"    s('date.parse(s)',           '-> timestamp de YYYY-MM-DD ou DD/MM/YYYY')\n"
"    s('date.diff(a,b)',          '-> {days,hours,minutes,seconds,total_seconds}')\n"
"    s('date.add(ts,{days=N})',   '-> novo timestamp somando intervalo')\n"
"    s('date.sub(ts,{days=N})',   '-> novo timestamp subtraindo intervalo')\n"
"    s('date.weekday(ts)',        '-> nome do dia da semana em Portugues')\n"
"    s('date.is_leap(year)',      '-> true se ano bissexto')\n"
"    s('date.timestamp()',        '-> unix timestamp atual')\n"
"    s('date.from_timestamp(n)',  '-> tabela de data a partir de timestamp')\n"
"  end\n"
"\n"
"  _G.date = date\n"
"end\n"

/* ── util.stats — estatística estilo Python statistics ──────────────── */
"do\n"
"\n"
"  -- util.mean(t) -> media aritmetica\n"
"  function util.mean(t, fn)\n"
"    if #t == 0 then return nil end\n"
"    local s = 0\n"
"    for _,v in ipairs(t) do s = s + (fn and fn(v) or v) end\n"
"    return s / #t\n"
"  end\n"
"\n"
"  -- util.median(t) -> mediana\n"
"  function util.median(t, fn)\n"
"    if #t == 0 then return nil end\n"
"    local r = {}\n"
"    for _,v in ipairs(t) do r[#r+1] = fn and fn(v) or v end\n"
"    table.sort(r)\n"
"    local n = #r\n"
"    if n % 2 == 1 then return r[math.ceil(n/2)]\n"
"    else return (r[n/2] + r[n/2+1]) / 2 end\n"
"  end\n"
"\n"
"  -- util.mode(t) -> valor mais frequente\n"
"  function util.mode(t)\n"
"    if #t == 0 then return nil end\n"
"    local freq = {}\n"
"    for _,v in ipairs(t) do\n"
"      local k = tostring(v)\n"
"      freq[k] = (freq[k] or 0) + 1\n"
"    end\n"
"    local best_k, best_n = nil, 0\n"
"    for k,n in pairs(freq) do\n"
"      if n > best_n then best_n = n; best_k = k end\n"
"    end\n"
"    -- tenta converter de volta para number se possivel\n"
"    local num = tonumber(best_k)\n"
"    return num ~= nil and num or best_k\n"
"  end\n"
"\n"
"  -- util.variance(t) -> variancia populacional\n"
"  function util.variance(t, fn)\n"
"    if #t < 2 then return 0 end\n"
"    local m = util.mean(t, fn)\n"
"    local s = 0\n"
"    for _,v in ipairs(t) do\n"
"      local x = (fn and fn(v) or v) - m\n"
"      s = s + x*x\n"
"    end\n"
"    return s / #t\n"
"  end\n"
"\n"
"  -- util.stdev(t) -> desvio padrao populacional\n"
"  function util.stdev(t, fn)\n"
"    return math.sqrt(util.variance(t, fn))\n"
"  end\n"
"\n"
"  -- util.stdev_sample(t) -> desvio padrao amostral (n-1)\n"
"  function util.stdev_sample(t, fn)\n"
"    if #t < 2 then return 0 end\n"
"    local m = util.mean(t, fn)\n"
"    local s = 0\n"
"    for _,v in ipairs(t) do\n"
"      local x = (fn and fn(v) or v) - m\n"
"      s = s + x*x\n"
"    end\n"
"    return math.sqrt(s / (#t - 1))\n"
"  end\n"
"\n"
"  -- util.percentile(t, p) -> percentil p (0-100)\n"
"  function util.percentile(t, p)\n"
"    if #t == 0 then return nil end\n"
"    local r = {}\n"
"    for _,v in ipairs(t) do r[#r+1] = v end\n"
"    table.sort(r)\n"
"    local idx = (p / 100) * (#r - 1) + 1\n"
"    local lo  = math.floor(idx)\n"
"    local hi  = math.ceil(idx)\n"
"    if lo == hi then return r[lo] end\n"
"    return r[lo] + (r[hi] - r[lo]) * (idx - lo)\n"
"  end\n"
"\n"
"  -- util.normalize(t) -> tabela normalizada entre 0 e 1\n"
"  function util.normalize(t)\n"
"    local mn = util.min(t); local mx = util.max(t)\n"
"    local rng = mx - mn\n"
"    if rng == 0 then\n"
"      local r = {}; for i=1,#t do r[i]=0 end; return r\n"
"    end\n"
"    return util.map(t, function(v) return (v - mn) / rng end)\n"
"  end\n"
"\n"
"  -- util.clamp(v, min, max) -> valor limitado ao intervalo\n"
"  function util.clamp(v, lo, hi)\n"
"    if v < lo then return lo end\n"
"    if v > hi then return hi end\n"
"    return v\n"
"  end\n"
"\n"
"  -- util.round(n, decimals) -> arredonda para N casas decimais\n"
"  function util.round(n, decimals)\n"
"    decimals = decimals or 0\n"
"    local m = 10 ^ decimals\n"
"    return math.floor(n * m + 0.5) / m\n"
"  end\n"
"\n"
"end\n"

/* ── util.iter — geradores lazy com coroutines (como Python generators) ── */
"do\n"
"\n"
"  -- util.iter(t) -> iterador lazy sobre tabela\n"
"  function util.iter(t)\n"
"    local i = 0\n"
"    return function()\n"
"      i = i + 1\n"
"      return t[i]\n"
"    end\n"
"  end\n"
"\n"
"  -- util.generator(fn) -> cria gerador a partir de coroutine\n"
"  -- fn deve chamar coroutine.yield(valor) para emitir valores\n"
"  -- Uso: local gen = util.generator(function() for i=1,10 do coroutine.yield(i) end end)\n"
"  --      for v in gen do print(v) end\n"
"  function util.generator(fn)\n"
"    local co = coroutine.create(fn)\n"
"    return function()\n"
"      if coroutine.status(co) == 'dead' then return nil end\n"
"      local ok, val = coroutine.resume(co)\n"
"      if ok then return val else return nil end\n"
"    end\n"
"  end\n"
"\n"
"  -- util.take(iter_or_table, n) -> primeiros n valores\n"
"  function util.take(src, n)\n"
"    local r = {}\n"
"    if type(src) == 'table' then\n"
"      for i=1, math.min(n, #src) do r[i] = src[i] end\n"
"    else\n"
"      local i = 0\n"
"      for v in src do\n"
"        i = i + 1; r[i] = v\n"
"        if i >= n then break end\n"
"      end\n"
"    end\n"
"    return r\n"
"  end\n"
"\n"
"  -- util.drop(t, n) -> tabela sem os primeiros n elementos\n"
"  function util.drop(t, n)\n"
"    local r = {}\n"
"    for i = n+1, #t do r[#r+1] = t[i] end\n"
"    return r\n"
"  end\n"
"\n"
"  -- util.step(t, n) -> pega um a cada n elementos (slice com step)\n"
"  function util.step(t, n)\n"
"    local r = {}\n"
"    for i = 1, #t, n do r[#r+1] = t[i] end\n"
"    return r\n"
"  end\n"
"\n"
"  -- util.chain(t) -> objeto encadeavel estilo lodash/underscore\n"
"  -- Permite: util.chain(t).filter(fn).map(fn).sorted().value()\n"
"  function util.chain(t)\n"
"    local obj = {_data = t}\n"
"    function obj:map(fn)     self._data = util.map(self._data, fn);    return self end\n"
"    function obj:filter(fn)  self._data = util.filter(self._data, fn); return self end\n"
"    function obj:sorted(fn)  self._data = util.sorted(self._data, fn); return self end\n"
"    function obj:unique()    self._data = util.unique(self._data);      return self end\n"
"    function obj:flatten(d)  self._data = util.flatten(self._data, d); return self end\n"
"    function obj:take(n)     self._data = util.take(self._data, n);    return self end\n"
"    function obj:drop(n)     self._data = util.drop(self._data, n);    return self end\n"
"    function obj:reverse()\n"
"      local r = {}; local d = self._data\n"
"      for i = #d, 1, -1 do r[#r+1] = d[i] end\n"
"      self._data = r; return self\n"
"    end\n"
"    function obj:each(fn)\n"
"      for i,v in ipairs(self._data) do fn(v,i) end\n"
"      return self\n"
"    end\n"
"    function obj:value()  return self._data end\n"
"    function obj:count()  return #self._data end\n"
"    function obj:sum()    return util.sum(self._data) end\n"
"    function obj:min()    return util.min(self._data) end\n"
"    function obj:max()    return util.max(self._data) end\n"
"    function obj:mean()   return util.mean(self._data) end\n"
"    function obj:first()  return self._data[1] end\n"
"    function obj:last()   return self._data[#self._data] end\n"
"    return obj\n"
"  end\n"
"\n"
"end\n"

/* ── Extensoes string — tipo Python: isnumeric, isalpha, isspace, etc. ── */
"function string.isnumeric(s)\n"
"  return s ~= '' and s:match('^[%d%.%-]+$') ~= nil and tonumber(s) ~= nil\n"
"end\n"
"function string.isinteger(s)\n"
"  return s ~= '' and s:match('^%-?%d+$') ~= nil\n"
"end\n"
"function string.isalpha(s)\n"
"  return s ~= '' and s:match('^%a+$') ~= nil\n"
"end\n"
"function string.isalnum(s)\n"
"  return s ~= '' and s:match('^%w+$') ~= nil\n"
"end\n"
"function string.isspace(s)\n"
"  return s ~= '' and s:match('^%s+$') ~= nil\n"
"end\n"
"function string.islower(s)\n"
"  return s ~= '' and s == s:lower() and s:match('%a') ~= nil\n"
"end\n"
"function string.isupper(s)\n"
"  return s ~= '' and s == s:upper() and s:match('%a') ~= nil\n"
"end\n"
"function string.zfill(s, n)\n"
"  s = tostring(s)\n"
"  local neg = s:sub(1,1) == '-'\n"
"  if neg then s = s:sub(2) end\n"
"  local pad = math.max(0, n - #s - (neg and 1 or 0))\n"
"  return (neg and '-' or '') .. string.rep('0', pad) .. s\n"
"end\n"
"function string.swapcase(s)\n"
"  return (s:gsub('%a', function(c)\n"
"    return c == c:upper() and c:lower() or c:upper()\n"
"  end))\n"
"end\n"
"function string.title(s)\n"
"  return (s:gsub('(%a)([%w_]*)', function(first, rest)\n"
"    return first:upper() .. rest:lower()\n"
"  end))\n"
"end\n"
"function string.capitalize(s)\n"
"  if #s == 0 then return s end\n"
"  return s:sub(1,1):upper() .. s:sub(2):lower()\n"
"end\n"
"function string.removeprefix(s, prefix)\n"
"  if s:sub(1, #prefix) == prefix then return s:sub(#prefix + 1) end\n"
"  return s\n"
"end\n"
"function string.removesuffix(s, suffix)\n"
"  if suffix ~= '' and s:sub(-#suffix) == suffix then return s:sub(1, -#suffix - 1) end\n"
"  return s\n"
"end\n"
"function string.ljust(s, n, ch)\n"
"  return string.rpad(s, n, ch)\n"
"end\n"
"function string.rjust(s, n, ch)\n"
"  return string.lpad(s, n, ch)\n"
"end\n"
"function string.partition(s, sep)\n"
"  local i = s:find(sep, 1, true)\n"
"  if not i then return s, '', '' end\n"
"  return s:sub(1, i-1), sep, s:sub(i + #sep)\n"
"end\n"
"function string.rpartition(s, sep)\n"
"  local last = nil\n"
"  local i = 1\n"
"  while true do\n"
"    local j = s:find(sep, i, true)\n"
"    if not j then break end\n"
"    last = j; i = j + 1\n"
"  end\n"
"  if not last then return '', '', s end\n"
"  return s:sub(1, last-1), sep, s:sub(last + #sep)\n"
"end\n"
"function string.expandtabs(s, tabsize)\n"
"  tabsize = tabsize or 8\n"
"  return (s:gsub('\\t', string.rep(' ', tabsize)))\n"
"end\n"
"function string.encode_url(s)\n"
"  return (s:gsub('[^%w%-%.%_%~]', function(c)\n"
"    return string.format('%%%02X', string.byte(c))\n"
"  end))\n"
"end\n"
"function string.decode_url(s)\n"
"  return (s:gsub('%%(%x%x)', function(h)\n"
"    return string.char(tonumber(h, 16))\n"
"  end):gsub('%+', ' '))\n"
"end\n"

/* ── util — helpers adicionais de alta ordem ─────────────────────────── */
"function util.pipe(...)\n"
"  local fns = {...}\n"
"  return function(v)\n"
"    for _,fn in ipairs(fns) do v = fn(v) end\n"
"    return v\n"
"  end\n"
"end\n"
"function util.compose(...)\n"
"  local fns = {...}\n"
"  return function(v)\n"
"    for i = #fns, 1, -1 do v = fns[i](v) end\n"
"    return v\n"
"  end\n"
"end\n"
"function util.identity(v) return v end\n"
"function util.noop() end\n"
"function util.always(v) return function() return v end end\n"
"function util.flip(fn)\n"
"  return function(a, b, ...) return fn(b, a, ...) end\n"
"end\n"
"function util.tap(v, fn)\n"
"  fn(v); return v\n"
"end\n"
"function util.default(v, d)\n"
"  if v == nil then return d end; return v\n"
"end\n"
"function util.truthy(v) return v ~= nil and v ~= false end\n"
"function util.falsy(v)  return v == nil or v == false end\n"
"\n"
"-- util.tally(t) -> contagem de frequencia de cada valor\n"
"function util.tally(t)\n"
"  local r = {}\n"
"  for _,v in ipairs(t) do\n"
"    local k = tostring(v)\n"
"    r[k] = (r[k] or 0) + 1\n"
"  end\n"
"  return r\n"
"end\n"
"\n"
"-- util.flat_map(t, fn) -> map + flatten de nivel 1 (como Python itertools.chain.from_iterable)\n"
"function util.flat_map(t, fn)\n"
"  local r = {}\n"
"  for _,v in ipairs(t) do\n"
"    local sub = fn(v)\n"
"    if type(sub) == 'table' then\n"
"      for _,sv in ipairs(sub) do r[#r+1] = sv end\n"
"    else\n"
"      r[#r+1] = sub\n"
"    end\n"
"  end\n"
"  return r\n"
"end\n"
"\n"
"-- util.interleave(a, b) -> mescla dois arrays alternando elementos\n"
"function util.interleave(a, b)\n"
"  local r = {}; local n = math.min(#a, #b)\n"
"  for i = 1, n do r[#r+1] = a[i]; r[#r+1] = b[i] end\n"
"  for i = n+1, #a do r[#r+1] = a[i] end\n"
"  for i = n+1, #b do r[#r+1] = b[i] end\n"
"  return r\n"
"end\n"
"\n"
"-- util.first(t, fn) -> primeiro elemento que satisfaz fn (ou primeiro elemento)\n"
"function util.first(t, fn)\n"
"  if not fn then return t[1] end\n"
"  for _,v in ipairs(t) do if fn(v) then return v end end\n"
"  return nil\n"
"end\n"
"\n"
"-- util.last(t, fn) -> ultimo elemento que satisfaz fn (ou ultimo)\n"
"function util.last(t, fn)\n"
"  if not fn then return t[#t] end\n"
"  local found = nil\n"
"  for _,v in ipairs(t) do if fn(v) then found = v end end\n"
"  return found\n"
"end\n"
"\n"
"-- util.index_of(t, val) -> posicao do valor (ou nil)\n"
"function util.index_of(t, val)\n"
"  for i,v in ipairs(t) do if v == val then return i end end\n"
"  return nil\n"
"end\n"
"\n"
"-- util.without(t, ...) -> tabela sem os valores listados\n"
"function util.without(t, ...)\n"
"  local skip = {}; for _,v in ipairs({...}) do skip[v] = true end\n"
"  return util.filter(t, function(v) return not skip[v] end)\n"
"end\n"
"\n"
"-- util.difference(a, b) -> elementos de a que nao estao em b\n"
"function util.difference(a, b)\n"
"  local set = {}; for _,v in ipairs(b) do set[v] = true end\n"
"  return util.filter(a, function(v) return not set[v] end)\n"
"end\n"
"\n"
"-- util.intersection(a, b) -> elementos presentes em ambos\n"
"function util.intersection(a, b)\n"
"  local set = {}; for _,v in ipairs(b) do set[v] = true end\n"
"  return util.filter(a, function(v) return set[v] ~= nil end)\n"
"end\n"
"\n"
"-- util.union(a, b) -> todos os elementos unicos de a e b\n"
"function util.union(a, b)\n"
"  local seen = {}; local r = {}\n"
"  for _,v in ipairs(a) do\n"
"    if not seen[v] then seen[v]=true; r[#r+1]=v end\n"
"  end\n"
"  for _,v in ipairs(b) do\n"
"    if not seen[v] then seen[v]=true; r[#r+1]=v end\n"
"  end\n"
"  return r\n"
"end\n"
"\n"
"-- util.rotate(t, n) -> rotaciona tabela n posicoes para a direita (negativo = esquerda)\n"
"function util.rotate(t, n)\n"
"  local len = #t; if len == 0 then return {} end\n"
"  n = ((n % len) + len) % len\n"
"  if n == 0 then return table.copy(t) end\n"
"  local r = {}\n"
"  for i = len - n + 1, len    do r[#r+1] = t[i] end\n"
"  for i = 1,           len - n do r[#r+1] = t[i] end\n"
"  return r\n"
"end\n"
"\n"
"-- util.transpose(matrix) -> transpoe matrix de tabelas\n"
"function util.transpose(m)\n"
"  if #m == 0 then return {} end\n"
"  local r = {}\n"
"  for j = 1, #m[1] do\n"
"    r[j] = {}\n"
"    for i = 1, #m do r[j][i] = m[i][j] end\n"
"  end\n"
"  return r\n"
"end\n"
"\n"
"-- util.combinations(t, r) -> todas as combinacoes de r elementos\n"
"function util.combinations(t, r)\n"
"  local result = {}; local n = #t\n"
"  if r > n then return result end\n"
"  local indices = {}\n"
"  for i = 1, r do indices[i] = i end\n"
"  while true do\n"
"    local combo = {}\n"
"    for _,i in ipairs(indices) do combo[#combo+1] = t[i] end\n"
"    result[#result+1] = combo\n"
"    local i = r\n"
"    while i >= 1 and indices[i] == i + n - r do i = i - 1 end\n"
"    if i < 1 then break end\n"
"    indices[i] = indices[i] + 1\n"
"    for j = i+1, r do indices[j] = indices[j-1] + 1 end\n"
"  end\n"
"  return result\n"
"end\n"
"\n"
"-- util.permutations(t) -> todas as permutacoes\n"
"function util.permutations(t)\n"
"  local result = {}\n"
"  local function perm(arr, n)\n"
"    if n == 1 then\n"
"      local copy = {}; for _,v in ipairs(arr) do copy[#copy+1] = v end\n"
"      result[#result+1] = copy; return\n"
"    end\n"
"    for i = 1, n do\n"
"      perm(arr, n-1)\n"
"      if n % 2 == 0 then arr[i], arr[n] = arr[n], arr[i]\n"
"      else arr[1], arr[n] = arr[n], arr[1] end\n"
"    end\n"
"  end\n"
"  local copy = {}; for _,v in ipairs(t) do copy[#copy+1] = v end\n"
"  perm(copy, #copy)\n"
"  return result\n"
"end\n"

/* ── util.help() atualizado — inclui stats, iter, chain ─────────────── */
"do\n"
"  local _orig_util_help = util.help\n"
"  function util.help(section)\n"
"    local E=string.char(27); local R=E..'[0m'; local B=E..'[1m'\n"
"    local G=E..'[1;32m'; local C=E..'[1;36m'; local D=E..'[2m'\n"
"    local function h(t) print(C..'  -- '..t..R) end\n"
"    local function s(f,d) print('  '..G..f..R..'  '..D..d..R) end\n"
"    if section == 'stats' then\n"
"      print(C..'  -- util.* estatisticas'..R)\n"
"      s('util.mean(t)',          '-> media aritmetica')\n"
"      s('util.median(t)',        '-> mediana')\n"
"      s('util.mode(t)',          '-> valor mais frequente')\n"
"      s('util.variance(t)',      '-> variancia populacional')\n"
"      s('util.stdev(t)',         '-> desvio padrao populacional')\n"
"      s('util.stdev_sample(t)',  '-> desvio padrao amostral (n-1)')\n"
"      s('util.percentile(t,p)',  '-> percentil p (0-100)')\n"
"      s('util.normalize(t)',     '-> normaliza entre 0 e 1')\n"
"      s('util.clamp(v,lo,hi)',   '-> limita v ao intervalo [lo,hi]')\n"
"      s('util.round(n,dec)',     '-> arredonda para dec casas decimais')\n"
"      return\n"
"    elseif section == 'iter' then\n"
"      print(C..'  -- util.* iteracao e generators'..R)\n"
"      s('util.iter(t)',            '-> iterador lazy sobre tabela')\n"
"      s('util.generator(fn)',      '-> gerador via coroutine (yield)')\n"
"      s('util.take(src,n)',        '-> primeiros n valores')\n"
"      s('util.drop(t,n)',          '-> sem os primeiros n')\n"
"      s('util.step(t,n)',          '-> um a cada n elementos')\n"
"      s('util.chain(t)',           '-> pipeline encadeavel .filter.map.sorted.value()')\n"
"      s('util.tally(t)',           '-> {valor->contagem}')\n"
"      s('util.flat_map(t,fn)',     '-> map + flatten nivel 1')\n"
"      s('util.interleave(a,b)',    '-> mescla alternando elementos')\n"
"      s('util.first(t,fn)',        '-> primeiro elemento que satisfaz fn')\n"
"      s('util.last(t,fn)',         '-> ultimo elemento que satisfaz fn')\n"
"      s('util.index_of(t,val)',    '-> posicao do valor')\n"
"      s('util.without(t,...)',     '-> sem os valores listados')\n"
"      s('util.difference(a,b)',    '-> elementos de a que nao estao em b')\n"
"      s('util.intersection(a,b)',  '-> elementos presentes em ambos')\n"
"      s('util.union(a,b)',         '-> uniao de dois arrays (unicos)')\n"
"      s('util.rotate(t,n)',        '-> rotaciona n posicoes')\n"
"      s('util.transpose(m)',       '-> transpoe matrix')\n"
"      s('util.combinations(t,r)',  '-> todas combinacoes de r elementos')\n"
"      s('util.permutations(t)',    '-> todas as permutacoes')\n"
"      return\n"
"    elseif section == 'fn' then\n"
"      print(C..'  -- util.* funcoes de alta ordem extras'..R)\n"
"      s('util.pipe(fn,...)',       '-> composicao esquerda-direita')\n"
"      s('util.compose(fn,...)',    '-> composicao direita-esquerda')\n"
"      s('util.identity(v)',        '-> retorna v')\n"
"      s('util.always(v)',          '-> funcao que sempre retorna v')\n"
"      s('util.flip(fn)',           '-> inverte ordem dos 2 primeiros args')\n"
"      s('util.tap(v,fn)',          '-> chama fn(v) e retorna v')\n"
"      s('util.default(v,d)',       '-> v se nao nil, senao d')\n"
"      s('util.truthy(v)',          '-> v nao eh nil nem false')\n"
"      s('util.falsy(v)',           '-> v eh nil ou false')\n"
"      return\n"
"    end\n"
"    -- help geral\n"
"    _orig_util_help()\n"
"    print('')\n"
"    print(C..'  -- Secoes extras: util.help(\"stats\") | util.help(\"iter\") | util.help(\"fn\")'..R)\n"
"    print(C..'  -- Modulo de datas: date.help()'..R)\n"
"  end\n"
"end\n"

/* -- Injeção de metodos em string via __index -------------------------- */
/* Permite: (\"hello world\"):split(\" \")  ->  {\"hello\", \"world\"} */
/* Nota: já funciona automaticamente porque Lua roteia metodos de string
   via getmetatable('').__index = string, então string.split etc. já
   ficam disponíveis como s:split() sem nenhuma metatable extra.       */

    );  /* fim luaL_dostring -- ELLIOT PRELUDE */
    if (_prelude_rc != LUA_OK) {
        fprintf(stderr, "\033[1;31m[ElliotOS] ERRO FATAL prelude: %s\033[0m\n",
            lua_tostring(L, -1));
        lua_pop(L, 1);
        return;
    }
    /* Verifica prelude (falha silenciosa = catastrofica) */
    {
        int _rc = luaL_dostring(L, "return type(util)=='table' and type(json)=='table'");
        if (_rc == LUA_OK) {
            if (!lua_toboolean(L, -1))
                fprintf(stderr, "\033[1;31m[ElliotOS] AVISO: prelude nao carregou (util/json nil)\033[0m\n");
            lua_pop(L, 1);
        } else {
            fprintf(stderr, "\033[1;31m[ElliotOS] ERRO prelude: %s\033[0m\n",
                lua_tostring(L,-1));
            lua_pop(L, 1);
        }
    }
}


/* ============================================================
 * luaopen_net — ponto de entrada registrado no linit.c
 * ============================================================ */
/* back() — função global do REPL */
static int l_back_impl(lua_State *LL) {
    (void)LL;
    printf("  \033[1;33m-> bash\033[0m  (exit para voltar ao ElliotOS)\n");
    fflush(stdout);
    system("bash");
    printf("  \033[1;32m<- ElliotOS\033[0m\n");
    return 0;
}

/* ══════════════════════════════════════════════════════════════════════════
 * MÓDULO ADB — Android Debug Bridge via Wi-Fi (estilo Shizuku)
 * ──────────────────────────────────────────────────────────────────────────
 * Usa o binário `adb` disponível no Termux (pkg install android-tools).
 * Fluxo Shizuku-like:
 *   1. adb.pair("ip:porta", "codigo")   → pareia via Wi-Fi (Android 11+)
 *   2. adb.connect("ip:porta")          → conecta ao dispositivo
 *   3. adb.shell("cmd")                 → executa comandos como ADB shell
 *
 * Todos os comandos rodam com pclose/popen capturando stdout+stderr.
 * Sem root necessário — usa apenas o protocolo ADB over TCP.
 * ══════════════════════════════════════════════════════════════════════════ */

/* Estado interno do módulo ADB */
static char g_adb_device[128] = {0};   /* último dispositivo conectado ip:porta */

/* ── estado rish (ponte Shizuku → Termux) ────────────────────────────── */
/* Diretório canônico dentro do Termux — não polui a memória interna */
#define RISH_TERMUX_DIR_FMT "%s/.local/rish"   /* home/.local/rish/ */

/* Caminhos de busca na memória interna (export padrão do Shizuku). */
static const char *RISH_SEARCH[] = {
    "/sdcard/rish",
    "/sdcard/Download/rish",
    "/storage/emulated/0/rish",
    "/storage/emulated/0/Download/rish",
    NULL
};
static const char *RISH_DEX_SEARCH[] = {
    "/sdcard/rish_shizuku.dex",
    "/sdcard/Download/rish_shizuku.dex",
    "/storage/emulated/0/rish_shizuku.dex",
    "/storage/emulated/0/Download/rish_shizuku.dex",
    NULL
};

static char g_rish_path[512]    = {0};  /* caminho do binário rish */
static char g_rish_dex[512]     = {0};  /* caminho do rish_shizuku.dex */
static int  g_rish_checked      = 0;    /* já tentou detectar? */
static int  g_rish_ok           = 0;    /* rish disponível e funcional? */

/* Salva caminhos do rish em ~/.cache/elliot/rish.conf */
static void rish_conf_save(void) {
    char path[512];
    const char *home = getenv("HOME"); if (!home) home = "/data/data/com.termux/files/home";
    snprintf(path, sizeof(path), "%s/.cache/elliot/rish.conf", home);
    char dir[512]; snprintf(dir, sizeof(dir), "%s", path);
    char *sl = strrchr(dir, '/'); if (sl) { *sl = '\0'; mkdir(dir, 0700); }
    FILE *f = fopen(path, "w");
    if (!f) return;
    fprintf(f, "rish=%s\ndex=%s\n", g_rish_path, g_rish_dex);
    fclose(f);
}

/* Carrega caminhos salvos */
static int rish_conf_load(void) {
    char path[512];
    const char *home = getenv("HOME"); if (!home) home = "/data/data/com.termux/files/home";
    snprintf(path, sizeof(path), "%s/.cache/elliot/rish.conf", home);
    FILE *f = fopen(path, "r");
    if (!f) return 0;
    char line[512];
    while (fgets(line, sizeof(line), f)) {
        int ll = (int)strlen(line);
        while (ll > 0 && (line[ll-1]=='\n'||line[ll-1]=='\r')) line[--ll]='\0';
        if (strncmp(line,"rish=",5)==0 && line[5])
            snprintf(g_rish_path, sizeof(g_rish_path), "%s", line+5);
        else if (strncmp(line,"dex=",4)==0 && line[4])
            snprintf(g_rish_dex, sizeof(g_rish_dex), "%s", line+4);
    }
    fclose(f);
    return (g_rish_path[0] && g_rish_dex[0]) ? 1 : 0;
}

/* Retorna ~/.local/rish/, criando o diretório se necessário. */
static int rish_termux_dir(char *out, size_t outsz) {
    const char *home = getenv("HOME");
    if (!home || !home[0]) home = "/data/data/com.termux/files/home";
    snprintf(out, outsz, RISH_TERMUX_DIR_FMT, home);
    /* cria hierarquia recursivamente */
    char tmp[512]; snprintf(tmp, sizeof(tmp), "%s", out);
    for (char *p = tmp + 1; *p; p++) {
        if (*p == '/') { *p = '\0'; mkdir(tmp, 0755); *p = '/'; }
    }
    mkdir(out, 0755);
    return (out[0] != '\0');
}

/* Copia rish e rish_shizuku.dex para $PREFIX/share/elliot/rish/ quando
 * encontrados na memória interna.
 * Atualiza g_rish_path e g_rish_dex com os novos caminhos.
 *
 * Layout final (ambos em ~/.local/rish/):
 *   ~/.local/rish/rish             chmod 755  — shell script
 *   ~/.local/rish/rish_shizuku.dex chmod 444  — sem write (Android 14+ exige)
 *
 * Execução: bash ~/.local/rish/rish -c 'cmd'
 * Retorna 1 se instalou (ou já estava no lugar certo), 0 em falha. */
static int rish_migrate_to_prefix(void) {
    if (!g_rish_path[0] || !g_rish_dex[0]) return 0;

    char destdir[512];
    if (!rish_termux_dir(destdir, sizeof(destdir))) return 0;

    char dest_rish[640], dest_dex[640];
    snprintf(dest_rish, sizeof(dest_rish), "%s/rish",             destdir);
    snprintf(dest_dex,  sizeof(dest_dex),  "%s/rish_shizuku.dex", destdir);

    /* já no lugar certo — nada a fazer */
    if (strcmp(g_rish_path, dest_rish) == 0 &&
        strcmp(g_rish_dex,  dest_dex)  == 0) return 1;

    printf("\033[1;36m📦 Instalando rish em ~/.local/rish/ ...\033[0m\n");
    fflush(stdout);

    /* helper: copia src → dst */
    #define _CP(SP,DP) do { \
        FILE *_s=fopen((SP),"rb"); \
        if(!_s){printf("\033[1;31m✖ leitura: %s\033[0m\n",(SP));return 0;} \
        FILE *_d=fopen((DP),"wb"); \
        if(!_d){fclose(_s);printf("\033[1;31m✖ escrita: %s\033[0m\n",(DP));return 0;} \
        char _b[65536];size_t _n; \
        while((_n=fread(_b,1,sizeof(_b),_s))>0)fwrite(_b,1,_n,_d); \
        fclose(_s);fclose(_d); \
    } while(0)

    if (strcmp(g_rish_path, dest_rish) != 0) {
        _CP(g_rish_path, dest_rish);
        chmod(dest_rish, 0755);
        if (strncmp(g_rish_path,"/sdcard",7)==0||strncmp(g_rish_path,"/storage",8)==0)
            remove(g_rish_path);
        snprintf(g_rish_path, sizeof(g_rish_path), "%s", dest_rish);
    }

    if (strcmp(g_rish_dex, dest_dex) != 0) {
        _CP(g_rish_dex, dest_dex);
        chmod(dest_dex, 0444);  /* sem write — Android 14+ rejeita .dex gravável */
        if (strncmp(g_rish_dex,"/sdcard",7)==0||strncmp(g_rish_dex,"/storage",8)==0)
            remove(g_rish_dex);
        snprintf(g_rish_dex, sizeof(g_rish_dex), "%s", dest_dex);
    }

    #undef _CP

    printf("\033[1;32m✓ rish instalado em %s\033[0m\n", destdir);
    return 1;
}

/* Detecta rish automaticamente nos caminhos conhecidos */
static int rish_detect(void) {
    if (g_rish_checked) return g_rish_ok;
    g_rish_checked = 1;

    /* tenta carregar da conf salva primeiro */
    if (rish_conf_load()) {
        struct stat st;
        if (stat(g_rish_path, &st)==0 && stat(g_rish_dex, &st)==0) {
            /* se o conf ainda aponta para a memória interna, migra agora */
            if (strncmp(g_rish_path, "/sdcard", 7) == 0 ||
                strncmp(g_rish_path, "/storage", 8) == 0) {
                rish_migrate_to_prefix();
                rish_conf_save();
            }
            g_rish_ok = 1;
            return 1;
        }
        /* arquivos sumiram, limpa */
        g_rish_path[0] = '\0'; g_rish_dex[0] = '\0';
    }

    /* busca primeiro no destino canônico: ~/.local/rish/rish + rish_shizuku.dex */
    {
        char destdir[512], p[640], d[640];
        struct stat st2;
        if (rish_termux_dir(destdir, sizeof(destdir))) {
            snprintf(p, sizeof(p), "%s/rish",             destdir);
            snprintf(d, sizeof(d), "%s/rish_shizuku.dex", destdir);
            if (stat(p, &st2) == 0 && stat(d, &st2) == 0) {
                snprintf(g_rish_path, sizeof(g_rish_path), "%s", p);
                snprintf(g_rish_dex,  sizeof(g_rish_dex),  "%s", d);
                rish_conf_save();
                g_rish_ok = 1;
                return 1;
            }
        }
    }

    /* busca na memória interna (export padrão do Shizuku) */
    struct stat st;
    for (int i = 0; RISH_SEARCH[i]; i++) {
        if (stat(RISH_SEARCH[i], &st) == 0) {
            snprintf(g_rish_path, sizeof(g_rish_path), "%s", RISH_SEARCH[i]);
            break;
        }
    }
    for (int i = 0; RISH_DEX_SEARCH[i]; i++) {
        if (stat(RISH_DEX_SEARCH[i], &st) == 0) {
            snprintf(g_rish_dex, sizeof(g_rish_dex), "%s", RISH_DEX_SEARCH[i]);
            break;
        }
    }
    if (g_rish_path[0] && g_rish_dex[0]) {
        /* migra automaticamente para dentro do $PREFIX e remove do sdcard */
        rish_migrate_to_prefix();
        rish_conf_save();
        g_rish_ok = 1;
    }
    return g_rish_ok;
}

/* Executa um comando via rish (Shizuku shell) e captura saída */
static int rish_run(lua_State *L, const char *cmd) {
    char full[4096];
    /* rish é um shell script — executa via bash com o .dex no mesmo diretório */
    snprintf(full, sizeof(full),
        "RISH_APPLICATION_ID=com.termux bash \"%s\" -c '%s' 2>&1",
        g_rish_path, cmd);
    FILE *fp = popen(full, "r");
    if (!fp) {
        lua_pushnil(L);
        lua_pushstring(L, "rish: falha ao executar (Shizuku está rodando?)");
        return 2;
    }
    char buf[8192]; buf[0] = '\0';
    size_t total = 0; char line[512];
    while (fgets(line, sizeof(line), fp) && total < sizeof(buf)-1) {
        size_t ll = strlen(line);
        if (total+ll < sizeof(buf)-1) { memcpy(buf+total,line,ll); total+=ll; }
    }
    buf[total] = '\0';
    int rc = pclose(fp);
    while (total > 0 && (buf[total-1]=='\n'||buf[total-1]=='\r')) buf[--total]='\0';
    lua_pushstring(L, buf);
    lua_pushboolean(L, rc == 0);
    return 2;
}

/* ── persistência de sessão ───────────────────────────────────────────── */
static void adb_session_path(char *out, size_t outsz) {
    const char *home = getenv("HOME");
    if (!home) home = "/tmp";
    snprintf(out, outsz, "%s/.cache/elliot/adb_session", home);
}

static void adb_session_save(void) {
    char path[512]; adb_session_path(path, sizeof(path));
    char dir[512]; snprintf(dir, sizeof(dir), "%s", path);
    char *sl = strrchr(dir, '/'); if (sl) { *sl = '\0'; mkdir(dir, 0700); }
    if (g_adb_device[0]) {
        FILE *f = fopen(path, "w");
        if (f) { fprintf(f, "%s\n", g_adb_device); fclose(f); }
    } else {
        remove(path);
    }
}

static void adb_session_restore(void) {
    char path[512]; adb_session_path(path, sizeof(path));
    FILE *f = fopen(path, "r");
    if (!f) return;
    char saved[128] = {0};
    if (!fgets(saved, sizeof(saved), f)) { fclose(f); return; }
    fclose(f);
    int sl = (int)strlen(saved);
    while (sl > 0 && (saved[sl-1]=='\n'||saved[sl-1]=='\r')) saved[--sl]='\0';
    if (!saved[0]) return;
    if (system("command -v adb >/dev/null 2>&1") != 0) return;
    char cmd[256];
    snprintf(cmd, sizeof(cmd), "adb connect %s >/dev/null 2>&1", saved);
    int rc = system(cmd);
    if (rc == 0) {
        snprintf(g_adb_device, sizeof(g_adb_device), "%s", saved);
        printf("\033[0;90m[adb] sessao restaurada \xe2\x86\x92 %s\033[0m\n", g_adb_device);
    }
}

/* ── helper: roda adb e captura saída ─────────────────────────────────── */
static int adb_run(lua_State *L, const char *cmd) {
    /* Monta: adb [-s device] <cmd> 2>&1 */
    char full[2048];
    if (g_adb_device[0])
        snprintf(full, sizeof(full), "adb -s %s %s 2>&1", g_adb_device, cmd);
    else
        snprintf(full, sizeof(full), "adb %s 2>&1", cmd);

    FILE *fp = popen(full, "r");
    if (!fp) {
        lua_pushnil(L);
        lua_pushstring(L, "adb: falha ao executar comando (popen)");
        return 2;
    }
    char buf[8192]; buf[0] = '\0';
    size_t total = 0;
    char line[512];
    while (fgets(line, sizeof(line), fp) && total < sizeof(buf)-1) {
        size_t ll = strlen(line);
        if (total + ll < sizeof(buf)-1) {
            memcpy(buf+total, line, ll);
            total += ll;
        }
    }
    buf[total] = '\0';
    int rc = pclose(fp);
    /* Remove trailing newline */
    while (total > 0 && (buf[total-1]=='\n'||buf[total-1]=='\r')) buf[--total]='\0';
    lua_pushstring(L, buf);
    lua_pushboolean(L, rc == 0);
    return 2;
}

/* ── helper: verifica backend disponível (rish ou adb) ───────────────── */
/* Retorna: 0=ok  1=erro (empilhou nil+msg no stack Lua) */
static int adb_check(lua_State *L) {
    /* rish tem prioridade — não precisa de adb nem de pareamento */
    if (rish_detect()) return 0;
    /* fallback: adb clássico */
    if (system("command -v adb >/dev/null 2>&1") == 0) return 0;
    lua_pushnil(L);
    lua_pushstring(L,
        "\033[1;31m✖ Nenhum backend disponível.\033[0m\n\n"
        "  \033[1;33mOpção 1 — Shizuku + rish (recomendado, sem cabo):\033[0m\n"
        "    1. Abra o Shizuku e inicie-o\n"
        "    2. Shizuku → \"Usar em apps de terminal\" → Exportar arquivos\n"
        "    3. Salve rish e rish_shizuku.dex em /sdcard/\n"
        "    4. adb.setup()   ← detecta e configura automaticamente\n\n"
        "  \033[1;33mOpção 2 — ADB clássico:\033[0m\n"
        "    pkg install android-tools\n");
    return 1;
}

/* adb.pair(ip_porta, codigo)
 * Pareia com o dispositivo Android via Wi-Fi (Android 11+).
 * ip_porta: ex. "192.168.1.10:37291"  (porta de pareamento, não a 5555)
 * codigo:   código de 6 dígitos exibido na tela do telefone */
/* ── helper: lê resposta do termux-dialog (JSON {"text":"..."}) ─────── */
static int adb_dialog_read(const char *cmd, char *out, size_t outsz) {
    FILE *fp = popen(cmd, "r");
    if (!fp) return 0;
    char buf[512] = {0}; size_t tot = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp) && tot < sizeof(buf)-1) {
        size_t ll = strlen(line);
        if (tot+ll < sizeof(buf)-1) { memcpy(buf+tot,line,ll); tot+=ll; }
    }
    pclose(fp);
    buf[tot] = '\0';
    /* parse {"text":"valor"} manualmente — sem deps JSON */
    const char *key = "\"text\":\"";
    char *p = strstr(buf, key);
    if (!p) return 0;
    p += strlen(key);
    char *end = strchr(p, '"');
    if (!end) return 0;
    size_t len = (size_t)(end - p);
    if (len >= outsz) len = outsz - 1;
    memcpy(out, p, len); out[len] = '\0';
    return len > 0 ? 1 : 0;
}

/* adb.pair([ip_porta, codigo])
 *
 * SEM argumentos (recomendado):
 *   Abre dois popups nativos do Android via termux-dialog — um pedindo
 *   IP:porta e outro pedindo o código — em cima da tela de pareamento,
 *   sem precisar sair dela. Requer Termux:API instalado.
 *
 * COM argumentos (fallback):
 *   adb.pair("192.168.1.10:37291", "123456")
 */
static int l_adb_pair(lua_State *L) {
    if (adb_check(L)) return 2;

    char addr[128] = {0};
    char code[32]  = {0};

    int has_args = (lua_gettop(L) >= 2 &&
                    lua_type(L,1) == LUA_TSTRING &&
                    lua_type(L,2) == LUA_TSTRING);

    if (has_args) {
        /* modo legado: argumentos diretos */
        snprintf(addr, sizeof(addr), "%s", lua_tostring(L,1));
        snprintf(code, sizeof(code), "%s", lua_tostring(L,2));
    } else {
        /* modo interativo: termux-dialog em cima de qualquer app */
        if (system("command -v termux-dialog >/dev/null 2>&1") != 0) {
            lua_pushnil(L);
            lua_pushstring(L,
                "\033[1;33m⚠ termux-dialog não encontrado.\033[0m\n"
                "  Instale: pkg install termux-api\n"
                "  Ou use:  adb.pair(\"ip:porta\", \"codigo\")");
            return 2;
        }

        printf("\033[1;36m📱 Popups de pareamento serão abertos sobre o app de configurações.\033[0m\n");
        printf("\033[0;90m   Vá para: Configurações → Opções do dev → Depuração sem fio\033[0m\n");
        printf("\033[0;90m   Toque em \"Parear dispositivo\" e aguarde os popups.\033[0m\n\n");
        fflush(stdout);

        /* popup 1 — IP:porta */
        if (!adb_dialog_read(
                "termux-dialog text"
                " -t \"ADB — Pareamento Wi-Fi\""
                " -i \"IP:porta (ex: 192.168.1.10:37291)\"",
                addr, sizeof(addr))) {
            lua_pushnil(L);
            lua_pushstring(L, "Pareamento cancelado pelo usuário.");
            return 2;
        }

        /* popup 2 — código de pareamento */
        if (!adb_dialog_read(
                "termux-dialog text"
                " -t \"ADB — Código de Pareamento\""
                " -i \"Código de 6 dígitos da tela\"",
                code, sizeof(code))) {
            lua_pushnil(L);
            lua_pushstring(L, "Pareamento cancelado pelo usuário.");
            return 2;
        }
    }

    if (!addr[0] || !code[0]) {
        lua_pushnil(L);
        lua_pushstring(L, "IP:porta ou código vazios.");
        return 2;
    }

    char cmd[256];
    snprintf(cmd, sizeof(cmd), "pair %s %s", addr, code);
    printf("\033[1;36m🔗 Pareando com %s...\033[0m\n", addr);
    fflush(stdout);

    int n = adb_run(L, cmd);
    const char *out = lua_tostring(L, -2);
    if (out && strstr(out, "Successfully")) {
        char host[64]; snprintf(host, sizeof(host), "%s", addr);
        char *colon = strchr(host, ':'); if (colon) *colon = '\0';
        snprintf(g_adb_device, sizeof(g_adb_device), "%s:5555", host);
        adb_session_save();
        printf("\033[1;32m✓ Pareado! Conectando...\033[0m\n");
        /* conecta automaticamente após parear */
        char conn[256];
        snprintf(conn, sizeof(conn), "connect %s:5555", host);
        lua_pop(L, n);
        g_adb_device[0] = '\0';
        n = adb_run(L, conn);
        const char *cout = lua_tostring(L, -2);
        if (cout && (strstr(cout,"connected")||strstr(cout,"already"))) {
            snprintf(g_adb_device, sizeof(g_adb_device), "%s:5555", host);
            adb_session_save();
            printf("\033[1;32m✓ Conectado a %s:5555 — sessão salva!\033[0m\n", host);
        }
    } else {
        printf("\033[1;31m✖ Falha no pareamento. Verifique o código e tente novamente.\033[0m\n");
    }
    return n;
}

/* adb.connect(ip_porta)
 * Conecta ao dispositivo. ip_porta: "192.168.1.10:5555" */
static int l_adb_connect(lua_State *L) {
    if (adb_check(L)) return 2;
    const char *addr = luaL_checkstring(L, 1);
    char cmd[256];
    snprintf(cmd, sizeof(cmd), "connect %s", addr);
    printf("\033[1;36m🔌 Conectando a %s...\033[0m\n", addr);
    fflush(stdout);
    /* Temporariamente limpa device para que adb_run não use -s */
    char prev[128]; memcpy(prev, g_adb_device, sizeof(prev));
    g_adb_device[0] = '\0';
    int n = adb_run(L, cmd);
    const char *out = lua_tostring(L, -2);
    if (out && (strstr(out, "connected") || strstr(out, "already"))) {
        snprintf(g_adb_device, sizeof(g_adb_device), "%s", addr);
        adb_session_save();
        printf("\033[1;32m✓ Conectado a %s\033[0m\n", addr);
    } else {
        memcpy(g_adb_device, prev, sizeof(g_adb_device));
    }
    return n;
}

/* adb.disconnect([ip_porta])
 * Desconecta do dispositivo atual ou do endereço especificado. */
static int l_adb_disconnect(lua_State *L) {
    if (adb_check(L)) return 2;
    const char *addr = lua_tostring(L, 1); /* opcional */
    char cmd[256];
    if (addr && addr[0])
        snprintf(cmd, sizeof(cmd), "disconnect %s", addr);
    else
        snprintf(cmd, sizeof(cmd), "disconnect");
    g_adb_device[0] = '\0';
    adb_session_save();
    return adb_run(L, cmd);
}

/* adb.devices()
 * Lista todos os dispositivos conectados. */
static int l_adb_devices(lua_State *L) {
    if (adb_check(L)) return 2;
    return adb_run(L, "devices -l");
}

/* adb.shell(cmd)
 * Executa um comando shell com privilégios ADB.
 * Usa rish (Shizuku) se disponível — senão cai no adb clássico. */
/* helper: executa cmd via fork+pipe e imprime saida ao vivo.
 * Retorna (saida_completa, ok) para o Lua — e ja exibe em tempo real. */
static int adb_shell_live(lua_State *L, const char *scmd) {
    int pfd[2];
    if (pipe(pfd) != 0) {
        lua_pushnil(L);
        lua_pushstring(L, "pipe() falhou");
        return 2;
    }
    pid_t pid = fork();
    if (pid == 0) {
        close(pfd[0]);
        dup2(pfd[1], STDOUT_FILENO);
        dup2(pfd[1], STDERR_FILENO);
        close(pfd[1]);
        execl("/system/bin/sh", "sh", "-c", scmd, (char*)NULL);
        execl("/bin/sh",        "sh", "-c", scmd, (char*)NULL);
        _exit(127);
    } else if (pid < 0) {
        close(pfd[0]); close(pfd[1]);
        lua_pushnil(L);
        lua_pushstring(L, "fork() falhou");
        return 2;
    }
    close(pfd[1]);
    char   acc[8192]; size_t atot = 0;
    char   buf[256];  ssize_t nr;
    while ((nr = read(pfd[0], buf, sizeof(buf))) > 0) {
        write(STDOUT_FILENO, buf, (size_t)nr);
        if (atot + (size_t)nr < sizeof(acc)-1) {
            memcpy(acc+atot, buf, (size_t)nr);
            atot += (size_t)nr;
        }
    }
    acc[atot] = 0;
    while (atot > 0 && (acc[atot-1] == 10 || acc[atot-1] == 13)) acc[--atot] = 0;
    close(pfd[0]);
    fflush(stdout);
    int wst; waitpid(pid, &wst, 0);
    int ok = (WIFEXITED(wst) && WEXITSTATUS(wst) == 0);
    lua_pushstring(L, acc);
    lua_pushboolean(L, ok);
    return 2;
}
static int l_adb_shell(lua_State *L) {
    if (adb_check(L)) return 2;
    const char *cmd = luaL_checkstring(L, 1);
    char scmd[4096];
    if (rish_detect()) {
        snprintf(scmd, sizeof(scmd),
            "RISH_APPLICATION_ID=com.termux bash \"%s\" -c '%s'",
            g_rish_path, cmd);
    } else if (g_adb_device[0]) {
        snprintf(scmd, sizeof(scmd), "adb -s %s shell %s", g_adb_device, cmd);
    } else {
        snprintf(scmd, sizeof(scmd), "adb shell %s", cmd);
    }
    return adb_shell_live(L, scmd);
}

/* adb.push(local, remoto)
 * Envia arquivo para o dispositivo. */
static int l_adb_push(lua_State *L) {
    if (adb_check(L)) return 2;
    const char *src  = luaL_checkstring(L, 1);
    const char *dst  = luaL_checkstring(L, 2);
    char cmd[1024];
    snprintf(cmd, sizeof(cmd), "push \"%s\" \"%s\"", src, dst);
    printf("\033[1;36m📤 Enviando %s → %s\033[0m\n", src, dst);
    fflush(stdout);
    return adb_run(L, cmd);
}

/* adb.pull(remoto [, local])
 * Baixa arquivo do dispositivo. */
static int l_adb_pull(lua_State *L) {
    if (adb_check(L)) return 2;
    const char *src  = luaL_checkstring(L, 1);
    const char *dst  = luaL_optstring(L, 2, ".");
    char cmd[1024];
    snprintf(cmd, sizeof(cmd), "pull \"%s\" \"%s\"", src, dst);
    printf("\033[1;36m📥 Baixando %s → %s\033[0m\n", src, dst);
    fflush(stdout);
    return adb_run(L, cmd);
}

/* adb.install(apk [, flags])
 * Instala um APK. flags: "-r" reinstalar, "-g" todas as permissões. */
static int l_adb_install(lua_State *L) {
