/* adb.logcat([filtro])
 * Captura as últimas 200 linhas do logcat.
 * filtro: ex. "ActivityManager:I *:S" */
static int l_adb_logcat(lua_State *L) {
    if (adb_check(L)) return 2;
    const char *filter = luaL_optstring(L, 1, "*:V");
