/* adb.reboot([modo])
 * Reinicia o dispositivo. modo: "" normal, "recovery", "bootloader", "sideload" */
static int l_adb_reboot(lua_State *L) {
    if (adb_check(L)) return 2;
    const char *mode = luaL_optstring(L, 1, "");
    char cmd[64];
    if (mode[0]) snprintf(cmd, sizeof(cmd), "reboot %s", mode);
    else         snprintf(cmd, sizeof(cmd), "reboot");
