/* adb.screenshot([destino])
 * Tira screenshot e salva no destino (padrão: ./screen.png). */
static int l_adb_screenshot(lua_State *L) {
    if (adb_check(L)) return 2;
    const char *dst = luaL_optstring(L, 1, "./screen.png");
    char cmd[512];
    /* Captura no device, puxa pro local, apaga do device */
    snprintf(cmd, sizeof(cmd),
        "shell screencap -p /sdcard/_elliot_screen.png");
    adb_run(L, cmd); lua_pop(L, 2);
    snprintf(cmd, sizeof(cmd),
        "pull /sdcard/_elliot_screen.png \"%s\"", dst);
    int n = adb_run(L, cmd);
    /* limpa */
    char rm_cmd[128];
    snprintf(rm_cmd, sizeof(rm_cmd), "shell rm -f /sdcard/_elliot_screen.png");
    adb_run(L, rm_cmd); lua_pop(L, 2);
    printf("\033[1;32m✓ Screenshot salvo em %s\033[0m\n", dst);
    return n;
}

/* adb.prop([chave])
