/* adb.forward(local_porta, remoto_porta)
 * Cria túnel TCP: porta local → porta no dispositivo.
 * Útil para acessar serviços rodando no Android pelo PC/Termux.
 *   ex: adb.forward(8080, 8080)  → acessa localhost:8080 no Termux */
static int l_adb_forward(lua_State *L) {
    if (adb_check(L)) return 2;
    int lport = (int)luaL_checknumber(L, 1);
    int rport = (int)luaL_checknumber(L, 2);
    char cmd[128];
    snprintf(cmd, sizeof(cmd), "forward tcp:%d tcp:%d", lport, rport);
    printf("\033[1;36m🔀 Tunelando localhost:%d → device:%d\033[0m\n", lport, rport);
    fflush(stdout);
    return adb_run(L, cmd);
}

