/* adb.screen_size([largura, altura])
 * Sem args: mostra tamanho atual.
 * Com args: muda resolucao. Ex: adb.screen_size(1280,720)
 * Para jogos leves: 960x540, 1280x720
 * Para tela esticada: use proporcao diferente da original */
static int l_adb_screen_size(lua_State *L) {
    if (adb_check(L)) return 2;
    if (lua_gettop(L) >= 2) {
        int w = (int)luaL_checknumber(L, 1);
        int h = (int)luaL_checknumber(L, 2);
        char cmd[128];
        snprintf(cmd, sizeof(cmd), "wm size %dx%d", w, h);
        printf("\033[1;36m📐 Resolucao: %dx%d\033[0m\n", w, h);
        fflush(stdout);
        if (rish_detect()) return rish_run(L, cmd);
        char full[160]; snprintf(full, sizeof(full), "shell %s", cmd);
        return adb_run(L, full);
    } else {
        if (rish_detect()) return rish_run(L, "wm size");
        return adb_run(L, "shell wm size");
    }
}

/* adb.screen_density([dpi])
 * Sem args: mostra DPI atual.
 * Com args: muda DPI. DPI menor = tela "esticada"/zoom.
 * Original geralmente 400-560. Tente 240-320 para jogos fullscreen. */
static int l_adb_screen_density(lua_State *L) {
    if (adb_check(L)) return 2;
    if (lua_gettop(L) >= 1) {
        int dpi = (int)luaL_checknumber(L, 1);
        char cmd[128];
        snprintf(cmd, sizeof(cmd), "wm density %d", dpi);
        printf("\033[1;36m🔍 DPI: %d\033[0m\n", dpi);
        fflush(stdout);
        if (rish_detect()) return rish_run(L, cmd);
        char full[160]; snprintf(full, sizeof(full), "shell %s", cmd);
        return adb_run(L, full);
    } else {
        if (rish_detect()) return rish_run(L, "wm density");
        return adb_run(L, "shell wm density");
    }
}

/* adb.screen_reset()
 * Volta resolucao e DPI para os valores originais do dispositivo. */
static int l_adb_screen_reset(lua_State *L) {
    if (adb_check(L)) return 2;
    printf("\033[1;33m↩ Resetando resolucao e DPI...\033[0m\n");
    fflush(stdout);
    /* reseta os dois */
    if (rish_detect()) {
        rish_run(L, "wm size reset"); lua_pop(L, 2);
        return rish_run(L, "wm density reset");
    }
    adb_run(L, "shell wm size reset");    lua_pop(L, 2);
    return adb_run(L, "shell wm density reset");
}

/* adb.screen_info()
 * Mostra resolucao atual, DPI atual e DPI fisico do dispositivo. */
static int l_adb_screen_info(lua_State *L) {
    if (adb_check(L)) return 2;
    printf("\033[1;36m📱 Info da tela:\033[0m\n");
    fflush(stdout);
    if (rish_detect()) {
        printf("  Resolucao : "); fflush(stdout);
        rish_run(L, "wm size");    lua_pop(L, 2);
        printf("  DPI atual : "); fflush(stdout);
        rish_run(L, "wm density"); lua_pop(L, 2);
        return rish_run(L, "dumpsys display | grep -E 'mBaseDisplayInfo|physicalDensityDpi|appWidth|appHeight' | head -6");
    }
    adb_run(L, "shell wm size");    lua_pop(L, 2);
    adb_run(L, "shell wm density"); lua_pop(L, 2);
    return adb_run(L, "shell dumpsys display | grep -E 'mBaseDisplayInfo|physicalDensityDpi' | head -4");
}

/* adb.overscan(top, right, bottom, left)
 * Ajusta as margens da tela em pixels.
 * Valores negativos expandem a imagem para alem das bordas (fullscreen real).
 * Ex: adb.overscan(0,0,0,0)  — sem margens
 *     adb.overscan(-20,-20,-20,-20) — expande 20px em cada lado */
static int l_adb_overscan(lua_State *L) {
    if (adb_check(L)) return 2;
    int t = (int)luaL_optnumber(L,1,0);
    int r = (int)luaL_optnumber(L,2,0);
    int b = (int)luaL_optnumber(L,3,0);
    int l2= (int)luaL_optnumber(L,4,0);
    char cmd[128];
    snprintf(cmd, sizeof(cmd), "wm overscan %d,%d,%d,%d", t, r, b, l2);
    printf("\033[1;36m🖥 Overscan: top=%d right=%d bottom=%d left=%d\033[0m\n",t,r,b,l2);
    fflush(stdout);
    if (rish_detect()) return rish_run(L, cmd);
    char full[160]; snprintf(full,sizeof(full),"shell %s",cmd);
    return adb_run(L, full);
}

