    char cmd[256];
    snprintf(cmd, sizeof(cmd),
        "cmd game mode %d %s", mode, pkg);
    printf("\033[1;36m🎮 Game mode '%s' para %s\033[0m\n", preset, pkg);
    fflush(stdout);
    if (rish_detect()) return rish_run(L, cmd);
    char full[280]; snprintf(full,sizeof(full),"shell %s",cmd);
    return adb_run(L, full);
}

