static int l_adb_status(lua_State *L) {
    char info[1024];
    int rish_avail = rish_detect();
    if (rish_avail) {
        snprintf(info, sizeof(info),
            "\033[1;32m● Backend : rish (Shizuku)\033[0m\n"
            "  rish     : %s\n"
            "  dex      : %s\n"
            "  Modo     : shell local com privilégios ADB\n",
            g_rish_path, g_rish_dex);
        /* testa com whoami */
        int n = rish_run(L, "whoami");
        const char *who = lua_tostring(L, -2);
        char full[1200];
        snprintf(full, sizeof(full), "%s  Usuário  : %s\n", info, who ? who : "?");
        lua_pop(L, n);
        lua_pushstring(L, full);
        lua_pushboolean(L, 1);
        return 2;
    }
    /* fallback adb */
    if (system("command -v adb >/dev/null 2>&1") != 0) {
        lua_pushstring(L, "\033[1;31m✖ Nenhum backend configurado.\033[0m  Use adb.setup()");
        lua_pushboolean(L, 0);
        return 2;
    }
    snprintf(info, sizeof(info),
        "\033[1;33m● Backend : adb clássico\033[0m\n"
        "  Dispositivo : %s\n",
        g_adb_device[0] ? g_adb_device : "(nenhum — use adb.connect)");
    int n2 = adb_run(L, "version");
    const char *ver = lua_tostring(L, -2);
    char full[1200];
    snprintf(full, sizeof(full), "%s%s", info, ver ? ver : "");
    lua_pop(L, n2);
    lua_pushstring(L, full);
    lua_pushboolean(L, 1);
    return 2;
}

/* adb.setup([rish_path, dex_path])
 * Detecta e configura a ponte Shizuku→Termux via rish.
 * Sem argumentos: busca nos caminhos padrão (/sdcard/, /sdcard/Download/).
 * Com argumentos: usa os caminhos fornecidos diretamente.
 *
 * Setup único (uma vez):
 *   1. Shizuku → "Usar em apps de terminal" → Exportar arquivos → /sdcard/
 *   2. adb.setup()   ← detecta, testa e salva a configuração
 *   3. adb.shell("whoami")  ← pronto! */
static int l_adb_setup(lua_State *L) {
    const char *rish_arg = lua_tostring(L, 1);
    const char *dex_arg  = lua_tostring(L, 2);

    /* reset para forçar re-detecção */
    g_rish_checked = 0; g_rish_ok = 0;
    g_rish_path[0] = '\0'; g_rish_dex[0] = '\0';

    if (rish_arg && rish_arg[0])
        snprintf(g_rish_path, sizeof(g_rish_path), "%s", rish_arg);
    if (dex_arg && dex_arg[0])
        snprintf(g_rish_dex, sizeof(g_rish_dex), "%s", dex_arg);

    printf("\033[1;36m🔍 Procurando rish...\033[0m\n");
    fflush(stdout);

    if (!rish_detect()) {
        printf("\033[1;31m✖ rish não encontrado nos caminhos padrão.\033[0m\n\n");
        printf("  Passos:\n");
        printf("  1. Abra o Shizuku e inicie-o\n");
        printf("  2. Shizuku → \"Usar em apps de terminal\" → Exportar arquivos\n");
        printf("  3. Escolha /sdcard/ como destino\n");
        printf("  4. Execute adb.setup() novamente\n\n");
        printf("  Ou forneça os caminhos manualmente:\n");
        printf("  adb.setup(\"/sdcard/rish\", \"/sdcard/rish_shizuku.dex\")\n\n");
        lua_pushboolean(L, 0);
        lua_pushstring(L, "rish não encontrado");
        return 2;
    }

    /* migra para $PREFIX/share/elliot/rish/ se ainda estiver na memória interna */
    rish_migrate_to_prefix();

    printf("\033[1;32m✓ rish encontrado:\033[0m\n");
    printf("   rish : %s\n", g_rish_path);
    printf("   dex  : %s\n", g_rish_dex);
    printf("\033[1;36m🧪 Testando conexão com Shizuku...\033[0m\n");
    fflush(stdout);

    /* testa com uid */
    int n = rish_run(L, "id");
    const char *out = lua_tostring(L, -2);
    int ok = (out && strlen(out) > 0 && !strstr(out, "error") && !strstr(out, "Error"));

    if (ok) {
        rish_conf_save();
        printf("\033[1;32m✓ Shizuku OK! Usuário: %s\033[0m\n", out);
        printf("\033[0;90m  Configuração salva. Reconecta automaticamente.\033[0m\n\n");
        printf("  Agora use:\n");
        printf("  \033[1;32madb.shell(\"pm list packages\")\033[0m\n");
        printf("  \033[1;32madb.shell(\"dumpsys battery\")\033[0m\n\n");
    } else {
        printf("\033[1;31m✖ Shizuku não respondeu.\033[0m\n");
        printf("   Verifique se o Shizuku está rodando e tem permissão.\n\n");
        g_rish_ok = 0;
    }
    return n;
}

/* adb.help()
 * Exibe referência rápida do módulo. */
/* adb.repl()
 * REPL interativo de shell ADB/Shizuku dentro do ElliotOS.
 *
 * Funcionalidades:
 *   - Usa rish (Shizuku) se configurado, senão adb shell clássico
 *   - Histórico de comandos navegável com ↑↓
 *   - cd emulado: mantém diretório atual entre comandos
 *   - Comandos especiais: clear, cls, help, exit/quit/q
 *   - Pipe e redirecionamentos passados direto ao shell
 *   - Prompt mostra diretório atual e backend ativo
 *   - Saída paginada automaticamente para outputs longos
 */
static int l_adb_repl(lua_State *L) {
    (void)L;
    if (adb_check(L)) return 2;

    int  use_rish  = rish_detect();
    char cwd[512];
    strcpy(cwd, "/");

    #define REPL_HIST_MAX 64
    char hist[REPL_HIST_MAX][512];
    int  hist_count = 0;
    memset(hist, 0, sizeof(hist));

    struct termios orig, raw;
    tcgetattr(STDIN_FILENO, &orig);
    raw = orig;
    raw.c_lflag &= ~(ICANON | ECHO);
    raw.c_cc[VMIN] = 1; raw.c_cc[VTIME] = 0;

    printf("\n\033[1;36m+--------------------------------------------------+\033[0m\n");
    printf("\033[1;36m|  ElliotOS * ADB Shell  %-26s|\033[0m\n",
           use_rish ? "(Shizuku/rish)" : "(adb classico)");
    printf("\033[1;36m+--------------------------------------------------+\033[0m\n");
    printf("\033[0;90m  cima/baixo: historico  |  exit ou q: sair\033[0m\n\n");
    fflush(stdout);

    /* ── executa com saida ao vivo via fork+pipe ── */
    #define REPL_RUN(cmd_str) do { \
        char _full[2048]; \
        char _scmd[4096]; \
        if (use_rish) { \
            if (cwd[0] && strcmp(cwd,"/")!=0) \
                snprintf(_full,sizeof(_full),"cd '%s' && %s",cwd,cmd_str); \
            else \
                snprintf(_full,sizeof(_full),"%s",cmd_str); \
            snprintf(_scmd,sizeof(_scmd), \
                "RISH_APPLICATION_ID=com.termux bash \"%s\" -c '%s'", \
                g_rish_path, _full); \
        } else { \
            if (g_adb_device[0]) \
                snprintf(_scmd,sizeof(_scmd),"adb -s %s shell %s",g_adb_device,cmd_str); \
            else \
                snprintf(_scmd,sizeof(_scmd),"adb shell %s",cmd_str); \
        } \
        int _pfd[2]; pipe(_pfd); \
        pid_t _pid = fork(); \
        if (_pid == 0) { \
            close(_pfd[0]); \
            dup2(_pfd[1], STDOUT_FILENO); \
            dup2(_pfd[1], STDERR_FILENO); \
            close(_pfd[1]); \
            execl("/system/bin/sh","sh","-c",_scmd,(char*)NULL); \
            execl("/bin/sh","sh","-c",_scmd,(char*)NULL); \
            _exit(127); \
        } else if (_pid > 0) { \
            close(_pfd[1]); \
            char _buf[256]; ssize_t _nr; int _got=0; \
            while ((_nr = read(_pfd[0],_buf,sizeof(_buf))) > 0) { \
                write(STDOUT_FILENO,_buf,(size_t)_nr); _got=1; \
            } \
            close(_pfd[0]); \
            int _ws; waitpid(_pid,&_ws,0); \
            if (!_got) printf("\033[0;90m(sem saida)\033[0m\n"); \
            fflush(stdout); \
        } else { \
            FILE *_fp = popen(_scmd,"r"); \
            if (_fp) { char _ln[512]; \
                while(fgets(_ln,sizeof(_ln),_fp)) fputs(_ln,stdout); \
                pclose(_fp); } \
        } \
    } while(0)

    char line[512];
    int  line_len = 0;
    int  h_nav    = -1;

    for (;;) {
        printf("\033[1;32madb\033[0m\033[0;90m:%s\033[0m\033[1;36m%s\033[0m $ ",
               use_rish ? "rish" : "adb",
               cwd[0] ? cwd : "/");
        fflush(stdout);

        line_len = 0; line[0] = '\0'; h_nav = -1;
        memset(line, 0, sizeof(line));

        tcsetattr(STDIN_FILENO, TCSANOW, &raw);

        int done = 0;
        while (!done) {
            unsigned char c = 0;
            if (read(STDIN_FILENO, &c, 1) <= 0) { done = 2; break; }

            if (c == 27) {
                unsigned char c2=0, c3=0;
                read(STDIN_FILENO, &c2, 1);
                read(STDIN_FILENO, &c3, 1);
                if (c2=='[') {
                    if (c3=='A') { /* seta cima — historico anterior */
                        int next = (h_nav < 0) ? hist_count-1 : h_nav-1;
                        if (next < 0) next = 0;
                        if (hist_count > 0 && hist[next % REPL_HIST_MAX][0]) {
                            h_nav = next;
                            for (int i=0;i<line_len;i++) printf("\b \b");
                            strncpy(line, hist[h_nav % REPL_HIST_MAX], sizeof(line)-1);
                            line_len = (int)strlen(line);
                            printf("%s", line); fflush(stdout);
                        }
                    } else if (c3=='B') { /* seta baixo — historico posterior */
                        if (h_nav >= 0) {
                            h_nav++;
                            for (int i=0;i<line_len;i++) printf("\b \b");
                            if (h_nav >= hist_count) {
                                h_nav = -1; line[0]='\0'; line_len=0;
                            } else {
                                strncpy(line, hist[h_nav % REPL_HIST_MAX], sizeof(line)-1);
                                line_len = (int)strlen(line);
                                printf("%s", line); fflush(stdout);
                            }
                        }
                    }
                }
            } else if (c == 127 || c == 8) {
                if (line_len > 0) {
                    line_len--; line[line_len]='\0';
                    printf("\b \b"); fflush(stdout);
                }
            } else if (c == '\r' || c == '\n') {
                printf("\n"); done = 1;
            } else if (c == 3) {
                printf("^C\n"); line[0]='\0'; line_len=0; done=1;
            } else if (c == 4) {
                printf("\n"); done=2;
            } else if (c >= 32 && line_len < (int)sizeof(line)-2) {
                line[line_len++]=(char)c; line[line_len]='\0';
                printf("%c",c); fflush(stdout);
            }
        }
        tcsetattr(STDIN_FILENO, TCSANOW, &orig);
        if (done == 2) break;

        /* trim */
        int ts=0, te=line_len-1;
        while (ts<line_len && (line[ts]==' '||line[ts]=='\t')) ts++;
        while (te>ts && (line[te]==' '||line[te]=='\t')) te--;
        char cmd[512]; int cl=te-ts+1;
        if (cl <= 0) continue;
        memcpy(cmd, line+ts, cl); cmd[cl]='\0';

        /* historico */
        if (hist_count==0 ||
            strcmp(hist[(hist_count-1)%REPL_HIST_MAX],cmd)!=0) {
            strncpy(hist[hist_count%REPL_HIST_MAX],cmd,511);
            hist_count++;
        }

        /* comandos especiais */
        if (strcmp(cmd,"exit")==0||strcmp(cmd,"quit")==0||strcmp(cmd,"q")==0)
            break;

        if (strcmp(cmd,"clear")==0||strcmp(cmd,"cls")==0) {
            printf("\033[2J\033[H"); fflush(stdout); continue;
        }

        if (strcmp(cmd,"help")==0||strcmp(cmd,"?")==0) {
            printf("\033[1;33m  Comandos especiais:\033[0m\n"
                   "    cd <dir>   muda diretorio\n"
                   "    clear      limpa a tela\n"
                   "    exit / q   sai do REPL\n"
                   "    Ctrl+C     cancela linha\n"
                   "    Ctrl+D     sai do REPL\n\n");
            continue;
        }

        /* cd emulado */
        if (strncmp(cmd,"cd",2)==0 && (cmd[2]=='\0'||cmd[2]==' ')) {
            const char *dest = (cmd[2]==' ') ? cmd+3 : "/";
            while (*dest==' ') dest++;
            if (!dest[0]||strcmp(dest,"~")==0) { strcpy(cwd,"/"); continue; }
            char newpath[512];
            if (dest[0]=='/')
                snprintf(newpath,sizeof(newpath),"%s",dest);
            else
                snprintf(newpath,sizeof(newpath),"%s/%s",
                         strcmp(cwd,"/")==0?"":cwd, dest);
            /* verifica existencia */
            char check[640];
            snprintf(check,sizeof(check),"test -d '%s' && echo OK || echo FAIL",newpath);
            char tbuf[16]={0};
            if (use_rish) {
                char rf[2048];
                snprintf(rf,sizeof(rf),
                    "RISH_APPLICATION_ID=com.termux bash \"%s\" -c '%s' 2>&1",
                    g_rish_path, check);
                FILE *fp2=popen(rf,"r");
                if (fp2){fgets(tbuf,sizeof(tbuf),fp2);pclose(fp2);}
            } else {
                char af[2048];
                if (g_adb_device[0])
                    snprintf(af,sizeof(af),"adb -s %s shell \"%s\" 2>&1",g_adb_device,check);
                else
                    snprintf(af,sizeof(af),"adb shell \"%s\" 2>&1",check);
                FILE *fp2=popen(af,"r");
                if (fp2){fgets(tbuf,sizeof(tbuf),fp2);pclose(fp2);}
            }
            if (strncmp(tbuf,"OK",2)==0) {
                snprintf(cwd,sizeof(cwd),"%s",newpath);
                int pl=(int)strlen(cwd);
                while(pl>1&&cwd[pl-1]=='/') cwd[--pl]='\0';
            } else {
                printf("\033[1;31mcd: %s: nao encontrado\033[0m\n",dest);
            }
            continue;
        }

        REPL_RUN(cmd);
    }

    tcsetattr(STDIN_FILENO, TCSANOW, &orig);
    printf("\n\033[0;90m[adb repl] encerrado\033[0m\n\n");
    #undef REPL_RUN
    #undef REPL_HIST_MAX
    return 0;
}
