    /* ── dow — download de mídia (yt-dlp + Cobalt + wget) ── */
    luaL_dostring(L,
        "do\n"
        "local C  = '\x1b[35m[dow]\x1b[0m '\n"
        "local OK = '\x1b[32m[OK]\x1b[0m '\n"
        "local ER = '\x1b[31m[ERRO]\x1b[0m '\n"
        "local WA = '\x1b[33m[dow]\x1b[0m '\n"
        "local HOME   = os.getenv('HOME')   or '/tmp'\n"
        "local PREFIX = os.getenv('PREFIX') or '/data/data/com.termux/files/usr'\n"
        "local CURL   = PREFIX .. '/bin/curl'\n"
        "local WGET   = PREFIX .. '/bin/wget'\n"
        "local DLDIR  = HOME .. '/Downloads'\n"
        "local CACHE  = HOME .. '/.dow_instance'\n"
        "os.execute('mkdir -p ' .. DLDIR)\n"
        "\n"
        "local COBALT_INSTANCES = {\n"
        "  'https://cobalt.ggtyler.dev',\n"
        "  'https://cobalt.drgns.space',\n"
        "  'https://cobalt.api.lostluma.dev',\n"
        "  'https://cobalt.bugbear.gg',\n"
        "  'https://cobalt.darkness.services',\n"
        "  'https://cbl.hz.lv',\n"
        "}\n"
        "local _instance = nil\n"
        "\n"
        "-- checa se arquivo existe\n"
        "local function dep(path)\n"
        "  local f = io.open(path,'r')\n"
        "  if f then f:close(); return true end\n"
        "  return false\n"
        "end\n"
        "\n"
        "-- detecta yt-dlp (com ou sem Python)\n"
        "local function find_ytdlp()\n"
        "  -- binario direto\n"
        "  local bins = {\n"
        "    PREFIX..'/bin/yt-dlp',\n"
        "    HOME..'/.local/bin/yt-dlp',\n"
        "  }\n"
        "  for _,b in ipairs(bins) do\n"
        "    if dep(b) then return b end\n"
        "  end\n"
        "  -- via python3 -m yt_dlp\n"
        "  local py = PREFIX..'/bin/python3'\n"
        "  if dep(py) then\n"
        "    local tmp = os.tmpname()\n"
        "    os.execute(py..' -m yt_dlp --version > '..tmp..' 2>/dev/null')\n"
        "    local f = io.open(tmp,'r')\n"
        "    if f then\n"
        "      local v = f:read('*l'); f:close(); os.remove(tmp)\n"
        "      if v and #v > 0 then return py..' -m yt_dlp' end\n"
        "    end\n"
        "  end\n"
        "  return nil\n"
        "end\n"
        "\n"
        "-- detecta se URL e YouTube\n"
        "local function is_youtube(url)\n"
        "  return url:find('youtu%.be') or url:find('youtube%.com')\n"
        "end\n"
        "\n"
        "-- download via yt-dlp\n"
        "local function ytdlp_down(url, modo)\n"
        "  local bin = find_ytdlp()\n"
        "  if not bin then\n"
        "    return nil, 'yt-dlp nao encontrado. Instale: pkg install python-yt-dlp'\n"
        "  end\n"
        "  local out = DLDIR..'/%(title)s.%(ext)s'\n"
        "  local flags = modo == 'audio'\n"
        "    and '-x --audio-format mp3'\n"
        "    or  '-f bestvideo+bestaudio/best --merge-output-format mp4'\n"
        "  local cmd = string.format(\n"
        "    '%s %s -o \"%s\" \"%s\" 2>&1',\n"
        "    bin, flags, out, url)\n"
        "  local ok = os.execute(cmd)\n"
        "  return ok == 0, DLDIR\n"
        "end\n"
        "\n"
        "-- testa instancia Cobalt\n"
        "local function test_instance(base)\n"
        "  if not dep(CURL) then return false end\n"
        "  local tmp = os.tmpname()\n"
        "  os.execute(string.format(\n"
        "    '\"%s\" -s -o \"%s\" --max-time 4 \"%s/\" 2>/dev/null',\n"
        "    CURL, tmp, base))\n"
        "  local f = io.open(tmp,'r')\n"
        "  if not f then return false end\n"
        "  local body = f:read('*a'); f:close(); os.remove(tmp)\n"
        "  return #body > 0\n"
        "end\n"
        "\n"
        "-- seleciona instancia Cobalt automaticamente\n"
        "local function get_instance()\n"
        "  if _instance then return _instance end\n"
        "  local fc = io.open(CACHE,'r')\n"
        "  if fc then\n"
        "    local cached = fc:read('*l'); fc:close()\n"
        "    if cached and cached ~= '' and test_instance(cached) then\n"
        "      _instance = cached; return _instance\n"
        "    end\n"
        "  end\n"
        "  print(WA..'Selecionando instancia Cobalt...')\n"
        "  for _, base in ipairs(COBALT_INSTANCES) do\n"
        "    if test_instance(base) then\n"
        "      _instance = base\n"
        "      local fw = io.open(CACHE,'w')\n"
        "      if fw then fw:write(base); fw:close() end\n"
        "      print(C..'Instancia: '..base)\n"
        "      return _instance\n"
        "    end\n"
        "  end\n"
        "  return nil\n"
        "end\n"
        "\n"
        "-- download via Cobalt\n"
        "local function cobalt_down(url, modo)\n"
        "  if not dep(CURL) then return nil,'curl nao encontrado' end\n"
        "  local base = get_instance()\n"
        "  if not base then return nil,'nenhuma instancia Cobalt disponivel' end\n"
        "  local tmp = os.tmpname()\n"
        "  local payload = string.format(\n"
        "    '{\"url\":\"%s\",\"downloadMode\":\"%s\"}', url, modo)\n"
        "  local cmd = string.format(\n"
        "    '\"%s\" -s -X POST \"%s/\"'\n"
        "    ..' -H \"Content-Type: application/json\"'\n"
        "    ..' -H \"Accept: application/json\"'\n"
        "    ..' -d \\'%s\\' > \"%s\" 2>/dev/null',\n"
        "    CURL, base, payload, tmp)\n"
        "  os.execute(cmd)\n"
        "  local f = io.open(tmp,'r')\n"
        "  if not f then os.remove(tmp); return nil,'sem resposta da API' end\n"
        "  local body = f:read('*a'); f:close(); os.remove(tmp)\n"
        "  if body == '' then os.remove(CACHE); _instance = nil; return nil,'resposta vazia' end\n"
        "  local err = body:match('\"error\"%s*:%s*{[^}]*\"code\"%s*:%s*\"([^\"]+)\"')\n"
        "  if err then\n"
        "    if err:find('auth') or err:find('jwt') then\n"
        "      os.remove(CACHE); _instance = nil\n"
        "      return nil,'instancia requer auth'\n"
        "    end\n"
        "    return nil,'Cobalt: '..err\n"
        "  end\n"
        "  local status = body:match('\"status\"%s*:%s*\"([^\"]+)\"')\n"
        "  if status == 'tunnel' or status == 'redirect' then\n"
        "    local link = body:match('\"url\"%s*:%s*\"([^\"]+)\"')\n"
        "    if not dep(WGET) then return nil,'wget nao encontrado' end\n"
        "    local nome = modo=='audio' and 'audio_'..os.time()..'.mp3'\n"
        "                               or  'video_'..os.time()..'.mp4'\n"
        "    local dest = DLDIR..'/'..nome\n"
        "    local ok = os.execute(string.format(\n"
        "      '\"%s\" -q --show-progress -O \"%s\" \"%s\"',WGET,dest,link))\n"
        "    return ok==0, dest\n"
        "  end\n"
        "  return nil,'resposta inesperada: '..(status or body:sub(1,80))\n"
        "end\n"
        "\n"
        "dow = {}\n"
        "\n"
        "function dow.video(url)\n"
        "  if is_youtube(url) then\n"
        "    print(C..'YouTube detectado, usando yt-dlp...')\n"
        "    local ok,dest = ytdlp_down(url,'video')\n"
        "    if ok then print(OK..'Salvo em: '..dest)\n"
        "    else print(ER..(dest or 'falhou')) end\n"
        "  else\n"
        "    print(C..'Usando Cobalt API...')\n"
        "    local ok,dest = cobalt_down(url,'auto')\n"
        "    if ok then print(OK..'Salvo em: '..dest)\n"
        "    else print(ER..(dest or 'falhou')) end\n"
        "  end\n"
        "end\n"
        "\n"
        "function dow.audio(url)\n"
        "  if is_youtube(url) then\n"
        "    print(C..'YouTube detectado, usando yt-dlp...')\n"
        "    local ok,dest = ytdlp_down(url,'audio')\n"
        "    if ok then print(OK..'Salvo em: '..dest)\n"
        "    else print(ER..(dest or 'falhou')) end\n"
        "  else\n"
        "    print(C..'Usando Cobalt API...')\n"
        "    local ok,dest = cobalt_down(url,'audio')\n"
        "    if ok then print(OK..'Salvo em: '..dest)\n"
        "    else print(ER..(dest or 'falhou')) end\n"
        "  end\n"
        "end\n"
        "\n"
        "function dow.imagen(url)\n"
        "  print(C..'Baixando imagem...')\n"
        "  if not dep(WGET) then print(ER..'wget nao encontrado'); return end\n"
        "  local ext = url:match('%.(%a+)%?" "?') or 'jpg'\n"
        "  local dest = DLDIR..'/imagem_'..os.time()..'.'..ext\n"
        "  local ok = os.execute(string.format(\n"
        "    '\"%s\" -q --show-progress -O \"%s\" \"%s\"',WGET,dest,url))\n"
        "  if ok==0 then print(OK..'Salvo em: '..dest)\n"
        "  else print(ER..'Falhou. Verifique a URL.') end\n"
        "end\n"
        "\n"
        "function dow.playlist(url)\n"
        "  if is_youtube(url) then\n"
        "    print(C..'Baixando playlist YouTube via yt-dlp...')\n"
        "    local ok,dest = ytdlp_down(url,'video')\n"
        "    if ok then print(OK..'Salvo em: '..dest)\n"
        "    else print(ER..(dest or 'falhou')) end\n"
        "  else\n"
        "    print(ER..'Playlist so suportada para YouTube.')\n"
        "  end\n"
        "end\n"
        "\n"
        "function dow.reset()\n"
        "  os.remove(CACHE); _instance = nil\n"
        "  print(C..'Cache limpo. Nova instancia sera selecionada no proximo uso.')\n"
        "end\n"
        "\n"
        "function dow.info(url)\n"
        "  local ytbin = find_ytdlp()\n"
        "  print(C..'--- info ---')\n"
        "  print('  yt-dlp : '..(ytbin or 'nao encontrado'))\n"
        "  print('  curl   : '..(dep(CURL) and CURL or 'nao encontrado'))\n"
        "  print('  wget   : '..(dep(WGET) and WGET or 'nao encontrado'))\n"
        "  local fc = io.open(CACHE,'r')\n"
        "  if fc then\n"
        "    local inst = fc:read('*l'); fc:close()\n"
        "    print('  cobalt : '..(inst or 'sem cache'))\n"
        "  else\n"
        "    print('  cobalt : sem cache')\n"
        "  end\n"
        "  if url then\n"
        "    print('  youtube: '..tostring(is_youtube(url) ~= nil))\n"
        "  end\n"
        "end\n"
        "\n"
        "function dow.help()\n"
        "  print('\x1b[35m╔════════════════════════════════════════╗\x1b[0m')\n"
        "  print('\x1b[35m║   dow — ElliotOS Media Downloader      ║\x1b[0m')\n"
        "  print('\x1b[35m╚════════════════════════════════════════╝\x1b[0m')\n"
        "  print('  dow.video(url)     Baixa video')\n"
        "  print('  dow.audio(url)     Extrai audio')\n"
        "  print('  dow.imagen(url)    Baixa imagem via URL direta')\n"
        "  print('  dow.playlist(url)  Baixa playlist (YouTube)')\n"
        "  print('  dow.info(url)      Mostra status das ferramentas')\n"
        "  print('  dow.reset()        Troca instancia Cobalt')\n"
        "  print('')\n"
        "  print('  \x1b[33mYouTube\x1b[0m  → yt-dlp  (pkg install python-yt-dlp)')\n"
        "  print('  \x1b[33mOutros  \x1b[0m → Cobalt API + wget')\n"
        "  print('  \x1b[33mImagens \x1b[0m → wget direto')\n"
        "  print('  \x1b[90mSalvo   : ~/Downloads/\x1b[0m')\n"
        "end\n"
        "end\n"
    );

    /* ── back() — cai no bash interativo e volta ao REPL ── */
    lua_pushcfunction(L, l_back_impl);
    lua_setglobal(L, "back");

    /* ── Histórico persistente ── */
    atexit(elliot_history_save);

    /* ── Variáveis indexadas (experimental) ── */
    elliot_ivar_init(L);

    /* ── Restaura sessão ADB da execução anterior ── */
    adb_session_restore();

    /* ── adb.* ── */
    lua_newtable(L);
    lua_pushcfunction(L,l_adb_pair);      lua_setfield(L,-2,"pair");
    lua_pushcfunction(L,l_adb_connect);   lua_setfield(L,-2,"connect");
    lua_pushcfunction(L,l_adb_disconnect);lua_setfield(L,-2,"disconnect");
    lua_pushcfunction(L,l_adb_devices);   lua_setfield(L,-2,"devices");
    lua_pushcfunction(L,l_adb_shell);     lua_setfield(L,-2,"shell");
    lua_pushcfunction(L,l_adb_push);      lua_setfield(L,-2,"push");
    lua_pushcfunction(L,l_adb_pull);      lua_setfield(L,-2,"pull");
    lua_pushcfunction(L,l_adb_install);   lua_setfield(L,-2,"install");
    lua_pushcfunction(L,l_adb_uninstall); lua_setfield(L,-2,"uninstall");
