    lua_pushcfunction(L,l_adb_reboot);    lua_setfield(L,-2,"reboot");
    lua_pushcfunction(L,l_adb_screenshot);lua_setfield(L,-2,"screenshot");
    lua_pushcfunction(L,l_adb_prop);      lua_setfield(L,-2,"prop");
    lua_pushcfunction(L,l_adb_forward);   lua_setfield(L,-2,"forward");
