    for _,o in ipairs({{"-p <porta>","Porta(s)","80"},{"-s <n>","Pacotes/sockets","100"},{"-t <n>","Threads","10"},{"-x <tam>","Payload (B/KB/MB/GB)","1KB"},{"-st <s>","Keep-alive (slow)","15"},{"-ua","UAs aleatorios",""},{"-v","Verbose",""}}) do
