    printf "  \033[1;32m  ms\033[0m              - abre o REPL interativo (MoonStyle Lua)\n"
    printf "  \033[1;32m  ms -a\033[0m           - chat com a CYN (IA nativa)\n"
    printf "  \033[1;32m  ms -h\033[0m           - lista todos os comandos\n"
    printf "  \033[1;32m  ms -f script.lua\033[0m - executa um script\n"
    printf "  \033[1;32m  lpm install <pkg>\033[0m - instala modulo Lua\n"
    printf "\n"
    printf "  \033[0;90mReinicie o terminal para ativar todas as configuracoes.\033[0m\n\n"
}

# ════════════════════════════════════════════════════════════════════════════
# _setup_termux_shortcuts - Configura atalhos de sessão no Termux
# Cria ~/.termux/termux.properties com Ctrl+T/N/P/W para gerenciar sessões
# Funciona apenas no Termux; ignorado silenciosamente em Linux normal
# ════════════════════════════════════════════════════════════════════════════
_setup_termux_shortcuts() {
    # Só faz sentido dentro do Termux
    if [ ! -d "/data/data/com.termux" ]; then
        return 0
    fi

    _section "SESSOES — Atalhos de teclado do Termux"

    local _TERMUX_CFG="$HOME/.termux/termux.properties"
    mkdir -p "$HOME/.termux"

    # ── Migra atalhos antigos (sem Alt) para os novos (com Alt) ───────────
    local _migrated=0

    if [ -f "$_TERMUX_CFG" ]; then
        if grep -qE "^shortcut\.create-session[[:space:]]*=[[:space:]]*ctrl[[:space:]]*\+[[:space:]]*t[[:space:]]*$" "$_TERMUX_CFG"; then
            sed -i 's|^shortcut\.create-session.*|shortcut.create-session = ctrl + alt + t|' "$_TERMUX_CFG"
            _migrated=1
        fi
        if grep -qE "^shortcut\.next-session[[:space:]]*=[[:space:]]*ctrl[[:space:]]*\+[[:space:]]*n[[:space:]]*$" "$_TERMUX_CFG"; then
            sed -i 's|^shortcut\.next-session.*|shortcut.next-session = ctrl + alt + n|' "$_TERMUX_CFG"
            _migrated=1
        fi
        if grep -qE "^shortcut\.previous-session[[:space:]]*=[[:space:]]*ctrl[[:space:]]*\+[[:space:]]*p[[:space:]]*$" "$_TERMUX_CFG"; then
            sed -i 's|^shortcut\.previous-session.*|shortcut.previous-session = ctrl + alt + p|' "$_TERMUX_CFG"
            _migrated=1
        fi
        if grep -qE "^shortcut\.rename-session[[:space:]]*=[[:space:]]*ctrl[[:space:]]*\+[[:space:]]*w[[:space:]]*$" "$_TERMUX_CFG"; then
            sed -i 's|^shortcut\.rename-session.*|shortcut.rename-session = ctrl + alt + w|' "$_TERMUX_CFG"
            _migrated=1
        fi

        if [ "$_migrated" = "1" ]; then
            _ok "Atalhos antigos detectados e migrados para Ctrl+Alt (conflito com ee resolvido)"
        fi
    fi

    # ── Escreve do zero se não existia nenhum atalho ElliotOS ─────────────
    if grep -q "# ElliotOS-session-shortcuts" "$_TERMUX_CFG" 2>/dev/null; then
        [ "$_migrated" = "0" ] && _ok "Atalhos ja gravados em termux.properties — pulando escrita"
    else
        cat >> "$_TERMUX_CFG" << 'SHORTCUTS_EOF'

# ElliotOS-session-shortcuts — gerado pelo instalador ElliotOS v17.0
shortcut.create-session = ctrl + alt + t
shortcut.next-session = ctrl + alt + n
shortcut.previous-session = ctrl + alt + p
shortcut.rename-session = ctrl + alt + w
SHORTCUTS_EOF
        _ok "~/.termux/termux.properties atualizado"
    fi

    # Instruções sempre exibidas, independente de já existir a config
    printf "\n"
    printf "  \033[1;37m SESSOES DO TERMUX - Atalhos de teclado\033[0m\n"
    printf "  \033[0;90m------------------------------------------------------------\033[0m\n"
    printf "\n"
    printf "  \033[0;90m  Tecla        Acao                Como funciona\033[0m\n"
    printf "  \033[0;90m  ---------    ----------------    ----------------------------\033[0m\n"
    printf "  \033[1;36m  Ctrl + Alt + T\033[0m  Nova sessao         Abre uma nova aba limpa\n"
    printf "  \033[1;36m  Ctrl + Alt + N\033[0m  Proxima sessao      Vai para a sessao seguinte\n"
    printf "  \033[1;36m  Ctrl + Alt + P\033[0m  Sessao anterior     Volta para a sessao anterior\n"
    printf "  \033[1;36m  Ctrl + Alt + W\033[0m  Renomear/fechar     Menu — opcao de deletar sessao\n"
    printf "  \033[1;36m  Ctrl + D\033[0m     Fechar sessao       Encerra a sessao atual (nativo)\n"
    printf "\n"
    printf "  \033[0;90m------------------------------------------------------------\033[0m\n"
    printf "  \033[1;33m  REQUISITO:\033[0m teclado fisico (USB/Bluetooth/built-in).\n"
    printf "  \033[0;90m  Teclado virtual do Android nao dispara Ctrl.\033[0m\n"
    printf "\n"
    printf "  \033[0;90m  Sessoes visiveis: deslize da borda esquerda (drawer).\033[0m\n"
    printf "  \033[0;90m  Config em: ~/.termux/termux.properties\033[0m\n"
    printf "  \033[0;33m  Se nao funcionar: rode\033[0m \033[1;37mtermux-reload-settings\033[0m\n"
    printf "  \033[0;90m------------------------------------------------------------\033[0m\n\n"
}

# ════════════════════════════════════════════════════════════════════════════
# _setup_motd — Cria MOTD colorido do ElliotOS no Termux
# Escreve ~/.termux/motd com arte ASCII + info do sistema
# ════════════════════════════════════════════════════════════════════════════
_setup_motd() {
    if [ ! -d "/data/data/com.termux" ]; then
        return 0
    fi

    _section "MOTD — Mensagem de boas-vindas do Termux"

    # O Termux exibe $PREFIX/etc/motd — é esse que precisa ser sobrescrito.
    # ~/.termux/motd NÃO é lido pelo Termux padrão.
    local _MOTD_FILE="${PREFIX:-/data/data/com.termux/files/usr}/etc/motd"
    local _R="\033[0m"
    local _PU="\033[1;35m"  # roxo negrito
    local _GR="\033[0;90m"  # cinza
    local _CY="\033[1;36m"  # ciano negrito
    local _YE="\033[1;33m"  # amarelo negrito
    printf "${_PU}\n" > "$_MOTD_FILE"
    printf "  ███████╗██╗     ██╗     ██╗ ██████╗ ████████╗ ██████╗ ███████╗\n" >> "$_MOTD_FILE"
    printf "  ██╔════╝██║     ██║     ██║██╔═══██╗╚══██╔══╝██╔═══██╗██╔════╝\n" >> "$_MOTD_FILE"
    printf "  █████╗  ██║     ██║     ██║██║   ██║   ██║   ██║   ██║███████╗\n" >> "$_MOTD_FILE"
    printf "  ██╔══╝  ██║     ██║     ██║██║   ██║   ██║   ██║   ██║╚════██║\n" >> "$_MOTD_FILE"
    printf "  ███████╗███████╗███████╗██║╚██████╔╝   ██║   ╚██████╔╝███████║\n" >> "$_MOTD_FILE"
    printf "  ╚══════╝╚══════╝╚══════╝╚═╝ ╚═════╝    ╚═╝    ╚═════╝ ╚══════╝${_R}\n" >> "$_MOTD_FILE"
    printf "${_GR}  ─────────────────────────────────────────────────────────────────${_R}\n" >> "$_MOTD_FILE"
    printf "${_CY}  v17.0${_R} ${_GR}·${_R} ${_PU}CYN${_R} ${_GR}·${_R} Lua + C nativo ${_GR}·${_R} Pentest ${_GR}·${_R} IA sem chave\n" >> "$_MOTD_FILE"
    printf "${_GR}  ─────────────────────────────────────────────────────────────────${_R}\n" >> "$_MOTD_FILE"
    printf "${_YE}  ms${_R} ${_GR}─${_R} MoonStyle Lua    ${_YE}ms -a${_R} ${_GR}─${_R} IA (CYN)    ${_YE}ee${_R} ${_GR}─${_R} Editor nativo\n" >> "$_MOTD_FILE"
    printf "${_YE}  lpm${_R} ${_GR}─${_R} Gerenciador      ${_YE}cxx${_R} ${_GR}─${_R} C/C++ build  ${_YE}luar${_R} ${_GR}─${_R} Lua direto\n" >> "$_MOTD_FILE"
    printf "${_GR}  ─────────────────────────────────────────────────────────────────${_R}\n" >> "$_MOTD_FILE"

    _ok "MOTD instalado em $_MOTD_FILE"
    _warn "Reinicie o Termux para ver o novo MOTD"
}

# ════════════════════════════════════════════════════════════════════════════
# _setup_password — Define senha de acesso ao ElliotOS
# Pede senha na instalação e grava hash SHA256 em ~/.elliotos_auth
# No .bashrc adiciona verificação de senha a cada novo shell
# Ctrl+C é ignorado durante o prompt — o usuário é forçado a digitar
# ════════════════════════════════════════════════════════════════════════════
_setup_password() {
    _section "SENHA — Proteção de acesso ao ElliotOS"

    local _AUTH_FILE="$HOME/.elliotos_auth"
    local _PASS1 _PASS2 _HASH

    printf "\n  \033[1;35m[🔐] Defina uma senha para proteger o ElliotOS\033[0m\n"
    printf "  \033[0;90m  A senha será pedida em todo novo terminal.\033[0m\n"
    printf "  \033[0;90m  Deixe em branco e pressione Enter para usar sem senha.\033[0m\n\n"

    # Bloqueia SIGINT durante todo o processo de definição
    trap '' INT

    # Loop até senhas coincidirem (ou usuário deixar em branco)
    while true; do
        printf "  \033[1;37mNova senha\033[0m \033[0;90m(Enter = sem senha)\033[0m\033[1;37m:\033[0m "
        IFS= read -rs _PASS1; printf "\n"

        # ── Campo vazio: modo sem senha ──────────────────────────────────
        if [ -z "$_PASS1" ]; then
            trap - INT
            printf "\n  \033[1;33m[ℹ] Nenhuma senha definida — terminal ficará sem proteção.\033[0m\n"
            printf "  \033[0;90m  Para adicionar senha depois: rm ~/.elliotos_auth && bash luascript\033[0m\n\n"
            rm -f "$_AUTH_FILE"
            return 0
        fi

        printf "  \033[1;37mConfirme a senha:\033[0m "
        IFS= read -rs _PASS2; printf "\n"

        if [ "$_PASS1" != "$_PASS2" ]; then
            printf "  \033[1;31m[!] Senhas não coincidem. Tente novamente.\033[0m\n\n"
            continue
        fi

        break
    done

    # Restaura SIGINT após definição
    trap - INT

    # Grava hash SHA256 da senha
    _HASH=$(printf '%s' "$_PASS1" | sha256sum | cut -d' ' -f1)
    printf '%s\n' "$_HASH" > "$_AUTH_FILE"
    chmod 600 "$_AUTH_FILE"
    unset _PASS1 _PASS2

    _ok "Senha definida e salva em $_AUTH_FILE"

    # Injeta verificador de senha no .bashrc (somente se ainda não existir)
    if ! grep -qF "elliotos_auth_check" "$HOME/.bashrc" 2>/dev/null; then
        cat >> "$HOME/.bashrc" << 'AUTHEOF'

# ── ElliotOS: verificação de senha ──────────────────────────────────────────
_elliotos_auth_check() {
    local _af="$HOME/.elliotos_auth"
    [ -f "$_af" ] || return 0          # sem arquivo = sem senha
    local _expected _input _hash _attempts=0 _max=5
    _expected=$(cat "$_af" 2>/dev/null)
    [ -z "$_expected" ] && return 0

    # Bloqueia Ctrl+C durante o prompt de senha
    trap '' INT

    while true; do
        printf "\033[1;35m[ElliotOS]\033[0m \033[1;37mSenha: \033[0m"
        IFS= read -rs _input; printf "\n"
        _hash=$(printf '%s' "$_input" | sha256sum | cut -d' ' -f1)
        if [ "$_hash" = "$_expected" ]; then
            trap - INT
            printf "\033[1;32m  ✓ Acesso autorizado\033[0m\n\n"
            return 0
        fi
        _attempts=$((_attempts + 1))
        printf "\033[1;31m  ✗ Senha incorreta"
        if [ "$_attempts" -ge "$_max" ]; then
            printf " — sessão encerrada\033[0m\n"
            trap - INT
            kill -9 $$
        fi
        printf " ($_attempts/$_max)\033[0m\n\n"
    done
}
_elliotos_auth_check
# ────────────────────────────────────────────────────────────────────────────
AUTHEOF
        _ok "Verificador de senha adicionado ao ~/.bashrc"
    else
        _ok "Verificador de senha já presente no ~/.bashrc — pulando"
    fi

    printf "\n  \033[0;90mPara remover a senha: \033[0mrm ~/.elliotos_auth\033[0m\n\n"
}

# ════════════════════════════════════════════════════════════════════════════
# _setup_prompt — Prompt customizado (ElliotOS) permanente no .bashrc
# Idempotente: so injeta se ainda nao existir. Nao da source no .bashrc
# durante a instalacao (evitaria disparar o verificador de senha no meio
# do instalador) — o usuario ativa com "source ~/.bashrc" no final, como
# ja e feito para as outras mudancas do instalador.
# ════════════════════════════════════════════════════════════════════════════
# ════════════════════════════════════════════════════════════════════════════
# _setup_nethunter — instala o script de instalação do NetHunter em ~/.xpm/nethunter/
# Idempotente. Versão 3: multi-arch, sem dependência de termux-distro.sh externo.
# ════════════════════════════════════════════════════════════════════════════
_setup_nethunter() {
    local nh_dir="$HOME/.xpm/nethunter"
    local nh_script="$nh_dir/install-nethunter.sh"
    mkdir -p "$nh_dir"

    # Idempotente: só recria se marcador da v3 não estiver presente
    if [ -f "$nh_script" ] && grep -q 'ElliotOS-NH-v3' "$nh_script" 2>/dev/null; then
        printf "  \033[1;32m✓\033[0m NetHunter installer (multi-arch v3) já presente\n"
        return 0
    fi

    printf "  \033[0;90m→\033[0m Gerando NetHunter installer multi-arch em ~/.xpm/nethunter/...\n"

    cat > "$nh_script" << 'NHEOF'
#!/data/data/com.termux/files/usr/bin/bash
# ElliotOS-NH-v3 — Kali NetHunter rootless installer (multi-arch)
# Suporta: aarch64 (arm64) · armv7 (armhf) · x86_64 (amd64) · i686 (i386)
# Não depende de termux-distro.sh nem scripts externos.

set -euo pipefail

R=$'\033[1;31m' G=$'\033[1;32m' Y=$'\033[1;33m'
B=$'\033[1;36m' W=$'\033[1;37m' D=$'\033[0;90m' N=$'\033[0m'
_ok()   { printf "${G}  ✓ %s${N}\n" "$1"; }
_info() { printf "${B}  → %s${N}\n" "$1"; }
_warn() { printf "${Y}  ! %s${N}\n" "$1"; }
_err()  { printf "${R}  ✗ %s${N}\n" "$1" >&2; exit 1; }
_head() { printf "\n${W}  ══ %s ══${N}\n\n" "$1"; }

PREFIX="${PREFIX:-/data/data/com.termux/files/usr}"
TERMUX_BIN="$PREFIX/bin"
NH_ROOTFS="${HOME}/.xpm/kali/rootfs"

# ── Detecção de arquitetura ───────────────────────────────────────────────
_detect_arch() {
  local m; m=$(uname -m 2>/dev/null || echo "aarch64")
  case "$m" in
    aarch64|arm64)          echo "arm64"  ;;
    armv7*|armv8*|armhf*)  echo "armhf"  ;;
    x86_64|amd64)           echo "amd64"  ;;
    i686|i386)              echo "i386"   ;;
    *)
      printf "${Y}  ! Arquitetura desconhecida: %s — usando arm64${N}\n" "$m" >&2
      echo "arm64"
      ;;
  esac
}

SYS_ARCH=$(_detect_arch)
_ok "Arquitetura: $(uname -m) → NetHunter arch: $SYS_ARCH"

# ── Verifica se já instalado ──────────────────────────────────────────────
if [ -d "$NH_ROOTFS" ] && [ -f "$TERMUX_BIN/nethunter" ]; then
  printf "\n${G}  NetHunter já instalado.${N} Para entrar: ${W}nethunter${N} ou ${W}nh${N}\n\n"
  read -rp "  Reinstalar/atualizar? [s/N] " _resp
  case "${_resp:-N}" in s|S|y|Y) : ;; *) exit 0 ;; esac
  rm -rf "$NH_ROOTFS"
fi

# ── Instala dependências ──────────────────────────────────────────────────
_head "Dependências"
_info "Atualizando pacotes..."
pkg update -y 2>/dev/null || true

_missing=()
# Mapeia cmd:pacote (xz é o binário do xz-utils no Termux)
for _entry in "proot:proot" "wget:wget" "tar:tar" "xz:xz-utils" "curl:curl"; do
  _dep="${_entry%%:*}"
  _pkg="${_entry##*:}"
  if ! command -v "$_dep" >/dev/null 2>&1; then
    _missing+=("$_pkg")
    _warn "$_dep não encontrado"
  else
    _ok "$_dep"
  fi
done

if [ ${#_missing[@]} -gt 0 ]; then
  _info "Instalando: ${_missing[*]}"
  pkg install -y "${_missing[@]}" 2>/dev/null || \
    apt-get install -y "${_missing[@]}" 2>/dev/null || \
    _warn "Alguns pacotes podem não ter sido instalados"
fi

command -v proot >/dev/null 2>&1 || _err "proot não encontrado. Instale: pkg install proot"

# ── Seleciona versão e tipo de instalação ────────────────────────────────
_head "Configuração"

printf "  ${W}Tipo de instalação:${N}\n"
printf "  ${G}1)${N} Nano   — mínimo       ~190 MB  ${D}(só ferramentas base)${N}\n"
printf "  ${G}2)${N} Mini   — essencial    ~130 MB  ${D}[recomendado]${N}\n"
printf "  ${G}3)${N} Full   — completo     >1.5 GB  ${D}(desktop incluído)${N}\n"
printf "\n  Escolha [1/2/3, padrão: 2]: "
read -r _choice
case "${_choice:-2}" in
  1) _TYPE="nano"    ; _ARCHIVE_TYPE="nano"    ;;
  3) _TYPE="full"    ; _ARCHIVE_TYPE="full"    ;;
  *) _TYPE="mini"    ; _ARCHIVE_TYPE="minimal" ;;
esac

# ── URL direta via /current/rootfs/ (sempre atualizado) ──────────────────
_head "Download"
ARCHIVE="kali-nethunter-rootfs-${_ARCHIVE_TYPE}-${SYS_ARCH}.tar.xz"
FOUND_URL="https://kali.download/nethunter-images/current/rootfs/${ARCHIVE}"

_info "Verificando: $FOUND_URL"
_code="000"
if command -v curl >/dev/null 2>&1; then
  _code=$(curl -sL --max-time 20 -o /dev/null -w "%{http_code}" "$FOUND_URL" 2>/dev/null || echo "000")
elif command -v wget >/dev/null 2>&1; then
  wget -q --spider --timeout=20 "$FOUND_URL" 2>/dev/null && _code="200" || _code="404"
fi

[ "$_code" = "200" ] || _err "Arquivo não encontrado (HTTP $_code) para arch=$SYS_ARCH tipo=$_ARCHIVE_TYPE.
  Verifique: https://kali.download/nethunter-images/current/rootfs/
  Ou tente: pkg install proot-distro && proot-distro install kali"

_ok "Arquivo disponível: $ARCHIVE"

_info "URL: $FOUND_URL"
_TMPDIR="${TMPDIR:-$PREFIX/tmp}"
mkdir -p "$_TMPDIR"
_ARCHIVE_PATH="$_TMPDIR/$ARCHIVE"

# Download
if command -v wget >/dev/null 2>&1; then
  wget --show-progress -q -c -O "$_ARCHIVE_PATH" "$FOUND_URL" || _err "Download falhou"
elif command -v curl >/dev/null 2>&1; then
  curl -L -C - --progress-bar -o "$_ARCHIVE_PATH" "$FOUND_URL" || _err "Download falhou"
fi
_ok "Download concluído: $_ARCHIVE_PATH"

# ── Verificação SHA256 (busca do servidor) ────────────────────────────────
_info "Verificando integridade..."
_SHA_URL="${FOUND_URL}.sha256sum"
_SHA_FILE="$_TMPDIR/${ARCHIVE}.sha256sum"
if command -v curl >/dev/null 2>&1; then
  curl -sL --max-time 15 -o "$_SHA_FILE" "$_SHA_URL" 2>/dev/null || rm -f "$_SHA_FILE"
elif command -v wget >/dev/null 2>&1; then
  wget -q --timeout=15 -O "$_SHA_FILE" "$_SHA_URL" 2>/dev/null || rm -f "$_SHA_FILE"
fi

if [ -f "$_SHA_FILE" ] && [ -s "$_SHA_FILE" ] && command -v sha256sum >/dev/null 2>&1; then
  _EXPECTED=$(awk '{print $1}' "$_SHA_FILE")
  _ACTUAL=$(sha256sum "$_ARCHIVE_PATH" | awk '{print $1}')
  if [ "$_EXPECTED" = "$_ACTUAL" ]; then
    _ok "SHA256 verificado ✓"
  else
    _warn "SHA256 não corresponde!"
    printf "  Esperado : %s\n  Obtido   : %s\n" "$_EXPECTED" "$_ACTUAL"
    read -rp "  Continuar mesmo assim? [s/N] " _c
    case "${_c:-N}" in s|S|y|Y) : ;; *) rm -f "$_ARCHIVE_PATH" "$_SHA_FILE"; exit 1 ;; esac
  fi
  rm -f "$_SHA_FILE"
else
  _warn "Checksum não disponível — verificação ignorada"
fi

# ── Extração ──────────────────────────────────────────────────────────────
_head "Extraindo rootfs"
mkdir -p "$NH_ROOTFS"
_info "Extraindo para $NH_ROOTFS ..."

# proot --link2symlink trata symlinks como hard links (necessário no Android)
if proot --link2symlink tar -xJf "$_ARCHIVE_PATH"     --exclude='dev' -C "$NH_ROOTFS"     --strip-components=1 2>/dev/null; then
  _ok "Extração via proot --link2symlink"
else
  _warn "Tentando extração padrão..."
  tar -xJf "$_ARCHIVE_PATH"     --exclude='dev' -C "$NH_ROOTFS"     --strip-components=1 || _err "Falha na extração"
  _ok "Extração concluída"
fi

rm -f "$_ARCHIVE_PATH" 2>/dev/null || true

# Cria dispositivos e diretórios essenciais
mkdir -p "$NH_ROOTFS"/{dev,proc,sys,tmp,run,dev/shm}

# ── Configura rede e locale ───────────────────────────────────────────────
printf "nameserver 8.8.8.8\nnameserver 1.1.1.1\n"   > "$NH_ROOTFS/etc/resolv.conf" 2>/dev/null || true

[ -f "$NH_ROOTFS/etc/locale.gen" ] &&   sed -i 's/# en_US.UTF-8 UTF-8/en_US.UTF-8 UTF-8/'     "$NH_ROOTFS/etc/locale.gen" 2>/dev/null || true

# ── Cria launcher nethunter / nh ──────────────────────────────────────────
_head "Configurando launcher"

cat > "$TERMUX_BIN/nethunter" << 'LAUNCHEOF'
#!/data/data/com.termux/files/usr/bin/bash
# ElliotOS NetHunter launcher — multi-arch
PREFIX="${PREFIX:-/data/data/com.termux/files/usr}"
NH_ROOTFS="${HOME}/.xpm/kali/rootfs"

[ ! -d "$NH_ROOTFS" ] && {
  echo "NetHunter não instalado. Execute: ms -nh"
  exit 1
}

# Limpa LD_PRELOAD (Android hook) para evitar conflito com proot
unset LD_PRELOAD

# Monta bind mounts disponíveis
_BINDS="-b /dev -b /proc -b /sys"
[ -d "/sdcard" ] && _BINDS="$_BINDS -b /sdcard"
[ -d "/data"   ] && _BINDS="$_BINDS -b /data"

exec proot   --link2symlink   -0   -r "$NH_ROOTFS"   $_BINDS   -b "${HOME}:/root"   -w /root   /usr/bin/env -i     HOME=/root     TERM="${TERM:-xterm-256color}"     LANG=C.UTF-8     PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin     /bin/bash --login "$@"
LAUNCHEOF

chmod +x "$TERMUX_BIN/nethunter"
ln -sf "$TERMUX_BIN/nethunter" "$TERMUX_BIN/nh" 2>/dev/null ||   cp "$TERMUX_BIN/nethunter" "$TERMUX_BIN/nh" && chmod +x "$TERMUX_BIN/nh"
_ok "Launcher: nethunter"
_ok "Atalho:   nh"

# ── Resumo final ─────────────────────────────────────────────────────────
printf "\n${G}╔══════════════════════════════════════════════════════════╗${N}\n"
printf "${G}║  Kali NetHunter instalado com sucesso! ✓                 ║${N}\n"
printf "${G}╚══════════════════════════════════════════════════════════╝${N}\n\n"
printf "  ${W}Entrar no NetHunter:${N}\n"
printf "  ${B}  nethunter${N}   ou   ${B}nh${N}\n\n"
printf "  ${D}Arch: $SYS_ARCH | Tipo: $_TYPE (current)${N}\n"
printf "  ${D}Rootfs: $NH_ROOTFS${N}\n\n"
printf "  ${Y}Primeiros comandos dentro do NetHunter:${N}\n"
printf "  ${D}  apt update && apt upgrade -y${N}\n"
printf "  ${D}  apt install kali-linux-default${N}\n\n"
NHEOF
    chmod +x "$nh_script"
    printf "  \033[1;32m✓\033[0m NetHunter installer multi-arch v3 instalado\n"
}
_setup_prompt() {
    if ! grep -qF "ElliotOS: prompt customizado" "$HOME/.bashrc" 2>/dev/null; then
        cat >> "$HOME/.bashrc" << 'PROMPTEOF'

# ── ElliotOS: prompt customizado (ElliotOS) ──────────────────────────────────
# Captura o $? do ultimo comando ANTES de qualquer outra coisa rodar no
# prompt (o check de root/EUID dentro do PS1 senao "suja" o $? real).
PROMPT_COMMAND='_ELLIOT_LAST_STATUS=$?'"${PROMPT_COMMAND:+; $PROMPT_COMMAND}"
PS1='\[\e[1;35m\]╭─[\[\e[1;36m\]⚡\[\e[1;31m\]\u$(if [ $EUID -eq 0 ]; then echo " 💀🧅🐰"; fi)\[\e[1;35m\]@\[\e[1;31m\]ElliotOS\[\e[1;35m\]]─[\[\e[1;33m\]📁\[\e[1;34m\] \w\[\e[1;35m\]]─[\[\e[0;90m\]🕐\[\e[0;37m\] \A\[\e[1;35m\]]\[\e[0m\]\n\[\e[1;35m\]╰─$(if [ "${_ELLIOT_LAST_STATUS:-0}" -eq 0 ]; then echo "\[\e[1;32m\]✓"; else echo "\[\e[1;31m\]✗"; fi)\[\e[1;34m\] ➤ \[\e[0m\]'
# ────────────────────────────────────────────────────────────────────────────
PROMPTEOF
        _ok "Prompt customizado adicionado ao ~/.bashrc"
    else
        _ok "Prompt customizado já presente no ~/.bashrc — pulando"
    fi
}

# ════════════════════════════════════════════════════════════════════════════
# _setup_ip_var — variável $ip com o IP privado sempre pronta em todo shell
# novo, pra usar direto em nmap/outras ferramentas sem digitar ifconfig toda
# hora (ex: nmap -sV $ip/24). 3 níveis de detecção, do pedido pro que
# sobrevive num Termux mínimo: ifconfig (net-tools, o método pedido) -> ip
# addr (iproute2, quase sempre presente mesmo sem net-tools) -> getprop
# (funciona sem pacote nenhum extra). wlan0 primeiro (Wi-Fi, cenário mais
# comum de pentest no celular); sem isso, cai pro primeiro adaptador
# não-loopback com IPv4 (hotspot/USB/eth). Idempotente: só injeta se ainda
# não existir. Igual ao _setup_prompt, não dá source no .bashrc aqui — o
# usuario ativa com "source ~/.bashrc" no final.
# ════════════════════════════════════════════════════════════════════════════
_setup_ip_var() {
    # ifconfig é o método pedido — garante que existe, mas sem travar a
    # instalação se o download falhar (só perde esse fallback específico,
    # "ip addr"/getprop cobrem o resto).
    command -v ifconfig >/dev/null 2>&1 || pkg install -y net-tools 2>/dev/null || true

    if ! grep -qF "ElliotOS: variavel de IP privado" "$HOME/.bashrc" 2>/dev/null; then
        cat >> "$HOME/.bashrc" << 'IPEOF'

# ── ElliotOS: variavel de IP privado ($ip) ───────────────────────────────────
_elliot_refresh_ip() {
    local _v=""
    if command -v ifconfig >/dev/null 2>&1; then
        _v=$(ifconfig wlan0 2>/dev/null | grep -oE 'inet (addr:)?[0-9]+(\.[0-9]+){3}' | grep -oE '[0-9]+(\.[0-9]+){3}' | head -1)
        [ -z "$_v" ] && _v=$(ifconfig 2>/dev/null | grep -oE 'inet (addr:)?[0-9]+(\.[0-9]+){3}' | grep -oE '[0-9]+(\.[0-9]+){3}' | grep -v '^127\.' | head -1)
    fi
    if [ -z "$_v" ] && command -v ip >/dev/null 2>&1; then
        _v=$(ip -4 addr show wlan0 2>/dev/null | grep -oE 'inet [0-9]+(\.[0-9]+){3}' | grep -oE '[0-9]+(\.[0-9]+){3}' | head -1)
        [ -z "$_v" ] && _v=$(ip -4 addr show 2>/dev/null | grep -oE 'inet [0-9]+(\.[0-9]+){3}' | grep -oE '[0-9]+(\.[0-9]+){3}' | grep -v '^127\.' | head -1)
    fi
    if [ -z "$_v" ] && command -v getprop >/dev/null 2>&1; then
        _v=$(getprop dhcp.wlan0.ipaddress 2>/dev/null)
    fi
    if [ -n "$_v" ]; then
        export ip="$_v"
    else
        unset ip
        printf '\033[1;33m[!] nao consegui detectar o IP privado (wifi desconectado?)\033[0m\n' >&2
    fi
}
_elliot_refresh_ip
alias ip-refresh='_elliot_refresh_ip'
# ────────────────────────────────────────────────────────────────────────────
IPEOF
        _ok "Variável \$ip (IP privado automático) adicionada ao ~/.bashrc"
    else
        _ok "Variável \$ip já presente no ~/.bashrc — pulando"
    fi
}

# ════════════════════════════════════════════════════════════════════════════
# _setup_inputrc — Atalhos de teclado readline no ~/.inputrc
# Idempotente: só escreve se o bloco ElliotOS ainda não existir.
# ════════════════════════════════════════════════════════════════════════════
_setup_inputrc() {
    if ! grep -qF "# ElliotOS: readline" "$HOME/.inputrc" 2>/dev/null; then
        cat >> "$HOME/.inputrc" << 'INPUTRC_EOF'

# ── ElliotOS: readline ───────────────────────────────────────────────────────
set completion-ignore-case on

"\C-l": "clear\n"
# ─────────────────────────────────────────────────────────────────────────────
INPUTRC_EOF
        _ok "Atalhos readline adicionados ao ~/.inputrc"
    else
        _ok "Atalhos readline já presentes no ~/.inputrc — pulando"
    fi
}
