    if [ "$INSTALL_SQ" = "1" ]; then
        printf "\n\033[1;36m── Compilando editor.c ──────────────────────────────────────\033[0m\n"
        clang -O2 -o "$_EE_BIN" "$_EE_SRC" 2>&1 || \
            cc -O2 -o "$_EE_BIN" "$_EE_SRC" 2>&1 || {
            _warn "Falha ao compilar editor.c"
            return 1
        }
    else
        clang -O2 -o "$_EE_BIN" "$_EE_SRC" 2>/dev/null || \
            cc -O2 -o "$_EE_BIN" "$_EE_SRC" || {
            _warn "Falha ao compilar editor.c"
            return 1
        }
    fi
    chmod +x "$_EE_BIN"
    _ok "Editor ElliotOS instalado em $_EE_BIN"
}


# ============================================================================
# _install_gui — Instala ElliotOS + XFCE4 via Termux:X11
# Uso: bash luascript --gui
# Requer: app Termux:X11 instalado no Android (APK separado)
# ============================================================================
_install_gui() {
    _TPFX="${PREFIX:-/data/data/com.termux/files/usr}"

    printf "\n\033[1;35m── ElliotOS --gui — Instalação com Interface Gráfica ────────────\033[0m\n\n"
    printf "  \033[0;90mEsta opção instala o ElliotOS + ambiente XFCE4 leve\033[0m\n"
    printf "  \033[0;90mrequerendo o app Termux:X11 instalado no Android.\033[0m\n\n"

    # ── 1. Verifica ambiente Termux ──────────────────────────────────────
    if [ "${_ENV_TERMUX:-0}" != "1" ] && [ "${INSTALL_UPDATE:-0}" != "1" ]; then
        _err "--gui só funciona no Termux (Android)"
        exit 1
    fi

    # ── 2. Aviso sobre Termux:X11 ────────────────────────────────────────
    printf "  \033[1;33m⚠\033[0m  Antes de iniciar a GUI você precisará:\n"
    printf "        1. Instalar o app \033[1mTermux:X11\033[0m (disponível no F-Droid ou GitHub)\n"
    printf "           https://github.com/termux/termux-x11/releases\n"
    printf "        2. Abrir o app Termux:X11 no Android\n"
    printf "        3. Rodar: \033[1melliot-gui\033[0m no terminal\n\n"

    # ── 3. Instala ElliotOS base ─────────────────────────────────────────
    if [ "${INSTALL_UPDATE:-0}" != "1" ]; then
        _step "🔧" "Instalando ElliotOS base..."
        install_elliotos
    fi

    # ── 4. Instala dependências de GUI (XFCE4 mínimo) ───────────────────
    _step "🖥️" "Instalando ambiente gráfico XFCE4 (leve)..."
    _GUI_PKGS="termux-x11-nightly dbus x11-repo xfce4 xfce4-terminal xfce4-session xorg-xauth x11-utils xdotool onboard tigervnc termux-x11-nightly"
    printf "  \033[0;90mPacotes: %s\033[0m\n" "$_GUI_PKGS"
    _GUI_FAILED=""
    if [ "${INSTALL_UPDATE:-0}" != "1" ]; then
    for _gpkg in $_GUI_PKGS; do
        if ! pkg install -y "$_gpkg" >/dev/null 2>&1; then
            _GUI_FAILED="$_GUI_FAILED $_gpkg"
        fi
    done
    fi
    if [ -n "$_GUI_FAILED" ]; then
        _warn "Pacotes opcionais não instalados:$_GUI_FAILED"
        _warn "Alguns recursos de GUI podem não funcionar — continuando"
    else
        _ok "Pacotes GUI instalados"
    fi

    # ── 5a. Configura tema escuro GTK permanente ────────────────────────────
    _step "🌑" "Configurando tema escuro..."
    for _gtk_ver in 3.0 4.0; do
        _gtk_dir="$HOME/.config/gtk-${_gtk_ver}"
        mkdir -p "$_gtk_dir"
        cat > "$_gtk_dir/settings.ini" << 'GTKDARK'
[Settings]
gtk-application-prefer-dark-theme=1
gtk-theme-name=Adwaita-dark
gtk-icon-theme-name=Adwaita
GTKDARK
    done
    # Qt apps
    mkdir -p "$HOME/.config"
    cat >> "$HOME/.profile" << 'QTDARK'
# ElliotOS GUI — Qt dark
export QT_STYLE_OVERRIDE=Adwaita-Dark
export GTK_THEME=Adwaita:dark
# end ElliotOS GUI Qt
QTDARK
    _ok "Tema escuro configurado (GTK3, GTK4, Qt)"

    # ── 5. Configura variáveis de ambiente para Termux:X11 ───────────────
    _step "⚙️" "Configurando ambiente Termux:X11..."

    # Remove TODOS os blocos GUI anteriores (awk — sem python3)
    awk '/# ElliotOS GUI/{skip=1} skip{if(/# end ElliotOS GUI/)skip=0; next} 1'         "$HOME/.bashrc" > "$HOME/.bashrc.tmp" && mv "$HOME/.bashrc.tmp" "$HOME/.bashrc"

    cat >> "$HOME/.bashrc" << 'GUIENV'
# ElliotOS GUI
export DISPLAY=:1
export TMPDIR=/data/data/com.termux/files/usr/tmp
export PULSE_SERVER=tcp:127.0.0.1:4713
export GTK_THEME=Adwaita:dark
export QT_STYLE_OVERRIDE=Adwaita-Dark

_elliot_ensure_display() {
    local _TMP=/data/data/com.termux/files/usr/tmp
    local _SOCK="${_TMP}/.X11-unix/X1"
    local _AM="am start --user 0 -n com.termux.x11/com.termux.x11.MainActivity"

    # Servidor já rodando — abre X11 primeiro, aguarda, depois executa
    if [ -S "$_SOCK" ] && pgrep -f "termux-x11" >/dev/null 2>&1; then
        $_AM 2>/dev/null || true
        sleep 1
        export DISPLAY=:1
        export DBUS_SESSION_BUS_ADDRESS="unix:path=${_TMP}/dbus.sock"
        return 0
    fi

    # Socket stale: existe mas processo morreu
    if [ -S "$_SOCK" ]; then
        rm -f "$_SOCK" "${_TMP}/.X1-lock" 2>/dev/null
    fi

    # Servidor não está rodando — sobe tudo
    if ! command -v termux-x11 >/dev/null 2>&1; then
        echo "[elliot-gui] termux-x11 não encontrado. Instale: pkg install termux-x11-nightly"
        return 1
    fi
    echo "[elliot-gui] Display não encontrado — iniciando Termux:X11..."
    termux-x11 :1 &
    $_AM 2>/dev/null || true
    local _W=0
    until [ -S "$_SOCK" ]; do
        sleep 1; _W=$((_W+1))
        [ "$_W" -ge 15 ] && { echo "[elliot-gui] Timeout — abra o app Termux:X11 manualmente."; return 1; }
    done
    if ! pgrep -x xfwm4 >/dev/null 2>&1; then
        export DBUS_SESSION_BUS_ADDRESS="unix:path=${_TMP}/dbus.sock"
        pgrep -f "dbus-daemon.*dbus.sock" >/dev/null 2>&1 ||             dbus-daemon --session --address="$DBUS_SESSION_BUS_ADDRESS" --fork 2>/dev/null || true
        xfsettingsd --no-daemon 2>/dev/null &
        sleep 1
        xfdesktop 2>/dev/null &
        xfce4-panel 2>/dev/null &
        xfwm4 --display :1 2>/dev/null &
        echo "[elliot-gui] XFCE4 iniciado em background."
    fi
    export DISPLAY=:1
    export DBUS_SESSION_BUS_ADDRESS="unix:path=${_TMP}/dbus.sock"
}

# Use: rungui -l <linguagem> [-t <lib>] <arquivo>
# Ex:  rungui -l python -t tkinter app.py
#      rungui -l c -t gtk app.c
#      rungui -l love jogo/
# end ElliotOS GUI
GUIENV

    # ── 6. Cria wrapper elliot-gui ───────────────────────────────────────
    _step "🚀" "Criando wrapper elliot-gui..."
    cat > "${_TPFX}/bin/elliot-gui" << 'GUIWRAP'
#!/data/data/com.termux/files/usr/bin/bash
# elliot-gui — Inicia XFCE4 via Termux:X11
# Uso: elliot-gui [--kill]

_TERMUX_TMP="/data/data/com.termux/files/usr/tmp"
_DBUS_SOCK="${_TERMUX_TMP}/dbus.sock"

export DISPLAY=:1
export TMPDIR="$_TERMUX_TMP"
export PULSE_SERVER=tcp:127.0.0.1:4713
export XDG_RUNTIME_DIR="${_TERMUX_TMP}/xdg"
mkdir -p "$XDG_RUNTIME_DIR"

_RED='\033[1;31m'
_GRN='\033[1;32m'
_YEL='\033[1;33m'
_CYN='\033[1;36m'
_RST='\033[0m'

_die()  { printf "${_RED}✗ %s${_RST}\n" "$1"; exit 1; }
_info() { printf "${_CYN}→ %s${_RST}\n" "$1"; }
_ok()   { printf "${_GRN}✓ %s${_RST}\n" "$1"; }
_warn() { printf "${_YEL}⚠ %s${_RST}\n" "$1"; }

# ── Parse de todos os argumentos (suporta combinações: -m -b, etc.) ──────
_OPT_MOBILE=0
_OPT_BG=0
_OPT_NO_AM=0   # flag interna: não abrir app Termux:X11 via am start
for _arg in "$@"; do
    case "$_arg" in
        -m|--mobile)      _OPT_MOBILE=1 ;;
        -b|--background)  _OPT_BG=1     ;;
        --no-am)          _OPT_NO_AM=1  ;;
    esac
done

# ── -h / --help ──────────────────────────────────────────────────────────
if [ "${1:-}" = "-h" ] || [ "${1:-}" = "--help" ]; then
    printf "\n\033[1;35mElliotOS GUI — Gerenciador de Interface Gráfica\033[0m\n\n"
    printf "  \033[1;37mUso:\033[0m elliot-gui [opção]\n\n"
    printf "  \033[1;32m(sem args)\033[0m      Inicia XFCE4 via Termux:X11\n"
    printf "  \033[1;32m-b, --background\033[0m Inicia em background (libera o terminal)\n"
    printf "  \033[1;32m-m, --mobile\033[0m     Abre o ElliotOS Launcher (home screen)\n"
    printf "  \033[1;32m-m -b\033[0m            Launcher em background (sem bloquear terminal)\n"
    printf "  \033[1;32m--vnc\033[0m            Inicia XFCE4 via VNC (porta 5902)\n"
    printf "  \033[1;32m--vnc [RES]\033[0m      VNC com resolução customizada (ex: 1280x720)\n"
    printf "  \033[1;32m--vnc-stop\033[0m       Encerra servidor VNC\n"
    printf "  \033[1;32m--kill\033[0m           Encerra toda a sessão gráfica\n"
    printf "  \033[1;32m-h, --help\033[0m       Mostra esta ajuda\n"
    printf "\n"
    printf "  \033[1;37mExemplos:\033[0m\n"
    printf "  \033[0;90m  elliot-gui\033[0m            # inicia XFCE4\n"
    printf "  \033[0;90m  elliot-gui -b\033[0m         # inicia em background\n"
    printf "  \033[0;90m  elliot-gui -m\033[0m         # abre o launcher mobile\n"
    printf "  \033[0;90m  elliot-gui -m -b\033[0m      # launcher em background\n"
    printf "  \033[0;90m  elliot-gui --vnc\033[0m      # inicia via VNC\n"
    printf "  \033[0;90m  elliot-gui --vnc 1280x720\033[0m  # VNC com resolução\n"
    printf "  \033[0;90m  elliot-gui --kill\033[0m     # encerra tudo\n"
    printf "\n"
    printf "  \033[1;37mRequer:\033[0m app Termux:X11 (para modo padrão/background/mobile)\n"
    printf "         app VNC como RVNC Viewer ou bVNC (para --vnc)\n\n"
    exit 0
fi

# ── -b / --background ────────────────────────────────────────────────────
# Re-lança a si mesmo com --no-am em background, passando flags restantes
if [ "$_OPT_BG" = "1" ]; then
    # Monta args sem o -b para o processo filho (--no-am é adicionado)
    _CHILD_ARGS="--no-am"
    [ "$_OPT_MOBILE" = "1" ] && _CHILD_ARGS="-m --no-am"
    nohup "$0" $_CHILD_ARGS > "${TMPDIR}/elliot-gui.log" 2>&1 &
    _BG_PID=$!
    sleep 2
    if kill -0 "$_BG_PID" 2>/dev/null; then
        printf "${_GRN}✓ elliot-gui rodando em background (PID %s)${_RST}\n" "$_BG_PID"
        printf "  ${_YEL}Log: %s/elliot-gui.log${_RST}\n" "$TMPDIR"
        printf "  ${_YEL}Para encerrar: elliot-gui --kill${_RST}\n"
    else
        printf "${_RED}✗ elliot-gui falhou — veja: %s/elliot-gui.log${_RST}\n" "$TMPDIR"
    fi
    exit 0
fi

# ── -m / --mobile — abre o ElliotOS Launcher (home screen mobile) ────────
if [ "$_OPT_MOBILE" = "1" ]; then
    if ! command -v love >/dev/null 2>&1; then
        printf "${_RED}✗ Love2D não encontrado. Instale: pkg install love${_RST}\n"
        exit 1
    fi
    _LAUNCHER_DIR="$HOME/.elliot/launcher"
    if [ ! -f "$_LAUNCHER_DIR/main.lua" ]; then
        printf "${_RED}✗ Launcher não instalado. Rode: bash luascript --gui${_RST}\n"
        exit 1
    fi
    # Garante servidor X ativo
    _X11_SOCK="/data/data/com.termux/files/usr/tmp/.X11-unix/X1"
    if ! [ -S "$_X11_SOCK" ] || ! pgrep -f "termux-x11" >/dev/null 2>&1; then
        "$0" --no-am
        sleep 3
    fi
    # Abre o app Termux:X11 no Android apenas se não for modo --no-am
    [ "$_OPT_NO_AM" = "0" ] && am start --user 0 -n com.termux.x11/com.termux.x11.MainActivity 2>/dev/null || true
    sleep 1
    # Força software rendering para evitar erro MESA/ZINK
    export GALLIUM_DRIVER=llvmpipe
    export LIBGL_ALWAYS_SOFTWARE=1
    export MESA_GL_VERSION_OVERRIDE=3.3
    export EGL_LOG_LEVEL=fatal
    # Redireciona stderr do love para o log (suprime XIO errors no terminal)
    DISPLAY=:1 love "$_LAUNCHER_DIR" 2>>"${TMPDIR}/elliot-gui.log" &
    printf "${_GRN}✓ ElliotOS Launcher iniciado${_RST}\n"
    [ "$_OPT_NO_AM" = "0" ] && printf "  ${_YEL}Abra o app Termux:X11 no Android para ver.${_RST}\n"
    exit 0
fi

# ── --vnc / --vnc-stop ───────────────────────────────────────────────────
if [ "${1:-}" = "--vnc" ]; then
    if ! command -v vncserver >/dev/null 2>&1; then
        printf "${_RED}✗ TigerVNC não encontrado. Instale: pkg install tigervnc${_RST}\n"
        exit 1
    fi
    _VNC_PASS="$HOME/.vnc/passwd"
    if [ ! -f "$_VNC_PASS" ]; then
        printf "${_CYN}→ Configurando senha VNC (mín. 6 caracteres)...${_RST}\n"
        vncpasswd || exit 1
    fi
    vncserver -kill :2 2>/dev/null || true
    sleep 1
    mkdir -p "$HOME/.vnc"
    cat > "$HOME/.vnc/xstartup" << 'VNCSTART'
#!/data/data/com.termux/files/usr/bin/bash
export DISPLAY=:2
export DBUS_SESSION_BUS_ADDRESS="unix:path=/data/data/com.termux/files/usr/tmp/dbus-vnc.sock"
export GTK_THEME=Adwaita:dark
export XDG_RUNTIME_DIR="/data/data/com.termux/files/usr/tmp/xdg-vnc"
mkdir -p "$XDG_RUNTIME_DIR"
# Força software rendering para evitar erro MESA/ZINK no Android
export GALLIUM_DRIVER=llvmpipe
export LIBGL_ALWAYS_SOFTWARE=1
export MESA_GL_VERSION_OVERRIDE=3.3
export MESA_GLSL_VERSION_OVERRIDE=330
export EGL_LOG_LEVEL=fatal
export MESA_LOADER_DRIVER_OVERRIDE=llvmpipe
dbus-daemon --session --address="$DBUS_SESSION_BUS_ADDRESS" --fork 2>/dev/null || true
xfsettingsd --no-daemon &
sleep 1
xfdesktop &
xfce4-panel &
exec xfwm4 --display :2
VNCSTART
    chmod +x "$HOME/.vnc/xstartup"
    _VNC_RES="${2:-1080x1920}"
    _info "Iniciando VNC em :2 (porta 5902) — ${_VNC_RES}..."
    vncserver :2 -geometry "$_VNC_RES" -depth 24 2>/dev/null
    _ok "Servidor VNC rodando!"
    printf "\n"
    printf "  ${_YEL}Conecte com um app VNC (RVNC Viewer, bVNC):${_RST}\n"
    printf "  ${_YEL}  Host: localhost   Porta: 5902${_RST}\n"
    printf "  ${_YEL}Para encerrar: elliot-gui --vnc-stop${_RST}\n\n"
    exit 0
fi

if [ "${1:-}" = "--vnc-stop" ]; then
    _info "Encerrando servidor VNC..."
    vncserver -kill :2 2>/dev/null || true
    pkill -f "Xtightvnc\|Xtigervnc\|vncserver" 2>/dev/null || true
    _ok "VNC encerrado."
    exit 0
fi

if [ "${1:-}" = "--kill" ]; then
    _info "Encerrando sessão GUI..."
    pkill -f xfwm4         2>/dev/null || true
    pkill -f xfdesktop     2>/dev/null || true
    pkill -f xfce4-panel   2>/dev/null || true
    pkill -f xfsettingsd   2>/dev/null || true
    pkill -f dbus-daemon   2>/dev/null || true
    pkill -f termux-x11    2>/dev/null || true
    # Aguarda processos encerrarem de fato antes de limpar arquivos
    _W=0
    while pgrep -f "termux-x11\|xfwm4\|xfdesktop\|xfce4-panel" >/dev/null 2>&1; do
        sleep 1
        _W=$((_W+1))
        [ "$_W" -ge 5 ] && { pkill -9 -f "termux-x11\|xfwm4\|xfdesktop\|xfce4-panel" 2>/dev/null || true; break; }
    done
    sleep 1
    # Remove sockets e locks para permitir reinício limpo
    rm -f "$_DBUS_SOCK" 2>/dev/null || true
    rm -f "${_TERMUX_TMP}/.X1-lock" 2>/dev/null || true
    rm -f "${_TERMUX_TMP}/.X11-unix/X1" 2>/dev/null || true
    _ok "GUI encerrada."
    exit 0
fi

# ── Verifica termux-x11 ───────────────────────────────────────────────────
if ! command -v termux-x11 >/dev/null 2>&1; then
    _die "termux-x11 não encontrado.
  1. Instale o APK: https://github.com/termux/termux-x11/releases
  2. Depois: pkg install termux-x11-nightly"
fi

# ── Limpeza completa antes de iniciar ────────────────────────────────────
# Mata qualquer instância prévia de termux-x11 (processo real, não só socket)
# Isso resolve "server already running" causado por processos zumbis ou
# sesssões anteriores que não foram encerradas corretamente.
_X11_SOCK="${_TERMUX_TMP}/.X11-unix/X1"
_X11_LOCK="${_TERMUX_TMP}/.X1-lock"

_X11_IS_ALIVE=0
if pgrep -f "termux-x11" >/dev/null 2>&1 && [ -S "$_X11_SOCK" ]; then
    # Processo rodando E socket presente = sessão ativa legítima
    _X11_IS_ALIVE=1
fi

if [ "$_X11_IS_ALIVE" = "0" ]; then
    # Qualquer outra combinação = estado inconsistente — limpeza total
    if pgrep -f "termux-x11" >/dev/null 2>&1; then
        _warn "Processo termux-x11 órfão detectado — encerrando..."
        pkill -f "termux-x11" 2>/dev/null || true
        sleep 1
    fi
    if [ -S "$_X11_SOCK" ] || [ -f "$_X11_LOCK" ]; then
        _warn "Arquivos stale detectados — limpando..."
        rm -f "$_X11_SOCK" "$_X11_LOCK" 2>/dev/null || true
        rmdir "${_TERMUX_TMP}/.X11-unix" 2>/dev/null || true
        mkdir -p "${_TERMUX_TMP}/.X11-unix"
    fi
fi

# ── Inicia servidor Termux:X11 ────────────────────────────────────────────
if [ "$_X11_IS_ALIVE" = "1" ]; then
    _ok "Servidor X já está rodando em :1"
else
    _info "Iniciando servidor Termux:X11..."
    termux-x11 :1 &
    # Abre o app Termux:X11 no Android (apenas no modo normal, não no -b)
    [ "$_OPT_NO_AM" = "0" ] && am start --user 0 -n com.termux.x11/com.termux.x11.MainActivity 2>/dev/null || true
    # Aguarda socket aparecer
    _WAIT=0
    until [ -S "$_X11_SOCK" ]; do
        sleep 1
        _WAIT=$((_WAIT + 1))
        [ "$_WAIT" -ge 15 ] && _die "Timeout — abra o app Termux:X11 no Android e tente novamente."
    done
    _ok "Servidor X pronto em :1"
fi

# ── dbus ──────────────────────────────────────────────────────────────────
if pgrep -f "dbus-daemon.*${_DBUS_SOCK}" >/dev/null 2>&1; then
    _ok "dbus já está rodando"
    export DBUS_SESSION_BUS_ADDRESS="unix:path=${_DBUS_SOCK}"
else
    _info "Iniciando dbus-daemon..."
    rm -f "$_DBUS_SOCK" 2>/dev/null || true
    if command -v dbus-daemon >/dev/null 2>&1; then
        dbus-daemon --session \
            --address="unix:path=${_DBUS_SOCK}" \
            --fork 2>/dev/null \
            && export DBUS_SESSION_BUS_ADDRESS="unix:path=${_DBUS_SOCK}" \
            && _ok "dbus iniciado" \
            || _warn "dbus falhou — continuando sem ele"
    else
        _warn "dbus não encontrado — instale: pkg install dbus"
    fi
fi

# ── Tema escuro ───────────────────────────────────────────────────────────
export GTK_THEME=Adwaita:dark
export QT_STYLE_OVERRIDE=Adwaita-Dark
if command -v xfconf-query >/dev/null 2>&1; then
    xfconf-query -c xsettings -p /Net/ThemeName -s "Adwaita-dark" --create -t string 2>/dev/null || true
    xfconf-query -c xsettings -p /Gtk/ApplicationPreferDarkTheme -s true --create -t bool 2>/dev/null || true
    xfconf-query -c xfwm4 -p /general/use_compositing -s false --create -t bool 2>/dev/null || true
fi

# ── Força software rendering (corrige erro MESA: ZINK failed / dri2 screen) ──
# O Android/Termux não expõe GPU via DRI — ZINK/Vulkan falham ao tentar usar
# a placa de vídeo. Forçamos llvmpipe (software renderer) para evitar o crash.
export GALLIUM_DRIVER=llvmpipe
export LIBGL_ALWAYS_SOFTWARE=1
export MESA_GL_VERSION_OVERRIDE=3.3
export MESA_GLSL_VERSION_OVERRIDE=330
# Suprime warnings de EGL/DRI que poluem o log mas não afetam o funcionamento
export EGL_LOG_LEVEL=fatal
export MESA_LOADER_DRIVER_OVERRIDE=llvmpipe

# ── Inicia componentes XFCE4 ─────────────────────────────────────────────
_ok "Iniciando XFCE4 em DISPLAY=:1 (renderer: llvmpipe/software)"
printf "  ${_YEL}Abra o app Termux:X11 no Android para ver a tela.${_RST}\n"
printf "  ${_YEL}Para rodar em background: elliot-gui -b${_RST}\n"
printf "  ${_YEL}Modo mobile: elliot-gui -m${_RST}\n"
printf "  ${_YEL}Para encerrar: elliot-gui --kill${_RST}\n\n"

xfsettingsd --no-daemon 2>>"${TMPDIR}/elliot-gui.log" &
sleep 1

xfdesktop 2>>"${TMPDIR}/elliot-gui.log" &
xfce4-panel 2>>"${TMPDIR}/elliot-gui.log" &

# xfwm4 bloqueia — mantém o processo vivo; stderr vai pro log, não ao terminal
exec xfwm4 --display :1 2>>"${TMPDIR}/elliot-gui.log"
GUIWRAP
    chmod +x "${_TPFX}/bin/elliot-gui"
    _ok "Wrapper elliot-gui instalado em ${_TPFX}/bin/elliot-gui"

    # ── 7. Cria binário rungui ────────────────────────────────────────────
    _step "🎮" "Criando binário rungui..."
    cat > "${_TPFX}/bin/rungui" << 'RUNGUIWRAP'
#!/data/data/com.termux/files/usr/bin/bash
# rungui — Executa qualquer script/programa com GUI via Termux:X11
# Uso: rungui -l <linguagem> [-t <lib>] <arquivo> [args...]
#      rungui -l love <pasta/>
#
# Linguagens: python, c, c++, love, java, lua
# Libs C/C++: gtk, gtk3, gtk4, sdl2, sfml, opengl, fltk, wx
# Libs Python: tkinter, pygame, wx, PyQt5, PyQt6, kivy, arcade, pyglet, turtle, glfw
# Libs Java:   swing, javafx, awt
# Libs Lua:    love, iup

_TERMUX_TMP="/data/data/com.termux/files/usr/tmp"
_DBUS_SOCK="${_TERMUX_TMP}/dbus.sock"
_X11_SOCK="${_TERMUX_TMP}/.X11-unix/X1"
_AM="am start --user 0 -n com.termux.x11/com.termux.x11.MainActivity"

export DISPLAY=:1
export TMPDIR="$_TERMUX_TMP"
export GTK_THEME=Adwaita:dark

_RED='\033[1;31m'
_GRN='\033[1;32m'
_YEL='\033[1;33m'
_CYN='\033[1;36m'
_RST='\033[0m'

_die()  { printf "${_RED}✗ %s${_RST}\n" "$*" >&2; exit 1; }
_info() { printf "${_CYN}→ %s${_RST}\n" "$*"; }
_ok()   { printf "${_GRN}✓ %s${_RST}\n" "$*"; }
_warn() { printf "${_YEL}⚠ %s${_RST}\n" "$*"; }

# ── Parse de argumentos ───────────────────────────────────────────────────
_LANG=""
_LIB=""
_FILE=""
_EXTRA_ARGS=""

while [ $# -gt 0 ]; do
    case "$1" in
        -l|--lang)  shift; _LANG="$1" ;;
        -t|--type)  shift; _LIB="$1"  ;;
        -h|--help)
            printf "Uso: rungui -l <linguagem> [-t <lib>] <arquivo> [args...]\n\n"
            printf "Linguagens:\n"
            printf "  python, c, c++, love, java, lua\n\n"
            printf "Libs GUI:\n"
            printf "  Python : tkinter pygame wx PyQt5 PyQt6 kivy arcade pyglet turtle glfw\n"
            printf "  C/C++  : gtk gtk3 gtk4 sdl2 sfml opengl fltk wx\n"
            printf "  Java   : swing javafx awt\n"
            printf "  Lua    : love iup\n\n"
            printf "Exemplos:\n"
            printf "  rungui -l python -t tkinter app.py\n"
            printf "  rungui -l c -t gtk app.c\n"
            printf "  rungui -l c++ -t sdl2 jogo.cpp\n"
            printf "  rungui -l love jogo/\n"
            printf "  rungui -l java -t swing App.java\n"
            exit 0
            ;;
        *)
            if [ -z "$_FILE" ]; then
                _FILE="$1"
            else
                _EXTRA_ARGS="$_EXTRA_ARGS $1"
            fi
            ;;
    esac
    shift
done

[ -z "$_LANG" ] && _die "Linguagem não especificada. Use: rungui -l <linguagem>"
[ -z "$_FILE" ] && _die "Arquivo não especificado."

# ── Normaliza linguagem ───────────────────────────────────────────────────
case "$_LANG" in
    python|python3|py) _LANG="python" ;;
    c|clang)           _LANG="c"      ;;
    c++|cpp|clang++)   _LANG="cpp"    ;;
    love|love2d)       _LANG="love"   ;;
    java)              _LANG="java"   ;;
    lua)               _LANG="lua"    ;;
    *) _die "Linguagem '$_LANG' não suportada. Use: python, c, c++, love, java, lua" ;;
esac

# ── Verifica arquivo/pasta ────────────────────────────────────────────────
if [ "$_LANG" != "love" ]; then
    [ -f "$_FILE" ] || _die "Arquivo '$_FILE' não encontrado."
fi

# ── Flags de compilação por lib (C/C++) ───────────────────────────────────
_get_compile_flags() {
    case "$1" in
        gtk|gtk3)  echo "$(pkg-config --cflags --libs gtk+-3.0 2>/dev/null || echo '-lgtk-3')" ;;
        gtk4)      echo "$(pkg-config --cflags --libs gtk4 2>/dev/null || echo '-lgtk-4')" ;;
        sdl2)      echo "$(pkg-config --cflags --libs sdl2 SDL2_image SDL2_ttf 2>/dev/null || echo '-lSDL2')" ;;
        sfml)      echo "-lsfml-graphics -lsfml-window -lsfml-system" ;;
        opengl)    echo "-lGL -lGLU -lglut" ;;
        fltk)      echo "$(fltk-config --cflags --libs 2>/dev/null || echo '-lfltk')" ;;
        wx)        echo "$(wx-config --cflags --libs 2>/dev/null || echo '-lwx')" ;;
        *)         echo "" ;;
    esac
}

# ── Sobe servidor X11 ─────────────────────────────────────────────────────
_RUNGUI_OWNED_SERVER=0  # 1 = rungui subiu o servidor, deve desligar ao fim

_ensure_x11() {
    # Stale socket
    if [ -S "$_X11_SOCK" ] && ! pgrep -f "termux-x11" >/dev/null 2>&1; then
        rm -f "$_X11_SOCK" "${_TERMUX_TMP}/.X1-lock" 2>/dev/null
    fi

    if [ -S "$_X11_SOCK" ] && pgrep -f "termux-x11" >/dev/null 2>&1; then
        _ok "Servidor X já rodando em :1"
        _RUNGUI_OWNED_SERVER=0
    else
        _info "Iniciando servidor Termux:X11..."
        rm -f "${_TERMUX_TMP}/.X1-lock" 2>/dev/null || true
        termux-x11 :1 &
        _RUNGUI_OWNED_SERVER=1
        local _W=0
        until [ -S "$_X11_SOCK" ]; do
            sleep 1; _W=$((_W+1))
            [ "$_W" -ge 15 ] && _die "Timeout — verifique o app Termux:X11."
        done
        _ok "Servidor X pronto em :1"
    fi

    # dbus
    if ! pgrep -f "dbus-daemon.*${_DBUS_SOCK}" >/dev/null 2>&1; then
        rm -f "$_DBUS_SOCK" 2>/dev/null
        dbus-daemon --session --address="unix:path=${_DBUS_SOCK}" --fork 2>/dev/null || true
    fi
    export DBUS_SESSION_BUS_ADDRESS="unix:path=${_DBUS_SOCK}"

    # XFCE4 se não estiver rodando
    if ! pgrep -x xfwm4 >/dev/null 2>&1; then
        xfsettingsd --no-daemon 2>/dev/null &
        sleep 1
        xfdesktop 2>/dev/null &
        xfce4-panel 2>/dev/null &
        xfwm4 --display :1 2>/dev/null &
        sleep 1
        _ok "XFCE4 iniciado"
    fi

    # Abre app e força fullscreen assim que uma janela aparecer
    $_AM 2>/dev/null || true
    sleep 1
    {
        local _W=0
        while [ $_W -lt 10 ]; do
            local _WID
            _WID=$(xdotool search --onlyvisible --name "" 2>/dev/null | head -1)
            if [ -n "$_WID" ]; then
                xdotool windowstate --add FULLSCREEN "$_WID" 2>/dev/null
                break
            fi
            sleep 1
            _W=$((_W+1))
        done
    } &
}

# ── Encerra servidor se foi o rungui que subiu e volta pro Termux ─────────
_cleanup_x11() {
    if [ "$_RUNGUI_OWNED_SERVER" = "1" ]; then
        _info "Encerrando servidor X11 (iniciado pelo rungui)..."
        pkill -f xfwm4         2>/dev/null || true
        pkill -f xfdesktop     2>/dev/null || true
        pkill -f xfce4-panel   2>/dev/null || true
        pkill -f xfsettingsd   2>/dev/null || true
        pkill -f dbus-daemon   2>/dev/null || true
        pkill -f termux-x11    2>/dev/null || true
        sleep 1
        rm -f "$_X11_SOCK" "${_TERMUX_TMP}/.X1-lock" "$_DBUS_SOCK" 2>/dev/null || true
        _ok "Servidor encerrado."
    fi
    # Sempre volta pro Termux ao terminar (normal ou Ctrl+C)
    am start com.termux/com.termux.app.TermuxActivity 2>/dev/null || true
}
trap _cleanup_x11 EXIT INT TERM

# ── Compila se necessário (C/C++) ─────────────────────────────────────────
_BIN=""
_compile() {
    local _flags
    _flags=$(_get_compile_flags "$_LIB")
    local _out="${_TERMUX_TMP}/rungui_$$"
    _info "Compilando '$_FILE' com lib '$_LIB'..."
    if [ "$_LANG" = "c" ]; then
        clang "$_FILE" -o "$_out" $_flags 2>&1 || _die "Falha na compilação."
    else
        clang++ "$_FILE" -o "$_out" $_flags 2>&1 || _die "Falha na compilação."
    fi
    _ok "Compilado: $_out"
    _BIN="$_out"
}

# ── Executa ───────────────────────────────────────────────────────────────
_ensure_x11

case "$_LANG" in
    python)
        command python3 "$_FILE" $_EXTRA_ARGS
        ;;
    c|cpp)
        _compile
        "$_BIN" $_EXTRA_ARGS
        rm -f "$_BIN"
        ;;
    love)
        command love "$_FILE" $_EXTRA_ARGS
        ;;
    java)
        # Compila .java se necessário
        if echo "$_FILE" | grep -q "\.java$"; then
            _info "Compilando '$_FILE'..."
            javac "$_FILE" || _die "Falha na compilação Java."
            _CLASS=$(basename "$_FILE" .java)
            _DIR=$(dirname "$_FILE")
            command java -cp "$_DIR" "$_CLASS" $_EXTRA_ARGS
        else
            # Já é .class ou .jar
            command java -cp "$(dirname $_FILE)" "$(basename $_FILE .class)" $_EXTRA_ARGS
        fi
        ;;
    lua)
        if [ "$_LIB" = "love" ]; then
            command love "$_FILE" $_EXTRA_ARGS
        else
            command lua "$_FILE" $_EXTRA_ARGS
        fi
        ;;
esac
