    # Copia módulos do launcher (statusbar, dock, grid, main)
    # main.lua
    cat > "${_LAUNCHER_DIR}/main.lua" << 'LAUNCHERMAIN'
local StatusBar = require("modules.statusbar")
local Dock      = require("modules.dock")
local Grid      = require("modules.grid")
local Apps      = require("apps")
local SW,SH     = 0,0
local cur_page  = 1
local tot_pages = #Apps.pages
local touch_st  = nil
local SWIPE_T   = 60
local popup     = nil
local wallpaper = nil

local function load_wp()
    local p = os.getenv("HOME").."/.elliot/launcher/assets/wallpaper.png"
    pcall(function() wallpaper = love.graphics.newImage(p) end)
end

local function open_app(app)
    if not app then return end
    popup = {name=app.name, timer=1.5}
    os.execute(app.cmd.." &")
end

local function go_page(dir)
    local n = cur_page + dir
    if n<1 or n>tot_pages then return end
    cur_page = n
    Grid.set_apps(Apps.pages[cur_page])
    Grid.slide_in(-dir)
end

function love.load()
    SW,SH = love.graphics.getDimensions()
    love.graphics.setDefaultFilter("linear","linear")
    StatusBar.load()
    Dock.load(Apps.dock)
    Grid.load(Apps.pages[cur_page], SW, SH, StatusBar.height(), Dock.height())
    load_wp()
end

function love.update(dt)
    StatusBar.update(dt)
    Dock.update(dt)
    Grid.update(dt)
    if popup then
        popup.timer = popup.timer - dt
        if popup.timer <= 0 then popup = nil end
    end
end

local function draw_bg()
    if wallpaper then
        local iw,ih = wallpaper:getDimensions()
        local s = math.max(SW/iw, SH/ih)
        love.graphics.setColor(1,1,1,1)
        love.graphics.draw(wallpaper, SW/2, SH/2, 0, s, s, iw/2, ih/2)
        love.graphics.setColor(0,0,0,0.55)
        love.graphics.rectangle("fill",0,0,SW,SH)
    else
        love.graphics.setColor(0.04,0.04,0.08,1)
        love.graphics.rectangle("fill",0,0,SW,SH)
        love.graphics.setColor(0.25,0.08,0.45,0.18)
        love.graphics.circle("fill", SW*0.5, SH*0.15, SW*0.7)
        love.graphics.setColor(0.05,0.15,0.4,0.15)
        love.graphics.circle("fill", SW*0.8, SH*0.6, SW*0.42)
    end
end

local function draw_popup()
    if not popup then return end
    local a   = math.min(1, popup.timer/0.3)
    local f   = love.graphics.newFont(16)
    local msg = "Abrindo "..popup.name.."..."
    local mw  = f:getWidth(msg)+32
    local mx, my = SW/2-mw/2, SH/2-22
    love.graphics.setColor(0.1,0.1,0.15,0.92*a)
    love.graphics.rectangle("fill",mx,my,mw,44,12,12)
    love.graphics.setColor(0.5,0.3,1.0,0.7*a)
    love.graphics.setLineWidth(1.5)
    love.graphics.rectangle("line",mx,my,mw,44,12,12)
    love.graphics.setFont(f)
    love.graphics.setColor(1,1,1,a)
    love.graphics.print(msg, mx+16, my+13)
end

function love.draw()
    love.graphics.clear(0.04,0.04,0.08,1)
    draw_bg()
    Grid.draw()
    StatusBar.draw(SW, cur_page, tot_pages)
    Dock.draw(SW, SH)
    draw_popup()
end

local function on_press(x,y)
    touch_st = {x=x, y=y, time=love.timer.getTime()}
    Grid.touch(x,y)
    Dock.touch(SW,SH,x,y)
end

local function on_release(x,y)
    Dock.release(); Grid.release()
    if not touch_st then return end
    local dx = x-touch_st.x
    local dy = y-touch_st.y
    touch_st = nil
    if math.abs(dx)>SWIPE_T and math.abs(dx)>math.abs(dy)*1.5 then
        go_page(dx<0 and 1 or -1); return
    end
    if math.abs(dx)<15 and math.abs(dy)<15 then
        local app = Dock.touch(SW,SH,x,y)
        if app then open_app(app); return end
        app = Grid.touch(x,y)
        if app then open_app(app) end
    end
end

function love.touchpressed(id,x,y)  on_press(x,y)   end
function love.touchreleased(id,x,y) on_release(x,y) end
function love.mousepressed(x,y,b)   if b==1 then on_press(x,y)   end end
function love.mousereleased(x,y,b)  if b==1 then on_release(x,y) end end
function love.keypressed(k) if k=="escape" then love.event.quit() end end
function love.resize(w,h)
    SW,SH=w,h
    Grid.load(Apps.pages[cur_page],SW,SH,StatusBar.height(),Dock.height())
end
LAUNCHERMAIN

