SBMOD

    # modules/dock.lua
    cat > "${_LAUNCHER_DIR}/modules/dock.lua" << 'DOCKMOD'
local M={}
local fa,fl,apps,H,IS,press,anim={},{},{},100,80,nil,{}
function M.load(a)
    apps=a
    fa=love.graphics.newFont(44)
    fl=love.graphics.newFont(13)
    for i=1,#a do anim[i]=1.0 end
end
function M.update(dt)
    for i=1,#anim do
        if press==i then anim[i]=math.max(0.85,anim[i]-dt*6)
        else anim[i]=math.min(1.0,anim[i]+dt*8) end
    end
end
function M.draw(sw,sh)
    local y0=sh-H
    love.graphics.setColor(0.07,0.07,0.11,0.97)
    love.graphics.rectangle("fill",0,y0,sw,H)
    love.graphics.setColor(0.4,0.2,0.8,0.5)
    love.graphics.rectangle("fill",0,y0,sw,1)
    local slot=sw/#apps
    for i,app in ipairs(apps) do
        local cx=slot*(i-0.5)
        local cy=y0+H/2-6
        local sc=anim[i]
        local r,g,b=app.color[1],app.color[2],app.color[3]
        local rad=(IS/2)*sc
        love.graphics.setColor(r*0.25,g*0.25,b*0.25,0.9)
        love.graphics.circle("fill",cx,cy,rad+2)
        love.graphics.setColor(r*0.5,g*0.5,b*0.5,0.7)
        love.graphics.circle("line",cx,cy,rad+2)
        love.graphics.setFont(fa)
        love.graphics.setColor(1,1,1,0.95)
        love.graphics.print(app.emoji, cx-fa:getWidth(app.emoji)/2, cy-fa:getHeight()/2)
        love.graphics.setFont(fl)
        love.graphics.setColor(0.8,0.8,0.8,0.8)
        love.graphics.print(app.name, cx-fl:getWidth(app.name)/2, y0+H-16)
    end
end
function M.touch(sw,sh,x,y)
    local y0=sh-H
    if y<y0 then return nil end
    local idx=math.floor(x/(sw/#apps))+1
    if idx>=1 and idx<=#apps then press=idx; return apps[idx] end
    return nil
end
function M.release() press=nil end
function M.height() return H end
return M
DOCKMOD

    # modules/grid.lua
    cat > "${_LAUNCHER_DIR}/modules/grid.lua" << 'GRIDMOD'
local M={}
local fe,fl,cols,rows,IS,apps,press,anim,ox,tx,sw,sh,top,bot=
      nil,nil,4,4,130,{},nil,{},0,0,0,0,0,0
function M.load(a,w,h,t,b)
    apps,sw,sh,top,bot=a,w,h,t,b
    fe=love.graphics.newFont(52)
    fl=love.graphics.newFont(14)
    anim={}
    for i=1,#a do anim[i]={scale=1.0} end
end
function M.update(dt)
    ox=ox+(tx-ox)*math.min(1,dt*14)
    for i=1,#anim do
        if press==i then anim[i].scale=math.max(0.82,anim[i].scale-dt*7)
        else anim[i].scale=math.min(1.0,anim[i].scale+dt*9) end
    end
end
function M.set_apps(a)
    apps=a; anim={}
    for i=1,#a do anim[i]={scale=1.0} end
    press=nil
end
function M.draw()
    local ah=sh-top-bot
    local cw=sw/cols
    local ch=ah/rows
    for i,app in ipairs(apps) do
        local col=(i-1)%cols
        local row=math.floor((i-1)/cols)
        local cx=ox+cw*col+cw/2
        local cy=top+ch*row+ch/2-4
        local sc=anim[i] and anim[i].scale or 1.0
        local r,g,b=app.color[1],app.color[2],app.color[3]
        local rad=(IS/2)*sc
        love.graphics.setColor(0,0,0,0.3)
        love.graphics.circle("fill",cx+2,cy+3,rad)
        love.graphics.setColor(r*0.2,g*0.2,b*0.2,0.92)
        love.graphics.circle("fill",cx,cy,rad)
        love.graphics.setColor(r*0.7,g*0.7,b*0.7,0.8)
        love.graphics.setLineWidth(1.5)
        love.graphics.circle("line",cx,cy,rad)
        love.graphics.setFont(fe)
        love.graphics.setColor(1,1,1,0.95)
        love.graphics.print(app.emoji, cx-fe:getWidth(app.emoji)/2, cy-fe:getHeight()/2)
        love.graphics.setFont(fl)
        love.graphics.setColor(0.9,0.9,0.9,0.85)
        love.graphics.print(app.name, cx-fl:getWidth(app.name)/2, cy+rad+2)
    end
end
function M.touch(x,y)
    if y<top or y>sh-bot then return nil end
    local ah=sh-top-bot
    local cw=sw/cols
    local ch=ah/rows
    local c=math.floor(x/cw)
    local r=math.floor((y-top)/ch)
    local idx=r*cols+c+1
    if idx>=1 and idx<=#apps then press=idx; return apps[idx] end
    return nil
end
function M.release() press=nil end
function M.slide_in(dir) ox=sw*dir; tx=0 end
return M
