# ── Detecta --gui em qualquer posição dos argumentos ─────────────────────
_ARG_GUI=0
for _arg in "$@"; do
    [ "$_arg" = "--gui" ] && _ARG_GUI=1
done

# Dispatch principal — INSTALL_EDITOR já foi setado pelo loop do topo
case "${1:-}" in
    -u|--uninstall)
        _run_uninstall
        ;;
    -ua|--uninstall-all)
        _run_uninstall
        ;;
    --doctor)
        _TPFX="${PREFIX:-/data/data/com.termux/files/usr}"
        printf "\n\033[1;35m── ElliotOS --doctor ────────────────────────────────────────────\033[0m\n\n"
        _DOCTOR_FAIL=0
        for _bin in lua-net ms luar lpm cxx elliot; do
            if command -v "$_bin" >/dev/null 2>&1; then
                _ok "Binário: $_bin → $(command -v "$_bin")"
            else
                _err "Binário ausente: $_bin"
                _DOCTOR_FAIL=1
            fi
        done
        _SMOKE=$("$_TPFX/bin/lua-net" -e "print('ok')" 2>/dev/null || true)
        if [ "$_SMOKE" = "ok" ]; then
            _ok "Smoke test: lua-net executa corretamente"
        else
            _err "Smoke test falhou — binário pode estar corrompido"
            _DOCTOR_FAIL=1
        fi
        if command -v ldd >/dev/null 2>&1; then
            _MISSING=$(ldd "$_TPFX/bin/lua-net" 2>/dev/null | grep "not found" || true)
            if [ -z "$_MISSING" ]; then
                _ok "Libs dinâmicas: todas encontradas"
            else
                _err "Libs faltando: $_MISSING"
                _DOCTOR_FAIL=1
            fi
        fi
        _LOG="$HOME/.cache/elliot/install.log"
        if [ -f "$_LOG" ]; then
            _ok "Log de instalação: $_LOG"
            printf "\033[0;90m"
            tail -8 "$_LOG" | sed 's/^/    /'
            printf "\033[0m"
        else
            _warn "Log de instalação não encontrado (instalado antes desta versão?)"
        fi
        printf "\n"
        if [ "$_DOCTOR_FAIL" = "1" ]; then
            printf "  \033[1;31m[✗] Problemas encontrados — considere reinstalar: bash luascript\033[0m\n\n"
        else
            printf "  \033[1;32m[✔] Tudo certo. ElliotOS está saudável.\033[0m\n\n"
        fi
        ;;
    --gui|-e|--editor)
        # Ambos já foram parseados pelo loop do topo:
        # INSTALL_EDITOR e INSTALL_GUI refletem todos os args independente da ordem
        if [ "${INSTALL_GUI:-0}" = "1" ]; then
            _install_gui
        else
            install_elliotos
        fi
        ;;
    --update)
        printf "\n\033[1;35m── ElliotOS --update ────────────────────────────────────────────\033[0m\n\n"
        printf "  \033[0;90mRecompila binário, atualiza scripts e binários — pula dependências.\033[0m\n"
        [ "${INSTALL_EDITOR:-0}" = "1" ] && printf "  \033[0;90m+ editor ee será recompilado\033[0m\n"
        [ "${INSTALL_GUI:-0}"    = "1" ] && printf "  \033[0;90m+ GUI será reinstalado\033[0m\n"
        printf "\n"
        if [ "${INSTALL_GUI:-0}" = "1" ]; then
            _install_gui
        else
            install_elliotos
            # Sobrescreve binários GUI se já estiverem instalados
            if [ -f "${PREFIX:-/data/data/com.termux/files/usr}/bin/elliot-gui" ]; then
                _step "🔄" "Atualizando binários GUI (elliot-gui, rungui)..."
                INSTALL_UPDATE=1 _install_gui
            fi
        fi
        ;;
    *)
        if [ "${INSTALL_GUI:-0}" = "1" ]; then
            _install_gui
        else
            install_elliotos
        fi
        ;;
esac
